CREATE OR REPLACE FUNCTION "ngoda_private"."record_registration_auth_creation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE v_attempt text;
BEGIN
    v_attempt := NEW.raw_user_meta_data ->> 'ngoda_registration_attempt';
    IF v_attempt IS NULL OR v_attempt !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
        RETURN NEW;
    END IF;
    INSERT INTO ngoda_private.registration_auth_creation(user_id,attempt_id)
    VALUES(NEW.id,v_attempt::uuid);
    RETURN NEW;
END;
$_$;
ALTER FUNCTION "ngoda_private"."record_registration_auth_creation"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."accrue_daily_interest_for_loan"("p_loan_id" "text", "p_accrual_date" "date") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_loan public.loan%rowtype;

    v_last_accrued_date date;
    v_days_missing integer;

    v_principal numeric := 0;
    v_interest_rate numeric := 0;
    v_daily_rate numeric := 0;
    v_interest numeric := 0;

    v_fiscal_year integer;
    v_period integer;

    v_document_prefix text;
    v_document_number text;

    v_mappings
        public.transaction_gl_mapping[];

    v_components
        public.posting_component[];

    v_financial_transaction_id bigint;

    v_stage text := 'initialization';

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * Lock the loan so two accrual processes cannot process
     * the same loan concurrently.
     */
    v_stage := 'fetch and lock active loan';

    select loan_record.*
    into v_loan
    from public.loan loan_record
    where loan_record.id =
          p_loan_id
      and loan_record.status =
          'active'::public."LoanStatus"
    for update;

    if not found then
        return false;
    end if;

    /*
     * Determine the last date for which interest was accrued.
     */
    v_stage := 'calculate missing accrual days';

    v_last_accrued_date :=
        coalesce(
            v_loan.last_accrued_at::date,
            v_loan.created_at::date
        );

    v_days_missing :=
        p_accrual_date -
        v_last_accrued_date;

    if v_days_missing <= 0 then
        return false;
    end if;

    /*
     * Prevent duplicate accrual for the same loan and date.
     */
    v_stage := 'check existing accrual';

    perform 1
    from public.loan_entry loan_entry_record
    where loan_entry_record.loan_id =
          v_loan.id
      and loan_entry_record.entry_type =
          'interest_accrual'::public."LoanEntryType"
      and loan_entry_record.accrual_date::date =
          p_accrual_date
    limit 1;

    if found then
        /*
         * The entry exists, so ensure last_accrued_at agrees
         * with the existing accrual.
         */
        update public.loan
        set
            last_accrued_at =
                p_accrual_date
        where id =
              v_loan.id;

        return false;
    end if;

    /*
     * Calculate outstanding principal.
     */
    v_stage := 'calculate outstanding principal';

    select coalesce(
        sum(
            coalesce(
                loan_entry_record.debit_principal,
                0
            ) -
            coalesce(
                loan_entry_record.credit_principal,
                0
            )
        ),
        0
    )
    into v_principal
    from public.loan_entry loan_entry_record
    where loan_entry_record.loan_id =
          v_loan.id;

    if v_principal <= 0 then
        return false;
    end if;

    /*
     * Calculate catch-up interest for all missing days.
     */
    v_stage := 'calculate interest';

    v_interest_rate :=
        coalesce(
            v_loan.interest_rate,
            12
        );

    if v_interest_rate <= 0 then
        raise exception
            'INVALID_LOAN_INTEREST_RATE';
    end if;

    v_daily_rate :=
        v_interest_rate /
        100 /
        365;

    v_interest :=
        v_principal *
        v_daily_rate *
        v_days_missing;

    if v_interest <= 0 then
        return false;
    end if;

    /*
     * Fetch fiscal period.
     */
    v_stage := 'fetch fiscal period';

    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_loan.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Fetch GL mappings.
     */
    v_stage := 'fetch GL mappings';

    select array_agg(mapping_record)
    into v_mappings
    from public.fetch_gl_mappings(
        'loan_interest_accrual'::public."TransactionType"
    ) as mapping_record;

    if v_mappings is null
       or cardinality(v_mappings) = 0
    then
        raise exception
            'GL_MAPPINGS_NOT_FOUND';
    end if;

    /*
     * Interest accrual is a balanced principal component:
     *
     * Debit:  accrued loan interest
     * Credit: interest income/payable GL
     *
     * The GL mapping determines the actual account codes.
     */
    v_stage := 'build posting components';

    v_components :=
        array[
            row(
                'principal'::public."ComponentType",
                v_interest,
                v_interest
            )::public.posting_component
        ];

    /*
     * Generate the document number using the configured prefix.
     */
    v_stage := 'fetch document prefix';

    v_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            'loan_interest_accrual'::public."TransactionType"
        );

    if v_document_prefix is null
       or btrim(v_document_prefix) = ''
    then
        raise exception
            'DOCUMENT_PREFIX_NOT_FOUND';
    end if;

    v_stage := 'generate document number';

    v_document_number :=
        public.generate_document_number(
            v_document_prefix,
            v_fiscal_year,
            v_period,
            v_loan.country_code
        );

    /*
     * Insert the loan interest entry.
     */
    v_stage := 'create loan interest entry';

    insert into public.loan_entry (
        loan_id,
        fiscal_year,
        period,
        document_number,
        entry_type,
        debit_principal,
        credit_principal,
        debit_interest,
        credit_interest,
        currency_code,
        accrual_date,
        country_code
    )
    values (
        v_loan.id,
        v_fiscal_year,
        v_period,
        v_document_number,
        'interest_accrual'::public."LoanEntryType",
        0,
        0,
        v_interest,
        0,
        v_loan.currency_code,
        p_accrual_date,
        v_loan.country_code
    );

    /*
     * Create the financial transaction header.
     */
    v_stage := 'create financial transaction';

    insert into public.financial_transaction (
        document_number,
        reference,
        fiscal_year,
        period,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        country_code
    )
    values (
        v_document_number,
        v_document_number,
        v_fiscal_year,
        v_period,
        'loan_interest_accrual'::public."TransactionType",
        format(
            'Loan interest accrual for %s (%s days)',
            v_loan.id,
            v_days_missing
        ),
        'admin',
        v_interest,
        v_loan.currency_code,
        v_loan.country_code
    )
    returning id
    into v_financial_transaction_id;

    /*
     * Post the GL entries.
     */
    v_stage := 'post financial entries';

    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_document_number,

        p_country_code =>
            v_loan.country_code,

        p_transaction_id =>
            v_financial_transaction_id,

        p_transaction_type =>
            'loan_interest_accrual'::public."TransactionType",

        p_created_by =>
            'admin',

        p_components =>
            v_components,

        p_mappings =>
            v_mappings,

        p_currency_code =>
            v_loan.currency_code,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_reference =>
            v_document_number,

        p_deposit_type =>
            null
    );

    /*
     * Update the loan balance snapshot using the existing
     * positional function signature:
     *
     * update_loan_snapshot(
     *   loan_id,
     *   user_id,
     *   country_code,
     *   debit_principal,
     *   credit_principal,
     *   debit_interest,
     *   credit_interest,
     *   fiscal_year,
     *   period
     * )
     */
    v_stage := 'update loan snapshot';

    perform public.update_loan_snapshot(
        v_loan.id,
        v_loan.user_id,
        v_loan.country_code,
        0::numeric,
        0::numeric,
        v_interest,
        0::numeric,
        v_fiscal_year,
        v_period
    );

    /*
     * Mark the loan as accrued through the processing date.
     */
    v_stage := 'update last accrued date';

    update public.loan
    set
        last_accrued_at =
            p_accrual_date
    where id =
          v_loan.id;

    if not found then
        raise exception
            'LOAN_UPDATE_FAILED';
    end if;

    return true;

exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;

        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'LOAN_INTEREST_ACCRUAL_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                coalesce(
                    nullif(
                        concat_ws(
                            E'\n',
                            nullif(
                                v_error_detail,
                                ''
                            ),
                            nullif(
                                v_error_context,
                                ''
                            )
                        ),
                        ''
                    ),
                    'No additional PostgreSQL context'
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    'Check the loan interest accrual stage reported in the error'
                );
end;
$$;
ALTER FUNCTION "public"."accrue_daily_interest_for_loan"("p_loan_id" "text", "p_accrual_date" "date") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."acknowledge_my_gamification_notification"("p_notification_id" "text", "p_mark_seen" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user_id text;
    v_notification_id text;
    v_notification public.gamification_notification%rowtype;
begin
    v_user_id := auth.uid()::text;

    if v_user_id is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    v_notification_id :=
        nullif(btrim(p_notification_id), '');

    if v_notification_id is null then
        raise exception 'GAMIFICATION_NOTIFICATION_ID_REQUIRED';
    end if;

    if p_mark_seen is null then
        raise exception 'INVALID_GAMIFICATION_NOTIFICATION_SEEN_VALUE';
    end if;

    update public.gamification_notification
    set
        displayed_at = coalesce(displayed_at, now()),
        seen_at = case
            when p_mark_seen then coalesce(seen_at, now())
            else seen_at
        end
    where id::text = v_notification_id
      and user_id = v_user_id
    returning * into v_notification;

    if not found then
        raise exception 'GAMIFICATION_NOTIFICATION_NOT_FOUND';
    end if;

    return jsonb_build_object(
        'success', true,
        'notification_id', v_notification.id,
        'displayed_at', v_notification.displayed_at,
        'seen_at', v_notification.seen_at
    );
end;
$$;
ALTER FUNCTION "public"."acknowledge_my_gamification_notification"("p_notification_id" "text", "p_mark_seen" boolean) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."apply_gl_snapshot_update"("p_gl_account_code" "text", "p_debit" numeric, "p_credit" numeric, "p_currency_code" "text", "p_country_code" "text", "p_fiscal_year" integer, "p_period" integer) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
declare
    v_opening numeric := 0;
    v_delta numeric;
begin
    if coalesce(p_debit, 0) = 0
       and coalesce(p_credit, 0) = 0
    then
        return;
    end if;

    v_delta :=
        coalesce(p_debit, 0) -
        coalesce(p_credit, 0);

    /*
     * First: fetch the exact current snapshot.
     * This matches Prisma findUnique().
     */
    select s.closing_balance
    into v_opening
    from public.gl_balance_snapshot s
    where s.country_code = p_country_code
      and s.gl_account_code = p_gl_account_code
      and s.currency_code = p_currency_code
      and s.fiscal_year = p_fiscal_year
      and s.period = p_period;

    /*
     * Second: if the exact snapshot does not exist, fetch the
     * latest earlier period in the same fiscal year.
     */
    if not found then
        select s.closing_balance
        into v_opening
        from public.gl_balance_snapshot s
        where s.country_code = p_country_code
          and s.gl_account_code = p_gl_account_code
          and s.currency_code = p_currency_code
          and s.fiscal_year = p_fiscal_year
          and s.period < p_period
        order by s.period desc
        limit 1;
    end if;

    /*
     * Third: if no snapshot exists in the current fiscal year,
     * fetch the latest snapshot from an earlier fiscal year.
     */
    if not found then
        select s.closing_balance
        into v_opening
        from public.gl_balance_snapshot s
        where s.country_code = p_country_code
          and s.gl_account_code = p_gl_account_code
          and s.currency_code = p_currency_code
          and s.fiscal_year < p_fiscal_year
        order by
            s.fiscal_year desc,
            s.period desc
        limit 1;
    end if;

    v_opening := coalesce(v_opening, 0);

    insert into public.gl_balance_snapshot as current_snapshot (
        country_code,
        gl_account_code,
        currency_code,
        fiscal_year,
        period,
        opening_balance,
        debit,
        credit,
        closing_balance,
        created_at,
        updated_at
    )
    values (
        p_country_code,
        p_gl_account_code,
        p_currency_code,
        p_fiscal_year,
        p_period,
        v_opening,
        coalesce(p_debit, 0),
        coalesce(p_credit, 0),
        v_opening + v_delta,
        now(),
        now()
    )
    on conflict (
        country_code,
        gl_account_code,
        currency_code,
        fiscal_year,
        period
    )
    do update
    set
        debit =
            current_snapshot.debit +
            excluded.debit,

        credit =
            current_snapshot.credit +
            excluded.credit,

        closing_balance =
            current_snapshot.closing_balance +
            excluded.debit -
            excluded.credit,

        updated_at = now();
end;
$$;
ALTER FUNCTION "public"."apply_gl_snapshot_update"("p_gl_account_code" "text", "p_debit" numeric, "p_credit" numeric, "p_currency_code" "text", "p_country_code" "text", "p_fiscal_year" integer, "p_period" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."apply_wallet_snapshot_update"("p_user_id" "text", "p_country_code" "text", "p_currency_code" "text", "p_wallet_owner" "public"."WalletOwnerType", "p_debit" numeric, "p_credit" numeric, "p_fiscal_year" integer, "p_period" integer, "p_blockchain_code" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
declare
    v_opening numeric := 0;
    v_delta numeric;

    v_currency_code text;
    v_blockchain_code text;

    v_debit numeric;
    v_credit numeric;

begin
    /*
     * ==========================================================
     * NORMALIZE CURRENCY AND BLOCKCHAIN
     * ==========================================================
     */
    v_currency_code :=
        nullif(
            lower(btrim(p_currency_code)),
            ''
        );

    v_blockchain_code :=
        nullif(
            lower(btrim(p_blockchain_code)),
            ''
        );

    /*
     * ==========================================================
     * VALIDATE REQUIRED PARAMETERS
     * ==========================================================
     */
    if nullif(btrim(p_user_id), '') is null then
        raise exception
            'WALLET_SNAPSHOT_USER_REQUIRED';
    end if;

    if nullif(btrim(p_country_code), '') is null then
        raise exception
            'WALLET_SNAPSHOT_COUNTRY_REQUIRED';
    end if;

    if v_currency_code is null then
        raise exception
            'WALLET_SNAPSHOT_CURRENCY_REQUIRED';
    end if;

    if p_wallet_owner is null then
        raise exception
            'WALLET_SNAPSHOT_OWNER_REQUIRED';
    end if;

    if p_fiscal_year is null
       or p_period is null
       or p_period < 1
       or p_period > 12
    then
        raise exception
            'INVALID_WALLET_SNAPSHOT_PERIOD';
    end if;

    /*
     * ==========================================================
     * VALIDATE BLOCKCHAIN REQUIREMENTS
     * ==========================================================
     *
     * GOLD:
     *   blockchain_code is mandatory.
     *
     * FIAT:
     *   blockchain_code must be NULL.
     */
    if v_currency_code = 'gold' then

        if v_blockchain_code is null then
            raise exception
                'BLOCKCHAIN_CODE_REQUIRED_FOR_GOLD';
        end if;

    elsif v_blockchain_code is not null then

        raise exception
            'BLOCKCHAIN_CODE_NOT_ALLOWED_FOR_FIAT';

    end if;

    /*
     * ==========================================================
     * NORMALIZE DEBIT AND CREDIT
     * ==========================================================
     */
    v_debit :=
        coalesce(p_debit, 0);

    v_credit :=
        coalesce(p_credit, 0);

    if v_debit < 0 or v_credit < 0 then
        raise exception
            'NEGATIVE_WALLET_SNAPSHOT_AMOUNT_NOT_ALLOWED';
    end if;

    /*
     * ==========================================================
     * SKIP ZERO-VALUE UPDATES
     * ==========================================================
     */
    if v_debit = 0 and v_credit = 0 then
        return;
    end if;

    v_delta :=
        v_credit - v_debit;

    /*
     * ==========================================================
     * FIRST: EXACT CURRENT SNAPSHOT
     * ==========================================================
     */
    select
        s.closing_balance
    into
        v_opening
    from public.wallet_balance_snapshot s
    where s.user_id = p_user_id
      and s.country_code = p_country_code
      and s.currency_code = v_currency_code
      and s.wallet_owner = p_wallet_owner
      and s.blockchain_code is not distinct from
          v_blockchain_code
      and s.fiscal_year = p_fiscal_year
      and s.period = p_period;

    /*
     * ==========================================================
     * SECOND: PREVIOUS PERIOD IN SAME FISCAL YEAR
     * ==========================================================
     */
    if not found then

        select
            s.closing_balance
        into
            v_opening
        from public.wallet_balance_snapshot s
        where s.user_id = p_user_id
          and s.country_code = p_country_code
          and s.currency_code = v_currency_code
          and s.wallet_owner = p_wallet_owner
          and s.blockchain_code is not distinct from
              v_blockchain_code
          and s.fiscal_year = p_fiscal_year
          and s.period < p_period
        order by
            s.period desc
        limit 1;

    end if;

    /*
     * ==========================================================
     * THIRD: LATEST PREVIOUS FISCAL YEAR
     * ==========================================================
     */
    if not found then

        select
            s.closing_balance
        into
            v_opening
        from public.wallet_balance_snapshot s
        where s.user_id = p_user_id
          and s.country_code = p_country_code
          and s.currency_code = v_currency_code
          and s.wallet_owner = p_wallet_owner
          and s.blockchain_code is not distinct from
              v_blockchain_code
          and s.fiscal_year < p_fiscal_year
        order by
            s.fiscal_year desc,
            s.period desc
        limit 1;

    end if;

    v_opening :=
        coalesce(v_opening, 0);

    /*
     * ==========================================================
     * FIAT SNAPSHOT
     * ==========================================================
     *
     * Fiat balances have no blockchain_code.
     */
    if v_blockchain_code is null then

        insert into public.wallet_balance_snapshot
            as current_snapshot (
                user_id,
                country_code,
                currency_code,
                wallet_owner,
                blockchain_code,
                fiscal_year,
                period,
                opening_balance,
                debit,
                credit,
                closing_balance,
                created_at,
                updated_at
            )
        values (
            p_user_id,
            p_country_code,
            v_currency_code,
            p_wallet_owner,
            null,
            p_fiscal_year,
            p_period,
            v_opening,
            v_debit,
            v_credit,
            v_opening + v_delta,
            now(),
            now()
        )
        on conflict (
            user_id,
            currency_code,
            wallet_owner,
            fiscal_year,
            period
        )
        where blockchain_code is null

        do update
        set
            debit =
                current_snapshot.debit +
                excluded.debit,

            credit =
                current_snapshot.credit +
                excluded.credit,

            closing_balance =
                current_snapshot.closing_balance +
                excluded.credit -
                excluded.debit,

            updated_at =
                now();

    /*
     * ==========================================================
     * BLOCKCHAIN-SPECIFIC GOLD SNAPSHOT
     * ==========================================================
     */
    else

        insert into public.wallet_balance_snapshot
            as current_snapshot (
                user_id,
                country_code,
                currency_code,
                wallet_owner,
                blockchain_code,
                fiscal_year,
                period,
                opening_balance,
                debit,
                credit,
                closing_balance,
                created_at,
                updated_at
            )
        values (
            p_user_id,
            p_country_code,
            v_currency_code,
            p_wallet_owner,
            v_blockchain_code,
            p_fiscal_year,
            p_period,
            v_opening,
            v_debit,
            v_credit,
            v_opening + v_delta,
            now(),
            now()
        )
        on conflict (
            user_id,
            currency_code,
            wallet_owner,
            blockchain_code,
            fiscal_year,
            period
        )
        where blockchain_code is not null

        do update
        set
            debit =
                current_snapshot.debit +
                excluded.debit,

            credit =
                current_snapshot.credit +
                excluded.credit,

            closing_balance =
                current_snapshot.closing_balance +
                excluded.credit -
                excluded.debit,

            updated_at =
                now();

    end if;

end;
$$;
ALTER FUNCTION "public"."apply_wallet_snapshot_update"("p_user_id" "text", "p_country_code" "text", "p_currency_code" "text", "p_wallet_owner" "public"."WalletOwnerType", "p_debit" numeric, "p_credit" numeric, "p_fiscal_year" integer, "p_period" integer, "p_blockchain_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."approve_my_credit_agent"("p_merchant_identifier" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_approver public.users%rowtype;
    v_merchant public.users%rowtype;

    v_identifier text;

    v_currency_count integer;

    v_accounts jsonb;
    v_currencies jsonb;

    v_stage text := 'initialization';
    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * Authenticate treasury.
     */
    v_stage := 'authorize treasury user';

    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if not public.has_role(
        array[
            'treasury'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Validate merchant identifier.
     */
    v_stage := 'validate input';

    v_identifier :=
        nullif(
            btrim(p_merchant_identifier),
            ''
        );

    if v_identifier is null then
        raise exception
            'MERCHANT_IDENTIFIER_REQUIRED';
    end if;

    /*
     * Fetch treasury approver.
     */
    v_stage := 'fetch treasury user';

    v_approver :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_approver.id is null then
        raise exception
            'TREASURY_USER_NOT_FOUND';
    end if;

    if v_approver.country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Only an active merchant can become a credit agent.
     */
    v_stage := 'fetch merchant';

    select user_record.*
    into v_merchant
    from public.users user_record
    join public.user_role role_record
      on role_record.id =
         user_record.role_id
    where user_record.country_code =
              v_approver.country_code

      and user_record.status =
              'active'::public."UserStatus"

      and lower(
          role_record.name::text
      ) =
              'merchant'

      and (
          lower(
              user_record.email
          ) =
              lower(v_identifier)

          or user_record.phone =
              v_identifier
      )
    limit 1;

    if not found then
        raise exception
            'ACTIVE_MERCHANT_NOT_FOUND';
    end if;

    /*
     * Ensure the country has active fiat currencies.
     */
    v_stage := 'fetch active fiat currencies';

    select count(*)
    into v_currency_count
    from public.country_currencies
        currency_record
    where currency_record.country_code =
              v_approver.country_code

      and currency_record.is_active =
              true

      and lower(
          currency_record.currency_code
      ) <>
              'gold';

    if v_currency_count = 0 then
        raise exception
            'ACTIVE_FIAT_CURRENCIES_NOT_FOUND';
    end if;

    /*
     * Approve the merchant for every active fiat currency.
     *
     * Existing balances are never reset.
     */
    v_stage := 'create credit agent accounts';

    insert into public.credit_agent_account (
        merchant_id,
        country_code,
        currency_code,
        receivable_balance,
        cash_holding_balance,
        is_active,
        approved_by,
        created_at,
        updated_at
    )
    select
        v_merchant.id,
        v_approver.country_code,
        lower(
            currency_record.currency_code
        ),
        0,
        0,
        true,
        v_approver.id,
        now(),
        now()
    from public.country_currencies
        currency_record
    where currency_record.country_code =
              v_approver.country_code

      and currency_record.is_active =
              true

      and lower(
          currency_record.currency_code
      ) <>
              'gold'

    on conflict (
        merchant_id,
        country_code,
        currency_code
    )
    do update
    set
        is_active =
            true,

        approved_by =
            excluded.approved_by,

        updated_at =
            now();

    /*
     * Return all active credit-agent accounts.
     */
    v_stage := 'fetch approved accounts';

    select
        coalesce(
            jsonb_agg(
                jsonb_build_object(
                    'credit_agent_account_id',
                    account_record.id,

                    'currency_code',
                    account_record.currency_code,

                    'receivable_balance',
                    account_record.receivable_balance::text,

                    'cash_holding_balance',
                    account_record.cash_holding_balance::text,

                    'is_active',
                    account_record.is_active
                )
                order by
                    account_record.currency_code
            ),
            '[]'::jsonb
        )
    into v_accounts
    from public.credit_agent_account
        account_record
    where account_record.merchant_id =
              v_merchant.id

      and account_record.country_code =
              v_approver.country_code

      and account_record.is_active =
              true;

    select
        coalesce(
            jsonb_agg(
                account_record.currency_code
                order by
                    account_record.currency_code
            ),
            '[]'::jsonb
        )
    into v_currencies
    from public.credit_agent_account
        account_record
    where account_record.merchant_id =
              v_merchant.id

      and account_record.country_code =
              v_approver.country_code

      and account_record.is_active =
              true;

    return jsonb_build_object(
        'success',
        true,

        'is_credit_agent',
        true,

        'merchant_id',
        v_merchant.id,

        'merchant_email',
        v_merchant.email,

        'merchant_phone',
        v_merchant.phone,

        'country_code',
        v_approver.country_code,

        'credit_agent_currencies',
        v_currencies,

        'credit_agent_accounts',
        v_accounts,

        'approved_by',
        v_approver.id
    );

exception
    when others then
        get stacked diagnostics
            v_error_state = returned_sqlstate,
            v_error_message = message_text,
            v_error_detail = pg_exception_detail,
            v_error_hint = pg_exception_hint,
            v_error_context = pg_exception_context;

        raise exception using
            errcode = v_error_state,

            message = format(
                'CREDIT_AGENT_APPROVAL_FAILED at [%s]: %s',
                v_stage,
                v_error_message
            ),

            detail = concat_ws(
                E'\n',
                nullif(v_error_detail, ''),
                nullif(v_error_context, '')
            ),

            hint = coalesce(
                nullif(v_error_hint, ''),
                'Check the Credit Agent Approval stage reported in the error'
            );
end;
$$;
ALTER FUNCTION "public"."approve_my_credit_agent"("p_merchant_identifier" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."award_loyalty_points"("p_idempotency_key" "text", "p_event_type" "public"."LoyaltyEventType", "p_user_id" "text", "p_source_reference" "text", "p_source_transaction_id" "text" DEFAULT NULL::"text", "p_transaction_type" "public"."TransactionType" DEFAULT NULL::"public"."TransactionType", "p_amount" numeric DEFAULT NULL::numeric, "p_amount_usd" numeric DEFAULT NULL::numeric, "p_country_code" "text" DEFAULT NULL::"text", "p_currency_code" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_idempotency_key text;
    v_user_id text;
    v_source_reference text;
    v_country_code text;
    v_currency_code text;
    v_metadata jsonb;

    v_event public.gamification_event%rowtype;
    v_rule public.loyalty_rule%rowtype;
    v_band public.loyalty_rule_band%rowtype;
    v_account public.loyalty_account%rowtype;
    v_program public.loyalty_program_config%rowtype;
    v_previous_level text;
    v_new_level text;

    v_existing_ledger public.loyalty_ledger%rowtype;
    v_ledger public.loyalty_ledger%rowtype;

    v_raw_points numeric := 0;
    v_calculated_points bigint := 0;
    v_awarded_points bigint := 0;

    v_event_time timestamptz;
    v_daily_start date;
    v_monthly_start date;

    v_program_daily_used bigint := 0;
    v_program_monthly_used bigint := 0;
    v_rule_daily_used bigint := 0;
    v_rule_monthly_used bigint := 0;

    v_program_daily_remaining bigint;
    v_program_monthly_remaining bigint;
    v_rule_daily_remaining bigint;
    v_rule_monthly_remaining bigint;

    v_rule_snapshot jsonb;
    v_result jsonb;
begin
    if coalesce(auth.role(), '') <> 'service_role' then
        raise exception using
            errcode = '42501',
            message = 'SERVICE_ROLE_REQUIRED';
    end if;

    v_idempotency_key := nullif(btrim(p_idempotency_key), '');
    v_user_id := nullif(btrim(p_user_id), '');
    v_source_reference := nullif(btrim(p_source_reference), '');
    v_country_code := lower(nullif(btrim(p_country_code), ''));
    v_currency_code := lower(nullif(btrim(p_currency_code), ''));
    v_metadata := coalesce(p_metadata, '{}'::jsonb);

    if v_idempotency_key is null then
        raise exception 'GAMIFICATION_IDEMPOTENCY_KEY_REQUIRED';
    end if;

    if p_event_type is null or p_event_type = 'reversal' then
        raise exception 'INVALID_GAMIFICATION_EARNING_EVENT_TYPE';
    end if;

    if v_user_id is null then
        raise exception 'GAMIFICATION_USER_ID_REQUIRED';
    end if;

    if v_source_reference is null then
        raise exception 'GAMIFICATION_SOURCE_REFERENCE_REQUIRED';
    end if;

    if p_amount is not null and p_amount < 0 then
        raise exception 'INVALID_GAMIFICATION_AMOUNT';
    end if;

    if p_amount_usd is not null and p_amount_usd < 0 then
        raise exception 'INVALID_GAMIFICATION_USD_AMOUNT';
    end if;

    if jsonb_typeof(v_metadata) <> 'object' then
        raise exception 'INVALID_GAMIFICATION_METADATA';
    end if;

    perform 1
    from public.users user_record
    where user_record.id = v_user_id;

    if not found then
        raise exception 'GAMIFICATION_USER_NOT_FOUND';
    end if;

    /*
     * Insert once. The idempotency key is the primary retry contract.
     * A separate user/event/reference key protects callers that accidentally
     * generate a different idempotency key for the same business event.
     */
    insert into public.gamification_event (
        idempotency_key,
        event_type,
        status,
        user_id,
        source_reference,
        source_transaction_id,
        transaction_type,
        amount,
        amount_usd,
        country_code,
        currency_code,
        metadata,
        attempt_count,
        claimed_at,
        lease_expires_at
    )
    values (
        v_idempotency_key,
        p_event_type,
        'processing'::public."GamificationEventStatus",
        v_user_id,
        v_source_reference,
        nullif(btrim(p_source_transaction_id), ''),
        p_transaction_type,
        p_amount,
        p_amount_usd,
        v_country_code,
        v_currency_code,
        v_metadata,
        1,
        now(),
        now() + interval '5 minutes'
    )
    on conflict do nothing
    returning *
    into v_event;

    if not found then
        select event_record.*
        into v_event
        from public.gamification_event event_record
        where event_record.idempotency_key = v_idempotency_key
           or (
               event_record.user_id = v_user_id
               and event_record.event_type = p_event_type
               and event_record.source_reference = v_source_reference
           )
        order by
            case
                when event_record.idempotency_key = v_idempotency_key
                    then 0
                else 1
            end,
            event_record.created_at,
            event_record.id
        limit 1
        for update;

        if not found then
            raise exception 'GAMIFICATION_EVENT_CONFLICT_NOT_FOUND';
        end if;

        if v_event.user_id <> v_user_id
           or v_event.event_type <> p_event_type
           or v_event.source_reference <> v_source_reference
        then
            raise exception 'GAMIFICATION_IDEMPOTENCY_KEY_PAYLOAD_MISMATCH';
        end if;

        select ledger_record.*
        into v_existing_ledger
        from public.loyalty_ledger ledger_record
        where ledger_record.event_id = v_event.id
          and ledger_record.ledger_type = 'earn'
        limit 1;

        if found then
            return jsonb_build_object(
                'success', true,
                'idempotent_replay', true,
                'event_id', v_event.id,
                'event_status', v_event.status,
                'user_id', v_event.user_id,
                'event_type', v_event.event_type,
                'source_reference', v_event.source_reference,
                'points_awarded', v_existing_ledger.points_delta,
                'available_points',
                    v_existing_ledger.available_balance_after,
                'tier_points', v_existing_ledger.tier_balance_after,
                'level_code', (
                    select account_record.level_code
                    from public.loyalty_account account_record
                    where account_record.id =
                          v_existing_ledger.loyalty_account_id
                ),
                'ledger_id', v_existing_ledger.id
            );
        end if;

        if v_event.status in ('ignored', 'failed', 'reversed') then
            return jsonb_build_object(
                'success', v_event.status <> 'failed',
                'idempotent_replay', true,
                'event_id', v_event.id,
                'event_status', v_event.status,
                'user_id', v_event.user_id,
                'event_type', v_event.event_type,
                'source_reference', v_event.source_reference,
                'points_awarded', 0,
                'reason', v_event.error_message
            );
        end if;

        /* A prior call cannot still be processing while this row is locked. */
        raise exception 'GAMIFICATION_EVENT_ALREADY_PROCESSING';
    end if;

    v_event_time := v_event.created_at;
    v_daily_start := (v_event_time at time zone 'UTC')::date;
    v_monthly_start :=
        date_trunc('month', v_event_time at time zone 'UTC')::date;

    /* Country-specific configuration overrides the global configuration. */
    select config_record.*
    into v_program
    from public.loyalty_program_config config_record
    where config_record.is_active = true
      and (
          config_record.country_code = v_country_code
          or config_record.country_code is null
      )
    order by
        case
            when config_record.country_code = v_country_code then 0
            else 1
        end,
        config_record.updated_at desc,
        config_record.id
    limit 1;

    if not found then
        raise exception 'ACTIVE_LOYALTY_PROGRAM_CONFIGURATION_NOT_FOUND';
    end if;

    /* Resolve one rule deterministically from most specific to least. */
    select rule_record.*
    into v_rule
    from public.loyalty_rule rule_record
    where rule_record.event_type = p_event_type
      and rule_record.is_active = true
      and (rule_record.country_code is null
           or rule_record.country_code = v_country_code)
      and (rule_record.currency_code is null
           or rule_record.currency_code = v_currency_code)
      and (rule_record.valid_from is null
           or rule_record.valid_from <= v_event_time)
      and (rule_record.valid_until is null
           or rule_record.valid_until > v_event_time)
      and (rule_record.min_amount_usd is null
           or coalesce(p_amount_usd, 0) >= rule_record.min_amount_usd)
      and (rule_record.max_amount_usd is null
           or coalesce(p_amount_usd, 0) <= rule_record.max_amount_usd)
    order by
        case when rule_record.country_code is not null then 0 else 1 end,
        case when rule_record.currency_code is not null then 0 else 1 end,
        rule_record.priority,
        rule_record.valid_from desc nulls last,
        rule_record.id
    limit 1;

    if not found then
        update public.gamification_event
        set
            status = 'ignored'::public."GamificationEventStatus",
            processed_at = now(),
            lease_expires_at = null,
            error_message = 'NO_ACTIVE_LOYALTY_RULE'
        where id = v_event.id
        returning * into v_event;

        return jsonb_build_object(
            'success', true,
            'idempotent_replay', false,
            'event_id', v_event.id,
            'event_status', v_event.status,
            'user_id', v_event.user_id,
            'event_type', v_event.event_type,
            'source_reference', v_event.source_reference,
            'points_awarded', 0,
            'reason', v_event.error_message
        );
    end if;

    /*
     * Serialize awards for this customer before evaluating once-per-user
     * rules or cap usage. This closes the race between different events for
     * the same user while still allowing different users to process in
     * parallel.
     */
    perform pg_advisory_xact_lock(
        hashtext('loyalty-award:' || v_user_id)
    );

    if coalesce((v_rule.condition_config ->> 'once_per_user')::boolean, false)
       and exists (
           select 1
           from public.loyalty_ledger ledger_record
           where ledger_record.user_id = v_user_id
             and ledger_record.rule_id = v_rule.id
             and ledger_record.ledger_type = 'earn'
       )
    then
        update public.gamification_event
        set
            status = 'ignored'::public."GamificationEventStatus",
            processed_at = now(),
            lease_expires_at = null,
            error_message = 'LOYALTY_RULE_ALREADY_AWARDED'
        where id = v_event.id
        returning * into v_event;

        return jsonb_build_object(
            'success', true,
            'idempotent_replay', false,
            'event_id', v_event.id,
            'event_status', v_event.status,
            'user_id', v_event.user_id,
            'event_type', v_event.event_type,
            'source_reference', v_event.source_reference,
            'rule_code', v_rule.rule_code,
            'points_awarded', 0,
            'reason', v_event.error_message
        );
    end if;

    if v_rule.calculation_type in ('amount_based', 'fixed_plus_amount')
       and p_amount_usd is null
    then
        raise exception 'GAMIFICATION_USD_AMOUNT_REQUIRED_FOR_RULE_%',
            upper(v_rule.rule_code);
    end if;

    if v_rule.calculation_type = 'fixed' then
        v_raw_points := v_rule.fixed_points;

    elsif v_rule.calculation_type = 'amount_based' then
        v_raw_points := p_amount_usd * v_rule.points_per_usd;

    elsif v_rule.calculation_type = 'fixed_plus_amount' then
        v_raw_points :=
            v_rule.fixed_points +
            (p_amount_usd * v_rule.points_per_usd);

    elsif v_rule.calculation_type = 'amount_band' then
        if p_amount_usd is null then
            raise exception 'GAMIFICATION_USD_AMOUNT_REQUIRED_FOR_RULE_%',
                upper(v_rule.rule_code);
        end if;

        select band_record.*
        into v_band
        from public.loyalty_rule_band band_record
        where band_record.rule_id = v_rule.id
          and p_amount_usd >= band_record.min_amount_usd
          and (band_record.max_amount_usd is null
               or p_amount_usd <= band_record.max_amount_usd)
        order by
            band_record.min_amount_usd desc,
            band_record.sort_order,
            band_record.id
        limit 1;

        if not found then
            update public.gamification_event
            set
                status = 'ignored'::public."GamificationEventStatus",
                processed_at = now(),
                lease_expires_at = null,
                error_message = 'NO_MATCHING_LOYALTY_RULE_BAND'
            where id = v_event.id
            returning * into v_event;

            return jsonb_build_object(
                'success', true,
                'idempotent_replay', false,
                'event_id', v_event.id,
                'event_status', v_event.status,
                'user_id', v_event.user_id,
                'event_type', v_event.event_type,
                'source_reference', v_event.source_reference,
                'rule_code', v_rule.rule_code,
                'points_awarded', 0,
                'reason', v_event.error_message
            );
        end if;

        v_raw_points :=
            v_band.fixed_points +
            (p_amount_usd * v_band.points_per_usd);
    else
        raise exception 'UNSUPPORTED_LOYALTY_CALCULATION_TYPE';
    end if;

    v_raw_points := v_raw_points * v_rule.multiplier;
    v_calculated_points := floor(v_raw_points)::bigint;

    if v_rule.min_points_per_event is not null then
        v_calculated_points := greatest(
            v_calculated_points,
            v_rule.min_points_per_event
        );
    end if;

    if v_rule.max_points_per_event is not null then
        v_calculated_points := least(
            v_calculated_points,
            v_rule.max_points_per_event
        );
    end if;

    if v_calculated_points <= 0 then
        update public.gamification_event
        set
            status = 'ignored'::public."GamificationEventStatus",
            processed_at = now(),
            lease_expires_at = null,
            error_message = 'CALCULATED_LOYALTY_POINTS_ZERO'
        where id = v_event.id
        returning * into v_event;

        return jsonb_build_object(
            'success', true,
            'idempotent_replay', false,
            'event_id', v_event.id,
            'event_status', v_event.status,
            'user_id', v_event.user_id,
            'event_type', v_event.event_type,
            'source_reference', v_event.source_reference,
            'rule_code', v_rule.rule_code,
            'calculated_points', v_calculated_points,
            'points_awarded', 0,
            'reason', v_event.error_message
        );
    end if;

    /*
     * Lock one account per user before cap buckets. This produces a stable
     * lock order and serializes simultaneous awards for the same customer.
     */
    insert into public.loyalty_account (user_id)
    values (v_user_id)
    on conflict (user_id) do nothing;

    select account_record.*
    into v_account
    from public.loyalty_account account_record
    where account_record.user_id = v_user_id
    for update;

    if not v_account.is_active then
        raise exception 'LOYALTY_ACCOUNT_NOT_ACTIVE';
    end if;

    v_previous_level := v_account.level_code;

    /* Create and lock the global daily cap bucket. */
    insert into public.loyalty_cap_usage (
        user_id,
        rule_id,
        period_type,
        period_start,
        points_awarded
    )
    values (
        v_user_id,
        null,
        'daily'::public."LoyaltyCapPeriodType",
        v_daily_start,
        0
    )
    on conflict (user_id, period_type, period_start)
    where rule_id is null
    do nothing;

    select usage_record.points_awarded
    into v_program_daily_used
    from public.loyalty_cap_usage usage_record
    where usage_record.user_id = v_user_id
      and usage_record.rule_id is null
      and usage_record.period_type = 'daily'
      and usage_record.period_start = v_daily_start
    for update;

    /* Create and lock the global monthly cap bucket. */
    insert into public.loyalty_cap_usage (
        user_id,
        rule_id,
        period_type,
        period_start,
        points_awarded
    )
    values (
        v_user_id,
        null,
        'monthly'::public."LoyaltyCapPeriodType",
        v_monthly_start,
        0
    )
    on conflict (user_id, period_type, period_start)
    where rule_id is null
    do nothing;

    select usage_record.points_awarded
    into v_program_monthly_used
    from public.loyalty_cap_usage usage_record
    where usage_record.user_id = v_user_id
      and usage_record.rule_id is null
      and usage_record.period_type = 'monthly'
      and usage_record.period_start = v_monthly_start
    for update;

    v_program_daily_remaining := greatest(
        v_program.daily_points_cap - v_program_daily_used,
        0
    );

    v_program_monthly_remaining := greatest(
        v_program.monthly_points_cap - v_program_monthly_used,
        0
    );

    v_awarded_points := least(
        v_calculated_points,
        v_program_daily_remaining,
        v_program_monthly_remaining
    );

    /* Rule cap buckets are only created when that rule defines a cap. */
    if v_rule.daily_cap_points is not null then
        insert into public.loyalty_cap_usage (
            user_id,
            rule_id,
            period_type,
            period_start,
            points_awarded
        )
        values (
            v_user_id,
            v_rule.id,
            'daily'::public."LoyaltyCapPeriodType",
            v_daily_start,
            0
        )
        on conflict (user_id, rule_id, period_type, period_start)
        where rule_id is not null
        do nothing;

        select usage_record.points_awarded
        into v_rule_daily_used
        from public.loyalty_cap_usage usage_record
        where usage_record.user_id = v_user_id
          and usage_record.rule_id = v_rule.id
          and usage_record.period_type = 'daily'
          and usage_record.period_start = v_daily_start
        for update;

        v_rule_daily_remaining := greatest(
            v_rule.daily_cap_points - v_rule_daily_used,
            0
        );

        v_awarded_points := least(
            v_awarded_points,
            v_rule_daily_remaining
        );
    end if;

    if v_rule.monthly_cap_points is not null then
        insert into public.loyalty_cap_usage (
            user_id,
            rule_id,
            period_type,
            period_start,
            points_awarded
        )
        values (
            v_user_id,
            v_rule.id,
            'monthly'::public."LoyaltyCapPeriodType",
            v_monthly_start,
            0
        )
        on conflict (user_id, rule_id, period_type, period_start)
        where rule_id is not null
        do nothing;

        select usage_record.points_awarded
        into v_rule_monthly_used
        from public.loyalty_cap_usage usage_record
        where usage_record.user_id = v_user_id
          and usage_record.rule_id = v_rule.id
          and usage_record.period_type = 'monthly'
          and usage_record.period_start = v_monthly_start
        for update;

        v_rule_monthly_remaining := greatest(
            v_rule.monthly_cap_points - v_rule_monthly_used,
            0
        );

        v_awarded_points := least(
            v_awarded_points,
            v_rule_monthly_remaining
        );
    end if;

    if v_awarded_points <= 0 then
        update public.gamification_event
        set
            status = 'ignored'::public."GamificationEventStatus",
            processed_at = now(),
            lease_expires_at = null,
            error_message = 'LOYALTY_POINTS_CAP_REACHED',
            metadata = metadata || jsonb_build_object(
                'calculated_points', v_calculated_points,
                'points_awarded', 0
            )
        where id = v_event.id
        returning * into v_event;

        return jsonb_build_object(
            'success', true,
            'idempotent_replay', false,
            'event_id', v_event.id,
            'event_status', v_event.status,
            'user_id', v_event.user_id,
            'event_type', v_event.event_type,
            'source_reference', v_event.source_reference,
            'rule_code', v_rule.rule_code,
            'calculated_points', v_calculated_points,
            'points_awarded', 0,
            'reason', v_event.error_message
        );
    end if;

    update public.loyalty_cap_usage
    set
        points_awarded = points_awarded + v_awarded_points,
        updated_at = now()
    where user_id = v_user_id
      and rule_id is null
      and period_type = 'daily'
      and period_start = v_daily_start;

    update public.loyalty_cap_usage
    set
        points_awarded = points_awarded + v_awarded_points,
        updated_at = now()
    where user_id = v_user_id
      and rule_id is null
      and period_type = 'monthly'
      and period_start = v_monthly_start;

    if v_rule.daily_cap_points is not null then
        update public.loyalty_cap_usage
        set
            points_awarded = points_awarded + v_awarded_points,
            updated_at = now()
        where user_id = v_user_id
          and rule_id = v_rule.id
          and period_type = 'daily'
          and period_start = v_daily_start;
    end if;

    if v_rule.monthly_cap_points is not null then
        update public.loyalty_cap_usage
        set
            points_awarded = points_awarded + v_awarded_points,
            updated_at = now()
        where user_id = v_user_id
          and rule_id = v_rule.id
          and period_type = 'monthly'
          and period_start = v_monthly_start;
    end if;

    update public.loyalty_account
    set
        available_points = available_points + v_awarded_points,
        tier_points = tier_points + v_awarded_points,
        lifetime_earned_points =
            lifetime_earned_points + v_awarded_points,
        last_event_at = v_event_time
    where id = v_account.id
    returning * into v_account;

    select level_record.level_code
    into v_new_level
    from public.loyalty_level level_record
    where level_record.is_active = true
      and level_record.min_tier_points <= v_account.tier_points
      and (level_record.max_tier_points is null
           or level_record.max_tier_points >= v_account.tier_points)
    order by level_record.min_tier_points desc
    limit 1;

    if not found then
        raise exception 'LOYALTY_LEVEL_NOT_FOUND_FOR_POINTS_%',
            v_account.tier_points;
    end if;

    if v_new_level <> v_previous_level then
        update public.loyalty_account
        set level_code = v_new_level
        where id = v_account.id
        returning * into v_account;

        insert into public.loyalty_level_history (
            loyalty_account_id,
            user_id,
            event_id,
            previous_level_code,
            new_level_code,
            tier_points,
            reason
        )
        values (
            v_account.id,
            v_user_id,
            v_event.id,
            v_previous_level,
            v_new_level,
            v_account.tier_points,
            'points_earned'::public."LoyaltyLevelChangeReason"
        );
    end if;

    v_rule_snapshot := jsonb_build_object(
        'rule_code', v_rule.rule_code,
        'rule_name', v_rule.rule_name,
        'calculation_type', v_rule.calculation_type,
        'fixed_points', v_rule.fixed_points,
        'points_per_usd', v_rule.points_per_usd,
        'multiplier', v_rule.multiplier,
        'min_points_per_event', v_rule.min_points_per_event,
        'max_points_per_event', v_rule.max_points_per_event,
        'daily_cap_points', v_rule.daily_cap_points,
        'monthly_cap_points', v_rule.monthly_cap_points,
        'condition_config', v_rule.condition_config,
        'calculated_points', v_calculated_points,
        'awarded_points', v_awarded_points
    );

    insert into public.loyalty_ledger (
        loyalty_account_id,
        user_id,
        event_id,
        rule_id,
        ledger_type,
        event_type,
        points_delta,
        available_balance_after,
        tier_points_delta,
        tier_balance_after,
        source_reference,
        description,
        rule_snapshot,
        metadata
    )
    values (
        v_account.id,
        v_user_id,
        v_event.id,
        v_rule.id,
        'earn'::public."LoyaltyLedgerType",
        p_event_type,
        v_awarded_points,
        v_account.available_points,
        v_awarded_points,
        v_account.tier_points,
        v_source_reference,
        v_rule.rule_name,
        v_rule_snapshot,
        v_metadata
    )
    returning * into v_ledger;

    update public.gamification_event
    set
        status = 'completed'::public."GamificationEventStatus",
        processed_at = now(),
        lease_expires_at = null,
        error_message = null,
        metadata = metadata || jsonb_build_object(
            'rule_code', v_rule.rule_code,
            'calculated_points', v_calculated_points,
            'points_awarded', v_awarded_points,
            'level_code', v_account.level_code
        )
    where id = v_event.id
    returning * into v_event;

    insert into public.gamification_notification (
        user_id,
        event_id,
        notification_type,
        points,
        title,
        subtitle,
        display_priority,
        payload
    )
    values (
        v_user_id,
        v_event.id,
        'points_earned'::public."GamificationNotificationType",
        v_awarded_points,
        '+' || v_awarded_points::text || ' points',
        v_rule.rule_name,
        100,
        jsonb_build_object(
            'event_type', p_event_type,
            'source_reference', v_source_reference,
            'points_awarded', v_awarded_points,
            'available_points', v_account.available_points,
            'tier_points', v_account.tier_points,
            'level_code', v_account.level_code
        )
    )
    on conflict (event_id, notification_type)
    where event_id is not null
    do nothing;

    if v_new_level <> v_previous_level then
        insert into public.gamification_notification (
            user_id,
            event_id,
            notification_type,
            points,
            title,
            subtitle,
            display_priority,
            payload
        )
        values (
            v_user_id,
            v_event.id,
            'level_up'::public."GamificationNotificationType",
            0,
            'Level up!',
            'You reached ' || initcap(v_new_level),
            10,
            jsonb_build_object(
                'previous_level_code', v_previous_level,
                'new_level_code', v_new_level,
                'tier_points', v_account.tier_points
            )
        )
        on conflict (event_id, notification_type)
        where event_id is not null
        do nothing;
    end if;

    v_result := jsonb_build_object(
        'success', true,
        'idempotent_replay', false,
        'event_id', v_event.id,
        'event_status', v_event.status,
        'user_id', v_event.user_id,
        'event_type', v_event.event_type,
        'source_reference', v_event.source_reference,
        'rule_code', v_rule.rule_code,
        'calculated_points', v_calculated_points,
        'points_awarded', v_awarded_points,
        'available_points', v_account.available_points,
        'tier_points', v_account.tier_points,
        'lifetime_earned_points', v_account.lifetime_earned_points,
        'previous_level_code', v_previous_level,
        'level_code', v_account.level_code,
        'level_changed', v_new_level <> v_previous_level,
        'ledger_id', v_ledger.id
    );

    return v_result;
end;
$$;
ALTER FUNCTION "public"."award_loyalty_points"("p_idempotency_key" "text", "p_event_type" "public"."LoyaltyEventType", "p_user_id" "text", "p_source_reference" "text", "p_source_transaction_id" "text", "p_transaction_type" "public"."TransactionType", "p_amount" numeric, "p_amount_usd" numeric, "p_country_code" "text", "p_currency_code" "text", "p_metadata" "jsonb") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."begin_liquidation_blockchain_submission"("p_queue_id" "text", "p_signed_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
    v_queue public.liquidation_blockchain_queue%rowtype;
    v_queue_id text;
BEGIN
    IF coalesce(auth.role(), '') <> 'service_role' THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'SERVICE_ROLE_REQUIRED';
    END IF;

    v_queue_id := nullif(btrim(p_queue_id), '');

    IF v_queue_id IS NULL THEN
        RAISE EXCEPTION 'LIQUIDATION_QUEUE_ID_REQUIRED';
    END IF;

    IF p_signed_payload IS NULL
       OR jsonb_typeof(p_signed_payload) IS DISTINCT FROM 'object'
    THEN
        RAISE EXCEPTION 'INVALID_LIQUIDATION_SIGNED_PAYLOAD';
    END IF;

    SELECT q.*
    INTO v_queue
    FROM public.liquidation_blockchain_queue AS q
    WHERE q.id = v_queue_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'LIQUIDATION_BLOCKCHAIN_QUEUE_NOT_FOUND';
    END IF;

    IF v_queue.manual_review_required THEN
        RAISE EXCEPTION
            'LIQUIDATION_BLOCKCHAIN_MANUAL_REVIEW_REQUIRED';
    END IF;

    IF v_queue.tx_hash IS NOT NULL THEN
        RAISE EXCEPTION
            'LIQUIDATION_BLOCKCHAIN_ALREADY_SUBMITTED';
    END IF;

    /*
     * Never automatically reopen submission after this
     * marker has been set, even if the lease expires.
     */
    IF v_queue.submission_started_at IS NOT NULL THEN
        RAISE EXCEPTION
            'LIQUIDATION_BLOCKCHAIN_SUBMISSION_ALREADY_STARTED';
    END IF;

    IF v_queue.status::text <> 'processing' THEN
        RAISE EXCEPTION
            'LIQUIDATION_BLOCKCHAIN_QUEUE_NOT_PROCESSING';
    END IF;

    IF v_queue.lease_expires_at IS NULL
       OR v_queue.lease_expires_at <= clock_timestamp()
    THEN
        RAISE EXCEPTION
            'LIQUIDATION_BLOCKCHAIN_LEASE_EXPIRED';
    END IF;

    /*
     * The worker must submit exactly the payload saved
     * in PostgreSQL, including its blockchain metadata.
     */
    IF v_queue.signed_payload IS NULL
       OR v_queue.signed_payload IS DISTINCT FROM p_signed_payload
    THEN
        RAISE EXCEPTION
            'LIQUIDATION_SIGNED_PAYLOAD_MISMATCH';
    END IF;

    IF (v_queue.signed_payload ->> 'blockchain_code')
       IS DISTINCT FROM v_queue.blockchain_code
    THEN
        RAISE EXCEPTION
            'LIQUIDATION_SIGNED_BLOCKCHAIN_MISMATCH';
    END IF;

    /*
     * Refuse an expired or nearly expired permit.
     */
    IF coalesce(
        v_queue.signed_payload ->> 'deadline',
        ''
    ) !~ '^[0-9]+$'
    THEN
        RAISE EXCEPTION
            'INVALID_LIQUIDATION_SIGNATURE_DEADLINE';
    END IF;

    IF (v_queue.signed_payload ->> 'deadline')::numeric <=
       extract(epoch FROM clock_timestamp()) + 30
    THEN
        RAISE EXCEPTION
            'LIQUIDATION_SIGNATURE_EXPIRED_OR_EXPIRING';
    END IF;

    UPDATE public.liquidation_blockchain_queue
    SET
        submission_started_at = clock_timestamp(),
        updated_at = now()
    WHERE id = v_queue.id
    RETURNING * INTO v_queue;

    RETURN jsonb_build_object(
        'success', true,
        'queue_id', v_queue.id,
        'blockchain_code', v_queue.blockchain_code,
        'submission_started_at', v_queue.submission_started_at
    );
END;
$_$;
ALTER FUNCTION "public"."begin_liquidation_blockchain_submission"("p_queue_id" "text", "p_signed_payload" "jsonb") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."build_country_supported_currencies"("p_country_code" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'currency_code',
                sc.currency_code,

                'symbol',
                sc.symbol,

                'name',
                sc.name,

                'is_active',
                sc.is_active,

                'is_reporting',
                cc.is_reporting
            )
            order by sc.currency_code
        ),
        '[]'::jsonb
    )
    from public.country_currencies cc
    join public.supported_currency sc
      on lower(sc.currency_code) =
         lower(cc.currency_code)
    where cc.country_code =
          p_country_code
      and cc.is_active = true
      and sc.is_active = true;
$$;
ALTER FUNCTION "public"."build_country_supported_currencies"("p_country_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."build_my_accounts_dashboard"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;
    v_fiscal_year integer;

    v_row record;
    v_rate numeric;

    v_revenue numeric;
    v_expenses numeric;
    v_net_profit numeric;

    v_assets numeric;
    v_liabilities numeric;
    v_equity numeric;
    v_equity_with_profit numeric;

    v_bank_net numeric;

    v_revenue_usd numeric;
    v_expenses_usd numeric;
    v_net_profit_usd numeric;

    v_assets_usd numeric;
    v_liabilities_usd numeric;
    v_equity_usd numeric;

    v_kpi jsonb :=
        '{}'::jsonb;

    v_snapshot jsonb :=
        '{}'::jsonb;

    v_bank_net_result jsonb :=
        '{}'::jsonb;

    v_currencies jsonb :=
        '[]'::jsonb;

    v_agent_commission_settlements jsonb :=
        '[]'::jsonb;

    v_government_tax_settlements jsonb :=
        '[]'::jsonb;
begin
    /*
     * Authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Fetch the authenticated application user and
     * enforce the Accounts role.
     */
    select user_record.*
    into v_user
    from public.users user_record
    join public.user_role role_record
      on role_record.id =
         user_record.role_id
    where user_record.id =
              auth.uid()::text

      and user_record.status =
              'active'::public."UserStatus"

      and lower(
          role_record.name::text
      ) =
              'accounts'
    limit 1;

    if not found then
        raise exception using
            errcode = '42501',
            message = 'ACCOUNTS_NOT_AUTHORIZED';
    end if;

    /*
     * Current fiscal year.
     */
    select fiscal_period_record.fiscal_year
    into v_fiscal_year
    from public.fiscal_period_config
        fiscal_period_record
    where fiscal_period_record.country_code =
              v_user.country_code

      and fiscal_period_record.opening_date <=
              current_date

      and fiscal_period_record.closing_date >=
              current_date
    order by
        fiscal_period_record.fiscal_year desc,
        fiscal_period_record.period desc
    limit 1;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Calculate accounting totals by currency.
     */
    for v_row in
        select
            lower(
                btrim(
                    financial_entry_record.currency_code
                )
            ) as currency_code,

            coalesce(
                sum(
                    case
                        when gl_account_record.type::text =
                             'revenue'
                        then
                            coalesce(
                                financial_entry_record.credit,
                                0
                            )
                            -
                            coalesce(
                                financial_entry_record.debit,
                                0
                            )
                        else
                            0
                    end
                ),
                0
            )::numeric as revenue,

            coalesce(
                sum(
                    case
                        when gl_account_record.type::text =
                             'expense'
                        then
                            coalesce(
                                financial_entry_record.debit,
                                0
                            )
                            -
                            coalesce(
                                financial_entry_record.credit,
                                0
                            )
                        else
                            0
                    end
                ),
                0
            )::numeric as expenses,

            coalesce(
                sum(
                    case
                        when gl_account_record.type::text =
                             'asset'
                        then
                            coalesce(
                                financial_entry_record.debit,
                                0
                            )
                            -
                            coalesce(
                                financial_entry_record.credit,
                                0
                            )
                        else
                            0
                    end
                ),
                0
            )::numeric as assets,

            coalesce(
                sum(
                    case
                        when gl_account_record.type::text =
                             'liability'
                        then
                            coalesce(
                                financial_entry_record.credit,
                                0
                            )
                            -
                            coalesce(
                                financial_entry_record.debit,
                                0
                            )
                        else
                            0
                    end
                ),
                0
            )::numeric as liabilities,

            coalesce(
                sum(
                    case
                        when gl_account_record.type::text =
                             'equity'
                        then
                            coalesce(
                                financial_entry_record.credit,
                                0
                            )
                            -
                            coalesce(
                                financial_entry_record.debit,
                                0
                            )
                        else
                            0
                    end
                ),
                0
            )::numeric as equity,

            coalesce(
                sum(
                    case
                        when financial_entry_record.gl_account_code =
                             '1001000'
                        then
                            coalesce(
                                financial_entry_record.debit,
                                0
                            )
                            -
                            coalesce(
                                financial_entry_record.credit,
                                0
                            )
                        else
                            0
                    end
                ),
                0
            )::numeric as bank_net

        from public.financial_entry
            financial_entry_record

        join public.gl_account
            gl_account_record
          on gl_account_record.code =
             financial_entry_record.gl_account_code

        where financial_entry_record.country_code =
                  v_user.country_code

          and financial_entry_record.fiscal_year =
                  v_fiscal_year

          and lower(
              btrim(
                  financial_entry_record.currency_code
              )
          ) <>
                  'gold'

        group by
            lower(
                btrim(
                    financial_entry_record.currency_code
                )
            )

        order by
            lower(
                btrim(
                    financial_entry_record.currency_code
                )
            )
    loop
        v_revenue :=
            coalesce(
                v_row.revenue,
                0
            );

        v_expenses :=
            coalesce(
                v_row.expenses,
                0
            );

        v_assets :=
            coalesce(
                v_row.assets,
                0
            );

        v_liabilities :=
            coalesce(
                v_row.liabilities,
                0
            );

        v_equity :=
            coalesce(
                v_row.equity,
                0
            );

        v_bank_net :=
            coalesce(
                v_row.bank_net,
                0
            );

        v_net_profit :=
            v_revenue -
            v_expenses;

        v_equity_with_profit :=
            v_equity +
            v_net_profit;

        /*
         * Convert balances to USD.
         *
         * USD is already in USD. Other fiat balances are
         * divided by rate_to_usd.
         */
        if v_row.currency_code = 'usd' then
            v_revenue_usd :=
                v_revenue;

            v_expenses_usd :=
                v_expenses;

            v_net_profit_usd :=
                v_net_profit;

            v_assets_usd :=
                v_assets;

            v_liabilities_usd :=
                v_liabilities;

            v_equity_usd :=
                v_equity_with_profit;
        else
            select current_rate_record.rate_to_usd
            into v_rate
            from public.current_rates
                current_rate_record
            where lower(
                btrim(
                    current_rate_record.code
                )
            ) =
                v_row.currency_code
            limit 1;

            if not found
               or v_rate is null
               or v_rate = 0
            then
                raise exception
                    'MISSING_RATE_FOR_%',
                    upper(
                        v_row.currency_code
                    );
            end if;

            v_revenue_usd :=
                v_revenue /
                v_rate;

            v_expenses_usd :=
                v_expenses /
                v_rate;

            v_net_profit_usd :=
                v_net_profit /
                v_rate;

            v_assets_usd :=
                v_assets /
                v_rate;

            v_liabilities_usd :=
                v_liabilities /
                v_rate;

            v_equity_usd :=
                v_equity_with_profit /
                v_rate;
        end if;

        /*
         * KPI response.
         */
        v_kpi :=
            v_kpi ||
            jsonb_build_object(
                v_row.currency_code,

                jsonb_build_object(
                    'total_revenue',
                    jsonb_build_object(
                        'balance',
                        trim_scale(
                            v_revenue
                        )::text,

                        'usd_value',
                        trim_scale(
                            v_revenue_usd
                        )::text
                    ),

                    'total_expenses',
                    jsonb_build_object(
                        'balance',
                        trim_scale(
                            v_expenses
                        )::text,

                        'usd_value',
                        trim_scale(
                            v_expenses_usd
                        )::text
                    ),

                    'net_profit',
                    jsonb_build_object(
                        'balance',
                        trim_scale(
                            v_net_profit
                        )::text,

                        'usd_value',
                        trim_scale(
                            v_net_profit_usd
                        )::text
                    )
                )
            );

        /*
         * Balance-sheet snapshot.
         */
        v_snapshot :=
            v_snapshot ||
            jsonb_build_object(
                v_row.currency_code,

                jsonb_build_object(
                    'assets',
                    jsonb_build_object(
                        'balance',
                        trim_scale(
                            v_assets
                        )::text,

                        'usd_value',
                        trim_scale(
                            v_assets_usd
                        )::text
                    ),

                    'liabilities',
                    jsonb_build_object(
                        'balance',
                        trim_scale(
                            v_liabilities
                        )::text,

                        'usd_value',
                        trim_scale(
                            v_liabilities_usd
                        )::text
                    ),

                    'equity',
                    jsonb_build_object(
                        'balance',
                        trim_scale(
                            v_equity_with_profit
                        )::text,

                        'usd_value',
                        trim_scale(
                            v_equity_usd
                        )::text
                    )
                )
            );

        /*
         * Preserve bank_net as a JSON number, matching
         * toNumber() in the original code.
         */
        v_bank_net_result :=
            v_bank_net_result ||
            jsonb_build_object(
                v_row.currency_code,
                v_bank_net
            );
    end loop;

    /*
     * Supported active fiat currencies for the Accounts
     * user's country.
     */
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'currency_code',
                supported_currency_record.currency_code,

                'symbol',
                supported_currency_record.symbol,

                'name',
                supported_currency_record.name,

                'is_active',
                supported_currency_record.is_active,

                'is_reporting',
                country_currency_record.is_reporting
            )
            order by
                supported_currency_record.currency_code
        ),
        '[]'::jsonb
    )
    into v_currencies
    from public.country_currencies
        country_currency_record

    join public.supported_currency
        supported_currency_record
      on lower(
          supported_currency_record.currency_code
      ) =
         lower(
             country_currency_record.currency_code
         )

    where country_currency_record.country_code =
              v_user.country_code

      and country_currency_record.is_active =
              true

      and supported_currency_record.is_active =
              true

      and supported_currency_record.currency_category =
              'fiat'::public."CurrencyCategory";

    /*
     * Fetch the latest Agent Commission settlement dates
     * for all commission currencies.
     */
    v_agent_commission_settlements :=
        public.fetch_my_last_agent_commission_settlement();

    /*
     * Fetch the latest Government Tax settlement dates
     * for all tax currencies.
     */
    v_government_tax_settlements :=
        public.fetch_my_last_government_tax_settlement();

    /*
     * Preserve all existing dashboard fields and add the
     * two settlement-date collections.
     */
    return jsonb_build_object(
        'kpi',
        v_kpi,

        'balance_sheet_snapshot',
        v_snapshot,

        'currencies',
        v_currencies,

        'bank_net',
        v_bank_net_result,

        'agent_commission_settlements',
        v_agent_commission_settlements,

        'government_tax_settlements',
        v_government_tax_settlements
    );
end;
$$;
ALTER FUNCTION "public"."build_my_accounts_dashboard"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."build_my_admin_dashboard"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_total_users integer := 0;
    v_total_credit_agents integer := 0;

    v_global_role_counts jsonb :=
        '{}'::jsonb;

    v_roles jsonb :=
        '[]'::jsonb;

    v_supported_currencies jsonb :=
        '[]'::jsonb;

    v_operational_countries jsonb :=
        '[]'::jsonb;

    v_countries jsonb :=
        '[]'::jsonb;

    v_country record;
    v_country_role_counts jsonb;
    v_country_total_users integer;
    v_country_credit_agents integer;
begin
    /*
     * Authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Only the global system administrator may access
     * this dashboard.
     */
    if not public.has_role(
        array[
            'admin'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Fetch every configured application role.
     */
    select coalesce(
        jsonb_agg(
            configured_role.role_name
            order by
                configured_role.role_name
        ),
        '[]'::jsonb
    )
    into v_roles
    from (
        select lower(
            role_record.name::text
        ) as role_name
        from public.user_role
            role_record
    ) configured_role;

    /*
     * Fetch every currency supported by the system.
     *
     * is_reporting is null because reporting status is a
     * country-level configuration.
     */
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'currency_code',
                lower(
                    btrim(
                        supported_record.currency_code
                    )
                ),

                'name',
                supported_record.name,

                'decimals',
                supported_record.decimals,

                'symbol',
                supported_record.symbol,

                'rate_api',
                supported_record.rate_api,

                'is_active',
                supported_record.is_active,

                'is_reporting',
                null
            )
            order by
                lower(
                    btrim(
                        supported_record.currency_code
                    )
                )
        ),
        '[]'::jsonb
    )
    into v_supported_currencies
    from public.supported_currency
        supported_record;

    /*
     * Fetch every operational country.
     *
     * Country-currency is_active and is_reporting values
     * come from country_currencies.
     *
     * Currency name, decimals, symbol and rate API come
     * from supported_currency.
     */
        select coalesce(
            jsonb_agg(
                jsonb_build_object(
                    'country_code',
                    lower(
                        btrim(
                            country_record.country_code
                        )
                    ),

                    'name',
                    country_record.name,

                    'calling_code',
                    country_record.calling_code,

                    'is_active',
                    country_record.is_active,

                    'currencies',
                    coalesce(
                        (
                            select jsonb_agg(
                                jsonb_build_object(
                                    'currency_code',
                                    lower(
                                        btrim(
                                            supported_record.currency_code
                                        )
                                    ),

                                    'name',
                                    supported_record.name,

                                    'decimals',
                                    supported_record.decimals,

                                    'symbol',
                                    supported_record.symbol,

                                    'rate_api',
                                    supported_record.rate_api,

                                    /*
                                    * In this list, is_active is the
                                    * country-currency status.
                                    */
                                    'is_active',
                                    country_currency_record.is_active,

                                    'is_reporting',
                                    country_currency_record.is_reporting
                                )
                                order by
                                    lower(
                                        btrim(
                                            supported_record.currency_code
                                        )
                                    )
                            )
                            from public.country_currencies
                                country_currency_record

                            join public.supported_currency
                                supported_record
                            on lower(
                                btrim(
                                    supported_record.currency_code
                                )
                            ) =
                                lower(
                                    btrim(
                                        country_currency_record.currency_code
                                    )
                                )

                            where lower(
                                btrim(
                                    country_currency_record.country_code
                                )
                            ) =
                                lower(
                                    btrim(
                                        country_record.country_code
                                    )
                                )
                        ),
                        '[]'::jsonb
                    )
                )
                order by
                    country_record.name,
                    country_record.country_code
            ),
            '[]'::jsonb
        )
        into v_operational_countries
        from public.operational_country
            country_record;
    /*
     * Total registered users globally.
     */
    select count(*)::integer
    into v_total_users
    from public.users;

    /*
     * Count active credit agents globally.
     *
     * A credit agent has one account per currency, so
     * merchant_id must be counted distinctly.
     */
    select count(
        distinct account_record.merchant_id
    )::integer
    into v_total_credit_agents
    from public.credit_agent_account
        account_record

    join public.users merchant_record
      on merchant_record.id =
         account_record.merchant_id

    where account_record.is_active =
          true

      and merchant_record.status =
          'active'::public."UserStatus";

    /*
     * Global user count for every configured role.
     */
    select coalesce(
        jsonb_object_agg(
            role_count.role_name,
            role_count.user_count
            order by
                role_count.role_name
        ),
        '{}'::jsonb
    )
    into v_global_role_counts
    from (
        select
            lower(
                role_record.name::text
            ) as role_name,

            count(
                user_record.id
            )::integer as user_count

        from public.user_role
            role_record

        left join public.users
            user_record
          on user_record.role_id =
             role_record.id

        group by
            lower(
                role_record.name::text
            )
    ) role_count;

    /*
     * Build per-country user totals.
     */
    for v_country in
        select distinct
            lower(
                btrim(
                    user_record.country_code
                )
            ) as country_code

        from public.users
            user_record

        where nullif(
            btrim(
                user_record.country_code
            ),
            ''
        ) is not null

        order by
            lower(
                btrim(
                    user_record.country_code
                )
            )
    loop
        /*
         * Total users in this country.
         */
        select count(*)::integer
        into v_country_total_users
        from public.users
            user_record
        where lower(
            btrim(
                user_record.country_code
            )
        ) =
            v_country.country_code;

        /*
         * Active credit agents in this country.
         */
        select count(
            distinct account_record.merchant_id
        )::integer
        into v_country_credit_agents
        from public.credit_agent_account
            account_record

        join public.users merchant_record
          on merchant_record.id =
             account_record.merchant_id

        where lower(
            btrim(
                account_record.country_code
            )
        ) =
            v_country.country_code

          and account_record.is_active =
              true

          and merchant_record.status =
              'active'::public."UserStatus";

        /*
         * User counts per role for this country.
         */
        select coalesce(
            jsonb_object_agg(
                role_count.role_name,
                role_count.user_count
                order by
                    role_count.role_name
            ),
            '{}'::jsonb
        )
        into v_country_role_counts
        from (
            select
                lower(
                    role_record.name::text
                ) as role_name,

                count(
                    user_record.id
                )::integer as user_count

            from public.user_role
                role_record

            left join public.users
                user_record
              on user_record.role_id =
                 role_record.id

             and lower(
                 btrim(
                     user_record.country_code
                 )
             ) =
                 v_country.country_code

            group by
                lower(
                    role_record.name::text
                )
        ) role_count;

        v_countries :=
            v_countries ||
            jsonb_build_array(
                jsonb_build_object(
                    'countryCode',
                    v_country.country_code,

                    'totalUsers',
                    v_country_total_users,

                    'creditAgents',
                    v_country_credit_agents,

                    'roleCounts',
                    v_country_role_counts
                )
            );
    end loop;

    return jsonb_build_object(
        'summary',
        jsonb_build_object(
            'totalUsers',
            v_total_users,

            'creditAgents',
            v_total_credit_agents,

            'roleCounts',
            v_global_role_counts
        ),

        /*
         * Per-country user statistics.
         */
        'countries',
        v_countries,

        /*
         * System configuration.
         */
        'roles',
        v_roles,

        'supportedCurrencies',
        v_supported_currencies,

        'operationalCountries',
        v_operational_countries
    );
end;
$$;
ALTER FUNCTION "public"."build_my_admin_dashboard"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."build_my_agent_dashboard"("p_blockchain_balances" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_user public.users%rowtype;

    v_currencies jsonb;
    v_wallet jsonb;
    v_daily_summary jsonb;
    v_loan_summary jsonb;
    v_blockchain_balances jsonb := '[]'::jsonb;

    v_total_tokens numeric := 0;
    v_locked_tokens numeric := 0;
    v_available_tokens numeric := 0;

    v_principal numeric := 0;
    v_interest numeric := 0;

    v_gold_price numeric := 0;
    v_collateral_value numeric := 0;
    v_ltv numeric := 0;
    v_health text := 'SAFE';

    v_required_collateral numeric := 0;

    v_available_points bigint := 0;
    v_tier_points bigint := 0;
    v_lifetime_earned_points bigint := 0;
    v_loyalty_level text := 'bronze';
    v_loyalty_account_active boolean := false;

    v_active_loans bigint := 0;
    v_active_loan_config_rows bigint := 0;
    v_min_max_active_loans numeric;
    v_max_max_active_loans numeric;
    v_max_active_loans integer;
    v_sva_access_utilisation numeric := 0;
    v_can_access_sva boolean := false;

    v_item jsonb;
    v_blockchain_code text;
    v_balance numeric;
    v_seen_blockchains text[] := ARRAY[]::text[];

BEGIN
    ------------------------------------------------------------
    -- AUTHENTICATION
    ------------------------------------------------------------
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;

    ------------------------------------------------------------
    -- RESOLVE AND AUTHORIZE ACTIVE AGENT
    ------------------------------------------------------------
    SELECT
        u.*
    INTO
        v_user
    FROM public.users u
    JOIN public.user_role r
        ON r.id = u.role_id
    WHERE u.id = auth.uid()::text
      AND u.status = 'active'::public."UserStatus"
      AND lower(r.name::text) = 'agent'
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'AGENT_NOT_AUTHORIZED';
    END IF;

    ------------------------------------------------------------
    -- CURRENT GOLD PRICE
    ------------------------------------------------------------
    SELECT
        r.rate_to_usd
    INTO
        v_gold_price
    FROM public.current_rates r
    WHERE lower(btrim(r.code)) = 'gold'
    LIMIT 1;

    v_gold_price :=
        coalesce(v_gold_price, 0);

    IF v_gold_price <= 0 THEN
        RAISE EXCEPTION
            'INVALID_GOLD_RATE';
    END IF;

    ------------------------------------------------------------
    -- VALIDATE BLOCKCHAIN BALANCES
    ------------------------------------------------------------
    IF p_blockchain_balances IS NULL
       OR jsonb_typeof(p_blockchain_balances) <> 'array'
    THEN
        RAISE EXCEPTION
            'INVALID_BLOCKCHAIN_BALANCES';
    END IF;

    ------------------------------------------------------------
    -- BUILD MULTI-CHAIN GOLD BALANCES
    ------------------------------------------------------------
    FOR v_item IN
        SELECT value
        FROM jsonb_array_elements(
            p_blockchain_balances
        )
    LOOP
        IF jsonb_typeof(v_item) <> 'object' THEN
            RAISE EXCEPTION
                'INVALID_BLOCKCHAIN_BALANCE';
        END IF;

        v_blockchain_code :=
            nullif(
                lower(
                    btrim(
                        v_item ->> 'blockchain_code'
                    )
                ),
                ''
            );

        IF v_blockchain_code IS NULL THEN
            RAISE EXCEPTION
                'BLOCKCHAIN_CODE_REQUIRED';
        END IF;

        IF v_blockchain_code = ANY(v_seen_blockchains) THEN
            RAISE EXCEPTION
                'DUPLICATE_BLOCKCHAIN_BALANCE_%',
                upper(v_blockchain_code);
        END IF;

        v_seen_blockchains :=
            array_append(
                v_seen_blockchains,
                v_blockchain_code
            );

        IF v_item ->> 'balance' IS NULL THEN
            RAISE EXCEPTION
                'BLOCKCHAIN_BALANCE_REQUIRED';
        END IF;

        BEGIN
            v_balance :=
                (v_item ->> 'balance')::numeric;

        EXCEPTION
            WHEN invalid_text_representation
              OR numeric_value_out_of_range
            THEN
                RAISE EXCEPTION
                    'INVALID_BLOCKCHAIN_TOKEN_BALANCE';
        END;

        IF v_balance < 0
           OR v_balance::text IN (
               'NaN',
               'Infinity',
               '-Infinity'
           )
        THEN
            RAISE EXCEPTION
                'INVALID_BLOCKCHAIN_TOKEN_BALANCE';
        END IF;

        v_total_tokens :=
            v_total_tokens + v_balance;

        v_blockchain_balances :=
            v_blockchain_balances ||
            jsonb_build_array(
                jsonb_build_object(
                    'blockchain_code',
                    v_blockchain_code,

                    'currency_code',
                    'gold',

                    'balance',
                    v_balance::text,

                    'usd_value',
                    (
                        v_balance *
                        v_gold_price
                    )::text
                )
            );
    END LOOP;

    ------------------------------------------------------------
    -- SUPPORTED CURRENCIES
    ------------------------------------------------------------
    v_currencies :=
        public.build_country_supported_currencies(
            v_user.country_code
        );

    ------------------------------------------------------------
    -- WALLET BALANCES
    ------------------------------------------------------------
    v_wallet :=
        jsonb_build_object(
            'agent',
            jsonb_build_object(
                'balances',
                '{}'::jsonb
            ),
            'customer',
            jsonb_build_object(
                'balances',
                '{}'::jsonb
            )
        )
        ||
        public.build_user_wallet_balance(
            v_user.id
        );

    ------------------------------------------------------------
    -- DAILY SUMMARY
    ------------------------------------------------------------
    v_daily_summary :=
        public.build_user_daily_summary(
            v_user.id
        );

    ------------------------------------------------------------
    -- LOYALTY
    ------------------------------------------------------------
    SELECT
        a.available_points,
        a.tier_points,
        a.lifetime_earned_points,
        a.level_code,
        a.is_active
    INTO
        v_available_points,
        v_tier_points,
        v_lifetime_earned_points,
        v_loyalty_level,
        v_loyalty_account_active
    FROM public.loyalty_account a
    WHERE a.user_id = v_user.id
    LIMIT 1;

    v_available_points :=
        greatest(
            coalesce(v_available_points, 0),
            0
        );

    v_tier_points :=
        greatest(
            coalesce(v_tier_points, 0),
            0
        );

    v_lifetime_earned_points :=
        greatest(
            coalesce(v_lifetime_earned_points, 0),
            0
        );

    v_loyalty_level :=
        coalesce(
            nullif(
                btrim(v_loyalty_level),
                ''
            ),
            'bronze'
        );

    v_loyalty_account_active :=
        coalesce(
            v_loyalty_account_active,
            false
        );

    ------------------------------------------------------------
    -- CURRENT POOLED COLLATERAL
    ------------------------------------------------------------
    SELECT
        coalesce(
            c.locked_tokens,
            0
        )
    INTO
        v_locked_tokens
    FROM public.collateral c
    WHERE c.user_id = v_user.id
    LIMIT 1;

    v_locked_tokens :=
        greatest(
            coalesce(v_locked_tokens, 0),
            0
        );

    v_available_tokens :=
        greatest(
            v_total_tokens -
            v_locked_tokens,
            0
        );

    ------------------------------------------------------------
    -- REQUIRED COLLATERAL
    ------------------------------------------------------------
    v_required_collateral :=
        public.calculate_required_collateral(
            v_user.id
        );

    ------------------------------------------------------------
    -- MAXIMUM ACTIVE LOANS CONFIGURATION
    ------------------------------------------------------------
    SELECT
        count(*),
        min(c.rate),
        max(c.rate)
    INTO
        v_active_loan_config_rows,
        v_min_max_active_loans,
        v_max_max_active_loans
    FROM public.loan_config c
    WHERE c.country_code =
          v_user.country_code
      AND lower(
          btrim(
              c.config_type::text
          )
      ) = 'max_active_loans'
      AND c.is_active = true;

    IF v_active_loan_config_rows = 0
       OR v_min_max_active_loans IS NULL
    THEN
        RAISE EXCEPTION
            'MAX_ACTIVE_LOANS_NOT_CONFIGURED';
    END IF;

    IF v_min_max_active_loans IS DISTINCT FROM
       v_max_max_active_loans
    THEN
        RAISE EXCEPTION
            'MAX_ACTIVE_LOANS_CONFIGURATION_AMBIGUOUS';
    END IF;

    IF v_min_max_active_loans <= 0
       OR trunc(v_min_max_active_loans) <>
          v_min_max_active_loans
    THEN
        RAISE EXCEPTION
            'INVALID_MAX_ACTIVE_LOANS';
    END IF;

    v_max_active_loans :=
        v_min_max_active_loans::integer;

    ------------------------------------------------------------
    -- ACTIVE LOAN BALANCES
    ------------------------------------------------------------
    SELECT
        count(
            distinct l.id
        )::bigint,

        coalesce(
            sum(e.debit_principal),
            0
        ) -
        coalesce(
            sum(e.credit_principal),
            0
        ),

        coalesce(
            sum(e.debit_interest),
            0
        ) -
        coalesce(
            sum(e.credit_interest),
            0
        )

    INTO
        v_active_loans,
        v_principal,
        v_interest

    FROM public.loan l
    LEFT JOIN public.loan_entry e
        ON e.loan_id = l.id
    WHERE l.user_id = v_user.id
      AND l.status =
          'active'::public."LoanStatus";

    v_active_loans :=
        greatest(
            coalesce(v_active_loans, 0),
            0
        );

    v_principal :=
        greatest(
            coalesce(v_principal, 0),
            0
        );

    v_interest :=
        greatest(
            coalesce(v_interest, 0),
            0
        );

    ------------------------------------------------------------
    -- SVA ACCESS
    ------------------------------------------------------------
    v_sva_access_utilisation :=
        round(
            (
                v_active_loans::numeric /
                v_max_active_loans::numeric
            ) * 100,
            2
        );

    v_can_access_sva :=
        v_sva_access_utilisation < 100;

    ------------------------------------------------------------
    -- CURRENT COLLATERAL VALUE AND LTV
    ------------------------------------------------------------
    v_collateral_value :=
        v_locked_tokens *
        v_gold_price;

    IF v_collateral_value > 0 THEN
        v_ltv :=
            (
                v_principal +
                v_interest
            ) /
            v_collateral_value *
            100;
    ELSE
        v_ltv := 0;
    END IF;

    IF v_ltv >= 85 THEN
        v_health :=
            'LIQUIDATION_RISK';

    ELSIF v_ltv >= 70 THEN
        v_health :=
            'WARNING';

    ELSE
        v_health :=
            'SAFE';
    END IF;

    ------------------------------------------------------------
    -- LOAN SUMMARY
    ------------------------------------------------------------
    v_loan_summary :=
        jsonb_build_object(
            'principal_outstanding',
            trim_scale(
                v_principal
            )::text,

            'interest_outstanding',
            trim_scale(
                v_interest
            )::text,

            'collateral_locked',
            trim_scale(
                v_locked_tokens
            )::text,

            'required_collateral',
            to_char(
                v_required_collateral,
                'FM999999999999999999999999990.000000'
            ),

            'ltv_percent',
            to_char(
                round(v_ltv, 2),
                'FM999999999999999999999999990.00'
            ),

            'health',
            v_health,

            'sva_access',
            jsonb_build_object(
                'active_loans',
                v_active_loans,

                'max_active_loans',
                v_max_active_loans,

                'utilisation_percent',
                to_char(
                    v_sva_access_utilisation,
                    'FM999999999999999999999999990.00'
                ),

                'can_access',
                v_can_access_sva
            ),

            'gold',
            jsonb_build_object(
                'total',
                jsonb_build_object(
                    'grams',
                    to_char(
                        round(
                            v_total_tokens,
                            6
                        ),
                        'FM999999999999999999999999990.000000'
                    ),

                    'usdValue',
                    to_char(
                        round(
                            v_total_tokens *
                            v_gold_price,
                            2
                        ),
                        'FM999999999999999999999999990.00'
                    )
                ),

                'locked',
                jsonb_build_object(
                    'grams',
                    to_char(
                        round(
                            v_locked_tokens,
                            6
                        ),
                        'FM999999999999999999999999990.000000'
                    ),

                    'usdValue',
                    to_char(
                        round(
                            v_locked_tokens *
                            v_gold_price,
                            2
                        ),
                        'FM999999999999999999999999990.00'
                    )
                ),

                'available',
                jsonb_build_object(
                    'grams',
                    to_char(
                        round(
                            v_available_tokens,
                            6
                        ),
                        'FM999999999999999999999999990.000000'
                    ),

                    'usdValue',
                    to_char(
                        round(
                            v_available_tokens *
                            v_gold_price,
                            2
                        ),
                        'FM999999999999999999999999990.00'
                    )
                )
            )
        );

    ------------------------------------------------------------
    -- RETURN DASHBOARD
    ------------------------------------------------------------
    RETURN jsonb_build_object(
        'currencies',
        v_currencies,

        'wallet',
        v_wallet,

        'dailySummary',
        v_daily_summary,

        'loyalty',
        jsonb_build_object(
            'available_points',
            v_available_points,

            'tier_points',
            v_tier_points,

            'lifetime_earned_points',
            v_lifetime_earned_points,

            'level_code',
            v_loyalty_level,

            'is_active',
            v_loyalty_account_active
        ),

        'loanSummary',
        v_loan_summary,

        'blockchainBalances',
        v_blockchain_balances
    );
END;
$$;
ALTER FUNCTION "public"."build_my_agent_dashboard"("p_blockchain_balances" "jsonb") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."build_my_compliance_dashboard"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE

    -- ========================================================
    -- GLOBAL COUNTS
    -- ========================================================

    v_total_users integer := 0;
    v_started integer := 0;
    v_not_started integer := 0;
    v_verified integer := 0;
    v_rejected integer := 0;
    v_pending_review integer := 0;


    -- ========================================================
    -- JSON RESULTS
    -- ========================================================

    v_role_counts jsonb :=
        '{}'::jsonb;

    v_countries jsonb :=
        '[]'::jsonb;


    -- ========================================================
    -- COUNTRY LOOP
    -- ========================================================

    v_country record;

    v_country_total_users integer;
    v_country_started integer;
    v_country_not_started integer;
    v_country_verified integer;
    v_country_rejected integer;
    v_country_pending_review integer;

    v_country_role_counts jsonb;

BEGIN

    -- ========================================================
    -- AUTHENTICATION
    -- ========================================================

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;


    -- ========================================================
    -- AUTHORIZATION
    --
    -- Only compliance users may access this dashboard.
    -- ========================================================

    IF NOT public.has_role(
        ARRAY[
            'compliance'
        ]::text[]
    ) THEN

        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'FORBIDDEN';

    END IF;


    -- ========================================================
    -- GLOBAL KYC STATISTICS
    --
    -- Start from users because a user does not have a
    -- user_kyc record until KYC has actually started.
    --
    -- Only the following roles participate in KYC:
    --
    -- customer
    -- agent
    -- vendor
    -- merchant
    -- ========================================================

    SELECT

        count(*)::integer,

        count(
            kyc_record.id
        )::integer,

        count(*) FILTER (
            WHERE kyc_record.id IS NULL
        )::integer,

        count(*) FILTER (
            WHERE
                kyc_record.kyc_status::text =
                    'verified'
        )::integer,

        count(*) FILTER (
            WHERE
                kyc_record.kyc_status::text =
                    'rejected'
        )::integer,

        count(*) FILTER (
            WHERE
                kyc_record.id IS NOT NULL

                AND
                kyc_record.kyc_status::text
                    NOT IN (
                        'verified',
                        'rejected'
                    )
        )::integer

    INTO
        v_total_users,
        v_started,
        v_not_started,
        v_verified,
        v_rejected,
        v_pending_review

    FROM
        public.users user_record

    INNER JOIN
        public.user_role role_record
        ON role_record.id =
           user_record.role_id

    LEFT JOIN
        public.user_kyc kyc_record
        ON kyc_record.user_id =
           user_record.id
       AND kyc_record.is_current =
           true

    WHERE
        lower(
            btrim(
                role_record.name::text
            )
        ) IN (
            'customer',
            'agent',
            'vendor',
            'merchant'
        );


    -- ========================================================
    -- GLOBAL STATISTICS BY ROLE
    --
    -- Build all four supported KYC roles even when one of the
    -- roles currently has zero users.
    -- ========================================================

    SELECT
        COALESCE(
            jsonb_object_agg(
                role_statistics.role_name,
                jsonb_build_object(

                    'total_users',
                        role_statistics.total_users,

                    'started',
                        role_statistics.started,

                    'not_started',
                        role_statistics.not_started,

                    'verified',
                        role_statistics.verified,

                    'rejected',
                        role_statistics.rejected,

                    'pending_review',
                        role_statistics.pending_review
                )
                ORDER BY
                    role_statistics.role_name
            ),
            '{}'::jsonb
        )

    INTO
        v_role_counts

    FROM (

        SELECT

            lower(
                btrim(
                    role_record.name::text
                )
            )
                AS role_name,


            count(
                user_record.id
            )::integer
                AS total_users,


            count(
                kyc_record.id
            )::integer
                AS started,


            count(
                user_record.id
            ) FILTER (
                WHERE
                    kyc_record.id IS NULL
            )::integer
                AS not_started,


            count(
                user_record.id
            ) FILTER (
                WHERE
                    kyc_record.kyc_status::text =
                        'verified'
            )::integer
                AS verified,


            count(
                user_record.id
            ) FILTER (
                WHERE
                    kyc_record.kyc_status::text =
                        'rejected'
            )::integer
                AS rejected,


            count(
                user_record.id
            ) FILTER (
                WHERE
                    kyc_record.id IS NOT NULL

                    AND
                    kyc_record.kyc_status::text
                        NOT IN (
                            'verified',
                            'rejected'
                        )
            )::integer
                AS pending_review


        FROM
            public.user_role role_record


        LEFT JOIN
            public.users user_record
            ON user_record.role_id =
               role_record.id


        LEFT JOIN
            public.user_kyc kyc_record
            ON kyc_record.user_id =
               user_record.id
           AND kyc_record.is_current =
               true


        WHERE
            lower(
                btrim(
                    role_record.name::text
                )
            ) IN (
                'customer',
                'agent',
                'vendor',
                'merchant'
            )


        GROUP BY
            lower(
                btrim(
                    role_record.name::text
                )
            )

    ) role_statistics;


    -- ========================================================
    -- PER-COUNTRY STATISTICS
    --
    -- Use operational_country so the response contains the
    -- country name as well as country code.
    --
    -- Only countries containing at least one KYC-relevant user
    -- are included.
    -- ========================================================

    FOR v_country IN

        SELECT
            lower(
                btrim(
                    country_record.country_code
                )
            )
                AS country_code,

            country_record.name
                AS country_name

        FROM
            public.operational_country
                country_record

        WHERE EXISTS (

            SELECT 1

            FROM
                public.users user_record

            INNER JOIN
                public.user_role role_record
                ON role_record.id =
                   user_record.role_id

            WHERE
                lower(
                    btrim(
                        user_record.country_code
                    )
                ) =
                    lower(
                        btrim(
                            country_record.country_code
                        )
                    )

                AND
                lower(
                    btrim(
                        role_record.name::text
                    )
                ) IN (
                    'customer',
                    'agent',
                    'vendor',
                    'merchant'
                )
        )

        ORDER BY
            country_record.name,
            country_record.country_code

    LOOP

        -- ====================================================
        -- COUNTRY TOTALS
        -- ====================================================

        SELECT

            count(*)::integer,

            count(
                kyc_record.id
            )::integer,

            count(*) FILTER (
                WHERE
                    kyc_record.id IS NULL
            )::integer,

            count(*) FILTER (
                WHERE
                    kyc_record.kyc_status::text =
                        'verified'
            )::integer,

            count(*) FILTER (
                WHERE
                    kyc_record.kyc_status::text =
                        'rejected'
            )::integer,

            count(*) FILTER (
                WHERE
                    kyc_record.id IS NOT NULL

                    AND
                    kyc_record.kyc_status::text
                        NOT IN (
                            'verified',
                            'rejected'
                        )
            )::integer

        INTO
            v_country_total_users,
            v_country_started,
            v_country_not_started,
            v_country_verified,
            v_country_rejected,
            v_country_pending_review

        FROM
            public.users user_record

        INNER JOIN
            public.user_role role_record
            ON role_record.id =
               user_record.role_id

        LEFT JOIN
            public.user_kyc kyc_record
            ON kyc_record.user_id =
               user_record.id
           AND kyc_record.is_current =
               true

        WHERE
            lower(
                btrim(
                    user_record.country_code
                )
            ) =
                v_country.country_code

            AND
            lower(
                btrim(
                    role_record.name::text
                )
            ) IN (
                'customer',
                'agent',
                'vendor',
                'merchant'
            );


        -- ====================================================
        -- COUNTRY STATISTICS BY ROLE
        --
        -- All four roles are returned even when a country has
        -- zero users for a particular role.
        -- ====================================================

        SELECT
            COALESCE(
                jsonb_object_agg(
                    role_statistics.role_name,
                    jsonb_build_object(

                        'total_users',
                            role_statistics.total_users,

                        'started',
                            role_statistics.started,

                        'not_started',
                            role_statistics.not_started,

                        'verified',
                            role_statistics.verified,

                        'rejected',
                            role_statistics.rejected,

                        'pending_review',
                            role_statistics.pending_review
                    )
                    ORDER BY
                        role_statistics.role_name
                ),
                '{}'::jsonb
            )

        INTO
            v_country_role_counts

        FROM (

            SELECT

                lower(
                    btrim(
                        role_record.name::text
                    )
                )
                    AS role_name,


                count(
                    user_record.id
                )::integer
                    AS total_users,


                count(
                    kyc_record.id
                )::integer
                    AS started,


                count(
                    user_record.id
                ) FILTER (
                    WHERE
                        kyc_record.id IS NULL
                )::integer
                    AS not_started,


                count(
                    user_record.id
                ) FILTER (
                    WHERE
                        kyc_record.kyc_status::text =
                            'verified'
                )::integer
                    AS verified,


                count(
                    user_record.id
                ) FILTER (
                    WHERE
                        kyc_record.kyc_status::text =
                            'rejected'
                )::integer
                    AS rejected,


                count(
                    user_record.id
                ) FILTER (
                    WHERE
                        kyc_record.id IS NOT NULL

                        AND
                        kyc_record.kyc_status::text
                            NOT IN (
                                'verified',
                                'rejected'
                            )
                )::integer
                    AS pending_review


            FROM
                public.user_role role_record


            LEFT JOIN
                public.users user_record
                ON user_record.role_id =
                   role_record.id

               AND lower(
                       btrim(
                           user_record.country_code
                       )
                   ) =
                       v_country.country_code


            LEFT JOIN
                public.user_kyc kyc_record
                ON kyc_record.user_id =
                   user_record.id
               AND kyc_record.is_current =
                   true


            WHERE
                lower(
                    btrim(
                        role_record.name::text
                    )
                ) IN (
                    'customer',
                    'agent',
                    'vendor',
                    'merchant'
                )


            GROUP BY
                lower(
                    btrim(
                        role_record.name::text
                    )
                )

        ) role_statistics;


        -- ====================================================
        -- ADD COUNTRY
        -- ====================================================

        v_countries :=
            v_countries ||
            jsonb_build_array(
                jsonb_build_object(

                    'country_code',
                        v_country.country_code,

                    'country_name',
                        v_country.country_name,

                    'total_users',
                        v_country_total_users,

                    'started',
                        v_country_started,

                    'not_started',
                        v_country_not_started,

                    'verified',
                        v_country_verified,

                    'rejected',
                        v_country_rejected,

                    'pending_review',
                        v_country_pending_review,

                    'role_counts',
                        v_country_role_counts
                )
            );

    END LOOP;


    -- ========================================================
    -- RESPONSE
    -- ========================================================

    RETURN jsonb_build_object(

        'summary',
            jsonb_build_object(

                'total_users',
                    v_total_users,

                'started',
                    v_started,

                'not_started',
                    v_not_started,

                'verified',
                    v_verified,

                'rejected',
                    v_rejected,

                'pending_review',
                    v_pending_review,

                'role_counts',
                    v_role_counts
            ),


        'countries',
            v_countries
    );

END;
$$;
ALTER FUNCTION "public"."build_my_compliance_dashboard"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."build_my_customer_dashboard"("p_blockchain_balances" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_user public.users%rowtype;

    v_wallet record;
    v_blockchain record;

    v_rate numeric;
    v_balance numeric;
    v_usd_value numeric;

    v_balances jsonb := '{}'::jsonb;
    v_currencies jsonb := '[]'::jsonb;
    v_blockchains jsonb := '[]'::jsonb;

    v_blockchain_codes text[] := ARRAY[]::text[];
    v_blockchain_code text;

    v_chain_balance numeric;
    v_chain_supply numeric;
    v_chain_gas_balance numeric;
    v_chain_usd_value numeric;

    v_total_tokens numeric := 0;
    v_locked_tokens numeric := 0;
    v_available_tokens numeric := 0;

    v_gas_balance text := '0';

    v_principal numeric := 0;
    v_interest numeric := 0;

    v_gold_price numeric := 0;
    v_collateral_value numeric := 0;
    v_ltv numeric := 0;
    v_health text := 'SAFE';

    v_required_collateral numeric := 0;

    v_available_points bigint := 0;
    v_tier_points bigint := 0;
    v_lifetime_earned_points bigint := 0;
    v_loyalty_level text := 'bronze';
    v_loyalty_account_active boolean := false;

    v_active_loans bigint := 0;
    v_active_loan_config_rows bigint := 0;
    v_min_max_active_loans numeric;
    v_max_max_active_loans numeric;
    v_max_active_loans integer;

    v_sva_access_utilisation numeric := 0;
    v_can_access_sva boolean := false;

BEGIN
    /*
     * ==========================================================
     * AUTHENTICATION
     * ==========================================================
     */
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;

    /*
     * ==========================================================
     * RESOLVE AND AUTHORIZE ACTIVE CUSTOMER
     * ==========================================================
     */
    SELECT
        u.*
    INTO
        v_user
    FROM public.users AS u
    JOIN public.user_role AS r
        ON r.id = u.role_id
    WHERE u.id = auth.uid()::text
      AND u.status = 'active'::public."UserStatus"
      AND lower(r.name) = 'customer'
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'CUSTOMER_NOT_AUTHORIZED';
    END IF;

    /*
     * ==========================================================
     * GOLD PRICE
     * ==========================================================
     *
     * Fetch once and reuse for:
     * - Per-blockchain GOLD USD values
     * - Total GOLD wallet USD value
     * - Collateral USD value
     * - Loan GOLD summary
     */
    SELECT
        coalesce(r.rate_to_usd, 0)
    INTO
        v_gold_price
    FROM public.current_rates AS r
    WHERE lower(r.code) = 'gold'
    LIMIT 1;

    v_gold_price :=
        coalesce(v_gold_price, 0);

    IF v_gold_price <= 0 THEN
        RAISE EXCEPTION
            'INVALID_GOLD_RATE';
    END IF;

    /*
     * ==========================================================
     * VALIDATE BLOCKCHAIN BALANCES
     * ==========================================================
     */
    IF p_blockchain_balances IS NULL
       OR jsonb_typeof(p_blockchain_balances) <> 'array'
    THEN
        RAISE EXCEPTION
            'INVALID_BLOCKCHAIN_BALANCES';
    END IF;

    /*
     * ==========================================================
     * AGGREGATE GOLD ACROSS ALL BLOCKCHAINS
     * ==========================================================
     */
    FOR v_blockchain IN
        SELECT
            value AS data
        FROM jsonb_array_elements(
            p_blockchain_balances
        )
    LOOP
        IF jsonb_typeof(v_blockchain.data) <> 'object' THEN
            RAISE EXCEPTION
                'INVALID_BLOCKCHAIN_BALANCE_ENTRY';
        END IF;

        v_blockchain_code :=
            lower(
                btrim(
                    coalesce(
                        v_blockchain.data ->> 'blockchain_code',
                        ''
                    )
                )
            );

        IF v_blockchain_code = '' THEN
            RAISE EXCEPTION
                'MISSING_BLOCKCHAIN_CODE';
        END IF;

        IF v_blockchain_code = ANY(v_blockchain_codes) THEN
            RAISE EXCEPTION
                'DUPLICATE_BLOCKCHAIN_CODE_%',
                upper(v_blockchain_code);
        END IF;

        v_blockchain_codes :=
            array_append(
                v_blockchain_codes,
                v_blockchain_code
            );

        BEGIN
            v_chain_balance :=
                coalesce(
                    nullif(
                        btrim(
                            v_blockchain.data ->> 'balance'
                        ),
                        ''
                    ),
                    '0'
                )::numeric;

            v_chain_supply :=
                coalesce(
                    nullif(
                        btrim(
                            v_blockchain.data ->> 'token_supply'
                        ),
                        ''
                    ),
                    '0'
                )::numeric;

            v_chain_gas_balance :=
                coalesce(
                    nullif(
                        btrim(
                            v_blockchain.data ->> 'gas_balance'
                        ),
                        ''
                    ),
                    '0'
                )::numeric;

        EXCEPTION
            WHEN invalid_text_representation
              OR numeric_value_out_of_range
            THEN
                RAISE EXCEPTION
                    'INVALID_BLOCKCHAIN_NUMERIC_BALANCE_%',
                    upper(v_blockchain_code);
        END;

        IF v_chain_balance < 0
           OR v_chain_supply < 0
           OR v_chain_gas_balance < 0
           OR v_chain_balance = 'NaN'::numeric
           OR v_chain_supply = 'NaN'::numeric
           OR v_chain_gas_balance = 'NaN'::numeric
           OR v_chain_balance = 'Infinity'::numeric
           OR v_chain_supply = 'Infinity'::numeric
           OR v_chain_gas_balance = 'Infinity'::numeric
        THEN
            RAISE EXCEPTION
                'INVALID_BLOCKCHAIN_BALANCE_%',
                upper(v_blockchain_code);
        END IF;

        /*
         * Combined GOLD balance across all blockchains.
         */
        v_total_tokens :=
            v_total_tokens + v_chain_balance;

        /*
         * USD value of GOLD held on this blockchain.
         */
        v_chain_usd_value :=
            v_chain_balance * v_gold_price;

        /*
         * Legacy gas_balance compatibility.
         *
         * Gas balances are chain-specific and must not
         * be summed across different native currencies.
         */
        IF jsonb_array_length(v_blockchains) = 0 THEN
            v_gas_balance :=
                trim_scale(v_chain_gas_balance)::text;
        END IF;

        /*
         * Each entry now matches BlockchainWalletBalance:
         *
         * blockchain_code
         * currency_code
         * balance
         * usd_value
         *
         * Additional blockchain metadata is preserved.
         */
        v_blockchains :=
            v_blockchains ||
            jsonb_build_array(
                jsonb_build_object(
                    'blockchain_code',
                    v_blockchain_code,

                    'currency_code',
                    'gold',

                    'balance',
                    trim_scale(v_chain_balance)::text,

                    'usd_value',
                    to_char(
                        round(v_chain_usd_value, 2),
                        'FM999999999999999999999999990.00'
                    ),

                    'chain_id',
                    v_blockchain.data ->> 'chain_id',

                    'gas_balance',
                    trim_scale(v_chain_gas_balance)::text,

                    'token_supply',
                    trim_scale(v_chain_supply)::text,

                    'native_currency_code',
                    v_blockchain.data ->> 'native_currency_code'
                )
            );
    END LOOP;

    /*
     * ==========================================================
     * CURRENT POOLED COLLATERAL
     * ==========================================================
     */
    SELECT
        coalesce(c.locked_tokens, 0)
    INTO
        v_locked_tokens
    FROM public.collateral AS c
    WHERE c.user_id = v_user.id
    LIMIT 1;

    v_locked_tokens :=
        greatest(
            coalesce(v_locked_tokens, 0),
            0
        );

    v_available_tokens :=
        greatest(
            v_total_tokens - v_locked_tokens,
            0
        );

    /*
     * ==========================================================
     * REQUIRED COLLATERAL
     * ==========================================================
     */
    v_required_collateral :=
        public.calculate_required_collateral(
            v_user.id
        );

    /*
     * ==========================================================
     * WALLET BALANCES
     * ==========================================================
     */
    FOR v_wallet IN
        SELECT
            w.currency_code,
            w.balance
        FROM public.wallet AS w
        WHERE w.user_id = v_user.id
    LOOP
        IF lower(v_wallet.currency_code) = 'usd' THEN

            v_balance :=
                coalesce(v_wallet.balance, 0);

            v_usd_value := v_balance;

        ELSE
            SELECT
                r.rate_to_usd
            INTO
                v_rate
            FROM public.current_rates AS r
            WHERE lower(r.code) =
                  lower(v_wallet.currency_code)
            LIMIT 1;

            IF NOT FOUND
               OR v_rate IS NULL
               OR v_rate = 0
            THEN
                RAISE EXCEPTION
                    'MISSING_RATE_%',
                    upper(v_wallet.currency_code);
            END IF;

            IF lower(v_wallet.currency_code) = 'gold' THEN

                v_balance := v_total_tokens;

                v_usd_value :=
                    v_balance * v_gold_price;

            ELSE
                v_balance :=
                    coalesce(v_wallet.balance, 0);

                v_usd_value :=
                    v_balance / v_rate;
            END IF;
        END IF;

        v_balances :=
            v_balances ||
            jsonb_build_object(
                lower(v_wallet.currency_code),
                jsonb_build_object(
                    'balance',
                    trim_scale(v_balance)::text,

                    'usd_value',
                    to_char(
                        round(v_usd_value, 2),
                        'FM999999999999999999999999990.00'
                    )
                )
            );
    END LOOP;

    /*
     * ==========================================================
     * LOYALTY
     * ==========================================================
     */
    SELECT
        a.available_points,
        a.tier_points,
        a.lifetime_earned_points,
        a.level_code,
        a.is_active
    INTO
        v_available_points,
        v_tier_points,
        v_lifetime_earned_points,
        v_loyalty_level,
        v_loyalty_account_active
    FROM public.loyalty_account AS a
    WHERE a.user_id = v_user.id
    LIMIT 1;

    v_available_points :=
        greatest(
            coalesce(v_available_points, 0),
            0
        );

    v_tier_points :=
        greatest(
            coalesce(v_tier_points, 0),
            0
        );

    v_lifetime_earned_points :=
        greatest(
            coalesce(v_lifetime_earned_points, 0),
            0
        );

    v_loyalty_level :=
        coalesce(
            nullif(btrim(v_loyalty_level), ''),
            'bronze'
        );

    v_loyalty_account_active :=
        coalesce(
            v_loyalty_account_active,
            false
        );

    /*
     * ==========================================================
     * MAXIMUM ACTIVE LOANS CONFIGURATION
     * ==========================================================
     */
    SELECT
        count(*),
        min(c.rate),
        max(c.rate)
    INTO
        v_active_loan_config_rows,
        v_min_max_active_loans,
        v_max_max_active_loans
    FROM public.loan_config AS c
    WHERE c.country_code = v_user.country_code
      AND lower(
          btrim(c.config_type::text)
      ) = 'max_active_loans'
      AND c.is_active = true;

    IF v_active_loan_config_rows = 0
       OR v_min_max_active_loans IS NULL
    THEN
        RAISE EXCEPTION
            'MAX_ACTIVE_LOANS_NOT_CONFIGURED';
    END IF;

    IF v_min_max_active_loans IS DISTINCT FROM
       v_max_max_active_loans
    THEN
        RAISE EXCEPTION
            'MAX_ACTIVE_LOANS_CONFIGURATION_AMBIGUOUS';
    END IF;

    IF v_min_max_active_loans <= 0
       OR trunc(v_min_max_active_loans) <>
          v_min_max_active_loans
    THEN
        RAISE EXCEPTION
            'INVALID_MAX_ACTIVE_LOANS';
    END IF;

    v_max_active_loans :=
        v_min_max_active_loans::integer;

    /*
     * ==========================================================
     * ACTIVE LOAN BALANCES
     * ==========================================================
     */
    SELECT
        count(DISTINCT l.id)::bigint,

        coalesce(
            sum(e.debit_principal),
            0
        ) -
        coalesce(
            sum(e.credit_principal),
            0
        ),

        coalesce(
            sum(e.debit_interest),
            0
        ) -
        coalesce(
            sum(e.credit_interest),
            0
        )
    INTO
        v_active_loans,
        v_principal,
        v_interest
    FROM public.loan AS l
    LEFT JOIN public.loan_entry AS e
        ON e.loan_id = l.id
    WHERE l.user_id = v_user.id
      AND l.status = 'active'::public."LoanStatus";

    v_active_loans :=
        greatest(
            coalesce(v_active_loans, 0),
            0
        );

    v_principal :=
        greatest(
            coalesce(v_principal, 0),
            0
        );

    v_interest :=
        greatest(
            coalesce(v_interest, 0),
            0
        );

    /*
     * ==========================================================
     * SVA ACCESS
     * ==========================================================
     */
    v_sva_access_utilisation :=
        round(
            (
                v_active_loans::numeric /
                v_max_active_loans::numeric
            ) * 100,
            2
        );

    v_can_access_sva :=
        v_sva_access_utilisation < 100;

    /*
     * ==========================================================
     * COLLATERAL VALUE AND LTV
     * ==========================================================
     */
    v_collateral_value :=
        v_locked_tokens * v_gold_price;

    IF v_collateral_value > 0 THEN

        v_ltv :=
            (
                v_principal +
                v_interest
            ) /
            v_collateral_value * 100;

    ELSE
        v_ltv := 0;
    END IF;

    IF v_ltv >= 85 THEN
        v_health := 'LIQUIDATION_RISK';

    ELSIF v_ltv >= 70 THEN
        v_health := 'WARNING';

    ELSE
        v_health := 'SAFE';
    END IF;

    /*
     * ==========================================================
     * SUPPORTED FIAT CURRENCIES
     * ==========================================================
     */
    SELECT
        coalesce(
            jsonb_agg(
                jsonb_build_object(
                    'currency_code',
                    s.currency_code,

                    'symbol',
                    s.symbol,

                    'name',
                    s.name,

                    'is_active',
                    s.is_active,

                    'is_reporting',
                    cc.is_reporting
                )
                ORDER BY s.currency_code
            ),
            '[]'::jsonb
        )
    INTO
        v_currencies
    FROM public.country_currencies AS cc
    JOIN public.supported_currency AS s
        ON lower(s.currency_code) =
           lower(cc.currency_code)
    WHERE cc.country_code = v_user.country_code
      AND cc.is_active = true
      AND s.currency_category =
          'fiat'::public."CurrencyCategory";

    /*
     * ==========================================================
     * RETURN CUSTOMER DASHBOARD
     * ==========================================================
     */
    RETURN jsonb_build_object(
        'wallet',
        jsonb_build_object(
            'wallet_address',
            v_user.wallet_address,

            'token_balance',
            trim_scale(v_total_tokens)::text,

            'gas_balance',
            v_gas_balance,

            'blockchains',
            v_blockchains,

            'balances',
            v_balances,

            'available_tokens',
            trim_scale(v_available_tokens)::text
        ),

        'loyalty',
        jsonb_build_object(
            'available_points',
            v_available_points,

            'tier_points',
            v_tier_points,

            'lifetime_earned_points',
            v_lifetime_earned_points,

            'level_code',
            v_loyalty_level,

            'is_active',
            v_loyalty_account_active
        ),

        'loan',
        jsonb_build_object(
            'principal_outstanding',
            trim_scale(v_principal)::text,

            'interest_outstanding',
            trim_scale(v_interest)::text,

            'collateral_locked',
            trim_scale(v_locked_tokens)::text,

            'required_collateral',
            to_char(
                v_required_collateral,
                'FM999999999999999999999999990.000000'
            ),

            'ltv_percent',
            to_char(
                round(v_ltv, 2),
                'FM999999999999999999999999990.00'
            ),

            'health',
            v_health,

            'sva_access',
            jsonb_build_object(
                'active_loans',
                v_active_loans,

                'max_active_loans',
                v_max_active_loans,

                'utilisation_percent',
                to_char(
                    v_sva_access_utilisation,
                    'FM999999999999999999999999990.00'
                ),

                'can_access',
                v_can_access_sva
            ),

            'gold',
            jsonb_build_object(
                'total',
                jsonb_build_object(
                    'grams',
                    to_char(
                        round(v_total_tokens, 6),
                        'FM999999999999999999999999990.000000'
                    ),

                    'usdValue',
                    to_char(
                        round(
                            v_total_tokens * v_gold_price,
                            2
                        ),
                        'FM999999999999999999999999990.00'
                    )
                ),

                'locked',
                jsonb_build_object(
                    'grams',
                    to_char(
                        round(v_locked_tokens, 6),
                        'FM999999999999999999999999990.000000'
                    ),

                    'usdValue',
                    to_char(
                        round(
                            v_locked_tokens * v_gold_price,
                            2
                        ),
                        'FM999999999999999999999999990.00'
                    )
                ),

                'available',
                jsonb_build_object(
                    'grams',
                    to_char(
                        round(v_available_tokens, 6),
                        'FM999999999999999999999999990.000000'
                    ),

                    'usdValue',
                    to_char(
                        round(
                            v_available_tokens * v_gold_price,
                            2
                        ),
                        'FM999999999999999999999999990.00'
                    )
                )
            )
        ),

        'currencies',
        v_currencies
    );
END;
$$;
ALTER FUNCTION "public"."build_my_customer_dashboard"("p_blockchain_balances" "jsonb") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."build_my_finance_dashboard"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_row record;

    v_currency_code text;
    v_balance numeric;
    v_rate numeric;
    v_usd_value numeric;

    v_balance_result jsonb;

    v_bank jsonb := '{}'::jsonb;
    v_treasury jsonb := '{}'::jsonb;
    v_customer jsonb := '{}'::jsonb;

    v_agent_asset jsonb := '{}'::jsonb;
    v_agent_float jsonb := '{}'::jsonb;

    v_credit_agent_float jsonb :=
        '{}'::jsonb;

    v_credit_agent_cash jsonb :=
        '{}'::jsonb;

    v_currencies jsonb :=
        '[]'::jsonb;
begin
    /*
     * Authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Resolve the authenticated application user and
     * enforce active finance status.
     */
    select u.*
    into v_user
    from public.users u
    join public.user_role r
      on r.id = u.role_id
    where u.id = auth.uid()::text
      and u.status =
          'active'::public."UserStatus"
      and lower(r.name::text) =
          'finance'
    limit 1;

    if not found then
        raise exception using
            errcode = '42501',
            message = 'FINANCE_NOT_AUTHORIZED';
    end if;

    /*
     * Preserve the original behaviour:
     * aggregate across every fiscal year.
     */
    for v_row in
        select
            fe.gl_account_code,

            lower(btrim(fe.currency_code))
                as currency_code,

            abs(
                coalesce(
                    sum(fe.debit),
                    0
                ) -
                coalesce(
                    sum(fe.credit),
                    0
                )
            )::numeric as balance

        from public.financial_entry fe

        where fe.country_code =
              v_user.country_code

          and fe.gl_account_code in (
              '1001000',
              '1002000',
              '2002000',
              '1003000',
              '2001000',
              '1007000',
              '1008000'
          )

        group by
            fe.gl_account_code,
            lower(btrim(fe.currency_code))

        order by
            fe.gl_account_code,
            lower(btrim(fe.currency_code))
    loop
        v_currency_code :=
            v_row.currency_code;

        v_balance :=
            coalesce(v_row.balance, 0);

        /*
         * Convert to USD using the original rules.
         */
        if v_currency_code = 'usd' then
            v_usd_value :=
                v_balance;
        else
            select cr.rate_to_usd
            into v_rate
            from public.current_rates cr
            where lower(btrim(cr.code)) =
                  v_currency_code
            limit 1;

            if not found
               or v_rate is null
               or v_rate = 0
            then
                raise exception
                    'MISSING_RATE_FOR_CURRENCY_%',
                    upper(v_currency_code);
            end if;

            if v_currency_code = 'gold' then
                v_usd_value :=
                    v_balance * v_rate;
            else
                v_usd_value :=
                    v_balance / v_rate;
            end if;
        end if;

        v_balance_result :=
            jsonb_build_object(
                'balance',
                trim_scale(v_balance)::text,

                'usd_value',
                trim_scale(v_usd_value)::text
            );

        case v_row.gl_account_code
            when '1001000' then
                v_bank :=
                    v_bank ||
                    jsonb_build_object(
                        v_currency_code,
                        v_balance_result
                    );

            when '1002000' then
                v_treasury :=
                    v_treasury ||
                    jsonb_build_object(
                        v_currency_code,
                        v_balance_result
                    );

            when '2002000' then
                v_customer :=
                    v_customer ||
                    jsonb_build_object(
                        v_currency_code,
                        v_balance_result
                    );

            when '1003000' then
                v_agent_asset :=
                    v_agent_asset ||
                    jsonb_build_object(
                        v_currency_code,
                        v_balance_result
                    );

            when '2001000' then
                v_agent_float :=
                    v_agent_float ||
                    jsonb_build_object(
                        v_currency_code,
                        v_balance_result
                    );

            /*
             * Corrected mappings.
             */
            when '1007000' then
                v_credit_agent_float :=
                    v_credit_agent_float ||
                    jsonb_build_object(
                        v_currency_code,
                        v_balance_result
                    );

            when '1008000' then
                v_credit_agent_cash :=
                    v_credit_agent_cash ||
                    jsonb_build_object(
                        v_currency_code,
                        v_balance_result
                    );
        end case;
    end loop;

    /*
     * Reuse the existing supported-currency function.
     */
    v_currencies :=
        public.build_country_supported_currencies(
            v_user.country_code
        );

    return jsonb_build_object(
        'bank',
        v_bank,

        'treasury',
        v_treasury,

        'customer',
        v_customer,

        'agentAsset',
        v_agent_asset,

        'agentFloat',
        v_agent_float,

        'creditAgentFloat',
        v_credit_agent_float,

        'creditAgentCash',
        v_credit_agent_cash,

        'currencies',
        v_currencies
    );
end;
$$;
ALTER FUNCTION "public"."build_my_finance_dashboard"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."build_my_merchant_dashboard"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_currencies jsonb;
    v_wallet jsonb;
    v_daily_summary jsonb;

    v_is_credit_agent boolean :=
        false;

    v_credit_agent_balances jsonb :=
        '{}'::jsonb;

    v_credit_account record;

    v_rate numeric;
    v_cash_holding_usd numeric;
    v_receivable_usd numeric;
begin
    /*
     * Authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Resolve the authenticated application user and
     * enforce active merchant status.
     */
    select user_record.*
    into v_user
    from public.users
        user_record
    join public.user_role
        role_record
      on role_record.id =
         user_record.role_id
    where user_record.id =
          auth.uid()::text

      and user_record.status =
          'active'::public."UserStatus"

      and lower(
          role_record.name::text
      ) =
          'merchant'
    limit 1;

    if not found then
        raise exception using
            errcode = '42501',
            message = 'MERCHANT_NOT_AUTHORIZED';
    end if;

    /*
     * Credit-agent status is merchant-wide.
     */
    select exists (
        select 1
        from public.credit_agent_account
            account_record
        where account_record.merchant_id =
              v_user.id

          and account_record.country_code =
              v_user.country_code

          and account_record.is_active =
              true
    )
    into v_is_credit_agent;

    /*
     * Build credit-agent balances by currency.
     *
     * Inactive accounts are included because deactivating
     * a credit agent must not hide an outstanding balance.
     */
    for v_credit_account in
        select
            lower(
                btrim(
                    account_record.currency_code
                )
            ) as currency_code,

            coalesce(
                account_record.cash_holding_balance,
                0
            )::numeric as cash_holding_balance,

            coalesce(
                account_record.receivable_balance,
                0
            )::numeric as receivable_balance,

            account_record.is_active

        from public.credit_agent_account
            account_record

        where account_record.merchant_id =
              v_user.id

          and account_record.country_code =
              v_user.country_code

        order by
            lower(
                btrim(
                    account_record.currency_code
                )
            )
    loop
        /*
         * Apply the same USD conversion used by the
         * existing daily-summary function.
         */
        if v_credit_account.currency_code = 'usd' then
            v_rate :=
                1;

            v_cash_holding_usd :=
                v_credit_account.cash_holding_balance;

            v_receivable_usd :=
                v_credit_account.receivable_balance;
        else
            select rate_record.rate_to_usd
            into v_rate
            from public.current_rates
                rate_record
            where lower(
                btrim(
                    rate_record.code
                )
            ) =
                v_credit_account.currency_code
            limit 1;

            if not found
               or v_rate is null
               or v_rate = 0
            then
                raise exception
                    'MISSING_RATE_%',
                    upper(
                        v_credit_account.currency_code
                    );
            end if;

            v_cash_holding_usd :=
                v_credit_account.cash_holding_balance /
                v_rate;

            v_receivable_usd :=
                v_credit_account.receivable_balance /
                v_rate;
        end if;

        v_credit_agent_balances :=
            v_credit_agent_balances ||
            jsonb_build_object(
                v_credit_account.currency_code,

                jsonb_build_object(
                    'cashOwed',
                    jsonb_build_object(
                        'balance',
                        trim_scale(
                            v_credit_account.cash_holding_balance
                        )::text,

                        'usd_value',
                        to_char(
                            round(
                                v_cash_holding_usd,
                                2
                            ),
                            'FM999999999999999999999999990.00'
                        )
                    ),

                    'receivableBalance',
                    jsonb_build_object(
                        'balance',
                        trim_scale(
                            v_credit_account.receivable_balance
                        )::text,

                        'usd_value',
                        to_char(
                            round(
                                v_receivable_usd,
                                2
                            ),
                            'FM999999999999999999999999990.00'
                        )
                    ),

                    'isActive',
                    v_credit_account.is_active
                )
            );
    end loop;

    /*
     * Existing supported currencies.
     */
    v_currencies :=
        public.build_country_supported_currencies(
            v_user.country_code
        );

    /*
     * Existing merchant wallets.
     */
    v_wallet :=
        jsonb_build_object(
            'merchant',
            jsonb_build_object(
                'balances',
                '{}'::jsonb
            ),

            'agent',
            jsonb_build_object(
                'balances',
                '{}'::jsonb
            )
        )
        ||
        public.build_user_wallet_balance(
            v_user.id
        );

    /*
     * Existing daily summary.
     */
    v_daily_summary :=
        public.build_user_daily_summary(
            v_user.id
        );

    /*
     * The original dashboard fields remain unchanged.
     * Credit-agent information is added separately.
     */
    return jsonb_build_object(
        'isCreditAgent',
        v_is_credit_agent,

        'creditAgent',
        jsonb_build_object(
            'balances',
            v_credit_agent_balances
        ),

        'currencies',
        v_currencies,

        'wallet',
        v_wallet,

        'dailySummary',
        v_daily_summary
    );
end;
$$;
ALTER FUNCTION "public"."build_my_merchant_dashboard"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."build_my_treasury_dashboard"("p_blockchain_balances" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_user public.users%rowtype;

    v_fiscal_year integer;

    v_token_supply numeric := 0;
    v_treasury_gold_balance numeric := 0;
    v_gold_reserve numeric := 0;
    v_reserve_ratio numeric := 0;

    v_blockchain jsonb;
    v_blockchain_code text;
    v_chain_id bigint;
    v_blockchain_supply numeric;
    v_blockchain_balance numeric;
    v_blockchain_gas_balance numeric;
    v_native_currency_code text;

    v_blockchain_balances jsonb := '[]'::jsonb;

    v_wallet record;
    v_balance numeric;
    v_rate numeric;
    v_usd_value numeric;

    v_wallet_balances jsonb := '[]'::jsonb;
    v_currencies jsonb := '[]'::jsonb;
BEGIN
    /*
     * 1. Authenticate Treasury user.
     */
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;

    SELECT u.*
    INTO v_user
    FROM public.users u
    JOIN public.user_role r
        ON r.id = u.role_id
    WHERE u.id = auth.uid()::text
      AND u.status =
          'active'::public."UserStatus"
      AND lower(r.name::text) = 'treasury'
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'TREASURY_NOT_AUTHORIZED';
    END IF;

    /*
     * 2. Validate blockchain balances.
     */
    IF p_blockchain_balances IS NULL
       OR jsonb_typeof(p_blockchain_balances) <> 'array'
    THEN
        RAISE EXCEPTION USING
            MESSAGE = 'INVALID_BLOCKCHAIN_BALANCES';
    END IF;

    /*
     * 3. Process individual blockchain balances.
     *
     * token_supply:
     *   Total token supply on the blockchain.
     *
     * balance:
     *   Treasury wallet gold balance.
     *
     * gas_balance:
     *   Treasury wallet native currency balance.
     */
    FOR v_blockchain IN
        SELECT value
        FROM jsonb_array_elements(
            p_blockchain_balances
        )
    LOOP
        IF jsonb_typeof(v_blockchain) <> 'object' THEN
            RAISE EXCEPTION USING
                MESSAGE = 'INVALID_BLOCKCHAIN_BALANCE_ENTRY';
        END IF;

        v_blockchain_code :=
            nullif(
                lower(
                    btrim(
                        v_blockchain ->> 'blockchain_code'
                    )
                ),
                ''
            );

        v_native_currency_code :=
            nullif(
                upper(
                    btrim(
                        v_blockchain ->> 'native_currency_code'
                    )
                ),
                ''
            );

        IF v_blockchain_code IS NULL
           OR v_native_currency_code IS NULL
           OR nullif(v_blockchain ->> 'chain_id', '') IS NULL
           OR nullif(v_blockchain ->> 'token_supply', '') IS NULL
           OR nullif(v_blockchain ->> 'balance', '') IS NULL
           OR nullif(v_blockchain ->> 'gas_balance', '') IS NULL
        THEN
            RAISE EXCEPTION USING
                MESSAGE = 'INVALID_BLOCKCHAIN_BALANCE_ENTRY';
        END IF;

        BEGIN
            v_chain_id :=
                (v_blockchain ->> 'chain_id')::bigint;

            v_blockchain_supply :=
                (v_blockchain ->> 'token_supply')::numeric;

            v_blockchain_balance :=
                (v_blockchain ->> 'balance')::numeric;

            v_blockchain_gas_balance :=
                (v_blockchain ->> 'gas_balance')::numeric;

        EXCEPTION
            WHEN invalid_text_representation
              OR numeric_value_out_of_range
            THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'INVALID_BLOCKCHAIN_BALANCE_VALUE';
        END;

        IF v_chain_id <= 0
           OR v_blockchain_supply < 0
           OR v_blockchain_balance < 0
           OR v_blockchain_gas_balance < 0
           OR v_blockchain_balance > v_blockchain_supply
        THEN
            RAISE EXCEPTION USING
                MESSAGE = 'INVALID_BLOCKCHAIN_BALANCE_VALUE';
        END IF;

        /*
         * Prevent duplicate blockchain entries.
         */
        IF EXISTS (
            SELECT 1
            FROM jsonb_array_elements(
                v_blockchain_balances
            ) AS existing(value)
            WHERE existing.value ->> 'blockchain_code'
                  = v_blockchain_code
        ) THEN
            RAISE EXCEPTION USING
                MESSAGE = 'DUPLICATE_BLOCKCHAIN_BALANCE';
        END IF;

        /*
         * Accumulate token supply across blockchains.
         */
        v_token_supply :=
            v_token_supply + v_blockchain_supply;

        /*
         * Accumulate Treasury gold balances
         * across blockchains.
         */
        v_treasury_gold_balance :=
            v_treasury_gold_balance +
            v_blockchain_balance;

        /*
         * Keep individual blockchain information.
         */
        v_blockchain_balances :=
            v_blockchain_balances ||
            jsonb_build_array(
                jsonb_build_object(
                    'blockchain_code',
                    v_blockchain_code,

                    'chain_id',
                    v_chain_id,

                    'token_supply',
                    trim_scale(
                        v_blockchain_supply
                    )::text,

                    'balance',
                    trim_scale(
                        v_blockchain_balance
                    )::text,

                    'gas_balance',
                    trim_scale(
                        v_blockchain_gas_balance
                    )::text,

                    'native_currency_code',
                    v_native_currency_code
                )
            );
    END LOOP;

    /*
     * 4. Resolve fiscal year.
     */
    SELECT fp.fiscal_year
    INTO v_fiscal_year
    FROM public.fiscal_period_config fp
    WHERE fp.country_code = 'zw'
      AND fp.opening_date <= current_date
      AND fp.closing_date >= current_date
    ORDER BY
        fp.fiscal_year DESC,
        fp.period DESC
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = 'FISCAL_PERIOD_NOT_FOUND';
    END IF;

    /*
     * 5. Calculate physical gold reserve.
     *
     * Preserve existing accounting calculation.
     */
    SELECT
        coalesce(sum(ae.credit), 0) -
        coalesce(sum(ae.debit), 0)
    INTO v_gold_reserve
    FROM public.asset_entry ae
    WHERE ae.fiscal_year = v_fiscal_year;

    v_gold_reserve :=
        coalesce(v_gold_reserve, 0);

    /*
     * 6. Calculate reserve ratio.
     */
    IF v_token_supply > 0 THEN
        v_reserve_ratio :=
            v_gold_reserve / v_token_supply;
    ELSE
        v_reserve_ratio := 0;
    END IF;

    /*
     * 7. Fetch consolidated Treasury fiat balances.
     *
     * Group by currency only.
     * Do not create separate rows per blockchain.
     *
     * Exclude gold because it is calculated
     * from the blockchain balances.
     */
    FOR v_wallet IN
        SELECT
            lower(btrim(w.currency_code))
                AS currency_code,

            sum(
                coalesce(w.balance, 0)
            )::numeric AS balance

        FROM public.wallet w

        WHERE w.owner_type =
              'treasury'::public."WalletOwnerType"

          AND w.country_code =
              v_user.country_code

          AND lower(btrim(w.currency_code)) <> 'gold'

        GROUP BY
            lower(btrim(w.currency_code))

        ORDER BY
            lower(btrim(w.currency_code))
    LOOP
        v_balance := v_wallet.balance;

        /*
         * Convert fiat balance to USD.
         */
        IF v_wallet.currency_code = 'usd' THEN
            v_usd_value := v_balance;
        ELSE
            SELECT cr.rate_to_usd
            INTO v_rate
            FROM public.current_rates cr
            WHERE lower(btrim(cr.code)) =
                  v_wallet.currency_code
            LIMIT 1;

            IF NOT FOUND
               OR v_rate IS NULL
               OR v_rate <= 0
            THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'MISSING_CURRENCY_RATE';
            END IF;

            v_usd_value :=
                v_balance / v_rate;
        END IF;

        v_wallet_balances :=
            v_wallet_balances ||
            jsonb_build_array(
                jsonb_build_object(
                    'currency_code',
                    v_wallet.currency_code,

                    'balance',
                    trim_scale(v_balance)::text,

                    'usd_value',
                    trim_scale(v_usd_value)::text
                )
            );
    END LOOP;

    /*
     * 8. Add ONE consolidated Treasury gold entry.
     *
     * Gold balance = sum of Treasury gold
     * balances from all supported blockchains.
     *
     * No blockchain_code is included here.
     */
    SELECT cr.rate_to_usd
    INTO v_rate
    FROM public.current_rates cr
    WHERE lower(btrim(cr.code)) = 'gold'
    LIMIT 1;

    IF NOT FOUND
       OR v_rate IS NULL
       OR v_rate <= 0
    THEN
        RAISE EXCEPTION USING
            MESSAGE = 'MISSING_GOLD_RATE';
    END IF;

    v_usd_value :=
        v_treasury_gold_balance * v_rate;

    v_wallet_balances :=
        v_wallet_balances ||
        jsonb_build_array(
            jsonb_build_object(
                'currency_code',
                'gold',

                'balance',
                trim_scale(
                    v_treasury_gold_balance
                )::text,

                'usd_value',
                trim_scale(v_usd_value)::text
            )
        );

    /*
     * 9. Supported currencies.
     */
    v_currencies :=
        public.build_country_supported_currencies(
            v_user.country_code
        );

    /*
     * 10. Return Treasury dashboard.
     */
    RETURN jsonb_build_object(
        'gold_reserve',
        v_gold_reserve,

        'token_supply',
        v_token_supply,

        'treasury_gold_balance',
        v_treasury_gold_balance,

        'reserve_ratio',
        v_reserve_ratio,

        'blockchain_balances',
        v_blockchain_balances,

        'treasury_wallet_balances',
        v_wallet_balances,

        'currencies',
        v_currencies
    );
END;
$$;
ALTER FUNCTION "public"."build_my_treasury_dashboard"("p_blockchain_balances" "jsonb") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."build_my_vendor_dashboard"("p_blockchain_balances" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_user public.users%rowtype;

    v_currencies jsonb;
    v_wallet jsonb;
    v_daily_summary jsonb;
    v_loan_summary jsonb;

    v_blockchain record;
    v_blockchain_balances jsonb := '[]'::jsonb;
    v_blockchain_codes text[] := ARRAY[]::text[];

    v_blockchain_code text;
    v_chain_balance numeric;
    v_chain_supply numeric;
    v_chain_gas_balance numeric;

    v_total_tokens numeric := 0;
    v_locked_tokens numeric := 0;
    v_available_tokens numeric := 0;

    v_principal numeric := 0;
    v_interest numeric := 0;

    v_gold_price numeric := 0;
    v_collateral_value numeric := 0;
    v_ltv numeric := 0;
    v_health text := 'SAFE';

    v_required_collateral numeric := 0;

    v_available_points bigint := 0;
    v_tier_points bigint := 0;
    v_lifetime_earned_points bigint := 0;
    v_loyalty_level text := 'bronze';
    v_loyalty_account_active boolean := false;

    v_active_loans bigint := 0;
    v_active_loan_config_rows bigint := 0;
    v_min_max_active_loans numeric;
    v_max_max_active_loans numeric;
    v_max_active_loans integer;

    v_sva_access_utilisation numeric := 0;
    v_can_access_sva boolean := false;

BEGIN
    /*
     * ==========================================================
     * AUTHENTICATION
     * ==========================================================
     */
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;

    /*
     * ==========================================================
     * RESOLVE AND AUTHORIZE ACTIVE VENDOR
     * ==========================================================
     */
    SELECT
        u.*
    INTO
        v_user
    FROM public.users AS u
    JOIN public.user_role AS r
        ON r.id = u.role_id
    WHERE u.id = auth.uid()::text
      AND u.status = 'active'::public."UserStatus"
      AND lower(r.name::text) = 'vendor'
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'VENDOR_NOT_AUTHORIZED';
    END IF;

    /*
     * ==========================================================
     * CURRENT GOLD PRICE
     * ==========================================================
     */
    SELECT
        coalesce(r.rate_to_usd, 0)
    INTO
        v_gold_price
    FROM public.current_rates AS r
    WHERE lower(btrim(r.code)) = 'gold'
    LIMIT 1;

    v_gold_price :=
        coalesce(v_gold_price, 0);

    IF v_gold_price <= 0 THEN
        RAISE EXCEPTION
            'INVALID_GOLD_RATE';
    END IF;

    /*
     * ==========================================================
     * VALIDATE BLOCKCHAIN BALANCES
     * ==========================================================
     */
    IF p_blockchain_balances IS NULL
       OR jsonb_typeof(p_blockchain_balances) <> 'array'
    THEN
        RAISE EXCEPTION
            'INVALID_BLOCKCHAIN_BALANCES';
    END IF;

    /*
     * ==========================================================
     * MULTI-CHAIN GOLD BALANCES
     * ==========================================================
     */
    FOR v_blockchain IN
        SELECT
            value AS data
        FROM jsonb_array_elements(
            p_blockchain_balances
        )
    LOOP
        IF jsonb_typeof(v_blockchain.data) <> 'object' THEN
            RAISE EXCEPTION
                'INVALID_BLOCKCHAIN_BALANCE_ENTRY';
        END IF;

        v_blockchain_code :=
            lower(
                btrim(
                    coalesce(
                        v_blockchain.data ->> 'blockchain_code',
                        ''
                    )
                )
            );

        IF v_blockchain_code = '' THEN
            RAISE EXCEPTION
                'MISSING_BLOCKCHAIN_CODE';
        END IF;

        IF v_blockchain_code = ANY(v_blockchain_codes) THEN
            RAISE EXCEPTION
                'DUPLICATE_BLOCKCHAIN_CODE_%',
                upper(v_blockchain_code);
        END IF;

        v_blockchain_codes :=
            array_append(
                v_blockchain_codes,
                v_blockchain_code
            );

        BEGIN
            v_chain_balance :=
                coalesce(
                    nullif(
                        btrim(
                            v_blockchain.data ->> 'balance'
                        ),
                        ''
                    ),
                    '0'
                )::numeric;

            v_chain_supply :=
                coalesce(
                    nullif(
                        btrim(
                            v_blockchain.data ->> 'token_supply'
                        ),
                        ''
                    ),
                    '0'
                )::numeric;

            v_chain_gas_balance :=
                coalesce(
                    nullif(
                        btrim(
                            v_blockchain.data ->> 'gas_balance'
                        ),
                        ''
                    ),
                    '0'
                )::numeric;

        EXCEPTION
            WHEN invalid_text_representation
              OR numeric_value_out_of_range
            THEN
                RAISE EXCEPTION
                    'INVALID_BLOCKCHAIN_NUMERIC_BALANCE_%',
                    upper(v_blockchain_code);
        END;

        IF v_chain_balance < 0
           OR v_chain_supply < 0
           OR v_chain_gas_balance < 0
           OR v_chain_balance = 'NaN'::numeric
           OR v_chain_supply = 'NaN'::numeric
           OR v_chain_gas_balance = 'NaN'::numeric
           OR v_chain_balance = 'Infinity'::numeric
           OR v_chain_supply = 'Infinity'::numeric
           OR v_chain_gas_balance = 'Infinity'::numeric
        THEN
            RAISE EXCEPTION
                'INVALID_BLOCKCHAIN_BALANCE_%',
                upper(v_blockchain_code);
        END IF;

        /*
         * Combined GOLD balance across every chain.
         */
        v_total_tokens :=
            v_total_tokens + v_chain_balance;

        /*
         * Build entries compatible with
         * BlockchainWalletBalance.fromJson().
         */
        v_blockchain_balances :=
            v_blockchain_balances ||
            jsonb_build_array(
                jsonb_build_object(
                    'blockchain_code',
                    v_blockchain_code,

                    'currency_code',
                    'gold',

                    'balance',
                    trim_scale(v_chain_balance)::text,

                    'usd_value',
                    to_char(
                        round(
                            v_chain_balance * v_gold_price,
                            2
                        ),
                        'FM999999999999999999999999990.00'
                    ),

                    'chain_id',
                    v_blockchain.data ->> 'chain_id',

                    'gas_balance',
                    trim_scale(v_chain_gas_balance)::text,

                    'token_supply',
                    trim_scale(v_chain_supply)::text,

                    'native_currency_code',
                    v_blockchain.data ->> 'native_currency_code'
                )
            );
    END LOOP;

    /*
     * ==========================================================
     * SUPPORTED CURRENCIES
     * ==========================================================
     */
    v_currencies :=
        public.build_country_supported_currencies(
            v_user.country_code
        );

    /*
     * ==========================================================
     * WALLET CONTAINERS
     * ==========================================================
     *
     * Preserve agent, merchant and customer wallets.
     * Fiat balances remain unchanged.
     */
    v_wallet :=
        jsonb_build_object(
            'agent',
            jsonb_build_object(
                'balances',
                '{}'::jsonb
            ),

            'merchant',
            jsonb_build_object(
                'balances',
                '{}'::jsonb
            ),

            'customer',
            jsonb_build_object(
                'balances',
                '{}'::jsonb
            )
        )
        ||
        public.build_user_wallet_balance(
            v_user.id
        );

    /*
     * ==========================================================
     * DAILY SUMMARY
     * ==========================================================
     */
    v_daily_summary :=
        public.build_user_daily_summary(
            v_user.id
        );

    /*
     * ==========================================================
     * LOYALTY
     * ==========================================================
     */
    SELECT
        a.available_points,
        a.tier_points,
        a.lifetime_earned_points,
        a.level_code,
        a.is_active
    INTO
        v_available_points,
        v_tier_points,
        v_lifetime_earned_points,
        v_loyalty_level,
        v_loyalty_account_active
    FROM public.loyalty_account AS a
    WHERE a.user_id = v_user.id
    LIMIT 1;

    v_available_points :=
        greatest(
            coalesce(v_available_points, 0),
            0
        );

    v_tier_points :=
        greatest(
            coalesce(v_tier_points, 0),
            0
        );

    v_lifetime_earned_points :=
        greatest(
            coalesce(v_lifetime_earned_points, 0),
            0
        );

    v_loyalty_level :=
        coalesce(
            nullif(
                btrim(v_loyalty_level),
                ''
            ),
            'bronze'
        );

    v_loyalty_account_active :=
        coalesce(
            v_loyalty_account_active,
            false
        );

    /*
     * ==========================================================
     * CURRENT POOLED COLLATERAL
     * ==========================================================
     */
    SELECT
        coalesce(c.locked_tokens, 0)
    INTO
        v_locked_tokens
    FROM public.collateral AS c
    WHERE c.user_id = v_user.id
    LIMIT 1;

    v_locked_tokens :=
        greatest(
            coalesce(v_locked_tokens, 0),
            0
        );

    v_available_tokens :=
        greatest(
            v_total_tokens - v_locked_tokens,
            0
        );

    /*
     * ==========================================================
     * REQUIRED COLLATERAL
     * ==========================================================
     */
    v_required_collateral :=
        public.calculate_required_collateral(
            v_user.id
        );

    /*
     * ==========================================================
     * MAXIMUM ACTIVE LOANS CONFIGURATION
     * ==========================================================
     */
    SELECT
        count(*),
        min(c.rate),
        max(c.rate)
    INTO
        v_active_loan_config_rows,
        v_min_max_active_loans,
        v_max_max_active_loans
    FROM public.loan_config AS c
    WHERE c.country_code = v_user.country_code
      AND lower(
          btrim(c.config_type::text)
      ) = 'max_active_loans'
      AND c.is_active = true;

    IF v_active_loan_config_rows = 0
       OR v_min_max_active_loans IS NULL
    THEN
        RAISE EXCEPTION
            'MAX_ACTIVE_LOANS_NOT_CONFIGURED';
    END IF;

    IF v_min_max_active_loans IS DISTINCT FROM
       v_max_max_active_loans
    THEN
        RAISE EXCEPTION
            'MAX_ACTIVE_LOANS_CONFIGURATION_AMBIGUOUS';
    END IF;

    IF v_min_max_active_loans <= 0
       OR trunc(v_min_max_active_loans) <>
          v_min_max_active_loans
    THEN
        RAISE EXCEPTION
            'INVALID_MAX_ACTIVE_LOANS';
    END IF;

    v_max_active_loans :=
        v_min_max_active_loans::integer;

    /*
     * ==========================================================
     * ACTIVE LOAN BALANCES
     * ==========================================================
     */
    SELECT
        count(DISTINCT l.id)::bigint,

        coalesce(
            sum(e.debit_principal),
            0
        ) -
        coalesce(
            sum(e.credit_principal),
            0
        ),

        coalesce(
            sum(e.debit_interest),
            0
        ) -
        coalesce(
            sum(e.credit_interest),
            0
        )
    INTO
        v_active_loans,
        v_principal,
        v_interest
    FROM public.loan AS l
    LEFT JOIN public.loan_entry AS e
        ON e.loan_id = l.id
    WHERE l.user_id = v_user.id
      AND l.status = 'active'::public."LoanStatus";

    v_active_loans :=
        greatest(
            coalesce(v_active_loans, 0),
            0
        );

    v_principal :=
        greatest(
            coalesce(v_principal, 0),
            0
        );

    v_interest :=
        greatest(
            coalesce(v_interest, 0),
            0
        );

    /*
     * ==========================================================
     * SVA ACCESS
     * ==========================================================
     */
    v_sva_access_utilisation :=
        round(
            (
                v_active_loans::numeric /
                v_max_active_loans::numeric
            ) * 100,
            2
        );

    v_can_access_sva :=
        v_sva_access_utilisation < 100;

    /*
     * ==========================================================
     * COLLATERAL VALUE AND LTV
     * ==========================================================
     */
    v_collateral_value :=
        v_locked_tokens * v_gold_price;

    IF v_collateral_value > 0 THEN
        v_ltv :=
            (
                v_principal +
                v_interest
            ) /
            v_collateral_value * 100;
    ELSE
        v_ltv := 0;
    END IF;

    IF v_ltv >= 85 THEN
        v_health := 'LIQUIDATION_RISK';

    ELSIF v_ltv >= 70 THEN
        v_health := 'WARNING';

    ELSE
        v_health := 'SAFE';
    END IF;

    /*
     * ==========================================================
     * LOAN SUMMARY
     * ==========================================================
     */
    v_loan_summary :=
        jsonb_build_object(
            'principal_outstanding',
            trim_scale(v_principal)::text,

            'interest_outstanding',
            trim_scale(v_interest)::text,

            'collateral_locked',
            trim_scale(v_locked_tokens)::text,

            'required_collateral',
            to_char(
                v_required_collateral,
                'FM999999999999999999999999990.000000'
            ),

            'ltv_percent',
            to_char(
                round(v_ltv, 2),
                'FM999999999999999999999999990.00'
            ),

            'health',
            v_health,

            'sva_access',
            jsonb_build_object(
                'active_loans',
                v_active_loans,

                'max_active_loans',
                v_max_active_loans,

                'utilisation_percent',
                to_char(
                    v_sva_access_utilisation,
                    'FM999999999999999999999999990.00'
                ),

                'can_access',
                v_can_access_sva
            ),

            'gold',
            jsonb_build_object(
                'total',
                jsonb_build_object(
                    'grams',
                    to_char(
                        round(v_total_tokens, 6),
                        'FM999999999999999999999999990.000000'
                    ),

                    'usdValue',
                    to_char(
                        round(
                            v_total_tokens * v_gold_price,
                            2
                        ),
                        'FM999999999999999999999999990.00'
                    )
                ),

                'locked',
                jsonb_build_object(
                    'grams',
                    to_char(
                        round(v_locked_tokens, 6),
                        'FM999999999999999999999999990.000000'
                    ),

                    'usdValue',
                    to_char(
                        round(
                            v_locked_tokens * v_gold_price,
                            2
                        ),
                        'FM999999999999999999999999990.00'
                    )
                ),

                'available',
                jsonb_build_object(
                    'grams',
                    to_char(
                        round(v_available_tokens, 6),
                        'FM999999999999999999999999990.000000'
                    ),

                    'usdValue',
                    to_char(
                        round(
                            v_available_tokens * v_gold_price,
                            2
                        ),
                        'FM999999999999999999999999990.00'
                    )
                )
            )
        );

    /*
     * ==========================================================
     * RETURN VENDOR DASHBOARD
     * ==========================================================
     */
    RETURN jsonb_build_object(
        'currencies',
        v_currencies,

        'wallet',
        v_wallet,

        'blockchainBalances',
        v_blockchain_balances,

        'dailySummary',
        v_daily_summary,

        'loyalty',
        jsonb_build_object(
            'available_points',
            v_available_points,

            'tier_points',
            v_tier_points,

            'lifetime_earned_points',
            v_lifetime_earned_points,

            'level_code',
            v_loyalty_level,

            'is_active',
            v_loyalty_account_active
        ),

        'loanSummary',
        v_loan_summary
    );
END;
$$;
ALTER FUNCTION "public"."build_my_vendor_dashboard"("p_blockchain_balances" "jsonb") OWNER TO "postgres";
SET default_tablespace = '';
SET default_table_access_method = "heap";
CREATE TABLE IF NOT EXISTS "public"."transaction_gl_mapping" (
    "id" "text" DEFAULT ("gen_random_uuid"())::"text" NOT NULL,
    "transaction_type" "public"."TransactionType" NOT NULL,
    "component_type" "public"."ComponentType" NOT NULL,
    "debit_gl" "text" NOT NULL,
    "credit_gl" "text" NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_by" "text" DEFAULT 'admin'::"text" NOT NULL,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp(3) without time zone DEFAULT "now"() NOT NULL,
    "updated_by" "text"
);
ALTER TABLE "public"."transaction_gl_mapping" OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."build_posting_components"("p_transaction_type" "public"."TransactionType", "p_principal" numeric, "p_mappings" "public"."transaction_gl_mapping"[], "p_country_code" "text", "p_currency_code" "text", "p_reverse" boolean DEFAULT false) RETURNS "public"."posting_component"[]
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
    v_components
        public.posting_component[] :=
            array[]::public.posting_component[];

    /*
     * pricing_result now contains:
     *
     * fee
     * tax
     * spread
     * commission
     * quantity
     * fiat_received
     * gold_price
     */
    v_pricing
        public.pricing_result :=
            row(
                0,
                0,
                0,
                0,
                0,
                0,
                0
            )::public.pricing_result;

    v_transaction_type
        public."TransactionType";

    v_principal_mode
        public."PrincipalMode";

    v_mapping
        public.transaction_gl_mapping%rowtype;

    v_component
        public.posting_component;

    v_principal_component
        public.posting_component;

    v_new_principal numeric;

    v_charges numeric :=
        0;

    v_raw_amount numeric;

    v_amount numeric;

    v_reverse boolean :=
        coalesce(
            p_reverse,
            false
        );

    /*
     * Debugging information.
     */
    v_stage text :=
        'initialization';

    v_mapping_position integer :=
        0;

    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
    v_error_state text;

begin
    /*
     * ==========================================================
     * INITIAL PRINCIPAL
     * ==========================================================
     */
    v_stage :=
        'round principal';


    v_new_principal :=
        public.round_down(
            p_principal
        );


    /*
     * ==========================================================
     * BASE TRANSACTION TYPE
     * ==========================================================
     */
    v_stage :=
        'resolve base transaction type';


    v_transaction_type :=
        public.get_base_transaction_type(
            p_transaction_type
        );


    /*
     * ==========================================================
     * CALCULATE PRICING
     * ==========================================================
     */
    v_stage :=
        'calculate pricing';


    if not public.is_gold_transaction(
        v_transaction_type
    )
    then
        v_pricing :=
            public.calculate_transaction_pricing(
                p_transaction_type,
                p_principal,
                p_country_code,
                p_currency_code
            );

    else
        /*
         * ======================================================
         * GOLD BUY
         * ======================================================
         */
        if v_transaction_type in (
            'gold_token_buy'::public."TransactionType",
            'gold_token_buy_sub_tx'::public."TransactionType"
        )
        then
            v_stage :=
                'calculate gold buy pricing';


            v_pricing :=
                public.calculate_gold_buy_pricing(
                    v_transaction_type,
                    p_principal,
                    p_country_code,
                    p_currency_code
                );


            /*
             * --------------------------------------------------
             * MAIN GOLD BUY — QUANTITY INPUT
             * --------------------------------------------------
             *
             * When the signed transaction contains:
             *
             *     amount   = gold quantity
             *     currency = gold
             *
             * p_principal is expressed in GOLD.
             *
             * But gold_token_buy is the USD financial
             * transaction.
             *
             * calculate_gold_buy_pricing therefore returns
             * the calculated USD fiatPaid through
             * pricing_result.fiat_received.
             *
             * That USD amount becomes the main posting
             * principal.
             */
            if v_transaction_type =
                   'gold_token_buy'::public."TransactionType"
               and lower(
                   p_currency_code
               ) = 'gold'
            then
                v_stage :=
                    'read gold buy USD principal';


                v_new_principal :=
                    public.round_down(
                        v_pricing.fiat_received
                    );


                if v_new_principal <= 0 then
                    raise exception
                        'INVALID_GOLD_BUY_USD_PRINCIPAL';
                end if;
            end if;


        /*
         * ======================================================
         * GOLD TRANSFER
         * ======================================================
         */
        elsif v_transaction_type =
              'gold_token_transfer'::public."TransactionType"
        then
            v_stage :=
                'calculate gold transfer pricing';


            v_pricing :=
                public.calculate_gold_transfer_pricing(
                    v_transaction_type,
                    p_principal,
                    p_country_code,
                    p_currency_code
                );


        /*
         * ======================================================
         * GOLD SELL
         * ======================================================
         */
        elsif v_transaction_type in (
            'gold_token_sell'::public."TransactionType",
            'gold_token_sell_sub_tx'::public."TransactionType"
        )
        then
            v_stage :=
                'calculate gold sell pricing';


            v_pricing :=
                public.calculate_gold_sell_pricing(
                    v_transaction_type,
                    p_principal,
                    p_country_code,
                    p_currency_code
                );


            v_stage :=
                'read fiat_received';


            v_new_principal :=
                public.round_down(
                    v_pricing.fiat_received
                );
        end if;


        /*
         * ======================================================
         * GOLD SUB-TRANSACTION
         * ======================================================
         *
         * Token sub-transactions are denominated in GOLD.
         *
         * Their principal must therefore always come from
         * the calculated token quantity rather than the
         * original fiat amount.
         */
        v_stage :=
            'check gold sub-transaction';


        if public.is_gold_sub_transaction(
            v_transaction_type
        )
        then
            v_stage :=
                'read pricing quantity';


            v_new_principal :=
                public.round_down(
                    v_pricing.quantity
                );


            if v_new_principal <= 0 then
                raise exception
                    'INVALID_GOLD_TOKEN_PRINCIPAL';
            end if;
        end if;
    end if;


    /*
     * ==========================================================
     * PRINCIPAL MODE
     * ==========================================================
     */
    v_stage :=
        'resolve principal mode';


    v_principal_mode :=
        public.resolve_principal_mode(
            v_transaction_type
        );


    /*
     * ==========================================================
     * BUILD NON-PRINCIPAL COMPONENTS
     * ==========================================================
     */
    v_stage :=
        'iterate mappings';


    foreach v_mapping in array p_mappings
    loop
        v_mapping_position :=
            v_mapping_position + 1;


        v_stage :=
            format(
                'mapping %s: read component_type',
                v_mapping_position
            );


        if v_mapping.component_type =
           'principal'::public."ComponentType"
        then
            continue;
        end if;


        v_stage :=
            format(
                'mapping %s: resolve component amount',
                v_mapping_position
            );


        v_raw_amount :=
            public.resolve_component_amount(
                v_mapping.component_type,
                v_pricing
            );


        v_stage :=
            format(
                'mapping %s: round component amount',
                v_mapping_position
            );


        v_amount :=
            public.round_down(
                v_raw_amount
            );


        /*
         * Zero-value configured components are deliberately
         * skipped.
         *
         * This allows fees and taxes to be disabled by
         * configuring them as zero.
         */
        if v_amount <= 0 then
            continue;
        end if;


        v_stage :=
            format(
                'mapping %s: check self balancing',
                v_mapping_position
            );


        if public.is_self_balancing_component(
            v_mapping.component_type
        )
        then
            v_component :=
                row(
                    v_mapping.component_type,
                    v_amount,
                    v_amount
                )::public.posting_component;


            v_components :=
                array_append(
                    v_components,
                    v_component
                );


            continue;
        end if;


        /*
         * Only non-self-balancing components form part of
         * the amount needed by build_principal_component().
         */
        v_charges :=
            v_charges +
            v_amount;


        v_stage :=
            format(
                'mapping %s: build posting component',
                v_mapping_position
            );


        if v_reverse then
            v_component :=
                row(
                    v_mapping.component_type,
                    v_amount,
                    0
                )::public.posting_component;

        else
            v_component :=
                row(
                    v_mapping.component_type,
                    0,
                    v_amount
                )::public.posting_component;
        end if;


        v_components :=
            array_append(
                v_components,
                v_component
            );
    end loop;


    /*
     * ==========================================================
     * BUILD PRINCIPAL COMPONENT
     * ==========================================================
     */
    v_stage :=
        'build principal component';


    v_principal_component :=
        public.build_principal_component(
            v_new_principal,
            v_charges,
            v_principal_mode,
            v_reverse
        );


    /*
     * ==========================================================
     * PREPEND PRINCIPAL
     * ==========================================================
     */
    v_stage :=
        'prepend principal component';


    v_components :=
        array_prepend(
            v_principal_component,
            v_components
        );


    /*
     * ==========================================================
     * VALIDATE COMPONENTS
     * ==========================================================
     */
    v_stage :=
        'validate components';


    return public.validate_components(
        v_components
    );


exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;


        raise exception using
            errcode =
                coalesce(
                    nullif(
                        v_error_state,
                        ''
                    ),
                    'P0001'
                ),

            message =
                format(
                    'BUILD_POSTING_COMPONENTS_FAILED at [%s]: %s',
                    coalesce(
                        nullif(
                            v_stage,
                            ''
                        ),
                        'unknown'
                    ),
                    coalesce(
                        nullif(
                            v_error_message,
                            ''
                        ),
                        'UNKNOWN_POSTING_COMPONENT_ERROR'
                    )
                ),

            detail =
                coalesce(
                    nullif(
                        concat_ws(
                            E'\n',
                            nullif(
                                v_error_detail,
                                ''
                            ),
                            nullif(
                                v_error_context,
                                ''
                            )
                        ),
                        ''
                    ),
                    'No additional PostgreSQL context'
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    'Check the posting-component stage reported in the error'
                );
end;
$$;
ALTER FUNCTION "public"."build_posting_components"("p_transaction_type" "public"."TransactionType", "p_principal" numeric, "p_mappings" "public"."transaction_gl_mapping"[], "p_country_code" "text", "p_currency_code" "text", "p_reverse" boolean) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."build_principal_component"("p_principal" numeric, "p_charges" numeric, "p_principal_mode" "public"."PrincipalMode", "p_reverse" boolean DEFAULT false) RETURNS "public"."posting_component"
    LANGUAGE "plpgsql" IMMUTABLE STRICT PARALLEL SAFE
    AS $$
declare
    v_debit numeric := p_principal;
    v_credit numeric := p_principal;
begin
    case p_principal_mode
        when 'gross' then
            if p_reverse then
                v_credit :=
                    p_principal + p_charges;
            else
                v_debit :=
                    p_principal + p_charges;
            end if;

        when 'net' then
            if p_reverse then
                v_debit :=
                    p_principal - p_charges;
            else
                v_credit :=
                    p_principal - p_charges;
            end if;

        when 'neutral' then
            v_debit := p_principal;
            v_credit := p_principal;

        when 'charges' then
            v_debit := p_charges;
            v_credit := 0;

        else
            raise exception
                'INVALID_PRINCIPAL_MODE_%',
                p_principal_mode;
    end case;

    if v_debit < 0 or v_credit < 0 then
        raise exception
            'PRINCIPAL_COMPONENT_NEGATIVE_AMOUNT';
    end if;

    return row(
        'principal'::public."ComponentType",
        v_debit,
        v_credit
    )::public.posting_component;
end;
$$;
ALTER FUNCTION "public"."build_principal_component"("p_principal" numeric, "p_charges" numeric, "p_principal_mode" "public"."PrincipalMode", "p_reverse" boolean) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."build_user_daily_summary"("p_user_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
    v_row record;

    v_currency_code text;
    v_amount numeric;
    v_rate numeric;
    v_usd_value numeric;

    v_summary_amount jsonb;

    v_deposits jsonb :=
        '{}'::jsonb;

    v_withdrawals jsonb :=
        '{}'::jsonb;

    v_payments jsonb :=
        '{}'::jsonb;

    v_deposit_counts jsonb :=
        '{}'::jsonb;

    v_withdrawal_counts jsonb :=
        '{}'::jsonb;

    v_payment_counts jsonb :=
        '{}'::jsonb;

    v_start_of_day timestamptz;
    v_start_of_next_day timestamptz;
begin
    if p_user_id is null
       or btrim(p_user_id) = ''
    then
        raise exception
            'USER_ID_IS_REQUIRED';
    end if;

    v_start_of_day :=
        date_trunc(
            'day',
            current_timestamp
        );

    v_start_of_next_day :=
        v_start_of_day +
        interval '1 day';

    /*
     * First classify related transaction types into the
     * same dashboard category.
     *
     * This prevents normal and credit-agent transactions
     * in the same currency from overwriting each other.
     *
     * Daily summary only includes:
     *
     * - agent wallets
     * - merchant wallets
     *
     * Customer wallet activity is excluded.
     */
    for v_row in
        with classified_entries as (
            select
                case
                    when wallet_entry_record.transaction_type in (
                        'cash_deposit'::public."TransactionType",
                        'credit_agent_cash_deposit'::public."TransactionType"
                    )
                    then 'deposit'

                    when wallet_entry_record.transaction_type in (
                        'cash_withdrawal'::public."TransactionType",
                        'credit_agent_cash_withdrawal'::public."TransactionType"
                    )
                    then 'withdrawal'

                    when wallet_entry_record.transaction_type =
                         'merchant_payment'::public."TransactionType"
                    then 'payment'
                end as summary_type,

                lower(
                    btrim(
                        wallet_entry_record.currency_code
                    )
                ) as currency_code,

                wallet_entry_record.document_number,

                coalesce(
                    wallet_entry_record.debit,
                    0
                )::numeric as debit,

                coalesce(
                    wallet_entry_record.credit,
                    0
                )::numeric as credit

            from public.wallet_entry
                wallet_entry_record

            join public.wallet
                wallet_record
              on wallet_record.id =
                 wallet_entry_record.wallet_id

            where wallet_record.user_id =
                  p_user_id

              /*
               * Only operational wallets are included
               * in the daily summary.
               *
               * agent:
               *   deposits and withdrawals
               *
               * merchant:
               *   merchant payments
               *
               * customer:
               *   excluded
               */
              and wallet_record.owner_type in (
                  'agent',
                  'merchant'
              )

              and wallet_entry_record.transaction_type in (
                  'cash_deposit'::public."TransactionType",
                  'credit_agent_cash_deposit'::public."TransactionType",
                  'cash_withdrawal'::public."TransactionType",
                  'credit_agent_cash_withdrawal'::public."TransactionType",
                  'merchant_payment'::public."TransactionType"
              )

              and wallet_entry_record.created_at >=
                  v_start_of_day

              and wallet_entry_record.created_at <
                  v_start_of_next_day
        )

        select
            classified_entry.summary_type,

            classified_entry.currency_code,

            coalesce(
                sum(
                    case
                        when classified_entry.summary_type =
                             'deposit'
                        then classified_entry.debit

                        when classified_entry.summary_type in (
                            'withdrawal',
                            'payment'
                        )
                        then classified_entry.credit

                        else 0
                    end
                ),
                0
            )::numeric as amount,

            count(
                distinct classified_entry.document_number
            )::integer as transaction_count

        from classified_entries
            classified_entry

        where classified_entry.summary_type
              is not null

        group by
            classified_entry.summary_type,
            classified_entry.currency_code

        order by
            classified_entry.summary_type,
            classified_entry.currency_code
    loop
        v_currency_code :=
            v_row.currency_code;

        v_amount :=
            coalesce(
                v_row.amount,
                0
            );

        /*
         * Ignore zero-value groups.
         */
        if v_amount = 0 then
            continue;
        end if;

        /*
         * Convert the transaction total to its USD
         * equivalent using the existing conversion rule.
         */
        if v_currency_code = 'usd' then
            v_usd_value :=
                v_amount;
        else
            v_rate :=
                null;

            select current_rate_record.rate_to_usd
            into v_rate
            from public.current_rates
                current_rate_record
            where lower(
                btrim(
                    current_rate_record.code
                )
            ) =
                v_currency_code
            limit 1;

            if not found
               or v_rate is null
               or v_rate = 0
            then
                raise exception
                    'MISSING_RATE_%',
                    upper(v_currency_code);
            end if;

            /*
             * Preserve the existing daily-summary
             * conversion rule.
             */
            v_usd_value :=
                v_amount /
                v_rate;
        end if;

        v_summary_amount :=
            jsonb_build_object(
                'balance',
                trim_scale(
                    v_amount
                )::text,

                'usd_value',
                to_char(
                    round(
                        v_usd_value,
                        2
                    ),
                    'FM999999999999999999999999990.00'
                )
            );

        case v_row.summary_type
            when 'deposit'
            then
                v_deposits :=
                    v_deposits ||
                    jsonb_build_object(
                        v_currency_code,
                        v_summary_amount
                    );

                v_deposit_counts :=
                    v_deposit_counts ||
                    jsonb_build_object(
                        v_currency_code,
                        v_row.transaction_count
                    );

            when 'withdrawal'
            then
                v_withdrawals :=
                    v_withdrawals ||
                    jsonb_build_object(
                        v_currency_code,
                        v_summary_amount
                    );

                v_withdrawal_counts :=
                    v_withdrawal_counts ||
                    jsonb_build_object(
                        v_currency_code,
                        v_row.transaction_count
                    );

            when 'payment'
            then
                v_payments :=
                    v_payments ||
                    jsonb_build_object(
                        v_currency_code,
                        v_summary_amount
                    );

                v_payment_counts :=
                    v_payment_counts ||
                    jsonb_build_object(
                        v_currency_code,
                        v_row.transaction_count
                    );

            else
                continue;
        end case;
    end loop;

    return jsonb_build_object(
        'deposits',
        v_deposits,

        'withdrawals',
        v_withdrawals,

        'payments',
        v_payments,

        'deposit_count',
        v_deposit_counts,

        'withdrawal_count',
        v_withdrawal_counts,

        'payment_count',
        v_payment_counts
    );
end;
$$;
ALTER FUNCTION "public"."build_user_daily_summary"("p_user_id" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."build_user_wallet_balance"("p_user_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
    v_row record;

    v_owner_type text;
    v_currency_code text;

    v_balance numeric;
    v_rate numeric;
    v_usd_value numeric;

    v_wallet jsonb := '{}'::jsonb;
begin
    if p_user_id is null
       or btrim(p_user_id) = ''
    then
        raise exception 'USER_ID_IS_REQUIRED';
    end if;

    for v_row in
        select
            lower(w.owner_type::text)
                as owner_type,

            lower(btrim(w.currency_code))
                as currency_code,

            coalesce(w.balance, 0)::numeric
                as balance

        from public.wallet w
        where w.user_id = p_user_id

        order by
            w.owner_type,
            w.currency_code
    loop
        v_owner_type :=
            v_row.owner_type;

        v_currency_code :=
            v_row.currency_code;

        v_balance :=
            v_row.balance;

        if v_currency_code = 'usd' then
            v_usd_value :=
                v_balance;
        else
            select cr.rate_to_usd
            into v_rate
            from public.current_rates cr
            where lower(btrim(cr.code)) =
                  v_currency_code
            limit 1;

            if not found
               or v_rate is null
               or v_rate = 0
            then
                raise exception
                    'MISSING_RATE_%',
                    upper(v_currency_code);
            end if;

            if v_currency_code = 'gold' then
                v_usd_value :=
                    v_balance * v_rate;
            else
                v_usd_value :=
                    v_balance / v_rate;
            end if;
        end if;

        /*
         * Create the wallet-owner container when it
         * does not already exist.
         */
        if not v_wallet ? v_owner_type then
            v_wallet :=
                jsonb_set(
                    v_wallet,
                    array[v_owner_type],
                    jsonb_build_object(
                        'balances',
                        '{}'::jsonb
                    ),
                    true
                );
        end if;

        /*
         * Add the currency balance.
         */
        v_wallet :=
            jsonb_set(
                v_wallet,
                array[
                    v_owner_type,
                    'balances',
                    v_currency_code
                ],
                jsonb_build_object(
                    'balance',
                    trim_scale(v_balance)::text,

                    'usd_value',
                    to_char(
                        round(v_usd_value, 2),
                        'FM999999999999999999999999990.00'
                    )
                ),
                true
            );
    end loop;

    return v_wallet;
end;
$$;
ALTER FUNCTION "public"."build_user_wallet_balance"("p_user_id" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."calculate_configured_amount"("p_amount" numeric, "p_config" "public"."amount_config" DEFAULT NULL::"public"."amount_config") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE PARALLEL SAFE
    AS $$
declare
    v_percentage numeric;
    v_fixed numeric;
    v_minimum numeric;
    v_maximum numeric;
    v_fee numeric;
begin
    if p_config is null then
        return 0;
    end if;

    v_percentage :=
        coalesce(p_config.percentage, 0);

    v_fixed :=
        coalesce(p_config.fixed_amount, 0);

    v_minimum :=
        p_config.min_amount;

    v_maximum :=
        p_config.max_amount;

    v_fee :=
        p_amount * v_percentage / 100;

    if v_fixed > 0 then
        v_fee := v_fee + v_fixed;
    end if;

    if v_minimum is not null
       and v_minimum > 0
       and v_fee < v_minimum
    then
        v_fee := v_minimum;
    end if;

    if v_maximum is not null
       and v_maximum > 0
       and v_fee > v_maximum
    then
        v_fee := v_maximum;
    end if;

    return v_fee;
end;
$$;
ALTER FUNCTION "public"."calculate_configured_amount"("p_amount" numeric, "p_config" "public"."amount_config") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."calculate_financial_behavior"("p_user_id" "text", "p_country_code" "text", "p_currency_code" "text", "p_fiscal_year" integer, "p_period" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_country_code text;
    v_currency_code text;

    v_pot public.financial_pot;

    v_period_currency public.financial_behavior;
    v_period_all public.financial_behavior;

    v_year_currency public.financial_behavior;
    v_year_all public.financial_behavior;
BEGIN

    -- ==========================================================
    -- NORMALIZE
    -- ==========================================================

    v_country_code :=
        lower(trim(p_country_code));

    v_currency_code :=
        lower(trim(p_currency_code));


    -- ==========================================================
    -- CURRENT POT DISTRIBUTION
    -- ==========================================================

    SELECT *
    INTO v_pot
    FROM public.calculate_financial_pot_percentages(
        p_user_id,
        v_currency_code,
        p_fiscal_year,
        p_period
    );


    -- ==========================================================
    -- CURRENT PERIOD / CURRENT CURRENCY
    -- ==========================================================

    SELECT *
    INTO v_period_currency
    FROM public.calculate_financial_behavior_snapshot(
        p_user_id,
        v_country_code,
        v_currency_code,
        p_fiscal_year,
        p_period,
        'period'::public.financial_behavior_scope
    );


    -- ==========================================================
    -- CURRENT PERIOD / ALL CURRENCIES
    -- ==========================================================

    SELECT *
    INTO v_period_all
    FROM public.calculate_financial_behavior_snapshot(
        p_user_id,
        v_country_code,
        NULL,
        p_fiscal_year,
        p_period,
        'period'::public.financial_behavior_scope
    );


    -- ==========================================================
    -- FISCAL YEAR / CURRENT CURRENCY
    -- ==========================================================

    SELECT *
    INTO v_year_currency
    FROM public.calculate_financial_behavior_snapshot(
        p_user_id,
        v_country_code,
        v_currency_code,
        p_fiscal_year,
        NULL,
        'fiscal_year'::public.financial_behavior_scope
    );


    -- ==========================================================
    -- FISCAL YEAR / ALL CURRENCIES
    -- ==========================================================

    SELECT *
    INTO v_year_all
    FROM public.calculate_financial_behavior_snapshot(
        p_user_id,
        v_country_code,
        NULL,
        p_fiscal_year,
        NULL,
        'fiscal_year'::public.financial_behavior_scope
    );


    RETURN jsonb_build_object(

        'pot',
            to_jsonb(v_pot),

        'period',
            jsonb_build_object(

                'currency',
                    to_jsonb(v_period_currency),

                'all_currencies',
                    to_jsonb(v_period_all)
            ),

        'fiscal_year',
            jsonb_build_object(

                'currency',
                    to_jsonb(v_year_currency),

                'all_currencies',
                    to_jsonb(v_year_all)
            )
    );

END;
$$;
ALTER FUNCTION "public"."calculate_financial_behavior"("p_user_id" "text", "p_country_code" "text", "p_currency_code" "text", "p_fiscal_year" integer, "p_period" integer) OWNER TO "postgres";
CREATE TABLE IF NOT EXISTS "public"."financial_behavior" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "text" NOT NULL,
    "country_code" "text" NOT NULL,
    "currency_code" "text",
    "fiscal_year" integer NOT NULL,
    "period" integer,
    "scope" "public"."financial_behavior_scope" NOT NULL,
    "behavior" "public"."financial_behavior_type" NOT NULL,
    "deposit_amount_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "withdrawal_amount_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "spending_amount_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "saving_amount_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "investment_amount_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "borrowing_amount_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "repayment_amount_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "withdrawal_percentage" numeric(9,4) DEFAULT 0 NOT NULL,
    "spending_percentage" numeric(9,4) DEFAULT 0 NOT NULL,
    "saving_percentage" numeric(9,4) DEFAULT 0 NOT NULL,
    "investment_percentage" numeric(9,4) DEFAULT 0 NOT NULL,
    "borrowing_percentage" numeric(9,4) DEFAULT 0 NOT NULL,
    "repayment_percentage" numeric(9,4) DEFAULT 0 NOT NULL,
    "rule_id" "uuid",
    "calculated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "shopper_score_percentage" numeric(9,4) DEFAULT 0 NOT NULL,
    "saver_score_percentage" numeric(9,4) DEFAULT 0 NOT NULL,
    "investor_score_percentage" numeric(9,4) DEFAULT 0 NOT NULL,
    "borrower_score_percentage" numeric(9,4) DEFAULT 0 NOT NULL,
    CONSTRAINT "financial_behavior_scope_period_check" CHECK (((("scope" = 'period'::"public"."financial_behavior_scope") AND (("period" >= 1) AND ("period" <= 12))) OR (("scope" = 'fiscal_year'::"public"."financial_behavior_scope") AND ("period" IS NULL))))
);
ALTER TABLE "public"."financial_behavior" OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."calculate_financial_behavior_snapshot"("p_user_id" "text", "p_country_code" "text", "p_currency_code" "text", "p_fiscal_year" integer, "p_period" integer, "p_scope" "public"."financial_behavior_scope") RETURNS "public"."financial_behavior"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_country_code text;
    v_currency_code text;

    v_deposit_amount_usd numeric(20, 6) := 0;

    v_withdrawal_amount_usd numeric(20, 6) := 0;
    v_spending_amount_usd numeric(20, 6) := 0;
    v_saving_amount_usd numeric(20, 6) := 0;
    v_investment_amount_usd numeric(20, 6) := 0;

    v_borrowing_amount_usd numeric(20, 6) := 0;
    v_repayment_amount_usd numeric(20, 6) := 0;

    v_distribution_total_usd numeric(20, 6) := 0;

    v_withdrawal_percentage numeric(9, 4) := 0;
    v_spending_percentage numeric(9, 4) := 0;
    v_saving_percentage numeric(9, 4) := 0;
    v_investment_percentage numeric(9, 4) := 0;
    v_borrowing_percentage numeric(9, 4) := 0;
    v_repayment_percentage numeric(9, 4) := 0;

    v_shopper_score numeric(9, 4) := 0;
    v_saver_score numeric(9, 4) := 0;
    v_investor_score numeric(9, 4) := 0;
    v_borrower_score numeric(9, 4) := 0;

    v_top_score numeric(9, 4) := 0;
    v_second_score numeric(9, 4) := 0;

    v_minimum_percentage numeric := 30;
    v_maximum_lead_percentage numeric := 10;

    v_behavior public.financial_behavior_type :=
        'neutral'::public.financial_behavior_type;

    v_rule_id uuid;

    v_result public.financial_behavior;
BEGIN

    -- ==========================================================
    -- VALIDATION / NORMALIZATION
    -- ==========================================================

    IF p_user_id IS NULL
       OR trim(p_user_id) = '' THEN
        RAISE EXCEPTION
            'FINANCIAL_BEHAVIOR_USER_REQUIRED';
    END IF;

    IF p_country_code IS NULL
       OR trim(p_country_code) = '' THEN
        RAISE EXCEPTION
            'FINANCIAL_BEHAVIOR_COUNTRY_REQUIRED';
    END IF;

    IF p_fiscal_year IS NULL THEN
        RAISE EXCEPTION
            'FINANCIAL_BEHAVIOR_FISCAL_YEAR_REQUIRED';
    END IF;

    IF p_scope IS NULL THEN
        RAISE EXCEPTION
            'FINANCIAL_BEHAVIOR_SCOPE_REQUIRED';
    END IF;

    IF p_scope =
        'period'::public.financial_behavior_scope
       AND (
            p_period IS NULL
            OR p_period < 1
            OR p_period > 12
       )
    THEN
        RAISE EXCEPTION
            'FINANCIAL_BEHAVIOR_INVALID_PERIOD';
    END IF;

    IF p_scope =
        'fiscal_year'::public.financial_behavior_scope
       AND p_period IS NOT NULL
    THEN
        RAISE EXCEPTION
            'FINANCIAL_BEHAVIOR_YEAR_PERIOD_MUST_BE_NULL';
    END IF;

    v_country_code :=
        lower(trim(p_country_code));

    v_currency_code :=
        CASE
            WHEN p_currency_code IS NULL
                THEN NULL
            ELSE lower(trim(p_currency_code))
        END;


    -- ==========================================================
    -- READ RULE CONFIGURATION
    -- ==========================================================

    SELECT
        COALESCE(
            (r.conditions ->> 'minimum_percentage')::numeric,
            30
        )
    INTO
        v_minimum_percentage
    FROM public.financial_behavior_rule AS r
    WHERE r.code = 'SAVER_V1'
      AND r.is_active = true
    LIMIT 1;

    v_minimum_percentage :=
        COALESCE(
            v_minimum_percentage,
            30
        );


    SELECT
        COALESCE(
            (
                r.conditions
                ->> 'maximum_lead_percentage'
            )::numeric,
            10
        )
    INTO
        v_maximum_lead_percentage
    FROM public.financial_behavior_rule AS r
    WHERE r.code = 'BALANCED_V1'
      AND r.is_active = true
    LIMIT 1;

    v_maximum_lead_percentage :=
        COALESCE(
            v_maximum_lead_percentage,
            10
        );


    -- ==========================================================
    -- ACTIVITY VALUES
    --
    -- amount_usd keeps the business/activity amount.
    --
    -- Cash-flow behavior uses cash_amount_usd.
    --
    -- Seed events are explicitly excluded.
    -- ==========================================================

    SELECT

        -- ------------------------------------------------------
        -- Deposit / source information
        -- ------------------------------------------------------

        COALESCE(
            SUM(
                CASE
                    WHEN e.activity_type =
                        'deposit'::public.financial_activity_type
                    THEN COALESCE(
                        NULLIF(e.cash_amount_usd, 0),
                        e.amount_usd,
                        0
                    )

                    ELSE 0
                END
            ),
            0
        ),


        -- ------------------------------------------------------
        -- Withdrawal
        -- ------------------------------------------------------

        COALESCE(
            SUM(
                CASE
                    WHEN e.activity_type =
                        'withdrawal'::public.financial_activity_type
                    THEN COALESCE(
                        NULLIF(e.cash_amount_usd, 0),
                        e.amount_usd,
                        0
                    )

                    ELSE 0
                END
            ),
            0
        ),


        -- ------------------------------------------------------
        -- Spending
        -- ------------------------------------------------------

        COALESCE(
            SUM(
                CASE
                    WHEN e.activity_type =
                        'spending'::public.financial_activity_type
                    THEN COALESCE(
                        NULLIF(e.cash_amount_usd, 0),
                        e.amount_usd,
                        0
                    )

                    ELSE 0
                END
            ),
            0
        ),


        -- ------------------------------------------------------
        -- Investment purchases
        -- ------------------------------------------------------

        COALESCE(
            SUM(
                CASE
                    WHEN e.activity_type =
                        'investment_buy'::public.financial_activity_type
                    THEN COALESCE(
                        NULLIF(e.cash_amount_usd, 0),
                        NULLIF(e.investment_cost_usd, 0),
                        e.amount_usd,
                        0
                    )

                    ELSE 0
                END
            ),
            0
        ),


        -- ------------------------------------------------------
        -- Loan disbursement
        --
        -- Retained as reporting data only.
        -- It is NOT a behavior score.
        -- ------------------------------------------------------

        COALESCE(
            SUM(
                CASE
                    WHEN e.activity_type =
                        'loan_disbursement'::public.financial_activity_type
                    THEN COALESCE(
                        e.amount_usd,
                        0
                    )

                    ELSE 0
                END
            ),
            0
        ),


        -- ------------------------------------------------------
        -- Repayment
        -- ------------------------------------------------------

        COALESCE(
            SUM(
                CASE
                    WHEN e.activity_type =
                        'loan_repayment'::public.financial_activity_type
                    THEN COALESCE(
                        NULLIF(e.cash_amount_usd, 0),
                        NULLIF(e.amount_usd, 0),
                        COALESCE(
                            e.principal_amount_usd,
                            0
                        )
                        +
                        COALESCE(
                            e.interest_amount_usd,
                            0
                        ),
                        0
                    )

                    ELSE 0
                END
            ),
            0
        )

    INTO
        v_deposit_amount_usd,
        v_withdrawal_amount_usd,
        v_spending_amount_usd,
        v_investment_amount_usd,
        v_borrowing_amount_usd,
        v_repayment_amount_usd

    FROM public.financial_pot_event AS e

    WHERE e.user_id = p_user_id

      AND e.country_code = v_country_code

      AND e.fiscal_year = p_fiscal_year

      AND (
            v_currency_code IS NULL
            OR e.currency_code = v_currency_code
      )

      AND (
            (
                p_scope =
                    'period'::public.financial_behavior_scope

                AND e.period =
                    p_period
            )

            OR

            (
                p_scope =
                    'fiscal_year'::public.financial_behavior_scope
            )
      )

      AND lower(e.transaction_type)
          NOT LIKE 'initial\_%' ESCAPE '\';


    -- ==========================================================
    -- CLOSING SAVINGS
    --
    -- Period:
    -- current period closing position.
    --
    -- Fiscal year:
    -- latest closing position for each currency, not a SUM of
    -- every period's closing balance.
    -- ==========================================================

    IF p_scope =
        'period'::public.financial_behavior_scope
    THEN

        SELECT
            COALESCE(
                SUM(fp.closing_savings_usd),
                0
            )
        INTO
            v_saving_amount_usd
        FROM public.financial_pot AS fp
        WHERE fp.user_id = p_user_id
          AND fp.fiscal_year = p_fiscal_year
          AND fp.period = p_period

          AND (
                v_currency_code IS NULL
                OR fp.currency_code =
                    v_currency_code
          );

    ELSE

        WITH ranked_pots AS (
            SELECT
                fp.currency_code,
                fp.closing_savings_usd,

                ROW_NUMBER() OVER (
                    PARTITION BY fp.currency_code
                    ORDER BY fp.period DESC
                ) AS row_number

            FROM public.financial_pot AS fp

            WHERE fp.user_id = p_user_id
              AND fp.fiscal_year = p_fiscal_year

              AND (
                    v_currency_code IS NULL
                    OR fp.currency_code =
                        v_currency_code
              )
        )

        SELECT
            COALESCE(
                SUM(rp.closing_savings_usd),
                0
            )
        INTO
            v_saving_amount_usd
        FROM ranked_pots AS rp
        WHERE rp.row_number = 1;

    END IF;


    -- ==========================================================
    -- DISTRIBUTION TOTAL
    --
    -- Withdrawal has no identity, but remains in denominator.
    -- ==========================================================

    v_distribution_total_usd :=
          v_withdrawal_amount_usd
        + v_spending_amount_usd
        + v_investment_amount_usd
        + v_repayment_amount_usd
        + v_saving_amount_usd;


    -- ==========================================================
    -- DISTRIBUTION PERCENTAGES
    -- ==========================================================

    IF v_distribution_total_usd > 0 THEN

        v_withdrawal_percentage :=
            round(
                (
                    v_withdrawal_amount_usd
                    /
                    v_distribution_total_usd
                    *
                    100
                )::numeric,
                4
            );

        v_spending_percentage :=
            round(
                (
                    v_spending_amount_usd
                    /
                    v_distribution_total_usd
                    *
                    100
                )::numeric,
                4
            );

        v_saving_percentage :=
            round(
                (
                    v_saving_amount_usd
                    /
                    v_distribution_total_usd
                    *
                    100
                )::numeric,
                4
            );

        v_investment_percentage :=
            round(
                (
                    v_investment_amount_usd
                    /
                    v_distribution_total_usd
                    *
                    100
                )::numeric,
                4
            );

        v_repayment_percentage :=
            round(
                (
                    v_repayment_amount_usd
                    /
                    v_distribution_total_usd
                    *
                    100
                )::numeric,
                4
            );

    END IF;


    -- ==========================================================
    -- IDENTITY SCORES
    --
    -- The identity values intentionally use the SAME percentages
    -- displayed in the allocation doughnut.
    --
    -- Withdrawal is therefore part of 100%, but not assigned an
    -- identity.
    -- ==========================================================

    v_shopper_score :=
        v_spending_percentage;

    v_saver_score :=
        v_saving_percentage;

    v_investor_score :=
        v_investment_percentage;

    v_borrower_score :=
        v_repayment_percentage;

    v_borrowing_percentage :=
        0;


    -- ==========================================================
    -- TOP TWO IDENTITY SCORES
    -- ==========================================================

    SELECT
        ranked.score
    INTO
        v_top_score
    FROM (
        VALUES
            (v_shopper_score),
            (v_saver_score),
            (v_investor_score),
            (v_borrower_score)
    ) AS ranked(score)
    ORDER BY ranked.score DESC
    LIMIT 1;


    SELECT
        ranked.score
    INTO
        v_second_score
    FROM (
        VALUES
            (v_shopper_score),
            (v_saver_score),
            (v_investor_score),
            (v_borrower_score)
    ) AS ranked(score)
    ORDER BY ranked.score DESC
    OFFSET 1
    LIMIT 1;


    v_top_score :=
        COALESCE(
            v_top_score,
            0
        );

    v_second_score :=
        COALESCE(
            v_second_score,
            0
        );


    -- ==========================================================
    -- CLASSIFICATION
    -- ==========================================================

    IF v_distribution_total_usd <= 0
       OR v_top_score <= 0
    THEN

        v_behavior :=
            'neutral'::public.financial_behavior_type;

    ELSIF v_top_score < v_minimum_percentage
    THEN

        v_behavior :=
            'neutral'::public.financial_behavior_type;

    ELSIF
        v_second_score > 0

        AND (
            v_top_score
            -
            v_second_score
        ) <= v_maximum_lead_percentage
    THEN

        v_behavior :=
            'balanced'::public.financial_behavior_type;

    ELSIF v_saver_score = v_top_score
    THEN

        v_behavior :=
            'saver'::public.financial_behavior_type;

    ELSIF v_investor_score = v_top_score
    THEN

        v_behavior :=
            'investor'::public.financial_behavior_type;

    ELSIF v_shopper_score = v_top_score
    THEN

        v_behavior :=
            'shopper'::public.financial_behavior_type;

    ELSE

        v_behavior :=
            'borrower'::public.financial_behavior_type;

    END IF;


    -- ==========================================================
    -- RULE
    -- ==========================================================

    SELECT
        r.id
    INTO
        v_rule_id
    FROM public.financial_behavior_rule AS r
    WHERE r.is_active = true
      AND r.behavior = v_behavior
    ORDER BY
        r.priority DESC,
        r.created_at ASC
    LIMIT 1;


    -- ==========================================================
    -- UPDATE EXISTING SNAPSHOT
    --
    -- Partial unique indexes cannot safely be targeted by one
    -- generic ON CONFLICT clause, so UPDATE + INSERT is clearer.
    -- ==========================================================

    UPDATE public.financial_behavior
    SET
        country_code =
            v_country_code,

        behavior =
            v_behavior,

        deposit_amount_usd =
            v_deposit_amount_usd,

        withdrawal_amount_usd =
            v_withdrawal_amount_usd,

        spending_amount_usd =
            v_spending_amount_usd,

        saving_amount_usd =
            v_saving_amount_usd,

        investment_amount_usd =
            v_investment_amount_usd,

        borrowing_amount_usd =
            v_borrowing_amount_usd,

        repayment_amount_usd =
            v_repayment_amount_usd,

        withdrawal_percentage =
            v_withdrawal_percentage,

        spending_percentage =
            v_spending_percentage,

        saving_percentage =
            v_saving_percentage,

        investment_percentage =
            v_investment_percentage,

        borrowing_percentage =
            0,

        repayment_percentage =
            v_repayment_percentage,

        shopper_score_percentage =
            v_shopper_score,

        saver_score_percentage =
            v_saver_score,

        investor_score_percentage =
            v_investor_score,

        borrower_score_percentage =
            v_borrower_score,

        rule_id =
            v_rule_id,

        calculated_at =
            now(),

        updated_at =
            now()

    WHERE user_id =
            p_user_id

      AND fiscal_year =
            p_fiscal_year

      AND scope =
            p_scope

      AND (
            (
                p_scope =
                    'period'::public.financial_behavior_scope

                AND period =
                    p_period
            )

            OR

            (
                p_scope =
                    'fiscal_year'::public.financial_behavior_scope

                AND period IS NULL
            )
      )

      AND (
            (
                v_currency_code IS NULL
                AND currency_code IS NULL
            )

            OR

            currency_code =
                v_currency_code
      )

    RETURNING *
    INTO v_result;


    -- ==========================================================
    -- INSERT IF MISSING
    -- ==========================================================

    IF NOT FOUND THEN

        INSERT INTO public.financial_behavior (
            user_id,
            country_code,
            currency_code,

            fiscal_year,
            period,
            scope,

            behavior,

            deposit_amount_usd,
            withdrawal_amount_usd,
            spending_amount_usd,
            saving_amount_usd,
            investment_amount_usd,
            borrowing_amount_usd,
            repayment_amount_usd,

            withdrawal_percentage,
            spending_percentage,
            saving_percentage,
            investment_percentage,
            borrowing_percentage,
            repayment_percentage,

            shopper_score_percentage,
            saver_score_percentage,
            investor_score_percentage,
            borrower_score_percentage,

            rule_id,

            calculated_at,
            created_at,
            updated_at
        )
        VALUES (
            p_user_id,
            v_country_code,
            v_currency_code,

            p_fiscal_year,

            CASE
                WHEN p_scope =
                    'period'::public.financial_behavior_scope
                THEN p_period

                ELSE NULL
            END,

            p_scope,

            v_behavior,

            v_deposit_amount_usd,
            v_withdrawal_amount_usd,
            v_spending_amount_usd,
            v_saving_amount_usd,
            v_investment_amount_usd,
            v_borrowing_amount_usd,
            v_repayment_amount_usd,

            v_withdrawal_percentage,
            v_spending_percentage,
            v_saving_percentage,
            v_investment_percentage,
            0,
            v_repayment_percentage,

            v_shopper_score,
            v_saver_score,
            v_investor_score,
            v_borrower_score,

            v_rule_id,

            now(),
            now(),
            now()
        )

        RETURNING *
        INTO v_result;

    END IF;


    RETURN v_result;

END;
$$;
ALTER FUNCTION "public"."calculate_financial_behavior_snapshot"("p_user_id" "text", "p_country_code" "text", "p_currency_code" "text", "p_fiscal_year" integer, "p_period" integer, "p_scope" "public"."financial_behavior_scope") OWNER TO "postgres";
CREATE TABLE IF NOT EXISTS "public"."financial_pot" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "text" NOT NULL,
    "country_code" "text" NOT NULL,
    "currency_code" "text" NOT NULL,
    "fiscal_year" integer NOT NULL,
    "period" integer NOT NULL,
    "deposit_amount" numeric(20,6) DEFAULT 0 NOT NULL,
    "deposit_amount_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "withdrawal_amount" numeric(20,6) DEFAULT 0 NOT NULL,
    "withdrawal_amount_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "spending_amount" numeric(20,6) DEFAULT 0 NOT NULL,
    "spending_amount_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "opening_savings" numeric(20,6) DEFAULT 0 NOT NULL,
    "savings_inflow" numeric(20,6) DEFAULT 0 NOT NULL,
    "savings_outflow" numeric(20,6) DEFAULT 0 NOT NULL,
    "closing_savings" numeric(20,6) DEFAULT 0 NOT NULL,
    "opening_savings_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "savings_inflow_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "savings_outflow_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "closing_savings_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "saving_amount" numeric(20,6) DEFAULT 0 NOT NULL,
    "saving_amount_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "investment_purchase_amount" numeric(20,6) DEFAULT 0 NOT NULL,
    "investment_purchase_amount_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "investment_sale_amount" numeric(20,6) DEFAULT 0 NOT NULL,
    "investment_sale_amount_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "gold_purchased" numeric(20,6) DEFAULT 0 NOT NULL,
    "gold_sold" numeric(20,6) DEFAULT 0 NOT NULL,
    "gold_transferred_in" numeric(20,6) DEFAULT 0 NOT NULL,
    "gold_transferred_out" numeric(20,6) DEFAULT 0 NOT NULL,
    "opening_gold_quantity" numeric(20,6) DEFAULT 0 NOT NULL,
    "closing_gold_quantity" numeric(20,6) DEFAULT 0 NOT NULL,
    "opening_investment_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "investment_inflow_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "investment_outflow_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "closing_investment_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "opening_loan_balance" numeric(20,6) DEFAULT 0 NOT NULL,
    "loan_disbursed_amount" numeric(20,6) DEFAULT 0 NOT NULL,
    "loan_repayment_amount" numeric(20,6) DEFAULT 0 NOT NULL,
    "loan_interest_accrued" numeric(20,6) DEFAULT 0 NOT NULL,
    "closing_loan_balance" numeric(20,6) DEFAULT 0 NOT NULL,
    "opening_loan_balance_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "loan_disbursed_amount_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "loan_repayment_amount_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "loan_interest_accrued_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "closing_loan_balance_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "loan_principal_repaid" numeric(20,6) DEFAULT 0 NOT NULL,
    "loan_interest_repaid" numeric(20,6) DEFAULT 0 NOT NULL,
    "loan_principal_repaid_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "loan_interest_repaid_usd" numeric(20,6) DEFAULT 0 NOT NULL,
    "withdrawal_percentage" numeric(9,4) DEFAULT 0 NOT NULL,
    "spending_percentage" numeric(9,4) DEFAULT 0 NOT NULL,
    "saving_percentage" numeric(9,4) DEFAULT 0 NOT NULL,
    "investment_percentage" numeric(9,4) DEFAULT 0 NOT NULL,
    "borrowing_percentage" numeric(9,4) DEFAULT 0 NOT NULL,
    "repayment_percentage" numeric(9,4) DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "cash_in_amount" numeric DEFAULT 0 NOT NULL,
    "cash_in_amount_usd" numeric DEFAULT 0 NOT NULL,
    "transfer_in_amount" numeric DEFAULT 0 NOT NULL,
    "transfer_in_amount_usd" numeric DEFAULT 0 NOT NULL,
    "investment_proceeds_amount" numeric DEFAULT 0 NOT NULL,
    "investment_proceeds_amount_usd" numeric DEFAULT 0 NOT NULL,
    "withdrawal_cash_amount" numeric DEFAULT 0 NOT NULL,
    "withdrawal_cash_amount_usd" numeric DEFAULT 0 NOT NULL,
    "spending_cash_amount" numeric DEFAULT 0 NOT NULL,
    "spending_cash_amount_usd" numeric DEFAULT 0 NOT NULL,
    "investment_cash_amount" numeric DEFAULT 0 NOT NULL,
    "investment_cash_amount_usd" numeric DEFAULT 0 NOT NULL,
    "repayment_cash_amount" numeric DEFAULT 0 NOT NULL,
    "repayment_cash_amount_usd" numeric DEFAULT 0 NOT NULL,
    CONSTRAINT "financial_pot_non_negative_activity_check" CHECK ((("deposit_amount" >= (0)::numeric) AND ("deposit_amount_usd" >= (0)::numeric) AND ("withdrawal_amount" >= (0)::numeric) AND ("withdrawal_amount_usd" >= (0)::numeric) AND ("spending_amount" >= (0)::numeric) AND ("spending_amount_usd" >= (0)::numeric) AND ("savings_inflow" >= (0)::numeric) AND ("savings_inflow_usd" >= (0)::numeric) AND ("savings_outflow" >= (0)::numeric) AND ("savings_outflow_usd" >= (0)::numeric) AND ("saving_amount" >= (0)::numeric) AND ("saving_amount_usd" >= (0)::numeric) AND ("investment_purchase_amount" >= (0)::numeric) AND ("investment_purchase_amount_usd" >= (0)::numeric) AND ("investment_sale_amount" >= (0)::numeric) AND ("investment_sale_amount_usd" >= (0)::numeric) AND ("gold_purchased" >= (0)::numeric) AND ("gold_sold" >= (0)::numeric) AND ("gold_transferred_in" >= (0)::numeric) AND ("gold_transferred_out" >= (0)::numeric) AND ("investment_inflow_usd" >= (0)::numeric) AND ("investment_outflow_usd" >= (0)::numeric) AND ("loan_disbursed_amount" >= (0)::numeric) AND ("loan_disbursed_amount_usd" >= (0)::numeric) AND ("loan_repayment_amount" >= (0)::numeric) AND ("loan_repayment_amount_usd" >= (0)::numeric) AND ("loan_interest_accrued" >= (0)::numeric) AND ("loan_interest_accrued_usd" >= (0)::numeric) AND ("loan_principal_repaid" >= (0)::numeric) AND ("loan_principal_repaid_usd" >= (0)::numeric) AND ("loan_interest_repaid" >= (0)::numeric) AND ("loan_interest_repaid_usd" >= (0)::numeric))),
    CONSTRAINT "financial_pot_period_check" CHECK ((("period" >= 1) AND ("period" <= 12)))
);
ALTER TABLE "public"."financial_pot" OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."calculate_financial_pot_percentages"("p_user_id" "text", "p_currency_code" "text", "p_fiscal_year" integer, "p_period" integer) RETURNS "public"."financial_pot"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_currency_code text;

    v_withdrawal_usd numeric(20, 6) := 0;
    v_spending_usd numeric(20, 6) := 0;
    v_investment_usd numeric(20, 6) := 0;
    v_repayment_usd numeric(20, 6) := 0;
    v_savings_usd numeric(20, 6) := 0;

    v_distribution_total_usd numeric(20, 6) := 0;

    v_withdrawal_percentage numeric(9, 4) := 0;
    v_spending_percentage numeric(9, 4) := 0;
    v_saving_percentage numeric(9, 4) := 0;
    v_investment_percentage numeric(9, 4) := 0;
    v_repayment_percentage numeric(9, 4) := 0;

    v_result public.financial_pot;
BEGIN

    -- ==========================================================
    -- VALIDATION
    -- ==========================================================

    IF p_user_id IS NULL
       OR trim(p_user_id) = '' THEN
        RAISE EXCEPTION
            'FINANCIAL_POT_USER_REQUIRED';
    END IF;

    IF p_currency_code IS NULL
       OR trim(p_currency_code) = '' THEN
        RAISE EXCEPTION
            'FINANCIAL_POT_CURRENCY_REQUIRED';
    END IF;

    IF p_fiscal_year IS NULL THEN
        RAISE EXCEPTION
            'FINANCIAL_POT_FISCAL_YEAR_REQUIRED';
    END IF;

    IF p_period IS NULL
       OR p_period < 1
       OR p_period > 12 THEN
        RAISE EXCEPTION
            'FINANCIAL_POT_INVALID_PERIOD';
    END IF;

    v_currency_code :=
        lower(trim(p_currency_code));


    -- ==========================================================
    -- CURRENT SAVINGS POSITION
    -- ==========================================================

    SELECT
        COALESCE(
            fp.closing_savings_usd,
            0
        )
    INTO
        v_savings_usd
    FROM public.financial_pot AS fp
    WHERE fp.user_id = p_user_id
      AND fp.currency_code = v_currency_code
      AND fp.fiscal_year = p_fiscal_year
      AND fp.period = p_period;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'FINANCIAL_POT_NOT_FOUND';
    END IF;


    -- ==========================================================
    -- ACTUAL DISTRIBUTION CASH MOVEMENTS
    --
    -- Seed events represent opening state and must never count
    -- as current-period behavior.
    -- ==========================================================

    SELECT

        COALESCE(
            SUM(
                CASE
                    WHEN e.activity_type =
                        'withdrawal'::public.financial_activity_type
                    THEN COALESCE(
                        NULLIF(e.cash_amount_usd, 0),
                        e.amount_usd,
                        0
                    )

                    ELSE 0
                END
            ),
            0
        ),

        COALESCE(
            SUM(
                CASE
                    WHEN e.activity_type =
                        'spending'::public.financial_activity_type
                    THEN COALESCE(
                        NULLIF(e.cash_amount_usd, 0),
                        e.amount_usd,
                        0
                    )

                    ELSE 0
                END
            ),
            0
        ),

        COALESCE(
            SUM(
                CASE
                    WHEN e.activity_type =
                        'investment_buy'::public.financial_activity_type
                    THEN COALESCE(
                        NULLIF(e.cash_amount_usd, 0),
                        NULLIF(e.investment_cost_usd, 0),
                        e.amount_usd,
                        0
                    )

                    ELSE 0
                END
            ),
            0
        ),

        COALESCE(
            SUM(
                CASE
                    WHEN e.activity_type =
                        'loan_repayment'::public.financial_activity_type
                    THEN COALESCE(
                        NULLIF(e.cash_amount_usd, 0),
                        NULLIF(e.amount_usd, 0),
                        COALESCE(
                            e.principal_amount_usd,
                            0
                        )
                        +
                        COALESCE(
                            e.interest_amount_usd,
                            0
                        ),
                        0
                    )

                    ELSE 0
                END
            ),
            0
        )

    INTO
        v_withdrawal_usd,
        v_spending_usd,
        v_investment_usd,
        v_repayment_usd

    FROM public.financial_pot_event AS e

    WHERE e.user_id = p_user_id
      AND e.currency_code = v_currency_code
      AND e.fiscal_year = p_fiscal_year
      AND e.period = p_period

      AND lower(e.transaction_type)
          NOT LIKE 'initial\_%' ESCAPE '\';


    -- ==========================================================
    -- DISTRIBUTION
    --
    -- 100% =
    --
    -- Withdrawal
    -- + Spending
    -- + Investment
    -- + Repayment
    -- + Closing Savings
    -- ==========================================================

    v_distribution_total_usd :=
          v_withdrawal_usd
        + v_spending_usd
        + v_investment_usd
        + v_repayment_usd
        + v_savings_usd;


    IF v_distribution_total_usd > 0 THEN

        v_withdrawal_percentage :=
            round(
                (
                    v_withdrawal_usd
                    /
                    v_distribution_total_usd
                    *
                    100
                )::numeric,
                4
            );

        v_spending_percentage :=
            round(
                (
                    v_spending_usd
                    /
                    v_distribution_total_usd
                    *
                    100
                )::numeric,
                4
            );

        v_investment_percentage :=
            round(
                (
                    v_investment_usd
                    /
                    v_distribution_total_usd
                    *
                    100
                )::numeric,
                4
            );

        v_repayment_percentage :=
            round(
                (
                    v_repayment_usd
                    /
                    v_distribution_total_usd
                    *
                    100
                )::numeric,
                4
            );

        v_saving_percentage :=
            round(
                (
                    v_savings_usd
                    /
                    v_distribution_total_usd
                    *
                    100
                )::numeric,
                4
            );

    END IF;


    -- ==========================================================
    -- UPDATE POT
    --
    -- borrowing_percentage is deliberately zero.
    --
    -- Loan disbursement is a SOURCE of money, not a use and not
    -- the Borrower identity metric.
    -- ==========================================================

    UPDATE public.financial_pot
    SET
        withdrawal_percentage =
            v_withdrawal_percentage,

        spending_percentage =
            v_spending_percentage,

        saving_percentage =
            v_saving_percentage,

        investment_percentage =
            v_investment_percentage,

        borrowing_percentage =
            0,

        repayment_percentage =
            v_repayment_percentage,

        updated_at =
            now()

    WHERE user_id = p_user_id
      AND currency_code = v_currency_code
      AND fiscal_year = p_fiscal_year
      AND period = p_period

    RETURNING *
    INTO v_result;


    RETURN v_result;

END;
$$;
ALTER FUNCTION "public"."calculate_financial_pot_percentages"("p_user_id" "text", "p_currency_code" "text", "p_fiscal_year" integer, "p_period" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."calculate_gold_buy_pricing"("p_transaction_type" "public"."TransactionType", "p_amount" numeric, "p_country_code" "text", "p_currency_code" "text") RETURNS "public"."pricing_result"
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
    v_transaction_key text :=
        lower(
            p_transaction_type::text
        );

    v_currency_key text :=
        lower(
            p_currency_code
        );

    v_tax_key text :=
        lower(
            p_transaction_type::text
        ) || '_tax';

    v_config record;

    v_fee_config
        public.amount_config := null;

    v_tax_config
        public.amount_config := null;

    v_spread_config
        public.amount_config := null;

    v_gold_market_price numeric := 0;
    v_spread_rate numeric := 0;
    v_buy_price numeric := 0;

    v_quantity numeric := 0;

    /*
     * USD pricing values.
     */
    v_fiat_paid numeric := 0;
    v_fiat_base numeric := 0;
    v_fee_fiat numeric := 0;

    /*
     * Gold-equivalent transaction fee used by the
     * gold-token sub-transaction.
     */
    v_fee_gold numeric := 0;

    v_treasury_cost numeric := 0;
    v_spread numeric := 0;
    v_tax numeric := 0;

    /*
     * Values exposed through pricing_result.
     */
    v_result_fee numeric := 0;
    v_result_tax numeric := 0;
    v_result_spread numeric := 0;

begin
    /*
     * ==========================================================
     * VALIDATE TRANSACTION TYPE
     * ==========================================================
     */
    if p_transaction_type not in (
        'gold_token_buy'::public."TransactionType",
        'gold_token_buy_sub_tx'::public."TransactionType"
    ) then
        raise exception
            'INVALID_TRANSACTION_TYPE';
    end if;


    if p_amount is null
       or p_amount <= 0
    then
        raise exception
            'INVALID_AMOUNT';
    end if;


    if v_currency_key is null
       or btrim(v_currency_key) = ''
    then
        raise exception
            'CURRENCY_MISSING';
    end if;


    /*
     * ==========================================================
     * FETCH TRANSACTION CONFIGURATION
     * ==========================================================
     */
    for v_config in
        select *
        from public.fetch_all_transaction_configs(
            p_country_code,
            p_currency_code
        )
    loop
        /*
         * Transaction fee.
         */
        if lower(
            v_config.config_key
        ) = v_transaction_key
           and lower(
               v_config.currency_code
           ) = v_currency_key
        then
            v_fee_config :=
                row(
                    v_config.percentage,
                    v_config.fixed_amount,
                    v_config.min_amount,
                    v_config.max_amount
                )::public.amount_config;
        end if;


        /*
         * Transaction tax.
         */
        if lower(
            v_config.config_key
        ) = v_tax_key
           and lower(
               v_config.currency_code
           ) = v_currency_key
        then
            v_tax_config :=
                row(
                    v_config.percentage,
                    v_config.fixed_amount,
                    v_config.min_amount,
                    v_config.max_amount
                )::public.amount_config;
        end if;


        /*
         * Gold buy spread is configured against gold.
         */
        if lower(
            v_config.config_key
        ) = 'gold_spread_buy'
           and lower(
               v_config.currency_code
           ) = 'gold'
        then
            v_spread_config :=
                row(
                    v_config.percentage,
                    v_config.fixed_amount,
                    v_config.min_amount,
                    v_config.max_amount
                )::public.amount_config;
        end if;
    end loop;


    /*
     * ==========================================================
     * GOLD MARKET PRICE
     * ==========================================================
     */
    v_gold_market_price :=
        public.fetch_gold_price();


    if v_gold_market_price is null
       or v_gold_market_price <= 0
    then
        raise exception
            'GOLD_MARKET_PRICE_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * BUY PRICE
     * ==========================================================
     *
     * buyPrice =
     *     goldMarketPrice * (1 + spread)
     */
    v_spread_rate :=
        coalesce(
            v_spread_config.percentage,
            0
        ) / 100;


    v_buy_price :=
        v_gold_market_price *
        (
            1 +
            v_spread_rate
        );


    if v_buy_price <= 0 then
        raise exception
            'INVALID_GOLD_BUY_PRICE';
    end if;


    /*
     * ==========================================================
     * BUY BY GOLD QUANTITY
     * ==========================================================
     */
    if v_currency_key = 'gold' then
        v_quantity :=
            p_amount;


        v_fiat_base :=
            v_quantity *
            v_buy_price;


        v_fee_fiat :=
            public.calculate_configured_amount(
                v_fiat_base,
                v_fee_config
            );


        v_fiat_paid :=
            v_fiat_base +
            v_fee_fiat;


        if v_buy_price > 0 then
            v_fee_gold :=
                v_fee_fiat /
                v_buy_price;
        else
            v_fee_gold :=
                0;
        end if;


        v_treasury_cost :=
            v_quantity *
            v_gold_market_price;


        v_spread :=
            v_fiat_base -
            v_treasury_cost;


        v_tax :=
            public.calculate_configured_amount(
                v_fiat_paid,
                v_tax_config
            );


    /*
     * ==========================================================
     * BUY BY FIAT AMOUNT
     * ==========================================================
     */
    else
        v_fiat_paid :=
            p_amount;


        v_fee_fiat :=
            public.calculate_configured_amount(
                v_fiat_paid,
                v_fee_config
            );


        v_fiat_base :=
            v_fiat_paid -
            v_fee_fiat;


        if v_fiat_base <= 0 then
            raise exception
                'INVALID_GOLD_BUY_FIAT_BASE';
        end if;


        v_quantity :=
            v_fiat_base /
            v_buy_price;


        v_fee_gold :=
            v_fee_fiat /
            v_buy_price;


        v_treasury_cost :=
            v_quantity *
            v_gold_market_price;


        v_spread :=
            v_fiat_base -
            v_treasury_cost;


        v_tax :=
            public.calculate_configured_amount(
                v_fiat_paid,
                v_tax_config
            );
    end if;


    /*
     * ==========================================================
     * VALIDATE CALCULATED PRICING
     * ==========================================================
     */
    if v_quantity <= 0 then
        raise exception
            'INVALID_GOLD_BUY_QUANTITY';
    end if;


    if v_fiat_paid <= 0 then
        raise exception
            'INVALID_GOLD_BUY_FIAT_AMOUNT';
    end if;


    if v_fiat_base <= 0 then
        raise exception
            'INVALID_GOLD_BUY_FIAT_BASE';
    end if;


    /*
     * ==========================================================
     * RESOLVE RESULT UNITS
     * ==========================================================
     */
    if p_transaction_type =
       'gold_token_buy'::public."TransactionType"
    then
        v_result_fee :=
            v_fee_fiat;

        v_result_tax :=
            v_tax;

        v_result_spread :=
            v_spread;

    else
        v_result_fee :=
            v_fee_gold;

        v_result_tax :=
            0;

        v_result_spread :=
            0;
    end if;


    /*
     * ==========================================================
     * RETURN PRICING
     * ==========================================================
     *
     * pricing_result:
     *
     * fee
     * tax
     * spread
     * commission
     * quantity
     * fiat_received
     * gold_price
     */
    return row(
        public.round_down(
            v_result_fee
        ),

        public.round_down(
            v_result_tax
        ),

        public.round_down(
            v_result_spread
        ),

        0,

        public.round_down(
            v_quantity
        ),

        public.round_down(
            v_fiat_paid
        ),

        public.round_down(
            v_buy_price
        )
    )::public.pricing_result;

end;
$$;
ALTER FUNCTION "public"."calculate_gold_buy_pricing"("p_transaction_type" "public"."TransactionType", "p_amount" numeric, "p_country_code" "text", "p_currency_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."calculate_gold_sell_pricing"("p_transaction_type" "public"."TransactionType", "p_amount" numeric, "p_country_code" "text", "p_currency_code" "text") RETURNS "public"."pricing_result"
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
    /*
     * ==========================================================
     * NORMALIZED INPUT
     * ==========================================================
     */
    v_currency_key text :=
        lower(
            nullif(
                btrim(
                    p_currency_code
                ),
                ''
            )
        );


    /*
     * ==========================================================
     * CONFIGURATION KEYS
     * ==========================================================
     */
    v_fee_key text :=
        'gold_token_sell';

    v_tax_key text :=
        'gold_token_sell_tax';

    v_spread_key text :=
        'gold_spread_sell';


    /*
     * ==========================================================
     * CONFIGURATION
     * ==========================================================
     */
    v_config record;

    v_fee_config
        public.amount_config := null;

    v_tax_config
        public.amount_config := null;

    v_spread_config
        public.amount_config := null;


    /*
     * ==========================================================
     * PRICING VALUES
     * ==========================================================
     */
    v_gold_market_price numeric := 0;

    v_spread_rate numeric := 0;

    v_sell_price numeric := 0;

    v_quantity numeric := 0;

    v_fiat_base numeric := 0;

    v_fiat_received numeric := 0;

    v_fee_fiat numeric := 0;

    v_fee_gold numeric := 0;

    v_market_fiat numeric := 0;

    v_spread numeric := 0;

    v_tax numeric := 0;


    /*
     * ==========================================================
     * RETURN VALUES
     * ==========================================================
     */
    v_result_fee numeric := 0;

    v_result_tax numeric := 0;

    v_result_spread numeric := 0;

begin
    /*
     * ==========================================================
     * VALIDATE TRANSACTION TYPE
     * ==========================================================
     */
    if p_transaction_type not in (
        'gold_token_sell'::public."TransactionType",
        'gold_token_sell_sub_tx'::public."TransactionType"
    ) then
        raise exception
            'INVALID_GOLD_SELL_TRANSACTION_%',
            p_transaction_type;
    end if;


    /*
     * ==========================================================
     * VALIDATE AMOUNT
     * ==========================================================
     */
    if p_amount is null
       or p_amount <= 0
    then
        raise exception
            'INVALID_AMOUNT';
    end if;


    /*
     * ==========================================================
     * VALIDATE INPUT CURRENCY
     * ==========================================================
     */
    if v_currency_key is null then
        raise exception
            'CURRENCY_MISSING';
    end if;


    /*
     * ==========================================================
     * FETCH GOLD MARKET PRICE
     * ==========================================================
     */
    v_gold_market_price :=
        public.fetch_gold_price();


    if v_gold_market_price is null
       or v_gold_market_price <= 0
    then
        raise exception
            'GOLD_MARKET_PRICE_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * FETCH TRANSACTION CONFIGURATION
     * ==========================================================
     */
    for v_config in
        select *
        from public.fetch_all_transaction_configs(
            p_country_code,
            p_currency_code
        )
    loop
        /*
         * TRANSACTION FEE
         */
        if lower(
            v_config.config_key
        ) = v_fee_key
           and lower(
               v_config.currency_code
           ) = v_currency_key
        then
            v_fee_config :=
                row(
                    v_config.percentage,
                    v_config.fixed_amount,
                    v_config.min_amount,
                    v_config.max_amount
                )::public.amount_config;
        end if;


        /*
         * GOVERNMENT TAX
         */
        if lower(
            v_config.config_key
        ) = v_tax_key
           and lower(
               v_config.currency_code
           ) = v_currency_key
        then
            v_tax_config :=
                row(
                    v_config.percentage,
                    v_config.fixed_amount,
                    v_config.min_amount,
                    v_config.max_amount
                )::public.amount_config;
        end if;


        /*
         * GOLD SELL SPREAD
         */
        if lower(
            v_config.config_key
        ) = v_spread_key
           and lower(
               v_config.currency_code
           ) = 'gold'
        then
            v_spread_config :=
                row(
                    v_config.percentage,
                    v_config.fixed_amount,
                    v_config.min_amount,
                    v_config.max_amount
                )::public.amount_config;
        end if;
    end loop;


    /*
     * ==========================================================
     * CALCULATE CUSTOMER SELL PRICE
     * ==========================================================
     */
    v_spread_rate :=
        coalesce(
            v_spread_config.percentage,
            0
        ) / 100;


    v_sell_price :=
        v_gold_market_price *
        (
            1 -
            v_spread_rate
        );


    if v_sell_price <= 0 then
        raise exception
            'INVALID_GOLD_SELL_PRICE';
    end if;


    /*
     * ==========================================================
     * MODE 1: USER ENTERS GOLD
     * ==========================================================
     */
    if v_currency_key = 'gold' then
        v_quantity :=
            p_amount;


        v_fiat_base :=
            v_quantity *
            v_sell_price;


        v_fee_fiat :=
            public.calculate_configured_amount(
                v_fiat_base,
                v_fee_config
            );


        v_fiat_received :=
            v_fiat_base -
            v_fee_fiat;


        v_fee_gold :=
            v_fee_fiat /
            v_sell_price;


        v_market_fiat :=
            v_quantity *
            v_gold_market_price;


        v_spread :=
            v_market_fiat -
            v_fiat_base;


        v_tax :=
            public.calculate_configured_amount(
                v_fiat_received,
                v_tax_config
            );


    /*
     * ==========================================================
     * MODE 2: USER ENTERS FIAT TO RECEIVE
     * ==========================================================
     */
    else
        v_fiat_received :=
            p_amount;


        v_fee_fiat :=
            public.calculate_configured_amount(
                v_fiat_received,
                v_fee_config
            );


        v_fiat_base :=
            v_fiat_received +
            v_fee_fiat;


        v_quantity :=
            v_fiat_base /
            v_sell_price;


        v_fee_gold :=
            v_fee_fiat /
            v_sell_price;


        v_market_fiat :=
            v_quantity *
            v_gold_market_price;


        v_spread :=
            v_market_fiat -
            v_fiat_base;


        v_tax :=
            public.calculate_configured_amount(
                v_fiat_received,
                v_tax_config
            );
    end if;


    /*
     * ==========================================================
     * VALIDATE CALCULATED RESULT
     * ==========================================================
     */
    if v_quantity is null
       or v_quantity <= 0
    then
        raise exception
            'INVALID_GOLD_SELL_QUANTITY';
    end if;


    if v_fiat_base is null
       or v_fiat_base <= 0
    then
        raise exception
            'INVALID_GOLD_SELL_FIAT_BASE';
    end if;


    if v_fiat_received is null
       or v_fiat_received <= 0
    then
        raise exception
            'INVALID_GOLD_SELL_FIAT_RECEIVED';
    end if;


    if v_fee_fiat < 0 then
        raise exception
            'INVALID_GOLD_SELL_FEE';
    end if;


    if v_fee_gold < 0 then
        raise exception
            'INVALID_GOLD_SELL_GOLD_FEE';
    end if;


    if v_spread < 0 then
        raise exception
            'INVALID_GOLD_SELL_SPREAD';
    end if;


    if v_tax < 0 then
        raise exception
            'INVALID_GOLD_SELL_TAX';
    end if;


    /*
     * ==========================================================
     * MAIN GOLD SELL
     * ==========================================================
     */
    if p_transaction_type =
       'gold_token_sell'::public."TransactionType"
    then
        v_result_fee :=
            v_fee_fiat;

        v_result_tax :=
            v_tax;

        v_result_spread :=
            v_spread;


    /*
     * ==========================================================
     * GOLD SELL SUB-TRANSACTION
     * ==========================================================
     */
    else
        v_result_fee :=
            v_fee_gold;

        v_result_tax :=
            0;

        v_result_spread :=
            0;
    end if;


    /*
     * ==========================================================
     * RETURN
     * ==========================================================
     *
     * pricing_result:
     *
     * fee
     * tax
     * spread
     * commission
     * quantity
     * fiat_received
     * gold_price
     */
    return row(
        public.round_down(
            v_result_fee
        ),

        public.round_down(
            v_result_tax
        ),

        public.round_down(
            v_result_spread
        ),

        0,

        public.round_down(
            v_quantity
        ),

        public.round_down(
            v_fiat_received
        ),

        public.round_down(
            v_sell_price
        )
    )::public.pricing_result;

end;
$$;
ALTER FUNCTION "public"."calculate_gold_sell_pricing"("p_transaction_type" "public"."TransactionType", "p_amount" numeric, "p_country_code" "text", "p_currency_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."calculate_gold_transfer_pricing"("p_transaction_type" "public"."TransactionType", "p_amount" numeric, "p_country_code" "text", "p_currency_code" "text") RETURNS "public"."pricing_result"
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
    v_transaction_key text :=
        lower(p_transaction_type::text);

    v_currency_key text :=
        lower(p_currency_code);

    v_tax_key text :=
        lower(p_transaction_type::text) || '_tax';

    v_config record;

    v_fee_config public.amount_config := null;
    v_tax_config public.amount_config := null;

    v_fee numeric := 0;
    v_tax numeric := 0;
begin
    if p_transaction_type <>
       'gold_token_transfer'::public."TransactionType"
    then
        raise exception 'INVALID_TRANSACTION_TYPE';
    end if;

    for v_config in
        select *
        from public.fetch_all_transaction_configs(
            p_country_code,
            p_currency_code
        )
    loop
        if lower(v_config.config_key) =
               v_transaction_key
           and lower(v_config.currency_code) =
               v_currency_key
        then
            v_fee_config := row(
                v_config.percentage,
                v_config.fixed_amount,
                v_config.min_amount,
                v_config.max_amount
            )::public.amount_config;
        end if;

        if lower(v_config.config_key) =
               v_tax_key
           and lower(v_config.currency_code) =
               v_currency_key
        then
            v_tax_config := row(
                v_config.percentage,
                v_config.fixed_amount,
                v_config.min_amount,
                v_config.max_amount
            )::public.amount_config;
        end if;
    end loop;

    v_fee :=
        public.calculate_configured_amount(
            p_amount,
            v_fee_config
        );

    v_tax :=
        public.calculate_configured_amount(
            p_amount,
            v_tax_config
        );

    return row(
        v_fee,
        v_tax,
        0,
        0,
        p_amount,
        0,
        0
    )::public.pricing_result;
end;
$$;
ALTER FUNCTION "public"."calculate_gold_transfer_pricing"("p_transaction_type" "public"."TransactionType", "p_amount" numeric, "p_country_code" "text", "p_currency_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."calculate_required_collateral"("p_user_id" "text") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_gold_price numeric := 0;
    v_locked_tokens numeric := 0;

    v_loan public.loan%rowtype;

    v_principal numeric := 0;
    v_interest numeric := 0;
    v_exposure numeric := 0;

    v_target_ltv numeric := 0;
    v_required_for_loan numeric := 0;

    v_total_required_pool numeric := 0;
    v_required_collateral numeric := 0;

begin
    /*
     * ==========================================================
     * VALIDATE USER
     * ==========================================================
     */
    if p_user_id is null
       or btrim(p_user_id) = ''
    then
        raise exception
            'USER_ID_REQUIRED';
    end if;


    perform 1
    from public.users user_record
    where user_record.id =
          p_user_id
    limit 1;


    if not found then
        raise exception
            'USER_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * CURRENT GOLD PRICE
     * ==========================================================
     */
    select
        coalesce(
            rate_record.rate_to_usd,
            0
        )
    into
        v_gold_price
    from public.current_rates rate_record
    where lower(
        btrim(
            rate_record.code
        )
    ) = 'gold'
    limit 1;


    v_gold_price :=
        coalesce(
            v_gold_price,
            0
        );


    if v_gold_price <= 0 then
        raise exception
            'INVALID_GOLD_RATE';
    end if;


    /*
     * ==========================================================
     * CURRENT POOLED COLLATERAL
     * ==========================================================
     */
    select
        coalesce(
            collateral_record.locked_tokens,
            0
        )
    into
        v_locked_tokens
    from public.collateral collateral_record
    where collateral_record.user_id =
          p_user_id
    limit 1;


    v_locked_tokens :=
        greatest(
            coalesce(
                v_locked_tokens,
                0
            ),
            0
        );


    /*
     * ==========================================================
     * CALCULATE REQUIRED COLLATERAL POOL
     * ==========================================================
     *
     * For every active loan:
     *
     * exposure =
     *     outstanding principal
     *     +
     *     outstanding interest
     *
     * target collateral gold =
     *
     *     exposure
     *     /
     *     (max_ltv_percent / 100)
     *     /
     *     current gold price
     *
     * The pool requirement is the SUM of all active-loan
     * requirements.
     *
     * loan.collateral is NOT used to determine the shortage.
     */
    for v_loan in
        select
            loan_record.*
        from public.loan loan_record
        where loan_record.user_id =
              p_user_id
          and loan_record.status =
              'active'::public."LoanStatus"
        order by
            loan_record.created_at asc,
            loan_record.id asc
    loop
        /*
         * Current outstanding principal and interest
         * for this loan.
         */
        select
            greatest(
                coalesce(
                    sum(
                        entry_record.debit_principal
                    ),
                    0
                ) -
                coalesce(
                    sum(
                        entry_record.credit_principal
                    ),
                    0
                ),
                0
            ),

            greatest(
                coalesce(
                    sum(
                        entry_record.debit_interest
                    ),
                    0
                ) -
                coalesce(
                    sum(
                        entry_record.credit_interest
                    ),
                    0
                ),
                0
            )
        into
            v_principal,
            v_interest
        from public.loan_entry entry_record
        where entry_record.loan_id =
              v_loan.id;


        v_exposure :=
            v_principal +
            v_interest;


        if v_exposure <= 0 then
            continue;
        end if;


        /*
         * max_ltv_percent is stored as a percentage.
         *
         * Example:
         *
         * 60.00 -> 0.60
         */
        v_target_ltv :=
            coalesce(
                v_loan.max_ltv_percent,
                0
            );


        if v_target_ltv <= 0
           or v_target_ltv > 100
        then
            raise exception
                'INVALID_LOAN_LTV_CONFIGURATION';
        end if;


        /*
         * Required Gold for this loan at the current
         * exposure and Gold price.
         */
        v_required_for_loan :=
            (
                v_exposure /
                (
                    v_target_ltv /
                    100
                )
            ) /
            v_gold_price;


        /*
         * Collateral quantities are maintained at
         * six decimal places.
         *
         * Round upward so we never understate what is
         * required to reach the configured target LTV.
         */
        v_required_for_loan :=
            ceil(
                v_required_for_loan *
                1000000
            ) /
            1000000;


        v_total_required_pool :=
            v_total_required_pool +
            v_required_for_loan;
    end loop;


    /*
     * ==========================================================
     * CALCULATE ADDITIONAL COLLATERAL REQUIRED
     * ==========================================================
     *
     * required collateral =
     *
     *     total required pool
     *     -
     *     actual pooled locked collateral
     */
    v_required_collateral :=
        greatest(
            v_total_required_pool -
            v_locked_tokens,
            0
        );


    if v_required_collateral > 0 then
        v_required_collateral :=
            ceil(
                v_required_collateral *
                1000000
            ) /
            1000000;
    else
        v_required_collateral := 0;
    end if;


    return
        v_required_collateral;
end;
$$;
ALTER FUNCTION "public"."calculate_required_collateral"("p_user_id" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."calculate_transaction_pricing"("p_transaction_type" "public"."TransactionType", "p_principal" numeric, "p_country_code" "text", "p_currency_code" "text") RETURNS "public"."pricing_result"
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
    v_transaction_key text :=
        lower(p_transaction_type::text);

    v_currency_key text :=
        lower(p_currency_code);

    v_tax_key text :=
        lower(p_transaction_type::text) || '_tax';

    v_config record;

    v_fee_config public.amount_config := null;
    v_tax_config public.amount_config := null;

    v_fee numeric := 0;
    v_tax numeric := 0;
    v_commission_rate numeric := 0;
    v_commission numeric := 0;
begin
    for v_config in
        select *
        from public.fetch_all_transaction_configs(
            p_country_code,
            p_currency_code
        )
    loop
        if lower(v_config.config_key) =
               v_transaction_key
           and lower(v_config.currency_code) =
               v_currency_key
        then
            v_fee_config := row(
                v_config.percentage,
                v_config.fixed_amount,
                v_config.min_amount,
                v_config.max_amount
            )::public.amount_config;
        end if;

        if lower(v_config.config_key) =
               v_tax_key
           and lower(v_config.currency_code) =
               v_currency_key
        then
            v_tax_config := row(
                v_config.percentage,
                v_config.fixed_amount,
                v_config.min_amount,
                v_config.max_amount
            )::public.amount_config;
        end if;
    end loop;

    v_fee :=
        public.calculate_configured_amount(
            p_principal,
            v_fee_config
        );

    v_tax :=
        public.calculate_configured_amount(
            p_principal,
            v_tax_config
        );

    v_commission_rate :=
        public.fetch_agent_commission_rate(
            p_transaction_type,
            p_currency_code,
            p_country_code
        );

    v_commission :=
        v_commission_rate / 100 * v_fee;

    return row(
        v_fee,
        v_tax,
        0,
        v_commission,
        0,
        0,
        0
    )::public.pricing_result;
end;
$$;
ALTER FUNCTION "public"."calculate_transaction_pricing"("p_transaction_type" "public"."TransactionType", "p_principal" numeric, "p_country_code" "text", "p_currency_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."cash_deposit"("p_user_id" "text", "p_transaction" "jsonb", "p_transaction_type" "public"."TransactionType", "p_country_code" "text", "p_transaction_state_id" "text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "reference" "text", "customer_id" "text", "gross_amount" "text", "gross_amount_usd" "text", "financial_transaction_id" "text", "receiver_notification_id" "text", "device_tokens" "text"[], "push_title" "text", "push_body" "text", "push_reference" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_decimals numeric := 100;
    v_amount numeric;
    v_amount_usd numeric(20, 6);
    v_rate_to_usd numeric;
    v_currency text;
    v_reference text;
    v_provider_id text;
    v_fiscal_year integer;
    v_period integer;

    v_user public.users%rowtype;
    v_provider public.users%rowtype;

    v_transaction_state
        public.transaction_state%rowtype;

    v_mappings
        public.transaction_gl_mapping[];

    v_components
        public.posting_component[];

    v_receiver_notification
        public.notification_message;

    v_sender_notification
        public.notification_message;

    v_device_tokens text[] :=
        array[]::text[];

    v_document_prefix text;
    v_document_number text;
    v_financial_transaction_id bigint;
    v_receiver_notification_id text;

    v_deposit_type
        public."CustomerDepositType" :=
            'agent'::public."CustomerDepositType";

    /* Debugging information. */
    v_stage text := 'initialization';
    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * This posting function is callable only by the
     * server-side service-role client.
     */
    v_stage := 'validate service role';

    if coalesce(auth.role(), '') <> 'service_role' then
        raise exception using
            errcode = '42501',
            message = 'SERVICE_ROLE_REQUIRED';
    end if;

    /* Validate the transaction type. */
    v_stage := 'validate transaction type';

    if p_transaction_type <>
       'cash_deposit'::public."TransactionType"
    then
        raise exception
            'INVALID_CASH_DEPOSIT_TRANSACTION_TYPE_%',
            p_transaction_type;
    end if;

    /*
     * Validate and lock the processing transaction.
     *
     * This state was created through the authenticated
     * client before the service-role posting call.
     */
    v_stage :=
        'validate and lock transaction state';

    select transaction_state_record.*
    into v_transaction_state
    from public.transaction_state
        transaction_state_record
    where transaction_state_record.id =
          p_transaction_state_id
      and transaction_state_record.created_by =
          p_user_id
      and transaction_state_record.transaction_type =
          p_transaction_type
      and transaction_state_record.country_code =
          p_country_code
      and transaction_state_record.status =
          'processing'::public."TransactionStatus"
    limit 1
    for update;

    if not found then
        raise exception
            'INVALID_TRANSACTION_STATE';
    end if;

    /*
     * Ensure the service-role posting uses the same
     * transaction that created the processing state.
     */
    v_stage :=
        'validate transaction state data';

    if v_transaction_state.transaction_data
       is distinct from p_transaction
    then
        raise exception
            'TRANSACTION_STATE_DATA_MISMATCH';
    end if;

    /* Parse transaction data. */
    v_stage := 'parse transaction amount';

    v_amount :=
        (p_transaction ->> 'a')::numeric /
        v_decimals;

    if v_amount <= 0 then
        raise exception
            'INVALID_AMOUNT';
    end if;

    v_stage := 'parse transaction currency';

    v_currency :=
        lower(
            nullif(
                btrim(p_transaction ->> 'c'),
                ''
            )
        );

    if v_currency is null then
        raise exception
            'CURRENCY_MISSING';
    end if;

    v_stage := 'parse transaction reference';

    v_reference :=
        nullif(
            btrim(p_transaction ->> 'r'),
            ''
        );

    if v_reference is null then
        raise exception
            'REFERENCE_MISSING';
    end if;

    v_stage := 'parse provider identifier';

    v_provider_id :=
        nullif(
            btrim(p_transaction ->> 's'),
            ''
        );

    if v_provider_id is null then
        raise exception
            'PROVIDER_ID_MISSING';
    end if;

    /*
     * Capture the qualifying USD amount inside the same
     * database transaction as the financial posting.
     *
     * Existing Ngoda rate convention:
     * - USD: already denominated in USD;
     * - Gold: amount multiplied by USD price per gram;
     * - Other fiat: amount divided by currency units per USD.
     */
    v_stage := 'calculate loyalty USD amount';

    if v_currency = 'usd' then
        v_amount_usd :=
            round(v_amount, 6);
    else
        select rate_record.rate_to_usd
        into v_rate_to_usd
        from public.current_rates rate_record
        where lower(btrim(rate_record.code)) =
              v_currency
        limit 1;

        if not found
           or v_rate_to_usd is null
           or v_rate_to_usd <= 0
        then
            raise exception
                'CURRENT_RATE_NOT_FOUND_%',
                upper(v_currency);
        end if;

        if v_currency = 'gold' then
            v_amount_usd :=
                round(
                    v_amount * v_rate_to_usd,
                    6
                );
        else
            v_amount_usd :=
                round(
                    v_amount / v_rate_to_usd,
                    6
                );
        end if;
    end if;

    if v_amount_usd <= 0 then
        raise exception
            'INVALID_CASH_DEPOSIT_USD_AMOUNT';
    end if;

    /*
     * Ensure the locked state belongs to the provider
     * contained in the signed transaction.
     */
    if v_transaction_state.user_id
       is distinct from v_provider_id
    then
        raise exception
            'TRANSACTION_PROVIDER_MISMATCH';
    end if;

    /*
     * Validate the sender approval stored in the
     * transaction state.
     */
    v_stage := 'validate sender approval';

    if v_transaction_state.sender_approval is null
       or jsonb_typeof(
           v_transaction_state.sender_approval
       ) <> 'object'
    then
        raise exception
            'SENDER_APPROVAL_MISSING';
    end if;

    if (
        v_transaction_state.sender_approval
            ->> 'a'
       )::numeric <>
       (
        p_transaction ->> 'a'
       )::numeric
    then
        raise exception
            'AMOUNT_MISMATCH';
    end if;

    if lower(
        btrim(
            v_transaction_state.sender_approval
                ->> 'c'
        )
    ) is distinct from v_currency
    then
        raise exception
            'CURRENCY_MISMATCH';
    end if;

    if btrim(
        v_transaction_state.sender_approval
            ->> 'r'
    ) is distinct from v_reference
    then
        raise exception
            'REFERENCE_MISMATCH';
    end if;

    /* Validate the initiating user's role. */
    v_stage := 'validate initiating user role';

    if not public.user_has_role(
        p_user_id,
        array[
            'customer'::public."Role",
            'agent'::public."Role",
            'vendor'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'USER_NOT_AUTHORIZED';
    end if;

    /* Validate the cash provider's role. */
    v_stage := 'validate provider role';

    if not public.user_has_role(
        v_provider_id,
        array[
            'agent'::public."Role",
            'vendor'::public."Role",
            'merchant'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'PROVIDER_NOT_AUTHORIZED';
    end if;

    /* Fetch both participants. */
    v_stage := 'fetch user';

    v_user :=
        public.fetch_user_by_id(
            p_user_id
        );

    v_stage := 'fetch provider';

    v_provider :=
        public.fetch_user_by_id(
            v_provider_id
        );

    /* Validate participants. */
    v_stage := 'validate participants';

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'USER_NOT_ACTIVE';
    end if;

    if v_provider.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'PROVIDER_NOT_ACTIVE';
    end if;

    if v_user.id = v_provider.id then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    if v_user.country_code is distinct from
       v_provider.country_code
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    if v_user.country_code is distinct from
       p_country_code
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    /* Fetch the current fiscal period. */
    v_stage := 'fetch fiscal period';

    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        p_country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /* Fetch the configured GL mappings. */
    v_stage := 'fetch GL mappings';

    select array_agg(mapping_record)
    into v_mappings
    from public.fetch_gl_mappings(
        p_transaction_type
    ) as mapping_record;

    if v_mappings is null
       or cardinality(v_mappings) = 0
    then
        raise exception
            'GL_MAPPINGS_NOT_FOUND';
    end if;

    /* Build the balanced posting components. */
    v_stage := 'build posting components';

    v_components :=
        public.build_posting_components(
            p_transaction_type,
            v_amount,
            v_mappings,
            p_country_code,
            v_currency,
            false
        );

    if v_components is null
       or cardinality(v_components) = 0
    then
        raise exception
            'POSTING_COMPONENTS_NOT_FOUND';
    end if;

    /* Build the user notification. */
    v_stage := 'create receiver notification';

    v_receiver_notification :=
        public.create_notification_message(
            p_country_code,
            p_transaction_type,
            'receiver'::public."NotificationAudience",
            v_amount,
            upper(v_currency),
            v_reference || '-01',
            0,
            coalesce(
                v_provider.email,
                v_provider.phone,
                v_provider.id
            ),
            coalesce(
                v_user.email,
                v_user.phone,
                v_user.id
            )
        );

    /* Build the provider notification. */
    v_stage := 'create sender notification';

    v_sender_notification :=
        public.create_notification_message(
            p_country_code,
            p_transaction_type,
            'sender'::public."NotificationAudience",
            v_amount,
            upper(v_currency),
            v_reference || '-02',
            0,
            'Ngoda',
            coalesce(
                v_user.email,
                v_user.phone,
                v_user.id
            )
        );

    /* Fetch the receiving user's device tokens. */
    v_stage := 'fetch receiver device tokens';

    v_device_tokens :=
        coalesce(
            public.fetch_device_tokens(
                p_country_code,
                v_user.id
            ),
            array[]::text[]
        );

    /* Generate the accounting document number. */
    v_stage :=
        'fetch document number prefix';

    v_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            p_transaction_type
        );

    v_stage := 'generate document number';

    v_document_number :=
        public.generate_document_number(
            v_document_prefix,
            v_fiscal_year,
            v_period,
            p_country_code
        );

    /* Create the financial transaction header. */
    v_stage :=
        'insert financial transaction';

    insert into public.financial_transaction (
        fiscal_year,
        period,
        document_number,
        reference,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        external_reference,
        country_code
    )
    values (
        v_fiscal_year,
        v_period,
        v_document_number,
        v_document_number,
        p_transaction_type,
        'User ' ||
        coalesce(
            v_user.email,
            v_user.phone,
            v_user.id
        ) ||
        ' deposit from provider ' ||
        coalesce(
            v_provider.email,
            v_provider.phone,
            v_provider.id
        ),
        v_provider.id,
        v_amount,
        v_currency,
        v_deposit_type::text,
        p_country_code
    )
    returning id
    into v_financial_transaction_id;

    /* Post the financial ledger entries. */
    v_stage := 'post financial entries';

    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_document_number,
        p_country_code =>
            p_country_code,
        p_transaction_id =>
            v_financial_transaction_id,
        p_transaction_type =>
            p_transaction_type,
        p_created_by =>
            v_provider.id,
        p_components =>
            v_components,
        p_mappings =>
            v_mappings,
        p_currency_code =>
            v_currency,
        p_fiscal_year =>
            v_fiscal_year,
        p_period =>
            v_period,
        p_reference =>
            v_reference,
        p_deposit_type =>
            v_deposit_type
    );

    /*
     * Debit the provider's agent wallet and credit
     * the user's customer wallet.
     */
    v_stage := 'post wallet entries';

    select result.receiver_notification_id
    into v_receiver_notification_id
    from public.post_wallet_entries(
        p_fiscal_year =>
            v_fiscal_year,
        p_period =>
            v_period,
        p_document_number =>
            v_document_number,
        p_reference =>
            v_reference,
        p_receiver_id =>
            v_user.id,
        p_sender_id =>
            v_provider.id,
        p_transaction_type =>
            p_transaction_type,
        p_credit_amount =>
            v_amount,
        p_debit_amount =>
            v_amount,
        p_sender_wallet_owner =>
            'agent'::public."WalletOwnerType",
        p_receiver_wallet_owner =>
            'customer'::public."WalletOwnerType",
        p_currency_code =>
            v_currency,
        p_country_code =>
            p_country_code,
        p_audit_action_type =>
            'cash_deposited'::public."AuditActionType",
        p_treasury_id =>
            null,
        p_fee_amount =>
            0,
        p_ip_address =>
            p_ip_address,
        p_receiver_notification =>
            v_receiver_notification,
        p_sender_notification =>
            v_sender_notification
    ) as result;

    /* Mark the transaction state as successful. */
    v_stage := 'update transaction state';

    update public.transaction_state
    set
        user_id =
            v_provider.id,
        status =
            'success'::public."TransactionStatus",
        message =
            null,
        updated_at =
            now()
    where id =
          p_transaction_state_id
      and created_by =
          p_user_id
      and user_id =
          v_provider.id
      and transaction_type =
          p_transaction_type
      and status =
          'processing'::public."TransactionStatus";

    if not found then
        raise exception
            'TRANSACTION_STATE_UPDATE_FAILED';
    end if;

    /* Return posting, loyalty, and push details. */
    v_stage := 'return cash deposit result';

    return query
    select
        true,
        v_document_number,
        v_user.id,
        v_amount::text,
        v_amount_usd::text,
        v_financial_transaction_id::text,
        v_receiver_notification_id,
        v_device_tokens,
        v_receiver_notification.title,
        v_receiver_notification.body,
        v_receiver_notification.payload
            ->> 'reference';
exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,
            v_error_message =
                message_text,
            v_error_detail =
                pg_exception_detail,
            v_error_hint =
                pg_exception_hint,
            v_error_context =
                pg_exception_context;

        raise exception using
            errcode =
                v_error_state,
            message =
                format(
                    'CASH_DEPOSIT_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),
            detail =
                coalesce(
                    nullif(
                        concat_ws(
                            E'\n',
                            nullif(
                                v_error_detail,
                                ''
                            ),
                            nullif(
                                v_error_context,
                                ''
                            )
                        ),
                        ''
                    ),
                    'No additional PostgreSQL context'
                ),
            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    'Check the cash-deposit stage reported in the error'
                );
end;
$$;
ALTER FUNCTION "public"."cash_deposit"("p_user_id" "text", "p_transaction" "jsonb", "p_transaction_type" "public"."TransactionType", "p_country_code" "text", "p_transaction_state_id" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."cash_transfer"("p_sender_id" "text", "p_transaction" "jsonb", "p_transaction_type" "public"."TransactionType", "p_country_code" "text", "p_transaction_state_id" "text", "p_ip_address" "text" DEFAULT NULL::"text", "p_fee_payment_method" "text" DEFAULT 'cash'::"text") RETURNS TABLE("success" boolean, "reference" "text", "financial_transaction_id" "text", "amount" "text", "amount_usd" "text", "original_fee" "text", "cash_fee" "text", "cash_charges" "text", "fee_payment_method" "text", "points_redeemed" bigint, "redemption_ledger_id" "text", "loyalty" "jsonb", "currency" "text", "receiver_notification_id" "text", "device_tokens" "text"[], "push_title" "text", "push_body" "text", "push_reference" "text", "receiver_id" "text", "sender_debit" "text", "sender_debit_usd" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$

declare

v_decimals numeric := 100;

v_amount numeric;
v_amount_usd numeric(20, 6);
v_principal numeric;
v_currency text;
v_reference text;
v_receiver_identifier text;
v_fee_payment_method text;
v_rate_to_usd numeric;

/*
 * Actual sender wallet debit converted using the same
 * transaction-time exchange rate as the transfer amount.
 */
v_sender_debit_usd numeric(20, 6);

v_fiscal_year integer;
v_period integer;

v_receiver public.users%rowtype;
v_sender public.users%rowtype;
v_treasury public.users%rowtype;
v_transaction_state public.transaction_state%rowtype;

v_mappings
    public.transaction_gl_mapping[];

v_components
    public.posting_component[];

v_component_totals
    public.component_totals;

v_principal_amount numeric;
v_others_amount numeric;
v_original_fee numeric := 0;
v_cash_fee numeric := 0;
v_fee_amount_usd numeric(20, 6) := 0;

v_redemption_config
    public.loyalty_redemption_config%rowtype;

v_points_redeemed bigint := 0;
v_redemption_result jsonb;
v_redemption_ledger_id text;
v_loyalty_result jsonb;

v_sender_notification
    public.notification_message;

v_receiver_notification
    public.notification_message;

v_device_tokens text[] :=
    array[]::text[];

v_document_prefix text;
v_document_number text;

v_financial_transaction_id bigint;
v_receiver_notification_id text;

v_stage text := 'initialization';
v_error_state text;
v_error_message text;
v_error_detail text;
v_error_hint text;
v_error_context text;


begin

v_stage := 'validate service role';

if coalesce(auth.role(), '') <> 'service_role' then
    raise exception using
        errcode = '42501',
        message = 'SERVICE_ROLE_REQUIRED';
end if;


v_stage := 'validate transaction type';

if p_transaction_type <>
   'cash_transfer'::public."TransactionType"
then
    raise exception
        'INVALID_CASH_TRANSFER_TRANSACTION_TYPE_%',
        p_transaction_type;
end if;


v_fee_payment_method :=
    lower(
        coalesce(
            nullif(
                btrim(p_fee_payment_method),
                ''
            ),
            'cash'
        )
    );


if v_fee_payment_method not in (
    'cash',
    'points'
) then
    raise exception
        'INVALID_FEE_PAYMENT_METHOD';
end if;


/* ---------------------------------------------------------------------- */
/* VALIDATE AND LOCK TRANSACTION STATE                                    */
/* ---------------------------------------------------------------------- */

v_stage :=
    'validate and lock transaction state';


select transaction_state_record.*
into v_transaction_state
from public.transaction_state
    transaction_state_record
where transaction_state_record.id =
      p_transaction_state_id
  and transaction_state_record.created_by =
      p_sender_id
  and transaction_state_record.transaction_type =
      p_transaction_type
  and transaction_state_record.country_code =
      p_country_code
  and transaction_state_record.status =
      'processing'::public."TransactionStatus"
limit 1
for update;


if not found then
    raise exception
        'INVALID_TRANSACTION_STATE';
end if;


if v_transaction_state.transaction_data
   is distinct from p_transaction
then
    raise exception
        'TRANSACTION_STATE_DATA_MISMATCH';
end if;


/* ---------------------------------------------------------------------- */
/* PARSE TRANSACTION                                                      */
/* ---------------------------------------------------------------------- */

v_stage := 'parse transaction amount';


v_amount :=
    (p_transaction ->> 'a')::numeric /
    v_decimals;


if v_amount <= 0 then
    raise exception
        'INVALID_AMOUNT';
end if;


v_principal :=
    v_amount;


v_stage :=
    'parse transaction currency';


v_currency :=
    lower(
        nullif(
            btrim(
                p_transaction ->> 'c'
            ),
            ''
        )
    );


if v_currency is null then
    raise exception
        'CURRENCY_MISSING';
end if;


v_stage :=
    'parse transaction reference';


v_reference :=
    nullif(
        btrim(
            p_transaction ->> 'r'
        ),
        ''
    );


if v_reference is null then
    raise exception
        'REFERENCE_MISSING';
end if;


v_stage :=
    'parse receiver identifier';


v_receiver_identifier :=
    nullif(
        btrim(
            p_transaction ->> 's'
        ),
        ''
    );


if v_receiver_identifier is null then
    raise exception
        'RECEIVER_IDENTIFIER_MISSING';
end if;


/* ---------------------------------------------------------------------- */
/* TRANSFER USD VALUE                                                     */
/* ---------------------------------------------------------------------- */

v_stage :=
    'calculate transfer USD amount';


if v_currency = 'usd' then

    v_rate_to_usd := 1;

    v_amount_usd :=
        round(
            v_amount,
            6
        );

else

    select
        rate_record.rate_to_usd
    into
        v_rate_to_usd
    from public.current_rates
        rate_record
    where lower(
        btrim(rate_record.code)
    ) = v_currency
    limit 1;


    if not found
       or v_rate_to_usd is null
       or v_rate_to_usd <= 0
    then
        raise exception
            'CURRENT_RATE_NOT_FOUND_%',
            upper(v_currency);
    end if;


    if v_currency = 'gold' then

        v_amount_usd :=
            round(
                v_amount *
                v_rate_to_usd,
                6
            );

    else

        v_amount_usd :=
            round(
                v_amount /
                v_rate_to_usd,
                6
            );

    end if;

end if;


if v_amount_usd <= 0 then
    raise exception
        'INVALID_TRANSFER_USD_AMOUNT';
end if;


/* ---------------------------------------------------------------------- */
/* GL MAPPINGS                                                            */
/* ---------------------------------------------------------------------- */

v_stage :=
    'fetch GL mappings';


select
    array_agg(mapping_row)
into
    v_mappings
from public.fetch_gl_mappings(
    p_transaction_type
) as mapping_row;


if v_mappings is null
   or cardinality(v_mappings) = 0
then
    raise exception
        'GL_MAPPINGS_NOT_FOUND';
end if;


/* ---------------------------------------------------------------------- */
/* POSTING COMPONENTS                                                     */
/* ---------------------------------------------------------------------- */

v_stage :=
    'build posting components';


v_components :=
    public.build_posting_components(
        p_transaction_type,
        v_principal,
        v_mappings,
        p_country_code,
        v_currency,
        false
    );


if v_components is null
   or cardinality(v_components) = 0
then
    raise exception
        'POSTING_COMPONENTS_NOT_FOUND';
end if;


/* ---------------------------------------------------------------------- */
/* ORIGINAL TRANSFER FEE                                                  */
/* ---------------------------------------------------------------------- */

v_stage :=
    'extract transfer fee';


select
    coalesce(
        component.credit_amount,
        0
    )
into
    v_original_fee
from unnest(v_components)
    as component(
        component_type,
        debit_amount,
        credit_amount
    )
where component.component_type =
      'transfer_fee'::public."ComponentType"
limit 1;


v_original_fee :=
    coalesce(
        v_original_fee,
        0
    );


if v_original_fee <= 0 then
    raise exception
        'INVALID_FEE_AMOUNT';
end if;


/* ---------------------------------------------------------------------- */
/* TRANSFER FEE USD                                                       */
/* ---------------------------------------------------------------------- */

if v_currency = 'usd' then

    v_fee_amount_usd :=
        round(
            v_original_fee,
            6
        );

elsif v_currency = 'gold' then

    v_fee_amount_usd :=
        round(
            v_original_fee *
            v_rate_to_usd,
            6
        );

else

    v_fee_amount_usd :=
        round(
            v_original_fee /
            v_rate_to_usd,
            6
        );

end if;


if v_fee_amount_usd <= 0 then
    raise exception
        'INVALID_TRANSFER_FEE_USD_AMOUNT';
end if;


/* ---------------------------------------------------------------------- */
/* POINT REDEMPTION                                                       */
/* ---------------------------------------------------------------------- */

/*
 * Resolve and apply all-or-nothing transfer-fee redemption.
 *
 * Other components, including government tax,
 * remain payable in cash.
 */

if v_fee_payment_method = 'points' then

    v_stage :=
        'resolve loyalty redemption config';


    select
        config_record.*
    into
        v_redemption_config
    from public.loyalty_redemption_config
        config_record
    where config_record.transaction_type =
          p_transaction_type

      and config_record.is_active = true

      and (
          config_record.country_code is null
          or config_record.country_code =
             lower(p_country_code)
      )

      and (
          config_record.currency_code is null
          or config_record.currency_code =
             v_currency
      )

      and (
          config_record.valid_from is null
          or config_record.valid_from <= now()
      )

      and (
          config_record.valid_until is null
          or config_record.valid_until > now()
      )

    order by

        case
            when config_record.country_code
                 is not null
            then 0
            else 1
        end,

        case
            when config_record.currency_code
                 is not null
            then 0
            else 1
        end,

        config_record.priority,
        config_record.id

    limit 1;


    if not found then
        raise exception
            'TRANSFER_FEE_POINT_REDEMPTION_NOT_AVAILABLE';
    end if;


    v_points_redeemed :=
        ceil(
            v_fee_amount_usd *
            v_redemption_config.points_per_usd
        )::bigint;


    if v_points_redeemed <= 0 then
        raise exception
            'INVALID_TRANSFER_FEE_POINTS';
    end if;


    /*
     * Remove transfer-fee component from the cash
     * posting and reduce the gross sender debit by
     * the same amount.
     */

    v_stage :=
        'apply loyalty fee discount to components';


    select
        array_agg(
            row(
                component.component_type,

                case
                    when component.component_type =
                         'principal'::public."ComponentType"
                    then
                        component.debit_amount -
                        v_original_fee
                    else
                        component.debit_amount
                end,

                component.credit_amount

            )::public.posting_component

            order by component.position
        )
    into
        v_components

    from unnest(v_components)
        with ordinality as component(
            component_type,
            debit_amount,
            credit_amount,
            position
        )

    where component.component_type <>
          'transfer_fee'::public."ComponentType";


    v_components :=
        public.validate_components(
            v_components
        );


    v_cash_fee := 0;

else

    v_cash_fee :=
        v_original_fee;

end if;


/* ---------------------------------------------------------------------- */
/* FINAL CASH TOTALS                                                      */
/* ---------------------------------------------------------------------- */

v_stage :=
    'extract final component totals';


v_component_totals :=
    public.extract_component_totals(
        v_components,
        false
    );


/*
 * IMPORTANT:
 *
 * This is the ACTUAL wallet debit for the sender.
 *
 * It contains:
 *
 * transfer principal
 * + charges still payable in cash
 *
 * If the transfer fee was redeemed with points,
 * that fee is no longer included.
 */

v_principal_amount :=
    v_component_totals.principal_amount;


v_others_amount :=
    v_component_totals.others_amount;


if v_principal_amount < v_amount then
    raise exception
        'INVALID_FINAL_TRANSFER_DEBIT';
end if;


/* ---------------------------------------------------------------------- */
/* SENDER ACTUAL DEBIT USD                                                */
/* ---------------------------------------------------------------------- */

/*
 * Financial Intelligence needs the USD equivalent
 * of the exact amount that was deducted from the
 * sender wallet.
 *
 * Use the SAME transaction-time rate already resolved
 * above. Do not fetch another exchange rate.
 */

v_stage :=
    'calculate sender debit USD';


if v_currency = 'usd' then

    v_sender_debit_usd :=
        round(
            v_principal_amount,
            6
        );

elsif v_currency = 'gold' then

    v_sender_debit_usd :=
        round(
            v_principal_amount *
            v_rate_to_usd,
            6
        );

else

    v_sender_debit_usd :=
        round(
            v_principal_amount /
            v_rate_to_usd,
            6
        );

end if;


if v_sender_debit_usd <= 0 then
    raise exception
        'INVALID_SENDER_DEBIT_USD_AMOUNT';
end if;


/* ---------------------------------------------------------------------- */
/* FISCAL PERIOD                                                          */
/* ---------------------------------------------------------------------- */

v_stage :=
    'fetch fiscal period';


select
    fiscal_period.fiscal_year,
    fiscal_period.period
into
    v_fiscal_year,
    v_period
from public.fetch_fiscal_period(
    p_country_code
) as fiscal_period;


if not found then
    raise exception
        'FISCAL_PERIOD_NOT_FOUND';
end if;


/* ---------------------------------------------------------------------- */
/* PARTICIPANTS                                                           */
/* ---------------------------------------------------------------------- */

v_stage :=
    'fetch receiver';


v_receiver :=
    public.fetch_user_by_email_or_phone(
        v_receiver_identifier
    );


v_stage :=
    'fetch sender';


v_sender :=
    public.fetch_user_by_id(
        p_sender_id
    );


v_stage :=
    'fetch country treasury';


v_treasury :=
    public.fetch_country_treasury(
        p_country_code
    );


/* ---------------------------------------------------------------------- */
/* PARTICIPANT VALIDATION                                                 */
/* ---------------------------------------------------------------------- */

v_stage :=
    'validate receiver status';


if v_receiver.status <>
   'active'::public."UserStatus"
then
    raise exception
        'RECEIVER_NOT_ACTIVE';
end if;


v_stage :=
    'validate sender status';


if v_sender.status <>
   'active'::public."UserStatus"
then
    raise exception
        'SENDER_NOT_ACTIVE';
end if;


if v_sender.id = v_receiver.id
   or v_sender.country_code is distinct from
      v_receiver.country_code
   or v_sender.country_code is distinct from
      p_country_code
then
    raise exception
        'OPERATION_NOT_ALLOWED';
end if;


/* ---------------------------------------------------------------------- */
/* NOTIFICATIONS                                                          */
/* ---------------------------------------------------------------------- */

v_stage :=
    'create sender notification';


v_sender_notification :=
    public.create_notification_message(
        p_country_code,
        p_transaction_type,
        'sender'::public."NotificationAudience",
        v_principal_amount,
        upper(v_currency),
        v_reference || '-01',
        0,

        coalesce(
            v_sender.email,
            v_sender.phone,
            v_sender.id
        ),

        coalesce(
            v_receiver.email,
            v_receiver.phone,
            v_receiver.id
        )
    );


v_stage :=
    'create receiver notification';


v_receiver_notification :=
    public.create_notification_message(
        p_country_code,
        p_transaction_type,
        'receiver'::public."NotificationAudience",
        v_amount,
        upper(v_currency),
        v_reference || '-02',
        0,

        coalesce(
            v_sender.email,
            v_sender.phone,
            v_sender.id
        ),

        coalesce(
            v_receiver.email,
            v_receiver.phone,
            v_receiver.id
        )
    );


v_stage :=
    'fetch receiver device tokens';


v_device_tokens :=
    coalesce(
        public.fetch_device_tokens(
            p_country_code,
            v_receiver.id
        ),
        array[]::text[]
    );


/* ---------------------------------------------------------------------- */
/* DOCUMENT NUMBER                                                        */
/* ---------------------------------------------------------------------- */

v_stage :=
    'fetch document number prefix';


v_document_prefix :=
    public.fetch_transaction_doc_num_prefix(
        p_transaction_type
    );


v_stage :=
    'generate document number';


v_document_number :=
    public.generate_document_number(
        v_document_prefix,
        v_fiscal_year,
        v_period,
        p_country_code
    );


/* ---------------------------------------------------------------------- */
/* FINANCIAL TRANSACTION                                                  */
/* ---------------------------------------------------------------------- */

v_stage :=
    'insert financial transaction';


insert into public.financial_transaction (
    document_number,
    fiscal_year,
    period,
    transaction_type,
    description,
    created_by,
    gross_amount,
    currency_code,
    reference,
    country_code
)
values (
    v_document_number,
    v_fiscal_year,
    v_period,
    p_transaction_type,

    'User transfer from ' ||
    coalesce(
        v_sender.email,
        v_sender.phone,
        v_sender.id
    ) ||
    ' to ' ||
    coalesce(
        v_receiver.email,
        v_receiver.phone,
        v_receiver.id
    ),

    p_sender_id,
    v_principal_amount,
    v_currency,
    v_reference,
    p_country_code
)
returning id
into v_financial_transaction_id;


/* ---------------------------------------------------------------------- */
/* REDEEM LOYALTY POINTS                                                  */
/* ---------------------------------------------------------------------- */

if v_fee_payment_method = 'points' then

    v_stage :=
        'redeem loyalty points';


    v_redemption_result :=
        public.redeem_loyalty_points_for_transfer_fee(
            p_sender_id,
            v_reference,
            v_financial_transaction_id::text,
            p_transaction_type,
            p_country_code,
            v_currency,
            v_original_fee,
            v_fee_amount_usd,
            v_points_redeemed,
            v_redemption_config.points_per_usd
        );


    v_redemption_ledger_id :=
        v_redemption_result ->>
        'ledger_id';


    if v_redemption_ledger_id is null then
        raise exception
            'LOYALTY_REDEMPTION_LEDGER_NOT_CREATED';
    end if;


    v_loyalty_result :=
        jsonb_build_object(

            'points_earned',
                0,

            'points_spent',
                coalesce(
                    (
                        v_redemption_result ->>
                        'points_redeemed'
                    )::bigint,
                    0
                ),

            'available_points',
                coalesce(
                    (
                        v_redemption_result ->>
                        'available_points'
                    )::bigint,
                    0
                ),

            'tier_points',
                coalesce(
                    (
                        v_redemption_result ->>
                        'tier_points'
                    )::bigint,
                    0
                ),

            'previous_level_code',
                v_redemption_result ->>
                'level_code',

            'level_code',
                v_redemption_result ->>
                'level_code',

            'level_changed',
                false
        );

end if;


/* ---------------------------------------------------------------------- */
/* FINANCIAL ENTRIES                                                      */
/* ---------------------------------------------------------------------- */

v_stage :=
    'post financial entries';


perform *
from public.post_financial_entries(

    p_document_number =>
        v_document_number,

    p_country_code =>
        p_country_code,

    p_transaction_id =>
        v_financial_transaction_id,

    p_transaction_type =>
        p_transaction_type,

    p_created_by =>
        p_sender_id,

    p_components =>
        v_components,

    p_mappings =>
        v_mappings,

    p_currency_code =>
        v_currency,

    p_fiscal_year =>
        v_fiscal_year,

    p_period =>
        v_period,

    p_reference =>
        v_reference,

    p_deposit_type =>
        null
);


/* ---------------------------------------------------------------------- */
/* WALLET ENTRIES                                                         */
/* ---------------------------------------------------------------------- */

v_stage :=
    'post wallet entries';


select
    result.receiver_notification_id
into
    v_receiver_notification_id
from public.post_wallet_entries(

    p_fiscal_year =>
        v_fiscal_year,

    p_period =>
        v_period,

    p_document_number =>
        v_document_number,

    p_reference =>
        v_reference,

    p_receiver_id =>
        v_receiver.id,

    p_sender_id =>
        p_sender_id,

    p_transaction_type =>
        p_transaction_type,

    /*
     * Receiver receives ONLY the entered transfer amount.
     */
    p_credit_amount =>
        v_amount,

    /*
     * Sender loses the transfer amount plus all remaining
     * charges payable in cash.
     */
    p_debit_amount =>
        v_principal_amount,

    p_sender_wallet_owner =>
        'customer'::public."WalletOwnerType",

    p_receiver_wallet_owner =>
        'customer'::public."WalletOwnerType",

    p_currency_code =>
        v_currency,

    p_country_code =>
        p_country_code,

    p_audit_action_type =>
        'cash_transferred'::public."AuditActionType",

    p_treasury_id =>
        v_treasury.id,

    p_fee_amount =>
        v_cash_fee,

    p_ip_address =>
        p_ip_address,

    p_receiver_notification =>
        v_receiver_notification,

    p_sender_notification =>
        v_sender_notification

) as result;


/* ---------------------------------------------------------------------- */
/* TRANSACTION SUCCESS                                                    */
/* ---------------------------------------------------------------------- */

v_stage :=
    'update transaction state';


update public.transaction_state
set
    user_id =
        v_receiver.id,

    status =
        'success'::public."TransactionStatus",

    message =
        null,

    updated_at =
        now()

where id =
      p_transaction_state_id

  and created_by =
      p_sender_id

  and transaction_type =
      p_transaction_type

  and status =
      'processing'::public."TransactionStatus";


if not found then
    raise exception
        'TRANSACTION_STATE_UPDATE_FAILED';
end if;


/* ---------------------------------------------------------------------- */
/* RETURN                                                                 */
/* ---------------------------------------------------------------------- */

v_stage :=
    'return cash transfer result';


return query
select
    true,

    v_reference,

    v_financial_transaction_id::text,

    /*
     * Amount received by receiver.
     */
    v_amount::text,

    v_amount_usd::text,

    v_original_fee::text,

    v_cash_fee::text,

    v_others_amount::text,

    v_fee_payment_method,

    v_points_redeemed,

    v_redemption_ledger_id,

    v_loyalty_result,

    v_currency,

    v_receiver_notification_id,

    v_device_tokens,

    v_receiver_notification.title,

    v_receiver_notification.body,

    v_receiver_notification.payload
        ->> 'reference',

    /*
     * ----------------------------------------------------------
     * Financial Intelligence
     * ----------------------------------------------------------
     */

    /*
     * Resolved user ID, not transaction.s email/phone.
     */
    v_receiver.id,

    /*
     * Exact sender wallet debit.
     */
    v_principal_amount::text,

    /*
     * Exact sender wallet debit in USD.
     */
    v_sender_debit_usd::text;


exception
when others then

    get stacked diagnostics

        v_error_state =
            returned_sqlstate,

        v_error_message =
            message_text,

        v_error_detail =
            pg_exception_detail,

        v_error_hint =
            pg_exception_hint,

        v_error_context =
            pg_exception_context;


    raise exception using

        errcode =
            v_error_state,

        message =
            format(
                'CASH_TRANSFER_FAILED at [%s]: %s',
                v_stage,
                v_error_message
            ),

        detail =
            coalesce(
                nullif(
                    concat_ws(
                        E'\n',
                        nullif(
                            v_error_detail,
                            ''
                        ),
                        nullif(
                            v_error_context,
                            ''
                        )
                    ),
                    ''
                ),
                'No additional PostgreSQL context'
            ),

        hint =
            coalesce(
                nullif(
                    v_error_hint,
                    ''
                ),
                'Check the cash-transfer stage reported in the error'
            );

end;

$$;
ALTER FUNCTION "public"."cash_transfer"("p_sender_id" "text", "p_transaction" "jsonb", "p_transaction_type" "public"."TransactionType", "p_country_code" "text", "p_transaction_state_id" "text", "p_ip_address" "text", "p_fee_payment_method" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."cash_withdrawal"("p_agent_id" "text", "p_transaction" "jsonb", "p_transaction_type" "public"."TransactionType", "p_country_code" "text", "p_transaction_state_id" "text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "document_no" "text", "amount" "text", "amount_usd" "text", "sender_debit" "text", "sender_debit_usd" "text", "fee" "text", "tax" "text", "currency" "text", "user_notification_id" "text", "device_tokens" "text"[], "push_title" "text", "push_body" "text", "push_reference" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_decimals numeric := 100;

    v_amount numeric;
    v_amount_usd numeric(20, 6) := 0;

    v_currency text;
    v_reference text;
    v_user_id text;
    v_version text;

    /*
     * current_rates.rate_to_usd stores the number of
     * currency units equivalent to 1 USD.
     *
     * Example:
     *
     * BWP rate_to_usd = 13.437538
     *
     * Therefore:
     *
     * USD = BWP / 13.437538
     */
    v_rate_to_usd numeric;

    /*
     * Actual withdrawing-user wallet debit converted
     * to USD.
     */
    v_sender_debit_usd numeric(20, 6) := 0;

    v_fiscal_year integer;
    v_period integer;

    v_agent public.users%rowtype;
    v_user public.users%rowtype;
    v_treasury public.users%rowtype;

    v_transaction_state
        public.transaction_state%rowtype;

    v_mappings
        public.transaction_gl_mapping[];

    v_components
        public.posting_component[];

    v_component_totals
        public.component_totals;

    v_principal_amount numeric := 0;
    v_others_amount numeric := 0;

    v_fee numeric := 0;
    v_tax numeric := 0;
    v_commission_amount numeric := 0;

    v_tax_rate numeric := 0;
    v_commission_rate numeric := 0;

    v_aml_threshold numeric;

    v_user_notification
        public.notification_message;

    v_device_tokens text[] :=
        array[]::text[];

    v_document_prefix text;
    v_document_number text;

    v_financial_transaction_id bigint;
    v_user_notification_id text;

    v_stage text := 'initialization';
    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;

begin
    /*
     * ==========================================================
     * VALIDATE TRANSACTION TYPE
     * ==========================================================
     */
    v_stage := 'validate transaction type';

    if p_transaction_type <>
       'cash_withdrawal'::public."TransactionType"
    then
        raise exception
            'INVALID_CASH_WITHDRAWAL_TRANSACTION_TYPE_%',
            p_transaction_type;
    end if;


    /*
     * ==========================================================
     * VALIDATE AND LOCK TRANSACTION STATE
     * ==========================================================
     */
    v_stage :=
        'validate and lock transaction state';

    select transaction_state_record.*
    into v_transaction_state
    from public.transaction_state
        transaction_state_record
    where transaction_state_record.id =
          p_transaction_state_id
      and transaction_state_record.created_by =
          p_agent_id
      and transaction_state_record.transaction_type =
          p_transaction_type
      and transaction_state_record.country_code =
          p_country_code
      and transaction_state_record.status =
          'processing'::public."TransactionStatus"
    limit 1
    for update;

    if not found then
        raise exception
            'INVALID_TRANSACTION_STATE';
    end if;


    /*
     * Ensure the service-role call uses the transaction
     * that created the processing state.
     */
    v_stage :=
        'validate transaction state data';

    if v_transaction_state.transaction_data
       is distinct from p_transaction
    then
        raise exception
            'TRANSACTION_STATE_DATA_MISMATCH';
    end if;


    /*
     * ==========================================================
     * VALIDATE TRANSACTION VERSION
     * ==========================================================
     */
    v_stage := 'validate transaction version';

    v_version :=
        nullif(
            btrim(p_transaction ->> 'v'),
            ''
        );

    if v_version is distinct from 'v3' then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;


    /*
     * ==========================================================
     * PARSE TRANSACTION AMOUNT
     * ==========================================================
     */
    v_stage := 'parse transaction amount';

    v_amount :=
        (p_transaction ->> 'a')::numeric /
        v_decimals;

    if v_amount <= 0 then
        raise exception
            'INVALID_AMOUNT';
    end if;


    /*
     * ==========================================================
     * PARSE TRANSACTION CURRENCY
     * ==========================================================
     */
    v_stage := 'parse transaction currency';

    v_currency :=
        lower(
            nullif(
                btrim(p_transaction ->> 'c'),
                ''
            )
        );

    if v_currency is null then
        raise exception
            'CURRENCY_MISSING';
    end if;


    /*
     * ==========================================================
     * FETCH USD CONVERSION RATE
     * ==========================================================
     *
     * Cash withdrawal is a fiat transaction.
     *
     * USD:
     *
     *     USD value = amount
     *
     * Non-USD fiat:
     *
     *     USD value =
     *         amount / current_rates.rate_to_usd
     */
    v_stage := 'fetch USD conversion rate';

    if v_currency = 'usd' then
        v_rate_to_usd := 1;

    else
        select
            current_rate.rate_to_usd
        into
            v_rate_to_usd
        from public.current_rates
            current_rate
        where lower(current_rate.code) =
              lower(v_currency)
        limit 1;

        if not found
           or v_rate_to_usd is null
           or v_rate_to_usd <= 0
        then
            raise exception
                'CURRENT_RATE_NOT_FOUND_%',
                v_currency;
        end if;
    end if;


    /*
     * Convert the actual withdrawal amount to USD.
     */
    v_stage :=
        'calculate withdrawal amount USD';

    if v_currency = 'usd' then
        v_amount_usd :=
            round(
                v_amount,
                6
            );

    else
        v_amount_usd :=
            round(
                v_amount /
                v_rate_to_usd,
                6
            );
    end if;

    if v_amount_usd <= 0 then
        raise exception
            'INVALID_AMOUNT_USD';
    end if;


    /*
     * ==========================================================
     * PARSE TRANSACTION REFERENCE
     * ==========================================================
     */
    v_stage := 'parse transaction reference';

    v_reference :=
        nullif(
            btrim(p_transaction ->> 'r'),
            ''
        );

    if v_reference is null then
        raise exception
            'REFERENCE_MISSING';
    end if;


    /*
     * ==========================================================
     * PARSE WITHDRAWING USER
     * ==========================================================
     */
    v_stage := 'parse withdrawing user';

    v_user_id :=
        nullif(
            btrim(p_transaction ->> 's'),
            ''
        );

    if v_user_id is null then
        raise exception
            'USER_ID_MISSING';
    end if;

    if v_transaction_state.user_id
       is distinct from v_user_id
    then
        raise exception
            'TRANSACTION_USER_MISMATCH';
    end if;


    /*
     * ==========================================================
     * VALIDATE SENDER APPROVAL
     * ==========================================================
     */
    v_stage := 'validate sender approval';

    if v_transaction_state.sender_approval is null
       or jsonb_typeof(
           v_transaction_state.sender_approval
       ) <> 'object'
    then
        raise exception
            'SENDER_APPROVAL_IS_MISSING';
    end if;

    if (
        v_transaction_state.sender_approval
            ->> 'a'
       )::numeric <>
       (
        p_transaction ->> 'a'
       )::numeric
    then
        raise exception
            'AMOUNT_MISMATCH';
    end if;

    if lower(
        btrim(
            v_transaction_state.sender_approval
                ->> 'c'
        )
    ) is distinct from v_currency
    then
        raise exception
            'CURRENCY_MISMATCH';
    end if;

    if btrim(
        v_transaction_state.sender_approval
            ->> 'r'
    ) is distinct from v_reference
    then
        raise exception
            'REFERENCE_MISMATCH';
    end if;


    /*
     * ==========================================================
     * VALIDATE AGENT ROLE
     * ==========================================================
     */
    v_stage := 'validate agent role';

    if not public.user_has_role(
        p_agent_id,
        array[
            'agent'::public."Role",
            'vendor'::public."Role",
            'merchant'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'AGENT_NOT_AUTHORIZED';
    end if;


    /*
     * ==========================================================
     * VALIDATE WITHDRAWING USER ROLE
     * ==========================================================
     */
    v_stage := 'validate user role';

    if not public.user_has_role(
        v_user_id,
        array[
            'customer'::public."Role",
            'agent'::public."Role",
            'vendor'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'USER_NOT_AUTHORIZED';
    end if;


    /*
     * ==========================================================
     * FETCH PARTICIPANTS
     * ==========================================================
     */
    v_stage := 'fetch agent';

    v_agent :=
        public.fetch_user_by_id(
            p_agent_id
        );


    v_stage := 'fetch user';

    v_user :=
        public.fetch_user_by_id(
            v_user_id
        );


    v_stage := 'fetch treasury';

    v_treasury :=
        public.fetch_country_treasury(
            p_country_code
        );


    /*
     * ==========================================================
     * VALIDATE PARTICIPANTS
     * ==========================================================
     */
    v_stage := 'validate participants';

    if v_agent.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'AGENT_NOT_ACTIVE';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'USER_NOT_ACTIVE';
    end if;

    if v_agent.id = v_user.id then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    if v_agent.country_code is distinct from
       v_user.country_code
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    if v_agent.country_code is distinct from
       p_country_code
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;


    /*
     * ==========================================================
     * FETCH FISCAL PERIOD
     * ==========================================================
     */
    v_stage := 'fetch fiscal period';

    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        p_country_code
    ) as fiscal_period;

    if not found
       or v_fiscal_year is null
       or v_period is null
    then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * FETCH GL MAPPINGS
     * ==========================================================
     */
    v_stage := 'fetch GL mappings';

    select array_agg(mapping_record)
    into v_mappings
    from public.fetch_gl_mappings(
        p_transaction_type
    ) as mapping_record;

    if v_mappings is null
       or cardinality(v_mappings) = 0
    then
        raise exception
            'GL_MAPPINGS_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * BUILD POSTING COMPONENTS
     * ==========================================================
     */
    v_stage := 'build posting components';

    v_components :=
        public.build_posting_components(
            p_transaction_type,
            v_amount,
            v_mappings,
            p_country_code,
            v_currency,
            false
        );

    if v_components is null
       or cardinality(v_components) = 0
    then
        raise exception
            'POSTING_COMPONENTS_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * EXTRACT COMPONENT TOTALS
     * ==========================================================
     */
    v_stage := 'extract component totals';

    v_component_totals :=
        public.extract_component_totals(
            v_components,
            false
        );

    v_principal_amount :=
        v_component_totals.principal_amount;

    v_others_amount :=
        v_component_totals.others_amount;


    /*
     * Cash withdrawal is gross-mode.
     *
     * v_principal_amount is therefore the actual amount
     * removed from the withdrawing user's wallet.
     *
     * This includes the entered withdrawal amount plus
     * applicable cash charges.
     */
    if v_principal_amount < v_amount then
        raise exception
            'INVALID_FINAL_WITHDRAWAL_DEBIT';
    end if;


    /*
     * ==========================================================
     * CONVERT ACTUAL SENDER WALLET DEBIT TO USD
     * ==========================================================
     *
     * This must happen AFTER component calculation because
     * v_principal_amount is the authoritative wallet debit.
     */
    v_stage :=
        'calculate sender debit USD';

    if v_currency = 'usd' then
        v_sender_debit_usd :=
            round(
                v_principal_amount,
                6
            );

    else
        v_sender_debit_usd :=
            round(
                v_principal_amount /
                v_rate_to_usd,
                6
            );
    end if;

    if v_sender_debit_usd <= 0 then
        raise exception
            'INVALID_SENDER_DEBIT_USD_AMOUNT';
    end if;


    /*
     * ==========================================================
     * EXTRACT GOVERNMENT TAX
     * ==========================================================
     */
    v_stage := 'extract government tax';

    select coalesce(
        component.credit_amount,
        0
    )
    into v_tax
    from unnest(v_components) as component(
        component_type,
        debit_amount,
        credit_amount
    )
    where component.component_type =
          'government_tax'::public."ComponentType"
    limit 1;

    v_tax :=
        coalesce(
            v_tax,
            0
        );


    /*
     * ==========================================================
     * EXTRACT WITHDRAWAL FEE
     * ==========================================================
     */
    v_stage := 'extract withdrawal fee';

    select coalesce(
        component.credit_amount,
        0
    )
    into v_fee
    from unnest(v_components) as component(
        component_type,
        debit_amount,
        credit_amount
    )
    where component.component_type =
          'withdrawal_fee'::public."ComponentType"
    limit 1;

    v_fee :=
        coalesce(
            v_fee,
            0
        );


    /*
     * ==========================================================
     * EXTRACT AGENT COMMISSION
     * ==========================================================
     */
    v_stage := 'extract agent commission';

    select coalesce(
        component.credit_amount,
        0
    )
    into v_commission_amount
    from unnest(v_components) as component(
        component_type,
        debit_amount,
        credit_amount
    )
    where component.component_type =
          'agent_commission'::public."ComponentType"
    limit 1;

    v_commission_amount :=
        coalesce(
            v_commission_amount,
            0
        );


    /*
     * ==========================================================
     * VALIDATE REQUIRED CHARGES
     * ==========================================================
     */
    v_stage := 'validate charges';

    if v_tax <= 0 then
        raise exception
            'INVALID_TAX_AMOUNT';
    end if;

    if v_fee <= 0 then
        raise exception
            'INVALID_FEE_AMOUNT';
    end if;


    /*
     * ==========================================================
     * FETCH CONFIGURED RATES
     * ==========================================================
     */
    v_stage := 'fetch configured rates';

    v_tax_rate :=
        public.fetch_government_tax_rate(
            p_transaction_type,
            v_currency,
            p_country_code
        );

    v_commission_rate :=
        public.fetch_agent_commission_rate(
            p_transaction_type,
            v_currency,
            p_country_code
        );


    /*
     * ==========================================================
     * ENFORCE TRANSACTION LIMIT
     * ==========================================================
     *
     * v_principal_amount is the actual customer wallet
     * debit for this gross-mode transaction.
     */
    v_stage := 'enforce transaction limit';

    perform public.enforce_transaction_limit(
        v_user.id,
        v_fiscal_year,
        v_period,
        p_transaction_type,
        v_currency,
        v_principal_amount,
        p_country_code
    );


    /*
     * ==========================================================
     * FETCH AML CONFIGURATION
     * ==========================================================
     */
    v_stage := 'fetch AML configuration';

    select aml_config_record.threshold_amount
    into v_aml_threshold
    from public.aml_config aml_config_record
    where aml_config_record.transaction_type =
          p_transaction_type
      and lower(
          aml_config_record.country_code
      ) = lower(p_country_code)
      and lower(
          aml_config_record.currency_code
      ) = lower(v_currency)
      and aml_config_record.is_active = true
    limit 1;


    /*
     * ==========================================================
     * CREATE USER NOTIFICATION
     * ==========================================================
     */
    v_stage := 'create user notification';

    v_user_notification :=
        public.create_notification_message(
            p_country_code,
            p_transaction_type,
            'receiver'::public."NotificationAudience",
            v_amount,
            upper(v_currency),
            v_reference || '-01',
            0,
            coalesce(
                v_user.email,
                v_user.phone,
                v_user.id
            ),
            coalesce(
                v_agent.email,
                v_agent.phone,
                v_agent.id
            )
        );


    /*
     * ==========================================================
     * FETCH USER DEVICE TOKENS
     * ==========================================================
     */
    v_stage := 'fetch user device tokens';

    v_device_tokens :=
        coalesce(
            public.fetch_device_tokens(
                p_country_code,
                v_user.id
            ),
            array[]::text[]
        );


    /*
     * ==========================================================
     * GENERATE DOCUMENT NUMBER
     * ==========================================================
     */
    v_stage :=
        'fetch document number prefix';

    v_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            p_transaction_type
        );

    v_stage := 'generate document number';

    v_document_number :=
        public.generate_document_number(
            v_document_prefix,
            v_fiscal_year,
            v_period,
            p_country_code
        );


    /*
     * ==========================================================
     * CREATE AML FLAG
     * ==========================================================
     */
    v_stage := 'create AML flag';

    if v_aml_threshold is not null
       and v_amount >= v_aml_threshold
    then
        insert into public.system_flag (
            country_code,
            fiscal_year,
            period,
            flag_name,
            is_active,
            triggered_by,
            reason
        )
        values (
            p_country_code,
            v_fiscal_year,
            v_period,
            'AML_' || v_document_number,
            true,
            v_user.id,
            'Withdrawal above AML threshold'
        );
    end if;


    /*
     * ==========================================================
     * CREATE FINANCIAL TRANSACTION
     * ==========================================================
     */
    v_stage :=
        'insert financial transaction';

    insert into public.financial_transaction (
        document_number,
        fiscal_year,
        period,
        reference,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        country_code
    )
    values (
        v_document_number,
        v_fiscal_year,
        v_period,
        v_reference,
        p_transaction_type,
        'User ' ||
        coalesce(
            v_user.email,
            v_user.phone,
            v_user.id
        ) ||
        ' cash withdrawal from agent ' ||
        coalesce(
            v_agent.email,
            v_agent.phone,
            v_agent.id
        ),
        v_agent.id,
        v_amount,
        v_currency,
        p_country_code
    )
    returning id
    into v_financial_transaction_id;


    /*
     * ==========================================================
     * POST FINANCIAL ENTRIES
     * ==========================================================
     */
    v_stage := 'post financial entries';

    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_document_number,

        p_country_code =>
            p_country_code,

        p_transaction_id =>
            v_financial_transaction_id,

        p_transaction_type =>
            p_transaction_type,

        p_created_by =>
            v_agent.id,

        p_components =>
            v_components,

        p_mappings =>
            v_mappings,

        p_currency_code =>
            v_currency,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_reference =>
            v_reference,

        p_deposit_type =>
            null
    );


    /*
     * ==========================================================
     * POST WALLET ENTRIES
     * ==========================================================
     *
     * Withdrawing user:
     *
     *     debit = v_principal_amount
     *
     * Receiver agent:
     *
     *     credit = v_amount
     *
     * Therefore:
     *
     *     sender FI cash outflow =
     *         v_principal_amount
     *
     *     receiver FI cash inflow =
     *         v_amount
     */
    v_stage := 'post wallet entries';

    perform *
    from public.post_wallet_entries(
        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_document_number =>
            v_document_number,

        p_reference =>
            v_reference,

        p_receiver_id =>
            v_agent.id,

        p_sender_id =>
            v_user.id,

        p_transaction_type =>
            p_transaction_type,

        p_credit_amount =>
            v_amount,

        p_debit_amount =>
            v_principal_amount,

        p_sender_wallet_owner =>
            'customer'::public."WalletOwnerType",

        p_receiver_wallet_owner =>
            'agent'::public."WalletOwnerType",

        p_currency_code =>
            v_currency,

        p_country_code =>
            p_country_code,

        p_audit_action_type =>
            'cash_withdrawal'::public."AuditActionType",

        p_treasury_id =>
            v_treasury.id,

        p_fee_amount =>
            v_fee + v_tax,

        p_ip_address =>
            p_ip_address,

        p_receiver_notification =>
            null,

        p_sender_notification =>
            v_user_notification
    );


    /*
     * ==========================================================
     * FETCH USER NOTIFICATION ID
     * ==========================================================
     */
    v_stage := 'fetch user notification ID';

    select notification_record.id::text
    into v_user_notification_id
    from public.notifications notification_record
    where notification_record.user_id =
          v_user.id
      and notification_record.reference =
          v_user_notification.payload
              ->> 'reference'
      and notification_record.transaction_type =
          p_transaction_type
    order by notification_record.created_at desc
    limit 1;

    if not found then
        raise exception
            'USER_NOTIFICATION_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * RECORD AGENT COMMISSION
     * ==========================================================
     */
    v_stage := 'insert agent commission';

    if v_commission_amount > 0 then
        insert into public.agent_commission (
            agent_id,
            document_number,
            fiscal_year,
            period,
            transaction_type,
            currency_code,
            amount,
            fee_amount,
            commission_rate,
            commission_amount,
            is_settled,
            country_code
        )
        values (
            v_agent.id,
            v_document_number,
            v_fiscal_year,
            v_period,
            p_transaction_type,
            v_currency,
            v_amount,
            v_fee,
            coalesce(
                v_commission_rate,
                0
            ),
            v_commission_amount,
            false,
            p_country_code
        );
    end if;


    /*
     * ==========================================================
     * RECORD GOVERNMENT TAX PAYABLE
     * ==========================================================
     */
    v_stage :=
        'insert government tax payable';

    if v_tax > 0 then
        insert into public.government_tax_payable (
            document_number,
            fiscal_year,
            period,
            transaction_type,
            currency_code,
            gross_amount,
            tax_amount,
            tax_rate,
            is_settled,
            country_code
        )
        values (
            v_document_number,
            v_fiscal_year,
            v_period,
            p_transaction_type,
            v_currency,
            v_amount,
            v_tax,
            coalesce(
                v_tax_rate,
                0
            ),
            false,
            p_country_code
        );
    end if;


    /*
     * ==========================================================
     * MARK TRANSACTION SUCCESSFUL
     * ==========================================================
     */
    v_stage := 'update transaction state';

    update public.transaction_state
    set
        user_id =
            v_user.id,

        status =
            'success'::public."TransactionStatus",

        message =
            null,

        updated_at =
            now()
    where id =
          p_transaction_state_id
      and created_by =
          p_agent_id
      and user_id =
          v_user.id
      and transaction_type =
          p_transaction_type
      and status =
          'processing'::public."TransactionStatus";

    if not found then
        raise exception
            'TRANSACTION_STATE_UPDATE_FAILED';
    end if;


    /*
     * ==========================================================
     * RETURN RESULT
     * ==========================================================
     *
     * Financial Intelligence:
     *
     * WITHDRAWING USER
     *
     * amount
     *     = v_amount
     *
     * amount_usd
     *     = v_amount_usd
     *
     * cash_amount
     *     = v_principal_amount
     *
     * cash_amount_usd
     *     = v_sender_debit_usd
     *
     *
     * RECEIVING AGENT
     *
     * amount
     *     = v_amount
     *
     * amount_usd
     *     = v_amount_usd
     *
     * cash_amount
     *     = v_amount
     *
     * cash_amount_usd
     *     = v_amount_usd
     */
    v_stage :=
        'return cash withdrawal result';

    return query
    select
        true,
        v_document_number,
        v_amount::text,
        v_amount_usd::text,
        v_principal_amount::text,
        v_sender_debit_usd::text,
        v_fee::text,
        v_tax::text,
        v_currency,
        v_user_notification_id,
        v_device_tokens,
        v_user_notification.title,
        v_user_notification.body,
        v_user_notification.payload
            ->> 'reference';


exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;


        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'CASH_WITHDRAWAL_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                coalesce(
                    nullif(
                        concat_ws(
                            E'\n',
                            nullif(
                                v_error_detail,
                                ''
                            ),
                            nullif(
                                v_error_context,
                                ''
                            )
                        ),
                        ''
                    ),
                    'No additional PostgreSQL context'
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    'Check the cash-withdrawal stage reported in the error'
                );
end;
$$;
ALTER FUNCTION "public"."cash_withdrawal"("p_agent_id" "text", "p_transaction" "jsonb", "p_transaction_type" "public"."TransactionType", "p_country_code" "text", "p_transaction_state_id" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."change_my_user_role"("p_identifier" "text", "p_new_role" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_admin public.users%rowtype;
    v_target_user public.users%rowtype;

    v_old_role public.user_role%rowtype;
    v_new_role public.user_role%rowtype;

    v_identifier text;
    v_new_role_name text;

    v_fiscal_year integer;
    v_period integer;

    v_changed boolean := false;

    v_stage text := 'initialization';
    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * Authenticate and authorize the global system
     * administrator.
     */
    v_stage := 'authorize administrator';

    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if not public.has_role(
        array[
            'admin'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Validate input.
     */
    v_stage := 'validate input';

    v_identifier :=
        nullif(
            btrim(p_identifier),
            ''
        );

    v_new_role_name :=
        lower(
            nullif(
                btrim(p_new_role),
                ''
            )
        );

    if v_identifier is null then
        raise exception
            'USER_IDENTIFIER_REQUIRED';
    end if;

    if v_new_role_name is null then
        raise exception
            'NEW_ROLE_REQUIRED';
    end if;

    if v_new_role_name = 'admin' then
        raise exception
            'CANNOT_ASSIGN_ROLE';
    end if;

    /*
     * Fetch the administrator.
     */
    v_stage := 'fetch administrator';

    v_admin :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_admin.id is null then
        raise exception
            'ADMIN_USER_NOT_FOUND';
    end if;

    /*
     * Fetch the target user using email, phone or user ID.
     */
    v_stage := 'fetch target user';

    select user_record.*
    into v_target_user
    from public.users user_record
    where lower(
        coalesce(
            user_record.email,
            ''
        )
    ) =
        lower(v_identifier)

       or user_record.phone =
          v_identifier

       or user_record.id =
          v_identifier
    limit 1;

    if not found then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_target_user.id =
       v_admin.id
    then
        raise exception
            'CANNOT_CHANGE_OWN_ROLE';
    end if;

    if v_target_user.country_code is null
       or btrim(v_target_user.country_code) = ''
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Fetch the user's current role.
     */
    v_stage := 'fetch current role';

    select role_record.*
    into v_old_role
    from public.user_role role_record
    where role_record.id =
          v_target_user.role_id
    limit 1;

    if not found then
        raise exception
            'CURRENT_ROLE_NOT_FOUND';
    end if;

    /*
     * Fetch the requested role.
     */
    v_stage := 'fetch new role';

    select role_record.*
    into v_new_role
    from public.user_role role_record
    where lower(
        role_record.name::text
    ) =
        v_new_role_name
    limit 1;

    if not found then
        raise exception
            'ROLE_NOT_FOUND';
    end if;

    /*
     * Make the operation idempotent.
     *
     * If the database role is already correct, return the
     * user information so the Edge Function can retry the
     * Supabase Auth metadata update.
     */
    if v_target_user.role_id =
       v_new_role.id
    then
        return jsonb_build_object(
            'success',
            true,

            'changed',
            false,

            'user_id',
            v_target_user.id,

            'user_email',
            v_target_user.email,

            'user_phone',
            v_target_user.phone,

            'country_code',
            lower(
                v_target_user.country_code
            ),

            'old_role_name',
            lower(
                v_old_role.name::text
            ),

            'new_role_name',
            lower(
                v_new_role.name::text
            )
        );
    end if;

    /*
     * Use the target user's country for the fiscal period.
     */
    v_stage := 'fetch fiscal period';

    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_target_user.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Update the public application user.
     */
    v_stage := 'update user role';

    update public.users
    set
        role_id =
            v_new_role.id,

        updated_at =
            now()
    where id =
          v_target_user.id;

    if not found then
        raise exception
            'USER_ROLE_UPDATE_FAILED';
    end if;

    v_changed := true;

    /*
     * Audit the role change.
     */
    v_stage := 'create audit log';

    insert into public.audit_log (
        fiscal_year,
        period,
        country_code,
        document_number,
        user_id,
        action_type,
        entity_type,
        entity_id,
        old_value,
        new_value,
        metadata
    )
    values (
        v_fiscal_year,
        v_period,
        v_target_user.country_code,
        '',
        v_admin.id,
        'user_role_changed'::public."AuditActionType",
        'user',
        v_target_user.id,

        jsonb_build_object(
            'role_id',
            v_old_role.id,

            'role_name',
            lower(
                v_old_role.name::text
            )
        ),

        jsonb_build_object(
            'role_id',
            v_new_role.id,

            'role_name',
            lower(
                v_new_role.name::text
            )
        ),

        jsonb_build_object(
            'identifier',
            v_identifier,

            'user_email',
            v_target_user.email,

            'user_phone',
            v_target_user.phone,

            'changed_by',
            v_admin.id
        )
    );

    return jsonb_build_object(
        'success',
        true,

        'changed',
        v_changed,

        'user_id',
        v_target_user.id,

        'user_email',
        v_target_user.email,

        'user_phone',
        v_target_user.phone,

        'country_code',
        lower(
            v_target_user.country_code
        ),

        'old_role_name',
        lower(
            v_old_role.name::text
        ),

        'new_role_name',
        lower(
            v_new_role.name::text
        )
    );

exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;

        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'CHANGE_USER_ROLE_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                concat_ws(
                    E'\n',
                    nullif(
                        v_error_detail,
                        ''
                    ),
                    nullif(
                        v_error_context,
                        ''
                    )
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    format(
                        'Check the User Role Change stage: %s',
                        v_stage
                    )
                );
end;
$$;
ALTER FUNCTION "public"."change_my_user_role"("p_identifier" "text", "p_new_role" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."claim_country_liquidation_accounting_jobs"("p_country_code" "text", "p_batch_size" integer DEFAULT 25) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
    v_country_code text;
    v_claimed integer := 0;
    v_jobs jsonb := '[]'::jsonb;

    v_stage text := 'initialization';

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
BEGIN
    v_stage := 'authorize service role';

    IF coalesce(auth.role(), '') <> 'service_role' THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'SERVICE_ROLE_REQUIRED';
    END IF;

    v_stage := 'validate input';

    v_country_code :=
        lower(nullif(btrim(p_country_code), ''));

    IF v_country_code IS NULL THEN
        RAISE EXCEPTION 'COUNTRY_CODE_REQUIRED';
    END IF;

    IF p_batch_size IS NULL
       OR p_batch_size < 1
       OR p_batch_size > 100
    THEN
        RAISE EXCEPTION 'INVALID_LIQUIDATION_BATCH_SIZE';
    END IF;

    v_stage := 'lock country accounting claim';

    PERFORM pg_advisory_xact_lock(
        hashtext(
            format(
                'liquidation-accounting-claim:%s',
                v_country_code
            )
        )
    );

    v_stage := 'claim confirmed liquidation jobs';

    WITH candidate_jobs AS MATERIALIZED (
        SELECT j.id
        FROM public.liquidation_job AS j
        WHERE lower(btrim(j.country_code)) = v_country_code
          AND nullif(btrim(j.blockchain_code), '') IS NOT NULL
          AND (
              j.status::text IN (
                  'blockchain_confirmed',
                  'accounting_failed'
              )
              OR (
                  j.status::text = 'accounting_processing'
                  AND (
                      j.accounting_started_at IS NULL
                      OR j.accounting_started_at <=
                         now() - interval '5 minutes'
                  )
              )
          )
          AND EXISTS (
              SELECT 1
              FROM public.liquidation_blockchain_queue AS q
              WHERE q.id::text = j.blockchain_queue_id
                AND q.liquidation_job_id = j.id::text
                AND q.user_id = j.user_id
                AND lower(btrim(q.country_code)) =
                    v_country_code
                AND q.blockchain_code = j.blockchain_code
                AND q.document_number = j.document_number
                AND q.status::text = 'confirmed'
                AND q.tx_hash ~ '^0x[0-9A-Fa-f]{64}$'
                AND q.confirmed_at IS NOT NULL
                AND q.manual_review_required = false
          )
        ORDER BY j.created_at, j.id
        LIMIT p_batch_size
        FOR UPDATE OF j SKIP LOCKED
    ),
    claimed_jobs AS (
        UPDATE public.liquidation_job AS j
        SET
            status =
                'accounting_processing'::public."LiquidationJobStatus",
            accounting_started_at = now(),
            accounting_retry_count =
                CASE
                    WHEN j.status::text IN (
                        'accounting_failed',
                        'accounting_processing'
                    )
                    THEN coalesce(j.accounting_retry_count, 0) + 1
                    ELSE coalesce(j.accounting_retry_count, 0)
                END,
            error_message = NULL
        FROM candidate_jobs AS candidate
        WHERE j.id = candidate.id
        RETURNING
            j.id,
            lower(btrim(j.country_code)) AS country_code
    )
    SELECT
        count(*)::integer,
        coalesce(
            jsonb_agg(
                jsonb_build_object(
                    'job_id', claimed.id,
                    'country_code', claimed.country_code
                )
                ORDER BY claimed.id
            ),
            '[]'::jsonb
        )
    INTO v_claimed, v_jobs
    FROM claimed_jobs AS claimed;

    RETURN jsonb_build_object(
        'success', true,
        'country_code', v_country_code,
        'claimed', v_claimed,
        'jobs', v_jobs
    );

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_error_state = RETURNED_SQLSTATE,
            v_error_message = MESSAGE_TEXT,
            v_error_detail = PG_EXCEPTION_DETAIL,
            v_error_hint = PG_EXCEPTION_HINT,
            v_error_context = PG_EXCEPTION_CONTEXT;

        RAISE EXCEPTION USING
            ERRCODE = v_error_state,
            MESSAGE = format(
                'LIQUIDATION_ACCOUNTING_CLAIM_FAILED at [%s]: %s',
                v_stage,
                v_error_message
            ),
            DETAIL = concat_ws(
                E'\n',
                nullif(v_error_detail, ''),
                nullif(v_error_context, '')
            ),
            HINT = coalesce(
                nullif(v_error_hint, ''),
                'Check the liquidation accounting claim stage'
            );
END;
$_$;
ALTER FUNCTION "public"."claim_country_liquidation_accounting_jobs"("p_country_code" "text", "p_batch_size" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."claim_country_liquidation_blockchain_jobs"("p_country_code" "text", "p_batch_size" integer DEFAULT 25) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_country_code text;
    v_queue public.liquidation_blockchain_queue%rowtype;

    v_claimed integer := 0;
    v_jobs jsonb := '[]'::jsonb;
BEGIN
    IF coalesce(auth.role(), '') <> 'service_role' THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'SERVICE_ROLE_REQUIRED';
    END IF;

    v_country_code :=
        lower(nullif(btrim(p_country_code), ''));

    IF v_country_code IS NULL THEN
        RAISE EXCEPTION 'COUNTRY_CODE_REQUIRED';
    END IF;

    IF p_batch_size IS NULL
       OR p_batch_size < 1
       OR p_batch_size > 100
    THEN
        RAISE EXCEPTION 'INVALID_LIQUIDATION_BATCH_SIZE';
    END IF;

    PERFORM pg_advisory_xact_lock(
        hashtext(
            format(
                'liquidation-blockchain-claim:%s',
                v_country_code
            )
        )
    );

    /*
     * Submission started but no hash was recorded.
     * Do not authorize another submission after lease expiry.
     *
     * Preserve the signature and submission marker.
     */
    UPDATE public.liquidation_blockchain_queue AS q
    SET
        manual_review_required = true,
        error_message =
            'LIQUIDATION_SUBMISSION_OUTCOME_UNKNOWN',
        updated_at = now()
    WHERE lower(btrim(q.country_code)) = v_country_code
      AND q.submission_started_at IS NOT NULL
      AND q.tx_hash IS NULL
      AND q.manual_review_required = false
      AND q.status::text IN (
          'pending',
          'processing',
          'failed'
      )
      AND (
          q.lease_expires_at IS NULL
          OR q.lease_expires_at <= clock_timestamp()
      );

    /* Five attempts is a hard stop, including receipt-recovery attempts.
     * Do not interrupt a live fifth attempt: its worker may still succeed.
     * If its lease expires, make the failure visible for operator review.
     * Preserve actual error text rather than replacing it with only MAX.
     */
    UPDATE public.liquidation_blockchain_queue AS q
    SET status = 'failed'::public."BlockchainLiquidationStatus",
        manual_review_required = true,
        error_message = CASE
            WHEN nullif(btrim(q.error_message), '') IS NULL
                THEN 'LIQUIDATION_BLOCKCHAIN_MAX_ATTEMPTS_REACHED'
            WHEN q.error_message LIKE 'LIQUIDATION_BLOCKCHAIN_MAX_ATTEMPTS_REACHED%'
                THEN q.error_message
            ELSE 'LIQUIDATION_BLOCKCHAIN_MAX_ATTEMPTS_REACHED: ' || q.error_message
        END,
        lease_expires_at = NULL,
        updated_at = now()
    WHERE lower(btrim(q.country_code)) = v_country_code
      AND q.attempt_count >= 5
      AND q.manual_review_required = false
      AND q.status::text IN ('pending', 'processing', 'failed')
      AND (q.status::text <> 'processing'
           OR q.lease_expires_at IS NULL
           OR q.lease_expires_at <= clock_timestamp());

    UPDATE public.liquidation_job AS j
    SET status = 'failed'::public."LiquidationJobStatus",
        error_message = q.error_message
    FROM public.liquidation_blockchain_queue AS q
    WHERE q.liquidation_job_id = j.id::text
      AND j.blockchain_queue_id = q.id::text
      AND lower(btrim(j.country_code)) = v_country_code
      AND q.manual_review_required = true
      AND q.attempt_count >= 5
      AND q.status::text = 'failed'
      AND j.status::text IN ('pending', 'failed', 'blockchain_processing');

    /* Jobs with submission evidence are never recreated. A known hash
     * resumes receipt checking while attempts remain. No-hash recovery
     * requires that the submission marker has never been set. */
    FOR v_queue IN
        SELECT q.*
        FROM public.liquidation_blockchain_queue AS q
        WHERE lower(btrim(q.country_code)) = v_country_code
          AND q.manual_review_required = false
          AND (
              q.tx_hash IS NOT NULL
              OR q.submission_started_at IS NULL
          )
          AND q.attempt_count < 5
          AND (
              q.status::text IN ('pending', 'failed')
              OR (
                  q.status::text = 'processing'
                  AND (
                      q.lease_expires_at IS NULL
                      OR q.lease_expires_at <= clock_timestamp()
                  )
              )
          )
        ORDER BY q.created_at, q.id
        LIMIT p_batch_size
        FOR UPDATE OF q SKIP LOCKED
    LOOP
        IF nullif(btrim(v_queue.blockchain_code), '') IS NULL
           OR v_queue.blockchain_code IS DISTINCT FROM
              lower(btrim(v_queue.blockchain_code))
        THEN
            UPDATE public.liquidation_blockchain_queue
            SET
                manual_review_required = true,
                error_message =
                    'LIQUIDATION_BLOCKCHAIN_CODE_REQUIRED_OR_INVALID',
                updated_at = now()
            WHERE id = v_queue.id;

            CONTINUE;
        END IF;

        /*
         * Require the queue and original calculation to agree.
         * Never substitute a different chain during recovery.
         */
        PERFORM 1
        FROM public.liquidation_job AS j
        WHERE j.id::text = v_queue.liquidation_job_id
          AND j.user_id = v_queue.user_id
          AND lower(btrim(j.country_code)) = v_country_code
          AND j.blockchain_code = v_queue.blockchain_code
          AND j.blockchain_queue_id = v_queue.id::text
          AND j.document_number = v_queue.document_number
          AND j.status::text IN (
              'pending',
              'failed',
              'blockchain_processing'
          );

        IF NOT FOUND THEN
            UPDATE public.liquidation_blockchain_queue
            SET
                manual_review_required = true,
                error_message =
                    'LIQUIDATION_JOB_QUEUE_MISMATCH_OR_INVALID_STATE',
                updated_at = now()
            WHERE id = v_queue.id;

            CONTINUE;
        END IF;

        UPDATE public.liquidation_blockchain_queue
        SET
            status =
                'processing'::public."BlockchainLiquidationStatus",
            claimed_at = clock_timestamp(),
            lease_expires_at =
                clock_timestamp() + interval '5 minutes',
            attempt_count = attempt_count + 1,
            last_attempt_at = clock_timestamp(),
            updated_at = now()
        WHERE id = v_queue.id
        RETURNING * INTO v_queue;

        UPDATE public.liquidation_job
        SET
            status =
                'blockchain_processing'::public."LiquidationJobStatus"
        WHERE id::text = v_queue.liquidation_job_id
          AND blockchain_queue_id = v_queue.id::text
          AND blockchain_code = v_queue.blockchain_code
          AND status::text IN (
              'pending',
              'failed',
              'blockchain_processing'
          );

        IF NOT FOUND THEN
            UPDATE public.liquidation_blockchain_queue
            SET
                manual_review_required = true,
                error_message =
                    'LIQUIDATION_JOB_STATE_CHANGED',
                lease_expires_at = NULL,
                updated_at = now()
            WHERE id = v_queue.id;

            CONTINUE;
        END IF;

        v_jobs := v_jobs || jsonb_build_array(
            jsonb_build_object(
                'queue_id', v_queue.id::text,
                'liquidation_job_id', v_queue.liquidation_job_id,
                'user_id', v_queue.user_id,
                'wallet_index', v_queue.wallet_index,
                'treasury_id', v_queue.treasury_id,
                'sender_wallet_address',
                    v_queue.sender_wallet_address,
                'collateral',
                    trim_scale(v_queue.collateral)::text,
                'debt_repayment_amount',
                    trim_scale(v_queue.debt_repayment_amount)::text,
                'penalty_amount',
                    trim_scale(v_queue.penalty_amount)::text,
                'total_liquidation_proceeds',
                    trim_scale(v_queue.total_liquidation_proceeds)::text,
                'total_debt',
                    trim_scale(v_queue.total_debt)::text,
                'gold_price',
                    trim_scale(v_queue.gold_price)::text,
                'document_number', v_queue.document_number,
                'fiscal_year', v_queue.fiscal_year,
                'period', v_queue.period,
                'country_code',
                    lower(btrim(v_queue.country_code)),
                'blockchain_code', v_queue.blockchain_code,
                'retry_count', v_queue.retry_count,
                'attempt_count', v_queue.attempt_count,
                'manual_review_required',
                    v_queue.manual_review_required,
                'queue_status', v_queue.status::text,
                'tx_hash', v_queue.tx_hash,
                'claimed_at', v_queue.claimed_at,
                'lease_expires_at', v_queue.lease_expires_at,
                'signed_payload', v_queue.signed_payload
            )
        );

        v_claimed := v_claimed + 1;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'country_code', v_country_code,
        'claimed', v_claimed,
        'jobs', v_jobs
    );
END;
$$;
ALTER FUNCTION "public"."claim_country_liquidation_blockchain_jobs"("p_country_code" "text", "p_batch_size" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."close_my_fiscal_year"("p_fiscal_year" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_user public.users%rowtype;

    v_next_fiscal_year integer;

    v_period_count integer;
    v_open_period_count integer;
    v_closed_period_count integer;
BEGIN
    /*
     * Authentication
     */
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHENTICATED';
    END IF;

    /*
     * Authorization
     *
     * Only Finance can close a fiscal year.
     */
    IF NOT public.has_role(
        ARRAY[
            'finance'
        ]::text[]
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'FORBIDDEN';
    END IF;

    /*
     * Validate input.
     */
    IF p_fiscal_year IS NULL
       OR p_fiscal_year <= 0 THEN
        RAISE EXCEPTION USING
            ERRCODE = '22023',
            MESSAGE = 'INVALID_FISCAL_YEAR';
    END IF;

    /*
     * Fetch authenticated application user.
     */
    SELECT user_record.*
    INTO v_user
    FROM public.fetch_user_by_id(
        auth.uid()::text
    ) AS user_record;

    IF v_user.id IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'USER_NOT_FOUND';
    END IF;

    IF v_user.country_code IS NULL
       OR btrim(v_user.country_code) = '' THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'USER_COUNTRY_NOT_CONFIGURED';
    END IF;

    /*
     * Confirm that the fiscal year being closed
     * actually exists for this user's country.
     */
    SELECT COUNT(*)
    INTO v_period_count
    FROM public.fiscal_period_config AS fpc
    WHERE fpc.country_code = v_user.country_code
      AND fpc.fiscal_year = p_fiscal_year;

    IF v_period_count = 0 THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'FISCAL_YEAR_NOT_CONFIGURED';
    END IF;

    /*
     * The next fiscal year must already exist.
     *
     * Opening and closing remain separate operations:
     *
     * 1. Finance opens the next fiscal year.
     * 2. Finance separately closes the previous year.
     *
     * Opening the next year does NOT automatically
     * close this year.
     */
    v_next_fiscal_year :=
        p_fiscal_year + 1;

    IF NOT EXISTS (
        SELECT 1
        FROM public.fiscal_period_config AS fpc
        WHERE fpc.country_code = v_user.country_code
          AND fpc.fiscal_year = v_next_fiscal_year
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'NEXT_FISCAL_YEAR_NOT_OPEN';
    END IF;

    /*
     * Determine how many periods are still open.
     */
    SELECT COUNT(*)
    INTO v_open_period_count
    FROM public.fiscal_period_config AS fpc
    WHERE fpc.country_code = v_user.country_code
      AND fpc.fiscal_year = p_fiscal_year
      AND fpc.is_closed = false;

    /*
     * Prevent repeated closing.
     */
    IF v_open_period_count = 0 THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'FISCAL_YEAR_ALREADY_CLOSED';
    END IF;

    /*
     * Close every open period belonging to the
     * selected fiscal year.
     */
    UPDATE public.fiscal_period_config AS fpc
    SET
        is_closed = true,
        updated_at = CURRENT_TIMESTAMP,
        updated_by = auth.uid()::text
    WHERE fpc.country_code = v_user.country_code
      AND fpc.fiscal_year = p_fiscal_year
      AND fpc.is_closed = false;

    GET DIAGNOSTICS
        v_closed_period_count = ROW_COUNT;

    /*
     * Safety check.
     *
     * Every period that was open when this operation
     * started must have been updated.
     *
     * Raising here rolls back the transaction.
     */
    IF v_closed_period_count <> v_open_period_count THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'FISCAL_YEAR_CLOSE_INCOMPLETE';
    END IF;

    RETURN jsonb_build_object(
        'country_code',
        v_user.country_code,
        'fiscal_year',
        p_fiscal_year,
        'periods',
        v_period_count,
        'periods_closed',
        v_closed_period_count,
        'is_closed',
        true
    );
END;
$$;
ALTER FUNCTION "public"."close_my_fiscal_year"("p_fiscal_year" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."complete_gold_buy"("p_user_id" "text", "p_transaction" "jsonb", "p_country_code" "text", "p_transaction_state_id" "text", "p_blockchain_transaction_id" "text", "p_blockchain_code" "text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "document_number" "text", "quantity" "text", "total_spent" "text", "explorer_url" "text", "receiver_notification_id" "text", "device_tokens" "text"[], "push_title" "text", "push_body" "text", "push_reference" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_blockchain_code text;
    v_preparation record;
    v_transaction_state
        public.transaction_state%rowtype;
    v_blockchain_transaction
        public.blockchain_transaction%rowtype;
    v_user public.users%rowtype;
    v_treasury public.users%rowtype;
    v_fiat_mappings
        public.transaction_gl_mapping[];
    v_token_mappings
        public.transaction_gl_mapping[];
    v_fiat_components
        public.posting_component[];
    v_token_components
        public.posting_component[];
    v_receiver_notification
        public.notification_message;
    v_device_tokens text[] :=
        array[]::text[];
    v_document_number text;
    v_sub_document_number text;
    v_fiat_transaction_id bigint;
    v_token_transaction_id bigint;
    v_receiver_notification_id text;
    v_sub_transaction_type
        public."TransactionType" :=
            'gold_token_buy_sub_tx'::public."TransactionType";
    v_stage text := 'initialization';
    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    if coalesce(auth.role(), '') <> 'service_role' then
        raise exception using errcode = '42501', message = 'SERVICE_ROLE_REQUIRED';
    end if;
    v_blockchain_code := lower(nullif(btrim(p_blockchain_code), ''));
    if v_blockchain_code is null then
        raise exception 'BLOCKCHAIN_CODE_REQUIRED';
    end if;
    perform 1 from public.supported_blockchain b
    where b.code = v_blockchain_code and b.is_active = true
      and exists (
        select 1 from public.supported_blockchain_network n
        where n.blockchain_id = b.id and n.is_active = true
      );
    if not found then
        raise exception 'BLOCKCHAIN_NOT_FOUND_OR_INACTIVE';
    end if;
    /*
     * Lock the processing transaction state.
     */
    v_stage :=
        'validate and lock transaction state';
    select transaction_state_record.*
    into v_transaction_state
    from public.transaction_state
        transaction_state_record
    where transaction_state_record.id =
          p_transaction_state_id
      and transaction_state_record.created_by =
          p_user_id
      and transaction_state_record.user_id =
          p_user_id
      and transaction_state_record.country_code =
          p_country_code
      and transaction_state_record.transaction_type =
          'gold_token_buy'::public."TransactionType"
      and transaction_state_record.status =
          'processing'::public."TransactionStatus"
    limit 1
    for update;
    if not found then
        raise exception
            'INVALID_TRANSACTION_STATE';
    end if;
    if v_transaction_state.blockchain_code is distinct from v_blockchain_code then
        raise exception 'TRANSACTION_BLOCKCHAIN_MISMATCH';
    end if;
    if v_transaction_state.transaction_data
       is distinct from p_transaction
    then
        raise exception
            'TRANSACTION_STATE_DATA_MISMATCH';
    end if;
    /*
     * Lock and validate the pending blockchain row.
     */
    v_stage :=
        'validate and lock blockchain transaction';
    select blockchain_record.*
    into v_blockchain_transaction
    from public.blockchain_transaction
        blockchain_record
    where blockchain_record.id::text =
          p_blockchain_transaction_id
      and blockchain_record.created_by =
          p_user_id
      and blockchain_record.country_code =
          p_country_code
      and blockchain_record.reference =
          p_transaction ->> 'r'
      and blockchain_record.transaction_type =
          'gold_token_buy'::public."TransactionType"
      and blockchain_record.status =
          'pending'::public."BlockchainTxStatus"
    limit 1
    for update;
    if not found then
        raise exception
            'PENDING_BLOCKCHAIN_TRANSACTION_NOT_FOUND';
    end if;
    /*
     * Recalculate trusted pricing and quantities.
     */
    v_stage := 'prepare gold buy';
    select preparation.*
    into v_preparation
    from public.prepare_gold_buy(
        p_user_id,
        p_transaction,
        p_country_code,
        p_transaction_state_id,
        v_blockchain_code
    ) as preparation;
    if not found then
        raise exception
            'GOLD_BUY_PREPARATION_NOT_FOUND';
    end if;
    /*
     * Validate the transaction Gold price carried forward
     * from prepare_gold_buy.
     *
     * Do not fetch the current Gold market price again here.
     */
    if coalesce(
        v_preparation.gold_price::numeric,
        0
    ) <= 0
    then
        raise exception
            'INVALID_GOLD_PRICE';
    end if;
    /*
     * Confirm the blockchain row matches the trusted
     * preparation result.
     */
    v_stage :=
        'validate blockchain transaction values';
    if v_blockchain_transaction.chain::text is distinct from
       v_blockchain_code then
        raise exception 'BLOCKCHAIN_CHAIN_MISMATCH';
    end if;
    if v_blockchain_transaction.currency_code is distinct from v_preparation.input_currency then
        raise exception 'BLOCKCHAIN_CURRENCY_MISMATCH';
    end if;
    if v_blockchain_transaction.net_amount is distinct from 0::numeric then
        raise exception 'BLOCKCHAIN_NET_AMOUNT_MISMATCH';
    end if;
    if v_blockchain_transaction.quantity
       is distinct from
       v_preparation.token_quantity::numeric
    then
        raise exception
            'BLOCKCHAIN_QUANTITY_MISMATCH';
    end if;
    if v_blockchain_transaction.gross_amount
       is distinct from
       v_preparation.input_amount::numeric
    then
        raise exception
            'BLOCKCHAIN_GROSS_AMOUNT_MISMATCH';
    end if;
    if v_blockchain_transaction.fee_amount
       is distinct from
       v_preparation.token_fee::numeric
    then
        raise exception
            'BLOCKCHAIN_FEE_MISMATCH';
    end if;
    if lower(
        v_blockchain_transaction.sender
    ) is distinct from lower(
        v_preparation.treasury_wallet_address
    ) then
        raise exception
            'BLOCKCHAIN_SENDER_MISMATCH';
    end if;
    if lower(
        v_blockchain_transaction.receiver
    ) is distinct from lower(
        v_preparation.user_wallet_address
    ) then
        raise exception
            'BLOCKCHAIN_RECEIVER_MISMATCH';
    end if;
    /*
     * Fetch participants.
     */
    v_stage := 'fetch participants';
    v_user :=
        public.fetch_user_by_id(
            p_user_id
        );
    v_treasury :=
        public.fetch_country_treasury(
            p_country_code
        );
    /*
     * Rebuild fiat and token components for posting.
     */
    v_stage := 'fetch fiat mappings';
    select array_agg(mapping_record)
    into v_fiat_mappings
    from public.fetch_gl_mappings(
        'gold_token_buy'::public."TransactionType"
    ) as mapping_record;
    if v_fiat_mappings is null
       or cardinality(v_fiat_mappings) = 0
    then
        raise exception
            'GOLD_BUY_GL_MAPPINGS_NOT_FOUND';
    end if;
    v_stage := 'fetch token mappings';
    select array_agg(mapping_record)
    into v_token_mappings
    from public.fetch_gl_mappings(
        v_sub_transaction_type
    ) as mapping_record;
    if v_token_mappings is null
       or cardinality(v_token_mappings) = 0
    then
        raise exception
            'GOLD_BUY_TOKEN_GL_MAPPINGS_NOT_FOUND';
    end if;
    v_stage := 'build fiat components';
    v_fiat_components :=
        public.build_posting_components(
            'gold_token_buy'::public."TransactionType",
            v_preparation.input_amount::numeric,
            v_fiat_mappings,
            p_country_code,
            v_preparation.input_currency,
            false
        );
    v_stage := 'build token components';
    v_token_components :=
        public.build_posting_components(
            v_sub_transaction_type,
            v_preparation.input_amount::numeric,
            v_token_mappings,
            p_country_code,
            v_preparation.input_currency,
            true
        );
    if v_fiat_components is null
       or cardinality(v_fiat_components) = 0
    then
        raise exception
            'GOLD_BUY_COMPONENTS_NOT_FOUND';
    end if;
    if v_token_components is null
       or cardinality(v_token_components) = 0
    then
        raise exception
            'GOLD_BUY_TOKEN_COMPONENTS_NOT_FOUND';
    end if;
    /*
     * Build buyer notification.
     */
    v_stage := 'validate posting components';
    v_fiat_components := public.validate_components(v_fiat_components);
    v_token_components := public.validate_components(v_token_components);
    if not exists (
        select 1 from unnest(v_fiat_components) c
        where c.component_type = 'principal'::public."ComponentType"
          and c.debit_amount = v_preparation.gross_amount::numeric
    ) or not exists (
        select 1 from unnest(v_token_components) c
        where c.component_type = 'principal'::public."ComponentType"
          and public.round_down(c.debit_amount) = v_preparation.token_quantity::numeric
          and public.round_down(c.credit_amount) = v_preparation.gross_token_quantity::numeric
    ) then
        raise exception 'POSTING_PREPARATION_MISMATCH';
    end if;
    v_stage := 'create receiver notification';
    v_receiver_notification :=
        public.create_notification_message(
            p_country_code,
            'gold_token_buy'::public."TransactionType",
            'receiver'::public."NotificationAudience",
            v_preparation.gross_amount::numeric,
            'USD',
            p_transaction ->> 'r',
            v_preparation.token_quantity::numeric,
            coalesce(
                v_treasury.email,
                v_treasury.phone,
                v_treasury.id
            ),
            coalesce(
                v_user.email,
                v_user.phone,
                v_user.id
            )
        );
    v_stage := 'fetch receiver device tokens';
    v_device_tokens :=
        coalesce(
            public.fetch_device_tokens(
                p_country_code,
                v_user.id
            ),
            array[]::text[]
        );
    /*
     * Generate the main accounting document.
     */
    v_stage := 'generate document number';
    v_document_number :=
        public.generate_document_number(
            v_preparation.document_prefix,
            v_preparation.fiscal_year,
            v_preparation.period,
            p_country_code
        );
    /*
     * Fiat financial transaction.
     */
    v_stage :=
        'insert fiat financial transaction';
    insert into public.financial_transaction (
        document_number,
        fiscal_year,
        reference,
        period,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        country_code
    )
    values (
        v_document_number,
        v_preparation.fiscal_year,
        p_transaction ->> 'r',
        v_preparation.period,
        'gold_token_buy'::public."TransactionType",
        'User ' ||
        coalesce(
            v_user.email,
            v_user.phone,
            v_user.id
        ) ||
        ' purchased ' ||
        v_preparation.token_quantity ||
        'g Gold tokens at USD ' ||
        v_preparation.gold_price ||
        '/g',
        p_user_id,
        v_preparation.gross_amount::numeric,
        'usd',
        p_country_code
    )
    returning id
    into v_fiat_transaction_id;
    v_stage := 'post fiat financial entries';
    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_document_number,
        p_country_code =>
            p_country_code,
        p_transaction_id =>
            v_fiat_transaction_id,
        p_transaction_type =>
            'gold_token_buy'::public."TransactionType",
        p_created_by =>
            p_user_id,
        p_components =>
            v_fiat_components,
        p_mappings =>
            v_fiat_mappings,
        p_currency_code =>
            'usd',
        p_fiscal_year =>
            v_preparation.fiscal_year,
        p_period =>
            v_preparation.period,
        p_reference =>
            p_transaction ->> 'r',
        p_deposit_type =>
            null
    );
    /*
     * Move fiat from the buyer's customer wallet to
     * the treasury USD wallet.
     */
    v_stage := 'post fiat wallet entries';
    perform *
    from public.post_wallet_entries(
        p_fiscal_year =>
            v_preparation.fiscal_year,
        p_period =>
            v_preparation.period,
        p_document_number =>
            v_document_number,
        p_reference =>
            p_transaction ->> 'r',
        p_receiver_id =>
            v_treasury.id,
        p_sender_id =>
            v_user.id,
        p_transaction_type =>
            'gold_token_buy'::public."TransactionType",
        p_credit_amount =>
            v_preparation.gross_amount::numeric,
        p_debit_amount =>
            v_preparation.gross_amount::numeric,
        p_sender_wallet_owner =>
            'customer'::public."WalletOwnerType",
        p_receiver_wallet_owner =>
            'treasury'::public."WalletOwnerType",
        p_currency_code =>
            'usd',
        p_country_code =>
            p_country_code,
        p_audit_action_type =>
            'token_bought'::public."AuditActionType",
        p_treasury_id =>
            null,
        p_fee_amount =>
            0,
        p_ip_address =>
            p_ip_address,
        p_receiver_notification =>
            null,
        p_sender_notification =>
            null,
        p_blockchain_code => null
    );
    /*
     * Gold-token sub-document.
     */
    v_sub_document_number :=
        v_document_number || '-01';
    v_stage :=
        'insert token financial transaction';
    insert into public.financial_transaction (
        document_number,
        fiscal_year,
        reference,
        period,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        country_code
    )
    values (
        v_sub_document_number,
        v_preparation.fiscal_year,
        (p_transaction ->> 'r') || '-01',
        v_preparation.period,
        v_sub_transaction_type,
        'User ' ||
        coalesce(
            v_user.email,
            v_user.phone,
            v_user.id
        ) ||
        ' purchased ' ||
        v_preparation.gross_amount ||
        ' USD Gold tokens',
        p_user_id,
        v_preparation.gross_token_quantity::numeric,
        'gold',
        p_country_code
    )
    returning id
    into v_token_transaction_id;
    v_stage := 'post token financial entries';
    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_sub_document_number,
        p_country_code =>
            p_country_code,
        p_transaction_id =>
            v_token_transaction_id,
        p_transaction_type =>
            v_sub_transaction_type,
        p_created_by =>
            p_user_id,
        p_components =>
            v_token_components,
        p_mappings =>
            v_token_mappings,
        p_currency_code =>
            'gold',
        p_fiscal_year =>
            v_preparation.fiscal_year,
        p_period =>
            v_preparation.period,
        p_reference =>
            (p_transaction ->> 'r') || '-01',
        p_deposit_type =>
            null
    );
    /*
     * Move the net token quantity from treasury to buyer.
     */
    v_stage := 'post token wallet entries';
    select result.receiver_notification_id
    into v_receiver_notification_id
    from public.post_wallet_entries(
        p_fiscal_year =>
            v_preparation.fiscal_year,
        p_period =>
            v_preparation.period,
        p_document_number =>
            v_sub_document_number,
        p_reference =>
            (p_transaction ->> 'r') || '-01',
        p_receiver_id =>
            v_user.id,
        p_sender_id =>
            v_treasury.id,
        p_transaction_type =>
            'gold_token_buy'::public."TransactionType",
        p_credit_amount =>
            v_preparation.token_quantity::numeric,
        p_debit_amount =>
            v_preparation.token_quantity::numeric,
        p_sender_wallet_owner =>
            'treasury'::public."WalletOwnerType",
        p_receiver_wallet_owner =>
            'customer'::public."WalletOwnerType",
        p_currency_code =>
            'gold',
        p_country_code =>
            p_country_code,
        p_audit_action_type =>
            'token_bought'::public."AuditActionType",
        p_treasury_id =>
            null,
        p_fee_amount =>
            0,
        p_ip_address =>
            p_ip_address,
        p_receiver_notification =>
            v_receiver_notification,
        p_sender_notification =>
            null,
        p_blockchain_code => v_blockchain_code
    ) as result;
    /*
     * Complete the blockchain row.
     */
    v_stage :=
        'complete blockchain transaction';
    update public.blockchain_transaction
    set
        document_number =
            v_sub_document_number,
        status =
            'completed'::public."BlockchainTxStatus"
    where id::text =
          p_blockchain_transaction_id
      and chain = v_blockchain_code
      and status =
          'pending'::public."BlockchainTxStatus";
    if not found then
        raise exception
            'BLOCKCHAIN_TRANSACTION_UPDATE_FAILED';
    end if;
    /*
     * Mark transaction state successful.
     */
    v_stage := 'update transaction state';
    update public.transaction_state
    set
        user_id =
            v_user.id,
        status =
            'success'::public."TransactionStatus",
        message =
            null,
        updated_at =
            now()
    where id =
          p_transaction_state_id
      and created_by =
          p_user_id
      and blockchain_code = v_blockchain_code
      and transaction_type =
          'gold_token_buy'::public."TransactionType"
      and status =
          'processing'::public."TransactionStatus";
    if not found then
        raise exception
            'TRANSACTION_STATE_UPDATE_FAILED';
    end if;
    return query
    select
        true,
        v_document_number,
        v_preparation.token_quantity,
        v_preparation.gross_amount,
        v_blockchain_transaction.explorer_url,
        v_receiver_notification_id,
        v_device_tokens,
        v_receiver_notification.title,
        v_receiver_notification.body,
        v_receiver_notification.payload
            ->> 'reference';
exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,
            v_error_message =
                message_text,
            v_error_detail =
                pg_exception_detail,
            v_error_hint =
                pg_exception_hint,
            v_error_context =
                pg_exception_context;
        raise exception using
            errcode =
                v_error_state,
            message =
                format(
                    'GOLD_BUY_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),
            detail =
                coalesce(
                    nullif(
                        concat_ws(
                            E'\n',
                            nullif(
                                v_error_detail,
                                ''
                            ),
                            nullif(
                                v_error_context,
                                ''
                            )
                        ),
                        ''
                    ),
                    'No additional PostgreSQL context'
                ),
            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    'Check the gold-buy stage reported in the error'
                );
end;
$$;
ALTER FUNCTION "public"."complete_gold_buy"("p_user_id" "text", "p_transaction" "jsonb", "p_country_code" "text", "p_transaction_state_id" "text", "p_blockchain_transaction_id" "text", "p_blockchain_code" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."complete_gold_sell"("p_seller_id" "text", "p_transaction" "jsonb", "p_country_code" "text", "p_transaction_state_id" "text", "p_blockchain_transaction_id" "text", "p_blockchain_code" "text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "document_number" "text", "token_document_number" "text", "quantity" "text", "gross_amount" "text", "net_amount" "text", "fee" "text", "explorer_url" "text", "receiver_notification_id" "text", "device_tokens" "text"[], "push_title" "text", "push_body" "text", "push_reference" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_preparation record;

    v_seller public.users%rowtype;
    v_treasury public.users%rowtype;

    v_blockchain_transaction
        public.blockchain_transaction%rowtype;

    v_receiver_notification
        public.notification_message;

    v_device_tokens text[] :=
        array[]::text[];

    v_document_number text;
    v_token_document_number text;

    v_financial_transaction_id bigint;
    v_token_financial_transaction_id bigint;

    v_receiver_notification_id text;

    v_reference text;
    v_blockchain_code text;

    /*
     * Actual fiat amount moved between wallets.
     *
     * Fiat input:
     * The entered USD amount is the exact amount received.
     *
     * Gold input:
     * Use the debit side of the main sell principal.
     *
     * This preserves the existing settlement rules.
     */
    v_fiat_wallet_amount numeric;

    v_stage text := 'initialization';

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
BEGIN
    /*
     * ==========================================================
     * 1. SERVICE ROLE AUTHORIZATION
     * ==========================================================
     */
    v_stage := 'service role validation';

    IF coalesce(auth.role(), '') <> 'service_role' THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'SERVICE_ROLE_REQUIRED';
    END IF;

    /*
     * ==========================================================
     * 2. VALIDATE BLOCKCHAIN CODE
     * ==========================================================
     */
    v_stage := 'validate blockchain code';

    v_blockchain_code :=
        lower(nullif(btrim(p_blockchain_code), ''));

    IF v_blockchain_code IS NULL THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_CODE_REQUIRED';
    END IF;

    /*
     * ==========================================================
     * 3. PREPARE GOLD SELL
     * ==========================================================
     *
     * The preparation function validates:
     * - Processing transaction state
     * - Selected blockchain
     * - Seller and treasury
     * - Gold wallet balance on selected blockchain
     * - Pricing
     * - GL mappings
     * - Posting components
     */
    v_stage := 'prepare gold sell';

    SELECT preparation_record.*
    INTO v_preparation
    FROM public.prepare_gold_sell(
        p_seller_id,
        p_transaction,
        p_country_code,
        p_transaction_state_id,
        v_blockchain_code
    ) AS preparation_record;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'GOLD_SELL_PREPARATION_NOT_FOUND';
    END IF;

    IF v_preparation.blockchain_code
       IS DISTINCT FROM v_blockchain_code
    THEN
        RAISE EXCEPTION
            'PREPARATION_BLOCKCHAIN_MISMATCH';
    END IF;

    /*
     * Validate the exact customer sell price returned
     * by the preparation function.
     *
     * Do not fetch the market price again here.
     */
    v_stage := 'validate gold price';

    IF coalesce(
        v_preparation.gold_price::numeric,
        0
    ) <= 0 THEN
        RAISE EXCEPTION
            'INVALID_GOLD_PRICE';
    END IF;

    /*
     * ==========================================================
     * 4. DETERMINE FIAT WALLET SETTLEMENT AMOUNT
     * ==========================================================
     */
    v_stage := 'resolve fiat wallet amount';

    IF lower(btrim(v_preparation.input_currency)) <> 'gold' THEN

        /*
         * FIAT INPUT
         *
         * The customer receives exactly the entered
         * USD amount.
         */
        v_fiat_wallet_amount :=
            v_preparation.input_amount::numeric;

    ELSE

        /*
         * GOLD INPUT
         *
         * Use the debit side of the main principal
         * component, preserving the existing logic.
         */
        SELECT
            component_record.debit_amount
        INTO
            v_fiat_wallet_amount
        FROM unnest(
            v_preparation.sell_components
        ) AS component_record
        WHERE component_record.component_type =
              'principal'::public."ComponentType"
        LIMIT 1;

        IF v_fiat_wallet_amount IS NULL THEN
            RAISE EXCEPTION
                'GOLD_SELL_PRINCIPAL_COMPONENT_NOT_FOUND';
        END IF;

    END IF;

    IF v_fiat_wallet_amount IS NULL
       OR v_fiat_wallet_amount <= 0
    THEN
        RAISE EXCEPTION
            'INVALID_FIAT_WALLET_AMOUNT';
    END IF;

    /*
     * ==========================================================
     * 5. VALIDATE TRANSACTION REFERENCE
     * ==========================================================
     */
    v_stage := 'validate transaction reference';

    v_reference :=
        nullif(
            btrim(p_transaction ->> 'r'),
            ''
        );

    IF v_reference IS NULL THEN
        RAISE EXCEPTION
            'REFERENCE_IS_REQUIRED';
    END IF;

    /*
     * ==========================================================
     * 6. LOCK PENDING BLOCKCHAIN TRANSACTION
     * ==========================================================
     */
    v_stage := 'lock blockchain transaction';

    SELECT blockchain_record.*
    INTO v_blockchain_transaction
    FROM public.blockchain_transaction AS blockchain_record
    WHERE blockchain_record.id::text =
          p_blockchain_transaction_id
      AND blockchain_record.created_by =
          p_seller_id
      AND blockchain_record.reference =
          v_reference
      AND blockchain_record.transaction_type =
          'gold_token_sell'::public."TransactionType"
      AND blockchain_record.status =
          'pending'::public."BlockchainTxStatus"
      AND blockchain_record.chain =
          v_blockchain_code
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'INVALID_BLOCKCHAIN_TRANSACTION';
    END IF;

    /*
     * ==========================================================
     * 7. VALIDATE BLOCKCHAIN TRANSACTION
     * ==========================================================
     */
    v_stage := 'validate blockchain transaction';

    IF lower(v_blockchain_transaction.sender)
       IS DISTINCT FROM
       lower(v_preparation.seller_wallet_address)
    THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_SELLER_MISMATCH';
    END IF;

    IF lower(v_blockchain_transaction.receiver)
       IS DISTINCT FROM
       lower(v_preparation.treasury_wallet_address)
    THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_TREASURY_MISMATCH';
    END IF;

    IF v_blockchain_transaction.quantity
       IS DISTINCT FROM
       v_preparation.token_quantity::numeric
    THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_QUANTITY_MISMATCH';
    END IF;

    IF coalesce(
        v_blockchain_transaction.gross_amount,
        0
    ) IS DISTINCT FROM
       v_preparation.gross_amount::numeric
    THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_GROSS_AMOUNT_MISMATCH';
    END IF;

    IF coalesce(
        v_blockchain_transaction.net_amount,
        0
    ) IS DISTINCT FROM
       v_preparation.net_amount::numeric
    THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_NET_AMOUNT_MISMATCH';
    END IF;

    IF coalesce(
        v_blockchain_transaction.fee_amount,
        0
    ) IS DISTINCT FROM
       v_preparation.token_fee_equivalent::numeric
    THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_FEE_AMOUNT_MISMATCH';
    END IF;

    IF lower(
        btrim(v_blockchain_transaction.country_code)
    ) IS DISTINCT FROM
       lower(btrim(v_preparation.country_code))
    THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_COUNTRY_MISMATCH';
    END IF;

    /*
     * ==========================================================
     * 8. FETCH SELLER AND TREASURY
     * ==========================================================
     */
    v_stage := 'fetch seller and treasury';

    v_seller :=
        public.fetch_user_by_id(
            v_preparation.seller_id
        );

    v_treasury :=
        public.fetch_user_by_id(
            v_preparation.treasury_id
        );

    IF v_seller.id IS NULL THEN
        RAISE EXCEPTION
            'SELLER_NOT_FOUND';
    END IF;

    IF v_treasury.id IS NULL THEN
        RAISE EXCEPTION
            'TREASURY_NOT_FOUND';
    END IF;

    /*
     * ==========================================================
     * 9. CREATE SELLER NOTIFICATION
     * ==========================================================
     *
     * The seller receives the USD wallet settlement.
     */
    v_stage := 'create seller notification';

    v_receiver_notification :=
        public.create_notification_message(
            v_preparation.country_code,
            'gold_token_sell'::public."TransactionType",
            'receiver'::public."NotificationAudience",
            v_fiat_wallet_amount,
            'USD',
            v_reference,
            v_preparation.token_quantity::numeric,
            coalesce(
                v_treasury.email,
                v_treasury.phone,
                v_treasury.id
            ),
            coalesce(
                v_seller.email,
                v_seller.phone,
                v_seller.id
            )
        );

    /*
     * ==========================================================
     * 10. FETCH DEVICE TOKENS
     * ==========================================================
     */
    v_stage := 'fetch seller device tokens';

    v_device_tokens :=
        coalesce(
            public.fetch_device_tokens(
                v_preparation.country_code,
                v_seller.id
            ),
            array[]::text[]
        );

    /*
     * ==========================================================
     * 11. GENERATE DOCUMENT NUMBERS
     * ==========================================================
     */
    v_stage := 'generate main document number';

    v_document_number :=
        public.generate_document_number(
            v_preparation.document_prefix,
            v_preparation.fiscal_year,
            v_preparation.period,
            v_preparation.country_code
        );

    IF v_document_number IS NULL
       OR btrim(v_document_number) = ''
    THEN
        RAISE EXCEPTION
            'DOCUMENT_NUMBER_GENERATION_FAILED';
    END IF;

    v_token_document_number :=
        v_document_number || '-01';

    /*
     * ==========================================================
     * 12. INSERT FIAT FINANCIAL TRANSACTION
     * ==========================================================
     */
    v_stage := 'insert fiat financial transaction';

    INSERT INTO public.financial_transaction (
        document_number,
        fiscal_year,
        period,
        reference,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        country_code
    )
    VALUES (
        v_document_number,
        v_preparation.fiscal_year,
        v_preparation.period,
        v_reference,
        'gold_token_sell'::public."TransactionType",

        'User ' ||
        coalesce(
            v_seller.email,
            v_seller.phone,
            v_seller.id
        ) ||
        ' sold ' ||
        v_preparation.token_quantity ||
        'g Gold tokens at USD ' ||
        v_preparation.gold_price ||
        '/g',

        v_seller.id,
        v_preparation.gross_amount::numeric,
        'usd',
        v_preparation.country_code
    )
    RETURNING id
    INTO v_financial_transaction_id;

    /*
     * ==========================================================
     * 13. POST FIAT GL ENTRIES
     * ==========================================================
     */
    v_stage := 'post fiat financial entries';

    PERFORM *
    FROM public.post_financial_entries(
        p_document_number =>
            v_document_number,

        p_country_code =>
            v_preparation.country_code,

        p_transaction_id =>
            v_financial_transaction_id,

        p_transaction_type =>
            'gold_token_sell'::public."TransactionType",

        p_created_by =>
            v_seller.id,

        p_components =>
            v_preparation.sell_components,

        p_mappings =>
            v_preparation.sell_mappings,

        p_currency_code =>
            'usd',

        p_fiscal_year =>
            v_preparation.fiscal_year,

        p_period =>
            v_preparation.period,

        p_reference =>
            v_reference,

        p_deposit_type =>
            null
    );

    /*
     * ==========================================================
     * 14. POST USD WALLET ENTRIES
     * ==========================================================
     *
     * Treasury USD wallet:
     *     Debit
     *
     * Seller customer USD wallet:
     *     Credit
     *
     * USD wallets are not blockchain-specific.
     * p_blockchain_code must remain NULL.
     */
    v_stage := 'post fiat wallet entries';

    SELECT wallet_result.receiver_notification_id
    INTO v_receiver_notification_id
    FROM public.post_wallet_entries(
        p_fiscal_year =>
            v_preparation.fiscal_year,

        p_period =>
            v_preparation.period,

        p_document_number =>
            v_document_number,

        p_reference =>
            v_reference,

        p_receiver_id =>
            v_seller.id,

        p_sender_id =>
            v_treasury.id,

        p_transaction_type =>
            'gold_token_sell'::public."TransactionType",

        p_credit_amount =>
            v_fiat_wallet_amount,

        p_debit_amount =>
            v_fiat_wallet_amount,

        p_sender_wallet_owner =>
            'treasury'::public."WalletOwnerType",

        p_receiver_wallet_owner =>
            'customer'::public."WalletOwnerType",

        p_currency_code =>
            'usd',

        p_country_code =>
            v_preparation.country_code,

        p_audit_action_type =>
            'token_sold'::public."AuditActionType",

        p_treasury_id =>
            null,

        p_fee_amount =>
            0,

        p_ip_address =>
            p_ip_address,

        p_receiver_notification =>
            v_receiver_notification,

        p_sender_notification =>
            null,

        p_blockchain_code =>
            null
    ) AS wallet_result;

    /*
     * ==========================================================
     * 15. INSERT GOLD FINANCIAL TRANSACTION
     * ==========================================================
     */
    v_stage := 'insert token financial transaction';

    INSERT INTO public.financial_transaction (
        document_number,
        fiscal_year,
        period,
        reference,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        country_code
    )
    VALUES (
        v_token_document_number,
        v_preparation.fiscal_year,
        v_preparation.period,
        v_reference || '-01',
        'gold_token_sell_sub_tx'::public."TransactionType",

        'User ' ||
        coalesce(
            v_seller.email,
            v_seller.phone,
            v_seller.id
        ) ||
        ' transferred ' ||
        v_preparation.token_quantity ||
        'g Gold tokens to treasury on ' ||
        v_blockchain_code,

        v_seller.id,
        v_preparation.token_quantity::numeric,
        'gold',
        v_preparation.country_code
    )
    RETURNING id
    INTO v_token_financial_transaction_id;

    /*
     * ==========================================================
     * 16. POST GOLD GL ENTRIES
     * ==========================================================
     */
    v_stage := 'post token financial entries';

    PERFORM *
    FROM public.post_financial_entries(
        p_document_number =>
            v_token_document_number,

        p_country_code =>
            v_preparation.country_code,

        p_transaction_id =>
            v_token_financial_transaction_id,

        p_transaction_type =>
            'gold_token_sell_sub_tx'::public."TransactionType",

        p_created_by =>
            v_seller.id,

        p_components =>
            v_preparation.token_components,

        p_mappings =>
            v_preparation.token_mappings,

        p_currency_code =>
            'gold',

        p_fiscal_year =>
            v_preparation.fiscal_year,

        p_period =>
            v_preparation.period,

        p_reference =>
            v_reference || '-01',

        p_deposit_type =>
            null
    );

    /*
     * ==========================================================
     * 17. POST BLOCKCHAIN-SPECIFIC GOLD WALLET ENTRIES
     * ==========================================================
     *
     * Seller customer Gold wallet:
     *     Debit token_quantity
     *
     * Treasury Gold wallet:
     *     Credit token_quantity
     *
     * Both wallets belong to the selected blockchain.
     *
     * No additional Gold fee is transferred.
     */
    v_stage := 'post token wallet entries';

    PERFORM *
    FROM public.post_wallet_entries(
        p_fiscal_year =>
            v_preparation.fiscal_year,

        p_period =>
            v_preparation.period,

        p_document_number =>
            v_token_document_number,

        p_reference =>
            v_reference || '-01',

        p_receiver_id =>
            v_treasury.id,

        p_sender_id =>
            v_seller.id,

        p_transaction_type =>
            'gold_token_sell'::public."TransactionType",

        p_credit_amount =>
            v_preparation.token_quantity::numeric,

        p_debit_amount =>
            v_preparation.token_quantity::numeric,

        p_sender_wallet_owner =>
            'customer'::public."WalletOwnerType",

        p_receiver_wallet_owner =>
            'treasury'::public."WalletOwnerType",

        p_currency_code =>
            'gold',

        p_country_code =>
            v_preparation.country_code,

        p_audit_action_type =>
            'token_sold'::public."AuditActionType",

        p_treasury_id =>
            null,

        p_fee_amount =>
            0,

        p_ip_address =>
            p_ip_address,

        p_receiver_notification =>
            null,

        p_sender_notification =>
            null,

        p_blockchain_code =>
            v_blockchain_code
    );

    /*
     * ==========================================================
     * 18. COMPLETE BLOCKCHAIN TRANSACTION
     * ==========================================================
     */
    v_stage := 'complete blockchain transaction';

    UPDATE public.blockchain_transaction
    SET
        document_number =
            v_token_document_number,

        status =
            'completed'::public."BlockchainTxStatus"

    WHERE id::text =
          p_blockchain_transaction_id
      AND chain =
          v_blockchain_code
      AND status =
          'pending'::public."BlockchainTxStatus";

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_TRANSACTION_UPDATE_FAILED';
    END IF;

    /*
     * ==========================================================
     * 19. COMPLETE TRANSACTION STATE
     * ==========================================================
     */
    v_stage := 'complete transaction state';

    UPDATE public.transaction_state
    SET
        user_id =
            v_seller.id,

        status =
            'success'::public."TransactionStatus",

        message =
            null,

        updated_at =
            now()

    WHERE id =
          p_transaction_state_id
      AND created_by =
          p_seller_id
      AND transaction_type =
          'gold_token_sell'::public."TransactionType"
      AND blockchain_code =
          v_blockchain_code
      AND status =
          'processing'::public."TransactionStatus";

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'TRANSACTION_STATE_UPDATE_FAILED';
    END IF;

    /*
     * ==========================================================
     * 20. RETURN COMPLETION RESULT
     * ==========================================================
     *
     * Financial gross and net values remain unchanged.
     * Fiat wallet settlement is calculated separately.
     */
    v_stage := 'return gold sell result';

    RETURN QUERY
    SELECT
        true,
        v_document_number,
        v_token_document_number,
        v_preparation.token_quantity,
        v_preparation.gross_amount,
        v_preparation.net_amount,
        v_preparation.fiat_fee,
        v_blockchain_transaction.explorer_url,
        v_receiver_notification_id,
        v_device_tokens,
        v_receiver_notification.title,
        v_receiver_notification.body,
        v_receiver_notification.payload
            ->> 'reference';

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_error_state =
                RETURNED_SQLSTATE,

            v_error_message =
                MESSAGE_TEXT,

            v_error_detail =
                PG_EXCEPTION_DETAIL,

            v_error_hint =
                PG_EXCEPTION_HINT,

            v_error_context =
                PG_EXCEPTION_CONTEXT;

        RAISE EXCEPTION USING
            ERRCODE =
                v_error_state,

            MESSAGE =
                format(
                    'GOLD_SELL_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            DETAIL =
                coalesce(
                    nullif(
                        concat_ws(
                            E'\n',
                            nullif(v_error_detail, ''),
                            nullif(v_error_context, '')
                        ),
                        ''
                    ),
                    'No additional PostgreSQL context'
                ),

            HINT =
                coalesce(
                    nullif(v_error_hint, ''),
                    'Check the Gold Sell stage reported in the error'
                );
END;
$$;
ALTER FUNCTION "public"."complete_gold_sell"("p_seller_id" "text", "p_transaction" "jsonb", "p_country_code" "text", "p_transaction_state_id" "text", "p_blockchain_transaction_id" "text", "p_blockchain_code" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."complete_gold_transfer"("p_sender_id" "text", "p_transaction" "jsonb", "p_country_code" "text", "p_transaction_state_id" "text", "p_blockchain_transaction_id" "text", "p_ip_address" "text" DEFAULT NULL::"text", "p_blockchain_code" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "document_number" "text", "amount" "text", "fee" "text", "explorer_url" "text", "receiver_notification_id" "text", "device_tokens" "text"[], "push_title" "text", "push_body" "text", "push_reference" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_preparation record;
    v_sender public.users%rowtype;
    v_receiver public.users%rowtype;
    v_blockchain_transaction public.blockchain_transaction%rowtype;
    v_sender_notification public.notification_message;
    v_receiver_notification public.notification_message;
    v_device_tokens text[] := ARRAY[]::text[];
    v_document_number text;
    v_financial_transaction_id bigint;
    v_receiver_notification_id text;
    v_reference text;
    v_blockchain_code text;
    v_stage text := 'initialization';
    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
BEGIN
    IF coalesce(auth.role(), '') <> 'service_role' THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'SERVICE_ROLE_REQUIRED';
    END IF;

    v_stage := 'validate blockchain code';

    v_blockchain_code :=
        lower(nullif(btrim(p_blockchain_code), ''));

    IF v_blockchain_code IS NULL THEN
        RAISE EXCEPTION 'BLOCKCHAIN_CODE_REQUIRED';
    END IF;

    v_stage := 'prepare gold transfer';

    SELECT preparation_record.*
    INTO v_preparation
    FROM public.prepare_gold_transfer(
        p_sender_id,
        p_transaction,
        p_country_code,
        p_transaction_state_id,
        v_blockchain_code
    ) AS preparation_record;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'GOLD_TRANSFER_PREPARATION_NOT_FOUND';
    END IF;

    IF v_preparation.blockchain_code
       IS DISTINCT FROM v_blockchain_code THEN
        RAISE EXCEPTION 'TRANSACTION_BLOCKCHAIN_MISMATCH';
    END IF;

    v_reference :=
        nullif(btrim(p_transaction ->> 'r'), '');

    IF v_reference IS NULL THEN
        RAISE EXCEPTION 'REFERENCE_IS_REQUIRED';
    END IF;

    v_stage := 'lock blockchain transaction';

    SELECT blockchain_record.*
    INTO v_blockchain_transaction
    FROM public.blockchain_transaction AS blockchain_record
    WHERE blockchain_record.id::text = p_blockchain_transaction_id
      AND blockchain_record.created_by = p_sender_id
      AND blockchain_record.reference = v_reference
      AND blockchain_record.transaction_type =
          'gold_token_transfer'::public."TransactionType"
      AND blockchain_record.status =
          'pending'::public."BlockchainTxStatus"
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'INVALID_BLOCKCHAIN_TRANSACTION';
    END IF;

    v_stage := 'validate blockchain transaction';

    IF lower(btrim(v_blockchain_transaction.chain))
       IS DISTINCT FROM v_blockchain_code THEN
        RAISE EXCEPTION 'BLOCKCHAIN_CODE_MISMATCH';
    END IF;

    IF lower(v_blockchain_transaction.sender)
       IS DISTINCT FROM
       lower(v_preparation.sender_wallet_address) THEN
        RAISE EXCEPTION 'BLOCKCHAIN_SENDER_MISMATCH';
    END IF;

    IF lower(v_blockchain_transaction.receiver)
       IS DISTINCT FROM
       lower(v_preparation.receiver_wallet_address) THEN
        RAISE EXCEPTION 'BLOCKCHAIN_RECEIVER_MISMATCH';
    END IF;

    IF v_blockchain_transaction.quantity
       IS DISTINCT FROM v_preparation.amount::numeric THEN
        RAISE EXCEPTION 'BLOCKCHAIN_QUANTITY_MISMATCH';
    END IF;

    IF coalesce(v_blockchain_transaction.fee_amount, 0)
       IS DISTINCT FROM v_preparation.fee::numeric THEN
        RAISE EXCEPTION 'BLOCKCHAIN_FEE_MISMATCH';
    END IF;

    IF lower(btrim(v_blockchain_transaction.currency_code))
       IS DISTINCT FROM 'gold' THEN
        RAISE EXCEPTION 'INVALID_BLOCKCHAIN_CURRENCY';
    END IF;

    v_stage := 'fetch transfer users';

    v_sender :=
        public.fetch_user_by_id(v_preparation.sender_id);

    v_receiver :=
        public.fetch_user_by_id(v_preparation.receiver_id);

    IF v_sender.id IS NULL THEN
        RAISE EXCEPTION 'SENDER_NOT_FOUND';
    END IF;

    IF v_receiver.id IS NULL THEN
        RAISE EXCEPTION 'RECEIVER_NOT_FOUND';
    END IF;

    v_stage := 'create sender notification';

    v_sender_notification :=
        public.create_notification_message(
            v_preparation.country_code,
            'gold_token_transfer'::public."TransactionType",
            'sender'::public."NotificationAudience",
            v_preparation.amount::numeric,
            'GOLD',
            v_reference || '-01',
            v_preparation.amount::numeric,
            coalesce(v_sender.email, v_sender.phone, v_sender.id),
            coalesce(v_receiver.email, v_receiver.phone, v_receiver.id)
        );

    v_stage := 'create receiver notification';

    v_receiver_notification :=
        public.create_notification_message(
            v_preparation.country_code,
            'gold_token_transfer'::public."TransactionType",
            'receiver'::public."NotificationAudience",
            v_preparation.amount::numeric,
            'GOLD',
            v_reference || '-02',
            v_preparation.amount::numeric,
            coalesce(v_sender.email, v_sender.phone, v_sender.id),
            coalesce(v_receiver.email, v_receiver.phone, v_receiver.id)
        );

    v_stage := 'fetch receiver device tokens';

    v_device_tokens :=
        coalesce(
            public.fetch_device_tokens(
                v_preparation.country_code,
                v_receiver.id
            ),
            ARRAY[]::text[]
        );

    v_stage := 'generate document number';

    v_document_number :=
        public.generate_document_number(
            v_preparation.document_prefix,
            v_preparation.fiscal_year,
            v_preparation.period,
            v_preparation.country_code
        );

    IF nullif(btrim(v_document_number), '') IS NULL THEN
        RAISE EXCEPTION 'DOCUMENT_NUMBER_GENERATION_FAILED';
    END IF;

    v_stage := 'insert financial transaction';

    INSERT INTO public.financial_transaction (
        document_number,
        fiscal_year,
        reference,
        period,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        country_code
    )
    VALUES (
        v_document_number,
        v_preparation.fiscal_year,
        v_reference,
        v_preparation.period,
        'gold_token_transfer'::public."TransactionType",
        'User ' ||
        coalesce(v_sender.email, v_sender.phone, v_sender.id) ||
        ' transferred ' ||
        v_preparation.amount ||
        'g Gold tokens to user ' ||
        coalesce(v_receiver.email, v_receiver.phone, v_receiver.id),
        v_sender.id,
        v_preparation.total_amount::numeric,
        'gold',
        v_preparation.country_code
    )
    RETURNING id INTO v_financial_transaction_id;

    v_stage := 'post financial entries';

    PERFORM *
    FROM public.post_financial_entries(
        p_document_number => v_document_number,
        p_country_code => v_preparation.country_code,
        p_transaction_id => v_financial_transaction_id,
        p_transaction_type =>
            'gold_token_transfer'::public."TransactionType",
        p_created_by => v_sender.id,
        p_components => v_preparation.components,
        p_mappings => v_preparation.mappings,
        p_currency_code => 'gold',
        p_fiscal_year => v_preparation.fiscal_year,
        p_period => v_preparation.period,
        p_reference => v_reference,
        p_deposit_type => NULL
    );

    /*
     * The transaction type selects the wallets.
     * Both users use customer wallets.
     *
     * Receiver wallet creation, if needed,
     * occurs inside post_wallet_entries.
     */
    v_stage := 'post wallet entries';

    SELECT wallet_result.receiver_notification_id
    INTO v_receiver_notification_id
    FROM public.post_wallet_entries(
        p_fiscal_year => v_preparation.fiscal_year,
        p_period => v_preparation.period,
        p_document_number => v_document_number,
        p_reference => v_reference,
        p_receiver_id => v_receiver.id,
        p_sender_id => v_sender.id,
        p_transaction_type =>
            'gold_token_transfer'::public."TransactionType",
        p_credit_amount => v_preparation.amount::numeric,
        p_debit_amount => v_preparation.total_amount::numeric,
        p_sender_wallet_owner =>
            'customer'::public."WalletOwnerType",
        p_receiver_wallet_owner =>
            'customer'::public."WalletOwnerType",
        p_currency_code => 'gold',
        p_country_code => v_preparation.country_code,
        p_audit_action_type =>
            'token_transferred'::public."AuditActionType",
        p_treasury_id => v_preparation.treasury_id,
        p_fee_amount => v_preparation.fee::numeric,
        p_ip_address => p_ip_address,
        p_receiver_notification => v_receiver_notification,
        p_sender_notification => v_sender_notification,
        p_blockchain_code => v_blockchain_code
    ) AS wallet_result;

    v_stage := 'complete blockchain transaction';

    UPDATE public.blockchain_transaction
    SET
        document_number = v_document_number,
        status = 'completed'::public."BlockchainTxStatus"
    WHERE id::text = p_blockchain_transaction_id
      AND status = 'pending'::public."BlockchainTxStatus"
      AND lower(btrim(chain)) = v_blockchain_code;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'BLOCKCHAIN_TRANSACTION_UPDATE_FAILED';
    END IF;

    v_stage := 'complete transaction state';

    UPDATE public.transaction_state
    SET
        user_id = v_receiver.id,
        status = 'success'::public."TransactionStatus",
        message = NULL,
        updated_at = now()
    WHERE id = p_transaction_state_id
      AND created_by = p_sender_id
      AND transaction_type =
          'gold_token_transfer'::public."TransactionType"
      AND status = 'processing'::public."TransactionStatus"
      AND blockchain_code = v_blockchain_code;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'TRANSACTION_STATE_UPDATE_FAILED';
    END IF;

    v_stage := 'return gold transfer result';

    RETURN QUERY
    SELECT
        true,
        v_document_number,
        v_preparation.amount,
        v_preparation.fee,
        v_blockchain_transaction.explorer_url,
        v_receiver_notification_id,
        v_device_tokens,
        v_receiver_notification.title,
        v_receiver_notification.body,
        v_receiver_notification.payload ->> 'reference';

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_error_state = RETURNED_SQLSTATE,
            v_error_message = MESSAGE_TEXT,
            v_error_detail = PG_EXCEPTION_DETAIL,
            v_error_hint = PG_EXCEPTION_HINT,
            v_error_context = PG_EXCEPTION_CONTEXT;

        RAISE EXCEPTION USING
            ERRCODE = v_error_state,
            MESSAGE = format(
                'GOLD_TRANSFER_FAILED at [%s]: %s',
                v_stage,
                v_error_message
            ),
            DETAIL = coalesce(
                nullif(
                    concat_ws(
                        E'\n',
                        nullif(v_error_detail, ''),
                        nullif(v_error_context, '')
                    ),
                    ''
                ),
                'No additional PostgreSQL context'
            ),
            HINT = coalesce(
                nullif(v_error_hint, ''),
                'Check the Gold Transfer stage reported in the error'
            );
END;
$$;
ALTER FUNCTION "public"."complete_gold_transfer"("p_sender_id" "text", "p_transaction" "jsonb", "p_country_code" "text", "p_transaction_state_id" "text", "p_blockchain_transaction_id" "text", "p_ip_address" "text", "p_blockchain_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."complete_merchant_payment"("p_payer_id" "text", "p_transaction" "jsonb", "p_approval" "jsonb", "p_country_code" "text", "p_transaction_state_id" "text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "document_number" "text", "amount" "text", "payment_fee" "text", "currency_code" "text", "receiver_notification_id" "text", "device_tokens" "text"[], "push_title" "text", "push_body" "text", "push_reference" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_preparation record;

    v_payer public.users%rowtype;
    v_merchant public.users%rowtype;

    v_sender_notification
        public.notification_message;

    v_receiver_notification
        public.notification_message;

    v_device_tokens text[] :=
        array[]::text[];

    v_document_number text;
    v_financial_transaction_id bigint;
    v_receiver_notification_id text;

    v_reference text;

    v_stage text := 'initialization';
    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * Only the Edge Function's service-role client may
     * execute privileged payment posting.
     */
    if coalesce(
        auth.role(),
        ''
    ) <> 'service_role'
    then
        raise exception using
            errcode = '42501',
            message = 'SERVICE_ROLE_REQUIRED';
    end if;

    /*
     * Recalculate all trusted values.
     *
     * prepare_merchant_payment also locks the processing
     * transaction state.
     */
    v_stage :=
        'prepare merchant payment';

    select preparation_record.*
    into v_preparation
    from public.prepare_merchant_payment(
        p_payer_id,
        p_transaction,
        p_approval,
        p_country_code,
        p_transaction_state_id
    ) as preparation_record;

    if not found then
        raise exception
            'MERCHANT_PAYMENT_PREPARATION_NOT_FOUND';
    end if;

    v_reference :=
        nullif(
            btrim(
                p_transaction ->> 'r'
            ),
            ''
        );

    if v_reference is null then
        raise exception
            'REFERENCE_IS_REQUIRED';
    end if;

    /*
     * Fetch payer and merchant for descriptions and
     * notification messages.
     */
    v_stage :=
        'fetch payment users';

    v_payer :=
        public.fetch_user_by_id(
            v_preparation.payer_id
        );

    v_merchant :=
        public.fetch_user_by_id(
            v_preparation.merchant_id
        );

    if v_payer.id is null then
        raise exception
            'PAYER_NOT_FOUND';
    end if;

    if v_merchant.id is null then
        raise exception
            'MERCHANT_NOT_FOUND';
    end if;

    /*
     * Sender notification belongs to the payer.
     */
    v_stage :=
        'create payer notification';

    v_sender_notification :=
        public.create_notification_message(
            v_preparation.country_code,
            'merchant_payment'::public."TransactionType",
            'sender'::public."NotificationAudience",
            v_preparation.payer_debit_amount::numeric,
            upper(
                v_preparation.currency_code
            ),
            v_reference || '-01',
            0,
            'Ngoda',
            coalesce(
                v_merchant.email,
                v_merchant.phone,
                v_merchant.id
            )
        );

    /*
     * Receiver notification belongs to the merchant.
     */
    v_stage :=
        'create merchant notification';

    v_receiver_notification :=
        public.create_notification_message(
            v_preparation.country_code,
            'merchant_payment'::public."TransactionType",
            'receiver'::public."NotificationAudience",
            v_preparation.merchant_credit_amount::numeric,
            upper(
                v_preparation.currency_code
            ),
            v_reference || '-02',
            0,
            coalesce(
                v_payer.email,
                v_payer.phone,
                v_payer.id
            ),
            coalesce(
                v_merchant.email,
                v_merchant.phone,
                v_merchant.id
            )
        );

    /*
     * Fetch merchant push-notification tokens.
     */
    v_stage :=
        'fetch merchant device tokens';

    v_device_tokens :=
        coalesce(
            public.fetch_device_tokens(
                v_preparation.country_code,
                v_merchant.id
            ),
            array[]::text[]
        );

    /*
     * Generate the document number using the configured
     * prefix returned by prepare_merchant_payment.
     */
    v_stage :=
        'generate document number';

    v_document_number :=
        public.generate_document_number(
            v_preparation.document_prefix,
            v_preparation.fiscal_year,
            v_preparation.period,
            v_preparation.country_code
        );

    if v_document_number is null
       or btrim(
           v_document_number
       ) = ''
    then
        raise exception
            'DOCUMENT_NUMBER_GENERATION_FAILED';
    end if;

    /*
     * Create financial transaction header.
     */
    v_stage :=
        'insert financial transaction';

    insert into public.financial_transaction (
        fiscal_year,
        period,
        document_number,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        reference,
        country_code
    )
    values (
        v_preparation.fiscal_year,
        v_preparation.period,
        v_document_number,
        'merchant_payment'::public."TransactionType",
        'User ' ||
        coalesce(
            v_payer.email,
            v_payer.phone,
            v_payer.id
        ) ||
        ' pays merchant ' ||
        coalesce(
            v_merchant.email,
            v_merchant.phone,
            v_merchant.id
        ),
        v_payer.id,
        v_preparation.payer_debit_amount::numeric,
        v_preparation.currency_code,
        v_reference,
        v_preparation.country_code
    )
    returning id
    into v_financial_transaction_id;

    /*
     * Post Merchant Payment GL entries.
     */
    v_stage :=
        'post financial entries';

    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_document_number,

        p_country_code =>
            v_preparation.country_code,

        p_transaction_id =>
            v_financial_transaction_id,

        p_transaction_type =>
            'merchant_payment'::public."TransactionType",

        p_created_by =>
            v_payer.id,

        p_components =>
            v_preparation.components,

        p_mappings =>
            v_preparation.mappings,

        p_currency_code =>
            v_preparation.currency_code,

        p_fiscal_year =>
            v_preparation.fiscal_year,

        p_period =>
            v_preparation.period,

        p_reference =>
            v_reference,

        p_deposit_type =>
            null
    );

    /*
     * Wallet movement:
     *
     * Payer customer wallet:
     *   debit configured principal amount
     *
     * Merchant wallet:
     *   credit purchase amount
     *
     * Treasury wallet:
     *   credit payment fee
     */
    v_stage :=
        'post wallet entries';

    select wallet_result.receiver_notification_id
    into v_receiver_notification_id
    from public.post_wallet_entries(
        p_fiscal_year =>
            v_preparation.fiscal_year,

        p_period =>
            v_preparation.period,

        p_document_number =>
            v_document_number,

        p_reference =>
            v_reference,

        p_receiver_id =>
            v_merchant.id,

        p_sender_id =>
            v_payer.id,

        p_transaction_type =>
            'merchant_payment'::public."TransactionType",

        p_credit_amount =>
            v_preparation.merchant_credit_amount::numeric,

        p_debit_amount =>
            v_preparation.payer_debit_amount::numeric,

        p_sender_wallet_owner =>
            'customer'::public."WalletOwnerType",

        p_receiver_wallet_owner =>
            'merchant'::public."WalletOwnerType",

        p_currency_code =>
            v_preparation.currency_code,

        p_country_code =>
            v_preparation.country_code,

        p_audit_action_type =>
            'merchant_payment'::public."AuditActionType",

        p_treasury_id =>
            v_preparation.treasury_id,

        p_fee_amount =>
            v_preparation.payment_fee::numeric,

        p_ip_address =>
            p_ip_address,

        p_receiver_notification =>
            v_receiver_notification,

        p_sender_notification =>
            v_sender_notification
    ) as wallet_result;

    /*
     * Record the merchant's share of the payment fee.
     */
    -- v_stage :=
    --     'insert merchant commission';

    -- if v_preparation.payment_fee::numeric > 0 then
    --     insert into public.merchant_commission (
    --         merchant_id,
    --         document_number,
    --         fiscal_year,
    --         period,
    --         transaction_type,
    --         currency_code,
    --         amount,
    --         fee_amount,
    --         commission_rate,
    --         commission_amount,
    --         is_settled,
    --         country_code
    --     )
    --     values (
    --         v_merchant.id,
    --         v_document_number,
    --         v_preparation.fiscal_year,
    --         v_preparation.period,
    --         'merchant_payment'::public."TransactionType",
    --         v_preparation.currency_code,
    --         v_preparation.merchant_credit_amount::numeric,
    --         v_preparation.payment_fee::numeric,
    --         v_preparation.commission_rate::numeric,
    --         v_preparation.commission_amount::numeric,
    --         false,
    --         v_preparation.country_code
    --     );
    -- end if;

    /*
     * Mark transaction state successful.
     */
    v_stage :=
        'complete transaction state';

    update public.transaction_state
    set
        user_id =
            v_merchant.id,

        status =
            'success'::public."TransactionStatus",

        message =
            null,

        updated_at =
            now()

    where id =
          p_transaction_state_id
      and created_by =
          p_payer_id
      and user_id =
          v_merchant.id
      and transaction_type =
          'merchant_payment'::public."TransactionType"
      and status =
          'processing'::public."TransactionStatus";

    if not found then
        raise exception
            'TRANSACTION_STATE_UPDATE_FAILED';
    end if;

    /*
     * Return posting and push-notification data.
     */
    v_stage :=
        'return merchant payment result';

    return query
    select
        true,
        v_document_number,
        v_preparation.merchant_credit_amount,
        v_preparation.payment_fee,
        v_preparation.currency_code,
        v_receiver_notification_id,
        v_device_tokens,
        v_receiver_notification.title,
        v_receiver_notification.body,
        v_receiver_notification.payload
            ->> 'reference';

exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;

        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'MERCHANT_PAYMENT_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                coalesce(
                    nullif(
                        concat_ws(
                            E'\n',
                            nullif(
                                v_error_detail,
                                ''
                            ),
                            nullif(
                                v_error_context,
                                ''
                            )
                        ),
                        ''
                    ),
                    'No additional PostgreSQL context'
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    'Check the Merchant Payment stage reported in the error'
                );
end;
$$;
ALTER FUNCTION "public"."complete_merchant_payment"("p_payer_id" "text", "p_transaction" "jsonb", "p_approval" "jsonb", "p_country_code" "text", "p_transaction_state_id" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."complete_merchant_payment"("p_payer_id" "text", "p_transaction" "jsonb", "p_approval" "jsonb", "p_country_code" "text", "p_transaction_state_id" "text", "p_payment_fee_contribution" boolean, "p_ip_address" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "document_number" "text", "financial_transaction_id" "text", "amount" "text", "amount_usd" "text", "payment_fee" "text", "payment_fee_usd" "text", "payment_fee_contribution" boolean, "payer_debit_amount" "text", "currency_code" "text", "receiver_notification_id" "text", "device_tokens" "text"[], "push_title" "text", "push_body" "text", "push_reference" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_preparation record;
    v_payer public.users%rowtype;
    v_merchant public.users%rowtype;
    v_sender_notification public.notification_message;
    v_receiver_notification public.notification_message;
    v_device_tokens text[] := array[]::text[];
    v_document_number text;
    v_financial_transaction_id bigint;
    v_receiver_notification_id text;
    v_reference text;
    v_rate_to_usd numeric;
    v_amount_usd numeric(20, 6);
    v_payment_fee_usd numeric(20, 6) := 0;
    v_contributed boolean := false;
    v_stage text := 'initialization';
    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    if coalesce(auth.role(), '') <> 'service_role' then
        raise exception using
            errcode = '42501',
            message = 'SERVICE_ROLE_REQUIRED';
    end if;

    if p_payment_fee_contribution is null then
        raise exception 'PAYMENT_FEE_CONTRIBUTION_REQUIRED';
    end if;

    v_stage := 'prepare merchant payment';

    select preparation_record.*
    into v_preparation
    from public.prepare_merchant_payment(
        p_payer_id,
        p_transaction,
        p_approval,
        p_country_code,
        p_transaction_state_id,
        p_payment_fee_contribution
    ) as preparation_record;

    if not found then
        raise exception 'MERCHANT_PAYMENT_PREPARATION_NOT_FOUND';
    end if;

    v_reference := nullif(btrim(p_transaction ->> 'r'), '');

    if v_reference is null then
        raise exception 'REFERENCE_IS_REQUIRED';
    end if;

    v_contributed :=
        p_payment_fee_contribution
        and v_preparation.payment_fee::numeric > 0;

    /* Capture the qualifying USD values in the posting transaction. */
    v_stage := 'calculate loyalty USD values';

    if lower(v_preparation.currency_code) = 'usd' then
        v_amount_usd := round(v_preparation.amount::numeric, 6);
        v_payment_fee_usd :=
            round(v_preparation.payment_fee::numeric, 6);
    else
        select rate_record.rate_to_usd
        into v_rate_to_usd
        from public.current_rates rate_record
        where lower(btrim(rate_record.code)) =
              lower(v_preparation.currency_code)
        limit 1;

        if not found
           or v_rate_to_usd is null
           or v_rate_to_usd <= 0
        then
            raise exception
                'CURRENT_RATE_NOT_FOUND_%',
                upper(v_preparation.currency_code);
        end if;

        /* Merchant payments support fiat currencies only. */
        v_amount_usd := round(
            v_preparation.amount::numeric / v_rate_to_usd,
            6
        );

        v_payment_fee_usd := round(
            v_preparation.payment_fee::numeric / v_rate_to_usd,
            6
        );
    end if;

    if v_amount_usd <= 0 then
        raise exception 'INVALID_MERCHANT_PAYMENT_USD_AMOUNT';
    end if;

    v_stage := 'fetch payment users';
    v_payer := public.fetch_user_by_id(v_preparation.payer_id);
    v_merchant := public.fetch_user_by_id(v_preparation.merchant_id);

    if v_payer.id is null then
        raise exception 'PAYER_NOT_FOUND';
    end if;

    if v_merchant.id is null then
        raise exception 'MERCHANT_NOT_FOUND';
    end if;

    v_stage := 'create payer notification';
    v_sender_notification := public.create_notification_message(
        v_preparation.country_code,
        'merchant_payment'::public."TransactionType",
        'sender'::public."NotificationAudience",
        v_preparation.payer_debit_amount::numeric,
        upper(v_preparation.currency_code),
        v_reference || '-01',
        0,
        'Ngoda',
        coalesce(v_merchant.email, v_merchant.phone, v_merchant.id)
    );

    v_stage := 'create merchant notification';
    v_receiver_notification := public.create_notification_message(
        v_preparation.country_code,
        'merchant_payment'::public."TransactionType",
        'receiver'::public."NotificationAudience",
        v_preparation.merchant_credit_amount::numeric,
        upper(v_preparation.currency_code),
        v_reference || '-02',
        0,
        coalesce(v_payer.email, v_payer.phone, v_payer.id),
        coalesce(v_merchant.email, v_merchant.phone, v_merchant.id)
    );

    v_stage := 'fetch merchant device tokens';
    v_device_tokens := coalesce(
        public.fetch_device_tokens(
            v_preparation.country_code,
            v_merchant.id
        ),
        array[]::text[]
    );

    v_stage := 'generate document number';
    v_document_number := public.generate_document_number(
        v_preparation.document_prefix,
        v_preparation.fiscal_year,
        v_preparation.period,
        v_preparation.country_code
    );

    if nullif(btrim(v_document_number), '') is null then
        raise exception 'DOCUMENT_NUMBER_GENERATION_FAILED';
    end if;

    v_stage := 'insert financial transaction';
    insert into public.financial_transaction (
        fiscal_year,
        period,
        document_number,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        reference,
        country_code
    )
    values (
        v_preparation.fiscal_year,
        v_preparation.period,
        v_document_number,
        'merchant_payment'::public."TransactionType",
        'User ' ||
        coalesce(v_payer.email, v_payer.phone, v_payer.id) ||
        ' pays merchant ' ||
        coalesce(v_merchant.email, v_merchant.phone, v_merchant.id),
        v_payer.id,
        v_preparation.payer_debit_amount::numeric,
        v_preparation.currency_code,
        v_reference,
        v_preparation.country_code
    )
    returning id into v_financial_transaction_id;

    v_stage := 'post financial entries';
    perform *
    from public.post_financial_entries(
        p_document_number => v_document_number,
        p_country_code => v_preparation.country_code,
        p_transaction_id => v_financial_transaction_id,
        p_transaction_type =>
            'merchant_payment'::public."TransactionType",
        p_created_by => v_payer.id,
        p_components => v_preparation.components,
        p_mappings => v_preparation.mappings,
        p_currency_code => v_preparation.currency_code,
        p_fiscal_year => v_preparation.fiscal_year,
        p_period => v_preparation.period,
        p_reference => v_reference,
        p_deposit_type => null
    );

    v_stage := 'post wallet entries';
    select wallet_result.receiver_notification_id
    into v_receiver_notification_id
    from public.post_wallet_entries(
        p_fiscal_year => v_preparation.fiscal_year,
        p_period => v_preparation.period,
        p_document_number => v_document_number,
        p_reference => v_reference,
        p_receiver_id => v_merchant.id,
        p_sender_id => v_payer.id,
        p_transaction_type =>
            'merchant_payment'::public."TransactionType",
        p_credit_amount =>
            v_preparation.merchant_credit_amount::numeric,
        p_debit_amount =>
            v_preparation.payer_debit_amount::numeric,
        p_sender_wallet_owner =>
            'customer'::public."WalletOwnerType",
        p_receiver_wallet_owner =>
            'merchant'::public."WalletOwnerType",
        p_currency_code => v_preparation.currency_code,
        p_country_code => v_preparation.country_code,
        p_audit_action_type =>
            'merchant_payment'::public."AuditActionType",
        p_treasury_id => v_preparation.treasury_id,
        p_fee_amount => v_preparation.payment_fee::numeric,
        p_ip_address => p_ip_address,
        p_receiver_notification => v_receiver_notification,
        p_sender_notification => v_sender_notification
    ) as wallet_result;

    v_stage := 'complete transaction state';
    update public.transaction_state state_record
    set
        user_id = v_merchant.id,
        status = 'success'::public."TransactionStatus",
        message = null,
        updated_at = now()
    where state_record.id::text = p_transaction_state_id
      and state_record.created_by = p_payer_id
      and state_record.user_id = v_merchant.id
      and state_record.transaction_type =
          'merchant_payment'::public."TransactionType"
      and state_record.status =
          'processing'::public."TransactionStatus"
      and state_record.payment_fee_contribution =
          p_payment_fee_contribution;

    if not found then
        raise exception 'TRANSACTION_STATE_UPDATE_FAILED';
    end if;

    v_stage := 'return merchant payment result';
    return query
    select
        true,
        v_document_number,
        v_financial_transaction_id::text,
        v_preparation.amount::text,
        v_amount_usd::text,
        v_preparation.payment_fee::text,
        v_payment_fee_usd::text,
        v_contributed,
        v_preparation.payer_debit_amount::text,
        v_preparation.currency_code::text,
        v_receiver_notification_id,
        v_device_tokens,
        v_receiver_notification.title,
        v_receiver_notification.body,
        v_receiver_notification.payload ->> 'reference';

exception
    when others then
        get stacked diagnostics
            v_error_state = returned_sqlstate,
            v_error_message = message_text,
            v_error_detail = pg_exception_detail,
            v_error_hint = pg_exception_hint,
            v_error_context = pg_exception_context;

        raise exception using
            errcode = v_error_state,
            message = format(
                'MERCHANT_PAYMENT_FAILED at [%s]: %s',
                v_stage,
                v_error_message
            ),
            detail = coalesce(
                nullif(
                    concat_ws(
                        E'\n',
                        nullif(v_error_detail, ''),
                        nullif(v_error_context, '')
                    ),
                    ''
                ),
                'No additional PostgreSQL context'
            ),
            hint = coalesce(
                nullif(v_error_hint, ''),
                'Check the Merchant Payment stage reported in the error'
            );
end;
$$;
ALTER FUNCTION "public"."complete_merchant_payment"("p_payer_id" "text", "p_transaction" "jsonb", "p_approval" "jsonb", "p_country_code" "text", "p_transaction_state_id" "text", "p_payment_fee_contribution" boolean, "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."complete_my_token_adjustment_execution"("p_adjustment_request_id" "text", "p_blockchain_transaction_id" "text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;
    v_treasury public.users%rowtype;

    v_request
        public.tokenised_asset_adjustment_request%rowtype;

    v_blockchain_transaction
        public.blockchain_transaction%rowtype;

    v_treasury_wallet
        public.wallet%rowtype;

    v_transaction_type
        public."TransactionType";

    v_final_status
        public."AdjustmentStatus";

    v_audit_action
        public."AuditActionType";

    v_quantity numeric;

    v_wallet_debit numeric := 0;
    v_wallet_credit numeric := 0;

    v_wallet_balance_before numeric := 0;
    v_wallet_balance_after numeric := 0;

    v_mappings
        public.transaction_gl_mapping[];

    v_components
        public.posting_component[];

    v_document_prefix text;
    v_document_number text;
    v_description text;

    v_financial_transaction_id bigint;

    v_fiscal_year integer;
    v_period integer;

    v_blockchain_code text;

    v_minting_country_code constant text := 'zw';

    v_wallet_found boolean := false;
begin
    /*
     * ==========================================================
     * AUTHENTICATION
     * ==========================================================
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    /*
     * ==========================================================
     * ROLE AUTHORIZATION
     * ==========================================================
     */
    if not public.has_role(
        array['treasury']::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * ==========================================================
     * VALIDATE INPUT
     * ==========================================================
     */
    if nullif(
        btrim(p_adjustment_request_id),
        ''
    ) is null then
        raise exception
            'ADJUSTMENT_REQUEST_ID_REQUIRED';
    end if;

    if nullif(
        btrim(p_blockchain_transaction_id),
        ''
    ) is null then
        raise exception
            'BLOCKCHAIN_TRANSACTION_ID_REQUIRED';
    end if;

    /*
     * ==========================================================
     * FETCH AUTHENTICATED TREASURY USER
     * ==========================================================
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'TREASURY_USER_NOT_FOUND';
    end if;

    /*
     * ==========================================================
     * CENTRAL MINTING TREASURY AUTHORIZATION
     * ==========================================================
     *
     * Zimbabwe is the designated minting and burning country.
     */
    if lower(
        btrim(
            coalesce(v_user.country_code, '')
        )
    ) <> v_minting_country_code then
        raise exception using
            errcode = '42501',
            message = 'CENTRAL_MINTING_TREASURY_ONLY';
    end if;

    /*
     * ==========================================================
     * FETCH ZIMBABWE TREASURY ACCOUNT
     * ==========================================================
     */
    v_treasury :=
        public.fetch_country_treasury(
            v_minting_country_code
        );

    if v_treasury.id is null then
        raise exception
            'TREASURY_NOT_FOUND';
    end if;

    /*
     * ==========================================================
     * LOCK ADJUSTMENT REQUEST
     * ==========================================================
     */
    select adjustment_record.*
    into v_request
    from public.tokenised_asset_adjustment_request
        adjustment_record
    where adjustment_record.id::text =
          btrim(p_adjustment_request_id)
    for update;

    if not found then
        raise exception
            'ADJUSTMENT_REQUEST_NOT_FOUND';
    end if;

    if v_request.status is distinct from
       'approved'::public."AdjustmentStatus"
    then
        raise exception
            'ADJUSTMENT_REQUEST_NOT_APPROVED';
    end if;

    if v_request.executed_by is distinct from
       v_user.id
    then
        raise exception
            'ADJUSTMENT_REQUEST_NOT_CLAIMED_BY_USER';
    end if;

    if nullif(
        btrim(v_request.tx_hash),
        ''
    ) is null then
        raise exception
            'ADJUSTMENT_REQUEST_BLOCKCHAIN_HASH_NOT_FOUND';
    end if;

    if v_request.quantity is null
       or v_request.quantity <= 0
    then
        raise exception
            'INVALID_TOKEN_ADJUSTMENT_AMOUNT';
    end if;

/*
 * ==========================================================
 * VALIDATE ORIGINAL INVENTORY PURCHASE CURRENCY
 * ==========================================================
 *
 * The adjustment request's currency_code represents the
 * original currency used to purchase physical gold.
 *
 * It can be USD, ZIG, ZAR, etc.
 *
 * GOLD remains the currency used for the blockchain
 * transaction, GL entries and treasury wallet.
 */
if nullif(
    lower(
        btrim(
            v_request.currency_code::text
        )
    ),
    ''
) is null then
    raise exception
        'ADJUSTMENT_PURCHASE_CURRENCY_REQUIRED';
end if;

    /*
     * ==========================================================
     * RESOLVE BLOCKCHAIN
     * ==========================================================
     */
    v_blockchain_code :=
        nullif(
            lower(
                btrim(v_request.blockchain_code)
            ),
            ''
        );

    if v_blockchain_code is null then
        raise exception
            'BLOCKCHAIN_CODE_REQUIRED';
    end if;

    v_quantity :=
        v_request.quantity;

    /*
     * ==========================================================
     * RESOLVE TRANSACTION TYPE
     * ==========================================================
     */
    if v_request.adjustment_type =
       'minting'::public."TokenAdjustmentType"
    then
        v_transaction_type :=
            'gold_token_mint'::public."TransactionType";

        v_final_status :=
            'minted'::public."AdjustmentStatus";

        v_audit_action :=
            'token_minted'::public."AuditActionType";

        v_description :=
            'Gold token minting - ' ||
            upper(v_blockchain_code);

        v_wallet_debit := 0;
        v_wallet_credit := v_quantity;

    elsif v_request.adjustment_type =
          'burning'::public."TokenAdjustmentType"
    then
        v_transaction_type :=
            'gold_token_burn'::public."TransactionType";

        v_final_status :=
            'burned'::public."AdjustmentStatus";

        v_audit_action :=
            'token_burned'::public."AuditActionType";

        v_description :=
            'Gold token burning - ' ||
            upper(v_blockchain_code);

        v_wallet_debit := v_quantity;
        v_wallet_credit := 0;

    else
        raise exception
            'INVALID_TOKEN_ADJUSTMENT_TYPE';
    end if;

    /*
     * ==========================================================
     * LOCK BLOCKCHAIN TRANSACTION
     * ==========================================================
     */
    select blockchain_record.*
    into v_blockchain_transaction
    from public.blockchain_transaction
        blockchain_record
    where blockchain_record.id::text =
          btrim(p_blockchain_transaction_id)
    for update;

    if not found then
        raise exception
            'BLOCKCHAIN_TRANSACTION_NOT_FOUND';
    end if;

    /*
     * ==========================================================
     * VALIDATE BLOCKCHAIN TRANSACTION
     * ==========================================================
     */
    if v_blockchain_transaction.reference
       is distinct from v_request.id::text
    then
        raise exception
            'BLOCKCHAIN_TRANSACTION_REQUEST_MISMATCH';
    end if;

    if lower(v_blockchain_transaction.tx_hash)
       is distinct from lower(v_request.tx_hash)
    then
        raise exception
            'BLOCKCHAIN_TRANSACTION_HASH_MISMATCH';
    end if;

    if v_blockchain_transaction.transaction_type
       is distinct from v_transaction_type
    then
        raise exception
            'BLOCKCHAIN_TRANSACTION_TYPE_MISMATCH';
    end if;

    /*
     * Mint/burn accounting belongs to Zimbabwe.
     */
    if lower(
        btrim(
            coalesce(
                v_blockchain_transaction.country_code,
                ''
            )
        )
    ) <> v_minting_country_code then
        raise exception
            'BLOCKCHAIN_TRANSACTION_COUNTRY_MISMATCH';
    end if;

    /*
     * Validate the blockchain independently of country.
     */
    if lower(
        btrim(
            coalesce(
                v_blockchain_transaction.blockchain_code,
                ''
            )
        )
    ) <> v_blockchain_code then
        raise exception
            'BLOCKCHAIN_TRANSACTION_CHAIN_MISMATCH';
    end if;

    if lower(
        btrim(
            coalesce(
                v_blockchain_transaction.currency_code,
                ''
            )
        )
    ) <> 'gold' then
        raise exception
            'BLOCKCHAIN_TRANSACTION_CURRENCY_MISMATCH';
    end if;

    if v_blockchain_transaction.quantity
       is distinct from v_quantity
    then
        raise exception
            'BLOCKCHAIN_TRANSACTION_QUANTITY_MISMATCH';
    end if;

    if v_blockchain_transaction.status is distinct from
       'pending'::public."BlockchainTxStatus"
    then
        raise exception
            'BLOCKCHAIN_TRANSACTION_NOT_PENDING';
    end if;

    if v_blockchain_transaction.document_number is not null then
        raise exception
            'BLOCKCHAIN_TRANSACTION_ALREADY_POSTED';
    end if;

    v_fiscal_year :=
        v_blockchain_transaction.fiscal_year;

    v_period :=
        v_blockchain_transaction.period;

    if v_fiscal_year is null
       or v_period is null
    then
        raise exception
            'BLOCKCHAIN_TRANSACTION_FISCAL_PERIOD_MISSING';
    end if;

    /*
     * ==========================================================
     * FETCH GL MAPPINGS
     * ==========================================================
     */
    select array_agg(mapping_record)
    into v_mappings
    from public.fetch_gl_mappings(
        v_transaction_type
    ) as mapping_record;

    if v_mappings is null
       or cardinality(v_mappings) = 0
    then
        raise exception
            'GL_MAPPINGS_NOT_FOUND';
    end if;

    /*
     * ==========================================================
     * BUILD POSTING COMPONENTS
     * ==========================================================
     */
    v_components :=
        public.build_posting_components(
            v_transaction_type,
            v_quantity,
            v_mappings,
            v_minting_country_code,
            'gold',
            false
        );

    if v_components is null
       or cardinality(v_components) = 0
    then
        raise exception
            'POSTING_COMPONENTS_NOT_FOUND';
    end if;

    /*
     * ==========================================================
     * GENERATE ACCOUNTING DOCUMENT NUMBER
     * ==========================================================
     */
    v_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            v_transaction_type
        );

    if nullif(
        btrim(v_document_prefix),
        ''
    ) is null then
        raise exception
            'DOCUMENT_PREFIX_NOT_FOUND';
    end if;

    v_document_number :=
        public.generate_document_number(
            v_document_prefix,
            v_fiscal_year,
            v_period,
            v_minting_country_code
        );

    /*
     * ==========================================================
     * CREATE FINANCIAL TRANSACTION
     * ==========================================================
     *
     * financial_transaction does not have blockchain_code.
     * The blockchain is included in the description.
     */
    insert into public.financial_transaction (
        document_number,
        reference,
        fiscal_year,
        period,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        country_code
    )
    values (
        v_document_number,
        v_request.tx_hash,
        v_fiscal_year,
        v_period,
        v_transaction_type,
        v_description,
        v_user.id,
        v_quantity,
        'gold',
        v_minting_country_code
    )
    returning id
    into v_financial_transaction_id;

    /*
     * ==========================================================
     * POST FINANCIAL ENTRIES
     * ==========================================================
     */
    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_document_number,

        p_country_code =>
            v_minting_country_code,

        p_transaction_id =>
            v_financial_transaction_id,

        p_transaction_type =>
            v_transaction_type,

        p_created_by =>
            v_user.id,

        p_components =>
            v_components,

        p_mappings =>
            v_mappings,

        p_currency_code =>
            'gold',

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_reference =>
            v_request.id::text,

        p_deposit_type =>
            null
    );

    /*
     * ==========================================================
     * LOCK ZIMBABWE TREASURY GOLD WALLET
     * ==========================================================
     *
     * Wallet balances remain country-specific and
     * blockchain-specific.
     */
    select wallet_record.*
    into v_treasury_wallet
    from public.wallet
        wallet_record
    where wallet_record.country_code =
          v_minting_country_code

      and wallet_record.user_id =
          v_treasury.id

      and lower(wallet_record.currency_code) =
          'gold'

      and wallet_record.owner_type =
          'treasury'::public."WalletOwnerType"

      and wallet_record.blockchain_code =
          v_blockchain_code

    for update;

    v_wallet_found := found;

    /*
     * ==========================================================
     * MINT GOLD TOKENS
     * ==========================================================
     */
    if v_request.adjustment_type =
       'minting'::public."TokenAdjustmentType"
    then
        /*
         * Create Zimbabwe's GOLD wallet for this blockchain
         * if it does not already exist.
         */
        if not v_wallet_found then

            insert into public.wallet (
                country_code,
                user_id,
                currency_code,
                blockchain_code,
                owner_type,
                balance,
                is_active
            )
            values (
                v_minting_country_code,
                v_treasury.id,
                'gold',
                v_blockchain_code,
                'treasury'::public."WalletOwnerType",
                v_quantity,
                true
            )
            returning *
            into v_treasury_wallet;

            v_wallet_balance_before := 0;
            v_wallet_balance_after := v_quantity;

        else
            if not v_treasury_wallet.is_active then
                raise exception
                    'TREASURY_GOLD_WALLET_FROZEN';
            end if;

            v_wallet_balance_before :=
                coalesce(
                    v_treasury_wallet.balance,
                    0
                );

            update public.wallet
            set balance =
                coalesce(balance, 0) + v_quantity
            where id = v_treasury_wallet.id
              and is_active = true
            returning *
            into v_treasury_wallet;

            if not found then
                raise exception
                    'TREASURY_GOLD_WALLET_UPDATE_FAILED';
            end if;

            v_wallet_balance_after :=
                v_treasury_wallet.balance;
        end if;

    /*
     * ==========================================================
     * BURN GOLD TOKENS
     * ==========================================================
     */
    else
        if not v_wallet_found then
            raise exception
                'TREASURY_GOLD_WALLET_NOT_FOUND';
        end if;

        if not v_treasury_wallet.is_active then
            raise exception
                'TREASURY_GOLD_WALLET_FROZEN';
        end if;

        v_wallet_balance_before :=
            coalesce(
                v_treasury_wallet.balance,
                0
            );

        update public.wallet
        set balance =
            balance - v_quantity
        where id = v_treasury_wallet.id
          and is_active = true
          and balance >= v_quantity
        returning *
        into v_treasury_wallet;

        if not found then
            raise exception
                'INSUFFICIENT_TREASURY_GOLD_BALANCE';
        end if;

        v_wallet_balance_after :=
            v_treasury_wallet.balance;
    end if;

/*
 * ==========================================================
 * CREATE TREASURY WALLET ENTRY
 * ==========================================================
 *
 * GOLD wallet entries must identify the blockchain.
 */
insert into public.wallet_entry (
    fiscal_year,
    period,
    document_number,
    reference,
    transaction_type,
    wallet_id,
    currency_code,
    blockchain_code,
    debit,
    credit,
    created_by,
    country_code
)
values (
    v_fiscal_year,
    v_period,
    v_document_number,
    v_request.id::text,
    v_transaction_type,
    v_treasury_wallet.id,
    'gold',
    v_blockchain_code,
    v_wallet_debit,
    v_wallet_credit,
    v_user.id,
    v_minting_country_code
);

    /*
     * ==========================================================
     * UPDATE BLOCKCHAIN-SPECIFIC WALLET SNAPSHOT
     * ==========================================================
     */
    perform public.update_wallet_balance_snapshot(
        v_transaction_type,
        v_treasury.id,
        v_treasury.id,
        null,
        'gold',
        'treasury'::public."WalletOwnerType",
        'treasury'::public."WalletOwnerType",
        v_wallet_debit,
        v_wallet_credit,
        v_fiscal_year,
        v_period,
        v_minting_country_code,
        0,
        v_blockchain_code
    );

    /*
     * ==========================================================
     * FINALIZE ADJUSTMENT REQUEST
     * ==========================================================
     */
    update public.tokenised_asset_adjustment_request
    set
        status = v_final_status,
        executed_by = v_user.id,
        executed_at = now(),
        tx_hash = v_request.tx_hash
    where id = v_request.id
      and status =
          'approved'::public."AdjustmentStatus"
      and executed_by = v_user.id
      and tx_hash = v_request.tx_hash;

    if not found then
        raise exception
            'ADJUSTMENT_REQUEST_COMPLETION_FAILED';
    end if;

    /*
     * ==========================================================
     * COMPLETE BLOCKCHAIN TRANSACTION
     * ==========================================================
     */
    update public.blockchain_transaction
    set
        document_number = v_document_number,
        status =
            'completed'::public."BlockchainTxStatus"
    where id = v_blockchain_transaction.id
      and blockchain_code = v_blockchain_code
      and status =
          'pending'::public."BlockchainTxStatus"
      and document_number is null;

    if not found then
        raise exception
            'BLOCKCHAIN_TRANSACTION_COMPLETION_FAILED';
    end if;

    /*
     * ==========================================================
     * AUDIT COMPLETED TOKEN ADJUSTMENT
     * ==========================================================
     */
    insert into public.audit_log (
        fiscal_year,
        period,
        country_code,
        document_number,
        user_id,
        action_type,
        entity_type,
        entity_id,
        old_value,
        new_value,
        metadata,
        ip_address
    )
    values (
        v_fiscal_year,
        v_period,
        v_minting_country_code,
        v_document_number,
        v_user.id,
        v_audit_action,
        'treasury',
        v_treasury.id,

        jsonb_build_object(
            'blockchain_code',
            v_blockchain_code,

            'treasury_gold_balance',
            v_wallet_balance_before::text
        ),

        jsonb_build_object(
            'blockchain_code',
            v_blockchain_code,

            'treasury_gold_balance',
            v_wallet_balance_after::text
        ),

        jsonb_build_object(
            'adjustment_request_id',
            v_request.id::text,

            'blockchain_transaction_id',
            v_blockchain_transaction.id::text,

            'blockchain_code',
            v_blockchain_code,

            'network_name',
            v_blockchain_transaction.chain,

            'tx_hash',
            v_request.tx_hash,

            'adjustment_type',
            v_request.adjustment_type,

            'quantity',
            v_quantity::text,

            'wallet_id',
            v_treasury_wallet.id
        ),

        p_ip_address
    );

    /*
     * ==========================================================
     * RETURN COMPLETED TRANSACTION
     * ==========================================================
     */
    return jsonb_build_object(
        'success',
        true,

        'document_number',
        v_document_number,

        'adjustment_request_id',
        v_request.id::text,

        'blockchain_transaction_id',
        v_blockchain_transaction.id::text,

        'blockchain_code',
        v_blockchain_code,

        'network_name',
        v_blockchain_transaction.chain,

        'transaction_type',
        v_transaction_type,

        'adjustment_type',
        v_request.adjustment_type,

        'adjusted_quantity',
        v_quantity::text,

        'status',
        v_final_status,

        'tx_hash',
        v_request.tx_hash,

        'explorer_url',
        v_blockchain_transaction.explorer_url,

        'treasury_wallet_id',
        v_treasury_wallet.id,

        'treasury_gold_balance',
        v_wallet_balance_after::text
    );
end;
$$;
ALTER FUNCTION "public"."complete_my_token_adjustment_execution"("p_adjustment_request_id" "text", "p_blockchain_transaction_id" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."complete_my_voucher_payment"("p_transaction" "jsonb", "p_voucher" "jsonb", "p_transaction_state_id" "text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "reference" "text", "customer_id" "text", "gross_amount" "text", "fee" "text", "currency" "text", "voucher_remaining_balance" "text", "notification_id" "text", "device_tokens" "text"[], "push_title" "text", "push_body" "text", "push_reference" "text", "gross_amount_usd" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user
        public.users%rowtype;

begin
    /*
     * ========================================================
     * AUTHORIZE MERCHANT / VENDOR
     * ========================================================
     */
    if auth.uid() is null then
        raise exception using
            errcode =
                '42501',

            message =
                'UNAUTHORIZED';
    end if;


    if not public.has_role(
        array[
            'merchant',
            'vendor'
        ]::text[]
    ) then
        raise exception using
            errcode =
                '42501',

            message =
                'FORBIDDEN';
    end if;


    /*
     * ========================================================
     * FETCH AUTHENTICATED MERCHANT
     * ========================================================
     */
    select
        user_record.*
    into
        v_user
    from public.users
        user_record
    where user_record.id =
          auth.uid()::text
    limit 1;


    if not found then
        raise exception
            'MERCHANT_NOT_FOUND';
    end if;


    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'MERCHANT_NOT_ACTIVE';
    end if;


    if v_user.country_code is null
       or btrim(
           v_user.country_code
       ) = ''
    then
        raise exception
            'MERCHANT_COUNTRY_NOT_CONFIGURED';
    end if;


    /*
     * ========================================================
     * COMPLETE VOUCHER PAYMENT
     * ========================================================
     *
     * The underlying function owns all pricing, currency
     * conversion, voucher accounting and financial posting.
     *
     * It must return gross_amount_usd as the final appended
     * result field.
     */
    return query
    select
        payment_result.success,
        payment_result.reference,
        payment_result.customer_id,
        payment_result.gross_amount,
        payment_result.fee,
        payment_result.currency,
        payment_result.voucher_remaining_balance,
        payment_result.notification_id,
        payment_result.device_tokens,
        payment_result.push_title,
        payment_result.push_body,
        payment_result.push_reference,
        payment_result.gross_amount_usd

    from public.complete_voucher_payment(
        p_merchant_id =>
            v_user.id,

        p_transaction =>
            p_transaction,

        p_voucher =>
            p_voucher,

        p_country_code =>
            v_user.country_code,

        p_transaction_state_id =>
            p_transaction_state_id,

        p_ip_address =>
            p_ip_address
    ) as payment_result;

end;
$$;
ALTER FUNCTION "public"."complete_my_voucher_payment"("p_transaction" "jsonb", "p_voucher" "jsonb", "p_transaction_state_id" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."complete_voucher_payment"("p_merchant_id" "text", "p_transaction" "jsonb", "p_voucher" "jsonb", "p_country_code" "text", "p_transaction_state_id" "text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "reference" "text", "customer_id" "text", "gross_amount" "text", "fee" "text", "currency" "text", "voucher_remaining_balance" "text", "notification_id" "text", "device_tokens" "text"[], "push_title" "text", "push_body" "text", "push_reference" "text", "gross_amount_usd" "text", "voucher_owner_debit_amount" "text", "voucher_owner_debit_amount_usd" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_transaction_type
        public."TransactionType" :=
            'merchant_payment'::public."TransactionType";

    v_stage text :=
        'initialization';

    v_merchant
        public.users%rowtype;

    v_voucher_owner
        public.users%rowtype;

    v_treasury
        public.users%rowtype;

    v_transaction_reference text;

    v_voucher_reference text;

    v_voucher_owner_id text;

    v_currency text;

    v_amount numeric;

    v_voucher_total numeric;

    v_voucher_used numeric :=
        0;

    v_voucher_available numeric :=
        0;

    v_voucher_remaining numeric :=
        0;


    /*
     * ========================================================
     * USD VALUES
     * ========================================================
     */
    v_rate_to_usd numeric;

    v_amount_usd
        numeric(20, 6);

    v_voucher_owner_debit_usd
        numeric(20, 6);


    v_fiscal_year integer;

    v_period integer;


    v_mappings
        public.transaction_gl_mapping[];

    v_components
        public.posting_component[];

    v_component_totals
        public.component_totals;


    v_principal_amount numeric :=
        0;

    v_others_amount numeric :=
        0;

    v_fee numeric :=
        0;


    v_merchant_commission_rate numeric :=
        0;

    v_merchant_commission_amount numeric :=
        0;


    v_document_prefix text;

    v_document_number text;

    v_financial_transaction_id bigint;


    v_voucher_usage_id text;


    v_sender_notification
        public.notification_message;

    v_receiver_notification
        public.notification_message;


    v_receiver_notification_id text;

    v_voucher_owner_notification_id text;


    v_device_tokens text[] :=
        array[]::text[];


    v_error_state text;

    v_error_message text;

    v_error_detail text;

    v_error_hint text;

    v_error_context text;

begin
    /*
     * ========================================================
     * VALIDATE TRANSACTION STATE
     * ========================================================
     */

    v_stage :=
        'validate and lock transaction state';


    perform 1
    from public.transaction_state
        state_record
    where state_record.id =
          p_transaction_state_id
      and state_record.created_by =
          p_merchant_id
      and state_record.transaction_type =
          v_transaction_type
      and state_record.status =
          'processing'::public."TransactionStatus"
      and state_record.country_code =
          p_country_code
      and state_record.transaction_data =
          p_transaction
      and state_record.sender_approval =
          p_voucher
    for update;


    if not found then
        raise exception
            'INVALID_TRANSACTION_STATE';
    end if;


    /*
     * The service-role client may ultimately call this through
     * the authenticated wrapper, therefore validate the supplied
     * merchant ID rather than relying on auth.uid().
     */
    v_stage :=
        'validate merchant role';


    if not public.user_has_role(
        p_merchant_id,
        array[
            'merchant',
            'vendor'
        ]::text[]
    ) then
        raise exception using
            errcode =
                '42501',

            message =
                'FORBIDDEN';
    end if;


    /*
     * ========================================================
     * VALIDATE VERSIONS
     * ========================================================
     */

    v_stage :=
        'validate transaction version';


    if p_transaction ->> 'v'
       is distinct from
       'v0'
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;


    v_stage :=
        'validate voucher version';


    if p_voucher ->> 'v'
       is distinct from
       'v0'
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;


    /*
     * ========================================================
     * PARSE TRANSACTION AND VOUCHER
     * ========================================================
     */

    v_stage :=
        'parse transaction reference';


    v_transaction_reference :=
        nullif(
            btrim(
                p_transaction ->> 'r'
            ),
            ''
        );


    if v_transaction_reference is null then
        raise exception
            'REFERENCE_MISSING';
    end if;


    v_stage :=
        'parse voucher reference';


    v_voucher_reference :=
        nullif(
            btrim(
                p_voucher ->> 'r'
            ),
            ''
        );


    if v_voucher_reference is null then
        raise exception
            'VOUCHER_REFERENCE_MISSING';
    end if;


    /*
     * transaction.s contains the voucher reference.
     */
    if nullif(
        btrim(
            p_transaction ->> 's'
        ),
        ''
    ) is distinct from
       v_voucher_reference
    then
        raise exception
            'REFERENCE_MISMATCH';
    end if;


    v_stage :=
        'parse voucher owner';


    v_voucher_owner_id :=
        nullif(
            btrim(
                p_voucher ->> 's'
            ),
            ''
        );


    if v_voucher_owner_id is null then
        raise exception
            'VOUCHER_OWNER_ID_MISSING';
    end if;


    v_stage :=
        'parse currency';


    v_currency :=
        lower(
            nullif(
                btrim(
                    p_transaction ->> 'c'
                ),
                ''
            )
        );


    if v_currency is null then
        raise exception
            'CURRENCY_MISSING';
    end if;


    if v_currency
       is distinct from
       lower(
           nullif(
               btrim(
                   p_voucher ->> 'c'
               ),
               ''
           )
       )
    then
        raise exception
            'CURRENCY_MISMATCH';
    end if;


    v_stage :=
        'parse payment amount';


    begin
        v_amount :=
            (
                p_transaction ->> 'a'
            )::numeric /
            100;

    exception
        when invalid_text_representation
          or numeric_value_out_of_range
        then
            raise exception
                'INVALID_AMOUNT';
    end;


    if v_amount <= 0 then
        raise exception
            'INVALID_AMOUNT';
    end if;


    v_stage :=
        'parse voucher total';


    begin
        v_voucher_total :=
            (
                p_voucher ->> 'a'
            )::numeric /
            100;

    exception
        when invalid_text_representation
          or numeric_value_out_of_range
        then
            raise exception
                'INVALID_VOUCHER_AMOUNT';
    end;


    if v_voucher_total <= 0 then
        raise exception
            'INVALID_VOUCHER_AMOUNT';
    end if;


    /*
     * ========================================================
     * FETCH AND VALIDATE USERS
     * ========================================================
     */

    v_stage :=
        'fetch merchant';


    v_merchant :=
        public.fetch_user_by_id(
            p_merchant_id
        );


    v_stage :=
        'fetch voucher owner';


    v_voucher_owner :=
        public.fetch_user_by_id(
            v_voucher_owner_id
        );


    v_stage :=
        'fetch treasury';


    v_treasury :=
        public.fetch_country_treasury(
            p_country_code
        );


    if v_merchant.id is null then
        raise exception
            'MERCHANT_NOT_FOUND';
    end if;


    if v_voucher_owner.id is null then
        raise exception
            'VOUCHER_OWNER_NOT_FOUND';
    end if;


    if v_treasury.id is null then
        raise exception
            'TREASURY_WALLET_NOT_FOUND';
    end if;


    if v_merchant.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'MERCHANT_NOT_ACTIVE';
    end if;


    if v_voucher_owner.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'VOUCHER_OWNER_NOT_ACTIVE';
    end if;


    if v_merchant.id =
       v_voucher_owner.id
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;


    if v_merchant.country_code
       is distinct from
       p_country_code
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;


    if v_voucher_owner.country_code
       is distinct from
       p_country_code
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;


    /*
     * Confirm the transaction state belongs to the voucher
     * owner.
     */
    perform 1
    from public.transaction_state
        state_record
    where state_record.id =
          p_transaction_state_id
      and state_record.user_id =
          v_voucher_owner.id;


    if not found then
        raise exception
            'VOUCHER_OWNER_MISMATCH';
    end if;


    /*
     * ========================================================
     * FETCH POSTING CONFIGURATION
     * ========================================================
     */

    v_stage :=
        'fetch GL mappings';


    select
        array_agg(
            mapping_record
        )
    into
        v_mappings
    from public.fetch_gl_mappings(
        v_transaction_type
    ) as mapping_record;


    if v_mappings is null
       or cardinality(
           v_mappings
       ) = 0
    then
        raise exception
            'GL_MAPPINGS_NOT_FOUND';
    end if;


    v_stage :=
        'fetch fiscal period';


    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        p_country_code
    ) as fiscal_period;


    if not found
       or v_fiscal_year is null
       or v_period is null
    then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;


    v_stage :=
        'build posting components';


    v_components :=
        public.build_posting_components(
            v_transaction_type,
            v_amount,
            v_mappings,
            p_country_code,
            v_currency,
            false
        );


    if v_components is null
       or cardinality(
           v_components
       ) = 0
    then
        raise exception
            'POSTING_COMPONENTS_NOT_FOUND';
    end if;


    v_stage :=
        'extract component totals';


    v_component_totals :=
        public.extract_component_totals(
            v_components,
            false
        );


    v_principal_amount :=
        coalesce(
            v_component_totals
                .principal_amount,
            0
        );


    v_others_amount :=
        coalesce(
            v_component_totals
                .others_amount,
            0
        );


    if v_principal_amount <= 0 then
        raise exception
            'INVALID_PRINCIPAL_AMOUNT';
    end if;


    v_stage :=
        'extract payment fee';


    select
        coalesce(
            component_record
                .credit_amount,
            0
        )
    into
        v_fee
    from unnest(
        v_components
    ) as component_record(
        component_type,
        debit_amount,
        credit_amount
    )
    where component_record.component_type =
          'payment_fee'::public."ComponentType"
    limit 1;


    v_fee :=
        coalesce(
            v_fee,
            0
        );


    /*
     * ========================================================
     * CALCULATE USD VALUES
     * ========================================================
     *
     * Use exactly the same FX convention as the current
     * merchant-payment implementation.
     *
     * current_rates.rate_to_usd represents local-currency units
     * per USD, therefore local amounts are divided by the rate.
     *
     * v_amount:
     *     qualifying merchant-purchase / spending amount
     *
     * v_principal_amount:
     *     exact voucher-owner wallet debit
     */
    v_stage :=
        'calculate voucher payment USD values';


    if lower(
        v_currency
    ) = 'usd'
    then
        v_amount_usd :=
            round(
                v_amount,
                6
            );


        v_voucher_owner_debit_usd :=
            round(
                v_principal_amount,
                6
            );

    else
        select
            rate_record.rate_to_usd
        into
            v_rate_to_usd
        from public.current_rates
            rate_record
        where lower(
            btrim(
                rate_record.code
            )
        ) =
        lower(
            v_currency
        )
        limit 1;


        if not found
           or v_rate_to_usd is null
           or v_rate_to_usd <= 0
        then
            raise exception
                'CURRENT_RATE_NOT_FOUND_%',
                upper(
                    v_currency
                );
        end if;


        /*
         * Voucher merchant payments support fiat currencies,
         * matching normal merchant payment.
         */
        v_amount_usd :=
            round(
                v_amount /
                v_rate_to_usd,
                6
            );


        v_voucher_owner_debit_usd :=
            round(
                v_principal_amount /
                v_rate_to_usd,
                6
            );
    end if;


    if v_amount_usd <= 0 then
        raise exception
            'INVALID_VOUCHER_PAYMENT_USD_AMOUNT';
    end if;


    if v_voucher_owner_debit_usd <= 0 then
        raise exception
            'INVALID_VOUCHER_PAYMENT_DEBIT_USD_AMOUNT';
    end if;


    /*
     * ========================================================
     * MERCHANT COMMISSION
     * ========================================================
     */

    v_stage :=
        'fetch merchant commission rate';


    v_merchant_commission_rate :=
        coalesce(
            public.fetch_merchant_commission_rate(
                v_transaction_type,
                v_currency,
                p_country_code
            ),
            0
        );


    if v_merchant_commission_rate < 0 then
        raise exception
            'INVALID_MERCHANT_COMMISSION_RATE';
    end if;


    if v_fee > 0
       and
       v_merchant_commission_rate > 0
    then
        v_merchant_commission_amount :=
            trunc(
                (
                    v_fee *
                    v_merchant_commission_rate
                ) /
                100,
                6
            );
    else
        v_merchant_commission_amount :=
            0;
    end if;


    /*
     * ========================================================
     * LOCK AND VALIDATE VOUCHER BALANCE
     * ========================================================
     */

    v_stage :=
        'acquire voucher lock';


    perform
        pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(
                v_voucher_reference,
                0
            )
        );


    v_stage :=
        'calculate voucher balance';


    v_voucher_used :=
        public.fetch_voucher_used_amount(
            v_voucher_reference
        );


    v_voucher_available :=
        v_voucher_total -
        coalesce(
            v_voucher_used,
            0
        );


    /*
     * The voucher covers the complete wallet debit.
     */
    if v_principal_amount >
       v_voucher_available
    then
        raise exception
            'VOUCHER_BALANCE_NOT_ENOUGH_[% %]',
            upper(
                v_currency
            ),
            trim_scale(
                greatest(
                    v_voucher_available,
                    0
                )
            );
    end if;


    v_voucher_remaining :=
        v_voucher_available -
        v_principal_amount;


    /*
     * ========================================================
     * CREATE VOUCHER USAGE
     * ========================================================
     */

    v_stage :=
        'create voucher usage';


    insert into public.voucher_usage (
        voucher_reference,
        reference,
        status,
        merchant_id,
        debit,
        credit,
        voucher_data,
        transaction_data
    )
    values (
        v_voucher_reference,
        v_transaction_reference,
        'processing'::public."TransactionStatus",
        v_merchant.id,
        v_principal_amount,
        0,
        p_voucher,
        p_transaction
    )
    returning
        id::text
    into
        v_voucher_usage_id;


    /*
     * ========================================================
     * BUILD NOTIFICATIONS
     * ========================================================
     */

    v_stage :=
        'create voucher owner notification';


    v_sender_notification :=
        public.create_notification_message(
            p_country_code,
            v_transaction_type,
            'sender'::public."NotificationAudience",
            v_principal_amount,
            upper(
                v_currency
            ),
            v_transaction_reference ||
            '-01',
            0,
            coalesce(
                v_voucher_owner.email,
                v_voucher_owner.phone,
                v_voucher_owner.id
            ),
            coalesce(
                v_merchant.email,
                v_merchant.phone,
                v_merchant.id
            )
        );


    v_stage :=
        'create merchant notification';


    v_receiver_notification :=
        public.create_notification_message(
            p_country_code,
            v_transaction_type,
            'receiver'::public."NotificationAudience",
            v_amount,
            upper(
                v_currency
            ),
            v_transaction_reference ||
            '-02',
            0,
            coalesce(
                v_voucher_owner.email,
                v_voucher_owner.phone,
                v_voucher_owner.id
            ),
            coalesce(
                v_merchant.email,
                v_merchant.phone,
                v_merchant.id
            )
        );


    v_device_tokens :=
        coalesce(
            public.fetch_device_tokens(
                p_country_code,
                v_voucher_owner.id
            ),
            array[]::text[]
        );


    /*
     * ========================================================
     * GENERATE DOCUMENT NUMBER
     * ========================================================
     */

    v_stage :=
        'fetch document prefix';


    v_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            v_transaction_type
        );


    if v_document_prefix is null
       or btrim(
           v_document_prefix
       ) = ''
    then
        raise exception
            'DOCUMENT_PREFIX_NOT_FOUND';
    end if;


    v_stage :=
        'generate document number';


    v_document_number :=
        public.generate_document_number(
            v_document_prefix,
            v_fiscal_year,
            v_period,
            p_country_code
        );


    /*
     * ========================================================
     * FINANCIAL TRANSACTION
     * ========================================================
     */

    v_stage :=
        'create financial transaction';


    insert into public.financial_transaction (
        fiscal_year,
        period,
        document_number,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        reference,
        country_code
    )
    values (
        v_fiscal_year,
        v_period,
        v_document_number,
        v_transaction_type,
        'Voucher payment from ' ||
        coalesce(
            v_voucher_owner.email,
            v_voucher_owner.phone,
            v_voucher_owner.id
        ) ||
        ' to merchant ' ||
        coalesce(
            v_merchant.email,
            v_merchant.phone,
            v_merchant.id
        ),
        v_merchant.id,
        v_principal_amount,
        v_currency,
        v_transaction_reference,
        p_country_code
    )
    returning
        id
    into
        v_financial_transaction_id;


    /*
     * ========================================================
     * POST FINANCIAL ENTRIES
     * ========================================================
     */

    v_stage :=
        'post financial entries';


    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_document_number,

        p_country_code =>
            p_country_code,

        p_transaction_id =>
            v_financial_transaction_id,

        p_transaction_type =>
            v_transaction_type,

        p_created_by =>
            v_merchant.id,

        p_components =>
            v_components,

        p_mappings =>
            v_mappings,

        p_currency_code =>
            v_currency,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_reference =>
            v_transaction_reference,

        p_deposit_type =>
            null
    );


    /*
     * ========================================================
     * POST WALLET ENTRIES
     * ========================================================
     *
     * Voucher owner:
     *     debit = v_principal_amount
     *
     * Merchant:
     *     credit = v_amount
     *
     * Therefore v_principal_amount is the exact FI cash/savings
     * outflow for the voucher owner.
     */

    v_stage :=
        'post wallet entries';


    select
        posting_result
            .receiver_notification_id
    into
        v_receiver_notification_id
    from public.post_wallet_entries(
        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_document_number =>
            v_document_number,

        p_reference =>
            v_transaction_reference,

        p_receiver_id =>
            v_merchant.id,

        p_sender_id =>
            v_voucher_owner.id,

        p_transaction_type =>
            v_transaction_type,

        p_credit_amount =>
            v_amount,

        p_debit_amount =>
            v_principal_amount,

        p_sender_wallet_owner =>
            'customer'::public."WalletOwnerType",

        p_receiver_wallet_owner =>
            'merchant'::public."WalletOwnerType",

        p_currency_code =>
            v_currency,

        p_country_code =>
            p_country_code,

        p_audit_action_type =>
            'merchant_payment'::public."AuditActionType",

        p_treasury_id =>
            v_treasury.id,

        p_fee_amount =>
            v_fee,

        p_ip_address =>
            p_ip_address,

        p_receiver_notification =>
            v_receiver_notification,

        p_sender_notification =>
            v_sender_notification
    ) as posting_result;


    /*
     * Find the voucher-owner notification inserted as the
     * sender notification by post_wallet_entries.
     */
    v_stage :=
        'fetch voucher owner notification';


    select
        notification_record.id::text
    into
        v_voucher_owner_notification_id
    from public.notifications
        notification_record
    where notification_record.user_id =
          v_voucher_owner.id
      and notification_record.reference =
          (
              v_sender_notification.payload
              ->> 'reference'
          )
    limit 1;


    /*
     * ========================================================
     * MERCHANT COMMISSION
     * ========================================================
     */

    if v_merchant_commission_amount > 0 then
        v_stage :=
            'create merchant commission';


        insert into public.merchant_commission (
            merchant_id,
            document_number,
            fiscal_year,
            period,
            transaction_type,
            currency_code,
            amount,
            fee_amount,
            commission_rate,
            commission_amount,
            is_settled,
            country_code
        )
        values (
            v_merchant.id,
            v_document_number,
            v_fiscal_year,
            v_period,
            v_transaction_type,
            v_currency,
            v_amount,
            v_fee,
            v_merchant_commission_rate,
            v_merchant_commission_amount,
            false,
            p_country_code
        );
    end if;


    /*
     * ========================================================
     * COMPLETE VOUCHER USAGE
     * ========================================================
     */

    v_stage :=
        'complete voucher usage';


    update public.voucher_usage
    set
        status =
            'success'::public."TransactionStatus",

        message =
            null
    where id::text =
          v_voucher_usage_id
      and status =
          'processing'::public."TransactionStatus";


    if not found then
        raise exception
            'VOUCHER_USAGE_UPDATE_FAILED';
    end if;


    /*
     * ========================================================
     * COMPLETE TRANSACTION STATE
     * ========================================================
     */

    v_stage :=
        'complete transaction state';


    update public.transaction_state
    set
        user_id =
            v_voucher_owner.id,

        status =
            'success'::public."TransactionStatus",

        message =
            null,

        updated_at =
            now()
    where id =
          p_transaction_state_id
      and created_by =
          p_merchant_id
      and transaction_type =
          v_transaction_type
      and status =
          'processing'::public."TransactionStatus";


    if not found then
        raise exception
            'TRANSACTION_STATE_UPDATE_FAILED';
    end if;


    /*
     * ========================================================
     * RESULT
     * ========================================================
     *
     * Loyalty:
     *
     * gross_amount
     * gross_amount_usd
     *
     * Financial Intelligence:
     *
     * spending:
     *     gross_amount / gross_amount_usd
     *
     * cash/savings outflow:
     *     voucher_owner_debit_amount /
     *     voucher_owner_debit_amount_usd
     */

    v_stage :=
        'return result';


    return query
    select
        true,

        v_transaction_reference,

        v_voucher_owner.id,

        trim_scale(
            v_amount
        )::text,

        trim_scale(
            v_fee
        )::text,

        v_currency,

        trim_scale(
            v_voucher_remaining
        )::text,

        v_voucher_owner_notification_id,

        v_device_tokens,

        v_sender_notification.title,

        v_sender_notification.body,

        v_sender_notification.payload
            ->> 'reference',

        /*
         * USD equivalent of merchant purchase amount.
         */
        trim_scale(
            v_amount_usd
        )::text,

        /*
         * Exact voucher-owner wallet debit.
         */
        trim_scale(
            v_principal_amount
        )::text,

        /*
         * USD equivalent of exact voucher-owner wallet debit.
         */
        trim_scale(
            v_voucher_owner_debit_usd
        )::text;


exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;


        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'VOUCHER_PAYMENT_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                coalesce(
                    nullif(
                        concat_ws(
                            E'\n',
                            nullif(
                                v_error_detail,
                                ''
                            ),
                            nullif(
                                v_error_context,
                                ''
                            )
                        ),
                        ''
                    ),
                    'No additional PostgreSQL context'
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    'Check the Voucher Payment stage reported in the error'
                );

end;
$$;
ALTER FUNCTION "public"."complete_voucher_payment"("p_merchant_id" "text", "p_transaction" "jsonb", "p_voucher" "jsonb", "p_country_code" "text", "p_transaction_state_id" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."confirm_liquidation_blockchain_transfer"("p_queue_id" "text", "p_tx_hash" "text", "p_explorer_url" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
    v_queue public.liquidation_blockchain_queue%rowtype;
    v_existing_tx public.blockchain_transaction%rowtype;

    v_queue_id text;
    v_tx_hash text;
    v_receiver text;
    v_explorer_url text;
BEGIN
    IF coalesce(auth.role(), '') <> 'service_role' THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'SERVICE_ROLE_REQUIRED';
    END IF;

    v_queue_id := nullif(btrim(p_queue_id), '');
    v_tx_hash := nullif(btrim(p_tx_hash), '');
    v_explorer_url := nullif(btrim(p_explorer_url), '');

    IF v_queue_id IS NULL THEN
        RAISE EXCEPTION 'LIQUIDATION_QUEUE_ID_REQUIRED';
    END IF;

    IF v_tx_hash IS NULL
       OR v_tx_hash !~ '^0x[0-9A-Fa-f]{64}$'
    THEN
        RAISE EXCEPTION 'INVALID_BLOCKCHAIN_TRANSACTION_HASH';
    END IF;

    SELECT q.*
    INTO v_queue
    FROM public.liquidation_blockchain_queue AS q
    WHERE q.id = v_queue_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'LIQUIDATION_BLOCKCHAIN_QUEUE_NOT_FOUND';
    END IF;

    IF nullif(btrim(v_queue.blockchain_code), '') IS NULL THEN
        RAISE EXCEPTION 'LIQUIDATION_BLOCKCHAIN_CODE_REQUIRED';
    END IF;

    IF (v_queue.signed_payload ->> 'blockchain_code')
       IS DISTINCT FROM v_queue.blockchain_code
    THEN
        RAISE EXCEPTION
            'LIQUIDATION_SIGNED_BLOCKCHAIN_MISMATCH';
    END IF;

    PERFORM 1
    FROM public.liquidation_job AS j
    WHERE j.id::text = v_queue.liquidation_job_id
      AND j.user_id = v_queue.user_id
      AND lower(btrim(j.country_code)) =
          lower(btrim(v_queue.country_code))
      AND j.blockchain_code = v_queue.blockchain_code;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'LIQUIDATION_JOB_BLOCKCHAIN_MISMATCH_OR_NOT_FOUND';
    END IF;

    IF v_queue.tx_hash IS NOT NULL
       AND lower(btrim(v_queue.tx_hash)) <> lower(v_tx_hash)
    THEN
        RAISE EXCEPTION 'LIQUIDATION_BLOCKCHAIN_TX_HASH_MISMATCH';
    END IF;

    /*
     * Preserve idempotency without moving an already
     * completed accounting job back to blockchain_confirmed.
     */
    IF v_queue.status::text = 'confirmed' THEN
        IF v_queue.tx_hash IS NULL THEN
            RAISE EXCEPTION
                'CONFIRMED_LIQUIDATION_TX_HASH_REQUIRED';
        END IF;

        RETURN jsonb_build_object(
            'success', true,
            'queue_id', v_queue.id,
            'liquidation_job_id', v_queue.liquidation_job_id,
            'status', v_queue.status,
            'tx_hash', v_queue.tx_hash,
            'confirmed_at', v_queue.confirmed_at
        );
    END IF;

    /*
     * PostgreSQL records the receipt result supplied by
     * the service worker; it does not fetch the receipt itself.
     */
    PERFORM 1
    FROM public.liquidation_blockchain_queue AS other_queue
    WHERE lower(btrim(other_queue.tx_hash)) = lower(v_tx_hash)
      AND other_queue.id <> v_queue.id;

    IF FOUND THEN
        RAISE EXCEPTION
            'LIQUIDATION_BLOCKCHAIN_TX_HASH_ALREADY_ASSIGNED';
    END IF;

    v_receiver :=
        nullif(btrim(v_queue.signed_payload ->> 'to'), '');

    IF v_receiver IS NULL
       OR v_receiver !~ '^0x[0-9A-Fa-f]{40}$'
    THEN
        RAISE EXCEPTION
            'INVALID_LIQUIDATION_BLOCKCHAIN_RECEIVER';
    END IF;

    IF lower(v_receiver)
       IS DISTINCT FROM lower(v_queue.receiver_wallet_address)
    THEN
        RAISE EXCEPTION
            'LIQUIDATION_RECEIVER_ADDRESS_MISMATCH';
    END IF;

    /*
     * Check an existing audit row instead of silently
     * accepting a hash belonging to a different operation.
     */
    SELECT bt.*
    INTO v_existing_tx
    FROM public.blockchain_transaction AS bt
    WHERE lower(btrim(bt.tx_hash)) = lower(v_tx_hash);

    IF FOUND THEN
        IF v_existing_tx.transaction_type IS DISTINCT FROM
           'loan_liquidation'::public."TransactionType"
           OR v_existing_tx.chain IS DISTINCT FROM
              v_queue.blockchain_code
           OR v_existing_tx.reference IS DISTINCT FROM
              v_queue.document_number
           OR v_existing_tx.document_number IS DISTINCT FROM
              v_queue.document_number
           OR lower(v_existing_tx.sender) IS DISTINCT FROM
              lower(v_queue.sender_wallet_address)
           OR lower(v_existing_tx.receiver) IS DISTINCT FROM
              lower(v_receiver)
           OR v_existing_tx.quantity IS DISTINCT FROM
              v_queue.collateral
        THEN
            RAISE EXCEPTION
                'LIQUIDATION_BLOCKCHAIN_AUDIT_MISMATCH';
        END IF;
    ELSE
        INSERT INTO public.blockchain_transaction (
            document_number,
            fiscal_year,
            country_code,
            period,
            tx_hash,
            reference,
            transaction_type,
            chain,
            sender,
            receiver,
            quantity,
            gross_amount,
            net_amount,
            fee_amount,
            currency_code,
            chain_status,
            status,
            description,
            explorer_url,
            created_by
        )
        VALUES (
            v_queue.document_number,
            v_queue.fiscal_year,
            lower(btrim(v_queue.country_code)),
            v_queue.period,
            v_tx_hash,
            v_queue.document_number,
            'loan_liquidation'::public."TransactionType",

            -- Selected blockchain code, replacing 'chiado'.
            v_queue.blockchain_code,

            v_queue.sender_wallet_address,
            v_receiver,
            v_queue.collateral,
            v_queue.total_debt,
            v_queue.debt_repayment_amount,
            v_queue.penalty_amount,
            'gold',
            'completed',
            'completed'::public."BlockchainTxStatus",
            format(
                'Loan liquidation blockchain transfer for user %s',
                v_queue.user_id
            ),
            v_explorer_url,
            'system'
        );
    END IF;

    UPDATE public.liquidation_blockchain_queue
    SET
        status =
            'confirmed'::public."BlockchainLiquidationStatus",
        tx_hash = v_tx_hash,
        receiver_wallet_address = v_receiver,
        explorer_url = v_explorer_url,
        submitted_at = coalesce(submitted_at, now()),
        confirmed_at = coalesce(confirmed_at, now()),
        manual_review_required = false,
        error_message = NULL,
        lease_expires_at = NULL,
        updated_at = now()
    WHERE id = v_queue.id
    RETURNING * INTO v_queue;

    UPDATE public.liquidation_job
    SET
        status =
            'blockchain_confirmed'::public."LiquidationJobStatus",
        error_message = NULL
    WHERE id::text = v_queue.liquidation_job_id
      AND blockchain_code = v_queue.blockchain_code
      AND status::text IN (
          'pending',
          'blockchain_processing',
          'failed',
          'blockchain_confirmed'
      );

    IF NOT FOUND THEN
        RAISE EXCEPTION 'INVALID_LIQUIDATION_JOB_STATE';
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'queue_id', v_queue.id,
        'liquidation_job_id', v_queue.liquidation_job_id,
        'status', v_queue.status,
        'tx_hash', v_queue.tx_hash,
        'confirmed_at', v_queue.confirmed_at
    );
END;
$_$;
ALTER FUNCTION "public"."confirm_liquidation_blockchain_transfer"("p_queue_id" "text", "p_tx_hash" "text", "p_explorer_url" "text") OWNER TO "postgres";
CREATE TABLE IF NOT EXISTS "public"."users" (
    "id" "text" NOT NULL,
    "email" "text",
    "phone" "text",
    "country_code" "text" NOT NULL,
    "first_name" "text",
    "middle_name" "text",
    "surname" "text",
    "dob" timestamp(3) without time zone,
    "nationality" "text",
    "residential_address" "text",
    "status" "public"."UserStatus" DEFAULT 'active'::"public"."UserStatus" NOT NULL,
    "preferred_language" "text" DEFAULT 'en'::"text" NOT NULL,
    "role_id" "text" NOT NULL,
    "wallet_address" "text" NOT NULL,
    "wallet_index" bigint NOT NULL,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp(6) with time zone DEFAULT "now"() NOT NULL,
    "upliner" "text",
    "referral_code" "text" NOT NULL,
    "gender" "public"."GenderType",
    "city" "text",
    "province_state" "text"
);
ALTER TABLE "public"."users" OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."create_customer_profile"("p_user_id" "uuid", "p_country_code" "text", "p_phone" "text", "p_email" "text", "p_wallet_address" "text", "p_wallet_index" bigint, "p_referral_code" "text", "p_upliner_code" "text" DEFAULT NULL::"text") RETURNS "public"."users"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_role_id uuid;
  v_upliner text;
  v_user public.users%rowtype;
begin
  select id
  into v_role_id
  from public.user_role
  where name = 'customer'
  limit 1;

  if v_role_id is null then
    raise exception 'ROLE_NOT_CONFIGURED';
  end if;

  v_upliner := null;

  if nullif(trim(p_upliner_code), '') is not null then
    select referral_code
    into v_upliner
    from public.users
    where referral_code = trim(p_upliner_code)
    limit 1;
  end if;

  insert into public.users (
    id,
    email,
    phone,
    country_code,
    role_id,
    wallet_address,
    wallet_index,
    referral_code,
    upliner
  )
  values (
    p_user_id,
    nullif(trim(p_email), ''),
    trim(p_phone),
    lower(trim(p_country_code)),
    v_role_id,
    p_wallet_address,
    p_wallet_index,
    p_referral_code,
    v_upliner
  )
  returning *
  into v_user;

  return v_user;
end;
$$;
ALTER FUNCTION "public"."create_customer_profile"("p_user_id" "uuid", "p_country_code" "text", "p_phone" "text", "p_email" "text", "p_wallet_address" "text", "p_wallet_index" bigint, "p_referral_code" "text", "p_upliner_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."create_my_agent_commission_settlement_batch"("p_currency_code" "text", "p_start_date" "date", "p_end_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_currency_code text;

    v_fiscal_year integer;
    v_period integer;

    v_document_number text;

    v_total_agents integer := 0;
    v_total_amount numeric := 0;

    v_batch public.agent_settlement_batch%rowtype;

    v_items jsonb :=
        '[]'::jsonb;

    v_stage text :=
        'initialization';

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * Authentication and authorization.
     */
    v_stage :=
        'authorize accounts user';

    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'accounts'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Fetch trusted Accounts user context.
     */
    v_stage :=
        'fetch accounts user';

    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'ACCOUNTS_USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'ACCOUNTS_USER_NOT_ACTIVE';
    end if;

    if nullif(
        btrim(
            v_user.country_code
        ),
        ''
    ) is null
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Validate input.
     */
    v_stage :=
        'validate input';

    v_currency_code :=
        lower(
            nullif(
                btrim(
                    p_currency_code
                ),
                ''
            )
        );

    if v_currency_code is null then
        raise exception
            'CURRENCY_CODE_REQUIRED';
    end if;

    if v_currency_code = 'gold' then
        raise exception
            'INVALID_COMMISSION_SETTLEMENT_CURRENCY';
    end if;

    if p_start_date is null then
        raise exception
            'START_DATE_REQUIRED';
    end if;

    if p_end_date is null then
        raise exception
            'END_DATE_REQUIRED';
    end if;

    if p_start_date > p_end_date then
        raise exception
            'INVALID_SETTLEMENT_DATE_RANGE';
    end if;

    /*
     * Confirm that the currency is configured for the
     * Accounts user's country.
     */
    perform 1
    from public.country_currencies
        currency_record
    where lower(
        btrim(
            currency_record.country_code
        )
    ) =
        lower(
            btrim(
                v_user.country_code
            )
        )

      and lower(
          btrim(
              currency_record.currency_code
          )
      ) =
        v_currency_code

      and currency_record.is_active =
        true
    limit 1;

    if not found then
        raise exception
            'COUNTRY_CURRENCY_NOT_ACTIVE';
    end if;

    /*
    * Prevent another settlement batch from being created
    * while the currency already has an unfinished payment.
    */
    v_stage :=
        'check existing payment underway';

    perform 1
    from public.agent_settlement_batch
        batch_record
    where lower(
        btrim(
            batch_record.country_code
        )
    ) =
        lower(
            btrim(
                v_user.country_code
            )
        )

    and lower(
        btrim(
            batch_record.currency_code
        )
    ) =
        v_currency_code

    and batch_record.status <>
        'settled'::public."SettlementStatus"
    limit 1;

    if found then
        raise exception
            'AGENT_COMMISSION_PAYMENT_ALREADY_UNDERWAY_%',
            upper(
                v_currency_code
            );
    end if;
    /*
     * Lock every eligible commission row.
     *
     * The end date is inclusive. Therefore, entries are
     * selected until the start of the following day.
     *
     * settlement_batch_id must be null so the same
     * commission cannot be included in multiple batches.
     */
    v_stage :=
        'lock unsettled commissions';

    perform 1
    from public.agent_commission
        commission_record
    where lower(
        btrim(
            commission_record.country_code
        )
    ) =
        lower(
            btrim(
                v_user.country_code
            )
        )

      and lower(
          btrim(
              commission_record.currency_code
          )
      ) =
        v_currency_code

      and commission_record.is_settled =
        false

      and commission_record.settlement_batch_id
          is null

      and commission_record.created_at >=
        p_start_date::timestamptz

      and commission_record.created_at <
        (
            p_end_date +
            1
        )::timestamptz
    for update;

    if not found then
        raise exception using
            errcode = 'P0001',

            message =
                'NO_PENDING_AGENT_COMMISSIONS_FOR_DATE_RANGE',

            detail =
                format(
                    'No unbatched Agent Commission entries were found for currency %s between %s and %s',
                    upper(v_currency_code),
                    p_start_date,
                    p_end_date
                ),

            hint =
                'Adjust the settlement start date or end date and try again';
    end if;

    /*
     * Calculate batch totals.
     *
     * agent_id is also used for vendors and merchants
     * earning withdrawal commission.
     */
    v_stage :=
        'calculate settlement totals';

    select
        count(
            distinct commission_record.agent_id
        )::integer,

        coalesce(
            sum(
                commission_record.commission_amount
            ),
            0
        )::numeric
    into
        v_total_agents,
        v_total_amount
    from public.agent_commission
        commission_record
    where lower(
        btrim(
            commission_record.country_code
        )
    ) =
        lower(
            btrim(
                v_user.country_code
            )
        )

      and lower(
          btrim(
              commission_record.currency_code
          )
      ) =
        v_currency_code

      and commission_record.is_settled =
        false

      and commission_record.settlement_batch_id
          is null

      and commission_record.created_at >=
        p_start_date::timestamptz

      and commission_record.created_at <
        (
            p_end_date +
            1
        )::timestamptz;

    if v_total_agents <= 0
       or v_total_amount <= 0
    then
        raise exception
            'INVALID_AGENT_COMMISSION_SETTLEMENT_TOTAL';
    end if;

    /*
     * Fetch fiscal period.
     */
    v_stage :=
        'fetch fiscal period';

    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_user.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Generate settlement document number.
     */
    v_stage :=
        'generate document number';

    v_document_number :=
        public.generate_document_number(
            'AGENT-COMM',
            v_fiscal_year,
            v_period,
            v_user.country_code
        );

    /*
     * Create the batch header.
     */
    v_stage :=
        'create settlement batch';

    insert into public.agent_settlement_batch (
        document_number,
        fiscal_year,
        period,
        currency_code,
        start_date,
        end_date,
        total_agents,
        total_amount,
        created_by,
        country_code
    )
    values (
        v_document_number,
        v_fiscal_year,
        v_period,
        v_currency_code,
        p_start_date,
        p_end_date,
        v_total_agents,
        v_total_amount,
        v_user.id,
        lower(
            btrim(
                v_user.country_code
            )
        )
    )
    returning *
    into v_batch;

    /*
     * Create one settlement item per commission earner.
     *
     * agent_id may belong to an agent, vendor or merchant.
     */
    v_stage :=
        'create settlement items';

    insert into public.agent_settlement_item (
        batch_id,
        agent_id,
        fiscal_year,
        period,
        currency_code,
        total_commission,
        total_withdrawal_volume,
        total_fees_generated,
        country_code
    )
    select
        v_batch.id,
        commission_record.agent_id,
        v_fiscal_year,
        v_period,
        v_currency_code,

        coalesce(
            sum(
                commission_record.commission_amount
            ),
            0
        ),

        coalesce(
            sum(
                commission_record.amount
            ),
            0
        ),

        coalesce(
            sum(
                commission_record.fee_amount
            ),
            0
        ),

        lower(
            btrim(
                v_user.country_code
            )
        )

    from public.agent_commission
        commission_record

    where lower(
        btrim(
            commission_record.country_code
        )
    ) =
        lower(
            btrim(
                v_user.country_code
            )
        )

      and lower(
          btrim(
              commission_record.currency_code
          )
      ) =
        v_currency_code

      and commission_record.is_settled =
        false

      and commission_record.settlement_batch_id
          is null

      and commission_record.created_at >=
        p_start_date::timestamptz

      and commission_record.created_at <
        (
            p_end_date +
            1
        )::timestamptz

    group by
        commission_record.agent_id;

    if not found then
        raise exception
            'AGENT_SETTLEMENT_ITEMS_NOT_CREATED';
    end if;

    /*
     * Reserve the underlying commission rows for this
     * batch.
     *
     * They remain unpaid until the batch payment process
     * sets is_settled to true.
     */
    v_stage :=
        'assign commissions to settlement batch';

    update public.agent_commission
    set
        settlement_batch_id =
            v_batch.id
    where lower(
        btrim(
            country_code
        )
    ) =
        lower(
            btrim(
                v_user.country_code
            )
        )

      and lower(
          btrim(
              currency_code
          )
      ) =
        v_currency_code

      and is_settled =
        false

      and settlement_batch_id
          is null

      and created_at >=
        p_start_date::timestamptz

      and created_at <
        (
            p_end_date +
            1
        )::timestamptz;

    if not found then
        raise exception
            'AGENT_COMMISSIONS_NOT_ASSIGNED_TO_BATCH';
    end if;

    /*
     * Return the created items.
     */
    v_stage :=
        'build result';

    select coalesce(
        jsonb_agg(
            to_jsonb(
                item_record
            )
            ||
            jsonb_build_object(
                'total_commission',
                item_record.total_commission::text,

                'total_withdrawal_volume',
                item_record.total_withdrawal_volume::text,

                'total_fees_generated',
                item_record.total_fees_generated::text
            )
            order by
                item_record.agent_id
        ),
        '[]'::jsonb
    )
    into v_items
    from public.agent_settlement_item
        item_record
    where item_record.batch_id =
          v_batch.id;

    return jsonb_build_object(
        'batch',
        to_jsonb(
            v_batch
        )
        ||
        jsonb_build_object(
            'total_amount',
            v_batch.total_amount::text
        ),

        'items',
        v_items
    );

exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;

        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'AGENT_COMMISSION_SETTLEMENT_BATCH_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                concat_ws(
                    E'\n',
                    nullif(
                        v_error_detail,
                        ''
                    ),
                    nullif(
                        v_error_context,
                        ''
                    )
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    'Check the Agent Commission Settlement Batch stage reported in the error'
                );
end;
$$;
ALTER FUNCTION "public"."create_my_agent_commission_settlement_batch"("p_currency_code" "text", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."create_my_cash_deposit_state"("p_transaction" "jsonb", "p_sender_approval" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user_id text;
    v_country_code text;
    v_provider_id text;
    v_reference text;
    v_transaction_state_id text;
begin
    /*
     * Validate authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Validate initiating role.
     */
    if not public.has_role(
        array[
            'customer'::public."Role",
            'agent'::public."Role",
            'vendor'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    if p_transaction is null
       or jsonb_typeof(p_transaction) <>
          'object'
    then
        raise exception
            'TRANSACTION_DATA_MISSING';
    end if;

    if p_sender_approval is null
       or jsonb_typeof(p_sender_approval) <>
          'object'
    then
        raise exception
            'SENDER_APPROVAL_MISSING';
    end if;

    v_reference :=
        nullif(
            btrim(p_transaction ->> 'r'),
            ''
        );

    if v_reference is null then
        raise exception
            'REFERENCE_MISSING';
    end if;

    v_provider_id :=
        nullif(
            btrim(p_transaction ->> 's'),
            ''
        );

    if v_provider_id is null then
        raise exception
            'PROVIDER_ID_MISSING';
    end if;

    v_user_id :=
        auth.uid()::text;

    if v_user_id = v_provider_id then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    /*
     * Validate the provider role.
     */
    if not public.user_has_role(
        v_provider_id,
        array[
            'agent'::public."Role",
            'merchant'::public."Role",
            'vendor'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'PROVIDER_NOT_AUTHORIZED';
    end if;

    /*
     * Read the initiating user's country and ensure that
     * the provider belongs to the same country.
     */
    select user_record.country_code
    into v_country_code
    from public.users user_record
    join public.users provider_record
      on provider_record.id =
         v_provider_id
    where user_record.id =
          v_user_id
      and user_record.status =
          'active'::public."UserStatus"
      and provider_record.status =
          'active'::public."UserStatus"
      and provider_record.country_code =
          user_record.country_code
    limit 1;

    if not found then
        raise exception
            'CASH_DEPOSIT_PARTICIPANTS_NOT_VALID';
    end if;

    /*
     * Reference is unique and provides replay protection.
     */
    insert into public.transaction_state (
        reference,
        status,
        transaction_type,
        country_code,
        transaction_data,
        sender_approval,
        created_by,
        user_id
    )
    values (
        v_reference,
        'processing'::public."TransactionStatus",
        'cash_deposit'::public."TransactionType",
        v_country_code,
        p_transaction,
        p_sender_approval,
        v_user_id,
        v_provider_id
    )
    returning id::text
    into v_transaction_state_id;

    return v_transaction_state_id;

exception
    when unique_violation then
        raise exception using
            errcode = '23505',
            message = 'TRANSACTION_REPLAY';
end;
$$;
ALTER FUNCTION "public"."create_my_cash_deposit_state"("p_transaction" "jsonb", "p_sender_approval" "jsonb") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."create_my_cash_withdrawal_state"("p_transaction" "jsonb", "p_sender_approval" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_agent_id text;
    v_user_id text;
    v_country_code text;
    v_reference text;
    v_version text;

    v_transaction_state_id text;
begin
    /*
     * Validate authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Only agents, vendors and merchants may initiate
     * cash withdrawals.
     */
    if not public.has_role(
        array[
            'agent'::public."Role",
            'merchant'::public."Role",
            'vendor'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Validate the supplied signed objects.
     */
    if p_transaction is null
       or jsonb_typeof(p_transaction) <>
          'object'
    then
        raise exception
            'TRANSACTION_DATA_IS_MISSING';
    end if;

    if p_sender_approval is null
       or jsonb_typeof(p_sender_approval) <>
          'object'
    then
        raise exception
            'SENDER_APPROVAL_IS_MISSING';
    end if;

    /*
     * Validate the transaction version.
     */
    v_version :=
        nullif(
            btrim(p_transaction ->> 'v'),
            ''
        );

    if v_version is distinct from 'v3' then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    /*
     * Parse the unique transaction reference.
     */
    v_reference :=
        nullif(
            btrim(p_transaction ->> 'r'),
            ''
        );

    if v_reference is null then
        raise exception
            'REFERENCE_MISSING';
    end if;

    /*
     * transaction.s is the withdrawing user.
     */
    v_user_id :=
        nullif(
            btrim(p_transaction ->> 's'),
            ''
        );

    if v_user_id is null then
        raise exception
            'USER_ID_MISSING';
    end if;

    v_agent_id :=
        auth.uid()::text;

    if v_agent_id = v_user_id then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    /*
     * Validate the withdrawing user's role.
     */
    if not public.user_has_role(
        v_user_id,
        array[
            'customer'::public."Role",
            'agent'::public."Role",
            'vendor'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'USER_NOT_AUTHORIZED';
    end if;

    /*
     * Fetch the agent country and ensure both users
     * belong to the same country.
     */
    select agent_record.country_code
    into v_country_code
    from public.users agent_record
    join public.users user_record
      on user_record.id =
         v_user_id
    where agent_record.id =
          v_agent_id
      and agent_record.status =
          'active'::public."UserStatus"
      and user_record.status =
          'active'::public."UserStatus"
      and agent_record.country_code =
          user_record.country_code
    limit 1;

    if not found then
        raise exception
            'CASH_WITHDRAWAL_PARTICIPANTS_NOT_VALID';
    end if;

    /*
     * Reference is unique and provides replay protection.
     */
    insert into public.transaction_state (
        reference,
        status,
        transaction_type,
        country_code,
        transaction_data,
        sender_approval,
        created_by,
        user_id
    )
    values (
        v_reference,
        'processing'::public."TransactionStatus",
        'cash_withdrawal'::public."TransactionType",
        v_country_code,
        p_transaction,
        p_sender_approval,
        v_agent_id,
        v_user_id
    )
    returning id::text
    into v_transaction_state_id;

    return v_transaction_state_id;

exception
    when unique_violation then
        raise exception using
            errcode = '23505',
            message = 'TRANSACTION_REPLAY';
end;
$$;
ALTER FUNCTION "public"."create_my_cash_withdrawal_state"("p_transaction" "jsonb", "p_sender_approval" "jsonb") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."create_my_credit_agent_cash_deposit_state"("p_transaction" "jsonb", "p_sender_approval" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;
    v_provider public.users%rowtype;

    v_transaction_state_id
        public.transaction_state.id%type;

    v_reference text;
    v_provider_id text;
    v_currency_code text;
    v_version text;
    v_approval_user_id text;

    v_stage text := 'initialization';
    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * Authentication.
     */
    v_stage := 'authenticate user';

    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    /*
     * Validate JSON input.
     */
    v_stage := 'validate input';

    if p_transaction is null
       or p_transaction =
          'null'::jsonb
    then
        raise exception
            'TRANSACTION_DATA_MISSING';
    end if;

    if p_sender_approval is null
       or p_sender_approval =
          'null'::jsonb
    then
        raise exception
            'SENDER_APPROVAL_MISSING';
    end if;

    v_version :=
        nullif(
            btrim(
                p_transaction ->> 'v'
            ),
            ''
        );

    v_reference :=
        nullif(
            btrim(
                p_transaction ->> 'r'
            ),
            ''
        );

    v_provider_id :=
        nullif(
            btrim(
                p_transaction ->> 's'
            ),
            ''
        );

    v_currency_code :=
        lower(
            nullif(
                btrim(
                    p_transaction ->> 'c'
                ),
                ''
            )
        );

    v_approval_user_id :=
        nullif(
            btrim(
                p_sender_approval ->> 'b'
            ),
            ''
        );

    if v_version is null then
        raise exception
            'TRANSACTION_VERSION_REQUIRED';
    end if;

    if v_version <> 'v1' then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    if v_reference is null then
        raise exception
            'REFERENCE_REQUIRED';
    end if;

    if v_provider_id is null then
        raise exception
            'PROVIDER_ID_REQUIRED';
    end if;

    if v_currency_code is null then
        raise exception
            'CURRENCY_REQUIRED';
    end if;

    if v_currency_code = 'gold' then
        raise exception
            'CREDIT_AGENT_CURRENCY_MUST_BE_FIAT';
    end if;

    if v_approval_user_id is null then
        raise exception
            'APPROVAL_USER_ID_REQUIRED';
    end if;

    if v_approval_user_id <>
       auth.uid()::text
    then
        raise exception
            'APPROVAL_USER_MISMATCH';
    end if;

    if v_provider_id =
       auth.uid()::text
    then
        raise exception
            'INVALID_DEPOSIT_PROVIDER';
    end if;

    /*
     * Reuse the established cash-deposit context.
     *
     * It validates:
     *
     * - authenticated initiating user;
     * - provider;
     * - user status;
     * - provider status;
     * - country;
     * - transaction version.
     */
    v_stage := 'validate cash deposit context';

    perform 1
    from public.fetch_my_cash_deposit_context(
        p_v =>
            v_version,

        p_provider_id =>
            v_provider_id
    );

    if not found then
        raise exception
            'CASH_DEPOSIT_CONTEXT_NOT_FOUND';
    end if;

    /*
     * Fetch authenticated user.
     */
    v_stage := 'fetch user';

    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'USER_NOT_ACTIVE';
    end if;

    if v_user.country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * The provider must specifically be an active merchant.
     *
     * Normal agents may use cash_deposit but cannot use
     * credit_agent_cash_deposit.
     */
    v_stage := 'fetch merchant provider';

    select user_record.*
    into v_provider
    from public.users user_record
    join public.user_role role_record
      on role_record.id =
         user_record.role_id
    where user_record.id =
              v_provider_id

      and user_record.country_code =
              v_user.country_code

      and user_record.status =
              'active'::public."UserStatus"

      and lower(
          role_record.name::text
      ) =
              'merchant'
    limit 1;

    if not found then
        raise exception
            'CREDIT_AGENT_MERCHANT_NOT_FOUND';
    end if;

    /*
     * The merchant must have an active credit-agent account for
     * the transaction currency.
     *
     * Approval creates accounts for every active fiat currency.
     */
    v_stage := 'validate credit agent account';

    perform 1
    from public.credit_agent_account
        account_record
    where account_record.merchant_id =
              v_provider.id

      and account_record.country_code =
              v_user.country_code

      and account_record.currency_code =
              v_currency_code

      and account_record.is_active =
              true
    limit 1;

    if not found then
        raise exception
            'MERCHANT_NOT_APPROVED_FOR_CREDIT_FACILITY';
    end if;

    /*
     * Prevent reference replay.
     */
    v_stage := 'check transaction replay';

    perform 1
    from public.transaction_state
        state_record
    where state_record.reference =
          v_reference
    limit 1;

    if found then
        raise exception
            'TRANSACTION_REPLAY';
    end if;

    /*
     * Create processing state.
     */
    v_stage := 'create transaction state';

    insert into public.transaction_state (
        reference,
        status,
        transaction_type,
        country_code,
        transaction_data,
        sender_approval,
        created_by,
        user_id
    )
    values (
        v_reference,
        'processing'::public."TransactionStatus",
        'credit_agent_cash_deposit'::public."TransactionType",
        v_user.country_code,
        p_transaction,
        p_sender_approval,
        v_user.id,
        v_provider.id
    )
    returning id
    into v_transaction_state_id;

    return v_transaction_state_id::text;

exception
    when unique_violation then
        raise exception
            'TRANSACTION_REPLAY';

    when others then
        get stacked diagnostics
            v_error_state = returned_sqlstate,
            v_error_message = message_text,
            v_error_detail = pg_exception_detail,
            v_error_hint = pg_exception_hint,
            v_error_context = pg_exception_context;

        raise exception using
            errcode = v_error_state,

            message = format(
                'CREATE_CREDIT_AGENT_CASH_DEPOSIT_STATE_FAILED at [%s]: %s',
                v_stage,
                v_error_message
            ),

            detail = concat_ws(
                E'\n',
                nullif(v_error_detail, ''),
                nullif(v_error_context, '')
            ),

            hint = coalesce(
                nullif(v_error_hint, ''),
                'Check the Credit Agent Cash Deposit State stage reported in the error'
            );
end;
$$;
ALTER FUNCTION "public"."create_my_credit_agent_cash_deposit_state"("p_transaction" "jsonb", "p_sender_approval" "jsonb") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."create_my_credit_agent_cash_settlement_state"("p_transaction" "jsonb", "p_sender_approval" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
    v_stage text :=
        'initialization';

    v_authenticated_merchant_id text;

    v_transaction_version text;
    v_reference text;
    v_accounts_id text;
    v_currency_code text;

    v_amount_minor numeric;

    v_approval_merchant_id text;

    v_context record;

    v_transaction_state_id
        public.transaction_state.id%type;

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * The merchant scans the accounts-generated
     * transaction and submits the signed approval.
     */
    if auth.uid() is null then
        raise exception using
            errcode =
                '42501',

            message =
                'UNAUTHORIZED';
    end if;

    v_authenticated_merchant_id :=
        auth.uid()::text;

    if not public.has_role(
        array[
            'merchant'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode =
                '42501',

            message =
                'FORBIDDEN';
    end if;

    if p_transaction is null then
        raise exception
            'TRANSACTION_DATA_IS_MISSING';
    end if;

    if p_sender_approval is null then
        raise exception
            'SENDER_APPROVAL_IS_MISSING';
    end if;

    /*
     * Read signed transaction fields.
     *
     * v = transaction version
     * r = reference
     * s = accounts user ID
     * c = currency
     * a = amount in minor units
     */
    v_stage :=
        'read transaction fields';

    v_transaction_version :=
        nullif(
            btrim(
                p_transaction ->> 'v'
            ),
            ''
        );

    v_reference :=
        nullif(
            btrim(
                p_transaction ->> 'r'
            ),
            ''
        );

    v_accounts_id :=
        nullif(
            btrim(
                p_transaction ->> 's'
            ),
            ''
        );

    v_currency_code :=
        lower(
            nullif(
                btrim(
                    p_transaction ->> 'c'
                ),
                ''
            )
        );

    /*
     * The approval must belong to the authenticated
     * merchant submitting the request.
     */
    v_approval_merchant_id :=
        nullif(
            btrim(
                p_sender_approval ->> 'b'
            ),
            ''
        );

    if v_transaction_version <> 'v8' then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    if v_reference is null then
        raise exception
            'REFERENCE_REQUIRED';
    end if;

    if v_accounts_id is null then
        raise exception
            'ACCOUNTS_ID_MISSING';
    end if;

    if v_currency_code is null then
        raise exception
            'CURRENCY_REQUIRED';
    end if;

    if v_currency_code = 'gold' then
        raise exception
            'INVALID_SETTLEMENT_CURRENCY';
    end if;

    if coalesce(
        p_transaction ->> 'a',
        ''
    ) !~ '^[0-9]+$'
    then
        raise exception
            'INVALID_AMOUNT';
    end if;

    v_amount_minor :=
        (p_transaction ->> 'a')::numeric;

    if v_amount_minor <= 0 then
        raise exception
            'INVALID_AMOUNT';
    end if;

    if v_approval_merchant_id is null then
        raise exception
            'APPROVAL_USER_ID_REQUIRED';
    end if;

    if v_approval_merchant_id <>
       v_authenticated_merchant_id
    then
        raise exception
            'APPROVAL_USER_MISMATCH';
    end if;

    if v_accounts_id =
       v_authenticated_merchant_id
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    /*
     * Reuse the trusted settlement context.
     *
     * This confirms:
     *
     * - authenticated user is an active merchant;
     * - transaction.s is an active accounts user;
     * - both users belong to the same country;
     * - the merchant has an active credit-agent account;
     * - treasury exists for the merchant country;
     * - v1 is configured.
     */
    v_stage :=
        'fetch settlement context';

    select context_record.*
    into v_context
    from public.fetch_my_credit_agent_cash_settlement_context(
        p_v =>
            v_transaction_version,

        p_accounts_id =>
            v_accounts_id,

        p_currency_code =>
            v_currency_code
    ) as context_record;

    if not found then
        raise exception
            'CREDIT_AGENT_CASH_SETTLEMENT_CONTEXT_NOT_FOUND';
    end if;

    if v_context.merchant_id is null
       or v_context.merchant_id <>
          v_authenticated_merchant_id
    then
        raise exception
            'MERCHANT_MISMATCH';
    end if;

    if v_context.accounts_id is null
       or v_context.accounts_id <>
          v_accounts_id
    then
        raise exception
            'ACCOUNTS_USER_MISMATCH';
    end if;

    if v_context.merchant_country_code is null then
        raise exception
            'MERCHANT_COUNTRY_NOT_CONFIGURED';
    end if;

    if v_context.accounts_country_code is null then
        raise exception
            'ACCOUNTS_COUNTRY_NOT_CONFIGURED';
    end if;

    if v_context.merchant_country_code <>
       v_context.accounts_country_code
    then
        raise exception
            'COUNTRY_MISMATCH';
    end if;

    if v_context.treasury_id is null then
        raise exception
            'TREASURY_NOT_FOUND';
    end if;

    /*
     * Reject a previously used signed reference.
     */
    v_stage :=
        'check transaction replay';

    perform 1
    from public.transaction_state
        transaction_state_record
    where transaction_state_record.reference =
          v_reference
    limit 1;

    if found then
        raise exception using
            errcode =
                '23505',

            message =
                'TRANSACTION_REPLAY';
    end if;

    /*
     * The authenticated merchant creates the state.
     *
     * The accounts user is stored as the other signed
     * participant and will later be recorded as the
     * financial transaction creator.
     */
    v_stage :=
        'create transaction state';

    insert into public.transaction_state (
        reference,
        transaction_type,
        transaction_data,
        sender_approval,
        status,
        created_by,
        user_id,
        country_code,
        created_at,
        updated_at
    )
    values (
        v_reference,
        'credit_agent_cash_settlement'::public."TransactionType",
        p_transaction,
        p_sender_approval,
        'processing'::public."TransactionStatus",
        v_authenticated_merchant_id,
        v_accounts_id,
        v_context.merchant_country_code,
        now(),
        now()
    )
    returning id
    into v_transaction_state_id;

    return
        v_transaction_state_id::text;

exception
    when unique_violation then
        raise exception using
            errcode =
                '23505',

            message =
                'TRANSACTION_REPLAY';

    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;

        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'CREATE_CREDIT_AGENT_CASH_SETTLEMENT_STATE_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                concat_ws(
                    E'\n',
                    nullif(
                        v_error_detail,
                        ''
                    ),
                    nullif(
                        v_error_context,
                        ''
                    )
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    format(
                        'Check the Credit Agent Cash Settlement State stage: %s',
                        v_stage
                    )
                );
end;
$_$;
ALTER FUNCTION "public"."create_my_credit_agent_cash_settlement_state"("p_transaction" "jsonb", "p_sender_approval" "jsonb") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."create_my_credit_agent_cash_withdrawal_state"("p_transaction" "jsonb", "p_sender_approval" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_stage text :=
        'initialization';

    v_authenticated_user_id text;

    v_transaction_version text;
    v_reference text;
    v_user_id text;
    v_currency_code text;

    v_approval_user_id text;

    v_context record;

    v_merchant public.users%rowtype;
    v_user public.users%rowtype;

    v_credit_agent_account
        public.credit_agent_account%rowtype;

    v_transaction_state_id
        public.transaction_state.id%type;

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * Authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode =
                '42501',

            message =
                'UNAUTHORIZED';
    end if;

    v_authenticated_user_id :=
        auth.uid()::text;

    if p_transaction is null then
        raise exception
            'TRANSACTION_DATA_IS_MISSING';
    end if;

    if p_sender_approval is null then
        raise exception
            'SENDER_APPROVAL_IS_MISSING';
    end if;

    /*
     * Read the signed transaction fields.
     *
     * v = transaction version
     * r = transaction reference
     * s = withdrawing customer
     * c = currency
     */
    v_stage :=
        'read transaction fields';

    v_transaction_version :=
        nullif(
            btrim(
                p_transaction ->> 'v'
            ),
            ''
        );

    v_reference :=
        nullif(
            btrim(
                p_transaction ->> 'r'
            ),
            ''
        );

    v_user_id :=
        nullif(
            btrim(
                p_transaction ->> 's'
            ),
            ''
        );

    v_currency_code :=
        lower(
            nullif(
                btrim(
                    p_transaction ->> 'c'
                ),
                ''
            )
        );

    /*
     * The approval belongs to the authenticated merchant.
     */
    v_approval_user_id :=
        nullif(
            btrim(
                p_sender_approval ->> 'b'
            ),
            ''
        );

    if v_transaction_version is null then
        raise exception
            'TRANSACTION_VERSION_REQUIRED';
    end if;

    if v_transaction_version <> 'v3' then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    if v_reference is null then
        raise exception
            'REFERENCE_REQUIRED';
    end if;

    if v_user_id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_currency_code is null then
        raise exception
            'CURRENCY_REQUIRED';
    end if;

    if v_approval_user_id is null then
        raise exception
            'APPROVAL_USER_ID_REQUIRED';
    end if;

    if v_approval_user_id <>
       v_authenticated_user_id
    then
        raise exception
            'APPROVAL_USER_MISMATCH';
    end if;

    if v_user_id =
       v_authenticated_user_id
    then
        raise exception
            'SELF_TRANSACTION_NOT_ALLOWED';
    end if;

    /*
     * Reuse the existing cash-withdrawal context.
     *
     * It validates the authenticated provider, the
     * customer, countries, wallet addresses and v3
     * transaction configuration.
     */
    v_stage :=
        'fetch cash withdrawal context';

    select context_record.*
    into v_context
    from public.fetch_my_cash_withdrawal_context(
        p_v =>
            v_transaction_version,

        p_user_id =>
            v_user_id
    ) as context_record;

    if not found then
        raise exception
            'CASH_WITHDRAWAL_CONTEXT_NOT_FOUND';
    end if;

    if v_context.agent_id is null then
        raise exception
            'MERCHANT_NOT_FOUND';
    end if;

    if v_context.agent_id <>
       v_authenticated_user_id
    then
        raise exception
            'MERCHANT_MISMATCH';
    end if;

    if v_context.user_id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_context.user_id <>
       v_user_id
    then
        raise exception
            'USER_MISMATCH';
    end if;

    if v_context.country_code is null then
        raise exception
            'MERCHANT_COUNTRY_NOT_CONFIGURED';
    end if;

    if v_context.user_country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    if lower(v_context.country_code) <>
       lower(v_context.user_country_code)
    then
        raise exception
            'COUNTRY_MISMATCH';
    end if;

    /*
     * Explicitly require the authenticated provider to
     * be an active merchant.
     */
    v_stage :=
        'validate merchant';

    select merchant_record.*
    into v_merchant
    from public.users merchant_record
    join public.user_role role_record
      on role_record.id =
         merchant_record.role_id
    where merchant_record.id =
          v_authenticated_user_id

      and merchant_record.status =
          'active'::public."UserStatus"

      and lower(
          role_record.name::text
      ) =
          'merchant'

      and lower(
          merchant_record.country_code
      ) =
          lower(v_context.country_code)
    limit 1;

    if not found then
        raise exception using
            errcode =
                '42501',

            message =
                'MERCHANT_NOT_AUTHORIZED';
    end if;

    /*
     * Confirm that the withdrawing user is still active.
     */
    v_stage :=
        'validate withdrawing user';

    select user_record.*
    into v_user
    from public.users user_record
    where user_record.id =
          v_user_id

      and user_record.status =
          'active'::public."UserStatus"

      and lower(
          user_record.country_code
      ) =
          lower(v_merchant.country_code)
    limit 1;

    if not found then
        raise exception
            'USER_NOT_ACTIVE';
    end if;

    /*
     * The merchant-wide approval creates one operational
     * balance row for each supported fiat currency.
     *
     * This check confirms that the merchant is approved
     * and active for the signed transaction currency.
     */
    v_stage :=
        'validate credit agent account';

    select account_record.*
    into v_credit_agent_account
    from public.credit_agent_account
        account_record
    where account_record.merchant_id =
          v_merchant.id

      and lower(
          account_record.country_code
      ) =
          lower(v_merchant.country_code)

      and lower(
          account_record.currency_code
      ) =
          v_currency_code

      and account_record.is_active =
          true
    limit 1;

    if not found then
        raise exception
            'CREDIT_AGENT_ACCOUNT_NOT_ACTIVE';
    end if;

    /*
     * A credit-agent withdrawal may use:
     *
     * 1. cash already held by the merchant;
     * 2. the remaining receivable balance;
     * 3. or a combination of both.
     *
     * The exact balance split is calculated later inside
     * the service-only posting transaction while the
     * credit-agent account is locked.
     */
    if
        coalesce(
            v_credit_agent_account.cash_holding_balance,
            0
        ) +
        coalesce(
            v_credit_agent_account.receivable_balance,
            0
        )
        <= 0
    then
        raise exception
            'CREDIT_AGENT_WITHDRAWAL_BALANCE_NOT_AVAILABLE';
    end if;

    /*
     * Prevent reference replay before creating another
     * processing state.
     */
    v_stage :=
        'check transaction replay';

    perform 1
    from public.transaction_state
        transaction_state_record
    where transaction_state_record.reference =
          v_reference
    limit 1;

    if found then
        raise exception using
            errcode =
                '23505',

            message =
                'TRANSACTION_REPLAY';
    end if;

    /*
     * Store the signed payloads exactly as received.
     *
     * created_by = authenticated merchant
     * user_id    = withdrawing customer
     */
    v_stage :=
        'create transaction state';

    insert into public.transaction_state (
        reference,
        transaction_type,
        transaction_data,
        sender_approval,
        status,
        created_by,
        user_id,
        country_code,
        created_at,
        updated_at
    )
    values (
        v_reference,
        'credit_agent_cash_withdrawal'::public."TransactionType",
        p_transaction,
        p_sender_approval,
        'processing'::public."TransactionStatus",
        v_merchant.id,
        v_user.id,
        v_merchant.country_code,
        now(),
        now()
    )
    returning id
    into v_transaction_state_id;

    return
        v_transaction_state_id::text;

exception
    when unique_violation then
        raise exception using
            errcode =
                '23505',

            message =
                'TRANSACTION_REPLAY';

    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;

        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'CREATE_CREDIT_AGENT_CASH_WITHDRAWAL_STATE_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                concat_ws(
                    E'\n',
                    nullif(
                        v_error_detail,
                        ''
                    ),
                    nullif(
                        v_error_context,
                        ''
                    )
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    format(
                        'Check the Credit Agent Cash Withdrawal State stage: %s',
                        v_stage
                    )
                );
end;
$$;
ALTER FUNCTION "public"."create_my_credit_agent_cash_withdrawal_state"("p_transaction" "jsonb", "p_sender_approval" "jsonb") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."create_my_gold_buy_state"("p_transaction" "jsonb", "p_blockchain_code" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_user public.users%rowtype;

    v_reference text;
    v_version text;
    v_input_currency text;
    v_blockchain_code text;
    v_transaction_id text;

    v_network record;
BEGIN
    /*
     * Authentication.
     */
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;

    IF p_transaction IS NULL THEN
        RAISE EXCEPTION
            'TRANSACTION_DATA_IS_MISSING';
    END IF;

    IF NOT public.has_role(
        ARRAY[
            'customer',
            'agent',
            'vendor'
        ]::text[]
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'FORBIDDEN';
    END IF;

    /*
     * Validate transaction version.
     */
    v_version :=
        nullif(
            btrim(p_transaction ->> 'v'),
            ''
        );

    IF v_version IS DISTINCT FROM 'v7' THEN
        RAISE EXCEPTION
            'OPERATION_NOT_ALLOWED';
    END IF;

    /*
     * Validate reference.
     */
    v_reference :=
        nullif(
            btrim(p_transaction ->> 'r'),
            ''
        );

    IF v_reference IS NULL THEN
        RAISE EXCEPTION
            'REFERENCE_IS_REQUIRED';
    END IF;

    /*
     * Validate transaction currency.
     */
    v_input_currency :=
        lower(
            nullif(
                btrim(p_transaction ->> 'c'),
                ''
            )
        );

    IF v_input_currency IS NULL THEN
        RAISE EXCEPTION
            'CURRENCY_IS_REQUIRED';
    END IF;

    IF v_input_currency NOT IN (
        'usd',
        'gold'
    ) THEN
        RAISE EXCEPTION
            'UNSUPPORTED_GOLD_BUY_CURRENCY';
    END IF;

    /*
     * Validate blockchain code.
     */
    v_blockchain_code :=
        lower(
            nullif(
                btrim(p_blockchain_code),
                ''
            )
        );

    IF v_blockchain_code IS NULL THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_CODE_REQUIRED';
    END IF;

    /*
     * Verify active blockchain configuration.
     */
    SELECT network.*
    INTO v_network
    FROM public.fetch_active_supported_blockchain(
        v_blockchain_code
    ) AS network;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_NOT_FOUND_OR_INACTIVE';
    END IF;

    /*
     * Fetch authenticated buyer.
     */
    SELECT user_record.*
    INTO v_user
    FROM public.users AS user_record
    WHERE user_record.id = auth.uid()::text
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'BUYER_NOT_FOUND';
    END IF;

    IF v_user.status <>
       'active'::public."UserStatus"
    THEN
        RAISE EXCEPTION
            'BUYER_NOT_ACTIVE';
    END IF;

    IF v_user.country_code IS NULL
       OR btrim(v_user.country_code) = ''
    THEN
        RAISE EXCEPTION
            'USER_COUNTRY_NOT_CONFIGURED';
    END IF;

    IF v_user.wallet_address IS NULL
       OR btrim(v_user.wallet_address) = ''
    THEN
        RAISE EXCEPTION
            'BUYER_WALLET_NOT_CONFIGURED';
    END IF;

    IF v_user.wallet_index IS NULL THEN
        RAISE EXCEPTION
            'BUYER_WALLET_INDEX_NOT_CONFIGURED';
    END IF;

    /*
     * Create processing state.
     *
     * Store the selected blockchain separately
     * from the original signed transaction.
     */
    BEGIN
        INSERT INTO public.transaction_state (
            reference,
            status,
            transaction_type,
            country_code,
            blockchain_code,
            transaction_data,
            created_by,
            user_id
        )
        VALUES (
            v_reference,
            'processing'::public."TransactionStatus",
            'gold_token_buy'::public."TransactionType",
            lower(btrim(v_user.country_code)),
            v_blockchain_code,
            p_transaction,
            v_user.id,
            v_user.id
        )
        RETURNING id::text
        INTO v_transaction_id;

    EXCEPTION
        WHEN unique_violation THEN
            RAISE EXCEPTION USING
                ERRCODE = '23505',
                MESSAGE = 'TRANSACTION_REPLAY';
    END;

    IF v_transaction_id IS NULL THEN
        RAISE EXCEPTION
            'TRANSACTION_STATE_CREATE_FAILED';
    END IF;

    RETURN v_transaction_id;
END;
$$;
ALTER FUNCTION "public"."create_my_gold_buy_state"("p_transaction" "jsonb", "p_blockchain_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."create_my_gold_sell_state"("p_transaction" "jsonb", "p_blockchain_code" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_seller public.users%rowtype;

    v_reference text;
    v_version text;
    v_input_currency text;
    v_blockchain_code text;
    v_transaction_id text;

    v_network record;
BEGIN
    /*
     * Authentication.
     */
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;

    IF p_transaction IS NULL THEN
        RAISE EXCEPTION
            'TRANSACTION_DATA_IS_MISSING';
    END IF;

    IF NOT public.has_role(
        ARRAY[
            'customer',
            'agent',
            'vendor'
        ]::text[]
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'FORBIDDEN';
    END IF;

    /*
     * Validate transaction version.
     */
    v_version :=
        nullif(
            btrim(p_transaction ->> 'v'),
            ''
        );

    IF v_version IS DISTINCT FROM 'v7' THEN
        RAISE EXCEPTION
            'OPERATION_NOT_ALLOWED';
    END IF;

    /*
     * Validate reference.
     */
    v_reference :=
        nullif(
            btrim(p_transaction ->> 'r'),
            ''
        );

    IF v_reference IS NULL THEN
        RAISE EXCEPTION
            'REFERENCE_IS_REQUIRED';
    END IF;

    /*
     * Validate transaction currency.
     */
    v_input_currency :=
        lower(
            nullif(
                btrim(p_transaction ->> 'c'),
                ''
            )
        );

    IF v_input_currency IS NULL THEN
        RAISE EXCEPTION
            'CURRENCY_IS_REQUIRED';
    END IF;

    IF v_input_currency NOT IN (
        'usd',
        'gold'
    ) THEN
        RAISE EXCEPTION
            'UNSUPPORTED_GOLD_SELL_CURRENCY';
    END IF;

    /*
     * Validate blockchain code.
     */
    v_blockchain_code :=
        lower(
            nullif(
                btrim(p_blockchain_code),
                ''
            )
        );

    IF v_blockchain_code IS NULL THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_CODE_REQUIRED';
    END IF;

    /*
     * Verify active blockchain configuration.
     */
    SELECT network.*
    INTO v_network
    FROM public.fetch_active_supported_blockchain(
        v_blockchain_code
    ) AS network;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_NOT_FOUND_OR_INACTIVE';
    END IF;

    /*
     * Fetch authenticated seller.
     */
    SELECT user_record.*
    INTO v_seller
    FROM public.users AS user_record
    WHERE user_record.id = auth.uid()::text
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'SELLER_NOT_FOUND';
    END IF;

    IF v_seller.status <>
       'active'::public."UserStatus"
    THEN
        RAISE EXCEPTION
            'SELLER_NOT_ACTIVE';
    END IF;

    IF v_seller.country_code IS NULL
       OR btrim(v_seller.country_code) = ''
    THEN
        RAISE EXCEPTION
            'USER_COUNTRY_NOT_CONFIGURED';
    END IF;

    IF v_seller.wallet_address IS NULL
       OR btrim(v_seller.wallet_address) = ''
    THEN
        RAISE EXCEPTION
            'SELLER_WALLET_NOT_CONFIGURED';
    END IF;

    IF v_seller.wallet_index IS NULL THEN
        RAISE EXCEPTION
            'SELLER_WALLET_INDEX_NOT_CONFIGURED';
    END IF;

    /*
     * Create processing state.
     *
     * Store the selected blockchain separately
     * from the original signed transaction.
     */
    BEGIN
        INSERT INTO public.transaction_state (
            reference,
            status,
            transaction_type,
            country_code,
            blockchain_code,
            transaction_data,
            created_by,
            user_id
        )
        VALUES (
            v_reference,
            'processing'::public."TransactionStatus",
            'gold_token_sell'::public."TransactionType",
            lower(btrim(v_seller.country_code)),
            v_blockchain_code,
            p_transaction,
            v_seller.id,
            v_seller.id
        )
        RETURNING id::text
        INTO v_transaction_id;

    EXCEPTION
        WHEN unique_violation THEN
            RAISE EXCEPTION USING
                ERRCODE = '23505',
                MESSAGE = 'TRANSACTION_REPLAY';
    END;

    IF v_transaction_id IS NULL THEN
        RAISE EXCEPTION
            'TRANSACTION_STATE_CREATE_FAILED';
    END IF;

    RETURN v_transaction_id;
END;
$$;
ALTER FUNCTION "public"."create_my_gold_sell_state"("p_transaction" "jsonb", "p_blockchain_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."create_my_gold_transfer_state"("p_transaction" "jsonb", "p_blockchain_code" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_sender public.users%rowtype;
    v_receiver public.users%rowtype;

    v_reference text;
    v_receiver_identifier text;
    v_currency text;
    v_version text;
    v_transaction_id text;
    v_blockchain_code text;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;

    IF p_transaction IS NULL THEN
        RAISE EXCEPTION
            'TRANSACTION_DATA_IS_MISSING';
    END IF;

    /*
     * Roles authorize the operation.
     * They do not determine wallet owner_type.
     */
    IF NOT public.has_role(
        ARRAY[
            'customer',
            'agent',
            'vendor'
        ]::text[]
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'FORBIDDEN';
    END IF;

    /*
     * Blockchain is supplied separately
     * from the signed transaction.
     */
    v_blockchain_code :=
        lower(
            nullif(
                btrim(p_blockchain_code),
                ''
            )
        );

    IF v_blockchain_code IS NULL THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_CODE_REQUIRED';
    END IF;

    /*
     * Validate the selected blockchain.
     *
     * Only the blockchain's active status
     * is required here.
     *
     * No environment, default network,
     * or network configuration checks.
     */
    IF NOT EXISTS (
        SELECT 1
        FROM public.supported_blockchain AS b
        WHERE b.code = v_blockchain_code
          AND b.is_active = true
    ) THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_NOT_FOUND_OR_INACTIVE';
    END IF;

    v_version :=
        nullif(
            btrim(p_transaction ->> 'v'),
            ''
        );

    IF v_version IS DISTINCT FROM 'v6' THEN
        RAISE EXCEPTION
            'OPERATION_NOT_ALLOWED';
    END IF;

    v_reference :=
        nullif(
            btrim(p_transaction ->> 'r'),
            ''
        );

    IF v_reference IS NULL THEN
        RAISE EXCEPTION
            'REFERENCE_IS_REQUIRED';
    END IF;

    v_receiver_identifier :=
        nullif(
            btrim(p_transaction ->> 's'),
            ''
        );

    IF v_receiver_identifier IS NULL THEN
        RAISE EXCEPTION
            'RECEIVER_IDENTIFIER_IS_REQUIRED';
    END IF;

    v_currency :=
        lower(
            nullif(
                btrim(p_transaction ->> 'c'),
                ''
            )
        );

    IF v_currency IS DISTINCT FROM 'gold' THEN
        RAISE EXCEPTION
            'INVALID_GOLD_TRANSFER_CURRENCY';
    END IF;

    /*
     * Fetch authenticated sender.
     */
    SELECT u.*
    INTO v_sender
    FROM public.users AS u
    WHERE u.id = auth.uid()::text
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'SENDER_NOT_FOUND';
    END IF;

    IF v_sender.status IS DISTINCT FROM
       'active'::public."UserStatus"
    THEN
        RAISE EXCEPTION
            'SENDER_NOT_ACTIVE';
    END IF;

    /*
     * Fetch receiver.
     */
    v_receiver :=
        public.fetch_user_by_email_or_phone(
            v_receiver_identifier
        );

    IF v_receiver.id IS NULL THEN
        RAISE EXCEPTION
            'RECEIVER_NOT_FOUND';
    END IF;

    IF v_receiver.status IS DISTINCT FROM
       'active'::public."UserStatus"
    THEN
        RAISE EXCEPTION
            'RECEIVER_NOT_ACTIVE';
    END IF;

    IF v_sender.id = v_receiver.id THEN
        RAISE EXCEPTION
            'OPERATION_NOT_ALLOWED';
    END IF;

    IF v_sender.country_code IS DISTINCT FROM
       v_receiver.country_code
    THEN
        RAISE EXCEPTION
            'OPERATION_NOT_ALLOWED';
    END IF;

    IF v_sender.wallet_address IS NULL
       OR btrim(v_sender.wallet_address) = ''
    THEN
        RAISE EXCEPTION
            'SENDER_WALLET_NOT_CONFIGURED';
    END IF;

    IF v_receiver.wallet_address IS NULL
       OR btrim(v_receiver.wallet_address) = ''
    THEN
        RAISE EXCEPTION
            'RECEIVER_WALLET_NOT_CONFIGURED';
    END IF;

    /*
     * GOLD TOKEN TRANSFER:
     *
     * Sender wallet owner_type = customer.
     * Receiver wallet owner_type = customer.
     *
     * This does not depend on user roles.
     *
     * The sender wallet must already exist.
     * The receiver wallet is created during
     * posting if it does not exist.
     */
    IF NOT EXISTS (
        SELECT 1
        FROM public.wallet AS w
        WHERE w.user_id = v_sender.id
          AND w.country_code =
              lower(btrim(v_sender.country_code))
          AND w.currency_code = 'gold'
          AND w.owner_type =
              'customer'::public."WalletOwnerType"
          AND w.blockchain_code =
              v_blockchain_code
    ) THEN
        RAISE EXCEPTION
            'SENDER_CUSTOMER_GOLD_WALLET_NOT_FOUND';
    END IF;

    /*
     * Store blockchain selection independently
     * of signed TransactionData.
     *
     * Reference uniqueness prevents replay.
     */
    BEGIN
        INSERT INTO public.transaction_state (
            reference,
            status,
            transaction_type,
            country_code,
            blockchain_code,
            transaction_data,
            created_by,
            user_id
        )
        VALUES (
            v_reference,
            'processing'::public."TransactionStatus",
            'gold_token_transfer'::public."TransactionType",
            lower(btrim(v_sender.country_code)),
            v_blockchain_code,
            p_transaction,
            v_sender.id,
            v_receiver.id
        )
        RETURNING id::text
        INTO v_transaction_id;

    EXCEPTION
        WHEN unique_violation THEN
            RAISE EXCEPTION USING
                ERRCODE = '23505',
                MESSAGE = 'TRANSACTION_REPLAY';
    END;

    IF v_transaction_id IS NULL THEN
        RAISE EXCEPTION
            'TRANSACTION_STATE_CREATE_FAILED';
    END IF;

    RETURN v_transaction_id;
END;
$$;
ALTER FUNCTION "public"."create_my_gold_transfer_state"("p_transaction" "jsonb", "p_blockchain_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."create_my_government_tax_settlement_batch"("p_currency_code" "text", "p_start_date" "date", "p_end_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_currency_code text;

    v_fiscal_year integer;
    v_period integer;

    v_document_prefix text;
    v_document_number text;

    v_batch_id
        public.government_tax_settlement_batch.id%type;

    v_total_gross numeric := 0;
    v_total_tax numeric := 0;

    v_payable_count integer := 0;
    v_assigned_count integer := 0;
    v_item_count integer := 0;

    v_existing_batch record;

    v_stage text :=
        'initialization';

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * Authentication and Accounts authorization.
     */
    v_stage :=
        'authorize accounts user';

    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'accounts'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Validate input.
     */
    v_stage :=
        'validate input';

    v_currency_code :=
        lower(
            nullif(
                btrim(p_currency_code),
                ''
            )
        );

    if v_currency_code is null then
        raise exception
            'CURRENCY_CODE_REQUIRED';
    end if;

    if v_currency_code = 'gold' then
        raise exception
            'INVALID_TAX_SETTLEMENT_CURRENCY';
    end if;

    if p_start_date is null then
        raise exception
            'START_DATE_REQUIRED';
    end if;

    if p_end_date is null then
        raise exception
            'END_DATE_REQUIRED';
    end if;

    /*
     * A same-day settlement is valid.
     */
    if p_start_date > p_end_date then
        raise exception
            'INVALID_SETTLEMENT_DATE_RANGE';
    end if;

    /*
     * Fetch trusted Accounts user.
     */
    v_stage :=
        'fetch accounts user';

    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'ACCOUNTS_USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'ACCOUNTS_USER_NOT_ACTIVE';
    end if;

    if nullif(
        btrim(v_user.country_code),
        ''
    ) is null
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Validate the country currency.
     *
     * Both the country configuration and the system
     * supported-currency configuration must be active.
     */
    v_stage :=
        'validate settlement currency';

    perform 1
    from public.country_currencies
        country_currency_record
    join public.supported_currency
        supported_currency_record
      on lower(
          btrim(
              supported_currency_record.currency_code
          )
      ) =
         lower(
             btrim(
                 country_currency_record.currency_code
             )
         )
    where lower(
        btrim(
            country_currency_record.country_code
        )
    ) =
        lower(
            btrim(
                v_user.country_code
            )
        )

      and lower(
          btrim(
              country_currency_record.currency_code
          )
      ) =
          v_currency_code

      and country_currency_record.is_active =
          true

      and supported_currency_record.is_active =
          true

      and supported_currency_record.currency_category =
          'fiat'::public."CurrencyCategory"
    limit 1;

    if not found then
        raise exception
            'SETTLEMENT_CURRENCY_NOT_ACTIVE';
    end if;

    /*
     * Serialize tax-batch creation by country and
     * currency.
     *
     * This prevents two requests from both passing the
     * active-batch check before either inserts a batch.
     */
    v_stage :=
        'lock tax settlement currency';

    perform pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            format(
                'government-tax-settlement:%s:%s',
                lower(
                    btrim(
                        v_user.country_code
                    )
                ),
                v_currency_code
            ),
            0
        )
    );

    /*
     * Do not create another batch while an earlier batch
     * for the currency is still actionable or processing.
     *
     * Failed and partial batches must be retried instead
     * of creating a new batch.
     */
    v_stage :=
        'check payment underway';

    select
        batch_record.id,
        batch_record.document_number,
        batch_record.status
    into v_existing_batch
    from public.government_tax_settlement_batch
        batch_record
    where lower(
        btrim(
            batch_record.country_code
        )
    ) =
        lower(
            btrim(
                v_user.country_code
            )
        )

      and lower(
          btrim(
              batch_record.currency_code
          )
      ) =
          v_currency_code

      and batch_record.status::text in (
          'draft',
          'pending',
          'approved',
          'partial',
          'failed',
          'processing'
      )
    order by
        batch_record.created_at desc,
        batch_record.id desc
    limit 1
    for update;

    if found then
        raise exception
            'GOVERNMENT_TAX_SETTLEMENT_PAYMENT_UNDERWAY_%_%',
            upper(
                v_existing_batch.status::text
            ),
            v_existing_batch.document_number;
    end if;

    /*
     * Fetch the current fiscal period.
     */
    v_stage :=
        'fetch fiscal period';

    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_user.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Lock every eligible Government Tax payable row.
     *
     * The end date is inclusive, therefore selection
     * continues until the start of the following day.
     *
     * settlement_batch_id must be null so a payable
     * cannot belong to multiple batches.
     */
    v_stage :=
        'lock unsettled government tax';

    perform 1
    from public.government_tax_payable
        tax_record
    where lower(
        btrim(
            tax_record.country_code
        )
    ) =
        lower(
            btrim(
                v_user.country_code
            )
        )

      and lower(
          btrim(
              tax_record.currency_code
          )
      ) =
          v_currency_code

      and tax_record.is_settled =
          false

      and tax_record.settlement_batch_id
          is null

      and tax_record.created_at >=
          p_start_date::timestamptz

      and tax_record.created_at <
          (
              p_end_date +
              1
          )::timestamptz
    for update;

    /*
     * Aggregate the locked payable rows.
     */
    v_stage :=
        'aggregate government tax';

    select
        count(*)::integer,

        coalesce(
            sum(
                tax_record.gross_amount
            ),
            0
        ),

        coalesce(
            sum(
                tax_record.tax_amount
            ),
            0
        )
    into
        v_payable_count,
        v_total_gross,
        v_total_tax
    from public.government_tax_payable
        tax_record
    where lower(
        btrim(
            tax_record.country_code
        )
    ) =
        lower(
            btrim(
                v_user.country_code
            )
        )

      and lower(
          btrim(
              tax_record.currency_code
          )
      ) =
          v_currency_code

      and tax_record.is_settled =
          false

      and tax_record.settlement_batch_id
          is null

      and tax_record.created_at >=
          p_start_date::timestamptz

      and tax_record.created_at <
          (
              p_end_date +
              1
          )::timestamptz;

    if v_payable_count = 0 then
        raise exception
            'GOVERNMENT_TAX_PAYABLE_NOT_FOUND_FOR_SELECTED_DATE_RANGE';
    end if;

    if v_total_tax <= 0 then
        raise exception
            'INVALID_GOVERNMENT_TAX_SETTLEMENT_TOTAL';
    end if;

    /*
     * Fetch the configured document prefix.
     */
    v_stage :=
        'fetch document prefix';

    v_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            'government_tax_clearing'::public."TransactionType"
        );

    if nullif(
        btrim(v_document_prefix),
        ''
    ) is null
    then
        raise exception
            'DOCUMENT_PREFIX_NOT_FOUND';
    end if;

    /*
     * Generate the settlement batch document number.
     */
    v_stage :=
        'generate document number';

    v_document_number :=
        public.generate_document_number(
            v_document_prefix,
            v_fiscal_year,
            v_period,
            v_user.country_code
        );

    /*
     * Create the draft batch.
     *
     * total_amount is the tax amount payable to the
     * Government, not the underlying transaction volume.
     */
    v_stage :=
        'create tax settlement batch';

    insert into public.government_tax_settlement_batch (
        document_number,
        fiscal_year,
        period,
        currency_code,
        country_code,
        start_date,
        end_date,
        total_amount,
        status,
        created_by
    )
    values (
        v_document_number,
        v_fiscal_year,
        v_period,
        v_currency_code,
        v_user.country_code,
        p_start_date,
        p_end_date,
        v_total_tax,
        'draft',
        v_user.id
    )
    returning id
    into v_batch_id;

    if v_batch_id is null then
        raise exception
            'GOVERNMENT_TAX_SETTLEMENT_BATCH_CREATE_FAILED';
    end if;

    /*
     * Create one item per transaction type.
     */
    v_stage :=
        'create tax settlement items';

    insert into public.government_tax_settlement_item (
        batch_id,
        transaction_type,
        fiscal_year,
        period,
        currency_code,
        country_code,
        gross_amount,
        tax_amount,
        status
    )
    select
        v_batch_id,
        tax_record.transaction_type,
        v_fiscal_year,
        v_period,
        v_currency_code,
        v_user.country_code,

        coalesce(
            sum(
                tax_record.gross_amount
            ),
            0
        ),

        coalesce(
            sum(
                tax_record.tax_amount
            ),
            0
        ),

        'draft'
    from public.government_tax_payable
        tax_record
    where lower(
        btrim(
            tax_record.country_code
        )
    ) =
        lower(
            btrim(
                v_user.country_code
            )
        )

      and lower(
          btrim(
              tax_record.currency_code
          )
      ) =
          v_currency_code

      and tax_record.is_settled =
          false

      and tax_record.settlement_batch_id
          is null

      and tax_record.created_at >=
          p_start_date::timestamptz

      and tax_record.created_at <
          (
              p_end_date +
              1
          )::timestamptz

    group by
        tax_record.transaction_type;

    get diagnostics
        v_item_count =
            row_count;

    if v_item_count = 0 then
        raise exception
            'GOVERNMENT_TAX_SETTLEMENT_ITEMS_CREATE_FAILED';
    end if;

    /*
     * Assign every selected payable row to the batch.
     */
    v_stage :=
        'assign government tax payables';

    update public.government_tax_payable
    set
        settlement_batch_id =
            v_batch_id
    where lower(
        btrim(
            country_code
        )
    ) =
        lower(
            btrim(
                v_user.country_code
            )
        )

      and lower(
          btrim(
              currency_code
          )
      ) =
          v_currency_code

      and is_settled =
          false

      and settlement_batch_id
          is null

      and created_at >=
          p_start_date::timestamptz

      and created_at <
          (
              p_end_date +
              1
          )::timestamptz;

    get diagnostics
        v_assigned_count =
            row_count;

    if v_assigned_count <>
       v_payable_count
    then
        raise exception
            'GOVERNMENT_TAX_PAYABLE_ASSIGNMENT_COUNT_MISMATCH_EXPECTED_%_ASSIGNED_%',
            v_payable_count,
            v_assigned_count;
    end if;

    return jsonb_build_object(
        'success',
        true,

        'batch_id',
        v_batch_id,

        'document_number',
        v_document_number,

        'currency_code',
        v_currency_code,

        'start_date',
        p_start_date,

        'end_date',
        p_end_date,

        'status',
        'draft',

        /*
         * Underlying transaction volume.
         */
        'totalAmount',
        trim_scale(
            v_total_gross
        )::text,

        /*
         * Amount payable to Government.
         */
        'totalTax',
        trim_scale(
            v_total_tax
        )::text,

        'payable_count',
        v_payable_count,

        'item_count',
        v_item_count
    );

exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;

        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'GOVERNMENT_TAX_SETTLEMENT_BATCH_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                concat_ws(
                    E'\n',
                    nullif(
                        v_error_detail,
                        ''
                    ),
                    nullif(
                        v_error_context,
                        ''
                    )
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    'Check the Government Tax Settlement Batch stage'
                );
end;
$$;
ALTER FUNCTION "public"."create_my_government_tax_settlement_batch"("p_currency_code" "text", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."create_my_merchant_payment_state"("p_transaction" "jsonb", "p_approval" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_payer public.users%rowtype;
    v_merchant public.users%rowtype;

    v_reference text;
    v_merchant_id text;
    v_currency text;
    v_version text;

    v_transaction_id text;
begin
    /*
     * Authenticate the payer.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if p_transaction is null then
        raise exception
            'TRANSACTION_DATA_MISSING';
    end if;

    if p_approval is null then
        raise exception
            'SENDER_APPROVAL_MISSING';
    end if;

    /*
     * Users allowed to make merchant payments.
     */
    if not public.has_role(
        array[
            'customer',
            'vendor',
            'agent'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Read the signed transaction fields.
     */
    v_version :=
        nullif(
            btrim(
                p_transaction ->> 'v'
            ),
            ''
        );

    if v_version is distinct from 'v4' then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    v_reference :=
        nullif(
            btrim(
                p_transaction ->> 'r'
            ),
            ''
        );

    if v_reference is null then
        raise exception
            'REFERENCE_IS_REQUIRED';
    end if;

    /*
     * transaction.s contains the receiving merchant or
     * vendor user ID.
     */
    v_merchant_id :=
        nullif(
            btrim(
                p_transaction ->> 's'
            ),
            ''
        );

    if v_merchant_id is null then
        raise exception
            'MERCHANT_ID_IS_REQUIRED';
    end if;

    v_currency :=
        lower(
            nullif(
                btrim(
                    p_transaction ->> 'c'
                ),
                ''
            )
        );

    if v_currency is null then
        raise exception
            'CURRENCY_IS_REQUIRED';
    end if;

    /*
     * The transaction and approval must describe the same
     * payment.
     */
    if p_transaction ->> 'a'
       is distinct from
       p_approval ->> 'a'
    then
        raise exception
            'AMOUNT_MISMATCH';
    end if;

    if lower(
        p_transaction ->> 'c'
    ) is distinct from lower(
        p_approval ->> 'c'
    ) then
        raise exception
            'CURRENCY_MISMATCH';
    end if;

    if p_transaction ->> 'r'
       is distinct from
       p_approval ->> 'r'
    then
        raise exception
            'REFERENCE_MISMATCH';
    end if;

    /*
     * Fetch the authenticated payer.
     */
    select payer_record.*
    into v_payer
    from public.users payer_record
    where payer_record.id =
          auth.uid()::text
    limit 1;

    if not found then
        raise exception
            'PAYER_NOT_FOUND';
    end if;

    /*
     * Fetch the payment receiver.
     */
    select merchant_record.*
    into v_merchant
    from public.users merchant_record
    where merchant_record.id =
          v_merchant_id
    limit 1;

    if not found then
        raise exception
            'MERCHANT_NOT_FOUND';
    end if;

    /*
     * Validate participant status.
     */
    if v_payer.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'PAYER_NOT_ACTIVE';
    end if;

    if v_merchant.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'MERCHANT_NOT_ACTIVE';
    end if;

    /*
     * Prevent payment to the same user.
     */
    if v_payer.id =
       v_merchant.id
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    /*
     * Both participants must belong to the same country.
     */
    if lower(
        btrim(
            v_payer.country_code
        )
    ) is distinct from lower(
        btrim(
            v_merchant.country_code
        )
    ) then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    /*
     * Both merchants and vendors may receive merchant
     * payments.
     */
    if not exists (
        select 1
        from public.user_role role_record
        where role_record.id =
              v_merchant.role_id

          and lower(
              role_record.name::text
          ) in (
              'merchant',
              'vendor'
          )
    ) then
        raise exception
            'INVALID_MERCHANT_ROLE';
    end if;

    /*
     * Create the processing transaction state.
     */
    begin
        insert into public.transaction_state (
            reference,
            status,
            transaction_type,
            country_code,
            transaction_data,
            sender_approval,
            created_by,
            user_id
        )
        values (
            v_reference,
            'processing'::public."TransactionStatus",
            'merchant_payment'::public."TransactionType",

            lower(
                btrim(
                    v_payer.country_code
                )
            ),

            p_transaction,
            p_approval,
            v_payer.id,
            v_merchant.id
        )
        returning id::text
        into v_transaction_id;

    exception
        when unique_violation then
            raise exception using
                errcode = '23505',
                message = 'TRANSACTION_REPLAY';
    end;

    if v_transaction_id is null then
        raise exception
            'TRANSACTION_STATE_CREATE_FAILED';
    end if;

    return v_transaction_id;
end;
$$;
ALTER FUNCTION "public"."create_my_merchant_payment_state"("p_transaction" "jsonb", "p_approval" "jsonb") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."create_my_merchant_payment_state"("p_transaction" "jsonb", "p_approval" "jsonb", "p_payment_fee_contribution" boolean) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_transaction_id text;
begin
    if p_payment_fee_contribution is null then
        raise exception 'PAYMENT_FEE_CONTRIBUTION_REQUIRED';
    end if;

    /*
     * The existing function performs authentication, role, participant,
     * signature-payload and replay validation before inserting the state.
     */
    v_transaction_id :=
        public.create_my_merchant_payment_state(
            p_transaction,
            p_approval
        );

    update public.transaction_state state_record
    set
        payment_fee_contribution = p_payment_fee_contribution,
        updated_at = now()
    where state_record.id::text = v_transaction_id
      and state_record.created_by = auth.uid()::text
      and state_record.transaction_type =
          'merchant_payment'::public."TransactionType"
      and state_record.status =
          'processing'::public."TransactionStatus";

    if not found then
        raise exception 'TRANSACTION_STATE_CONTRIBUTION_UPDATE_FAILED';
    end if;

    return v_transaction_id;
end;
$$;
ALTER FUNCTION "public"."create_my_merchant_payment_state"("p_transaction" "jsonb", "p_approval" "jsonb", "p_payment_fee_contribution" boolean) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."create_my_transaction_state"("p_transaction" "jsonb", "p_transaction_type" "public"."TransactionType") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user_id text;
    v_country_code text;
    v_transaction_id text;
    v_transaction_data jsonb;
begin
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    select
        u.id,
        u.country_code
    into
        v_user_id,
        v_country_code
    from public.users u
    where u.id = auth.uid()::text
      and u.status =
          'active'::public."UserStatus"
    limit 1;

    if not found then
        raise exception using
            errcode = '42501',
            message = 'USER_NOT_ACTIVE_OR_NOT_FOUND';
    end if;

    if v_country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    if p_transaction is null then
        raise exception
            'TRANSACTION_DATA_IS_MISSING';
    end if;

    if nullif(
        trim(p_transaction ->> 'r'),
        ''
    ) is null then
        raise exception
            'TRANSACTION_REFERENCE_REQUIRED';
    end if;

    v_transaction_id :=
        gen_random_uuid()::text;

    /*
     * Preserve the same fields stored by the TypeScript service.
     */
    v_transaction_data :=
        jsonb_build_object(
            'v', p_transaction -> 'v',
            'r', p_transaction -> 'r',
            's', p_transaction -> 's',
            'a', p_transaction -> 'a',
            'f', p_transaction -> 'f',
            'g', p_transaction -> 'g',
            'c', p_transaction -> 'c',
            't', p_transaction -> 't',
            'e', p_transaction -> 'e',
            'ms', p_transaction -> 'ms'
        );

    insert into public.transaction_state (
        id,
        reference,
        status,
        transaction_type,
        country_code,
        transaction_data,
        created_by,
        user_id,
        updated_at
    )
    values (
        v_transaction_id,
        p_transaction ->> 'r',
        'processing'::public."TransactionStatus",
        p_transaction_type,
        v_country_code,
        v_transaction_data,
        v_user_id,
        p_transaction ->> 's',
        now()
    );

    return v_transaction_id;

exception
    when unique_violation then
        raise exception using
            errcode = '23505',
            message = 'TRANSACTION_REPLAY';
end;
$$;
ALTER FUNCTION "public"."create_my_transaction_state"("p_transaction" "jsonb", "p_transaction_type" "public"."TransactionType") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."create_my_voucher_payment_state"("p_transaction" "jsonb", "p_voucher" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_transaction_reference text;
    v_transaction_currency text;
    v_transaction_voucher_reference text;

    v_voucher_reference text;
    v_voucher_currency text;
    v_voucher_owner_id text;

    v_transaction_amount numeric;
    v_voucher_amount numeric;

    v_transaction_state_id text;
begin
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'merchant',
            'vendor'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    if p_transaction is null then
        raise exception
            'TRANSACTION_DATA_MISSING';
    end if;

    if p_voucher is null then
        raise exception
            'VOUCHER_DATA_MISSING';
    end if;

    if p_transaction ->> 'v' is distinct from
       'v0'
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    if p_voucher ->> 'v' is distinct from
       'v0'
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    select user_record.*
    into v_user
    from public.users user_record
    where user_record.id =
          auth.uid()::text
    limit 1;

    if not found then
        raise exception
            'MERCHANT_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'MERCHANT_NOT_ACTIVE';
    end if;

    v_transaction_reference :=
        nullif(
            btrim(p_transaction ->> 'r'),
            ''
        );

    if v_transaction_reference is null then
        raise exception
            'REFERENCE_MISSING';
    end if;

    v_transaction_currency :=
        lower(
            nullif(
                btrim(p_transaction ->> 'c'),
                ''
            )
        );

    if v_transaction_currency is null then
        raise exception
            'CURRENCY_MISSING';
    end if;

    v_transaction_voucher_reference :=
        nullif(
            btrim(p_transaction ->> 's'),
            ''
        );

    if v_transaction_voucher_reference is null then
        raise exception
            'VOUCHER_REFERENCE_MISSING';
    end if;

    v_voucher_reference :=
        nullif(
            btrim(p_voucher ->> 'r'),
            ''
        );

    if v_voucher_reference is null then
        raise exception
            'VOUCHER_REFERENCE_MISSING';
    end if;

    v_voucher_currency :=
        lower(
            nullif(
                btrim(p_voucher ->> 'c'),
                ''
            )
        );

    if v_voucher_currency is null then
        raise exception
            'VOUCHER_CURRENCY_MISSING';
    end if;

    v_voucher_owner_id :=
        nullif(
            btrim(p_voucher ->> 's'),
            ''
        );

    if v_voucher_owner_id is null then
        raise exception
            'VOUCHER_OWNER_ID_MISSING';
    end if;

    if v_transaction_currency is distinct from
       v_voucher_currency
    then
        raise exception
            'CURRENCY_MISMATCH';
    end if;

    /*
     * The merchant transaction points to the voucher reference
     * through transaction.s.
     */
    if v_transaction_voucher_reference is distinct from
       v_voucher_reference
    then
        raise exception
            'REFERENCE_MISMATCH';
    end if;

    begin
        v_transaction_amount :=
            (p_transaction ->> 'a')::numeric /
            100;
    exception
        when invalid_text_representation
          or numeric_value_out_of_range
        then
            raise exception
                'INVALID_AMOUNT';
    end;

    begin
        v_voucher_amount :=
            (p_voucher ->> 'a')::numeric /
            100;
    exception
        when invalid_text_representation
          or numeric_value_out_of_range
        then
            raise exception
                'INVALID_VOUCHER_AMOUNT';
    end;

    if v_transaction_amount <= 0 then
        raise exception
            'INVALID_AMOUNT';
    end if;

    if v_voucher_amount <= 0 then
        raise exception
            'INVALID_VOUCHER_AMOUNT';
    end if;

    if v_transaction_amount >
       v_voucher_amount
    then
        raise exception
            'VOUCHER_BALANCE_NOT_ENOUGH';
    end if;

    begin
        insert into public.transaction_state (
            reference,
            status,
            transaction_type,
            country_code,
            transaction_data,
            sender_approval,
            created_by,
            user_id
        )
        values (
            v_transaction_reference,
            'processing'::public."TransactionStatus",
            'merchant_payment'::public."TransactionType",
            v_user.country_code,
            p_transaction,
            p_voucher,
            v_user.id,
            v_voucher_owner_id
        )
        returning id::text
        into v_transaction_state_id;

    exception
        when unique_violation then
            raise exception using
                errcode = '23505',
                message = 'TRANSACTION_REPLAY';
    end;

    return v_transaction_state_id;
end;
$$;
ALTER FUNCTION "public"."create_my_voucher_payment_state"("p_transaction" "jsonb", "p_voucher" "jsonb") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."create_notification_message"("p_country_code" "text", "p_transaction_type" "public"."TransactionType", "p_audience" "public"."NotificationAudience", "p_amount" numeric, "p_currency" "text", "p_reference" "text", "p_quantity" numeric DEFAULT 0, "p_sender" "text" DEFAULT NULL::"text", "p_receiver" "text" DEFAULT NULL::"text") RETURNS "public"."notification_message"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_template
        public.notification_template%rowtype;

    v_payload jsonb;

    v_formatted_amount numeric;
    v_formatted_quantity numeric;
begin
    /*
     * Fetch the notification template.
     */
    select template_record.*
    into v_template
    from public.notification_template
        template_record
    where template_record.country_code =
          p_country_code
      and template_record.language_code =
          'en'
      and template_record.transaction_type =
          p_transaction_type
      and template_record.audience =
          p_audience
    limit 1;

    if not found then
        raise exception
            'NOTIFICATION_TEMPLATE_NOT_FOUND_%',
            upper(
                p_transaction_type::text
            );
    end if;

    /*
     * Currency amount formatting:
     *
     * - Gold: 6 decimal places
     * - Fiat: 2 decimal places
     */
    if lower(
        btrim(
            coalesce(
                p_currency,
                ''
            )
        )
    ) = 'gold'
    then
        v_formatted_amount :=
            round(
                coalesce(
                    p_amount,
                    0
                ),
                6
            );
    else
        v_formatted_amount :=
            round(
                coalesce(
                    p_amount,
                    0
                ),
                2
            );
    end if;

    /*
     * Quantity represents Gold grams in Gold transactions,
     * so it always uses 6 decimal places.
     */
    v_formatted_quantity :=
        round(
            coalesce(
                p_quantity,
                0
            ),
            6
        );

    /*
     * Build the consistently formatted notification payload.
     */
    v_payload :=
        jsonb_build_object(
            'quantity',
            v_formatted_quantity,

            'amount',
            v_formatted_amount,

            'currency',
            p_currency,

            'reference',
            p_reference
        );

    if p_sender is not null then
        v_payload :=
            v_payload ||
            jsonb_build_object(
                'sender',
                p_sender
            );
    end if;

    if p_receiver is not null then
        v_payload :=
            v_payload ||
            jsonb_build_object(
                'receiver',
                p_receiver
            );
    end if;

    return row(
        v_template.notification_type,

        public.render_notification_template(
            v_template.title_template,
            v_payload
        ),

        public.render_notification_template(
            v_template.body_template,
            v_payload
        ),

        v_payload
    )::public.notification_message;
end;
$$;
ALTER FUNCTION "public"."create_notification_message"("p_country_code" "text", "p_transaction_type" "public"."TransactionType", "p_audience" "public"."NotificationAudience", "p_amount" numeric, "p_currency" "text", "p_reference" "text", "p_quantity" numeric, "p_sender" "text", "p_receiver" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."credit_agent_cash_deposit"("p_user_id" "text", "p_transaction" "jsonb", "p_transaction_type" "public"."TransactionType", "p_country_code" "text", "p_transaction_state_id" "text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "reference" "text", "customer_id" "text", "gross_amount" "text", "gross_amount_usd" "text", "financial_transaction_id" "text", "receiver_notification_id" "text", "device_tokens" "text"[], "push_title" "text", "push_body" "text", "push_reference" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_posting record;
    v_currency_code text;
    v_amount numeric;
    v_amount_usd numeric(20, 6);
    v_rate_to_usd numeric;
    v_financial_transaction_id bigint;
begin
    /*
     * The internal function performs all validation, locking,
     * accounting, wallet posting, credit-agent posting and the
     * transaction-state update in this same database transaction.
     */
    select posting_result.*
    into v_posting
    from public.credit_agent_cash_deposit_posting(
        p_user_id,
        p_transaction,
        p_transaction_type,
        p_country_code,
        p_transaction_state_id,
        p_ip_address
    ) as posting_result;

    if not found or not coalesce(v_posting.success, false) then
        raise exception
            'CREDIT_AGENT_CASH_DEPOSIT_POSTING_RESULT_NOT_FOUND';
    end if;

    v_currency_code :=
        lower(
            nullif(
                btrim(p_transaction ->> 'c'),
                ''
            )
        );

    if v_currency_code is null then
        raise exception 'CURRENCY_REQUIRED';
    end if;

    v_amount :=
        nullif(v_posting.gross_amount::text, '')::numeric;

    if v_amount is null or v_amount <= 0 then
        raise exception 'INVALID_AMOUNT';
    end if;

    /*
     * Use the same Ngoda rate convention as the other loyalty-enabled
     * transactions: USD is already USD, gold multiplies by its USD
     * price, and other fiat divides by currency units per USD.
     */
    if v_currency_code = 'usd' then
        v_amount_usd := round(v_amount, 6);
    else
        select rate_record.rate_to_usd
        into v_rate_to_usd
        from public.current_rates rate_record
        where lower(btrim(rate_record.code)) =
              v_currency_code
        limit 1;

        if not found
           or v_rate_to_usd is null
           or v_rate_to_usd <= 0
        then
            raise exception
                'CURRENT_RATE_NOT_FOUND_%',
                upper(v_currency_code);
        end if;

        if v_currency_code = 'gold' then
            v_amount_usd :=
                round(v_amount * v_rate_to_usd, 6);
        else
            v_amount_usd :=
                round(v_amount / v_rate_to_usd, 6);
        end if;
    end if;

    if v_amount_usd <= 0 then
        raise exception
            'INVALID_CREDIT_AGENT_CASH_DEPOSIT_USD_AMOUNT';
    end if;

    /*
     * The posting function has just created this unique transaction.
     * Resolve its authoritative ID before returning to the Edge
     * Function so loyalty can link to the financial transaction.
     */
    select transaction_record.id
    into v_financial_transaction_id
    from public.financial_transaction transaction_record
    where transaction_record.reference =
          v_posting.reference
      and transaction_record.transaction_type =
          p_transaction_type
      and transaction_record.country_code =
          p_country_code
    order by transaction_record.id desc
    limit 1;

    if not found then
        raise exception
            'FINANCIAL_TRANSACTION_NOT_FOUND';
    end if;

    return query
    select
        v_posting.success::boolean,
        v_posting.reference::text,
        v_posting.customer_id::text,
        v_posting.gross_amount::text,
        v_amount_usd::text,
        v_financial_transaction_id::text,
        v_posting.receiver_notification_id::text,
        v_posting.device_tokens::text[],
        v_posting.push_title::text,
        v_posting.push_body::text,
        v_posting.push_reference::text;
end;
$$;
ALTER FUNCTION "public"."credit_agent_cash_deposit"("p_user_id" "text", "p_transaction" "jsonb", "p_transaction_type" "public"."TransactionType", "p_country_code" "text", "p_transaction_state_id" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."credit_agent_cash_deposit_posting"("p_user_id" "text", "p_transaction" "jsonb", "p_transaction_type" "public"."TransactionType", "p_country_code" "text", "p_transaction_state_id" "text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "reference" "text", "customer_id" "text", "gross_amount" "text", "receiver_notification_id" "text", "device_tokens" "text"[], "push_title" "text", "push_body" "text", "push_reference" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
    v_stage text := 'initialization';

    v_customer public.users%rowtype;
    v_provider public.users%rowtype;
    v_transaction_state public.transaction_state%rowtype;
    v_credit_account public.credit_agent_account%rowtype;

    v_transaction_version text;
    v_reference text;
    v_provider_id text;
    v_currency_code text;

    v_amount_minor numeric;
    v_amount numeric;

    v_fiscal_year integer;
    v_period integer;

    v_mappings public.transaction_gl_mapping[];
    v_components public.posting_component[];

    v_wallet_owners
        public.transaction_type_wallet_owner%rowtype;

    v_document_prefix text;
    v_document_number text;

    v_financial_transaction_id
        public.financial_transaction.id%type;

    v_notification public.notification_message;
    v_notification_json jsonb;

    v_device_tokens text[];

    v_wallet_entry_count integer;
    v_receiver_notification_id text;

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * This function is called only by the Edge Function
     * through the service-role Supabase client.
     */
    if coalesce(auth.role(), '') <> 'service_role' then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    if p_transaction_type <>
       'credit_agent_cash_deposit'::public."TransactionType"
    then
        raise exception
            'INVALID_CREDIT_AGENT_CASH_DEPOSIT_TRANSACTION_TYPE';
    end if;

    if p_transaction is null then
        raise exception
            'TRANSACTION_DATA_MISSING';
    end if;

    if nullif(btrim(p_transaction_state_id), '') is null then
        raise exception
            'TRANSACTION_STATE_ID_REQUIRED';
    end if;

    /*
     * Read signed transaction fields.
     *
     * a = amount in minor currency units
     * c = currency
     * r = reference
     * s = provider/merchant ID
     * v = transaction version
     */
    v_stage := 'read transaction fields';

    v_transaction_version :=
        nullif(
            btrim(p_transaction ->> 'v'),
            ''
        );

    v_reference :=
        nullif(
            btrim(p_transaction ->> 'r'),
            ''
        );

    v_provider_id :=
        nullif(
            btrim(p_transaction ->> 's'),
            ''
        );

    v_currency_code :=
        lower(
            nullif(
                btrim(p_transaction ->> 'c'),
                ''
            )
        );

    if v_transaction_version <> 'v1' then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    if v_reference is null then
        raise exception
            'REFERENCE_REQUIRED';
    end if;

    if v_provider_id is null then
        raise exception
            'PROVIDER_NOT_FOUND';
    end if;

    if v_currency_code is null then
        raise exception
            'CURRENCY_REQUIRED';
    end if;

    if coalesce(p_transaction ->> 'a', '') !~ '^[0-9]+$' then
        raise exception
            'INVALID_AMOUNT';
    end if;

    v_amount_minor :=
        (p_transaction ->> 'a')::numeric;

    /*
     * Signed fiat amounts are represented in minor units.
     */
    v_amount :=
        round(
            v_amount_minor / 100,
            2
        );

    if v_amount <= 0 then
        raise exception
            'INVALID_AMOUNT';
    end if;

    /*
     * Lock and validate the processing transaction state.
     */
    v_stage := 'validate transaction state';

    select transaction_state_record.*
    into v_transaction_state
    from public.transaction_state transaction_state_record
    where transaction_state_record.id::text =
          p_transaction_state_id
    for update;

    if not found then
        raise exception
            'TRANSACTION_STATE_NOT_FOUND';
    end if;

    if v_transaction_state.status <>
       'processing'::public."TransactionStatus"
    then
        raise exception
            'TRANSACTION_NOT_PROCESSING';
    end if;

    if v_transaction_state.transaction_type <>
       p_transaction_type
    then
        raise exception
            'TRANSACTION_TYPE_MISMATCH';
    end if;

    if v_transaction_state.reference <>
       v_reference
    then
        raise exception
            'REFERENCE_MISMATCH';
    end if;

    if v_transaction_state.created_by <>
       p_user_id
    then
        raise exception
            'CUSTOMER_MISMATCH';
    end if;

    if v_transaction_state.user_id <>
       v_provider_id
    then
        raise exception
            'PROVIDER_MISMATCH';
    end if;

    /*
     * Fetch the customer.
     */
    v_stage := 'fetch customer';

    select user_record.*
    into v_customer
    from public.users user_record
    where user_record.id = p_user_id
      and user_record.status =
          'active'::public."UserStatus"
    limit 1;

    if not found then
        raise exception
            'CUSTOMER_NOT_FOUND';
    end if;

    if lower(v_customer.country_code) <>
       lower(p_country_code)
    then
        raise exception
            'CUSTOMER_COUNTRY_MISMATCH';
    end if;

    /*
     * Fetch and validate the merchant.
     */
    v_stage := 'fetch credit merchant';

    select merchant_record.*
    into v_provider
    from public.users merchant_record
    join public.user_role role_record
      on role_record.id =
         merchant_record.role_id
    where merchant_record.id =
          v_provider_id

      and merchant_record.status =
          'active'::public."UserStatus"

      and lower(
          merchant_record.country_code
      ) =
          lower(p_country_code)

      and lower(
          role_record.name::text
      ) =
          'merchant'
    limit 1;

    if not found then
        raise exception
            'CREDIT_AGENT_NOT_FOUND';
    end if;

    /*
     * Lock the currency balance belonging to this
     * credit merchant.
     */
    v_stage := 'lock credit agent account';

    select account_record.*
    into v_credit_account
    from public.credit_agent_account account_record
    where account_record.merchant_id =
          v_provider.id

      and lower(
          account_record.country_code
      ) =
          lower(p_country_code)

      and lower(
          account_record.currency_code
      ) =
          v_currency_code

      and account_record.is_active =
          true
    for update;

    if not found then
        raise exception
            'CREDIT_AGENT_ACCOUNT_NOT_ACTIVE';
    end if;

    /*
     * Prevent a verified reference from being posted
     * more than once.
     */
    v_stage := 'check posting replay';

    perform 1
    from public.financial_transaction
        financial_transaction_record
    where financial_transaction_record.reference =
          v_reference

      and financial_transaction_record.country_code =
          p_country_code

      and financial_transaction_record.transaction_type =
          p_transaction_type
    limit 1;

    if found then
        raise exception
            'TRANSACTION_REPLAY';
    end if;

    /*
     * Load accounting configuration.
     */
    v_stage := 'fetch gl mappings';

    select array_agg(mapping_record)
    into v_mappings
    from public.fetch_gl_mappings(
        p_transaction_type
    ) as mapping_record;

    if v_mappings is null
       or cardinality(v_mappings) = 0
    then
        raise exception
            'GL_MAPPINGS_NOT_FOUND';
    end if;

    v_stage := 'build posting components';

    v_components :=
        public.build_posting_components(
            p_transaction_type,
            v_amount,
            v_mappings,
            p_country_code,
            v_currency_code,
            false
        );

    if v_components is null
       or cardinality(v_components) = 0
    then
        raise exception
            'POSTING_COMPONENTS_NOT_FOUND';
    end if;

    /*
     * Expected configured accounting:
     *
     * Dr 1008000 Agent Cash Holding
     * Cr 2002000 Customer Deposits
     */
    v_stage := 'fetch fiscal period';

    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        p_country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    v_stage := 'fetch wallet-owner configuration';

    select wallet_owner_record.*
    into v_wallet_owners
    from public.fetch_transaction_type_wallet_owner(
        p_transaction_type
    ) as wallet_owner_record;

    if not found then
        raise exception
            'CREDIT_AGENT_CASH_DEPOSIT_WALLET_OWNER_NOT_FOUND';
    end if;

    v_stage := 'generate document number';

    v_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            p_transaction_type
        );

    if nullif(btrim(v_document_prefix), '') is null then
        raise exception
            'DOCUMENT_PREFIX_NOT_FOUND';
    end if;

    v_document_number :=
        public.generate_document_number(
            v_document_prefix,
            v_fiscal_year,
            v_period,
            p_country_code
        );

    /*
     * Build notification before wallet posting.
     */
    v_stage := 'build customer notification';

    v_notification :=
        public.create_notification_message(
            p_country_code =>
                p_country_code,

            p_transaction_type =>
                p_transaction_type,

            p_audience =>
                'receiver'::public."NotificationAudience",

            p_amount =>
                v_amount,

            p_currency =>
                upper(v_currency_code),

            p_reference =>
                v_reference,

            p_quantity =>
                0,

            p_sender =>
                coalesce(
                    v_provider.email,
                    v_provider.id
                ),

            p_receiver =>
                coalesce(
                    v_customer.email,
                    v_customer.id
                )
        );

    v_notification_json :=
        to_jsonb(v_notification);

    v_device_tokens :=
        public.fetch_device_tokens(
            p_country_code,
            v_customer.id
        );

    /*
     * Create financial transaction.
     */
    v_stage := 'create financial transaction';

    insert into public.financial_transaction (
        document_number,
        reference,
        fiscal_year,
        period,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        country_code
    )
    values (
        v_document_number,
        v_reference,
        v_fiscal_year,
        v_period,
        p_transaction_type,
        format(
            'Credit-agent cash deposit for customer %s through merchant %s',
            v_customer.id,
            v_provider.id
        ),
        v_provider.id,
        v_amount,
        v_currency_code,
        p_country_code
    )
    returning id
    into v_financial_transaction_id;

    /*
     * Post the GL journal.
     */
    v_stage := 'post financial entries';

    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_document_number,

        p_country_code =>
            p_country_code,

        p_transaction_id =>
            v_financial_transaction_id,

        p_transaction_type =>
            p_transaction_type,

        p_created_by =>
            v_provider.id,

        p_components =>
            v_components,

        p_mappings =>
            v_mappings,

        p_currency_code =>
            v_currency_code,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_reference =>
            v_reference,

        p_deposit_type =>
            null
    );

    /*
     * Move wallet value:
     *
     * sender   = merchant's agent wallet
     * receiver = customer's user wallet
     */
    v_stage := 'post wallet entries';

    select
        wallet_result.wallet_entry_count,
        wallet_result.receiver_notification_id
    into
        v_wallet_entry_count,
        v_receiver_notification_id
    from public.post_wallet_entries(
        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_document_number =>
            v_document_number,

        p_reference =>
            v_reference,

        p_receiver_id =>
            v_customer.id,

        p_sender_id =>
            v_provider.id,

        p_transaction_type =>
            p_transaction_type,

        p_credit_amount =>
            v_amount,

        p_debit_amount =>
            v_amount,

        p_sender_wallet_owner =>
            v_wallet_owners.sender_wallet_owner,

        p_receiver_wallet_owner =>
            v_wallet_owners.receiver_wallet_owner,

        p_currency_code =>
            v_currency_code,

        p_country_code =>
            p_country_code,

        p_audit_action_type =>
            v_wallet_owners.audit_action_type,

        p_treasury_id =>
            null,

        p_fee_amount =>
            0,

        p_ip_address =>
            p_ip_address,

        p_receiver_notification =>
            v_notification,

        p_sender_notification =>
            null
    ) as wallet_result;

    /*
     * Increase the merchant's cash holding.
     *
     * Receivable is unchanged.
     */
    v_stage := 'post credit agent cash holding';

    perform public.post_credit_agent_entry(
        p_credit_agent_account_id =>
            v_credit_account.id::text,

        p_document_number =>
            v_document_number,

        p_transaction_type =>
            p_transaction_type,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_debit_receivable =>
            0,

        p_credit_receivable =>
            0,

        p_debit_cash_holding =>
            v_amount,

        p_credit_cash_holding =>
            0,

        p_created_by =>
            v_provider.id
    );

    /*
     * Mark the verified transaction state completed.
     */
    v_stage := 'complete transaction state';

    update public.transaction_state
    set
        status =
            'success'::public."TransactionStatus",

        message =
            null,

        updated_at =
            now()
    where id::text =
          p_transaction_state_id

      and status =
          'processing'::public."TransactionStatus";

    if not found then
        raise exception
            'TRANSACTION_STATE_UPDATE_FAILED';
    end if;

    return query
    select
        true,

        v_reference,

        v_customer.id,

        v_amount::text,

        v_receiver_notification_id,

        v_device_tokens,

        coalesce(
            v_notification_json ->> 'title',
            v_notification_json ->> 'push_title'
        ),

        coalesce(
            v_notification_json ->> 'body',
            v_notification_json ->> 'message',
            v_notification_json ->> 'push_body'
        ),

        coalesce(
            v_notification_json ->> 'reference',
            v_reference
        );

exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;

        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'CREDIT_AGENT_CASH_DEPOSIT_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                concat_ws(
                    E'\n',
                    nullif(v_error_detail, ''),
                    nullif(v_error_context, '')
                ),

            hint =
                coalesce(
                    nullif(v_error_hint, ''),
                    format(
                        'Check the Credit Agent Cash Deposit stage: %s',
                        v_stage
                    )
                );
end;
$_$;
ALTER FUNCTION "public"."credit_agent_cash_deposit_posting"("p_user_id" "text", "p_transaction" "jsonb", "p_transaction_type" "public"."TransactionType", "p_country_code" "text", "p_transaction_state_id" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."credit_agent_cash_settlement"("p_merchant_id" "text", "p_transaction" "jsonb", "p_transaction_type" "public"."TransactionType", "p_country_code" "text", "p_transaction_state_id" "text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "document_number" "text", "reference" "text", "merchant_id" "text", "accounts_id" "text", "currency_code" "text", "settled_amount" "text", "cash_holding_before" "text", "cash_holding_after" "text", "merchant_notification_id" "text", "device_tokens" "text"[], "push_title" "text", "push_body" "text", "push_reference" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
    v_stage text :=
        'initialization';

    v_transaction_state
        public.transaction_state%rowtype;

    v_merchant
        public.users%rowtype;

    v_accounts
        public.users%rowtype;

    v_treasury
        public.users%rowtype;

    v_treasury_wallet
        public.wallet%rowtype;

    v_credit_account
        public.credit_agent_account%rowtype;

    v_transaction_version text;
    v_reference text;
    v_accounts_id text;
    v_currency_code text;

    v_amount_minor numeric;
    v_amount numeric;

    v_cash_holding_before numeric;
    v_cash_holding_after numeric;

    v_fiscal_year integer;
    v_period integer;

    v_mappings
        public.transaction_gl_mapping[];

    v_components
        public.posting_component[];

    v_principal_debit numeric := 0;
    v_principal_credit numeric := 0;

    v_document_prefix text;
    v_document_number text;

    v_financial_transaction_id
        public.financial_transaction.id%type;

    v_notification
        public.notification_message;

    v_notification_json jsonb;

    v_device_tokens text[];

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * Only the Edge Function service client executes the
     * financial posting.
     */
    if coalesce(
        auth.role(),
        ''
    ) <> 'service_role'
    then
        raise exception using
            errcode =
                '42501',

            message =
                'FORBIDDEN';
    end if;

    if p_transaction_type <>
       'credit_agent_cash_settlement'::public."TransactionType"
    then
        raise exception
            'INVALID_CREDIT_AGENT_CASH_SETTLEMENT_TRANSACTION_TYPE';
    end if;

    if p_transaction is null then
        raise exception
            'TRANSACTION_DATA_IS_MISSING';
    end if;

    if nullif(
        btrim(
            p_transaction_state_id
        ),
        ''
    ) is null
    then
        raise exception
            'TRANSACTION_STATE_ID_REQUIRED';
    end if;

    /*
     * Read transaction fields.
     *
     * transaction.s is the accounts user who received
     * the physical cash.
     */
    v_stage :=
        'read transaction fields';

    v_transaction_version :=
        nullif(
            btrim(
                p_transaction ->> 'v'
            ),
            ''
        );

    v_reference :=
        nullif(
            btrim(
                p_transaction ->> 'r'
            ),
            ''
        );

    v_accounts_id :=
        nullif(
            btrim(
                p_transaction ->> 's'
            ),
            ''
        );

    v_currency_code :=
        lower(
            nullif(
                btrim(
                    p_transaction ->> 'c'
                ),
                ''
            )
        );

    if v_transaction_version <> 'v8' then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    if v_reference is null then
        raise exception
            'REFERENCE_REQUIRED';
    end if;

    if v_accounts_id is null then
        raise exception
            'ACCOUNTS_ID_MISSING';
    end if;

    if v_currency_code is null then
        raise exception
            'CURRENCY_REQUIRED';
    end if;

    if v_currency_code = 'gold' then
        raise exception
            'INVALID_SETTLEMENT_CURRENCY';
    end if;

    if coalesce(
        p_transaction ->> 'a',
        ''
    ) !~ '^[0-9]+$'
    then
        raise exception
            'INVALID_AMOUNT';
    end if;

    v_amount_minor :=
        (p_transaction ->> 'a')::numeric;

    v_amount :=
        round(
            v_amount_minor /
            100,
            2
        );

    if v_amount <= 0 then
        raise exception
            'INVALID_AMOUNT';
    end if;

    /*
     * Lock and validate the processing state.
     */
    v_stage :=
        'validate transaction state';

    select transaction_state_record.*
    into v_transaction_state
    from public.transaction_state
        transaction_state_record
    where transaction_state_record.id::text =
          p_transaction_state_id
    for update;

    if not found then
        raise exception
            'TRANSACTION_STATE_NOT_FOUND';
    end if;

    if v_transaction_state.status <>
       'processing'::public."TransactionStatus"
    then
        raise exception
            'TRANSACTION_NOT_PROCESSING';
    end if;

    if v_transaction_state.transaction_type <>
       p_transaction_type
    then
        raise exception
            'TRANSACTION_TYPE_MISMATCH';
    end if;

    if v_transaction_state.reference <>
       v_reference
    then
        raise exception
            'REFERENCE_MISMATCH';
    end if;

    /*
     * The merchant created the state after scanning the
     * accounts transaction.
     */
    if v_transaction_state.created_by <>
       p_merchant_id
    then
        raise exception
            'MERCHANT_MISMATCH';
    end if;

    /*
     * The accounts user signed TransactionData.
     */
    if v_transaction_state.user_id <>
       v_accounts_id
    then
        raise exception
            'ACCOUNTS_USER_MISMATCH';
    end if;

    if lower(
        v_transaction_state.country_code
    ) <>
       lower(p_country_code)
    then
        raise exception
            'COUNTRY_MISMATCH';
    end if;

    /*
     * Fetch the active merchant.
     */
    v_stage :=
        'fetch merchant';

    select merchant_record.*
    into v_merchant
    from public.users
        merchant_record
    join public.user_role
        role_record
      on role_record.id =
         merchant_record.role_id
    where merchant_record.id =
          p_merchant_id

      and merchant_record.status =
          'active'::public."UserStatus"

      and lower(
          role_record.name::text
      ) =
          'merchant'

      and lower(
          merchant_record.country_code
      ) =
          lower(p_country_code)
    limit 1;

    if not found then
        raise exception
            'MERCHANT_NOT_AUTHORIZED';
    end if;

    /*
     * Fetch the active accounts user.
     */
    v_stage :=
        'fetch accounts user';

    select accounts_record.*
    into v_accounts
    from public.users
        accounts_record
    where accounts_record.id =
          v_accounts_id

      and accounts_record.status =
          'active'::public."UserStatus"

      and accounts_record.country_code =
          v_merchant.country_code
    limit 1;

    if not found then
        raise exception
            'ACCOUNTS_USER_NOT_FOUND';
    end if;

    if not public.user_has_role(
        v_accounts.id,
        array[
            'accounts'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode =
                '42501',

            message =
                'ACCOUNTS_USER_NOT_AUTHORIZED';
    end if;

    /*
     * Fetch the country treasury using the trusted
     * merchant country.
     */
    v_stage :=
        'fetch country treasury';

    select treasury_record.*
    into v_treasury
    from public.fetch_country_treasury(
        v_merchant.country_code
    ) as treasury_record;

    if not found
       or v_treasury.id is null
    then
        raise exception
            'TREASURY_NOT_FOUND';
    end if;

    /*
     * Lock the merchant's credit-agent account.
     */
    v_stage :=
        'lock credit agent account';

    select account_record.*
    into v_credit_account
    from public.credit_agent_account
        account_record
    where account_record.merchant_id =
          v_merchant.id

      and account_record.country_code =
          v_merchant.country_code

      and lower(
          btrim(
              account_record.currency_code
          )
      ) =
          v_currency_code

      and account_record.is_active =
          true
    for update;

    if not found then
        raise exception
            'CREDIT_AGENT_ACCOUNT_NOT_ACTIVE';
    end if;

    v_cash_holding_before :=
        coalesce(
            v_credit_account.cash_holding_balance,
            0
        );

    if v_amount >
       v_cash_holding_before
    then
        raise exception
            'SETTLEMENT_EXCEEDS_CASH_HOLDING';
    end if;

    v_cash_holding_after :=
        v_cash_holding_before -
        v_amount;

    /*
     * Prevent duplicate financial posting.
     */
    v_stage :=
        'check posting replay';

    perform 1
    from public.financial_transaction
        financial_transaction_record
    where financial_transaction_record.reference =
          v_reference
    limit 1;

    if found then
        raise exception
            'TRANSACTION_REPLAY';
    end if;

    /*
     * Fetch the principal-only settlement mappings.
     *
     * Expected posting:
     *
     * Dr Bank/Cash Reserve
     * Cr Agent Cash Holding
     */
    v_stage :=
        'fetch gl mappings';

    select array_agg(
        mapping_record
    )
    into v_mappings
    from public.fetch_gl_mappings(
        p_transaction_type
    ) as mapping_record;

    if v_mappings is null
       or cardinality(
           v_mappings
       ) = 0
    then
        raise exception
            'GL_MAPPINGS_NOT_FOUND';
    end if;

    v_stage :=
        'build posting components';

    v_components :=
        public.build_posting_components(
            p_transaction_type,
            v_amount,
            v_mappings,
            v_merchant.country_code,
            v_currency_code,
            false
        );

    if v_components is null
       or cardinality(
           v_components
       ) = 0
    then
        raise exception
            'POSTING_COMPONENTS_NOT_FOUND';
    end if;

    /*
     * Settlement must not contain fees, taxes or
     * commissions.
     */
    perform 1
    from unnest(
        v_components
    ) as component_record
    where component_record.component_type <>
          'principal'::public."ComponentType"

      and (
          coalesce(
              component_record.debit_amount,
              0
          ) <> 0

          or

          coalesce(
              component_record.credit_amount,
              0
          ) <> 0
      )
    limit 1;

    if found then
        raise exception
            'CASH_SETTLEMENT_CHARGES_NOT_ALLOWED';
    end if;

    /*
     * Read the principal fields directly.
     */
    select
        coalesce(
            component_record.debit_amount,
            0
        ),

        coalesce(
            component_record.credit_amount,
            0
        )
    into
        v_principal_debit,
        v_principal_credit
    from unnest(
        v_components
    ) as component_record
    where component_record.component_type =
          'principal'::public."ComponentType"
    limit 1;

    if not found then
        raise exception
            'PRINCIPAL_COMPONENT_NOT_FOUND';
    end if;

    if v_principal_debit <> v_amount
       or v_principal_credit <> v_amount
    then
        raise exception
            'INVALID_SETTLEMENT_PRINCIPAL';
    end if;

    /*
     * Fetch fiscal period.
     */
    v_stage :=
        'fetch fiscal period';

    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_merchant.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Generate document number.
     */
    v_stage :=
        'generate document number';

    v_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            p_transaction_type
        );

    if nullif(
        btrim(
            v_document_prefix
        ),
        ''
    ) is null
    then
        raise exception
            'DOCUMENT_PREFIX_NOT_FOUND';
    end if;

    v_document_number :=
        public.generate_document_number(
            v_document_prefix,
            v_fiscal_year,
            v_period,
            v_merchant.country_code
        );

    /*
     * Build settlement confirmation for the merchant.
     */
    v_stage :=
        'build merchant notification';

    v_notification :=
        public.create_notification_message(
            p_country_code =>
                v_merchant.country_code,

            p_transaction_type =>
                p_transaction_type,

            p_audience =>
                'receiver'::public."NotificationAudience",

            p_amount =>
                v_amount,

            p_currency =>
                upper(
                    v_currency_code
                ),

            p_reference =>
                v_reference,

            p_quantity =>
                0,

            p_sender =>
                coalesce(
                    v_accounts.email,
                    v_accounts.id
                ),

            p_receiver =>
                coalesce(
                    v_merchant.email,
                    v_merchant.id
                )
        );

    v_notification_json :=
        to_jsonb(
            v_notification
        );

    v_device_tokens :=
        public.fetch_device_tokens(
            v_merchant.country_code,
            v_merchant.id
        );

    /*
     * Create financial transaction.
     *
     * Accounts is the business user who received the
     * physical cash and created TransactionData.
     */
    v_stage :=
        'create financial transaction';

    insert into public.financial_transaction (
        document_number,
        reference,
        fiscal_year,
        period,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        country_code
    )
    values (
        v_document_number,
        v_reference,
        v_fiscal_year,
        v_period,
        p_transaction_type,

        format(
            'Credit-agent cash settlement received from merchant %s by accounts user %s',
            v_merchant.id,
            v_accounts.id
        ),

        v_accounts.id,
        v_amount,
        v_currency_code,
        v_merchant.country_code
    )
    returning id
    into v_financial_transaction_id;

    /*
     * Post:
     *
     * Dr Bank/Cash Reserve
     * Cr Agent Cash Holding
     */
    v_stage :=
        'post financial entries';

    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_document_number,

        p_country_code =>
            v_merchant.country_code,

        p_transaction_id =>
            v_financial_transaction_id,

        p_transaction_type =>
            p_transaction_type,

        p_created_by =>
            v_accounts.id,

        p_components =>
            v_components,

        p_mappings =>
            v_mappings,

        p_currency_code =>
            v_currency_code,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_reference =>
            v_reference,

        p_deposit_type =>
            null
    );

    /*
     * Lock the country treasury wallet.
     */
    v_stage :=
        'lock treasury wallet';

    select wallet_record.*
    into v_treasury_wallet
    from public.wallet
        wallet_record
    where wallet_record.country_code =
          v_merchant.country_code

      and wallet_record.user_id =
          v_treasury.id

      and lower(
          btrim(
              wallet_record.currency_code
          )
      ) =
          v_currency_code

      and wallet_record.owner_type =
          'treasury'::public."WalletOwnerType"
    for update;

    if not found then
        raise exception
            'TREASURY_WALLET_NOT_FOUND';
    end if;

    if not v_treasury_wallet.is_active then
        raise exception
            'TREASURY_WALLET_FROZEN';
    end if;

    /*
     * Accounts and merchant do not have financial-wallet
     * movements. Only the country treasury wallet is
     * credited.
     */
    v_stage :=
        'credit treasury wallet';

    update public.wallet
    set
        balance =
            balance +
            v_amount
    where id =
          v_treasury_wallet.id

      and is_active =
          true;

    if not found then
        raise exception
            'TREASURY_WALLET_UPDATE_FAILED';
    end if;

    insert into public.wallet_entry (
        document_number,
        reference,
        fiscal_year,
        period,
        transaction_type,
        wallet_id,
        currency_code,
        country_code,
        debit,
        credit,
        created_by
    )
    values (
        v_document_number,
        v_reference,
        v_fiscal_year,
        v_period,
        p_transaction_type,
        v_treasury_wallet.id,
        v_currency_code,
        v_merchant.country_code,
        0,
        v_amount,
        v_accounts.id
    );

    /*
     * Update the treasury wallet snapshot.
     *
     * The first wallet amount is debit/outgoing.
     * The second wallet amount is credit/incoming.
     */
    perform public.update_wallet_balance_snapshot(
        p_transaction_type,
        v_treasury.id,
        v_treasury.id,
        null,
        v_currency_code,
        'treasury'::public."WalletOwnerType",
        'treasury'::public."WalletOwnerType",
        0,
        v_amount,
        v_fiscal_year,
        v_period,
        v_merchant.country_code,
        0
    );

    /*
     * Reduce the merchant cash-holding balance and create
     * the immutable credit-agent entry.
     */
    v_stage :=
        'post credit agent cash settlement';

    perform public.post_credit_agent_entry(
        p_credit_agent_account_id =>
            v_credit_account.id::text,

        p_document_number =>
            v_document_number,

        p_transaction_type =>
            p_transaction_type,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_debit_receivable =>
            0,

        p_credit_receivable =>
            0,

        p_debit_cash_holding =>
            0,

        p_credit_cash_holding =>
            v_amount,

        p_created_by =>
            v_accounts.id
    );

    /*
     * Audit the accounts user who received the cash.
     */
    v_stage :=
        'create audit log';

    insert into public.audit_log (
        user_id,
        country_code,
        fiscal_year,
        period,
        action_type,
        entity_type,
        entity_id,
        document_number,
        old_value,
        new_value,
        metadata,
        ip_address
    )
    values (
        v_accounts.id,
        v_merchant.country_code,
        v_fiscal_year,
        v_period,
        'credit_agent_cash_settled'::public."AuditActionType",
        'credit_agent_account',
        v_credit_account.id::text,
        v_document_number,

        jsonb_build_object(
            'cash_holding_balance',
            v_cash_holding_before::text
        ),

        jsonb_build_object(
            'cash_holding_balance',
            v_cash_holding_after::text
        ),

        jsonb_build_object(
            'merchant_id',
            v_merchant.id,

            'accounts_id',
            v_accounts.id,

            'treasury_id',
            v_treasury.id,

            'reference',
            v_reference,

            'currency_code',
            v_currency_code,

            'settled_amount',
            v_amount::text
        ),

        p_ip_address
    );

    /*
     * Mark the signed transaction successful.
     */
    v_stage :=
        'complete transaction state';

    update public.transaction_state
    set
        status =
            'success'::public."TransactionStatus",

        message =
            null,

        updated_at =
            now()
    where id::text =
          p_transaction_state_id

      and status =
          'processing'::public."TransactionStatus";

    if not found then
        raise exception
            'TRANSACTION_STATE_UPDATE_FAILED';
    end if;

    return query
    select
        true,

        v_document_number,

        v_reference,

        v_merchant.id,

        v_accounts.id,

        v_currency_code,

        v_amount::text,

        v_cash_holding_before::text,

        v_cash_holding_after::text,

        null::text,

        v_device_tokens,

        coalesce(
            v_notification_json ->> 'title',
            v_notification_json ->> 'push_title'
        ),

        coalesce(
            v_notification_json ->> 'body',
            v_notification_json ->> 'message',
            v_notification_json ->> 'push_body'
        ),

        coalesce(
            v_notification_json ->> 'reference',
            v_reference
        );

exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;

        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'CREDIT_AGENT_CASH_SETTLEMENT_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                concat_ws(
                    E'\n',
                    nullif(
                        v_error_detail,
                        ''
                    ),
                    nullif(
                        v_error_context,
                        ''
                    )
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    format(
                        'Check the Credit Agent Cash Settlement stage: %s',
                        v_stage
                    )
                );
end;
$_$;
ALTER FUNCTION "public"."credit_agent_cash_settlement"("p_merchant_id" "text", "p_transaction" "jsonb", "p_transaction_type" "public"."TransactionType", "p_country_code" "text", "p_transaction_state_id" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."credit_agent_cash_withdrawal"("p_agent_id" "text", "p_transaction" "jsonb", "p_transaction_type" "public"."TransactionType", "p_country_code" "text", "p_transaction_state_id" "text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "document_no" "text", "amount" "text", "fee" "text", "tax" "text", "currency" "text", "holding_used" "text", "receivable_used" "text", "user_notification_id" "text", "device_tokens" "text"[], "push_title" "text", "push_body" "text", "push_reference" "text", "amount_usd" "text", "sender_debit" "text", "sender_debit_usd" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
    v_stage text :=
        'initialization';

    v_transaction_state
        public.transaction_state%rowtype;

    v_agent
        public.users%rowtype;

    v_user
        public.users%rowtype;

    v_treasury
        public.users%rowtype;

    v_credit_account
        public.credit_agent_account%rowtype;

    v_transaction_version text;
    v_reference text;
    v_user_id text;
    v_currency_code text;

    v_requested_amount_minor numeric;
    v_requested_amount numeric;

    /*
     * Financial Intelligence USD conversion.
     *
     * current_rates.rate_to_usd means:
     *
     *     1 USD = rate_to_usd units of currency
     *
     * Therefore:
     *
     *     USD = currency amount / rate_to_usd
     *
     * USD itself uses rate 1.
     */
    v_rate_to_usd numeric;

    v_amount_usd numeric(20, 6) := 0;
    v_sender_debit_usd numeric(20, 6) := 0;

    v_fiscal_year integer;
    v_period integer;

    v_all_mappings
        public.transaction_gl_mapping[];

    v_build_mappings
        public.transaction_gl_mapping[];

    v_components
        public.posting_component[];

    v_final_components
        public.posting_component[] :=
            array[]::public.posting_component[];

    v_component
        public.posting_component;

    v_cash_amount numeric := 0;
    v_total_wallet_debit numeric := 0;

    v_fee numeric := 0;
    v_tax numeric := 0;
    v_agent_commission numeric := 0;

    v_tax_rate numeric := 0;
    v_commission_rate numeric := 0;

    v_total_charges numeric := 0;

    v_holding_used numeric := 0;
    v_receivable_used numeric := 0;
    v_available_balance numeric := 0;

    v_wallet_owners
        public.transaction_type_wallet_owner%rowtype;

    v_document_prefix text;
    v_document_number text;

    v_financial_transaction_id
        public.financial_transaction.id%type;

    v_notification
        public.notification_message;

    v_notification_json jsonb;
    v_device_tokens text[];

    v_wallet_entry_count integer;
    v_ignored_notification_id text;

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;

begin
    /*
     * ==========================================================
     * AUTHORIZATION
     * ==========================================================
     *
     * Only the Edge Function service client can execute
     * the financial posting.
     */
    if coalesce(
        auth.role(),
        ''
    ) <> 'service_role'
    then
        raise exception using
            errcode =
                '42501',

            message =
                'FORBIDDEN';
    end if;


    /*
     * ==========================================================
     * VALIDATE TRANSACTION TYPE
     * ==========================================================
     */
    if p_transaction_type <>
       'credit_agent_cash_withdrawal'::public."TransactionType"
    then
        raise exception
            'INVALID_CREDIT_AGENT_CASH_WITHDRAWAL_TRANSACTION_TYPE';
    end if;


    if p_transaction is null then
        raise exception
            'TRANSACTION_DATA_IS_MISSING';
    end if;


    if nullif(
        btrim(
            p_transaction_state_id
        ),
        ''
    ) is null
    then
        raise exception
            'TRANSACTION_STATE_ID_REQUIRED';
    end if;


    /*
     * ==========================================================
     * READ SIGNED TRANSACTION FIELDS
     * ==========================================================
     */
    v_stage :=
        'read transaction fields';


    v_transaction_version :=
        nullif(
            btrim(
                p_transaction ->> 'v'
            ),
            ''
        );


    v_reference :=
        nullif(
            btrim(
                p_transaction ->> 'r'
            ),
            ''
        );


    v_user_id :=
        nullif(
            btrim(
                p_transaction ->> 's'
            ),
            ''
        );


    v_currency_code :=
        lower(
            nullif(
                btrim(
                    p_transaction ->> 'c'
                ),
                ''
            )
        );


    if v_transaction_version <> 'v3' then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;


    if v_reference is null then
        raise exception
            'REFERENCE_REQUIRED';
    end if;


    if v_user_id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;


    if v_currency_code is null then
        raise exception
            'CURRENCY_REQUIRED';
    end if;


    if coalesce(
        p_transaction ->> 'a',
        ''
    ) !~ '^[0-9]+$'
    then
        raise exception
            'INVALID_AMOUNT';
    end if;


    v_requested_amount_minor :=
        (p_transaction ->> 'a')::numeric;


    v_requested_amount :=
        round(
            v_requested_amount_minor /
            100,
            2
        );


    if v_requested_amount <= 0 then
        raise exception
            'INVALID_AMOUNT';
    end if;


    /*
     * ==========================================================
     * VALIDATE TRANSACTION STATE
     * ==========================================================
     */
    v_stage :=
        'validate transaction state';


    select transaction_state_record.*
    into v_transaction_state
    from public.transaction_state
        transaction_state_record
    where transaction_state_record.id::text =
          p_transaction_state_id
    for update;


    if not found then
        raise exception
            'TRANSACTION_STATE_NOT_FOUND';
    end if;


    if v_transaction_state.status <>
       'processing'::public."TransactionStatus"
    then
        raise exception
            'TRANSACTION_NOT_PROCESSING';
    end if;


    if v_transaction_state.transaction_type <>
       p_transaction_type
    then
        raise exception
            'TRANSACTION_TYPE_MISMATCH';
    end if;


    if v_transaction_state.reference <>
       v_reference
    then
        raise exception
            'REFERENCE_MISMATCH';
    end if;


    if v_transaction_state.created_by <>
       p_agent_id
    then
        raise exception
            'MERCHANT_MISMATCH';
    end if;


    if v_transaction_state.user_id <>
       v_user_id
    then
        raise exception
            'USER_MISMATCH';
    end if;


    /*
     * ==========================================================
     * FETCH ACTIVE CREDIT MERCHANT
     * ==========================================================
     */
    v_stage :=
        'fetch credit merchant';


    select merchant_record.*
    into v_agent
    from public.users
        merchant_record
    join public.user_role
        role_record
      on role_record.id =
         merchant_record.role_id
    where merchant_record.id =
          p_agent_id

      and merchant_record.status =
          'active'::public."UserStatus"

      and lower(
          merchant_record.country_code
      ) =
          lower(p_country_code)

      and lower(
          role_record.name::text
      ) =
          'merchant'
    limit 1;


    if not found then
        raise exception
            'CREDIT_AGENT_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * FETCH ACTIVE WITHDRAWING USER
     * ==========================================================
     */
    v_stage :=
        'fetch withdrawing user';


    select user_record.*
    into v_user
    from public.users
        user_record
    where user_record.id =
          v_user_id

      and user_record.status =
          'active'::public."UserStatus"

      and lower(
          user_record.country_code
      ) =
          lower(p_country_code)
    limit 1;


    if not found then
        raise exception
            'USER_NOT_ACTIVE';
    end if;


    /*
     * ==========================================================
     * FETCH COUNTRY TREASURY
     * ==========================================================
     */
    v_stage :=
        'fetch country treasury';


    select treasury_record.*
    into v_treasury
    from public.fetch_country_treasury(
        p_country_code
    ) as treasury_record;


    if not found
       or v_treasury.id is null
    then
        raise exception
            'TREASURY_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * LOCK CREDIT AGENT ACCOUNT
     * ==========================================================
     */
    v_stage :=
        'lock credit agent account';


    select account_record.*
    into v_credit_account
    from public.credit_agent_account
        account_record
    where account_record.merchant_id =
          v_agent.id

      and lower(
          account_record.country_code
      ) =
          lower(p_country_code)

      and lower(
          account_record.currency_code
      ) =
          v_currency_code

      and account_record.is_active =
          true
    for update;


    if not found then
        raise exception
            'CREDIT_AGENT_ACCOUNT_NOT_ACTIVE';
    end if;


    /*
     * ==========================================================
     * FETCH GL MAPPINGS
     * ==========================================================
     *
     * principal
     * credit_agent_receivable
     * withdrawal_fee
     * government_tax
     * agent_commission
     */
    v_stage :=
        'fetch gl mappings';


    select array_agg(
        mapping_record
    )
    into v_all_mappings
    from public.fetch_gl_mappings(
        p_transaction_type
    ) as mapping_record;


    if v_all_mappings is null
       or cardinality(
           v_all_mappings
       ) = 0
    then
        raise exception
            'GL_MAPPINGS_NOT_FOUND';
    end if;


    /*
     * Receivable is calculated dynamically, so exclude
     * it from the normal pricing build.
     */
    select array_agg(
        mapping_record
    )
    into v_build_mappings
    from unnest(
        v_all_mappings
    ) as mapping_record
    where mapping_record.component_type <>
          'credit_agent_receivable'::public."ComponentType";


    if v_build_mappings is null
       or cardinality(
           v_build_mappings
       ) = 0
    then
        raise exception
            'BASE_GL_MAPPINGS_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * BUILD WITHDRAWAL COMPONENTS
     * ==========================================================
     */
    v_stage :=
        'build withdrawal components';


    v_components :=
        public.build_posting_components(
            p_transaction_type,
            v_requested_amount,
            v_build_mappings,
            p_country_code,
            v_currency_code,
            false
        );


    if v_components is null
       or cardinality(
           v_components
       ) = 0
    then
        raise exception
            'POSTING_COMPONENTS_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * READ PRINCIPAL COMPONENT
     * ==========================================================
     *
     * debit_amount:
     *
     *     actual customer wallet debit
     *
     * credit_amount:
     *
     *     cash amount received by merchant
     */
    v_stage :=
        'read principal component';


    select
        coalesce(
            component_record.debit_amount,
            0
        ),

        coalesce(
            component_record.credit_amount,
            0
        )
    into
        v_total_wallet_debit,
        v_cash_amount
    from unnest(
        v_components
    ) as component_record
    where component_record.component_type =
          'principal'::public."ComponentType"
    limit 1;


    if not found then
        raise exception
            'PRINCIPAL_COMPONENT_NOT_FOUND';
    end if;


    if v_total_wallet_debit <= 0
       or v_cash_amount <= 0
    then
        raise exception
            'INVALID_WITHDRAWAL_COMPONENTS';
    end if;


    if v_total_wallet_debit <
       v_cash_amount
    then
        raise exception
            'INVALID_FINAL_WITHDRAWAL_DEBIT';
    end if;


    /*
     * ==========================================================
     * FETCH USD CONVERSION RATE
     * ==========================================================
     *
     * current_rates:
     *
     *     code
     *     rate_to_usd
     *
     * Example:
     *
     *     BWP rate_to_usd = 13.437538
     *
     * Therefore:
     *
     *     100 BWP / 13.437538
     *         = USD equivalent
     */
    v_stage :=
        'fetch USD conversion rate';


    if v_currency_code = 'usd' then
        v_rate_to_usd := 1;

    else
        select
            current_rate.rate_to_usd
        into
            v_rate_to_usd
        from public.current_rates
            current_rate
        where lower(
            current_rate.code
        ) =
            lower(
                v_currency_code
            )
        limit 1;


        if not found
           or v_rate_to_usd is null
           or v_rate_to_usd <= 0
        then
            raise exception
                'CURRENT_RATE_NOT_FOUND_%',
                v_currency_code;
        end if;
    end if;


    /*
     * ==========================================================
     * CALCULATE CASH AMOUNT USD
     * ==========================================================
     *
     * This is the amount the receiving credit agent
     * actually receives.
     */
    v_stage :=
        'calculate withdrawal amount USD';


    if v_currency_code = 'usd' then
        v_amount_usd :=
            round(
                v_cash_amount,
                6
            );

    else
        v_amount_usd :=
            round(
                v_cash_amount /
                v_rate_to_usd,
                6
            );
    end if;


    if v_amount_usd <= 0 then
        raise exception
            'INVALID_AMOUNT_USD';
    end if;


    /*
     * ==========================================================
     * CALCULATE CUSTOMER WALLET DEBIT USD
     * ==========================================================
     *
     * This is the full savings outflow from the
     * withdrawing customer's wallet.
     *
     * It includes the withdrawal amount plus the
     * applicable customer charges.
     */
    v_stage :=
        'calculate sender debit USD';


    if v_currency_code = 'usd' then
        v_sender_debit_usd :=
            round(
                v_total_wallet_debit,
                6
            );

    else
        v_sender_debit_usd :=
            round(
                v_total_wallet_debit /
                v_rate_to_usd,
                6
            );
    end if;


    if v_sender_debit_usd <= 0 then
        raise exception
            'INVALID_SENDER_DEBIT_USD_AMOUNT';
    end if;


    /*
     * ==========================================================
     * EXTRACT WITHDRAWAL FEE
     * ==========================================================
     */
    select coalesce(
        sum(
            greatest(
                coalesce(
                    component_record.debit_amount,
                    0
                ),
                coalesce(
                    component_record.credit_amount,
                    0
                )
            )
        ),
        0
    )
    into v_fee
    from unnest(
        v_components
    ) as component_record
    where component_record.component_type =
          'withdrawal_fee'::public."ComponentType";


    /*
     * ==========================================================
     * EXTRACT GOVERNMENT TAX
     * ==========================================================
     */
    select coalesce(
        sum(
            greatest(
                coalesce(
                    component_record.debit_amount,
                    0
                ),
                coalesce(
                    component_record.credit_amount,
                    0
                )
            )
        ),
        0
    )
    into v_tax
    from unnest(
        v_components
    ) as component_record
    where component_record.component_type =
          'government_tax'::public."ComponentType";


    /*
     * ==========================================================
     * EXTRACT AGENT COMMISSION
     * ==========================================================
     *
     * Self-balancing component:
     *
     * Dr Agent Commission Expense
     * Cr Agent Commission Payable
     */
    select coalesce(
        sum(
            greatest(
                coalesce(
                    component_record.debit_amount,
                    0
                ),
                coalesce(
                    component_record.credit_amount,
                    0
                )
            )
        ),
        0
    )
    into v_agent_commission
    from unnest(
        v_components
    ) as component_record
    where component_record.component_type =
          'agent_commission'::public."ComponentType";


    /*
     * ==========================================================
     * DERIVE CONFIGURED RATES
     * ==========================================================
     */
    if v_cash_amount > 0
       and v_tax > 0
    then
        v_tax_rate :=
            round(
                (
                    v_tax *
                    100
                ) /
                v_cash_amount,
                2
            );
    end if;


    if v_fee > 0
       and v_agent_commission > 0
    then
        v_commission_rate :=
            round(
                (
                    v_agent_commission *
                    100
                ) /
                v_fee,
                2
            );
    end if;


    /*
     * ==========================================================
     * CUSTOMER CHARGES
     * ==========================================================
     *
     * Commission is a company expense and therefore does
     * not form part of the customer's wallet debit.
     */
    v_total_charges :=
        v_total_wallet_debit -
        v_cash_amount;


    if v_total_charges < 0 then
        raise exception
            'INVALID_WITHDRAWAL_CHARGES';
    end if;


    /*
     * ==========================================================
     * CALCULATE CASH HOLDING / RECEIVABLE SPLIT
     * ==========================================================
     */
    v_stage :=
        'calculate balance split';


    v_holding_used :=
        least(
            v_cash_amount,

            coalesce(
                v_credit_account.cash_holding_balance,
                0
            )
        );


    v_receivable_used :=
        v_cash_amount -
        v_holding_used;


    v_available_balance :=
        coalesce(
            v_credit_account.cash_holding_balance,
            0
        ) +
        coalesce(
            v_credit_account.receivable_balance,
            0
        );


    if v_cash_amount >
       v_available_balance
    then
        raise exception
            'INSUFFICIENT_CREDIT_AGENT_WITHDRAWAL_BALANCE';
    end if;


    if v_receivable_used >
       coalesce(
           v_credit_account.receivable_balance,
           0
       )
    then
        raise exception
            'INSUFFICIENT_CREDIT_AGENT_RECEIVABLE_BALANCE';
    end if;


    /*
     * ==========================================================
     * BUILD SPLIT POSTING COMPONENTS
     * ==========================================================
     *
     * Replace principal credit with the cash-holding
     * funded portion.
     */
    v_stage :=
        'build split posting components';


    foreach v_component in array v_components
    loop
        if v_component.component_type =
           'principal'::public."ComponentType"
        then
            v_component :=
                row(
                    v_component.component_type,
                    v_component.debit_amount,
                    v_holding_used
                )::public.posting_component;
        end if;


        v_final_components :=
            array_append(
                v_final_components,
                v_component
            );
    end loop;


    /*
     * Add receivable-funded portion.
     */
    if v_receivable_used > 0 then
        v_final_components :=
            array_append(
                v_final_components,

                row(
                    'credit_agent_receivable'::public."ComponentType",
                    0,
                    v_receivable_used
                )::public.posting_component
            );
    end if;


    v_stage :=
        'validate split posting components';


    v_final_components :=
        public.validate_components(
            v_final_components
        );


    /*
     * ==========================================================
     * FISCAL PERIOD
     * ==========================================================
     */
    v_stage :=
        'fetch fiscal period';


    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        p_country_code
    ) as fiscal_period;


    if not found
       or v_fiscal_year is null
       or v_period is null
    then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * DOCUMENT NUMBER
     * ==========================================================
     */
    v_stage :=
        'generate document number';


    v_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            p_transaction_type
        );


    if nullif(
        btrim(
            v_document_prefix
        ),
        ''
    ) is null
    then
        raise exception
            'DOCUMENT_PREFIX_NOT_FOUND';
    end if;


    v_document_number :=
        public.generate_document_number(
            v_document_prefix,
            v_fiscal_year,
            v_period,
            p_country_code
        );


    /*
     * ==========================================================
     * WALLET OWNER CONFIGURATION
     * ==========================================================
     */
    v_stage :=
        'fetch wallet-owner configuration';


    select wallet_owner_record.*
    into v_wallet_owners
    from public.fetch_transaction_type_wallet_owner(
        p_transaction_type
    ) as wallet_owner_record;


    if not found then
        raise exception
            'CREDIT_AGENT_CASH_WITHDRAWAL_WALLET_OWNER_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * CUSTOMER NOTIFICATION
     * ==========================================================
     */
    v_stage :=
        'build user notification';


    v_notification :=
        public.create_notification_message(
            p_country_code =>
                p_country_code,

            p_transaction_type =>
                p_transaction_type,

            p_audience =>
                'receiver'::public."NotificationAudience",

            p_amount =>
                v_cash_amount,

            p_currency =>
                upper(
                    v_currency_code
                ),

            p_reference =>
                v_reference,

            p_quantity =>
                0,

            p_sender =>
                coalesce(
                    v_agent.email,
                    v_agent.id
                ),

            p_receiver =>
                coalesce(
                    v_user.email,
                    v_user.id
                )
        );


    v_notification_json :=
        to_jsonb(
            v_notification
        );


    v_device_tokens :=
        public.fetch_device_tokens(
            p_country_code,
            v_user.id
        );


    /*
     * ==========================================================
     * FINANCIAL TRANSACTION HEADER
     * ==========================================================
     */
    v_stage :=
        'create financial transaction';


    insert into public.financial_transaction (
        document_number,
        reference,
        fiscal_year,
        period,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        country_code
    )
    values (
        v_document_number,
        v_reference,
        v_fiscal_year,
        v_period,
        p_transaction_type,

        format(
            'Credit-agent cash withdrawal for user %s through merchant %s',
            v_user.id,
            v_agent.id
        ),

        v_agent.id,
        v_total_wallet_debit,
        v_currency_code,
        p_country_code
    )
    returning id
    into v_financial_transaction_id;


    /*
     * ==========================================================
     * POST FINANCIAL ENTRIES
     * ==========================================================
     *
     * Dr Customer Deposits
     * Dr Agent Commission Expense
     *
     * Cr Agent Cash Holding
     * Cr Agent Receivable
     * Cr Withdrawal Fee Revenue
     * Cr Government Tax Payable
     * Cr Agent Commission Payable
     */
    v_stage :=
        'post financial entries';


    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_document_number,

        p_country_code =>
            p_country_code,

        p_transaction_id =>
            v_financial_transaction_id,

        p_transaction_type =>
            p_transaction_type,

        p_created_by =>
            v_agent.id,

        p_components =>
            v_final_components,

        p_mappings =>
            v_all_mappings,

        p_currency_code =>
            v_currency_code,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_reference =>
            v_reference,

        p_deposit_type =>
            null
    );


    /*
     * ==========================================================
     * WALLET POSTING
     * ==========================================================
     *
     * Customer:
     *
     *     debit = amount + charges
     *           = v_total_wallet_debit
     *
     * Credit merchant:
     *
     *     credit = cash amount
     *            = v_cash_amount
     *
     * Treasury:
     *
     *     credit = customer charges
     */
    v_stage :=
        'post wallet entries';


    select
        wallet_result.wallet_entry_count,
        wallet_result.receiver_notification_id
    into
        v_wallet_entry_count,
        v_ignored_notification_id
    from public.post_wallet_entries(
        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_document_number =>
            v_document_number,

        p_reference =>
            v_reference,

        p_receiver_id =>
            v_agent.id,

        p_sender_id =>
            v_user.id,

        p_transaction_type =>
            p_transaction_type,

        p_credit_amount =>
            v_cash_amount,

        p_debit_amount =>
            v_total_wallet_debit,

        p_sender_wallet_owner =>
            v_wallet_owners.sender_wallet_owner,

        p_receiver_wallet_owner =>
            v_wallet_owners.receiver_wallet_owner,

        p_currency_code =>
            v_currency_code,

        p_country_code =>
            p_country_code,

        p_audit_action_type =>
            v_wallet_owners.audit_action_type,

        p_treasury_id =>
            v_treasury.id,

        p_fee_amount =>
            v_total_charges,

        p_ip_address =>
            p_ip_address,

        p_receiver_notification =>
            null,

        p_sender_notification =>
            v_notification
    ) as wallet_result;


    /*
     * ==========================================================
     * AGENT COMMISSION PAYABLE
     * ==========================================================
     */
    if v_agent_commission > 0 then
        v_stage :=
            'create agent commission payable';


        insert into public.agent_commission (
            period,
            fiscal_year,
            country_code,
            agent_id,
            document_number,
            reference,
            transaction_type,
            currency_code,
            amount,
            fee_amount,
            commission_rate,
            commission_amount,
            is_settled,
            settled_at,
            settled_by,
            created_at,
            settlement_batch_id
        )
        values (
            v_period,
            v_fiscal_year,
            p_country_code,
            v_agent.id,
            v_document_number,
            null,
            p_transaction_type,
            v_currency_code,
            v_cash_amount,
            v_fee,
            v_commission_rate,
            v_agent_commission,
            false,
            null,
            null,
            now(),
            null
        );
    end if;


    /*
     * ==========================================================
     * GOVERNMENT TAX PAYABLE
     * ==========================================================
     */
    if v_tax > 0 then
        v_stage :=
            'create government tax payable';


        insert into public.government_tax_payable (
            period,
            fiscal_year,
            document_number,
            reference,
            transaction_type,
            currency_code,
            country_code,
            gross_amount,
            tax_rate,
            tax_amount,
            is_settled,
            settled_at,
            settled_by,
            created_at,
            settlement_batch_id
        )
        values (
            v_period,
            v_fiscal_year,
            v_document_number,
            null,
            p_transaction_type,
            v_currency_code,
            p_country_code,
            v_cash_amount,
            v_tax_rate,
            v_tax,
            false,
            null,
            null,
            now(),
            null
        );
    end if;


    /*
     * ==========================================================
     * REDUCE CREDIT AGENT BALANCES
     * ==========================================================
     */
    v_stage :=
        'post credit agent balance movement';


    perform public.post_credit_agent_entry(
        p_credit_agent_account_id =>
            v_credit_account.id::text,

        p_document_number =>
            v_document_number,

        p_transaction_type =>
            p_transaction_type,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_debit_receivable =>
            0,

        p_credit_receivable =>
            v_receivable_used,

        p_debit_cash_holding =>
            0,

        p_credit_cash_holding =>
            v_holding_used,

        p_created_by =>
            v_agent.id
    );


    /*
     * ==========================================================
     * COMPLETE TRANSACTION STATE
     * ==========================================================
     */
    v_stage :=
        'complete transaction state';


    update public.transaction_state
    set
        status =
            'success'::public."TransactionStatus",

        message =
            null,

        updated_at =
            now()
    where id::text =
          p_transaction_state_id

      and status =
          'processing'::public."TransactionStatus";


    if not found then
        raise exception
            'TRANSACTION_STATE_UPDATE_FAILED';
    end if;


    /*
     * ==========================================================
     * RETURN RESULT
     * ==========================================================
     *
     * Existing fields remain in their original order.
     *
     * Financial Intelligence fields are appended:
     *
     * amount_usd
     * sender_debit
     * sender_debit_usd
     *
     *
     * CUSTOMER
     *
     * withdrawal amount:
     *     v_cash_amount
     *
     * savings outflow:
     *     v_total_wallet_debit
     *
     *
     * CREDIT AGENT
     *
     * deposit amount:
     *     v_cash_amount
     *
     * savings inflow:
     *     v_cash_amount
     */
    v_stage :=
        'return credit agent cash withdrawal result';


    return query
    select
        true,

        v_document_number,

        v_cash_amount::text,

        v_fee::text,

        v_tax::text,

        v_currency_code,

        v_holding_used::text,

        v_receivable_used::text,

        null::text,

        v_device_tokens,

        coalesce(
            v_notification_json ->> 'title',
            v_notification_json ->> 'push_title'
        ),

        coalesce(
            v_notification_json ->> 'body',
            v_notification_json ->> 'message',
            v_notification_json ->> 'push_body'
        ),

        coalesce(
            v_notification_json ->> 'reference',
            v_reference
        ),

        /*
         * Financial Intelligence values.
         */
        v_amount_usd::text,

        v_total_wallet_debit::text,

        v_sender_debit_usd::text;


exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;


        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'CREDIT_AGENT_CASH_WITHDRAWAL_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                concat_ws(
                    E'\n',
                    nullif(
                        v_error_detail,
                        ''
                    ),
                    nullif(
                        v_error_context,
                        ''
                    )
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    format(
                        'Check the Credit Agent Cash Withdrawal stage: %s',
                        v_stage
                    )
                );
end;
$_$;
ALTER FUNCTION "public"."credit_agent_cash_withdrawal"("p_agent_id" "text", "p_transaction" "jsonb", "p_transaction_type" "public"."TransactionType", "p_country_code" "text", "p_transaction_state_id" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."detect_unhealthy_loan_positions"("p_country_code" "text", "p_gold_price_per_gram" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_country_code text;

    v_fiscal_year integer;
    v_period integer;

    v_target_ltv_percent numeric;
    v_liquidation_ltv_percent numeric;
    v_penalty_rate_percent numeric;

    v_target_ltv numeric;
    v_penalty_rate numeric;
    v_denominator numeric;

    v_position record;

    v_total_principal numeric;
    v_total_interest numeric;
    v_total_debt numeric;

    v_locked_tokens numeric;
    v_collateral_value numeric;
    v_current_ltv numeric;

    v_debt_repayment numeric;
    v_penalty_amount numeric;
    v_total_proceeds numeric;
    v_collateral_required numeric;

    v_evaluated integer := 0;
    v_detected integer := 0;
    v_already_underway integer := 0;
    v_skipped integer := 0;

    v_blockchain_code text;
    v_blockchain_gold_balance numeric;
    v_capped_sale_value numeric;

    v_stage text :=
        'initialization';

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * Only the liquidation Edge Function may execute
     * this financial detection process.
     */
    v_stage :=
        'authorize service role';

    if coalesce(
        auth.role(),
        ''
    ) <> 'service_role'
    then
        raise exception using
            errcode = '42501',
            message = 'SERVICE_ROLE_REQUIRED';
    end if;

    /*
     * Validate input.
     */
    v_stage :=
        'validate input';

    v_country_code :=
        lower(
            nullif(
                btrim(
                    p_country_code
                ),
                ''
            )
        );

    if v_country_code is null then
        raise exception
            'COUNTRY_CODE_REQUIRED';
    end if;

    if p_gold_price_per_gram is null
       or p_gold_price_per_gram <= 0
    then
        raise exception
            'INVALID_GOLD_PRICE_PER_GRAM';
    end if;

    /*
     * Confirm that the country is operational.
     */
    v_stage :=
        'validate operational country';

    perform 1
    from public.operational_country
        country_record
    where lower(
        btrim(
            country_record.country_code
        )
    ) =
        v_country_code

      and country_record.is_active =
          true
    limit 1;

    if not found then
        raise exception
            'OPERATIONAL_COUNTRY_NOT_ACTIVE';
    end if;

    /*
     * Prevent overlapping cron runs from detecting
     * positions for the same country simultaneously.
     */
    v_stage :=
        'lock country liquidation detection';

    perform pg_advisory_xact_lock(
        hashtext(
            format(
                'loan-liquidation-detection:%s',
                v_country_code
            )
        )
    );

    /*
     * Fetch the current fiscal period.
     */
    v_stage :=
        'fetch fiscal period';

    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Fetch the configured target LTV.
     */
    v_stage :=
        'fetch target ltv';

    select config_record.rate
    into v_target_ltv_percent
    from public.loan_config
        config_record
    where config_record.config_type::text =
              'loan_ltv'

      and config_record.is_active =
              true
    limit 1;

    if not found
       or v_target_ltv_percent is null
    then
        raise exception
            'ACTIVE_LOAN_LTV_CONFIG_NOT_FOUND';
    end if;

    /*
     * Fetch the configured liquidation threshold.
     */
    v_stage :=
        'fetch liquidation ltv';

    select config_record.rate
    into v_liquidation_ltv_percent
    from public.loan_config
        config_record
    where config_record.config_type::text =
              'liquidation_ltv'

      and config_record.is_active =
              true
    limit 1;

    if not found
       or v_liquidation_ltv_percent is null
    then
        raise exception
            'ACTIVE_LIQUIDATION_LTV_CONFIG_NOT_FOUND';
    end if;

    /*
     * Fetch the liquidation penalty rate.
     */
    v_stage :=
        'fetch liquidation penalty';

    select config_record.rate
    into v_penalty_rate_percent
    from public.loan_config
        config_record
    where config_record.config_type::text =
              'liquidation_penalty'

      and config_record.is_active =
              true
    limit 1;

    if not found
       or v_penalty_rate_percent is null
    then
        raise exception
            'ACTIVE_LIQUIDATION_PENALTY_CONFIG_NOT_FOUND';
    end if;

    /*
     * Validate configuration.
     */
    v_stage :=
        'validate liquidation configuration';

    if v_target_ltv_percent <= 0
       or v_target_ltv_percent >= 100
    then
        raise exception
            'INVALID_TARGET_LTV';
    end if;

    if v_liquidation_ltv_percent <=
       v_target_ltv_percent
       or v_liquidation_ltv_percent > 100
    then
        raise exception
            'INVALID_LIQUIDATION_LTV';
    end if;

    if v_penalty_rate_percent < 0
       or v_penalty_rate_percent >= 100
    then
        raise exception
            'INVALID_LIQUIDATION_PENALTY_RATE';
    end if;

    v_target_ltv :=
        v_target_ltv_percent / 100;

    v_penalty_rate :=
        v_penalty_rate_percent / 100;

    /*
     * Formula denominator:
     *
     * 1 - targetLtv × (1 + penaltyRate)
     */
    v_denominator :=
        1 -
        (
            v_target_ltv *
            (
                1 +
                v_penalty_rate
            )
        );

    if v_denominator <= 0 then
        raise exception
            'INVALID_PARTIAL_LIQUIDATION_CONFIGURATION';
    end if;

    /*
     * Aggregate active loan balances per user.
     */
    v_stage :=
        'detect unhealthy positions';

    for v_position in
        select
            loan_record.user_id,

            greatest(
                coalesce(
                    sum(
                        coalesce(
                            entry_record.debit_principal,
                            0
                        ) -
                        coalesce(
                            entry_record.credit_principal,
                            0
                        )
                    ),
                    0
                ),
                0
            )::numeric as total_principal,

            greatest(
                coalesce(
                    sum(
                        coalesce(
                            entry_record.debit_interest,
                            0
                        ) -
                        coalesce(
                            entry_record.credit_interest,
                            0
                        )
                    ),
                    0
                ),
                0
            )::numeric as total_interest,

            coalesce(
                collateral_record.locked_tokens,
                0
            )::numeric as locked_tokens

        from public.loan
            loan_record

        left join public.loan_entry
            entry_record
          on entry_record.loan_id =
             loan_record.id

        JOIN public.collateral AS collateral_record
          ON collateral_record.user_id = loan_record.user_id
         AND lower(btrim(collateral_record.country_code)) =
             v_country_code

        WHERE loan_record.status =
              'active'::public."LoanStatus"
          AND lower(btrim(loan_record.country_code)) =
              v_country_code
              
        group by
            loan_record.user_id,
            collateral_record.locked_tokens

        order by
            loan_record.user_id
    loop
        v_evaluated :=
            v_evaluated + 1;

        v_total_principal :=
            trunc(
                coalesce(
                    v_position.total_principal,
                    0
                ),
                6
            );

        v_total_interest :=
            trunc(
                coalesce(
                    v_position.total_interest,
                    0
                ),
                6
            );

        v_total_debt :=
            trunc(
                v_total_principal +
                v_total_interest,
                6
            );

        v_locked_tokens :=
            trunc(
                coalesce(
                    v_position.locked_tokens,
                    0
                ),
                6
            );

        if v_total_debt <= 0
           or v_locked_tokens <= 0
        then
            v_skipped :=
                v_skipped + 1;

            continue;
        end if;

        v_collateral_value :=
            trunc(
                v_locked_tokens *
                p_gold_price_per_gram,
                6
            );

        if v_collateral_value <= 0 then
            v_skipped :=
                v_skipped + 1;

            continue;
        end if;

        v_current_ltv :=
            trunc(
                (
                    v_total_debt /
                    v_collateral_value
                ) *
                100,
                6
            );

        if v_current_ltv <
           v_liquidation_ltv_percent
        then
            v_skipped :=
                v_skipped + 1;

            continue;
        end if;

        /*
         * Do not create another liquidation job while
         * an earlier job for the position is unfinished.
         *
         * Failed jobs remain underway because they must
         * be retried instead of producing a new transfer.
         */
        perform 1
        from public.liquidation_job
            job_record
        where job_record.user_id =
                  v_position.user_id

          and lower(
              btrim(
                  job_record.country_code
              )
          ) =
                  v_country_code

          and job_record.status::text not in (
              'completed',
              'cancelled'
          )
        limit 1;

        if found then
            v_already_underway :=
                v_already_underway + 1;

            continue;
        end if;

        /*
         * Calculate the debt repayment required to leave
         * the remaining position at the target LTV:
         *
         * repayment =
         *   (
         *     debt -
         *     targetLtv × collateralValue
         *   )
         *   /
         *   (
         *     1 -
         *     targetLtv × (1 + penaltyRate)
         *   )
         */
        v_debt_repayment :=
            trunc(
                (
                    v_total_debt -
                    (
                        v_target_ltv *
                        v_collateral_value
                    )
                ) /
                v_denominator,
                6
            );

        if v_debt_repayment <= 0 then
            v_skipped :=
                v_skipped + 1;

            continue;
        end if;

        /*
         * Debt repayment cannot exceed the outstanding
         * principal plus interest.
         */
        v_debt_repayment :=
            least(
                v_debt_repayment,
                v_total_debt
            );

        v_penalty_amount :=
            trunc(
                v_debt_repayment *
                v_penalty_rate,
                6
            );

        v_total_proceeds :=
            trunc(
                v_debt_repayment +
                v_penalty_amount,
                6
            );

        /*
         * If the available collateral cannot cover the
         * calculated proceeds, use all available
         * collateral and recalculate the repayment and
         * penalty split.
         */
        if v_total_proceeds >
           v_collateral_value
        then
            v_debt_repayment :=
                trunc(
                    least(
                        v_total_debt,
                        v_collateral_value /
                        (
                            1 +
                            v_penalty_rate
                        )
                    ),
                    6
                );

            v_penalty_amount :=
                trunc(
                    v_debt_repayment *
                    v_penalty_rate,
                    6
                );

            v_total_proceeds :=
                trunc(
                    v_debt_repayment +
                    v_penalty_amount,
                    6
                );
        end if;

        v_collateral_required :=
            trunc(
                v_total_proceeds /
                p_gold_price_per_gram,
                6
            );

        v_collateral_required :=
            least(
                v_collateral_required,
                v_locked_tokens
            );

        /*
         * Select the active customer GOLD wallet with the
         * largest balance on a supported active blockchain.
         *
         * A blockchain code provides a deterministic
         * tie-breaker when balances are equal.
         */
        v_stage := 'select liquidation blockchain';

        v_blockchain_code := NULL;
        v_blockchain_gold_balance := NULL;

        SELECT
            w.blockchain_code,
            trunc(w.balance, 6)
        INTO
            v_blockchain_code,
            v_blockchain_gold_balance
        FROM public.wallet AS w
        JOIN public.supported_blockchain AS b
          ON b.code = w.blockchain_code
         AND b.is_active = true
        WHERE w.user_id = v_position.user_id
          AND lower(btrim(w.country_code)) = v_country_code
          AND w.currency_code = 'gold'
          AND w.owner_type =
              'customer'::public."WalletOwnerType"
          AND w.is_active = true
          AND w.balance > 0
          AND w.balance::text NOT IN (
              'NaN', 'Infinity', '-Infinity'
          )
          AND EXISTS (
              SELECT 1
              FROM public.supported_blockchain_network AS n
              WHERE n.blockchain_id = b.id
                AND n.is_active = true
          )
        ORDER BY
            w.balance DESC,
            w.blockchain_code ASC
        LIMIT 1;

        IF NOT FOUND
           OR coalesce(v_blockchain_gold_balance, 0) <= 0
        THEN
            v_skipped := v_skipped + 1;
            CONTINUE;
        END IF;

        /*
         * Liquidate from one blockchain only.
         *
         * If its balance covers the calculated quantity,
         * retain the existing calculation.
         *
         * Otherwise use that blockchain's balance and
         * recalculate repayment and penalty.
         */
        IF v_collateral_required > v_blockchain_gold_balance THEN
            v_stage := 'recalculate blockchain-limited liquidation';

            v_collateral_required :=
                least(
                    v_blockchain_gold_balance,
                    v_locked_tokens
                );

            v_capped_sale_value :=
                trunc(
                    v_collateral_required *
                    p_gold_price_per_gram,
                    6
                );

            /*
             * Preserve the existing penalty rule:
             *
             * proceeds = repayment + repayment × penalty rate
             */
            v_debt_repayment :=
                trunc(
                    least(
                        v_total_debt,
                        v_capped_sale_value /
                        (1 + v_penalty_rate)
                    ),
                    6
                );

            v_penalty_amount :=
                trunc(
                    v_debt_repayment * v_penalty_rate,
                    6
                );

            v_total_proceeds :=
                trunc(
                    v_debt_repayment + v_penalty_amount,
                    6
                );
        END IF;

        if v_debt_repayment <= 0
           or v_total_proceeds <= 0
           or v_collateral_required <= 0
        then
            v_skipped :=
                v_skipped + 1;

            continue;
        end if;

        /*
         * Store the immutable liquidation calculation.
         *
         * total_required is now the total collateral-sale
         * proceeds:
         *
         * debt repayment + liquidation penalty.
         */
        insert into public.liquidation_job (
            user_id,
            fiscal_year,
            period,

            total_principal,
            total_interest,
            total_debt,

            repayment_required,
            penalty_amount,
            total_required,

            collateral_value,
            collateral_required,

            gold_price,
            target_ltv,
            liquidation_ltv,
            penalty_rate,

            status,
            country_code,
            blockchain_code
        )
        values (
            v_position.user_id,
            v_fiscal_year,
            v_period,

            v_total_principal,
            v_total_interest,
            v_total_debt,

            v_debt_repayment,
            v_penalty_amount,
            v_total_proceeds,

            v_collateral_value,
            v_collateral_required,

            p_gold_price_per_gram,
            v_target_ltv_percent,
            v_liquidation_ltv_percent,
            v_penalty_rate_percent,

            'pending'::public."LiquidationJobStatus",
            v_country_code,
            v_blockchain_code
        );

        v_detected :=
            v_detected + 1;
    end loop;

    return jsonb_build_object(
        'success',
        true,

        'country_code',
        v_country_code,

        'fiscal_year',
        v_fiscal_year,

        'period',
        v_period,

        'gold_price',
        trim_scale(
            p_gold_price_per_gram
        )::text,

        'evaluated',
        v_evaluated,

        'detected',
        v_detected,

        'already_underway',
        v_already_underway,

        'skipped',
        v_skipped
    );

exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;

        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'LIQUIDATION_DETECTION_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                concat_ws(
                    E'\n',
                    nullif(
                        v_error_detail,
                        ''
                    ),
                    nullif(
                        v_error_context,
                        ''
                    )
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    'Check the liquidation detection stage reported in the error'
                );
end;
$$;
ALTER FUNCTION "public"."detect_unhealthy_loan_positions"("p_country_code" "text", "p_gold_price_per_gram" numeric) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."enforce_transaction_limit"("p_user_id" "text", "p_fiscal_year" integer, "p_period" integer, "p_transaction_type" "public"."TransactionType", "p_currency_code" "text", "p_amount" numeric, "p_country_code" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_limit public.transaction_limit%rowtype;
    v_kyc_status public."KycStatus";

    v_today_start
        timestamp with time zone;

    v_total_today numeric := 0;
    v_month_start timestamp with time zone;
    v_next_month_start timestamp with time zone;
    v_total_month numeric := 0;
begin
    if p_user_id is null
       or btrim(p_user_id) = ''
    then
        raise exception
            'USER_ID_IS_REQUIRED';
    end if;

    if p_currency_code is null
       or btrim(p_currency_code) = ''
    then
        raise exception
            'CURRENCY_IS_REQUIRED';
    end if;

    if p_country_code is null
       or btrim(p_country_code) = ''
    then
        raise exception
            'COUNTRY_IS_REQUIRED';
    end if;

    if p_amount is null
       or p_amount::text IN ('NaN','Infinity','-Infinity')
       or p_amount <= 0
    then
        raise exception
            'INVALID_AMOUNT';
    end if;

    if p_fiscal_year is null then
        raise exception
            'FISCAL_YEAR_IS_REQUIRED';
    end if;

    if p_period is null then
        raise exception
            'PERIOD_IS_REQUIRED';
    end if;

    -- Only current KYC determines the limit. Historical verification
    -- cannot upgrade a newer pending/rejected submission.
    select k.kyc_status into v_kyc_status
    from public.user_kyc k
    where k.user_id=p_user_id and k.is_current=true;
    v_kyc_status := coalesce(v_kyc_status,'pending'::public."KycStatus");

    /*
     * Fetch the active configuration for transaction type, country,
     * currency AND current KYC status.
     */
    select transaction_limit_record.*
    into v_limit
    from public.transaction_limit
        transaction_limit_record
    where transaction_limit_record.transaction_type =
          p_transaction_type
      and lower(
          transaction_limit_record.country_code
      ) = lower(
          btrim(p_country_code)
      )
      and lower(
          transaction_limit_record.currency_code
      ) = lower(
          btrim(p_currency_code)
      )
      and transaction_limit_record.is_active = true
      and transaction_limit_record.kyc_status = v_kyc_status;

    if not found then
        -- Preserve the existing no-limits behavior only when there are no
        -- active limits at all for this transaction/country/currency.
        -- A missing KYC tier must not bypass configured limits.
        if exists (
            select 1 from public.transaction_limit t
            where t.transaction_type=p_transaction_type
              and lower(t.country_code)=lower(btrim(p_country_code))
              and lower(t.currency_code)=lower(btrim(p_currency_code))
              and t.is_active=true
        ) then
            raise exception 'TRANSACTION_LIMIT_NOT_CONFIGURED_FOR_KYC_STATUS'
                using detail=format('kyc_status=%s',v_kyc_status::text);
        end if;
        return;
    end if;

    /*
     * Minimum transaction amount.
     */
    if v_limit.min_amount is not null
       and p_amount < v_limit.min_amount
    then
        raise exception
            'AMOUNT_BELOW_MINIMUM_TRANSACTION_AMOUNT';
    end if;

    /*
     * Maximum amount per transaction.
     */
    if v_limit.max_amount is not null
       and p_amount > v_limit.max_amount
    then
        raise exception
            'AMOUNT_EXCEEDS_MAXIMUM_TRANSACTION_AMOUNT';
    end if;

    /*
     * Daily cumulative limit.
     */
    if v_limit.daily_limit is not null then
        v_today_start :=
            date_trunc(
                'day',
                now() at time zone 'UTC'
            ) at time zone 'UTC';

        select coalesce(
            sum(
                coalesce(
                    wallet_entry_record.debit,
                    0
                )
            ),
            0
        )
        into v_total_today
        from public.wallet_entry
            wallet_entry_record
        join public.wallet
            wallet_record
          on wallet_record.id =
             wallet_entry_record.wallet_id
        where wallet_record.user_id =
              p_user_id
          and lower(
              wallet_record.currency_code
          ) = lower(
              btrim(p_currency_code)
          )
          and lower(
              wallet_record.country_code
          ) = lower(
              btrim(p_country_code)
          )
          and wallet_entry_record.transaction_type =
              p_transaction_type
          and wallet_entry_record.created_at >=
              v_today_start;

        if (
            v_total_today +
            p_amount
        ) > v_limit.daily_limit
        then
            raise exception
                'DAILY_TRANSACTION_LIMIT_EXCEEDED';
        end if;
    end if;

    /*
     * Monthly cumulative limit: UTC calendar month, with the same
     * transaction/country/currency/user debit scope as the daily check.
     * All matching wallets/chains contribute to one monthly total.
     */
    if v_limit.monthly_limit is not null then
        v_month_start := date_trunc('month',now() at time zone 'UTC')
            at time zone 'UTC';
        v_next_month_start :=
            (date_trunc('month',now() at time zone 'UTC') + interval '1 month')
            at time zone 'UTC';

        select coalesce(sum(coalesce(e.debit,0)),0)
        into v_total_month
        from public.wallet_entry e
        join public.wallet w on w.id=e.wallet_id
        where w.user_id=p_user_id
          and lower(w.currency_code)=lower(btrim(p_currency_code))
          and lower(w.country_code)=lower(btrim(p_country_code))
          and e.transaction_type=p_transaction_type
          and e.created_at>=v_month_start
          and e.created_at<v_next_month_start;

        if v_total_month+p_amount>v_limit.monthly_limit then
            raise exception 'MONTHLY_TRANSACTION_LIMIT_EXCEEDED';
        end if;
    end if;
end;
$$;
ALTER FUNCTION "public"."enforce_transaction_limit"("p_user_id" "text", "p_fiscal_year" integer, "p_period" integer, "p_transaction_type" "public"."TransactionType", "p_currency_code" "text", "p_amount" numeric, "p_country_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."evaluate_badges_after_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
    perform public.evaluate_user_badges(new.user_id, new.id);
    return new;
exception
    when others then
        raise warning 'BADGE_EVALUATION_FAILED event_id=% user_id=% error=%',
            new.id,
            new.user_id,
            sqlerrm;
        return new;
end;
$$;
ALTER FUNCTION "public"."evaluate_badges_after_event"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."evaluate_financial_badges"("p_user_id" "text", "p_country_code" "text", "p_fiscal_year" integer, "p_period" integer) RETURNS TABLE("badge_id" "uuid", "badge_code" "text", "badge_name" "text", "metric" "public"."financial_badge_metric", "achieved_value_usd" numeric, "newly_awarded" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_badge record;

    v_spending_usd numeric(20, 2) := 0;
    v_saving_usd numeric(20, 2) := 0;
    v_investment_usd numeric(20, 2) := 0;
    v_borrowing_usd numeric(20, 2) := 0;

    v_metric_value numeric(20, 2) := 0;
    v_inserted boolean := false;
BEGIN

    /*
     * SHOPPER
     */
    SELECT
        COALESCE(
            SUM(e.amount_usd),
            0
        )
    INTO
        v_spending_usd
    FROM public.financial_pot_event AS e
    WHERE e.user_id = p_user_id
      AND e.activity_type =
          'spending'::public.financial_activity_type;


    /*
     * INVESTOR
     */
    SELECT
        COALESCE(
            SUM(e.amount_usd),
            0
        )
    INTO
        v_investment_usd
    FROM public.financial_pot_event AS e
    WHERE e.user_id = p_user_id
      AND e.activity_type =
          'investment_buy'::public.financial_activity_type;


    /*
     * BORROWER
     */
    SELECT
        COALESCE(
            SUM(e.amount_usd),
            0
        )
    INTO
        v_borrowing_usd
    FROM public.financial_pot_event AS e
    WHERE e.user_id = p_user_id
      AND e.activity_type =
          'loan_disbursement'::public.financial_activity_type;


    /*
     * SAVER
     *
     * Use all-currency period behaviour rows only.
     */
    SELECT
        COALESCE(
            SUM(fb.saving_amount_usd),
            0
        )
    INTO
        v_saving_usd
    FROM public.financial_behavior AS fb
    WHERE fb.user_id = p_user_id
      AND fb.scope =
          'period'::public.financial_behavior_scope
      AND fb.currency_code IS NULL;


    /*
     * Evaluate all active badge thresholds.
     */
    FOR v_badge IN

        SELECT
            b.id,
            b.code,
            b.name,
            b.metric,
            b.level,
            b.threshold_usd
        FROM public.financial_badge AS b
        WHERE b.is_active = true
        ORDER BY
            b.metric,
            b.level

    LOOP

        /*
         * Determine the lifetime value for this
         * badge metric.
         */
        CASE v_badge.metric

            WHEN 'spending'::public.financial_badge_metric THEN
                v_metric_value :=
                    v_spending_usd;

            WHEN 'saving'::public.financial_badge_metric THEN
                v_metric_value :=
                    v_saving_usd;

            WHEN 'investment'::public.financial_badge_metric THEN
                v_metric_value :=
                    v_investment_usd;

            WHEN 'borrowing'::public.financial_badge_metric THEN
                v_metric_value :=
                    v_borrowing_usd;

            ELSE
                v_metric_value := 0;

        END CASE;


        /*
         * Badge threshold not reached.
         */
        IF v_metric_value < v_badge.threshold_usd THEN
            CONTINUE;
        END IF;


        /*
         * Award badge.
         *
         * IMPORTANT:
         *
         * Do not use:
         *
         * ON CONFLICT (user_id, badge_id)
         *
         * because badge_id is also an output variable
         * of this PL/pgSQL function.
         *
         * We check explicitly instead.
         */
        IF NOT EXISTS (
            SELECT
                1
            FROM public.user_financial_badge AS ufb
            WHERE ufb.user_id = p_user_id
              AND ufb.badge_id = v_badge.id
        ) THEN

            INSERT INTO public.user_financial_badge (
                user_id,
                badge_id,
                achieved_value_usd,
                fiscal_year,
                period,
                achieved_at,
                created_at
            )
            VALUES (
                p_user_id,
                v_badge.id,
                v_metric_value,
                p_fiscal_year,
                p_period,
                now(),
                now()
            );

            v_inserted := true;

        ELSE

            v_inserted := false;

        END IF;


        /*
         * Populate return row.
         */
        badge_id :=
            v_badge.id;

        badge_code :=
            v_badge.code;

        badge_name :=
            v_badge.name;

        metric :=
            v_badge.metric;

        achieved_value_usd :=
            v_metric_value;

        newly_awarded :=
            v_inserted;

        RETURN NEXT;

    END LOOP;

    RETURN;

END;
$$;
ALTER FUNCTION "public"."evaluate_financial_badges"("p_user_id" "text", "p_country_code" "text", "p_fiscal_year" integer, "p_period" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."evaluate_user_badges"("p_user_id" "text", "p_event_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user_id text;
    v_event_id text;
    v_badge public.loyalty_badge%rowtype;
    v_account public.loyalty_account%rowtype;
    v_current_value bigint;
    v_awarded public.user_badge%rowtype;
    v_evaluated integer := 0;
    v_newly_awarded integer := 0;
    v_badges jsonb := '[]'::jsonb;
begin
    if coalesce(auth.role(), '') <> 'service_role' then
        raise exception using
            errcode = '42501',
            message = 'SERVICE_ROLE_REQUIRED';
    end if;

    v_user_id := nullif(btrim(p_user_id), '');
    v_event_id := nullif(btrim(p_event_id), '');

    if v_user_id is null then
        raise exception 'BADGE_USER_ID_REQUIRED';
    end if;

    perform pg_advisory_xact_lock(
        hashtext('loyalty-badge:' || v_user_id)
    );

    select account_record.*
    into v_account
    from public.loyalty_account account_record
    where account_record.user_id = v_user_id;

    if not found then
        raise exception 'LOYALTY_ACCOUNT_NOT_FOUND';
    end if;

    for v_badge in
        select badge_record.*
        from public.loyalty_badge badge_record
        where badge_record.is_active = true
          and (
              badge_record.valid_from is null
              or badge_record.valid_from <= now()
          )
          and (
              badge_record.valid_until is null
              or badge_record.valid_until > now()
          )
        order by badge_record.sort_order, badge_record.id
    loop
        v_evaluated := v_evaluated + 1;

        v_current_value :=
            case v_badge.criteria_type
                when 'event_count' then (
                    select count(*)::bigint
                    from public.gamification_event event_record
                    where event_record.user_id = v_user_id
                      and event_record.event_type = v_badge.event_type
                      and event_record.status =
                          'completed'::public."GamificationEventStatus"
                )
                when 'lifetime_points' then
                    v_account.lifetime_earned_points
                when 'tier_points' then
                    v_account.tier_points
                when 'available_points' then
                    greatest(v_account.available_points, 0)
            end;

        v_current_value := greatest(coalesce(v_current_value, 0), 0);

        insert into public.loyalty_badge_progress (
            user_id,
            badge_id,
            current_value,
            target_value,
            completed_at
        )
        values (
            v_user_id,
            v_badge.id,
            v_current_value,
            v_badge.target_value,
            case
                when v_current_value >= v_badge.target_value then now()
                else null
            end
        )
        on conflict (user_id, badge_id) do update
        set
            current_value = excluded.current_value,
            target_value = excluded.target_value,
            completed_at = coalesce(
                public.loyalty_badge_progress.completed_at,
                excluded.completed_at
            );

        if v_current_value < v_badge.target_value then
            continue;
        end if;

        v_awarded := null;

        insert into public.user_badge (
            user_id,
            badge_id,
            awarded_event_id,
            metadata
        )
        values (
            v_user_id,
            v_badge.id,
            v_event_id,
            jsonb_build_object(
                'current_value', v_current_value,
                'target_value', v_badge.target_value
            )
        )
        on conflict (user_id, badge_id) do nothing
        returning * into v_awarded;

        if v_awarded.id is null then
            continue;
        end if;

        v_newly_awarded := v_newly_awarded + 1;
        v_badges := v_badges || jsonb_build_array(
            jsonb_build_object(
                'badge_code', v_badge.badge_code,
                'name', v_badge.name,
                'awarded_at', v_awarded.awarded_at
            )
        );

        /*
         * event_id is intentionally null here. The existing notification
         * uniqueness contract allows one notification of each type per event,
         * while one event may unlock more than one badge. user_badge provides
         * the durable idempotency contract for badge notifications.
         */
        insert into public.gamification_notification (
            user_id,
            event_id,
            notification_type,
            points,
            title,
            subtitle,
            display_priority,
            payload
        )
        values (
            v_user_id,
            null,
            'badge_awarded'::public."GamificationNotificationType",
            0,
            'Badge unlocked',
            v_badge.name,
            20,
            jsonb_build_object(
                'user_badge_id', v_awarded.id,
                'badge_id', v_badge.id,
                'badge_code', v_badge.badge_code,
                'name', v_badge.name,
                'description', v_badge.description,
                'category', v_badge.category,
                'icon_key', v_badge.icon_key,
                'source_event_id', v_event_id
            )
        );
    end loop;

    return jsonb_build_object(
        'success', true,
        'user_id', v_user_id,
        'evaluated', v_evaluated,
        'newly_awarded', v_newly_awarded,
        'badges', v_badges
    );
end;
$$;
ALTER FUNCTION "public"."evaluate_user_badges"("p_user_id" "text", "p_event_id" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."execute_additional_collateral"("p_user_id" "text", "p_requested_collateral" "text", "p_token_balance" "text", "p_reference" "text") RETURNS TABLE("success" boolean, "collateral_required" boolean, "requested_collateral" "text", "collateral_added" "text", "unused_collateral" "text", "remaining_required_collateral" "text", "previous_locked_collateral" "text", "new_locked_collateral" "text", "loans_adjusted" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_stage text :=
        'initialization';

    v_user
        public.users%rowtype;

    v_collateral
        public.collateral%rowtype;

    v_loan
        public.loan%rowtype;

    v_reference text;

    /*
     * Maximum amount authorised by the user for this
     * collateral top-up.
     */
    v_requested_collateral numeric;

    /*
     * Current blockchain gold balance supplied by the
     * authenticated Edge Function.
     */
    v_total_tokens numeric;

    /*
     * Gold currently available outside the locked pool.
     */
    v_available_tokens numeric := 0;

    /*
     * Current USD gold price.
     */
    v_gold_price numeric := 0;

    /*
     * Per-loan outstanding exposure.
     */
    v_principal numeric := 0;
    v_interest numeric := 0;
    v_exposure numeric := 0;

    /*
     * Target LTV configured on each loan.
     *
     * Stored as:
     *
     * 60.00
     *
     * and converted to:
     *
     * 0.60
     *
     * during the collateral calculation.
     */
    v_target_ltv numeric := 0;

    /*
     * Current required collateral for one loan at:
     *
     * - current outstanding exposure;
     * - current gold price;
     * - configured target LTV.
     */
    v_target_collateral numeric := 0;

    /*
     * Total gold currently required to cover every
     * active loan at its target LTV.
     *
     * IMPORTANT:
     *
     * This is the required SIZE OF THE POOL.
     *
     * It is not the additional collateral shortage.
     */
    v_total_required_pool numeric := 0;

    /*
     * Additional gold required before and after this
     * operation.
     */
    v_collateral_shortage numeric := 0;
    v_remaining_required numeric := 0;

    /*
     * Actual collateral added by this operation.
     *
     * This can be less than the amount authorised by
     * the user when the complete authorised amount is
     * not required.
     */
    v_collateral_added numeric := 0;

    /*
     * Consolidated collateral balances.
     */
    v_previous_locked numeric := 0;
    v_new_locked numeric := 0;

    /*
     * Allocation of the actual consolidated pool across
     * individual active loans.
     */
    v_remaining_pool numeric := 0;
    v_allocation numeric := 0;

    /*
     * When reallocating the pool, distinguish gold that
     * already existed in the pool from NEW gold added by
     * this operation.
     *
     * Only the new portion creates collateral_entry rows.
     */
    v_existing_pool_remaining numeric := 0;
    v_new_gold_remaining numeric := 0;
    v_existing_allocation numeric := 0;
    v_new_allocation numeric := 0;

    /*
     * Existing loan.collateral value before synchronising
     * the current allocation.
     */
    v_previous_loan_allocation numeric := 0;

    v_loans_adjusted integer := 0;
    v_posted_debits numeric := 0;
    v_liquidation_price numeric := 0;

    /*
     * Snapshot period.
     */
    v_fiscal_year integer;
    v_period integer;

    /*
     * Error diagnostics.
     */
    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;

begin
    /*
     * ==========================================================
     * AUTHENTICATION / AUTHORIZATION
     * ==========================================================
     */
    v_stage :=
        'authorize customer';

    if coalesce(auth.role(), '') <> 'service_role' then
        raise exception using errcode='42501', message='SERVICE_ROLE_REQUIRED';
    end if;
    if nullif(btrim(p_user_id), '') is null then
        raise exception 'USER_ID_REQUIRED';
    end if;


    if not public.user_has_role(
        p_user_id,
        array[
            'customer',
            'agent',
            'vendor'
        ]::text[]
    ) then
        raise exception using
            errcode =
                '42501',
            message =
                'FORBIDDEN';
    end if;


    select
        user_record.*
    into
        v_user
    from public.users
        user_record
    where user_record.id =
          p_user_id
    limit 1;


    if not found then
        raise exception
            'USER_NOT_FOUND';
    end if;


    if v_user.status is distinct from
       'active'::public."UserStatus"
    then
        raise exception
            'USER_NOT_ACTIVE';
    end if;


    if v_user.country_code is null
       or btrim(
           v_user.country_code
       ) = ''
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;


    /*
     * ==========================================================
     * PARSE REQUESTED COLLATERAL
     * ==========================================================
     */
    v_stage :=
        'parse requested collateral';


    begin
        v_requested_collateral :=
            nullif(
                btrim(
                    p_requested_collateral
                ),
                ''
            )::numeric;

    exception
        when invalid_text_representation
          or numeric_value_out_of_range
        then
            raise exception
                'INVALID_COLLATERAL_AMOUNT';
    end;


    if v_requested_collateral is null
       or v_requested_collateral::text in ('NaN', 'Infinity', '-Infinity')
       or v_requested_collateral <= 0
    then
        raise exception
            'INVALID_COLLATERAL_AMOUNT';
    end if;


    /*
     * collateral_entry supports six decimal places.
     *
     * Do not silently modify the quantity authorised by
     * the user's signed request.
     */
    if v_requested_collateral <>
       trunc(
           v_requested_collateral,
           6
       )
    then
        raise exception
            'INVALID_COLLATERAL_PRECISION';
    end if;


    /*
     * ==========================================================
     * PARSE BLOCKCHAIN TOKEN BALANCE
     * ==========================================================
     */
    v_stage :=
        'parse token balance';


    begin
        v_total_tokens :=
            coalesce(
                nullif(
                    btrim(
                        p_token_balance
                    ),
                    ''
                ),
                '0'
            )::numeric;

    exception
        when invalid_text_representation
          or numeric_value_out_of_range
        then
            raise exception
                'INVALID_BLOCKCHAIN_TOKEN_BALANCE';
    end;


    if v_total_tokens::text in ('NaN', 'Infinity', '-Infinity')
       or v_total_tokens < 0 then
        raise exception
            'INVALID_BLOCKCHAIN_TOKEN_BALANCE';
    end if;


    /*
     * ==========================================================
     * PARSE REFERENCE
     * ==========================================================
     */
    v_stage :=
        'parse reference';


    v_reference :=
        nullif(
            btrim(
                p_reference
            ),
            ''
        );


    if v_reference is null then
        raise exception
            'REFERENCE_REQUIRED';
    end if;


    /*
     * ==========================================================
     * REPLAY PROTECTION
     * ==========================================================
     */
    v_stage :=
        'lock collateral reference';


    perform
        pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(
                v_reference,
                0
            )
        );


    perform 1
    from public.collateral_entry
        collateral_entry_record
    join public.loan
        loan_record
      on loan_record.id =
         collateral_entry_record.loan_id
    where collateral_entry_record.reference =
          v_reference
      and loan_record.user_id =
          v_user.id
    limit 1;


    if found then
        raise exception using
            errcode =
                '23505',
            message =
                'TRANSACTION_REPLAY';
    end if;


    /*
     * ==========================================================
     * ENSURE CONSOLIDATED COLLATERAL ROW EXISTS
     * ==========================================================
     */
    v_stage := 'lock loan position';
    perform pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('loan-position:' || v_user.id, 0)
    );
    if exists (
        select 1 from public.liquidation_job as j
        where j.user_id = v_user.id
          and j.status::text not in ('completed', 'cancelled')
    ) then
        raise exception 'LOAN_POSITION_LIQUIDATION_IN_PROGRESS';
    end if;

    v_stage :=
        'create collateral row';


    insert into public.collateral (
        user_id,
        locked_tokens,
        country_code
    )
    values (
        v_user.id,
        0,
        v_user.country_code
    )
    on conflict (
        user_id
    )
    do nothing;


    /*
     * ==========================================================
     * LOCK CONSOLIDATED COLLATERAL
     * ==========================================================
     *
     * collateral.locked_tokens is the authoritative quantity
     * of gold currently locked for the user's loan portfolio.
     * ==========================================================
     */
    v_stage :=
        'lock collateral row';


    select
        collateral_record.*
    into
        v_collateral
    from public.collateral
        collateral_record
    where collateral_record.user_id =
          v_user.id
    for update;


    if not found then
        raise exception
            'COLLATERAL_NOT_FOUND';
    end if;


    if v_collateral.country_code
       is distinct from
       v_user.country_code
    then
        raise exception
            'COLLATERAL_COUNTRY_MISMATCH';
    end if;


    v_previous_locked := v_collateral.locked_tokens;
    if v_previous_locked is null
       or v_previous_locked::text in ('NaN', 'Infinity', '-Infinity')
       or v_previous_locked < 0
       or v_previous_locked <> trunc(v_previous_locked, 6)
    then
        raise exception 'INVALID_LOCKED_COLLATERAL';
    end if;

    /*
     * ==========================================================
     * LOCK ACTIVE LOANS
     * ==========================================================
     *
     * The portfolio must remain stable while:
     *
     * - exposure is calculated;
     * - pooled collateral is increased;
     * - the pool is redistributed across loans.
     *
     * Oldest loan first is also the allocation order.
     * ==========================================================
     */
    v_stage :=
        'lock active loans';


    perform
        loan_record.id
    from public.loan
        loan_record
    where loan_record.user_id =
          v_user.id
      and loan_record.status =
          'active'::public."LoanStatus"
    order by
        loan_record.created_at asc,
        loan_record.id asc
    for update;


    /*
     * ==========================================================
     * FETCH CURRENT GOLD PRICE
     * ==========================================================
     */
    v_stage :=
        'fetch gold price';


    select
        coalesce(
            rate_record.rate_to_usd,
            0
        )
    into
        v_gold_price
    from public.current_rates
        rate_record
    where lower(
        rate_record.code
    ) = 'gold'
    limit 1;


    v_gold_price :=
        coalesce(
            v_gold_price,
            0
        );


    if v_gold_price is null
       or v_gold_price::text in ('NaN', 'Infinity', '-Infinity')
       or v_gold_price <= 0 then
        raise exception
            'INVALID_GOLD_RATE';
    end if;


    /*
     * ==========================================================
     * CALCULATE REQUIRED COLLATERAL POOL
     * ==========================================================
     *
     * The collateral model is pooled.
     *
     * Therefore loan.collateral MUST NOT be subtracted here.
     *
     * For every active loan:
     *
     * exposure =
     *     outstanding principal
     *     +
     *     outstanding interest
     *
     * required collateral USD =
     *     exposure /
     *     target LTV
     *
     * required collateral gold =
     *     required collateral USD /
     *     current gold price
     *
     * The required pool is the SUM of the current requirements
     * of all active loans.
     *
     * loan.collateral is only the current DISTRIBUTION of that
     * shared pool across individual loans.
     * ==========================================================
     */
    v_stage :=
        'calculate required collateral pool';


    v_total_required_pool := 0;


    for v_loan in
        select
            loan_record.*
        from public.loan
            loan_record
        where loan_record.user_id =
              v_user.id
          and loan_record.status =
              'active'::public."LoanStatus"
        order by
            loan_record.created_at asc,
            loan_record.id asc
    loop
        select
            greatest(
                coalesce(
                    sum(
                        entry_record.debit_principal
                    ),
                    0
                ) -
                coalesce(
                    sum(
                        entry_record.credit_principal
                    ),
                    0
                ),
                0
            ),

            greatest(
                coalesce(
                    sum(
                        entry_record.debit_interest
                    ),
                    0
                ) -
                coalesce(
                    sum(
                        entry_record.credit_interest
                    ),
                    0
                ),
                0
            )
        into
            v_principal,
            v_interest
        from public.loan_entry
            entry_record
        where entry_record.loan_id =
              v_loan.id;


        if v_loan.country_code is distinct from v_user.country_code
           or lower(btrim(v_loan.currency_code)) is distinct from 'usd'
        then
            raise exception 'LOAN_PORTFOLIO_CONTEXT_MISMATCH';
        end if;
        if v_principal::text in ('NaN', 'Infinity', '-Infinity')
           or v_interest::text in ('NaN', 'Infinity', '-Infinity')
        then
            raise exception 'INVALID_LOAN_BALANCE';
        end if;

        v_exposure :=
            v_principal +
            v_interest;


        if v_exposure <= 0 then
            continue;
        end if;


        v_target_ltv :=
            coalesce(
                v_loan.max_ltv_percent,
                0
            );


        if v_target_ltv::text in ('NaN', 'Infinity', '-Infinity')
           or v_target_ltv <= 0
           or v_target_ltv >= 100
        then
            raise exception
                'INVALID_LOAN_LTV_CONFIGURATION';
        end if;


        /*
         * Example:
         *
         * max_ltv_percent = 60.00
         *
         * target LTV =
         *
         * 60.00 / 100
         * =
         * 0.60
         */
        v_target_collateral := ceil(
            v_exposure * 100 / (v_target_ltv * v_gold_price) * 1000000
        ) / 1000000;


        v_total_required_pool :=
            v_total_required_pool +
            v_target_collateral;
    end loop;


    /*
     * Keep the portfolio requirement itself at six decimals,
     * matching the sum of its individual loan allocations.
     */
    v_total_required_pool :=
        round(
            v_total_required_pool,
            6
        );


    /*
     * ==========================================================
     * CALCULATE CURRENT POOL SHORTAGE
     * ==========================================================
     *
     * This is the fundamental pooled-collateral calculation:
     *
     * shortage =
     *
     *     current collateral required by all active loans
     *
     *     MINUS
     *
     *     actual consolidated gold currently locked
     * ==========================================================
     */
    v_collateral_shortage :=
        greatest(
            v_total_required_pool -
            v_previous_locked,
            0
        );


    /*
     * ==========================================================
     * NOTHING NEEDS TO BE ADDED
     * ==========================================================
     *
     * The actual pooled collateral is already sufficient to
     * cover all current active loan exposure at the configured
     * target LTVs.
     *
     * Do not lock additional gold merely because the user
     * authorised an amount.
     * ==========================================================
     */
    if v_collateral_shortage <= 0 then
        return query
        select
            true,

            false,

            to_char(
                v_requested_collateral,
                'FM999999999999999999999999990.000000'
            ),

            '0.000000'::text,

            to_char(
                v_requested_collateral,
                'FM999999999999999999999999990.000000'
            ),

            '0.000000'::text,

            to_char(
                round(
                    v_previous_locked,
                    6
                ),
                'FM999999999999999999999999990.000000'
            ),

            to_char(
                round(
                    v_previous_locked,
                    6
                ),
                'FM999999999999999999999999990.000000'
            ),

            0;

        return;
    end if;


    /*
     * ==========================================================
     * DETERMINE ACTUAL GOLD TO ADD
     * ==========================================================
     *
     * The signed requested amount is a MAXIMUM authorization.
     *
     * Example:
     *
     * requested = 0.100000
     * shortage  = 0.050000
     *
     * add only:
     *
     * 0.050000
     *
     * The remaining 0.050000 remains available to the user.
     * ==========================================================
     */
    v_collateral_added :=
        least(
            v_requested_collateral,
            v_collateral_shortage
        );


    /*
     * collateral_entry can persist only six decimal places.
     */
    v_collateral_added :=
        trunc(
            v_collateral_added,
            6
        );


    if v_collateral_added <= 0 then
        return query
        select
            true,

            true,

            to_char(
                v_requested_collateral,
                'FM999999999999999999999999990.000000'
            ),

            '0.000000'::text,

            to_char(
                v_requested_collateral,
                'FM999999999999999999999999990.000000'
            ),

            to_char(
                v_collateral_shortage,
                'FM999999999999999999999999990.000000'
            ),

            to_char(
                round(
                    v_previous_locked,
                    6
                ),
                'FM999999999999999999999999990.000000'
            ),

            to_char(
                round(
                    v_previous_locked,
                    6
                ),
                'FM999999999999999999999999990.000000'
            ),

            0;

        return;
    end if;


    /*
     * ==========================================================
     * CHECK AVAILABLE BLOCKCHAIN GOLD
     * ==========================================================
     *
     * IMPORTANT:
     *
     * Validate the amount ACTUALLY being locked.
     *
     * Do not reject a request merely because the user authorised
     * more than is necessary.
     *
     * Example:
     *
     * requested       = 0.100000
     * required        = 0.050000
     * available       = 0.060000
     *
     * This is valid because only 0.050000 will be locked.
     * ==========================================================
     */
    v_stage :=
        'validate available collateral';


    v_available_tokens :=
        greatest(
            v_total_tokens -
            v_previous_locked,
            0
        );


    if v_collateral_added >
       v_available_tokens
    then
        raise exception
            'INSUFFICIENT_AVAILABLE_GOLD';
    end if;


    /*
     * ==========================================================
     * UPDATE CONSOLIDATED COLLATERAL POOL
     * ==========================================================
     *
     * The pool is updated BEFORE its distribution across active
     * loans.
     *
     * Only the amount actually required and authorised is added.
     * ==========================================================
     */
    v_stage :=
        'update consolidated collateral';


    update public.collateral
    set
        locked_tokens =
            coalesce(
                locked_tokens,
                0
            ) +
            v_collateral_added,
        updated_at = now()
    where id = v_collateral.id
      and user_id = v_user.id
    returning
        locked_tokens
    into
        v_new_locked;


    if not found then
        raise exception
            'COLLATERAL_UPDATE_FAILED';
    end if;

    if v_new_locked <> v_previous_locked + v_collateral_added then
        raise exception 'COLLATERAL_POOL_UPDATE_MISMATCH';
    end if;


    /*
     * ==========================================================
     * REDISTRIBUTE ACTUAL POOL ACROSS ACTIVE LOANS
     * ==========================================================
     *
     * loan.collateral represents the CURRENT allocation of the
     * shared collateral pool to that individual loan.
     *
     * It is therefore recalculated rather than incremented.
     *
     * Allocation order:
     *
     * oldest active loan
     *     ↓
     * next oldest
     *     ↓
     * until the actual pool is exhausted.
     *
     * If the pool is sufficient, every loan receives its full
     * target collateral.
     *
     * If the top-up was only partial, later loans may remain
     * partially covered or uncovered.
     *
     * Existing pool gold is allocated first.
     *
     * Only allocation originating from v_collateral_added
     * creates new collateral_entry debit rows.
     * ==========================================================
     */
    v_stage :=
        'redistribute collateral pool';


    v_remaining_pool :=
        v_new_locked;

    v_existing_pool_remaining :=
        v_previous_locked;

    v_new_gold_remaining :=
        v_collateral_added;

    v_loans_adjusted :=
        0;


    for v_loan in
        select
            loan_record.*
        from public.loan
            loan_record
        where loan_record.user_id =
              v_user.id
          and loan_record.status =
              'active'::public."LoanStatus"
        order by
            loan_record.created_at asc,
            loan_record.id asc
    loop
        /*
         * ------------------------------------------------------
         * CURRENT OUTSTANDING EXPOSURE
         * ------------------------------------------------------
         */
        select
            greatest(
                coalesce(
                    sum(
                        entry_record.debit_principal
                    ),
                    0
                ) -
                coalesce(
                    sum(
                        entry_record.credit_principal
                    ),
                    0
                ),
                0
            ),

            greatest(
                coalesce(
                    sum(
                        entry_record.debit_interest
                    ),
                    0
                ) -
                coalesce(
                    sum(
                        entry_record.credit_interest
                    ),
                    0
                ),
                0
            )
        into
            v_principal,
            v_interest
        from public.loan_entry
            entry_record
        where entry_record.loan_id =
              v_loan.id;


        if v_loan.country_code is distinct from v_user.country_code
           or lower(btrim(v_loan.currency_code)) is distinct from 'usd'
        then
            raise exception 'LOAN_PORTFOLIO_CONTEXT_MISMATCH';
        end if;
        if v_principal::text in ('NaN', 'Infinity', '-Infinity')
           or v_interest::text in ('NaN', 'Infinity', '-Infinity')
        then
            raise exception 'INVALID_LOAN_BALANCE';
        end if;

        v_exposure :=
            v_principal +
            v_interest;


        /*
         * An active loan with no remaining exposure receives no
         * collateral allocation.
         */
        if v_exposure <= 0 then
            v_target_collateral := 0;
        else
            v_target_ltv :=
                coalesce(
                    v_loan.max_ltv_percent,
                    0
                );


            if v_target_ltv::text in ('NaN', 'Infinity', '-Infinity')
               or v_target_ltv <= 0
               or v_target_ltv >= 100
            then
                raise exception
                    'INVALID_LOAN_LTV_CONFIGURATION';
            end if;


            v_target_collateral := ceil(
                v_exposure * 100 / (v_target_ltv * v_gold_price) * 1000000
            ) / 1000000;
        end if;


        /*
         * Allocate only gold that actually exists in the pool.
         */
        v_allocation :=
            least(
                v_target_collateral,
                greatest(
                    v_remaining_pool,
                    0
                )
            );


        v_allocation :=
            trunc(
                v_allocation,
                6
            );


        /*
         * ------------------------------------------------------
         * IDENTIFY EXISTING POOL VS NEW TOP-UP
         * ------------------------------------------------------
         *
         * Existing pool collateral is consumed first during the
         * redistribution.
         *
         * Any portion beyond that is newly locked gold belonging
         * to this operation and therefore receives a new
         * collateral_entry.
         * ------------------------------------------------------
         */
        v_existing_allocation :=
            least(
                v_allocation,
                greatest(
                    v_existing_pool_remaining,
                    0
                )
            );


        v_existing_allocation :=
            trunc(
                v_existing_allocation,
                6
            );


        v_new_allocation :=
            greatest(
                v_allocation -
                v_existing_allocation,
                0
            );


        v_new_allocation :=
            least(
                v_new_allocation,
                greatest(
                    v_new_gold_remaining,
                    0
                )
            );


        v_new_allocation :=
            trunc(
                v_new_allocation,
                6
            );


        /*
         * ------------------------------------------------------
         * SYNCHRONISE INDIVIDUAL LOAN ALLOCATION
         * ------------------------------------------------------
         *
         * DO NOT:
         *
         *     loan.collateral += top_up
         *
         * The old value may represent a position calculated at
         * a different:
         *
         * - gold price;
         * - principal balance;
         * - interest balance;
         * - liquidation state;
         * - repayment state.
         *
         * Instead loan.collateral becomes the amount of today's
         * actual pooled collateral allocated to that loan.
         * ------------------------------------------------------
         */
        v_previous_loan_allocation :=
            greatest(
                coalesce(
                    v_loan.collateral,
                    0
                ),
                0
            );


        if v_previous_loan_allocation
           is distinct from
           v_allocation
        then
            v_stage :=
                'update loan collateral allocation';


            update public.loan
            set
                collateral =
                    v_allocation,
                updated_at = now()
            where id =
                  v_loan.id;


            if not found then
                raise exception
                    'LOAN_COLLATERAL_UPDATE_FAILED';
            end if;


            v_loans_adjusted :=
                v_loans_adjusted +
                1;
        end if;


        v_liquidation_price := 0;
        if v_exposure > 0 and v_allocation > 0 then
            if v_loan.liquidation_ltv is null
               or v_loan.liquidation_ltv::text in ('NaN', 'Infinity', '-Infinity')
               or v_loan.liquidation_ltv <= 0
               or v_loan.liquidation_ltv > 100
            then
                raise exception 'INVALID_LIQUIDATION_LTV';
            end if;
            v_liquidation_price := trunc(
                v_exposure / (v_allocation * v_loan.liquidation_ltv / 100), 6
            );
        end if;
        update public.loan
        set liquidation_price = v_liquidation_price,
            updated_at = now()
        where id = v_loan.id;

        /*
         * ------------------------------------------------------
         * CREATE LEDGER ENTRY FOR NEW GOLD ONLY
         * ------------------------------------------------------
         *
         * Existing pooled gold is merely being redistributed.
         * It must not be posted again.
         *
         * Only newly locked gold from this request creates a
         * collateral_entry debit.
         * ------------------------------------------------------
         */
        if v_new_allocation > 0 then
            v_stage :=
                'create collateral entry';


            insert into public.collateral_entry (
                loan_id,
                document_number,
                reference,
                debit,
                credit,
                country_code
            )
            values (
                v_loan.id,
                v_reference,
                v_reference,
                v_new_allocation,
                0,
                v_user.country_code
            );
            v_posted_debits := v_posted_debits + v_new_allocation;
        end if;


        /*
         * ------------------------------------------------------
         * REDUCE REMAINING POOL
         * ------------------------------------------------------
         */
        v_remaining_pool :=
            greatest(
                v_remaining_pool -
                v_allocation,
                0
            );


        v_existing_pool_remaining :=
            greatest(
                v_existing_pool_remaining -
                v_existing_allocation,
                0
            );


        v_new_gold_remaining :=
            greatest(
                v_new_gold_remaining -
                v_new_allocation,
                0
            );
    end loop;


    /*
     * ==========================================================
     * SAFETY CHECK: NEW GOLD MUST BE ACCOUNTED FOR
     * ==========================================================
     *
     * Because the new pool cannot exceed the calculated required
     * pool, all newly added gold should have been assigned to an
     * active loan.
     *
     * A remaining new amount indicates that the portfolio changed
     * unexpectedly or the allocation calculation is inconsistent.
     * ==========================================================
     */
    if v_new_gold_remaining <> 0
       or v_existing_pool_remaining <> 0
       or v_remaining_pool <> 0
       or v_posted_debits <> v_collateral_added
    then
        raise exception
            'COLLATERAL_ALLOCATION_MISMATCH';
    end if;


    /*
     * ==========================================================
     * FETCH FISCAL PERIOD
     * ==========================================================
     */
    v_stage :=
        'fetch fiscal period';


    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_user.country_code
    ) as fiscal_period;


    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * UPDATE COLLATERAL SNAPSHOT
     * ==========================================================
     *
     * Only newly locked collateral changes the consolidated
     * balance snapshot.
     *
     * Redistributing existing pooled collateral across loans
     * does not change the user's total locked gold.
     * ==========================================================
     */
    v_stage :=
        'update collateral snapshot';


    perform public.update_collateral_snapshot(
        v_user.id,
        v_user.country_code,
        v_collateral_added,
        0::numeric,
        v_fiscal_year,
        v_period
    );


    /*
     * ==========================================================
     * CALCULATE REMAINING PORTFOLIO SHORTAGE
     * ==========================================================
     */
    v_remaining_required :=
        greatest(
            v_total_required_pool -
            v_new_locked,
            0
        );


    /*
     * Keep the externally reported requirement at six decimal
     * places.
     */
    v_remaining_required :=
        ceil(
            v_remaining_required *
            1000000
        ) /
        1000000;


    /*
     * ==========================================================
     * RETURN RESULT
     * ==========================================================
     */
    return query
    select
        true,

        /*
         * true means the pool is STILL below target after this
         * operation.
         */
        v_remaining_required > 0,

        to_char(
            v_requested_collateral,
            'FM999999999999999999999999990.000000'
        ),

        to_char(
            v_collateral_added,
            'FM999999999999999999999999990.000000'
        ),

        to_char(
            greatest(
                v_requested_collateral -
                v_collateral_added,
                0
            ),
            'FM999999999999999999999999990.000000'
        ),

        to_char(
            v_remaining_required,
            'FM999999999999999999999999990.000000'
        ),

        to_char(
            round(
                v_previous_locked,
                6
            ),
            'FM999999999999999999999999990.000000'
        ),

        to_char(
            round(
                v_new_locked,
                6
            ),
            'FM999999999999999999999999990.000000'
        ),

        v_loans_adjusted;


exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;


        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'ADDITIONAL_COLLATERAL_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                coalesce(
                    nullif(
                        concat_ws(
                            E'\n',
                            nullif(
                                v_error_detail,
                                ''
                            ),
                            nullif(
                                v_error_context,
                                ''
                            )
                        ),
                        ''
                    ),
                    'No additional PostgreSQL context'
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    'Check the Additional Collateral stage reported in the error'
                );
end;
$$;
ALTER FUNCTION "public"."execute_additional_collateral"("p_user_id" "text", "p_requested_collateral" "text", "p_token_balance" "text", "p_reference" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."execute_loan_disbursement"("p_user_id" "text", "p_requested_amount" "text", "p_token_balance" "text", "p_reference" "text", "p_currency_code" "text" DEFAULT 'usd'::"text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "document_number" "text", "loan_id" "text", "customer_id" "text", "country_code" "text", "currency_code" "text", "principal_amount" "text", "collateral_locked" "text", "initiation_fee" "text", "net_disbursed" "text", "notification_id" "text", "device_tokens" "text"[], "push_title" "text", "push_body" "text", "push_reference" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_transaction_type
        public."TransactionType" :=
        'loan_disbursement'::public."TransactionType";

    v_stage text :=
        'initialization';

    v_user
        public.users%rowtype;

    v_treasury
        public.users%rowtype;

    v_collateral
        public.collateral%rowtype;

    v_reference text;
    v_currency text;

    /*
     * Full loan principal.
     *
     * Example:
     *
     * requested loan = 100
     *
     * principal = 100
     */
    v_requested_amount numeric;

    v_preview jsonb;
    v_preview_data jsonb;

    v_required_collateral numeric;
    v_initiation_fee numeric;

    /*
     * Actual USD amount credited to the customer's wallet.
     *
     * Example:
     *
     * principal       = 100
     * initiation fee  = 2
     * net disbursed   = 98
     */
    v_net_disbursed numeric;

    v_liquidation_price numeric;
    v_ltv_percent numeric;
    v_liquidation_ltv_percent numeric;

    v_loan_interest numeric :=
        12;

    v_fiscal_year integer;
    v_period integer;

    v_mappings
        public.transaction_gl_mapping[];

    v_components
        public.posting_component[];

    v_document_prefix text;
    v_document_number text;

    v_financial_transaction_id bigint;
    v_loan_id text;

    v_receiver_notification
        public.notification_message;

    v_receiver_notification_id text;

    v_device_tokens text[] :=
        array[]::text[];

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;

begin
    /*
     * ==========================================================
     * AUTHENTICATION / AUTHORIZATION
     * ==========================================================
     */
    v_stage :=
        'authorize customer';

    if coalesce(auth.role(), '') <> 'service_role' then
        raise exception using errcode='42501', message='SERVICE_ROLE_REQUIRED';
    end if;

    if nullif(btrim(p_user_id), '') is null then
        raise exception 'USER_ID_REQUIRED';
    end if;


    if not public.user_has_role(
        p_user_id,
        array[
            'customer',
            'agent',
            'vendor'
        ]::text[]
    ) then
        raise exception using
            errcode =
                '42501',
            message =
                'FORBIDDEN';
    end if;


    select
        user_record.*
    into
        v_user
    from public.users
        user_record
    where user_record.id =
          p_user_id
    limit 1;


    if not found then
        raise exception
            'USER_NOT_FOUND';
    end if;


    if v_user.status is distinct from
       'active'::public."UserStatus"
    then
        raise exception
            'USER_NOT_ACTIVE';
    end if;


    if v_user.country_code is null
       or btrim(
           v_user.country_code
       ) = ''
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;


    /*
     * ==========================================================
     * PARSE REQUESTED AMOUNT
     * ==========================================================
     */
    v_stage :=
        'parse requested amount';


    begin
        v_requested_amount :=
            nullif(
                btrim(
                    p_requested_amount
                ),
                ''
            )::numeric;

    exception
        when invalid_text_representation
          or numeric_value_out_of_range
        then
            raise exception
                'INVALID_LOAN_AMOUNT';
    end;


    if v_requested_amount is null
       or v_requested_amount::text in ('NaN', 'Infinity', '-Infinity')
       or v_requested_amount <> trunc(v_requested_amount, 2)
       or v_requested_amount <= 0
    then
        raise exception
            'INVALID_LOAN_AMOUNT';
    end if;


    /*
     * ==========================================================
     * PARSE REFERENCE
     * ==========================================================
     */
    v_stage :=
        'parse reference';


    v_reference :=
        nullif(
            btrim(
                p_reference
            ),
            ''
        );


    if v_reference is null then
        raise exception
            'REFERENCE_REQUIRED';
    end if;


    /*
     * ==========================================================
     * PARSE CURRENCY
     * ==========================================================
     *
     * Loans are always USD.
     */
    v_stage :=
        'parse currency';


    v_currency :=
        lower(
            nullif(
                btrim(
                    p_currency_code
                ),
                ''
            )
        );


    if v_currency is null then
        raise exception
            'CURRENCY_MISSING';
    end if;


    if v_currency <> 'usd' then
        raise exception
            'UNSUPPORTED_LOAN_CURRENCY';
    end if;


    /*
     * ==========================================================
     * REPLAY PROTECTION
     * ==========================================================
     */
    v_stage :=
        'lock loan reference';


    perform
        pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(
                v_reference,
                0
            )
        );


    perform 1
    from public.financial_transaction
        transaction_record
    where transaction_record.reference =
          v_reference;


    if found then
        raise exception using
            errcode =
                '23505',
            message =
                'TRANSACTION_REPLAY';
    end if;


    /*
     * ==========================================================
     * FETCH COUNTRY TREASURY
     * ==========================================================
     */
    -- Use the same per-user lock as liquidation detection/repayment.
    v_stage := 'lock loan position';
    perform pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('loan-position:' || v_user.id, 0)
    );
    if exists (
        select 1 from public.liquidation_job as j
        where j.user_id = v_user.id
          and j.status::text not in ('completed', 'cancelled')
    ) then
        raise exception 'LOAN_POSITION_LIQUIDATION_IN_PROGRESS';
    end if;

    v_stage :=
        'fetch country treasury';


    v_treasury :=
        public.fetch_country_treasury(
            v_user.country_code
        );


    if v_treasury.id is null then
        raise exception
            'TREASURY_WALLET_NOT_CONFIGURED';
    end if;


    /*
     * ==========================================================
     * ENSURE COLLATERAL ROW EXISTS
     * ==========================================================
     */
    v_stage :=
        'create collateral row';


    insert into public.collateral (
        user_id,
        locked_tokens,
        country_code
    )
    values (
        v_user.id,
        0,
        v_user.country_code
    )
    on conflict (
        user_id
    )
    do nothing;


    /*
     * ==========================================================
     * LOCK COLLATERAL
     * ==========================================================
     */
    v_stage :=
        'lock collateral row';


    select
        collateral_record.*
    into
        v_collateral
    from public.collateral
        collateral_record
    where collateral_record.user_id =
          v_user.id
    for update;


    if not found then
        raise exception
            'COLLATERAL_NOT_FOUND';
    end if;


    if v_collateral.country_code
       is distinct from
       v_user.country_code
    then
        raise exception
            'COLLATERAL_COUNTRY_MISMATCH';
    end if;


    /*
     * ==========================================================
     * RECALCULATE LOAN PREVIEW
     * ==========================================================
     */
    v_stage :=
        'recalculate loan preview';


    v_preview :=
        public.preview_loan_for_user(
            p_user_id => p_user_id,
            p_requested_amount =>
                v_requested_amount::text,

            p_token_balance =>
                p_token_balance,

            p_currency_code =>
                v_currency
        );


    if v_preview is null
       or coalesce(
           (
               v_preview
               ->> 'success'
           )::boolean,
           false
       ) = false
    then
        raise exception
            'LOAN_PREVIEW_FAILED';
    end if;


    v_preview_data :=
        v_preview
        -> 'data';


    if v_preview_data is null then
        raise exception
            'LOAN_PREVIEW_DATA_NOT_FOUND';
    end if;


    begin
        v_required_collateral :=
            (
                v_preview_data
                ->> 'required_collateral_grams'
            )::numeric;


        v_initiation_fee :=
            (
                v_preview_data
                ->> 'initiation_fee'
            )::numeric;


        v_net_disbursed :=
            (
                v_preview_data
                ->> 'net_disbursed'
            )::numeric;


        v_liquidation_price :=
            (
                v_preview_data
                -> 'risk'
                ->> 'liquidationPrice'
            )::numeric;


        v_ltv_percent :=
            (
                v_preview_data
                ->> 'ltv_percent'
            )::numeric;


        v_liquidation_ltv_percent :=
            (
                v_preview_data
                ->> 'liquidation_ltv_percent'
            )::numeric;

    exception
        when invalid_text_representation
          or numeric_value_out_of_range
        then
            raise exception
                'INVALID_LOAN_PREVIEW_RESULT';
    end;


    if v_required_collateral is null
       or v_required_collateral::text in ('NaN', 'Infinity', '-Infinity')
       or v_required_collateral <= 0 then
        raise exception
            'INVALID_COLLATERAL_AMOUNT';
    end if;


    if v_initiation_fee is null
       or v_initiation_fee::text in ('NaN', 'Infinity', '-Infinity')
       or v_initiation_fee < 0 then
        raise exception
            'INVALID_INITIATION_FEE';
    end if;


    if v_net_disbursed is null
       or v_net_disbursed::text in ('NaN', 'Infinity', '-Infinity')
       or v_net_disbursed <= 0 then
        raise exception
            'INVALID_NET_DISBURSEMENT';
    end if;


    if v_liquidation_price is null
       or v_liquidation_price::text in ('NaN', 'Infinity', '-Infinity')
       or v_liquidation_price <= 0 then
        raise exception
            'INVALID_LIQUIDATION_PRICE';
    end if;


    /*
     * ==========================================================
     * FETCH LOAN INTEREST
     * ==========================================================
     */
    if v_required_collateral <> ceil(v_required_collateral * 1000000) / 1000000
       or v_initiation_fee <> trunc(v_initiation_fee, 2)
       or v_net_disbursed <> trunc(v_net_disbursed, 2)
       or v_net_disbursed + v_initiation_fee <> v_requested_amount
    then
        raise exception 'INVALID_LOAN_PREVIEW_RESULT';
    end if;

    -- Persist the configured borrowing LTV, not the display-rounded actual
    -- LTV from the risk summary (rounding collateral can slightly lower it).
    select c.rate into v_ltv_percent
    from public.loan_config as c
    where c.config_type = 'loan_ltv' and c.is_active = true
    limit 1;
    if not found or v_ltv_percent is null
       or v_ltv_percent::text in ('NaN', 'Infinity', '-Infinity')
       or v_ltv_percent <= 0 or v_ltv_percent >= 100
       or v_liquidation_ltv_percent is null
       or v_liquidation_ltv_percent::text in ('NaN', 'Infinity', '-Infinity')
       or v_liquidation_ltv_percent <= v_ltv_percent
       or v_liquidation_ltv_percent > 100
    then
        raise exception 'INVALID_LOAN_LTV_CONFIGURATION';
    end if;

    v_stage :=
        'fetch loan interest';


    select
        loan_config_record.rate
    into
        v_loan_interest
    from public.loan_config
        loan_config_record
    where loan_config_record.config_type =
          'loan_interest'
      and loan_config_record.is_active =
          true
    limit 1;


    v_loan_interest :=
        coalesce(
            v_loan_interest,
            12
        );


    if v_loan_interest is null
       or v_loan_interest::text in ('NaN', 'Infinity', '-Infinity')
       or v_loan_interest < 0 then
        raise exception
            'INVALID_LOAN_INTEREST_RATE';
    end if;


    /*
     * ==========================================================
     * FETCH FISCAL PERIOD
     * ==========================================================
     */
    v_stage :=
        'fetch fiscal period';


    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_user.country_code
    ) as fiscal_period;


    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * FETCH GL MAPPINGS
     * ==========================================================
     */
    v_stage :=
        'fetch GL mappings';


    select
        array_agg(
            mapping_record
        )
    into
        v_mappings
    from public.fetch_gl_mappings(
        v_transaction_type
    ) as mapping_record;


    if v_mappings is null
       or cardinality(
           v_mappings
       ) = 0
    then
        raise exception
            'GL_MAPPINGS_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * BUILD POSTING COMPONENTS
     * ==========================================================
     */
    v_stage :=
        'build posting components';


    v_components :=
        public.build_posting_components(
            v_transaction_type,
            v_requested_amount,
            v_mappings,
            v_user.country_code,
            v_currency,
            false
        );


    if v_components is null
       or cardinality(
           v_components
       ) = 0
    then
        raise exception
            'POSTING_COMPONENTS_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * CUSTOMER NOTIFICATION
     * ==========================================================
     */
    v_stage :=
        'create customer notification';


    v_receiver_notification :=
        public.create_notification_message(
            v_user.country_code,
            v_transaction_type,
            'receiver'::public."NotificationAudience",
            v_requested_amount,
            upper(
                v_currency
            ),
            v_reference,
            0,
            coalesce(
                v_treasury.email,
                v_treasury.phone,
                v_treasury.id
            ),
            coalesce(
                v_user.email,
                v_user.phone,
                v_user.id
            )
        );


    v_device_tokens :=
        coalesce(
            public.fetch_device_tokens(
                v_user.country_code,
                v_user.id
            ),
            array[]::text[]
        );


    /*
     * ==========================================================
     * DOCUMENT NUMBER
     * ==========================================================
     */
    v_stage :=
        'fetch document prefix';


    v_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            v_transaction_type
        );


    if v_document_prefix is null
       or btrim(
           v_document_prefix
       ) = ''
    then
        raise exception
            'DOCUMENT_PREFIX_NOT_FOUND';
    end if;


    v_stage :=
        'generate document number';


    v_document_number :=
        public.generate_document_number(
            v_document_prefix,
            v_fiscal_year,
            v_period,
            v_user.country_code
        );


    /*
     * ==========================================================
     * CREATE FINANCIAL TRANSACTION
     * ==========================================================
     */
    v_stage :=
        'create financial transaction';


    insert into public.financial_transaction (
        document_number,
        fiscal_year,
        reference,
        period,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        country_code
    )
    values (
        v_document_number,
        v_fiscal_year,
        v_reference,
        v_period,
        v_transaction_type,
        'Loan disbursement for user ' ||
            v_user.id,
        v_user.id,
        v_requested_amount,
        v_currency,
        v_user.country_code
    )
    returning
        id
    into
        v_financial_transaction_id;


    /*
     * ==========================================================
     * POST FINANCIAL ENTRIES
     * ==========================================================
     */
    v_stage :=
        'post financial entries';


    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_document_number,

        p_country_code =>
            v_user.country_code,

        p_transaction_id =>
            v_financial_transaction_id,

        p_transaction_type =>
            v_transaction_type,

        p_created_by =>
            v_user.id,

        p_components =>
            v_components,

        p_mappings =>
            v_mappings,

        p_currency_code =>
            v_currency,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_reference =>
            v_reference,

        p_deposit_type =>
            null
    );


    /*
     * ==========================================================
     * POST WALLET ENTRIES
     * ==========================================================
     *
     * Only the net loan proceeds are credited to the customer.
     *
     * Example:
     *
     * loan principal  = 100
     * initiation fee  = 2
     * wallet credit   = 98
     */
    v_stage :=
        'post wallet entries';


    select
        posting_result.receiver_notification_id
    into
        v_receiver_notification_id
    from public.post_wallet_entries(
        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_document_number =>
            v_document_number,

        p_reference =>
            v_reference,

        p_receiver_id =>
            v_user.id,

        p_sender_id =>
            v_treasury.id,

        p_transaction_type =>
            v_transaction_type,

        p_credit_amount =>
            v_net_disbursed,

        p_debit_amount =>
            v_net_disbursed,

        p_sender_wallet_owner =>
            'treasury'::public."WalletOwnerType",

        p_receiver_wallet_owner =>
            'customer'::public."WalletOwnerType",

        p_currency_code =>
            v_currency,

        p_country_code =>
            v_user.country_code,

        p_audit_action_type =>
            'loan_issued'::public."AuditActionType",

        p_treasury_id =>
            null,

        p_fee_amount =>
            0,

        p_ip_address =>
            p_ip_address,

        p_receiver_notification =>
            v_receiver_notification,

        p_sender_notification =>
            null
    ) as posting_result;


    /*
     * ==========================================================
     * CREATE LOAN
     * ==========================================================
     *
     * Principal remains the full requested loan amount.
     */
    v_stage :=
        'create loan';


    insert into public.loan (
        document_number,
        reference,
        user_id,
        fiscal_year,
        period,
        principal,
        net_amount,
        initiation_fee,
        interest_rate,
        collateral,
        max_ltv_percent,
        liquidation_ltv,
        liquidation_price,
        status,
        currency_code,
        country_code
    )
    values (
        v_document_number,
        v_reference,
        v_user.id,
        v_fiscal_year,
        v_period,
        v_requested_amount,
        v_net_disbursed,
        v_initiation_fee,
        v_loan_interest,
        v_required_collateral,
        v_ltv_percent,
        v_liquidation_ltv_percent,
        v_liquidation_price,
        'active'::public."LoanStatus",
        v_currency,
        v_user.country_code
    )
    returning
        id::text
    into
        v_loan_id;


    /*
     * ==========================================================
     * CREATE LOAN PRINCIPAL ENTRY
     * ==========================================================
     */
    v_stage :=
        'create loan entry';


    insert into public.loan_entry (
        loan_id,
        fiscal_year,
        period,
        document_number,
        entry_type,
        debit_principal,
        credit_principal,
        debit_interest,
        credit_interest,
        currency_code,
        country_code
    )
    values (
        v_loan_id,
        v_fiscal_year,
        v_period,
        v_document_number,
        'disbursement'::public."LoanEntryType",
        v_requested_amount,
        0,
        0,
        0,
        v_currency,
        v_user.country_code
    );


    /*
     * ==========================================================
     * UPDATE COLLATERAL
     * ==========================================================
     */
    v_stage :=
        'update collateral';


    update public.collateral
    set
        locked_tokens =
            coalesce(
                locked_tokens,
                0
            ) +
            v_required_collateral
    where user_id =
          v_user.id;


    if not found then
        raise exception
            'COLLATERAL_UPDATE_FAILED';
    end if;


    /*
     * ==========================================================
     * CREATE COLLATERAL ENTRY
     * ==========================================================
     */
    v_stage :=
        'create collateral entry';


    insert into public.collateral_entry (
        loan_id,
        document_number,
        debit,
        credit,
        country_code
    )
    values (
        v_loan_id,
        v_document_number,
        v_required_collateral,
        0,
        v_user.country_code
    );


    /*
     * ==========================================================
     * UPDATE LOAN SNAPSHOT
     * ==========================================================
     *
     * Full loan principal increases the outstanding loan.
     */
    v_stage :=
        'update loan snapshot';


    perform public.update_loan_snapshot(
        v_loan_id,
        v_user.id,
        v_user.country_code,
        v_requested_amount,
        0::numeric,
        0::numeric,
        0::numeric,
        v_fiscal_year,
        v_period
    );


    /*
     * ==========================================================
     * UPDATE COLLATERAL SNAPSHOT
     * ==========================================================
     */
    v_stage :=
        'update collateral snapshot';


    perform public.update_collateral_snapshot(
        v_user.id,
        v_user.country_code,
        v_required_collateral,
        0::numeric,
        v_fiscal_year,
        v_period
    );


    /*
     * ==========================================================
     * RETURN COMMITTED RESULT
     * ==========================================================
     *
     * Financial Intelligence uses:
     *
     * principal_amount
     *     = loan / borrowing increase
     *
     * net_disbursed
     *     = customer deposit / savings inflow
     *
     * Example:
     *
     * principal_amount = 100
     * net_disbursed    = 98
     *
     * FI:
     *
     * loan increase    +100
     * savings inflow   +98
     */
    return query
    select
        true,

        v_document_number,

        v_loan_id,

        v_user.id,

        lower(
            btrim(
                v_user.country_code
            )
        ),

        v_currency,

        to_char(
            round(
                v_requested_amount,
                2
            ),
            'FM999999999999999999999999990.00'
        ),

        to_char(
            round(
                v_required_collateral,
                6
            ),
            'FM999999999999999999999999990.000000'
        ),

        to_char(
            round(
                v_initiation_fee,
                2
            ),
            'FM999999999999999999999999990.00'
        ),

        to_char(
            round(
                v_net_disbursed,
                2
            ),
            'FM999999999999999999999999990.00'
        ),

        v_receiver_notification_id,

        v_device_tokens,

        v_receiver_notification.title,

        v_receiver_notification.body,

        v_receiver_notification.payload
            ->> 'reference';


exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;


        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'LOAN_DISBURSEMENT_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                coalesce(
                    nullif(
                        concat_ws(
                            E'\n',
                            nullif(
                                v_error_detail,
                                ''
                            ),
                            nullif(
                                v_error_context,
                                ''
                            )
                        ),
                        ''
                    ),
                    'No additional PostgreSQL context'
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    'Check the Loan Disbursement stage reported in the error'
                );

end;
$$;
ALTER FUNCTION "public"."execute_loan_disbursement"("p_user_id" "text", "p_requested_amount" "text", "p_token_balance" "text", "p_reference" "text", "p_currency_code" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."execute_my_additional_collateral"("p_requested_collateral" "text", "p_token_balance" "text", "p_reference" "text") RETURNS TABLE("success" boolean, "collateral_required" boolean, "requested_collateral" "text", "collateral_added" "text", "unused_collateral" "text", "remaining_required_collateral" "text", "previous_locked_collateral" "text", "new_locked_collateral" "text", "loans_adjusted" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_stage text :=
        'initialization';

    v_user
        public.users%rowtype;

    v_collateral
        public.collateral%rowtype;

    v_loan
        public.loan%rowtype;

    v_reference text;

    /*
     * Maximum amount authorised by the user for this
     * collateral top-up.
     */
    v_requested_collateral numeric;

    /*
     * Current blockchain gold balance supplied by the
     * authenticated Edge Function.
     */
    v_total_tokens numeric;

    /*
     * Gold currently available outside the locked pool.
     */
    v_available_tokens numeric := 0;

    /*
     * Current USD gold price.
     */
    v_gold_price numeric := 0;

    /*
     * Per-loan outstanding exposure.
     */
    v_principal numeric := 0;
    v_interest numeric := 0;
    v_exposure numeric := 0;

    /*
     * Target LTV configured on each loan.
     *
     * Stored as:
     *
     * 60.00
     *
     * and converted to:
     *
     * 0.60
     *
     * during the collateral calculation.
     */
    v_target_ltv numeric := 0;

    /*
     * Current required collateral for one loan at:
     *
     * - current outstanding exposure;
     * - current gold price;
     * - configured target LTV.
     */
    v_target_collateral numeric := 0;

    /*
     * Total gold currently required to cover every
     * active loan at its target LTV.
     *
     * IMPORTANT:
     *
     * This is the required SIZE OF THE POOL.
     *
     * It is not the additional collateral shortage.
     */
    v_total_required_pool numeric := 0;

    /*
     * Additional gold required before and after this
     * operation.
     */
    v_collateral_shortage numeric := 0;
    v_remaining_required numeric := 0;

    /*
     * Actual collateral added by this operation.
     *
     * This can be less than the amount authorised by
     * the user when the complete authorised amount is
     * not required.
     */
    v_collateral_added numeric := 0;

    /*
     * Consolidated collateral balances.
     */
    v_previous_locked numeric := 0;
    v_new_locked numeric := 0;

    /*
     * Allocation of the actual consolidated pool across
     * individual active loans.
     */
    v_remaining_pool numeric := 0;
    v_allocation numeric := 0;

    /*
     * When reallocating the pool, distinguish gold that
     * already existed in the pool from NEW gold added by
     * this operation.
     *
     * Only the new portion creates collateral_entry rows.
     */
    v_existing_pool_remaining numeric := 0;
    v_new_gold_remaining numeric := 0;
    v_existing_allocation numeric := 0;
    v_new_allocation numeric := 0;

    /*
     * Existing loan.collateral value before synchronising
     * the current allocation.
     */
    v_previous_loan_allocation numeric := 0;

    v_loans_adjusted integer := 0;
    v_posted_debits numeric := 0;
    v_liquidation_price numeric := 0;

    /*
     * Snapshot period.
     */
    v_fiscal_year integer;
    v_period integer;

    /*
     * Error diagnostics.
     */
    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;

begin
    /*
     * ==========================================================
     * AUTHENTICATION / AUTHORIZATION
     * ==========================================================
     */
    v_stage :=
        'authorize customer';

    if auth.uid() is null then
        raise exception using
            errcode =
                '42501',
            message =
                'UNAUTHORIZED';
    end if;


    if not public.has_role(
        array[
            'customer',
            'agent',
            'vendor'
        ]::text[]
    ) then
        raise exception using
            errcode =
                '42501',
            message =
                'FORBIDDEN';
    end if;


    select
        user_record.*
    into
        v_user
    from public.users
        user_record
    where user_record.id =
          auth.uid()::text
    limit 1;


    if not found then
        raise exception
            'USER_NOT_FOUND';
    end if;


    if v_user.status is distinct from
       'active'::public."UserStatus"
    then
        raise exception
            'USER_NOT_ACTIVE';
    end if;


    if v_user.country_code is null
       or btrim(
           v_user.country_code
       ) = ''
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;


    /*
     * ==========================================================
     * PARSE REQUESTED COLLATERAL
     * ==========================================================
     */
    v_stage :=
        'parse requested collateral';


    begin
        v_requested_collateral :=
            nullif(
                btrim(
                    p_requested_collateral
                ),
                ''
            )::numeric;

    exception
        when invalid_text_representation
          or numeric_value_out_of_range
        then
            raise exception
                'INVALID_COLLATERAL_AMOUNT';
    end;


    if v_requested_collateral is null
       or v_requested_collateral::text in ('NaN', 'Infinity', '-Infinity')
       or v_requested_collateral <= 0
    then
        raise exception
            'INVALID_COLLATERAL_AMOUNT';
    end if;


    /*
     * collateral_entry supports six decimal places.
     *
     * Do not silently modify the quantity authorised by
     * the user's signed request.
     */
    if v_requested_collateral <>
       trunc(
           v_requested_collateral,
           6
       )
    then
        raise exception
            'INVALID_COLLATERAL_PRECISION';
    end if;


    /*
     * ==========================================================
     * PARSE BLOCKCHAIN TOKEN BALANCE
     * ==========================================================
     */
    v_stage :=
        'parse token balance';


    begin
        v_total_tokens :=
            coalesce(
                nullif(
                    btrim(
                        p_token_balance
                    ),
                    ''
                ),
                '0'
            )::numeric;

    exception
        when invalid_text_representation
          or numeric_value_out_of_range
        then
            raise exception
                'INVALID_BLOCKCHAIN_TOKEN_BALANCE';
    end;


    if v_total_tokens::text in ('NaN', 'Infinity', '-Infinity')
       or v_total_tokens < 0 then
        raise exception
            'INVALID_BLOCKCHAIN_TOKEN_BALANCE';
    end if;


    /*
     * ==========================================================
     * PARSE REFERENCE
     * ==========================================================
     */
    v_stage :=
        'parse reference';


    v_reference :=
        nullif(
            btrim(
                p_reference
            ),
            ''
        );


    if v_reference is null then
        raise exception
            'REFERENCE_REQUIRED';
    end if;


    /*
     * ==========================================================
     * REPLAY PROTECTION
     * ==========================================================
     */
    v_stage :=
        'lock collateral reference';


    perform
        pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(
                v_reference,
                0
            )
        );


    perform 1
    from public.collateral_entry
        collateral_entry_record
    join public.loan
        loan_record
      on loan_record.id =
         collateral_entry_record.loan_id
    where collateral_entry_record.reference =
          v_reference
      and loan_record.user_id =
          v_user.id
    limit 1;


    if found then
        raise exception using
            errcode =
                '23505',
            message =
                'TRANSACTION_REPLAY';
    end if;


    /*
     * ==========================================================
     * ENSURE CONSOLIDATED COLLATERAL ROW EXISTS
     * ==========================================================
     */
    v_stage := 'lock loan position';
    perform pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('loan-position:' || v_user.id, 0)
    );
    if exists (
        select 1 from public.liquidation_job as j
        where j.user_id = v_user.id
          and j.status::text not in ('completed', 'cancelled')
    ) then
        raise exception 'LOAN_POSITION_LIQUIDATION_IN_PROGRESS';
    end if;

    v_stage :=
        'create collateral row';


    insert into public.collateral (
        user_id,
        locked_tokens,
        country_code
    )
    values (
        v_user.id,
        0,
        v_user.country_code
    )
    on conflict (
        user_id
    )
    do nothing;


    /*
     * ==========================================================
     * LOCK CONSOLIDATED COLLATERAL
     * ==========================================================
     *
     * collateral.locked_tokens is the authoritative quantity
     * of gold currently locked for the user's loan portfolio.
     * ==========================================================
     */
    v_stage :=
        'lock collateral row';


    select
        collateral_record.*
    into
        v_collateral
    from public.collateral
        collateral_record
    where collateral_record.user_id =
          v_user.id
    for update;


    if not found then
        raise exception
            'COLLATERAL_NOT_FOUND';
    end if;


    if v_collateral.country_code
       is distinct from
       v_user.country_code
    then
        raise exception
            'COLLATERAL_COUNTRY_MISMATCH';
    end if;


    v_previous_locked := v_collateral.locked_tokens;
    if v_previous_locked is null
       or v_previous_locked::text in ('NaN', 'Infinity', '-Infinity')
       or v_previous_locked < 0
       or v_previous_locked <> trunc(v_previous_locked, 6)
    then
        raise exception 'INVALID_LOCKED_COLLATERAL';
    end if;

    /*
     * ==========================================================
     * LOCK ACTIVE LOANS
     * ==========================================================
     *
     * The portfolio must remain stable while:
     *
     * - exposure is calculated;
     * - pooled collateral is increased;
     * - the pool is redistributed across loans.
     *
     * Oldest loan first is also the allocation order.
     * ==========================================================
     */
    v_stage :=
        'lock active loans';


    perform
        loan_record.id
    from public.loan
        loan_record
    where loan_record.user_id =
          v_user.id
      and loan_record.status =
          'active'::public."LoanStatus"
    order by
        loan_record.created_at asc,
        loan_record.id asc
    for update;


    /*
     * ==========================================================
     * FETCH CURRENT GOLD PRICE
     * ==========================================================
     */
    v_stage :=
        'fetch gold price';


    select
        coalesce(
            rate_record.rate_to_usd,
            0
        )
    into
        v_gold_price
    from public.current_rates
        rate_record
    where lower(
        rate_record.code
    ) = 'gold'
    limit 1;


    v_gold_price :=
        coalesce(
            v_gold_price,
            0
        );


    if v_gold_price is null
       or v_gold_price::text in ('NaN', 'Infinity', '-Infinity')
       or v_gold_price <= 0 then
        raise exception
            'INVALID_GOLD_RATE';
    end if;


    /*
     * ==========================================================
     * CALCULATE REQUIRED COLLATERAL POOL
     * ==========================================================
     *
     * The collateral model is pooled.
     *
     * Therefore loan.collateral MUST NOT be subtracted here.
     *
     * For every active loan:
     *
     * exposure =
     *     outstanding principal
     *     +
     *     outstanding interest
     *
     * required collateral USD =
     *     exposure /
     *     target LTV
     *
     * required collateral gold =
     *     required collateral USD /
     *     current gold price
     *
     * The required pool is the SUM of the current requirements
     * of all active loans.
     *
     * loan.collateral is only the current DISTRIBUTION of that
     * shared pool across individual loans.
     * ==========================================================
     */
    v_stage :=
        'calculate required collateral pool';


    v_total_required_pool := 0;


    for v_loan in
        select
            loan_record.*
        from public.loan
            loan_record
        where loan_record.user_id =
              v_user.id
          and loan_record.status =
              'active'::public."LoanStatus"
        order by
            loan_record.created_at asc,
            loan_record.id asc
    loop
        select
            greatest(
                coalesce(
                    sum(
                        entry_record.debit_principal
                    ),
                    0
                ) -
                coalesce(
                    sum(
                        entry_record.credit_principal
                    ),
                    0
                ),
                0
            ),

            greatest(
                coalesce(
                    sum(
                        entry_record.debit_interest
                    ),
                    0
                ) -
                coalesce(
                    sum(
                        entry_record.credit_interest
                    ),
                    0
                ),
                0
            )
        into
            v_principal,
            v_interest
        from public.loan_entry
            entry_record
        where entry_record.loan_id =
              v_loan.id;


        if v_loan.country_code is distinct from v_user.country_code
           or lower(btrim(v_loan.currency_code)) is distinct from 'usd'
        then
            raise exception 'LOAN_PORTFOLIO_CONTEXT_MISMATCH';
        end if;
        if v_principal::text in ('NaN', 'Infinity', '-Infinity')
           or v_interest::text in ('NaN', 'Infinity', '-Infinity')
        then
            raise exception 'INVALID_LOAN_BALANCE';
        end if;

        v_exposure :=
            v_principal +
            v_interest;


        if v_exposure <= 0 then
            continue;
        end if;


        v_target_ltv :=
            coalesce(
                v_loan.max_ltv_percent,
                0
            );


        if v_target_ltv::text in ('NaN', 'Infinity', '-Infinity')
           or v_target_ltv <= 0
           or v_target_ltv >= 100
        then
            raise exception
                'INVALID_LOAN_LTV_CONFIGURATION';
        end if;


        /*
         * Example:
         *
         * max_ltv_percent = 60.00
         *
         * target LTV =
         *
         * 60.00 / 100
         * =
         * 0.60
         */
        v_target_collateral := ceil(
            v_exposure * 100 / (v_target_ltv * v_gold_price) * 1000000
        ) / 1000000;


        v_total_required_pool :=
            v_total_required_pool +
            v_target_collateral;
    end loop;


    /*
     * Keep the portfolio requirement itself at six decimals,
     * matching the sum of its individual loan allocations.
     */
    v_total_required_pool :=
        round(
            v_total_required_pool,
            6
        );


    /*
     * ==========================================================
     * CALCULATE CURRENT POOL SHORTAGE
     * ==========================================================
     *
     * This is the fundamental pooled-collateral calculation:
     *
     * shortage =
     *
     *     current collateral required by all active loans
     *
     *     MINUS
     *
     *     actual consolidated gold currently locked
     * ==========================================================
     */
    v_collateral_shortage :=
        greatest(
            v_total_required_pool -
            v_previous_locked,
            0
        );


    /*
     * ==========================================================
     * NOTHING NEEDS TO BE ADDED
     * ==========================================================
     *
     * The actual pooled collateral is already sufficient to
     * cover all current active loan exposure at the configured
     * target LTVs.
     *
     * Do not lock additional gold merely because the user
     * authorised an amount.
     * ==========================================================
     */
    if v_collateral_shortage <= 0 then
        return query
        select
            true,

            false,

            to_char(
                v_requested_collateral,
                'FM999999999999999999999999990.000000'
            ),

            '0.000000'::text,

            to_char(
                v_requested_collateral,
                'FM999999999999999999999999990.000000'
            ),

            '0.000000'::text,

            to_char(
                round(
                    v_previous_locked,
                    6
                ),
                'FM999999999999999999999999990.000000'
            ),

            to_char(
                round(
                    v_previous_locked,
                    6
                ),
                'FM999999999999999999999999990.000000'
            ),

            0;

        return;
    end if;


    /*
     * ==========================================================
     * DETERMINE ACTUAL GOLD TO ADD
     * ==========================================================
     *
     * The signed requested amount is a MAXIMUM authorization.
     *
     * Example:
     *
     * requested = 0.100000
     * shortage  = 0.050000
     *
     * add only:
     *
     * 0.050000
     *
     * The remaining 0.050000 remains available to the user.
     * ==========================================================
     */
    v_collateral_added :=
        least(
            v_requested_collateral,
            v_collateral_shortage
        );


    /*
     * collateral_entry can persist only six decimal places.
     */
    v_collateral_added :=
        trunc(
            v_collateral_added,
            6
        );


    if v_collateral_added <= 0 then
        return query
        select
            true,

            true,

            to_char(
                v_requested_collateral,
                'FM999999999999999999999999990.000000'
            ),

            '0.000000'::text,

            to_char(
                v_requested_collateral,
                'FM999999999999999999999999990.000000'
            ),

            to_char(
                v_collateral_shortage,
                'FM999999999999999999999999990.000000'
            ),

            to_char(
                round(
                    v_previous_locked,
                    6
                ),
                'FM999999999999999999999999990.000000'
            ),

            to_char(
                round(
                    v_previous_locked,
                    6
                ),
                'FM999999999999999999999999990.000000'
            ),

            0;

        return;
    end if;


    /*
     * ==========================================================
     * CHECK AVAILABLE BLOCKCHAIN GOLD
     * ==========================================================
     *
     * IMPORTANT:
     *
     * Validate the amount ACTUALLY being locked.
     *
     * Do not reject a request merely because the user authorised
     * more than is necessary.
     *
     * Example:
     *
     * requested       = 0.100000
     * required        = 0.050000
     * available       = 0.060000
     *
     * This is valid because only 0.050000 will be locked.
     * ==========================================================
     */
    v_stage :=
        'validate available collateral';


    v_available_tokens :=
        greatest(
            v_total_tokens -
            v_previous_locked,
            0
        );


    if v_collateral_added >
       v_available_tokens
    then
        raise exception
            'INSUFFICIENT_AVAILABLE_GOLD';
    end if;


    /*
     * ==========================================================
     * UPDATE CONSOLIDATED COLLATERAL POOL
     * ==========================================================
     *
     * The pool is updated BEFORE its distribution across active
     * loans.
     *
     * Only the amount actually required and authorised is added.
     * ==========================================================
     */
    v_stage :=
        'update consolidated collateral';


    update public.collateral
    set
        locked_tokens =
            coalesce(
                locked_tokens,
                0
            ) +
            v_collateral_added,
        updated_at = now()
    where id = v_collateral.id
      and user_id = v_user.id
    returning
        locked_tokens
    into
        v_new_locked;


    if not found then
        raise exception
            'COLLATERAL_UPDATE_FAILED';
    end if;

    if v_new_locked <> v_previous_locked + v_collateral_added then
        raise exception 'COLLATERAL_POOL_UPDATE_MISMATCH';
    end if;


    /*
     * ==========================================================
     * REDISTRIBUTE ACTUAL POOL ACROSS ACTIVE LOANS
     * ==========================================================
     *
     * loan.collateral represents the CURRENT allocation of the
     * shared collateral pool to that individual loan.
     *
     * It is therefore recalculated rather than incremented.
     *
     * Allocation order:
     *
     * oldest active loan
     *     ↓
     * next oldest
     *     ↓
     * until the actual pool is exhausted.
     *
     * If the pool is sufficient, every loan receives its full
     * target collateral.
     *
     * If the top-up was only partial, later loans may remain
     * partially covered or uncovered.
     *
     * Existing pool gold is allocated first.
     *
     * Only allocation originating from v_collateral_added
     * creates new collateral_entry debit rows.
     * ==========================================================
     */
    v_stage :=
        'redistribute collateral pool';


    v_remaining_pool :=
        v_new_locked;

    v_existing_pool_remaining :=
        v_previous_locked;

    v_new_gold_remaining :=
        v_collateral_added;

    v_loans_adjusted :=
        0;


    for v_loan in
        select
            loan_record.*
        from public.loan
            loan_record
        where loan_record.user_id =
              v_user.id
          and loan_record.status =
              'active'::public."LoanStatus"
        order by
            loan_record.created_at asc,
            loan_record.id asc
    loop
        /*
         * ------------------------------------------------------
         * CURRENT OUTSTANDING EXPOSURE
         * ------------------------------------------------------
         */
        select
            greatest(
                coalesce(
                    sum(
                        entry_record.debit_principal
                    ),
                    0
                ) -
                coalesce(
                    sum(
                        entry_record.credit_principal
                    ),
                    0
                ),
                0
            ),

            greatest(
                coalesce(
                    sum(
                        entry_record.debit_interest
                    ),
                    0
                ) -
                coalesce(
                    sum(
                        entry_record.credit_interest
                    ),
                    0
                ),
                0
            )
        into
            v_principal,
            v_interest
        from public.loan_entry
            entry_record
        where entry_record.loan_id =
              v_loan.id;


        if v_loan.country_code is distinct from v_user.country_code
           or lower(btrim(v_loan.currency_code)) is distinct from 'usd'
        then
            raise exception 'LOAN_PORTFOLIO_CONTEXT_MISMATCH';
        end if;
        if v_principal::text in ('NaN', 'Infinity', '-Infinity')
           or v_interest::text in ('NaN', 'Infinity', '-Infinity')
        then
            raise exception 'INVALID_LOAN_BALANCE';
        end if;

        v_exposure :=
            v_principal +
            v_interest;


        /*
         * An active loan with no remaining exposure receives no
         * collateral allocation.
         */
        if v_exposure <= 0 then
            v_target_collateral := 0;
        else
            v_target_ltv :=
                coalesce(
                    v_loan.max_ltv_percent,
                    0
                );


            if v_target_ltv::text in ('NaN', 'Infinity', '-Infinity')
               or v_target_ltv <= 0
               or v_target_ltv >= 100
            then
                raise exception
                    'INVALID_LOAN_LTV_CONFIGURATION';
            end if;


            v_target_collateral := ceil(
                v_exposure * 100 / (v_target_ltv * v_gold_price) * 1000000
            ) / 1000000;
        end if;


        /*
         * Allocate only gold that actually exists in the pool.
         */
        v_allocation :=
            least(
                v_target_collateral,
                greatest(
                    v_remaining_pool,
                    0
                )
            );


        v_allocation :=
            trunc(
                v_allocation,
                6
            );


        /*
         * ------------------------------------------------------
         * IDENTIFY EXISTING POOL VS NEW TOP-UP
         * ------------------------------------------------------
         *
         * Existing pool collateral is consumed first during the
         * redistribution.
         *
         * Any portion beyond that is newly locked gold belonging
         * to this operation and therefore receives a new
         * collateral_entry.
         * ------------------------------------------------------
         */
        v_existing_allocation :=
            least(
                v_allocation,
                greatest(
                    v_existing_pool_remaining,
                    0
                )
            );


        v_existing_allocation :=
            trunc(
                v_existing_allocation,
                6
            );


        v_new_allocation :=
            greatest(
                v_allocation -
                v_existing_allocation,
                0
            );


        v_new_allocation :=
            least(
                v_new_allocation,
                greatest(
                    v_new_gold_remaining,
                    0
                )
            );


        v_new_allocation :=
            trunc(
                v_new_allocation,
                6
            );


        /*
         * ------------------------------------------------------
         * SYNCHRONISE INDIVIDUAL LOAN ALLOCATION
         * ------------------------------------------------------
         *
         * DO NOT:
         *
         *     loan.collateral += top_up
         *
         * The old value may represent a position calculated at
         * a different:
         *
         * - gold price;
         * - principal balance;
         * - interest balance;
         * - liquidation state;
         * - repayment state.
         *
         * Instead loan.collateral becomes the amount of today's
         * actual pooled collateral allocated to that loan.
         * ------------------------------------------------------
         */
        v_previous_loan_allocation :=
            greatest(
                coalesce(
                    v_loan.collateral,
                    0
                ),
                0
            );


        if v_previous_loan_allocation
           is distinct from
           v_allocation
        then
            v_stage :=
                'update loan collateral allocation';


            update public.loan
            set
                collateral =
                    v_allocation,
                updated_at = now()
            where id =
                  v_loan.id;


            if not found then
                raise exception
                    'LOAN_COLLATERAL_UPDATE_FAILED';
            end if;


            v_loans_adjusted :=
                v_loans_adjusted +
                1;
        end if;


        v_liquidation_price := 0;
        if v_exposure > 0 and v_allocation > 0 then
            if v_loan.liquidation_ltv is null
               or v_loan.liquidation_ltv::text in ('NaN', 'Infinity', '-Infinity')
               or v_loan.liquidation_ltv <= 0
               or v_loan.liquidation_ltv > 100
            then
                raise exception 'INVALID_LIQUIDATION_LTV';
            end if;
            v_liquidation_price := trunc(
                v_exposure / (v_allocation * v_loan.liquidation_ltv / 100), 6
            );
        end if;
        update public.loan
        set liquidation_price = v_liquidation_price,
            updated_at = now()
        where id = v_loan.id;

        /*
         * ------------------------------------------------------
         * CREATE LEDGER ENTRY FOR NEW GOLD ONLY
         * ------------------------------------------------------
         *
         * Existing pooled gold is merely being redistributed.
         * It must not be posted again.
         *
         * Only newly locked gold from this request creates a
         * collateral_entry debit.
         * ------------------------------------------------------
         */
        if v_new_allocation > 0 then
            v_stage :=
                'create collateral entry';


            insert into public.collateral_entry (
                loan_id,
                document_number,
                reference,
                debit,
                credit,
                country_code
            )
            values (
                v_loan.id,
                v_reference,
                v_reference,
                v_new_allocation,
                0,
                v_user.country_code
            );
            v_posted_debits := v_posted_debits + v_new_allocation;
        end if;


        /*
         * ------------------------------------------------------
         * REDUCE REMAINING POOL
         * ------------------------------------------------------
         */
        v_remaining_pool :=
            greatest(
                v_remaining_pool -
                v_allocation,
                0
            );


        v_existing_pool_remaining :=
            greatest(
                v_existing_pool_remaining -
                v_existing_allocation,
                0
            );


        v_new_gold_remaining :=
            greatest(
                v_new_gold_remaining -
                v_new_allocation,
                0
            );
    end loop;


    /*
     * ==========================================================
     * SAFETY CHECK: NEW GOLD MUST BE ACCOUNTED FOR
     * ==========================================================
     *
     * Because the new pool cannot exceed the calculated required
     * pool, all newly added gold should have been assigned to an
     * active loan.
     *
     * A remaining new amount indicates that the portfolio changed
     * unexpectedly or the allocation calculation is inconsistent.
     * ==========================================================
     */
    if v_new_gold_remaining <> 0
       or v_existing_pool_remaining <> 0
       or v_remaining_pool <> 0
       or v_posted_debits <> v_collateral_added
    then
        raise exception
            'COLLATERAL_ALLOCATION_MISMATCH';
    end if;


    /*
     * ==========================================================
     * FETCH FISCAL PERIOD
     * ==========================================================
     */
    v_stage :=
        'fetch fiscal period';


    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_user.country_code
    ) as fiscal_period;


    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * UPDATE COLLATERAL SNAPSHOT
     * ==========================================================
     *
     * Only newly locked collateral changes the consolidated
     * balance snapshot.
     *
     * Redistributing existing pooled collateral across loans
     * does not change the user's total locked gold.
     * ==========================================================
     */
    v_stage :=
        'update collateral snapshot';


    perform public.update_collateral_snapshot(
        v_user.id,
        v_user.country_code,
        v_collateral_added,
        0::numeric,
        v_fiscal_year,
        v_period
    );


    /*
     * ==========================================================
     * CALCULATE REMAINING PORTFOLIO SHORTAGE
     * ==========================================================
     */
    v_remaining_required :=
        greatest(
            v_total_required_pool -
            v_new_locked,
            0
        );


    /*
     * Keep the externally reported requirement at six decimal
     * places.
     */
    v_remaining_required :=
        ceil(
            v_remaining_required *
            1000000
        ) /
        1000000;


    /*
     * ==========================================================
     * RETURN RESULT
     * ==========================================================
     */
    return query
    select
        true,

        /*
         * true means the pool is STILL below target after this
         * operation.
         */
        v_remaining_required > 0,

        to_char(
            v_requested_collateral,
            'FM999999999999999999999999990.000000'
        ),

        to_char(
            v_collateral_added,
            'FM999999999999999999999999990.000000'
        ),

        to_char(
            greatest(
                v_requested_collateral -
                v_collateral_added,
                0
            ),
            'FM999999999999999999999999990.000000'
        ),

        to_char(
            v_remaining_required,
            'FM999999999999999999999999990.000000'
        ),

        to_char(
            round(
                v_previous_locked,
                6
            ),
            'FM999999999999999999999999990.000000'
        ),

        to_char(
            round(
                v_new_locked,
                6
            ),
            'FM999999999999999999999999990.000000'
        ),

        v_loans_adjusted;


exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;


        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'ADDITIONAL_COLLATERAL_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                coalesce(
                    nullif(
                        concat_ws(
                            E'\n',
                            nullif(
                                v_error_detail,
                                ''
                            ),
                            nullif(
                                v_error_context,
                                ''
                            )
                        ),
                        ''
                    ),
                    'No additional PostgreSQL context'
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    'Check the Additional Collateral stage reported in the error'
                );
end;
$$;
ALTER FUNCTION "public"."execute_my_additional_collateral"("p_requested_collateral" "text", "p_token_balance" "text", "p_reference" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."execute_my_agent_commission_settlement_batch"("p_batch_id" "text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;
    v_batch public.agent_settlement_batch%rowtype;
    v_item public.agent_settlement_item%rowtype;
    v_agent public.users%rowtype;
    v_treasury public.users%rowtype;
    v_receiver_wallet public.wallet%rowtype;

    v_batch_id text;

    v_fiscal_year integer;
    v_period integer;

    v_mappings
        public.transaction_gl_mapping[];

    v_components
        public.posting_component[];

    v_wallet_owners
        public.transaction_type_wallet_owner%rowtype;

    v_document_prefix text;
    v_document_number text;
    v_reference text;

    v_financial_transaction_id
        public.financial_transaction.id%type;

    v_amount numeric;

    v_commission_rows integer := 0;
    v_commission_total numeric := 0;

    v_eligible_items integer := 0;
    v_remaining_items integer := 0;

    v_success_count integer := 0;
    v_failed_count integer := 0;

    v_final_status
        public."SettlementStatus";

    v_item_error text;

    v_stage text :=
        'initialization';

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * Authentication and Accounts authorization.
     */
    v_stage :=
        'authorize accounts user';

    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'accounts'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Validate input.
     */
    v_stage :=
        'validate input';

    v_batch_id :=
        nullif(
            btrim(p_batch_id),
            ''
        );

    if v_batch_id is null then
        raise exception
            'SETTLEMENT_BATCH_ID_REQUIRED';
    end if;

    /*
     * Fetch trusted Accounts user.
     */
    v_stage :=
        'fetch accounts user';

    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'ACCOUNTS_USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'ACCOUNTS_USER_NOT_ACTIVE';
    end if;

    if nullif(
        btrim(v_user.country_code),
        ''
    ) is null
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Lock the batch.
     *
     * The row lock prevents two Accounts users from
     * executing the same batch concurrently.
     */
    v_stage :=
        'lock settlement batch';

    select batch_record.*
    into v_batch
    from public.agent_settlement_batch
        batch_record
    where batch_record.id::text =
              v_batch_id

      and lower(
          btrim(
              batch_record.country_code
          )
      ) =
          lower(
              btrim(
                  v_user.country_code
              )
          )
    for update;

    if not found then
        raise exception
            'AGENT_COMMISSION_SETTLEMENT_BATCH_NOT_FOUND';
    end if;

    if v_batch.status::text not in (
        'approved',
        'partial'
    ) then
        raise exception
            'ONLY_APPROVED_OR_PARTIAL_BATCHES_CAN_BE_SETTLED';
    end if;

    /*
     * Fetch current fiscal period.
     */
    v_stage :=
        'fetch fiscal period';

    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_batch.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Fetch the country treasury.
     */
    v_stage :=
        'fetch country treasury';

    select treasury_record.*
    into v_treasury
    from public.fetch_country_treasury(
        v_batch.country_code
    ) as treasury_record;

    if not found
       or v_treasury.id is null
    then
        raise exception
            'TREASURY_NOT_FOUND';
    end if;

    /*
     * Fetch GL mappings.
     *
     * Expected principal mapping:
     *
     * Dr Agent Commission Payable
     * Cr Cash/Bank Reserve
     */
    v_stage :=
        'fetch gl mappings';

    select array_agg(
        mapping_record
        order by
            mapping_record.component_type
    )
    into v_mappings
    from public.fetch_gl_mappings(
        'agent_commission_settlement'::public."TransactionType"
    ) as mapping_record;

    if v_mappings is null
       or cardinality(v_mappings) = 0
    then
        raise exception
            'AGENT_COMMISSION_SETTLEMENT_GL_MAPPINGS_NOT_FOUND';
    end if;

    /*
     * Fetch and validate wallet-owner configuration.
     *
     * Commission is paid from Treasury into the
     * facilitator's customer wallet.
     */
    v_stage :=
        'fetch wallet owner configuration';

    select wallet_owner_record.*
    into v_wallet_owners
    from public.fetch_transaction_type_wallet_owner(
        'agent_commission_settlement'::public."TransactionType"
    ) as wallet_owner_record;

    if not found then
        raise exception
            'AGENT_COMMISSION_SETTLEMENT_WALLET_OWNER_NOT_FOUND';
    end if;

    if v_wallet_owners.sender_wallet_owner <>
       'treasury'::public."WalletOwnerType"
    then
        raise exception
            'AGENT_COMMISSION_SETTLEMENT_SENDER_WALLET_MUST_BE_TREASURY';
    end if;

    if v_wallet_owners.receiver_wallet_owner <>
       'customer'::public."WalletOwnerType"
    then
        raise exception
            'AGENT_COMMISSION_SETTLEMENT_RECEIVER_WALLET_MUST_BE_CUSTOMER';
    end if;

    /*
     * Fetch document prefix.
     */
    v_stage :=
        'fetch document prefix';

    v_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            'agent_commission_settlement'::public."TransactionType"
        );

    if nullif(
        btrim(v_document_prefix),
        ''
    ) is null
    then
        raise exception
            'DOCUMENT_PREFIX_NOT_FOUND';
    end if;

    /*
     * Count items eligible for this execution.
     *
     * Failed items are included so a partial batch can
     * retry only its failed payments.
     */
    v_stage :=
        'count eligible settlement items';

    select count(*)::integer
    into v_eligible_items
    from public.agent_settlement_item
        item_record
    where item_record.batch_id =
              v_batch.id

      and item_record.status::text in (
          'approved',
          'failed'
      );

    if v_eligible_items = 0 then
        raise exception
            'NO_AGENT_COMMISSION_SETTLEMENT_ITEMS_TO_PROCESS';
    end if;

    /*
     * Mark the batch as processing.
     */
    v_stage :=
        'mark batch processing';

    update public.agent_settlement_batch
    set
        status =
            'processing'::public."SettlementStatus",

        error_message =
            null
    where id =
          v_batch.id;

    if not found then
        raise exception
            'AGENT_COMMISSION_BATCH_PROCESSING_UPDATE_FAILED';
    end if;

    /*
     * Process each approved or previously failed item.
     *
     * The nested begin/exception block is a PostgreSQL
     * subtransaction. Failure rolls back only the
     * current item's accounting and wallet movements.
     */
    for v_item in
        select item_record.*
        from public.agent_settlement_item
            item_record
        where item_record.batch_id =
                  v_batch.id

          and item_record.status::text in (
              'approved',
              'failed'
          )
        order by
            item_record.agent_id,
            item_record.id
        for update
    loop
        begin
            v_item_error :=
                null;

            v_amount :=
                coalesce(
                    v_item.total_commission,
                    0
                );

            if v_amount <= 0 then
                raise exception
                    'INVALID_AGENT_COMMISSION_SETTLEMENT_AMOUNT';
            end if;

    /*
    * Validate the facilitator.
    *
    * Agent, vendor and merchant roles can earn
    * cash-withdrawal commission.
    */
    v_stage :=
        'validate settlement recipient';

    select agent_record.*
    into v_agent
    from public.users
        agent_record
    join public.user_role
        role_record
    on role_record.id =
        agent_record.role_id
    where agent_record.id =
            v_item.agent_id

    and agent_record.status =
            'active'::public."UserStatus"

    and lower(
        btrim(
            agent_record.country_code
        )
    ) =
        lower(
            btrim(
                v_batch.country_code
            )
        )

    and lower(
        role_record.name::text
    ) in (
        'agent',
        'vendor',
        'merchant'
    )
    limit 1;

    if not found then
        raise exception
            'COMMISSION_RECIPIENT_NOT_AUTHORIZED_%',
            v_item.agent_id;
    end if;

    /*
    * Do not require the receiver wallet to exist here.
    *
    * post_wallet_entries creates the customer wallet when
    * it does not exist. Only the sender treasury wallet is
    * required to exist before posting.
    */

    /*
    * Lock and validate the underlying commission records.
    */
    v_stage :=
        'lock underlying commissions';

    perform 1
    from public.agent_commission
        commission_record
    where commission_record.settlement_batch_id =
            v_batch.id

    and commission_record.agent_id =
            v_agent.id

    and lower(
        btrim(
            commission_record.currency_code
        )
    ) =
        lower(
            btrim(
                v_batch.currency_code
            )
        )

    and commission_record.is_settled =
            false
    for update;
            /*
             * Mark this item as processing.
             */
            v_stage :=
                'mark settlement item processing';

            update public.agent_settlement_item
            set
                status =
                    'processing'::public."SettlementStatus",

                error_message =
                    null
            where id =
                  v_item.id;

            /*
             * Build the GL posting components.
             */
            v_stage :=
                'build posting components';

            v_components :=
                public.build_posting_components(
                    'agent_commission_settlement'::public."TransactionType",
                    v_amount,
                    v_mappings,
                    v_batch.country_code,
                    lower(
                        btrim(
                            v_batch.currency_code
                        )
                    ),
                    false
                );

            if v_components is null
               or cardinality(v_components) = 0
            then
                raise exception
                    'AGENT_COMMISSION_SETTLEMENT_COMPONENTS_NOT_FOUND';
            end if;

            v_components :=
                public.validate_components(
                    v_components
                );

            /*
             * Generate one financial document for this
             * settlement item.
             */
            v_stage :=
                'generate document number';

            v_document_number :=
                public.generate_document_number(
                    v_document_prefix,
                    v_fiscal_year,
                    v_period,
                    v_batch.country_code
                );

            v_reference :=
                format(
                    '%s_%s',
                    v_batch.document_number,
                    v_agent.id
                );

            /*
             * Create financial transaction header.
             */
            v_stage :=
                'create financial transaction';

            insert into public.financial_transaction (
                document_number,
                reference,
                fiscal_year,
                period,
                transaction_type,
                description,
                created_by,
                gross_amount,
                currency_code,
                country_code
            )
            values (
                v_document_number,
                v_reference,
                v_fiscal_year,
                v_period,
                'agent_commission_settlement'::public."TransactionType",

                format(
                    'Commission settlement for facilitator %s from batch %s',
                    v_agent.id,
                    v_batch.document_number
                ),

                v_user.id,
                v_amount,
                lower(
                    btrim(
                        v_batch.currency_code
                    )
                ),
                v_batch.country_code
            )
            returning id
            into v_financial_transaction_id;

            /*
             * Post:
             *
             * Dr Agent Commission Payable
             * Cr Cash/Bank Reserve
             */
            v_stage :=
                'post financial entries';

            perform *
            from public.post_financial_entries(
                p_document_number =>
                    v_document_number,

                p_country_code =>
                    v_batch.country_code,

                p_transaction_id =>
                    v_financial_transaction_id,

                p_transaction_type =>
                    'agent_commission_settlement'::public."TransactionType",

                p_created_by =>
                    v_user.id,

                p_components =>
                    v_components,

                p_mappings =>
                    v_mappings,

                p_currency_code =>
                    lower(
                        btrim(
                            v_batch.currency_code
                        )
                    ),

                p_fiscal_year =>
                    v_fiscal_year,

                p_period =>
                    v_period,

                p_reference =>
                    v_reference,

                p_deposit_type =>
                    null
            );

            /*
             * Wallet posting:
             *
             * Dr/outgoing Treasury wallet
             * Cr/incoming Customer wallet
             */
            v_stage :=
                'post wallet entries';

            perform *
            from public.post_wallet_entries(
                p_fiscal_year =>
                    v_fiscal_year,

                p_period =>
                    v_period,

                p_document_number =>
                    v_document_number,

                p_reference =>
                    v_reference,

                p_receiver_id =>
                    v_agent.id,

                p_sender_id =>
                    v_treasury.id,

                p_transaction_type =>
                    'agent_commission_settlement'::public."TransactionType",

                p_credit_amount =>
                    v_amount,

                p_debit_amount =>
                    v_amount,

                p_sender_wallet_owner =>
                    'treasury'::public."WalletOwnerType",

                p_receiver_wallet_owner =>
                    'customer'::public."WalletOwnerType",

                p_currency_code =>
                    lower(
                        btrim(
                            v_batch.currency_code
                        )
                    ),

                p_country_code =>
                    v_batch.country_code,

                p_audit_action_type =>
                    v_wallet_owners.audit_action_type,

                p_treasury_id =>
                    v_treasury.id,

                p_fee_amount =>
                    0,

                p_ip_address =>
                    p_ip_address,

                p_receiver_notification =>
                    null,

                p_sender_notification =>
                    null
            );

            /*
             * Mark underlying commission records settled.
             */
            v_stage :=
                'settle underlying commissions';

            update public.agent_commission
            set
                is_settled =
                    true,

                settled_at =
                    now(),

                settled_by =
                    v_user.id
            where settlement_batch_id =
                      v_batch.id

              and agent_id =
                      v_agent.id

              and lower(
                  btrim(
                      currency_code
                  )
              ) =
                  lower(
                      btrim(
                          v_batch.currency_code
                      )
                  )

              and is_settled =
                      false;

            get diagnostics
                v_commission_rows =
                    row_count;

            if v_commission_rows = 0 then
                raise exception
                    'AGENT_COMMISSION_ROWS_NOT_UPDATED';
            end if;

            /*
             * Mark the settlement item successful.
             */
            v_stage :=
                'complete settlement item';

            update public.agent_settlement_item
            set
                status =
                    'settled'::public."SettlementStatus",

                paid_at =
                    now(),

                error_message =
                    null
            where id =
                  v_item.id;

            if not found then
                raise exception
                    'AGENT_COMMISSION_SETTLEMENT_ITEM_UPDATE_FAILED';
            end if;

            v_success_count :=
                v_success_count + 1;

        exception
            when others then
                get stacked diagnostics
                    v_item_error =
                        message_text;

                /*
                 * The nested block rollback has removed
                 * any partial GL and wallet movements for
                 * this item. Only the failed status is
                 * stored outside that subtransaction.
                 */
                update public.agent_settlement_item
                set
                    status =
                        'failed'::public."SettlementStatus",

                    error_message =
                        left(
                            coalesce(
                                v_item_error,
                                'UNKNOWN_SETTLEMENT_ERROR'
                            ),
                            1000
                        )
                where id =
                      v_item.id;

                v_failed_count :=
                    v_failed_count + 1;
        end;
    end loop;

    /*
     * Determine whether any item remains unsettled.
     */
    v_stage :=
        'calculate final batch status';

    select count(*)::integer
    into v_remaining_items
    from public.agent_settlement_item
        item_record
    where item_record.batch_id =
              v_batch.id

      and item_record.status::text <>
              'settled';

    if v_remaining_items = 0 then
        v_final_status :=
            'settled'::public."SettlementStatus";
    else
        v_final_status :=
            'partial'::public."SettlementStatus";
    end if;

    /*
     * Complete the batch.
     *
     * paid_at records that payment processing occurred,
     * including partially successful execution.
     */
    v_stage :=
        'complete settlement batch';

    update public.agent_settlement_batch
    set
        status =
            v_final_status,

        paid_at =
            case
                when v_success_count > 0
                then coalesce(
                    paid_at,
                    now()
                )
                else paid_at
            end,

        error_message =
            case
                when v_final_status::text = 'partial'
                then format(
                    '%s settlement item(s) failed',
                    v_failed_count
                )
                else null
            end
    where id =
          v_batch.id
    returning *
    into v_batch;

    /*
     * Audit the execution.
     */
    v_stage :=
        'create audit log';

    insert into public.audit_log (
        user_id,
        country_code,
        fiscal_year,
        period,
        action_type,
        entity_type,
        entity_id,
        document_number,
        metadata,
        ip_address
    )
    values (
        v_user.id,
        v_batch.country_code,
        v_fiscal_year,
        v_period,
        'agent_settlement_settled'::public."AuditActionType",
        'agent_settlement_batch',
        v_batch.id::text,
        v_batch.document_number,

        jsonb_build_object(
            'processed',
            v_success_count +
            v_failed_count,

            'success_count',
            v_success_count,

            'failed_count',
            v_failed_count,

            'remaining_items',
            v_remaining_items,

            'status',
            v_final_status
        ),

        p_ip_address
    );

    return jsonb_build_object(
        'success',
        true,

        'batch_id',
        v_batch.id,

        'document_number',
        v_batch.document_number,

        'currency_code',
        v_batch.currency_code,

        'status',
        v_final_status,

        'processed',
        v_success_count +
        v_failed_count,

        'success_count',
        v_success_count,

        'failed_count',
        v_failed_count,

        'remaining_items',
        v_remaining_items
    );

exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;

        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'AGENT_COMMISSION_SETTLEMENT_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                concat_ws(
                    E'\n',
                    nullif(
                        v_error_detail,
                        ''
                    ),
                    nullif(
                        v_error_context,
                        ''
                    )
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    'Check the Agent Commission Settlement stage'
                );
end;
$$;
ALTER FUNCTION "public"."execute_my_agent_commission_settlement_batch"("p_batch_id" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."execute_my_agent_funding"("p_transaction_type" "public"."TransactionType", "p_agent_identifier" "text" DEFAULT NULL::"text", "p_currency_code" "text" DEFAULT NULL::"text", "p_amount" numeric DEFAULT NULL::numeric, "p_reference" "text" DEFAULT NULL::"text", "p_document_number" "text" DEFAULT NULL::"text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_executor public.users%rowtype;
    v_treasury public.users%rowtype;
    v_agent public.users%rowtype;

    v_original_funding
        public.financial_transaction%rowtype;

    v_original_deposit
        public.financial_transaction%rowtype;

    v_is_reversal boolean;

    v_identifier text;
    v_currency_code text;
    v_amount numeric;
    v_reference text;

    v_fiscal_year integer;
    v_period integer;

    v_funding_transaction_type
        public."TransactionType";

    v_deposit_transaction_type
        public."TransactionType";

    v_funding_mappings
        public.transaction_gl_mapping[];

    v_deposit_mappings
        public.transaction_gl_mapping[];

    v_funding_components
        public.posting_component[];

    v_deposit_components
        public.posting_component[];

    v_funding_prefix text;
    v_deposit_prefix text;

    v_funding_document_number text;
    v_deposit_document_number text;

    v_funding_transaction_id
        public.financial_transaction.id%type;

    v_deposit_transaction_id
        public.financial_transaction.id%type;

    v_sender_id text;
    v_receiver_id text;

    v_sender_wallet_owner
        public."WalletOwnerType";

    v_receiver_wallet_owner
        public."WalletOwnerType";

    v_audit_action
        public."AuditActionType";

    v_funding_description text;
    v_deposit_description text;

    v_receiver_notification
        public.notification_message;

    v_stage text := 'initialization';
    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * Authenticate and authorize treasury.
     */
    v_stage := 'authorize treasury user';

    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if not public.has_role(
        array[
            'treasury'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Validate transaction type.
     */
    v_stage := 'validate transaction type';

    if p_transaction_type not in (
        'agent_funding'::public."TransactionType",
        'agent_funding_reversal'::public."TransactionType"
    ) then
        raise exception
            'INVALID_AGENT_FUNDING_TRANSACTION_TYPE';
    end if;

    v_is_reversal :=
        p_transaction_type =
        'agent_funding_reversal'::public."TransactionType";

    v_funding_transaction_type :=
        p_transaction_type;

    v_deposit_transaction_type :=
        case
            when v_is_reversal then
                'agent_deposit_reversal'::public."TransactionType"
            else
                'agent_deposit'::public."TransactionType"
        end;

    /*
     * Fetch authenticated user.
     */
    v_stage := 'fetch authenticated user';

    v_executor :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_executor.id is null then
        raise exception
            'TREASURY_USER_NOT_FOUND';
    end if;

    if v_executor.country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Fetch country treasury.
     */
    v_stage := 'fetch country treasury';

    v_treasury :=
        public.fetch_country_treasury(
            v_executor.country_code
        );

    if v_treasury.id is null then
        raise exception
            'TREASURY_NOT_FOUND';
    end if;

    /*
     * Normal agent funding.
     */
    if not v_is_reversal then
        v_stage := 'validate funding input';

        v_identifier :=
            nullif(
                btrim(p_agent_identifier),
                ''
            );

        if v_identifier is null then
            raise exception
                'AGENT_IDENTIFIER_REQUIRED';
        end if;

        v_currency_code :=
            lower(
                nullif(
                    btrim(p_currency_code),
                    ''
                )
            );

        if v_currency_code is null then
            raise exception
                'CURRENCY_REQUIRED';
        end if;

        v_amount :=
            public.round_down(p_amount);

        if v_amount is null
           or v_amount <= 0
        then
            raise exception
                'INVALID_AMOUNT';
        end if;

        v_reference :=
            nullif(
                btrim(p_reference),
                ''
            );

        if v_reference is null then
            raise exception
                'REFERENCE_REQUIRED';
        end if;

        /*
         * An agent-operation recipient may have an agent,
         * vendor, or merchant account role.
         */
        v_stage := 'fetch funding recipient';

        select user_record.*
        into v_agent
        from public.users user_record
        join public.user_role role_record
          on role_record.id =
             user_record.role_id
        where user_record.country_code =
              v_executor.country_code

          and user_record.status =
              'active'::public."UserStatus"

          and lower(
              role_record.name::text
          ) in (
              'agent',
              'vendor',
              'merchant'
          )

          and (
              lower(
                  user_record.email
              ) =
                  lower(v_identifier)

              or user_record.phone =
                  v_identifier
          )
        limit 1;

        if not found then
            raise exception
                'AGENT_VENDOR_OR_MERCHANT_NOT_FOUND';
        end if;

        /*
         * Prevent duplicate request reference.
         */
        v_stage := 'check funding reference';

        perform 1
        from public.financial_transaction
            transaction_record
        where transaction_record.reference =
              v_reference
        limit 1;

        if found then
            raise exception
                'TRANSACTION_REPLAY';
        end if;

        v_sender_id :=
            v_treasury.id;

        v_receiver_id :=
            v_agent.id;

        /*
         * Vendor and merchant users are funded through their
         * agent-operation wallet.
         */
        v_sender_wallet_owner :=
            'treasury'::public."WalletOwnerType";

        v_receiver_wallet_owner :=
            'agent'::public."WalletOwnerType";

        v_audit_action :=
            'agent_funded'::public."AuditActionType";

        v_funding_description :=
            format(
                'Agent funding %s',
                coalesce(
                    v_agent.email,
                    v_agent.phone,
                    v_agent.id
                )
            );

        v_deposit_description :=
            format(
                'Agent deposit %s',
                coalesce(
                    v_agent.email,
                    v_agent.phone,
                    v_agent.id
                )
            );
    end if;

    /*
     * Agent funding reversal.
     */
    if v_is_reversal then
        v_stage := 'validate reversal document';

        if nullif(
            btrim(p_document_number),
            ''
        ) is null
        then
            raise exception
                'DOCUMENT_NUMBER_REQUIRED_FOR_REVERSAL';
        end if;

        /*
         * Lock original funding document.
         */
        v_stage := 'fetch original funding document';

        select transaction_record.*
        into v_original_funding
        from public.financial_transaction
            transaction_record
        where transaction_record.document_number =
              btrim(p_document_number)

          and transaction_record.country_code =
              v_executor.country_code
        for update;

        if not found then
            raise exception
                'DOCUMENT_NOT_FOUND';
        end if;

        if v_original_funding.transaction_type <>
           'agent_funding'::public."TransactionType"
        then
            raise exception
                'DOCUMENT_IS_NOT_AGENT_FUNDING';
        end if;

        /*
         * Prevent duplicate reversal.
         */
        v_stage := 'check duplicate reversal';

        perform 1
        from public.financial_transaction
            reversal_record
        where reversal_record.country_code =
              v_executor.country_code

          and reversal_record.transaction_type =
              'agent_funding_reversal'::public."TransactionType"

          and reversal_record.reversal_of =
              v_original_funding.document_number
        limit 1;

        if found then
            raise exception
                'DOCUMENT_ALREADY_REVERSED';
        end if;

        /*
         * Fetch paired original agent-deposit document.
         */
        v_stage := 'fetch original deposit document';

        select transaction_record.*
        into v_original_deposit
        from public.financial_transaction
            transaction_record
        where transaction_record.country_code =
              v_executor.country_code

          and transaction_record.transaction_type =
              'agent_deposit'::public."TransactionType"

          and transaction_record.reference =
              v_original_funding.document_number
        for update;

        if not found then
            raise exception
                'AGENT_DEPOSIT_DOCUMENT_NOT_FOUND';
        end if;

        /*
         * Resolve original recipient through the agent wallet.
         *
         * The user may have the agent, vendor, or merchant role,
         * while the funded wallet owner remains agent.
         */
        v_stage := 'fetch original funding recipient';

        select user_record.*
        into v_agent
        from public.wallet_entry wallet_entry_record
        join public.wallet wallet_record
          on wallet_record.id =
             wallet_entry_record.wallet_id
        join public.users user_record
          on user_record.id =
             wallet_record.user_id
        join public.user_role role_record
          on role_record.id =
             user_record.role_id
        where wallet_entry_record.document_number =
              v_original_funding.document_number

          and wallet_entry_record.country_code =
              v_executor.country_code

          and wallet_record.owner_type =
              'agent'::public."WalletOwnerType"

          and lower(
              role_record.name::text
          ) in (
              'agent',
              'vendor',
              'merchant'
          )
        limit 1;

        if not found then
            raise exception
                'ORIGINAL_FUNDING_RECIPIENT_NOT_FOUND';
        end if;

        v_currency_code :=
            lower(
                v_original_funding.currency_code
            );

        v_amount :=
            v_original_funding.gross_amount;

        if v_amount is null
           or v_amount <= 0
        then
            raise exception
                'INVALID_ORIGINAL_AMOUNT';
        end if;

        v_reference :=
            v_original_funding.reference;

        v_sender_id :=
            v_agent.id;

        v_receiver_id :=
            v_treasury.id;

        v_sender_wallet_owner :=
            'agent'::public."WalletOwnerType";

        v_receiver_wallet_owner :=
            'treasury'::public."WalletOwnerType";

        v_audit_action :=
            'agent_fund_reversed'::public."AuditActionType";

        v_funding_description :=
            format(
                'Agent funding reversal %s',
                coalesce(
                    v_agent.email,
                    v_agent.phone,
                    v_agent.id
                )
            );

        v_deposit_description :=
            format(
                'Agent deposit reversal %s',
                coalesce(
                    v_agent.email,
                    v_agent.phone,
                    v_agent.id
                )
            );
    end if;

    /*
     * Fetch mappings.
     */
    v_stage := 'fetch funding mappings';

    select array_agg(mapping_record)
    into v_funding_mappings
    from public.fetch_gl_mappings(
        v_funding_transaction_type
    ) as mapping_record;

    if v_funding_mappings is null
       or cardinality(v_funding_mappings) = 0
    then
        raise exception
            'AGENT_FUNDING_GL_MAPPINGS_NOT_FOUND';
    end if;

    v_stage := 'fetch deposit mappings';

    select array_agg(mapping_record)
    into v_deposit_mappings
    from public.fetch_gl_mappings(
        v_deposit_transaction_type
    ) as mapping_record;

    if v_deposit_mappings is null
       or cardinality(v_deposit_mappings) = 0
    then
        raise exception
            'AGENT_DEPOSIT_GL_MAPPINGS_NOT_FOUND';
    end if;

    /*
     * Build posting components.
     */
    v_stage := 'build funding components';

    v_funding_components :=
        public.build_posting_components(
            v_funding_transaction_type,
            v_amount,
            v_funding_mappings,
            v_executor.country_code,
            v_currency_code,
            false
        );

    v_stage := 'build deposit components';

    v_deposit_components :=
        public.build_posting_components(
            v_deposit_transaction_type,
            v_amount,
            v_deposit_mappings,
            v_executor.country_code,
            v_currency_code,
            false
        );

    /*
     * Fiscal period.
     */
    v_stage := 'fetch fiscal period';

    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_executor.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Document prefixes.
     */
    v_stage := 'fetch funding document prefix';

    v_funding_prefix :=
        public.fetch_transaction_doc_num_prefix(
            v_funding_transaction_type
        );

    if nullif(
        btrim(v_funding_prefix),
        ''
    ) is null
    then
        raise exception
            'AGENT_FUNDING_DOCUMENT_PREFIX_NOT_FOUND';
    end if;

    v_stage := 'fetch deposit document prefix';

    v_deposit_prefix :=
        public.fetch_transaction_doc_num_prefix(
            v_deposit_transaction_type
        );

    if nullif(
        btrim(v_deposit_prefix),
        ''
    ) is null
    then
        raise exception
            'AGENT_DEPOSIT_DOCUMENT_PREFIX_NOT_FOUND';
    end if;

    /*
     * Generate document numbers.
     */
    v_stage := 'generate funding document number';

    v_funding_document_number :=
        public.generate_document_number(
            v_funding_prefix,
            v_fiscal_year,
            v_period,
            v_executor.country_code
        );

    v_stage := 'generate deposit document number';

    v_deposit_document_number :=
        public.generate_document_number(
            v_deposit_prefix,
            v_fiscal_year,
            v_period,
            v_executor.country_code
        );

    /*
     * Receiver notification.
     */
    v_stage := 'create receiver notification';

    v_receiver_notification :=
        public.create_notification_message(
            p_country_code =>
                v_executor.country_code,

            p_transaction_type =>
                v_funding_transaction_type,

            p_audience =>
                'receiver'::public."NotificationAudience",

            p_amount =>
                v_amount,

            p_currency =>
                upper(v_currency_code),

            p_reference =>
                case
                    when v_is_reversal then
                        v_funding_document_number
                    else
                        v_reference
                end,

            p_quantity =>
                0,

            p_sender =>
                coalesce(
                    case
                        when v_is_reversal
                            then v_agent.email
                        else v_treasury.email
                    end,
                    'Ngoda'
                ),

            p_receiver =>
                coalesce(
                    case
                        when v_is_reversal
                            then v_treasury.email
                        else v_agent.email
                    end,
                    v_receiver_id
                )
        );

    /*
     * Create agent-deposit transaction.
     */
    v_stage := 'create agent deposit transaction';

    insert into public.financial_transaction (
        fiscal_year,
        period,
        country_code,
        document_number,
        reference,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        reversal_of,
        reversed_by
    )
    values (
        v_fiscal_year,
        v_period,
        v_executor.country_code,
        v_deposit_document_number,
        v_funding_document_number,
        v_deposit_transaction_type,
        v_deposit_description,
        v_executor.id,
        v_amount,
        v_currency_code,
        case
            when v_is_reversal
                then v_original_deposit.document_number
            else null
        end,
        case
            when v_is_reversal
                then v_executor.id
            else null
        end
    )
    returning id
    into v_deposit_transaction_id;

    /*
     * Post agent-deposit entries.
     */
    v_stage := 'post agent deposit entries';

    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_deposit_document_number,

        p_country_code =>
            v_executor.country_code,

        p_transaction_id =>
            v_deposit_transaction_id,

        p_transaction_type =>
            v_deposit_transaction_type,

        p_created_by =>
            v_executor.id,

        p_components =>
            v_deposit_components,

        p_mappings =>
            v_deposit_mappings,

        p_currency_code =>
            v_currency_code,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_reference =>
            case
                when v_is_reversal
                    then v_original_deposit.document_number
                else v_funding_document_number
            end,

        p_deposit_type =>
            null
    );

    /*
     * Create agent-funding transaction.
     */
    v_stage := 'create agent funding transaction';

    insert into public.financial_transaction (
        fiscal_year,
        period,
        country_code,
        document_number,
        reference,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        reversal_of,
        reversed_by
    )
    values (
        v_fiscal_year,
        v_period,
        v_executor.country_code,
        v_funding_document_number,
        case
            when v_is_reversal
                then v_funding_document_number
            else v_reference
        end,
        v_funding_transaction_type,
        v_funding_description,
        v_executor.id,
        v_amount,
        v_currency_code,
        case
            when v_is_reversal
                then v_original_funding.document_number
            else null
        end,
        case
            when v_is_reversal
                then v_executor.id
            else null
        end
    )
    returning id
    into v_funding_transaction_id;

    /*
     * Post agent-funding entries.
     */
    v_stage := 'post agent funding entries';

    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_funding_document_number,

        p_country_code =>
            v_executor.country_code,

        p_transaction_id =>
            v_funding_transaction_id,

        p_transaction_type =>
            v_funding_transaction_type,

        p_created_by =>
            v_executor.id,

        p_components =>
            v_funding_components,

        p_mappings =>
            v_funding_mappings,

        p_currency_code =>
            v_currency_code,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_reference =>
            case
                when v_is_reversal
                    then v_original_funding.document_number
                else v_reference
            end,

        p_deposit_type =>
            null
    );

    /*
     * Wallet movement:
     *
     * Funding: treasury -> agent-operation wallet
     * Reversal: agent-operation wallet -> treasury
     */
    v_stage := 'post wallet entries';

    perform *
    from public.post_wallet_entries(
        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_document_number =>
            v_funding_document_number,

        p_reference =>
            case
                when v_is_reversal
                    then v_original_funding.document_number
                else v_reference
            end,

        p_receiver_id =>
            v_receiver_id,

        p_sender_id =>
            v_sender_id,

        p_transaction_type =>
            v_funding_transaction_type,

        p_credit_amount =>
            v_amount,

        p_debit_amount =>
            v_amount,

        p_sender_wallet_owner =>
            v_sender_wallet_owner,

        p_receiver_wallet_owner =>
            v_receiver_wallet_owner,

        p_currency_code =>
            v_currency_code,

        p_country_code =>
            v_executor.country_code,

        p_audit_action_type =>
            v_audit_action,

        p_treasury_id =>
            v_treasury.id,

        p_fee_amount =>
            0,

        p_ip_address =>
            p_ip_address,

        p_receiver_notification =>
            v_receiver_notification,

        p_sender_notification =>
            null
    );

    return jsonb_build_object(
        'success',
        true,

        'transaction_type',
        v_funding_transaction_type,

        'document_number',
        v_funding_document_number,

        'deposit_document_number',
        v_deposit_document_number,

        'reference',
        case
            when v_is_reversal
                then v_funding_document_number
            else v_reference
        end,

        'reversal_of',
        case
            when v_is_reversal
                then v_original_funding.document_number
            else null
        end,

        'funded_amount',
        v_amount::text,

        'currency',
        v_currency_code,

        'agent_id',
        v_agent.id
    );

exception
    when others then
        get stacked diagnostics
            v_error_state = returned_sqlstate,
            v_error_message = message_text,
            v_error_detail = pg_exception_detail,
            v_error_hint = pg_exception_hint,
            v_error_context = pg_exception_context;

        raise exception using
            errcode = v_error_state,

            message = format(
                'AGENT_FUNDING_FAILED at [%s]: %s',
                v_stage,
                v_error_message
            ),

            detail = concat_ws(
                E'\n',
                nullif(v_error_detail, ''),
                nullif(v_error_context, '')
            ),

            hint = coalesce(
                nullif(v_error_hint, ''),
                'Check the Agent Funding stage reported in the error'
            );
end;
$$;
ALTER FUNCTION "public"."execute_my_agent_funding"("p_transaction_type" "public"."TransactionType", "p_agent_identifier" "text", "p_currency_code" "text", "p_amount" numeric, "p_reference" "text", "p_document_number" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."execute_my_credit_agent_cash_deposit"("p_customer_identifier" "text", "p_currency_code" "text", "p_amount" numeric, "p_reference" "text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_merchant public.users%rowtype;
    v_customer public.users%rowtype;
    v_treasury public.users%rowtype;

    v_credit_account
        public.credit_agent_account%rowtype;

    v_credit_entry
        public.credit_agent_entry%rowtype;

    v_wallet_owners
        public.transaction_type_wallet_owner%rowtype;

    v_transaction_type
        public."TransactionType" :=
        'credit_agent_cash_deposit'::public."TransactionType";

    v_identifier text;
    v_currency_code text;
    v_amount numeric;
    v_reference text;

    v_fiscal_year integer;
    v_period integer;

    v_mappings
        public.transaction_gl_mapping[];

    v_components
        public.posting_component[];

    v_document_prefix text;
    v_document_number text;

    v_financial_transaction_id
        public.financial_transaction.id%type;

    v_receiver_notification
        public.notification_message;

    v_cash_holding_balance numeric;

    v_stage text := 'initialization';
    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * Authenticate merchant.
     */
    v_stage := 'authorize merchant';

    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if not public.has_role(
        array[
            'merchant'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Validate input.
     */
    v_stage := 'validate input';

    v_identifier :=
        nullif(
            btrim(p_customer_identifier),
            ''
        );

    if v_identifier is null then
        raise exception
            'CUSTOMER_IDENTIFIER_REQUIRED';
    end if;

    v_currency_code :=
        lower(
            nullif(
                btrim(p_currency_code),
                ''
            )
        );

    if v_currency_code is null then
        raise exception
            'CURRENCY_REQUIRED';
    end if;

    if v_currency_code = 'gold' then
        raise exception
            'CREDIT_AGENT_CURRENCY_MUST_BE_FIAT';
    end if;

    v_amount :=
        trunc(
            p_amount,
            2
        );

    if v_amount is null
       or v_amount <= 0
    then
        raise exception
            'INVALID_AMOUNT';
    end if;

    v_reference :=
        nullif(
            btrim(p_reference),
            ''
        );

    if v_reference is null then
        raise exception
            'REFERENCE_REQUIRED';
    end if;

    /*
     * Fetch authenticated merchant.
     */
    v_stage := 'fetch merchant';

    v_merchant :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_merchant.id is null then
        raise exception
            'MERCHANT_NOT_FOUND';
    end if;

    if v_merchant.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'MERCHANT_NOT_ACTIVE';
    end if;

    if v_merchant.country_code is null then
        raise exception
            'MERCHANT_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Lock merchant credit-agent account.
     */
    v_stage := 'lock credit agent account';

    select account_record.*
    into v_credit_account
    from public.credit_agent_account
        account_record
    where account_record.merchant_id =
              v_merchant.id

      and account_record.country_code =
              v_merchant.country_code

      and account_record.currency_code =
              v_currency_code
    for update;

    if not found then
        raise exception
            'MERCHANT_NOT_APPROVED_FOR_CREDIT_FACILITY';
    end if;

    if not v_credit_account.is_active then
        raise exception
            'CREDIT_AGENT_ACCOUNT_NOT_ACTIVE';
    end if;

    /*
     * Fetch active customer in the same country.
     */
    v_stage := 'fetch customer';

    select user_record.*
    into v_customer
    from public.users user_record
    join public.user_role role_record
      on role_record.id =
         user_record.role_id
    where user_record.country_code =
              v_merchant.country_code

      and user_record.status =
              'active'::public."UserStatus"

      and lower(
          role_record.name::text
      ) =
              'customer'

      and (
          lower(
              user_record.email
          ) =
              lower(v_identifier)

          or user_record.phone =
              v_identifier
      )
    limit 1;

    if not found then
        raise exception
            'ACTIVE_CUSTOMER_NOT_FOUND';
    end if;

    if v_customer.id =
       v_merchant.id
    then
        raise exception
            'INVALID_DEPOSIT_CUSTOMER';
    end if;

    /*
     * Fetch country treasury.
     */
    v_stage := 'fetch country treasury';

    v_treasury :=
        public.fetch_country_treasury(
            v_merchant.country_code
        );

    if v_treasury.id is null then
        raise exception
            'TREASURY_NOT_FOUND';
    end if;

    /*
     * Prevent reference replay.
     */
    v_stage := 'check transaction reference';

    perform 1
    from public.financial_transaction
        transaction_record
    where transaction_record.reference =
          v_reference
    limit 1;

    if found then
        raise exception
            'TRANSACTION_REPLAY';
    end if;

    /*
     * Fetch GL mappings.
     *
     * Expected principal mapping:
     *
     * Dr Agent Cash Holding
     * Cr Customer Deposits
     */
    v_stage := 'fetch GL mappings';

    select array_agg(mapping_record)
    into v_mappings
    from public.fetch_gl_mappings(
        v_transaction_type
    ) as mapping_record;

    if v_mappings is null
       or cardinality(v_mappings) = 0
    then
        raise exception
            'CREDIT_AGENT_CASH_DEPOSIT_GL_MAPPINGS_NOT_FOUND';
    end if;

    /*
     * Build posting components.
     */
    v_stage := 'build posting components';

    v_components :=
        public.build_posting_components(
            v_transaction_type,
            v_amount,
            v_mappings,
            v_merchant.country_code,
            v_currency_code,
            false
        );

    if v_components is null
       or cardinality(v_components) = 0
    then
        raise exception
            'POSTING_COMPONENTS_NOT_FOUND';
    end if;

    /*
     * Fetch wallet configuration.
     */
    v_stage := 'fetch wallet-owner configuration';

    select wallet_owner_record.*
    into v_wallet_owners
    from public.fetch_transaction_type_wallet_owner(
        v_transaction_type
    ) as wallet_owner_record;

    if not found then
        raise exception
            'CREDIT_AGENT_CASH_DEPOSIT_WALLET_OWNER_NOT_FOUND';
    end if;

    if v_wallet_owners.sender_wallet_owner <>
       'agent'::public."WalletOwnerType"
    then
        raise exception
            'CASH_DEPOSIT_SENDER_MUST_BE_AGENT_WALLET';
    end if;

    if v_wallet_owners.receiver_wallet_owner <>
       'customer'::public."WalletOwnerType"
    then
        raise exception
            'CASH_DEPOSIT_RECEIVER_MUST_BE_CUSTOMER_WALLET';
    end if;

    if v_wallet_owners.audit_action_type is null then
        raise exception
            'CASH_DEPOSIT_AUDIT_ACTION_NOT_CONFIGURED';
    end if;

    /*
     * Fetch fiscal period.
     */
    v_stage := 'fetch fiscal period';

    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_merchant.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Generate document number.
     */
    v_stage := 'fetch document prefix';

    v_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            v_transaction_type
        );

    if nullif(
        btrim(v_document_prefix),
        ''
    ) is null
    then
        raise exception
            'CREDIT_AGENT_CASH_DEPOSIT_PREFIX_NOT_FOUND';
    end if;

    v_stage := 'generate document number';

    v_document_number :=
        public.generate_document_number(
            v_document_prefix,
            v_fiscal_year,
            v_period,
            v_merchant.country_code
        );

    /*
     * Create customer notification.
     */
    v_stage := 'create receiver notification';

    v_receiver_notification :=
        public.create_notification_message(
            p_country_code =>
                v_merchant.country_code,

            p_transaction_type =>
                v_transaction_type,

            p_audience =>
                'receiver'::public."NotificationAudience",

            p_amount =>
                v_amount,

            p_currency =>
                upper(v_currency_code),

            p_reference =>
                v_reference,

            p_quantity =>
                0,

            p_sender =>
                coalesce(
                    v_merchant.email,
                    v_merchant.id
                ),

            p_receiver =>
                coalesce(
                    v_customer.email,
                    v_customer.id
                )
        );

    /*
     * Create financial transaction.
     */
    v_stage := 'create financial transaction';

    insert into public.financial_transaction (
        fiscal_year,
        period,
        country_code,
        document_number,
        reference,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code
    )
    values (
        v_fiscal_year,
        v_period,
        v_merchant.country_code,
        v_document_number,
        v_reference,
        v_transaction_type,
        format(
            'Customer cash deposit through credit merchant %s',
            coalesce(
                v_merchant.email,
                v_merchant.phone,
                v_merchant.id
            )
        ),
        v_merchant.id,
        v_amount,
        v_currency_code
    )
    returning id
    into v_financial_transaction_id;

    /*
     * Post:
     *
     * Dr Agent Cash Holding
     * Cr Customer Deposits
     */
    v_stage := 'post financial entries';

    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_document_number,

        p_country_code =>
            v_merchant.country_code,

        p_transaction_id =>
            v_financial_transaction_id,

        p_transaction_type =>
            v_transaction_type,

        p_created_by =>
            v_merchant.id,

        p_components =>
            v_components,

        p_mappings =>
            v_mappings,

        p_currency_code =>
            v_currency_code,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_reference =>
            v_reference,

        p_deposit_type =>
            null
    );

    /*
     * Wallet movement:
     *
     * Merchant agent wallet -> Customer wallet.
     *
     * post_wallet_entries must reject an insufficient merchant
     * float balance.
     */
    v_stage := 'post wallet entries';

    perform *
    from public.post_wallet_entries(
        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_document_number =>
            v_document_number,

        p_reference =>
            v_reference,

        p_receiver_id =>
            v_customer.id,

        p_sender_id =>
            v_merchant.id,

        p_transaction_type =>
            v_transaction_type,

        p_credit_amount =>
            v_amount,

        p_debit_amount =>
            v_amount,

        p_sender_wallet_owner =>
            v_wallet_owners.sender_wallet_owner,

        p_receiver_wallet_owner =>
            v_wallet_owners.receiver_wallet_owner,

        p_currency_code =>
            v_currency_code,

        p_country_code =>
            v_merchant.country_code,

        p_audit_action_type =>
            v_wallet_owners.audit_action_type,

        p_treasury_id =>
            v_treasury.id,

        p_fee_amount =>
            0,

        p_ip_address =>
            p_ip_address,

        p_receiver_notification =>
            v_receiver_notification,

        p_sender_notification =>
            null
    );

    /*
     * Increase this merchant's physical cash holding.
     */
    v_stage := 'post credit agent cash holding';

    v_credit_entry :=
        public.post_credit_agent_entry(
            p_credit_agent_account_id =>
                v_credit_account.id,

            p_document_number =>
                v_document_number,

            p_transaction_type =>
                v_transaction_type,

            p_fiscal_year =>
                v_fiscal_year,

            p_period =>
                v_period,

            p_debit_receivable =>
                0,

            p_credit_receivable =>
                0,

            p_debit_cash_holding =>
                v_amount,

            p_credit_cash_holding =>
                0,

            p_created_by =>
                v_merchant.id
        );

    /*
     * Read final cash-holding balance.
     */
    v_stage := 'fetch final cash holding balance';

    select account_record.cash_holding_balance
    into v_cash_holding_balance
    from public.credit_agent_account
        account_record
    where account_record.id =
          v_credit_account.id;

    return jsonb_build_object(
        'success',
        true,

        'document_number',
        v_document_number,

        'reference',
        v_reference,

        'transaction_type',
        v_transaction_type,

        'deposited_amount',
        v_amount::text,

        'currency_code',
        v_currency_code,

        'merchant_id',
        v_merchant.id,

        'customer_id',
        v_customer.id,

        'credit_agent_account_id',
        v_credit_account.id,

        'credit_agent_entry_id',
        v_credit_entry.id,

        'cash_holding_balance',
        v_cash_holding_balance::text
    );

exception
    when others then
        get stacked diagnostics
            v_error_state = returned_sqlstate,
            v_error_message = message_text,
            v_error_detail = pg_exception_detail,
            v_error_hint = pg_exception_hint,
            v_error_context = pg_exception_context;

        raise exception using
            errcode = v_error_state,

            message = format(
                'CREDIT_AGENT_CASH_DEPOSIT_FAILED at [%s]: %s',
                v_stage,
                v_error_message
            ),

            detail = concat_ws(
                E'\n',
                nullif(v_error_detail, ''),
                nullif(v_error_context, '')
            ),

            hint = coalesce(
                nullif(v_error_hint, ''),
                'Check the Credit Agent Cash Deposit stage reported in the error'
            );
end;
$$;
ALTER FUNCTION "public"."execute_my_credit_agent_cash_deposit"("p_customer_identifier" "text", "p_currency_code" "text", "p_amount" numeric, "p_reference" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."execute_my_credit_agent_funding"("p_agent_identifier" "text", "p_currency_code" "text", "p_amount" numeric, "p_reference" "text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_executor public.users%rowtype;
    v_treasury public.users%rowtype;
    v_merchant public.users%rowtype;

    v_credit_account
        public.credit_agent_account%rowtype;

    v_credit_entry
        public.credit_agent_entry%rowtype;

    v_credit_transaction_type
        public."TransactionType" :=
        'credit_agent_funding'::public."TransactionType";

    v_deposit_transaction_type
        public."TransactionType" :=
        'agent_deposit'::public."TransactionType";

    v_identifier text;
    v_currency_code text;
    v_amount numeric;
    v_reference text;

    v_fiscal_year integer;
    v_period integer;

    v_credit_mappings
        public.transaction_gl_mapping[];

    v_deposit_mappings
        public.transaction_gl_mapping[];

    v_credit_components
        public.posting_component[];

    v_deposit_components
        public.posting_component[];

    v_wallet_owners
        public.transaction_type_wallet_owner%rowtype;

    v_credit_document_prefix text;
    v_deposit_document_prefix text;

    v_credit_document_number text;
    v_deposit_document_number text;

    v_credit_transaction_id
        public.financial_transaction.id%type;

    v_deposit_transaction_id
        public.financial_transaction.id%type;

    v_receiver_notification
        public.notification_message;

    v_receivable_balance numeric;

    v_stage text := 'initialization';
    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * Authenticate treasury.
     */
    v_stage := 'authorize treasury user';

    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if not public.has_role(
        array[
            'treasury'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Validate input.
     */
    v_stage := 'validate input';

    v_identifier :=
        nullif(
            btrim(p_agent_identifier),
            ''
        );

    if v_identifier is null then
        raise exception
            'MERCHANT_IDENTIFIER_REQUIRED';
    end if;

    v_currency_code :=
        lower(
            nullif(
                btrim(p_currency_code),
                ''
            )
        );

    if v_currency_code is null then
        raise exception
            'CURRENCY_REQUIRED';
    end if;

    if v_currency_code = 'gold' then
        raise exception
            'CREDIT_AGENT_CURRENCY_MUST_BE_FIAT';
    end if;

    v_amount :=
        trunc(
            p_amount,
            2
        );

    if v_amount is null
       or v_amount <= 0
    then
        raise exception
            'INVALID_AMOUNT';
    end if;

    v_reference :=
        nullif(
            btrim(p_reference),
            ''
        );

    if v_reference is null then
        raise exception
            'REFERENCE_REQUIRED';
    end if;

    /*
     * Fetch authenticated treasury user.
     */
    v_stage := 'fetch treasury user';

    v_executor :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_executor.id is null then
        raise exception
            'TREASURY_USER_NOT_FOUND';
    end if;

    if v_executor.country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Fetch country treasury.
     */
    v_stage := 'fetch country treasury';

    v_treasury :=
        public.fetch_country_treasury(
            v_executor.country_code
        );

    if v_treasury.id is null then
        raise exception
            'TREASURY_NOT_FOUND';
    end if;

    /*
     * Find an active merchant.
     */
    v_stage := 'fetch merchant';

    select user_record.*
    into v_merchant
    from public.users user_record
    join public.user_role role_record
      on role_record.id =
         user_record.role_id
    where user_record.country_code =
              v_executor.country_code

      and user_record.status =
              'active'::public."UserStatus"

      and lower(
          role_record.name::text
      ) =
              'merchant'

      and (
          lower(
              user_record.email
          ) =
              lower(v_identifier)

          or user_record.phone =
              v_identifier
      )
    limit 1;

    if not found then
        raise exception
            'ACTIVE_MERCHANT_NOT_FOUND';
    end if;

    /*
     * Lock the approved credit-agent account.
     */
    v_stage := 'lock credit agent account';

    select account_record.*
    into v_credit_account
    from public.credit_agent_account
        account_record
    where account_record.merchant_id =
              v_merchant.id

      and account_record.country_code =
              v_executor.country_code

      and account_record.currency_code =
              v_currency_code
    for update;

    if not found then
        raise exception
            'MERCHANT_NOT_APPROVED_FOR_CREDIT_FACILITY';
    end if;

    if not v_credit_account.is_active then
        raise exception
            'CREDIT_AGENT_ACCOUNT_NOT_ACTIVE';
    end if;

    /*
     * Prevent reference replay.
     */
    v_stage := 'check transaction reference';

    perform 1
    from public.financial_transaction
        transaction_record
    where transaction_record.reference =
          v_reference
    limit 1;

    if found then
        raise exception
            'TRANSACTION_REPLAY';
    end if;

    /*
     * Fetch GL mappings.
     */
    v_stage := 'fetch credit funding mappings';

    select array_agg(mapping_record)
    into v_credit_mappings
    from public.fetch_gl_mappings(
        v_credit_transaction_type
    ) as mapping_record;

    if v_credit_mappings is null
       or cardinality(v_credit_mappings) = 0
    then
        raise exception
            'CREDIT_AGENT_FUNDING_GL_MAPPINGS_NOT_FOUND';
    end if;

    v_stage := 'fetch agent deposit mappings';

    select array_agg(mapping_record)
    into v_deposit_mappings
    from public.fetch_gl_mappings(
        v_deposit_transaction_type
    ) as mapping_record;

    if v_deposit_mappings is null
       or cardinality(v_deposit_mappings) = 0
    then
        raise exception
            'AGENT_DEPOSIT_GL_MAPPINGS_NOT_FOUND';
    end if;

    /*
     * Build posting components.
     *
     * credit_agent_funding:
     * Dr Agent Receivable
     * Cr Bank
     *
     * agent_deposit:
     * Dr Bank
     * Cr Agent Float Payable
     */
    v_stage := 'build credit funding components';

    v_credit_components :=
        public.build_posting_components(
            v_credit_transaction_type,
            v_amount,
            v_credit_mappings,
            v_executor.country_code,
            v_currency_code,
            false
        );

    v_stage := 'build agent deposit components';

    v_deposit_components :=
        public.build_posting_components(
            v_deposit_transaction_type,
            v_amount,
            v_deposit_mappings,
            v_executor.country_code,
            v_currency_code,
            false
        );

    /*
     * Fetch wallet-owner configuration.
     */
    v_stage := 'fetch wallet-owner configuration';

    select wallet_owner_record.*
    into v_wallet_owners
    from public.fetch_transaction_type_wallet_owner(
        v_credit_transaction_type
    ) as wallet_owner_record;

    if not found then
        raise exception
            'CREDIT_AGENT_FUNDING_WALLET_OWNER_NOT_FOUND';
    end if;

    if v_wallet_owners.sender_wallet_owner <>
       'treasury'::public."WalletOwnerType"
    then
        raise exception
            'CREDIT_AGENT_FUNDING_SENDER_MUST_BE_TREASURY';
    end if;

    if v_wallet_owners.receiver_wallet_owner <>
       'agent'::public."WalletOwnerType"
    then
        raise exception
            'CREDIT_AGENT_FUNDING_RECEIVER_MUST_BE_AGENT_WALLET';
    end if;

    if v_wallet_owners.audit_action_type is null then
        raise exception
            'CREDIT_AGENT_FUNDING_AUDIT_ACTION_NOT_CONFIGURED';
    end if;

    /*
     * Fetch fiscal period.
     */
    v_stage := 'fetch fiscal period';

    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_executor.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Fetch document prefixes.
     */
    v_stage := 'fetch credit funding document prefix';

    v_credit_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            v_credit_transaction_type
        );

    if nullif(
        btrim(v_credit_document_prefix),
        ''
    ) is null
    then
        raise exception
            'CREDIT_AGENT_FUNDING_DOCUMENT_PREFIX_NOT_FOUND';
    end if;

    v_stage := 'fetch agent deposit document prefix';

    v_deposit_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            v_deposit_transaction_type
        );

    if nullif(
        btrim(v_deposit_document_prefix),
        ''
    ) is null
    then
        raise exception
            'AGENT_DEPOSIT_DOCUMENT_PREFIX_NOT_FOUND';
    end if;

    /*
     * Generate document numbers.
     */
    v_stage := 'generate credit funding document';

    v_credit_document_number :=
        public.generate_document_number(
            v_credit_document_prefix,
            v_fiscal_year,
            v_period,
            v_executor.country_code
        );

    v_stage := 'generate agent deposit document';

    v_deposit_document_number :=
        public.generate_document_number(
            v_deposit_document_prefix,
            v_fiscal_year,
            v_period,
            v_executor.country_code
        );

    /*
     * Create receiver notification.
     */
    v_stage := 'create receiver notification';

    v_receiver_notification :=
        public.create_notification_message(
            p_country_code =>
                v_executor.country_code,

            p_transaction_type =>
                v_credit_transaction_type,

            p_audience =>
                'receiver'::public."NotificationAudience",

            p_amount =>
                v_amount,

            p_currency =>
                upper(v_currency_code),

            p_reference =>
                v_reference,

            p_quantity =>
                0,

            p_sender =>
                coalesce(
                    v_treasury.email,
                    'Ngoda'
                ),

            p_receiver =>
                coalesce(
                    v_merchant.email,
                    v_merchant.id
                )
        );

    /*
     * Document 1:
     *
     * Dr Agent Receivable
     * Cr Bank
     */
    v_stage := 'create credit funding transaction';

    insert into public.financial_transaction (
        fiscal_year,
        period,
        country_code,
        document_number,
        reference,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code
    )
    values (
        v_fiscal_year,
        v_period,
        v_executor.country_code,
        v_credit_document_number,
        v_reference,
        v_credit_transaction_type,
        format(
            'Credit funding issued to merchant %s',
            coalesce(
                v_merchant.email,
                v_merchant.phone,
                v_merchant.id
            )
        ),
        v_executor.id,
        v_amount,
        v_currency_code
    )
    returning id
    into v_credit_transaction_id;

    v_stage := 'post credit funding entries';

    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_credit_document_number,

        p_country_code =>
            v_executor.country_code,

        p_transaction_id =>
            v_credit_transaction_id,

        p_transaction_type =>
            v_credit_transaction_type,

        p_created_by =>
            v_executor.id,

        p_components =>
            v_credit_components,

        p_mappings =>
            v_credit_mappings,

        p_currency_code =>
            v_currency_code,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_reference =>
            v_reference,

        p_deposit_type =>
            null
    );

    /*
     * Document 2:
     *
     * Dr Bank
     * Cr Agent Float Payable
     */
    v_stage := 'create agent deposit transaction';

    insert into public.financial_transaction (
        fiscal_year,
        period,
        country_code,
        document_number,
        reference,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code
    )
    values (
        v_fiscal_year,
        v_period,
        v_executor.country_code,
        v_deposit_document_number,
        v_credit_document_number,
        v_deposit_transaction_type,
        format(
            'Credit float deposited to merchant agent wallet %s',
            coalesce(
                v_merchant.email,
                v_merchant.phone,
                v_merchant.id
            )
        ),
        v_executor.id,
        v_amount,
        v_currency_code
    )
    returning id
    into v_deposit_transaction_id;

    v_stage := 'post agent deposit entries';

    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_deposit_document_number,

        p_country_code =>
            v_executor.country_code,

        p_transaction_id =>
            v_deposit_transaction_id,

        p_transaction_type =>
            v_deposit_transaction_type,

        p_created_by =>
            v_executor.id,

        p_components =>
            v_deposit_components,

        p_mappings =>
            v_deposit_mappings,

        p_currency_code =>
            v_currency_code,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_reference =>
            v_credit_document_number,

        p_deposit_type =>
            null
    );

    /*
     * Move electronic float:
     *
     * Treasury -> merchant agent wallet.
     */
    v_stage := 'post wallet entries';

    perform *
    from public.post_wallet_entries(
        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_document_number =>
            v_credit_document_number,

        p_reference =>
            v_reference,

        p_receiver_id =>
            v_merchant.id,

        p_sender_id =>
            v_treasury.id,

        p_transaction_type =>
            v_credit_transaction_type,

        p_credit_amount =>
            v_amount,

        p_debit_amount =>
            v_amount,

        p_sender_wallet_owner =>
            v_wallet_owners.sender_wallet_owner,

        p_receiver_wallet_owner =>
            v_wallet_owners.receiver_wallet_owner,

        p_currency_code =>
            v_currency_code,

        p_country_code =>
            v_executor.country_code,

        p_audit_action_type =>
            v_wallet_owners.audit_action_type,

        p_treasury_id =>
            v_treasury.id,

        p_fee_amount =>
            0,

        p_ip_address =>
            p_ip_address,

        p_receiver_notification =>
            v_receiver_notification,

        p_sender_notification =>
            null
    );

    /*
     * Increase this merchant's receivable:
     *
     * debit_receivable = funding amount.
     */
    v_stage := 'post credit agent receivable';

    v_credit_entry :=
        public.post_credit_agent_entry(
            p_credit_agent_account_id =>
                v_credit_account.id,

            p_document_number =>
                v_credit_document_number,

            p_transaction_type =>
                v_credit_transaction_type,

            p_fiscal_year =>
                v_fiscal_year,

            p_period =>
                v_period,

            p_debit_receivable =>
                v_amount,

            p_credit_receivable =>
                0,

            p_debit_cash_holding =>
                0,

            p_credit_cash_holding =>
                0,

            p_created_by =>
                v_executor.id
        );

    /*
     * Read final balance.
     */
    v_stage := 'fetch final receivable balance';

    select account_record.receivable_balance
    into v_receivable_balance
    from public.credit_agent_account
        account_record
    where account_record.id =
          v_credit_account.id;

    return jsonb_build_object(
        'success',
        true,

        'transaction_type',
        v_credit_transaction_type,

        'document_number',
        v_credit_document_number,

        'deposit_document_number',
        v_deposit_document_number,

        'reference',
        v_reference,

        'funded_amount',
        v_amount::text,

        'currency_code',
        v_currency_code,

        'merchant_id',
        v_merchant.id,

        'credit_agent_account_id',
        v_credit_account.id,

        'credit_agent_entry_id',
        v_credit_entry.id,

        'receivable_balance',
        v_receivable_balance::text
    );

exception
    when others then
        get stacked diagnostics
            v_error_state = returned_sqlstate,
            v_error_message = message_text,
            v_error_detail = pg_exception_detail,
            v_error_hint = pg_exception_hint,
            v_error_context = pg_exception_context;

        raise exception using
            errcode = v_error_state,

            message = format(
                'CREDIT_AGENT_FUNDING_FAILED at [%s]: %s',
                v_stage,
                v_error_message
            ),

            detail = concat_ws(
                E'\n',
                nullif(v_error_detail, ''),
                nullif(v_error_context, '')
            ),

            hint = coalesce(
                nullif(v_error_hint, ''),
                'Check the Credit Agent Funding stage reported in the error'
            );
end;
$$;
ALTER FUNCTION "public"."execute_my_credit_agent_funding"("p_agent_identifier" "text", "p_currency_code" "text", "p_amount" numeric, "p_reference" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."execute_my_customer_direct_deposit"("p_identifier" "text", "p_currency_code" "text", "p_amount" numeric, "p_reference" "text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_finance_user public.users%rowtype;
    v_customer public.users%rowtype;
    v_treasury public.users%rowtype;

    v_identifier text;
    v_currency_code text;
    v_reference text;

    v_amount numeric;
    v_fee numeric := 0;
    v_net_amount numeric;

    v_fiscal_year integer;
    v_period integer;

    v_mappings
        public.transaction_gl_mapping[];

    v_components
        public.posting_component[];

    v_document_prefix text;
    v_document_number text;

    v_financial_transaction_id bigint;

    v_notification
        public.notification_message;

    v_device_tokens text[] :=
        array[]::text[];

    v_receiver_notification_id text;
begin
    /*
     * Authenticate and authorize finance.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if not public.has_role(
        array[
            'finance'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Validate input.
     */
    v_identifier :=
        nullif(
            btrim(p_identifier),
            ''
        );

    if v_identifier is null then
        raise exception
            'IDENTIFIER_REQUIRED';
    end if;

    v_currency_code :=
        lower(
            nullif(
                btrim(p_currency_code),
                ''
            )
        );

    if v_currency_code is null then
        raise exception
            'CURRENCY_REQUIRED';
    end if;

    v_reference :=
        nullif(
            btrim(p_reference),
            ''
        );

    if v_reference is null then
        raise exception
            'REFERENCE_REQUIRED';
    end if;

    v_amount :=
        p_amount;

    if v_amount is null
       or v_amount <= 0
    then
        raise exception
            'INVALID_AMOUNT';
    end if;

    /*
     * References are globally unique.
     */
    perform 1
    from public.financial_transaction
        financial_transaction_record
    where financial_transaction_record.reference =
          v_reference
    limit 1;

    if found then
        raise exception
            'TRANSACTION_REPLAY';
    end if;

    /*
     * Fetch trusted finance-user context.
     */
    v_finance_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_finance_user.id is null then
        raise exception
            'FINANCE_USER_NOT_FOUND';
    end if;

    if v_finance_user.country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Fetch the customer and country treasury.
     */
    v_customer :=
        public.fetch_user_by_email_or_phone(
            v_identifier
        );

    if v_customer.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    v_treasury :=
        public.fetch_country_treasury(
            v_finance_user.country_code
        );

    if v_treasury.id is null then
        raise exception
            'TREASURY_WALLET_NOT_FOUND';
    end if;

    /*
     * Validate customer.
     */
    if v_customer.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'USER_NOT_ACTIVE';
    end if;

    if v_customer.country_code is distinct from
       v_finance_user.country_code
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    /*
     * Fetch GL mappings.
     */
    select array_agg(mapping_record)
    into v_mappings
    from public.fetch_gl_mappings(
        'customer_direct_deposit'::public."TransactionType"
    ) as mapping_record;

    if v_mappings is null
       or cardinality(v_mappings) = 0
    then
        raise exception
            'GL_MAPPINGS_NOT_FOUND';
    end if;

    /*
     * Build deposit components.
     */
    v_components :=
        public.build_posting_components(
            'customer_direct_deposit'::public."TransactionType",
            v_amount,
            v_mappings,
            v_finance_user.country_code,
            v_currency_code,
            false
        );

    if v_components is null
       or cardinality(v_components) = 0
    then
        raise exception
            'POSTING_COMPONENTS_NOT_FOUND';
    end if;

    /*
     * Extract the configured deposit fee.
     */
    select coalesce(
        component_record.credit_amount,
        0
    )
    into v_fee
    from unnest(
        v_components
    ) as component_record(
        component_type,
        debit_amount,
        credit_amount
    )
    where component_record.component_type =
          'deposit_fee'::public."ComponentType"
    limit 1;

    v_fee :=
        coalesce(
            v_fee,
            0
        );

    if v_fee < 0 then
        raise exception
            'INVALID_FEE_AMOUNT';
    end if;

    v_net_amount :=
        v_amount -
        v_fee;

    if v_net_amount <= 0 then
        raise exception
            'INVALID_NET_DEPOSIT_AMOUNT';
    end if;

    /*
     * Fetch fiscal period.
     */
    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_finance_user.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Prepare customer notification.
     */
    v_notification :=
        public.create_notification_message(
            v_finance_user.country_code,
            'customer_direct_deposit'::public."TransactionType",
            'receiver'::public."NotificationAudience",
            v_amount,
            upper(
                v_currency_code
            ),
            v_reference,
            0,
            'Ngoda',
            coalesce(
                v_customer.email,
                v_customer.phone,
                v_customer.id
            )
        );

    v_device_tokens :=
        coalesce(
            public.fetch_device_tokens(
                v_customer.country_code,
                v_customer.id
            ),
            array[]::text[]
        );

    /*
     * Generate document number.
     */
    v_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            'customer_direct_deposit'::public."TransactionType"
        );

    if v_document_prefix is null
       or btrim(v_document_prefix) = ''
    then
        raise exception
            'DOCUMENT_PREFIX_NOT_FOUND';
    end if;

    v_document_number :=
        public.generate_document_number(
            v_document_prefix,
            v_fiscal_year,
            v_period,
            v_finance_user.country_code
        );

    /*
     * Create financial transaction header.
     */
    insert into public.financial_transaction (
        fiscal_year,
        period,
        document_number,
        reference,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        country_code
    )
    values (
        v_fiscal_year,
        v_period,
        v_document_number,
        v_reference,
        'customer_direct_deposit'::public."TransactionType",
        format(
            'Customer direct deposit for %s',
            coalesce(
                v_customer.email,
                v_customer.phone,
                v_customer.id
            )
        ),
        v_finance_user.id,
        v_amount,
        v_currency_code,
        v_finance_user.country_code
    )
    returning id
    into v_financial_transaction_id;

    /*
     * Post GL entries.
     */
    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_document_number,

        p_country_code =>
            v_finance_user.country_code,

        p_transaction_id =>
            v_financial_transaction_id,

        p_transaction_type =>
            'customer_direct_deposit'::public."TransactionType",

        p_created_by =>
            v_finance_user.id,

        p_components =>
            v_components,

        p_mappings =>
            v_mappings,

        p_currency_code =>
            v_currency_code,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_reference =>
            v_reference,

        p_deposit_type =>
            null
    );

    /*
     * Post wallet entries.
     *
     * The treasury wallet is the internal system counterparty.
     * The external money itself is received through the bank
     * or office and is represented by the GL posting.
     */
    select wallet_result.receiver_notification_id
    into v_receiver_notification_id
    from public.post_wallet_entries(
        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_document_number =>
            v_document_number,

        p_reference =>
            v_reference,

        p_receiver_id =>
            v_customer.id,

        p_sender_id =>
            v_treasury.id,

        p_transaction_type =>
            'customer_direct_deposit'::public."TransactionType",

        p_credit_amount =>
            v_net_amount,

        p_debit_amount =>
            v_amount,

        p_sender_wallet_owner =>
            'treasury'::public."WalletOwnerType",

        p_receiver_wallet_owner =>
            'customer'::public."WalletOwnerType",

        p_currency_code =>
            v_currency_code,

        p_country_code =>
            v_finance_user.country_code,

        p_audit_action_type =>
            'customer_direct_deposit'::public."AuditActionType",

        p_treasury_id =>
            v_treasury.id,

        p_fee_amount =>
            v_fee,

        p_ip_address =>
            p_ip_address,

        p_receiver_notification =>
            v_notification,

        p_sender_notification =>
            null
    ) as wallet_result;

    return jsonb_build_object(
        'success',
        true,

        'document_number',
        v_document_number,

        'reference',
        v_reference,

        'user_id',
        v_customer.id,

        'currency_code',
        v_currency_code,

        'funded_amount',
        v_amount::text,

        'fee',
        v_fee::text,

        'net_amount',
        v_net_amount::text,

        'receiver_notification_id',
        v_receiver_notification_id,

        'device_tokens',
        to_jsonb(
            v_device_tokens
        ),

        'push_title',
        v_notification.title,

        'push_body',
        v_notification.body,

        'push_reference',
        v_notification.payload
            ->> 'reference'
    );
end;
$$;
ALTER FUNCTION "public"."execute_my_customer_direct_deposit"("p_identifier" "text", "p_currency_code" "text", "p_amount" numeric, "p_reference" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."execute_my_external_funding"("p_currency_code" "text" DEFAULT NULL::"text", "p_amount" numeric DEFAULT NULL::numeric, "p_original_document_number" "text" DEFAULT NULL::"text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_original_document
        public.financial_transaction%rowtype;

    v_currency_code text;
    v_amount numeric;

    v_transaction_type
        public."TransactionType";

    v_description text;

    v_fiscal_year integer;
    v_period integer;

    v_mappings
        public.transaction_gl_mapping[];

    v_components
        public.posting_component[];

    v_document_prefix text;
    v_document_number text;

    v_reference text;
    v_reversal_of text;
    v_reversed_by text;

    v_financial_transaction_id bigint;

    v_stage text := 'initialization';

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * Authenticate and authorize.
     */
    v_stage := 'authenticate';

    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    v_stage := 'authorize finance role';

    if not public.has_role(
        array[
            'finance'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Fetch trusted user context.
     */
    v_stage := 'fetch user context';

    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Decide whether this is new external funding or a
     * reversal.
     */
    if nullif(
        btrim(p_original_document_number),
        ''
    ) is null
    then
        /*
         * Normal external funding.
         */
        v_stage := 'validate external funding input';

        v_transaction_type :=
            'external_funding'::public."TransactionType";

        v_currency_code :=
            lower(
                nullif(
                    btrim(p_currency_code),
                    ''
                )
            );

        if v_currency_code is null then
            raise exception
                'CURRENCY_IS_REQUIRED';
        end if;

        v_amount :=
            p_amount;

        if v_amount is null then
            raise exception
                'AMOUNT_IS_REQUIRED';
        end if;

        if v_amount <= 0 then
            raise exception
                'INVALID_AMOUNT';
        end if;

        v_description :=
            'External funding';

        v_reversal_of :=
            null;

        v_reversed_by :=
            null;
    else
        /*
         * External funding reversal.
         */
        v_stage :=
            'lock original external funding document';

        select financial_transaction_record.*
        into v_original_document
        from public.financial_transaction
            financial_transaction_record
        where financial_transaction_record.document_number =
              btrim(
                  p_original_document_number
              )

          and financial_transaction_record.country_code =
              v_user.country_code
        for update;

        if not found then
            raise exception
                'DOCUMENT_NOT_FOUND';
        end if;

        v_stage :=
            'validate original transaction type';

        if v_original_document.transaction_type <>
           'external_funding'::public."TransactionType"
        then
            raise exception
                'DOCUMENT_IS_NOT_EXTERNAL_FUNDING';
        end if;

        /*
         * Prevent the same document from being reversed more
         * than once.
         */
        v_stage :=
            'check existing reversal';

        perform 1
        from public.financial_transaction
            reversal_record
        where reversal_record.country_code =
              v_user.country_code

          and reversal_record.reversal_of =
              v_original_document.document_number

          and reversal_record.transaction_type =
              'external_funding_reversal'::public."TransactionType"
        limit 1;

        if found then
            raise exception
                'DOCUMENT_ALREADY_REVERSED';
        end if;

        /*
         * Currency and amount are trusted from the original
         * document.
         */
        v_transaction_type :=
            'external_funding_reversal'::public."TransactionType";

        v_currency_code :=
            lower(
                v_original_document.currency_code
            );

        v_amount :=
            v_original_document.gross_amount;

        if v_amount is null
           or v_amount <= 0
        then
            raise exception
                'INVALID_ORIGINAL_DOCUMENT_AMOUNT';
        end if;

        v_description :=
            format(
                'External funding reversal for document %s',
                v_original_document.document_number
            );

        v_reversal_of :=
            v_original_document.document_number;

        v_reversed_by :=
            v_user.id;
    end if;

    /*
     * Fetch the GL mappings.
     */
    v_stage := 'fetch GL mappings';

    select array_agg(mapping_record)
    into v_mappings
    from public.fetch_gl_mappings(
        v_transaction_type
    ) as mapping_record;

    if v_mappings is null
       or cardinality(v_mappings) = 0
    then
        raise exception
            'GL_MAPPINGS_NOT_FOUND';
    end if;

    /*
     * Build posting components.
     *
     * Reversal mappings/components determine the reversed
     * debit and credit directions.
     */
    v_stage := 'build posting components';

    v_components :=
        public.build_posting_components(
            v_transaction_type,
            v_amount,
            v_mappings,
            v_user.country_code,
            v_currency_code,
            false
        );

    if v_components is null
       or cardinality(v_components) = 0
    then
        raise exception
            'POSTING_COMPONENTS_NOT_FOUND';
    end if;

    /*
     * Fetch fiscal period.
     */
    v_stage := 'fetch fiscal period';

    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_user.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Fetch the configured document prefix.
     */
    v_stage := 'fetch document prefix';

    v_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            v_transaction_type
        );

    if v_document_prefix is null
       or btrim(v_document_prefix) = ''
    then
        raise exception
            'DOCUMENT_PREFIX_NOT_FOUND';
    end if;

    /*
     * Generate the document number.
     */
    v_stage := 'generate document number';

    v_document_number :=
        public.generate_document_number(
            v_document_prefix,
            v_fiscal_year,
            v_period,
            v_user.country_code
        );

    /*
     * Normal funding references itself.
     *
     * A reversal references the original document.
     */
    v_reference :=
        coalesce(
            v_reversal_of,
            v_document_number
        );

    /*
     * Create financial transaction header.
     */
    v_stage :=
        'create financial transaction';

    insert into public.financial_transaction (
        document_number,
        reference,
        fiscal_year,
        country_code,
        period,
        transaction_type,
        description,
        created_by,
        gross_amount,
        reversal_of,
        reversed_by,
        currency_code
    )
    values (
        v_document_number,
        v_reference,
        v_fiscal_year,
        v_user.country_code,
        v_period,
        v_transaction_type,
        v_description,
        v_user.id,
        v_amount,
        v_reversal_of,
        v_reversed_by,
        v_currency_code
    )
    returning id
    into v_financial_transaction_id;

    /*
     * Post the GL entries.
     */
    v_stage := 'post financial entries';

    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_document_number,

        p_country_code =>
            v_user.country_code,

        p_transaction_id =>
            v_financial_transaction_id,

        p_transaction_type =>
            v_transaction_type,

        p_created_by =>
            v_user.id,

        p_components =>
            v_components,

        p_mappings =>
            v_mappings,

        p_currency_code =>
            v_currency_code,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_reference =>
            v_reference,

        p_deposit_type =>
            null
    );

    /*
     * Create audit record.
     *
     * treasury_funded is retained because it is the existing
     * AuditActionType used by this operation.
     */
    v_stage := 'create audit log';

    insert into public.audit_log (
        fiscal_year,
        period,
        user_id,
        country_code,
        action_type,
        entity_type,
        entity_id,
        metadata,
        ip_address,
        document_number
    )
    values (
        v_fiscal_year,
        v_period,
        v_user.id,
        v_user.country_code,
        'treasury_funded'::public."AuditActionType",
        'external',
        'finance',
        jsonb_build_object(
            'document_number',
            v_document_number,

            'reference',
            v_reference,

            'transaction_type',
            v_transaction_type,

            'amount',
            v_amount::text,

            'currency_code',
            v_currency_code,

            'reversal_of',
            v_reversal_of
        ),
        p_ip_address,
        v_document_number
    );

    return jsonb_build_object(
        'success',
        true,

        'document_number',
        v_document_number,

        'reference',
        v_reference,

        'transaction_type',
        v_transaction_type,

        'currency_code',
        v_currency_code,

        'amount',
        v_amount::text,

        'reversal_of',
        v_reversal_of
    );

exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;

        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'EXTERNAL_FUNDING_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                coalesce(
                    nullif(
                        concat_ws(
                            E'\n',
                            nullif(
                                v_error_detail,
                                ''
                            ),
                            nullif(
                                v_error_context,
                                ''
                            )
                        ),
                        ''
                    ),
                    'No additional PostgreSQL context'
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    'Check the external-funding stage reported in the error'
                );
end;
$$;
ALTER FUNCTION "public"."execute_my_external_funding"("p_currency_code" "text", "p_amount" numeric, "p_original_document_number" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."execute_my_external_funding"("p_transaction_type" "public"."TransactionType", "p_currency_code" "text" DEFAULT NULL::"text", "p_amount" numeric DEFAULT NULL::numeric, "p_document_number" "text" DEFAULT NULL::"text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_original_document
        public.financial_transaction%rowtype;

    v_currency_code text;
    v_amount numeric;

    /*
     * Header reference must always be unique.
     */
    v_transaction_reference text;

    /*
     * Entry reference connects the reversal entries to the
     * original document.
     */
    v_entry_reference text;

    v_reversal_of text;
    v_reversed_by text;

    v_description text;

    v_audit_action
        public."AuditActionType";

    v_fiscal_year integer;
    v_period integer;

    v_mappings
        public.transaction_gl_mapping[];

    v_components
        public.posting_component[];

    v_document_prefix text;
    v_new_document_number text;

    v_financial_transaction_id bigint;
begin
    /*
     * Authenticate and authorize.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if not public.has_role(
        array[
            'finance'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Only these two transaction types are supported.
     */
    if p_transaction_type not in (
        'external_funding'::public."TransactionType",
        'external_funding_reversal'::public."TransactionType"
    ) then
        raise exception
            'INVALID_EXTERNAL_FUNDING_TRANSACTION_TYPE_%',
            p_transaction_type;
    end if;

    /*
     * Fetch the authenticated finance user.
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Normal external funding.
     */
    if p_transaction_type =
       'external_funding'::public."TransactionType"
    then
        v_currency_code :=
            lower(
                nullif(
                    btrim(p_currency_code),
                    ''
                )
            );

        if v_currency_code is null then
            raise exception
                'CURRENCY_IS_REQUIRED';
        end if;

        v_amount :=
            p_amount;

        if v_amount is null then
            raise exception
                'AMOUNT_IS_REQUIRED';
        end if;

        if v_amount <= 0 then
            raise exception
                'INVALID_AMOUNT';
        end if;

        v_description :=
            'External funding received in bank';

        v_audit_action :=
            'external_funding'::public."AuditActionType";

        v_reversal_of :=
            null;

        v_reversed_by :=
            null;
    end if;

    /*
     * External funding reversal.
     */
    if p_transaction_type =
       'external_funding_reversal'::public."TransactionType"
    then
        if nullif(
            btrim(p_document_number),
            ''
        ) is null
        then
            raise exception
                'DOCUMENT_NUMBER_REQUIRED_FOR_REVERSAL';
        end if;

        /*
         * Lock the original document.
         */
        select financial_transaction_record.*
        into v_original_document
        from public.financial_transaction
            financial_transaction_record
        where financial_transaction_record.document_number =
              btrim(p_document_number)

          and financial_transaction_record.country_code =
              v_user.country_code
        for update;

        if not found then
            raise exception
                'DOCUMENT_NOT_FOUND';
        end if;

        if v_original_document.transaction_type <>
           'external_funding'::public."TransactionType"
        then
            raise exception
                'DOCUMENT_IS_NOT_EXTERNAL_FUNDING';
        end if;

        /*
         * Prevent duplicate reversal.
         */
        perform 1
        from public.financial_transaction
            reversal_record
        where reversal_record.country_code =
              v_user.country_code

          and reversal_record.reversal_of =
              v_original_document.document_number

          and reversal_record.transaction_type =
              'external_funding_reversal'::public."TransactionType"
        limit 1;

        if found then
            raise exception
                'DOCUMENT_ALREADY_REVERSED';
        end if;

        /*
         * Reversal values come from the original document.
         */
        v_currency_code :=
            lower(
                v_original_document.currency_code
            );

        v_amount :=
            v_original_document.gross_amount;

        if v_amount is null
           or v_amount <= 0
        then
            raise exception
                'INVALID_ORIGINAL_DOCUMENT_AMOUNT';
        end if;

        v_description :=
            format(
                'External funding reversal for %s',
                v_original_document.document_number
            );

        v_audit_action :=
            'external_funding_reversed'::public."AuditActionType";

        v_reversal_of :=
            v_original_document.document_number;

        v_reversed_by :=
            v_user.id;
    end if;

    /*
     * Fetch GL mappings.
     */
    select array_agg(mapping_record)
    into v_mappings
    from public.fetch_gl_mappings(
        p_transaction_type
    ) as mapping_record;

    if v_mappings is null
       or cardinality(v_mappings) = 0
    then
        raise exception
            'GL_MAPPINGS_NOT_FOUND';
    end if;

    /*
     * Build normal or reversal components.
     */
    v_components :=
        public.build_posting_components(
            p_transaction_type,
            v_amount,
            v_mappings,
            v_user.country_code,
            v_currency_code,
            false
        );

    if v_components is null
       or cardinality(v_components) = 0
    then
        raise exception
            'POSTING_COMPONENTS_NOT_FOUND';
    end if;

    /*
     * Fetch fiscal period.
     */
    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_user.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Fetch and generate document number.
     */
    v_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            p_transaction_type
        );

    if v_document_prefix is null
       or btrim(v_document_prefix) = ''
    then
        raise exception
            'DOCUMENT_PREFIX_NOT_FOUND';
    end if;

    v_new_document_number :=
        public.generate_document_number(
            v_document_prefix,
            v_fiscal_year,
            v_period,
            v_user.country_code
        );

    /*
     * The financial transaction header always receives its
     * own unique reference.
     */
    v_transaction_reference :=
        v_new_document_number;

    /*
     * Financial entries use the original document as their
     * reference for reversals.
     */
    v_entry_reference :=
        coalesce(
            v_reversal_of,
            v_new_document_number
        );

    /*
     * Create the financial transaction.
     */
    insert into public.financial_transaction (
        document_number,
        reference,
        fiscal_year,
        country_code,
        period,
        transaction_type,
        description,
        created_by,
        gross_amount,
        reversal_of,
        reversed_by,
        currency_code
    )
    values (
        v_new_document_number,
        v_transaction_reference,
        v_fiscal_year,
        v_user.country_code,
        v_period,
        p_transaction_type,
        v_description,
        v_user.id,
        v_amount,
        v_reversal_of,
        v_reversed_by,
        v_currency_code
    )
    returning id
    into v_financial_transaction_id;

    /*
     * Post financial entries.
     *
     * No wallet entries are posted because external funding
     * remains in the bank GL until it is transferred to
     * treasury.
     */
    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_new_document_number,

        p_country_code =>
            v_user.country_code,

        p_transaction_id =>
            v_financial_transaction_id,

        p_transaction_type =>
            p_transaction_type,

        p_created_by =>
            v_user.id,

        p_components =>
            v_components,

        p_mappings =>
            v_mappings,

        p_currency_code =>
            v_currency_code,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_reference =>
            v_entry_reference,

        p_deposit_type =>
            null
    );

    /*
     * Create the audit entry.
     */
    insert into public.audit_log (
        fiscal_year,
        period,
        user_id,
        country_code,
        action_type,
        entity_type,
        entity_id,
        metadata,
        ip_address,
        document_number
    )
    values (
        v_fiscal_year,
        v_period,
        v_user.id,
        v_user.country_code,
        v_audit_action,
        'external',
        'finance',
        jsonb_build_object(
            'document_number',
            v_new_document_number,

            'reference',
            v_transaction_reference,

            'entry_reference',
            v_entry_reference,

            'transaction_type',
            p_transaction_type,

            'currency_code',
            v_currency_code,

            'amount',
            v_amount::text,

            'reversal_of',
            v_reversal_of
        ),
        p_ip_address,
        v_new_document_number
    );

    return jsonb_build_object(
        'success',
        true,

        'document_number',
        v_new_document_number,

        'reference',
        v_transaction_reference,

        'transaction_type',
        p_transaction_type,

        'currency_code',
        v_currency_code,

        'amount',
        v_amount::text,

        'reversal_of',
        v_reversal_of
    );
end;
$$;
ALTER FUNCTION "public"."execute_my_external_funding"("p_transaction_type" "public"."TransactionType", "p_currency_code" "text", "p_amount" numeric, "p_document_number" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."execute_my_gold_inventory_purchase"("p_transaction_type" "public"."TransactionType", "p_token_total_supply" numeric, "p_quantity_grams" numeric DEFAULT NULL::numeric, "p_price_per_gram" numeric DEFAULT NULL::numeric, "p_currency_code" "text" DEFAULT NULL::"text", "p_bar_serial_number" "text" DEFAULT NULL::"text", "p_supplier_name" "text" DEFAULT NULL::"text", "p_custodian_name" "text" DEFAULT NULL::"text", "p_document_number" "text" DEFAULT NULL::"text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;
    v_treasury public.users%rowtype;

    v_original_transaction
        public.financial_transaction%rowtype;

    v_original_reserve
        public.asset_reserve%rowtype;

    v_treasury_wallet
        public.wallet%rowtype;

    v_is_reversal boolean;

    v_quantity numeric;
    v_price numeric;
    v_total_value numeric;

    v_currency_code text;
    v_bar_serial_number text;

    v_supplier_name text;
    v_custodian_name text;

    v_description text;

    v_fiscal_year integer;
    v_period integer;

    v_mappings
        public.transaction_gl_mapping[];

    v_components
        public.posting_component[];

    v_document_prefix text;
    v_new_document_number text;

    v_transaction_reference text;
    v_entry_reference text;
    v_reversal_of text;
    v_reversed_by text;

    v_financial_transaction_id bigint;

    v_asset_entry_id
        public.asset_entry.id%type;

    v_asset_reserve_id
        public.asset_reserve.id%type;

    v_wallet_debit numeric := 0;
    v_wallet_credit numeric := 0;

    v_physical_gold_balance numeric := 0;

    /*
     * Pending mint quantities are positive.
     * Pending burning quantities are negative.
     */
    v_pending_token_adjustment numeric := 0;

    v_projected_token_supply numeric := 0;
    v_token_difference numeric := 0;

    v_minimum_adjustment numeric :=
        0.000001;

    v_adjustment_type
        public."TokenAdjustmentType";

    v_adjustment_request_id
        public.tokenised_asset_adjustment_request.id%type;

    v_adjustment_created boolean :=
        false;

    v_audit_action
        public."AuditActionType";
begin
    /*
     * Authenticate and authorize.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if not public.has_role(
        array[
            'finance'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Validate transaction type.
     */
    if p_transaction_type not in (
        'gold_inventory_purchase'::public."TransactionType",
        'gold_inventory_purchase_reversal'::public."TransactionType"
    ) then
        raise exception
            'INVALID_GOLD_INVENTORY_TRANSACTION_TYPE_%',
            p_transaction_type;
    end if;

    v_is_reversal :=
        p_transaction_type =
        'gold_inventory_purchase_reversal'::public."TransactionType";

    if p_token_total_supply is null
       or p_token_total_supply < 0
    then
        raise exception
            'INVALID_TOKEN_TOTAL_SUPPLY';
    end if;


    /*
     * Fetch trusted finance-user context.
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'FINANCE_USER_NOT_FOUND';
    end if;

    if v_user.country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Fetch country treasury.
     */
    v_treasury :=
        public.fetch_country_treasury(
            v_user.country_code
        );

    if v_treasury.id is null then
        raise exception
            'TREASURY_NOT_FOUND';
    end if;

    /*
     * Normal Gold inventory purchase.
     */
    if not v_is_reversal then
        v_quantity :=
            public.round_down(
                p_quantity_grams
            );

        if v_quantity is null
           or v_quantity <= 0
        then
            raise exception
                'INVALID_GOLD_QUANTITY';
        end if;

        v_price :=
            p_price_per_gram;

        if v_price is null
           or v_price <= 0
        then
            raise exception
                'INVALID_GOLD_PRICE';
        end if;

        v_currency_code :=
            lower(
                nullif(
                    btrim(p_currency_code),
                    ''
                )
            );

        if v_currency_code is null then
            raise exception
                'CURRENCY_REQUIRED';
        end if;

        v_bar_serial_number :=
            nullif(
                btrim(p_bar_serial_number),
                ''
            );

        if v_bar_serial_number is null then
            raise exception
                'BAR_SERIAL_NUMBER_REQUIRED';
        end if;

        /*
         * Prevent an active physical bar from being captured
         * more than once in the same country.
         */
        perform 1
        from public.asset_reserve
            asset_reserve_record
        where asset_reserve_record.country_code =
              v_user.country_code

          and asset_reserve_record.bar_serial_number =
              v_bar_serial_number

          and asset_reserve_record.is_active =
              true
        limit 1;

        if found then
            raise exception
                'GOLD_BAR_ALREADY_CAPTURED';
        end if;

        v_supplier_name :=
            nullif(
                btrim(p_supplier_name),
                ''
            );

        v_custodian_name :=
            nullif(
                btrim(p_custodian_name),
                ''
            );

        v_total_value :=
            v_quantity *
            v_price;

        v_description :=
            format(
                'Gold inventory purchase %s',
                v_bar_serial_number
            );

        v_reversal_of :=
            null;

        v_reversed_by :=
            null;

        v_audit_action :=
            'gold_purchased'::public."AuditActionType";
    end if;

    /*
     * Gold inventory purchase reversal.
     */
    if v_is_reversal then
        if nullif(
            btrim(p_document_number),
            ''
        ) is null
        then
            raise exception
                'DOCUMENT_NUMBER_REQUIRED_FOR_REVERSAL';
        end if;

        /*
         * Lock the original financial transaction.
         */
        select financial_transaction_record.*
        into v_original_transaction
        from public.financial_transaction
            financial_transaction_record
        where financial_transaction_record.document_number =
              btrim(p_document_number)

          and financial_transaction_record.country_code =
              v_user.country_code
        for update;

        if not found then
            raise exception
                'DOCUMENT_NOT_FOUND';
        end if;

        if v_original_transaction.transaction_type <>
           'gold_inventory_purchase'::public."TransactionType"
        then
            raise exception
                'DOCUMENT_IS_NOT_GOLD_INVENTORY_PURCHASE';
        end if;

        /*
         * Prevent duplicate reversal.
         */
        perform 1
        from public.financial_transaction
            reversal_record
        where reversal_record.country_code =
              v_user.country_code

          and reversal_record.reversal_of =
              v_original_transaction.document_number

          and reversal_record.transaction_type =
              'gold_inventory_purchase_reversal'::public."TransactionType"
        limit 1;

        if found then
            raise exception
                'DOCUMENT_ALREADY_REVERSED';
        end if;

        /*
         * Lock and fetch the active original reserve.
         */
        select asset_reserve_record.*
        into v_original_reserve
        from public.asset_reserve
            asset_reserve_record
        where asset_reserve_record.document_number =
              v_original_transaction.document_number

          and asset_reserve_record.country_code =
              v_user.country_code

          and asset_reserve_record.type =
              'gold'::public."AssetType"

          and asset_reserve_record.is_active =
              true
        for update;

        if not found then
            raise exception
                'ACTIVE_ASSET_DOCUMENT_NOT_FOUND';
        end if;

        v_quantity :=
            v_original_reserve.quantity;

        v_price :=
            v_original_reserve.price;

        v_total_value :=
            v_original_reserve.total_value;

        if v_quantity is null
           or v_quantity <= 0
        then
            raise exception
                'INVALID_ORIGINAL_GOLD_QUANTITY';
        end if;

        if v_price is null
           or v_price <= 0
        then
            raise exception
                'INVALID_ORIGINAL_GOLD_PRICE';
        end if;

        if v_total_value is null
           or v_total_value <= 0
        then
            raise exception
                'INVALID_ORIGINAL_TOTAL_VALUE';
        end if;

        v_currency_code :=
            lower(
                v_original_reserve.currency_code
            );

        v_bar_serial_number :=
            v_original_reserve.bar_serial_number;

        v_supplier_name :=
            v_original_reserve.supplier_name;

        v_custodian_name :=
            v_original_reserve.custodian_name;

        v_description :=
            format(
                'Gold inventory purchase reversal %s',
                v_bar_serial_number
            );

        v_reversal_of :=
            v_original_transaction.document_number;

        v_reversed_by :=
            v_user.id;

        v_asset_reserve_id :=
            v_original_reserve.id;

        v_audit_action :=
            'gold_purchase_reversed'::public."AuditActionType";

        /*
         * Cancel a pending token adjustment created by the
         * original purchase.
         *
         * Completed requests remain intact. Reconciliation
         * later creates a burn request when required.
         */
        update public.tokenised_asset_adjustment_request
        set
            status =
                'cancelled'::public."AdjustmentStatus"
        where reference =
              v_original_reserve.asset_entry_id

          and status =
              'pending'::public."AdjustmentStatus";
    end if;

    /*
     * Fetch GL mappings.
     */
    select array_agg(mapping_record)
    into v_mappings
    from public.fetch_gl_mappings(
        p_transaction_type
    ) as mapping_record;

    if v_mappings is null
       or cardinality(v_mappings) = 0
    then
        raise exception
            'GL_MAPPINGS_NOT_FOUND';
    end if;

    /*
     * Build posting components.
     */
    v_components :=
        public.build_posting_components(
            p_transaction_type,
            v_total_value,
            v_mappings,
            v_user.country_code,
            v_currency_code,
            false
        );

    if v_components is null
       or cardinality(v_components) = 0
    then
        raise exception
            'POSTING_COMPONENTS_NOT_FOUND';
    end if;

    /*
     * Fetch fiscal period.
     */
    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_user.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Fetch configured document prefix.
     */
    v_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            p_transaction_type
        );

    if v_document_prefix is null
       or btrim(v_document_prefix) = ''
    then
        raise exception
            'DOCUMENT_PREFIX_NOT_FOUND';
    end if;

    /*
     * Generate document number.
     */
    v_new_document_number :=
        public.generate_document_number(
            v_document_prefix,
            v_fiscal_year,
            v_period,
            v_user.country_code
        );

    /*
     * The financial-transaction reference is unique.
     * Therefore the reversal receives its own reference.
     *
     * Financial entries and wallet entries reference the
     * original document when this is a reversal.
     */
    v_transaction_reference :=
        v_new_document_number;

    v_entry_reference :=
        coalesce(
            v_reversal_of,
            v_new_document_number
        );

    /*
     * Create financial transaction.
     */
    insert into public.financial_transaction (
        document_number,
        reference,
        fiscal_year,
        period,
        transaction_type,
        description,
        currency_code,
        created_by,
        gross_amount,
        country_code,
        reversal_of,
        reversed_by
    )
    values (
        v_new_document_number,
        v_transaction_reference,
        v_fiscal_year,
        v_period,
        p_transaction_type,
        v_description,
        v_currency_code,
        v_user.id,
        v_total_value,
        v_user.country_code,
        v_reversal_of,
        v_reversed_by
    )
    returning id
    into v_financial_transaction_id;

    /*
     * Post financial entries.
     */
    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_new_document_number,

        p_country_code =>
            v_user.country_code,

        p_transaction_id =>
            v_financial_transaction_id,

        p_transaction_type =>
            p_transaction_type,

        p_created_by =>
            v_user.id,

        p_components =>
            v_components,

        p_mappings =>
            v_mappings,

        p_currency_code =>
            v_currency_code,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_reference =>
            v_entry_reference,

        p_deposit_type =>
            null
    );

    /*
     * Record the physical Gold movement.
     *
     * Purchase:
     *     credit = quantity
     *
     * Reversal:
     *     debit = quantity
     *
     * Both amounts remain positive.
     */
    insert into public.asset_entry (
        document_number,
        fiscal_year,
        period,
        debit,
        credit,
        total_value,
        price,
        currency_code,
        created_by,
        country_code
    )
    values (
        v_new_document_number,
        v_fiscal_year,
        v_period,

        case
            when v_is_reversal
                then v_quantity
            else 0
        end,

        case
            when v_is_reversal
                then 0
            else v_quantity
        end,

        v_total_value,
        v_price,
        v_currency_code,
        v_user.id,
        v_user.country_code
    )
    returning id
    into v_asset_entry_id;

    /*
     * A purchase creates a new active physical reserve.
     *
     * A reversal deactivates the original reserve. It does
     * not insert a reserve containing negative amounts.
     */
    if not v_is_reversal then
        insert into public.asset_reserve (
            document_number,
            asset_entry_id,
            fiscal_year,
            period,
            bar_serial_number,
            type,
            quantity,
            uom,
            price,
            total_value,
            currency_code,
            supplier_name,
            custodian_name,
            acquisition_date,
            country_code,
            is_active
        )
        values (
            v_new_document_number,
            v_asset_entry_id,
            v_fiscal_year,
            v_period,
            v_bar_serial_number,
            'gold'::public."AssetType",
            v_quantity,
            'gram'::public."Uom",
            v_price,
            v_total_value,
            v_currency_code,
            v_supplier_name,
            v_custodian_name,
            now(),
            v_user.country_code,
            true
        )
        returning id
        into v_asset_reserve_id;
    else
        update public.asset_reserve
        set
            is_active = false
        where id =
              v_original_reserve.id

          and country_code =
              v_user.country_code

          and is_active =
              true;

        if not found then
            raise exception
                'ACTIVE_ASSET_DOCUMENT_NOT_FOUND';
        end if;

        v_asset_reserve_id :=
            v_original_reserve.id;
    end if;

    /*
     * Lock treasury fiat wallet.
     */
    select wallet_record.*
    into v_treasury_wallet
    from public.wallet
        wallet_record
    where wallet_record.country_code =
          v_user.country_code

      and wallet_record.user_id =
          v_treasury.id

      and lower(
          wallet_record.currency_code
      ) =
          v_currency_code

      and wallet_record.owner_type =
          'treasury'::public."WalletOwnerType"
    for update;

    if not found then
        raise exception
            'TREASURY_WALLET_NOT_FOUND';
    end if;

    if not v_treasury_wallet.is_active then
        raise exception
            'TREASURY_WALLET_FROZEN';
    end if;

    /*
     * Purchase pays for the physical Gold from treasury.
     * Reversal restores the amount to treasury.
     */
    if not v_is_reversal then
        update public.wallet
        set
            balance =
                balance -
                v_total_value
        where id =
              v_treasury_wallet.id

          and is_active =
              true

          and balance >=
              v_total_value;

        if not found then
            raise exception
                'INSUFFICIENT_TREASURY_BALANCE';
        end if;

        v_wallet_debit :=
            v_total_value;

        v_wallet_credit :=
            0;
    else
        update public.wallet
        set
            balance =
                balance +
                v_total_value
        where id =
              v_treasury_wallet.id

          and is_active =
              true;

        if not found then
            raise exception
                'TREASURY_WALLET_UPDATE_FAILED';
        end if;

        v_wallet_debit :=
            0;

        v_wallet_credit :=
            v_total_value;
    end if;

    /*
     * Create treasury wallet entry.
     */
    insert into public.wallet_entry (
        document_number,
        reference,
        fiscal_year,
        period,
        transaction_type,
        wallet_id,
        currency_code,
        country_code,
        debit,
        credit,
        created_by
    )
    values (
        v_new_document_number,
        v_entry_reference,
        v_fiscal_year,
        v_period,
        p_transaction_type,
        v_treasury_wallet.id,
        v_currency_code,
        v_user.country_code,
        v_wallet_debit,
        v_wallet_credit,
        v_user.id
    );

    /*
     * Update treasury wallet snapshot.
     */
    perform public.update_wallet_balance_snapshot(
        p_transaction_type,
        v_treasury.id,
        v_treasury.id,
        null,
        v_currency_code,
        'treasury'::public."WalletOwnerType",
        'treasury'::public."WalletOwnerType",
        v_wallet_debit,
        v_wallet_credit,
        v_fiscal_year,
        v_period,
        v_user.country_code,
        0
    );

    /*
     * Calculate the physical Gold balance from append-only
     * asset entries.
     */
    select coalesce(
        sum(
            coalesce(
                asset_entry_record.credit,
                0
            ) -
            coalesce(
                asset_entry_record.debit,
                0
            )
        ),
        0
    )
    into v_physical_gold_balance
    from public.asset_entry
        asset_entry_record;

    /*
     * Include pending mint and burn requests in projected
     * token supply to prevent duplicate requests.
     */
    select coalesce(
        sum(
            case
                when adjustment_record.adjustment_type =
                     'minting'::public."TokenAdjustmentType"
                then
                    adjustment_record.quantity

                when adjustment_record.adjustment_type =
                     'burning'::public."TokenAdjustmentType"
                then
                    -adjustment_record.quantity

                else
                    0
            end
        ),
        0
    )
    into v_pending_token_adjustment
    from public.tokenised_asset_adjustment_request
        adjustment_record
    where adjustment_record.status =
          'pending'::public."AdjustmentStatus";

    v_projected_token_supply :=
        p_token_total_supply +
        v_pending_token_adjustment;

    v_token_difference :=
        public.round_down(
            v_physical_gold_balance -
            v_projected_token_supply
        );

    /*
     * Positive difference requires minting.
     * Negative difference requires burning.
     */
    if abs(
        v_token_difference
    ) >= v_minimum_adjustment
    then
        v_adjustment_type :=
            case
                when v_token_difference > 0
                then
                    'minting'::public."TokenAdjustmentType"

                else
                    'burning'::public."TokenAdjustmentType"
            end;

        insert into public.tokenised_asset_adjustment_request (
            document_number,
            fiscal_year,
            period,
            reference,
            adjustment_type,
            quantity,
            uom,
            total_value,
            currency_code,
            status,
            description,
            created_by
        )
        values (
            v_new_document_number,
            v_fiscal_year,
            v_period,
            v_asset_entry_id,
            v_adjustment_type,
            abs(
                v_token_difference
            ),
            'gram'::public."Uom",
            abs(
                v_token_difference
            ) *
            v_price,
            v_currency_code,
            'pending'::public."AdjustmentStatus",

            case
                when v_adjustment_type =
                     'minting'::public."TokenAdjustmentType"
                then
                    'Physical Gold reserve requires token minting'
                else
                    'Physical Gold reserve requires token burning'
            end,

            v_user.id
        )
        returning id
        into v_adjustment_request_id;

        v_adjustment_created :=
            true;
    end if;

    /*
     * Audit the inventory purchase or reversal.
     */
    insert into public.audit_log (
        user_id,
        country_code,
        fiscal_year,
        period,
        action_type,
        entity_type,
        entity_id,
        document_number,
        metadata,
        ip_address
    )
    values (
        v_user.id,
        v_user.country_code,
        v_fiscal_year,
        v_period,
        v_audit_action,
        'gold_purchase',
        v_asset_reserve_id::text,
        v_new_document_number,

        jsonb_build_object(
            'transaction_type',
            p_transaction_type,

            'supplier',
            v_supplier_name,

            'quantity',
            v_quantity::text,

            'price_per_gram',
            v_price::text,

            'total_value',
            v_total_value::text,

            'currency',
            v_currency_code,

            'bar_serial_number',
            v_bar_serial_number,

            'reversal_of',
            v_reversal_of,

            'physical_gold_balance',
            v_physical_gold_balance::text,

            'onchain_token_supply',
            p_token_total_supply::text,

            'pending_token_adjustment',
            v_pending_token_adjustment::text,

            'token_difference',
            v_token_difference::text,

            'adjustment_request_id',
            v_adjustment_request_id
        ),

        p_ip_address
    );

    return jsonb_build_object(
        'success',
        true,

        'document_number',
        v_new_document_number,

        'transaction_type',
        p_transaction_type,

        'quantity_grams',
        v_quantity::text,

        'price_per_gram',
        v_price::text,

        'total_value',
        v_total_value::text,

        'currency',
        v_currency_code,

        'reversal_of',
        v_reversal_of,

        'physical_gold_balance',
        v_physical_gold_balance::text,

        'token_total_supply',
        p_token_total_supply::text,

        'projected_token_supply',
        v_projected_token_supply::text,

        'token_difference',
        v_token_difference::text,

        'adjustment_created',
        v_adjustment_created,

        'adjustment_request_id',
        v_adjustment_request_id,

        'adjustment_type',
        v_adjustment_type,

        'mint_status',
        case
            when v_adjustment_created
                then 'pending'
            else 'not_required'
        end
    );
end;
$$;
ALTER FUNCTION "public"."execute_my_gold_inventory_purchase"("p_transaction_type" "public"."TransactionType", "p_token_total_supply" numeric, "p_quantity_grams" numeric, "p_price_per_gram" numeric, "p_currency_code" "text", "p_bar_serial_number" "text", "p_supplier_name" "text", "p_custodian_name" "text", "p_document_number" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."execute_my_government_tax_settlement_batch"("p_batch_id" "text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_batch
        public.government_tax_settlement_batch%rowtype;

    v_item
        public.government_tax_settlement_item%rowtype;

    v_treasury public.users%rowtype;
    v_treasury_wallet public.wallet%rowtype;

    v_batch_id text;

    v_fiscal_year integer;
    v_period integer;

    v_mappings
        public.transaction_gl_mapping[];

    v_components
        public.posting_component[];

    v_document_prefix text;
    v_document_number text;
    v_reference text;

    v_financial_transaction_id
        public.financial_transaction.id%type;

    v_amount numeric;
    v_execution_total numeric := 0;

    v_payable_count integer := 0;
    v_updated_payables integer := 0;
    v_payable_total numeric := 0;

    v_eligible_items integer := 0;
    v_remaining_items integer := 0;

    v_success_count integer := 0;
    v_failed_count integer := 0;

    v_final_status
        public."SettlementStatus";

    v_item_error text;

    v_stage text :=
        'initialization';

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * Authentication and Accounts authorization.
     */
    v_stage :=
        'authorize accounts user';

    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'accounts'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Validate input.
     */
    v_stage :=
        'validate input';

    v_batch_id :=
        nullif(
            btrim(p_batch_id),
            ''
        );

    if v_batch_id is null then
        raise exception
            'SETTLEMENT_BATCH_ID_REQUIRED';
    end if;

    /*
     * Fetch trusted Accounts user.
     */
    v_stage :=
        'fetch accounts user';

    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'ACCOUNTS_USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'ACCOUNTS_USER_NOT_ACTIVE';
    end if;

    if nullif(
        btrim(
            v_user.country_code
        ),
        ''
    ) is null
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Lock the batch.
     *
     * This prevents two Accounts users from executing
     * the same batch simultaneously.
     */
    v_stage :=
        'lock tax settlement batch';

    select batch_record.*
    into v_batch
    from public.government_tax_settlement_batch
        batch_record
    where batch_record.id::text =
              v_batch_id

      and lower(
          btrim(
              batch_record.country_code
          )
      ) =
          lower(
              btrim(
                  v_user.country_code
              )
          )
    for update;

    if not found then
        raise exception
            'GOVERNMENT_TAX_SETTLEMENT_BATCH_NOT_FOUND';
    end if;

    /*
     * Approved batches can be settled.
     * Partial and failed batches can retry failed items.
     */
    if v_batch.status::text not in (
        'approved',
        'partial',
        'failed'
    ) then
        raise exception
            'ONLY_APPROVED_PARTIAL_OR_FAILED_TAX_BATCHES_CAN_BE_SETTLED';
    end if;

    /*
     * Fetch current fiscal period.
     */
    v_stage :=
        'fetch fiscal period';

    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_batch.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Fetch country treasury.
     */
    v_stage :=
        'fetch country treasury';

    select treasury_record.*
    into v_treasury
    from public.fetch_country_treasury(
        v_batch.country_code
    ) as treasury_record;

    if not found
       or v_treasury.id is null
    then
        raise exception
            'TREASURY_NOT_FOUND';
    end if;

    /*
     * Lock the sender Treasury wallet.
     *
     * Unlike a receiver wallet, a sender wallet must
     * already exist.
     */
    v_stage :=
        'lock treasury wallet';

    select wallet_record.*
    into v_treasury_wallet
    from public.wallet
        wallet_record
    where wallet_record.user_id =
              v_treasury.id

      and lower(
          btrim(
              wallet_record.country_code
          )
      ) =
          lower(
              btrim(
                  v_batch.country_code
              )
          )

      and lower(
          btrim(
              wallet_record.currency_code
          )
      ) =
          lower(
              btrim(
                  v_batch.currency_code
              )
          )

      and wallet_record.owner_type =
          'treasury'::public."WalletOwnerType"
    for update;

    if not found then
        raise exception
            'TREASURY_WALLET_NOT_FOUND';
    end if;

    if not v_treasury_wallet.is_active then
        raise exception
            'TREASURY_WALLET_NOT_ACTIVE';
    end if;

    /*
     * Lock settlement items eligible for processing.
     */
    v_stage :=
        'lock eligible tax settlement items';

    perform 1
    from public.government_tax_settlement_item
        item_record
    where item_record.batch_id =
              v_batch.id

      and item_record.status::text in (
          'approved',
          'failed'
      )
    for update;

    /*
     * Count eligible items and calculate the amount that
     * will be paid during this execution.
     */
    select
        count(*)::integer,

        coalesce(
            sum(
                item_record.tax_amount
            ),
            0
        )
    into
        v_eligible_items,
        v_execution_total
    from public.government_tax_settlement_item
        item_record
    where item_record.batch_id =
              v_batch.id

      and item_record.status::text in (
          'approved',
          'failed'
      );

    if v_eligible_items = 0 then
        raise exception
            'NO_GOVERNMENT_TAX_SETTLEMENT_ITEMS_TO_PROCESS';
    end if;

    if v_execution_total <= 0 then
        raise exception
            'INVALID_GOVERNMENT_TAX_SETTLEMENT_TOTAL';
    end if;

    /*
     * Validate Treasury funds before paying any item.
     *
     * This prevents some items from succeeding merely
     * because the Treasury wallet ran out of funds
     * halfway through the batch.
     */
    if coalesce(
        v_treasury_wallet.balance,
        0
    ) <
       v_execution_total
    then
        raise exception
            'INSUFFICIENT_TREASURY_WALLET_BALANCE_AVAILABLE_%_REQUIRED_%',
            coalesce(
                v_treasury_wallet.balance,
                0
            ),
            v_execution_total;
    end if;

    /*
     * Fetch Government Tax clearing GL mappings.
     *
     * Expected posting:
     *
     * Dr Government Tax Payable
     * Cr Cash/Bank Reserve
     */
    v_stage :=
        'fetch government tax clearing mappings';

    select array_agg(
        mapping_record
        order by
            mapping_record.component_type
    )
    into v_mappings
    from public.fetch_gl_mappings(
        'government_tax_clearing'::public."TransactionType"
    ) as mapping_record;

    if v_mappings is null
       or cardinality(v_mappings) = 0
    then
        raise exception
            'GOVERNMENT_TAX_CLEARING_GL_MAPPINGS_NOT_FOUND';
    end if;

    /*
     * Fetch document prefix.
     */
    v_stage :=
        'fetch document prefix';

    v_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            'government_tax_clearing'::public."TransactionType"
        );

    if nullif(
        btrim(
            v_document_prefix
        ),
        ''
    ) is null
    then
        raise exception
            'DOCUMENT_PREFIX_NOT_FOUND';
    end if;

    /*
     * Mark batch processing.
     */
    v_stage :=
        'mark tax batch processing';

    update public.government_tax_settlement_batch
    set
        status =
            'processing',

        error_message =
            null
    where id =
          v_batch.id;

    if not found then
        raise exception
            'GOVERNMENT_TAX_BATCH_PROCESSING_UPDATE_FAILED';
    end if;

    /*
     * Process approved and previously failed items.
     *
     * Each nested block is a PostgreSQL subtransaction.
     * If one item fails, its own GL and wallet posting is
     * rolled back while other successful items remain.
     */
    for v_item in
        select item_record.*
        from public.government_tax_settlement_item
            item_record
        where item_record.batch_id =
                  v_batch.id

          and item_record.status::text in (
              'approved',
              'failed'
          )
        order by
            item_record.transaction_type,
            item_record.id
        for update
    loop
        begin
            v_item_error :=
                null;

            v_amount :=
                coalesce(
                    v_item.tax_amount,
                    0
                );

            if v_amount <= 0 then
                raise exception
                    'INVALID_GOVERNMENT_TAX_ITEM_AMOUNT';
            end if;

            /*
             * Lock underlying tax payable rows for this
             * transaction type.
             */
            v_stage :=
                'lock underlying tax payables';

            perform 1
            from public.government_tax_payable
                payable_record
            where payable_record.settlement_batch_id =
                      v_batch.id

              and payable_record.transaction_type =
                      v_item.transaction_type

              and lower(
                  btrim(
                      payable_record.currency_code
                  )
              ) =
                  lower(
                      btrim(
                          v_batch.currency_code
                      )
                  )

              and payable_record.is_settled =
                      false
            for update;

            /*
             * Validate that the underlying payable total
             * matches the settlement item.
             */
            select
                count(*)::integer,

                coalesce(
                    sum(
                        payable_record.tax_amount
                    ),
                    0
                )
            into
                v_payable_count,
                v_payable_total
            from public.government_tax_payable
                payable_record
            where payable_record.settlement_batch_id =
                      v_batch.id

              and payable_record.transaction_type =
                      v_item.transaction_type

              and lower(
                  btrim(
                      payable_record.currency_code
                  )
              ) =
                  lower(
                      btrim(
                          v_batch.currency_code
                      )
                  )

              and payable_record.is_settled =
                      false;

            if v_payable_count = 0 then
                raise exception
                    'UNSETTLED_GOVERNMENT_TAX_PAYABLES_NOT_FOUND_FOR_%',
                    v_item.transaction_type::text;
            end if;

            if v_payable_total <>
               v_amount
            then
                raise exception
                    'GOVERNMENT_TAX_AMOUNT_MISMATCH_EXPECTED_%_FOUND_%',
                    v_amount,
                    v_payable_total;
            end if;

            /*
             * Mark the current item processing.
             */
            v_stage :=
                'mark tax settlement item processing';

            update public.government_tax_settlement_item
            set
                status =
                    'processing',

                error_message =
                    null
            where id =
                  v_item.id;

            /*
             * Build GL components for the tax amount.
             */
            v_stage :=
                'build tax clearing components';

            v_components :=
                public.build_posting_components(
                    'government_tax_clearing'::public."TransactionType",
                    v_amount,
                    v_mappings,
                    v_batch.country_code,
                    lower(
                        btrim(
                            v_batch.currency_code
                        )
                    ),
                    false
                );

            if v_components is null
               or cardinality(v_components) = 0
            then
                raise exception
                    'GOVERNMENT_TAX_CLEARING_COMPONENTS_NOT_FOUND';
            end if;

            v_components :=
                public.validate_components(
                    v_components
                );

            /*
             * Generate one financial document per
             * transaction-type settlement item.
             */
            v_stage :=
                'generate tax clearing document number';

            v_document_number :=
                public.generate_document_number(
                    v_document_prefix,
                    v_fiscal_year,
                    v_period,
                    v_batch.country_code
                );

            v_reference :=
                format(
                    '%s_%s',
                    v_batch.document_number,
                    v_item.transaction_type::text
                );

            /*
             * Create financial transaction header.
             */
            v_stage :=
                'create tax clearing transaction';

            insert into public.financial_transaction (
                document_number,
                reference,
                fiscal_year,
                period,
                transaction_type,
                description,
                created_by,
                gross_amount,
                currency_code,
                country_code
            )
            values (
                v_document_number,
                v_reference,
                v_fiscal_year,
                v_period,
                'government_tax_clearing'::public."TransactionType",

                format(
                    'Government Tax settlement for %s from batch %s',
                    v_item.transaction_type::text,
                    v_batch.document_number
                ),

                v_user.id,
                v_amount,
                lower(
                    btrim(
                        v_batch.currency_code
                    )
                ),
                v_batch.country_code
            )
            returning id
            into v_financial_transaction_id;

            /*
             * Post:
             *
             * Dr Government Tax Payable
             * Cr Cash/Bank Reserve
             */
            v_stage :=
                'post tax clearing financial entries';

            perform *
            from public.post_financial_entries(
                p_document_number =>
                    v_document_number,

                p_country_code =>
                    v_batch.country_code,

                p_transaction_id =>
                    v_financial_transaction_id,

                p_transaction_type =>
                    'government_tax_clearing'::public."TransactionType",

                p_created_by =>
                    v_user.id,

                p_components =>
                    v_components,

                p_mappings =>
                    v_mappings,

                p_currency_code =>
                    lower(
                        btrim(
                            v_batch.currency_code
                        )
                    ),

                p_fiscal_year =>
                    v_fiscal_year,

                p_period =>
                    v_period,

                p_reference =>
                    v_reference,

                p_deposit_type =>
                    null
            );

            /*
             * Debit only the Treasury wallet.
             *
             * Government does not have an application
             * user wallet, therefore post_wallet_entries
             * is not used for this transaction.
             */
            v_stage :=
                'debit treasury wallet';

            update public.wallet
            set
                balance =
                    balance -
                    v_amount
            where id =
                      v_treasury_wallet.id

              and is_active =
                      true

              and balance >=
                      v_amount;

            if not found then
                raise exception
                    'TREASURY_WALLET_DEBIT_FAILED';
            end if;

            /*
             * Record the outgoing Treasury wallet entry.
             */
            v_stage :=
                'create treasury wallet entry';

            insert into public.wallet_entry (
                document_number,
                reference,
                fiscal_year,
                period,
                transaction_type,
                wallet_id,
                currency_code,
                country_code,
                debit,
                credit,
                created_by
            )
            values (
                v_document_number,
                v_reference,
                v_fiscal_year,
                v_period,
                'government_tax_clearing'::public."TransactionType",
                v_treasury_wallet.id,
                lower(
                    btrim(
                        v_batch.currency_code
                    )
                ),
                v_batch.country_code,
                v_amount,
                0,
                v_user.id
            );

            /*
             * Update Treasury wallet snapshot.
             *
             * The first amount is debit/outgoing.
             * The second amount is credit/incoming.
             */
            v_stage :=
                'update treasury wallet snapshot';

            perform public.update_wallet_balance_snapshot(
                'government_tax_clearing'::public."TransactionType",
                v_treasury.id,
                v_treasury.id,
                null,
                lower(
                    btrim(
                        v_batch.currency_code
                    )
                ),
                'treasury'::public."WalletOwnerType",
                'treasury'::public."WalletOwnerType",
                v_amount,
                0,
                v_fiscal_year,
                v_period,
                v_batch.country_code,
                0
            );

            /*
             * Mark the underlying tax payables settled.
             */
            v_stage :=
                'settle government tax payables';

            update public.government_tax_payable
            set
                is_settled =
                    true,

                settled_at =
                    now(),

                settled_by =
                    v_user.id
            where settlement_batch_id =
                      v_batch.id

              and transaction_type =
                      v_item.transaction_type

              and lower(
                  btrim(
                      currency_code
                  )
              ) =
                  lower(
                      btrim(
                          v_batch.currency_code
                      )
                  )

              and is_settled =
                      false;

            get diagnostics
                v_updated_payables =
                    row_count;

            if v_updated_payables <>
               v_payable_count
            then
                raise exception
                    'GOVERNMENT_TAX_PAYABLE_UPDATE_COUNT_MISMATCH_EXPECTED_%_UPDATED_%',
                    v_payable_count,
                    v_updated_payables;
            end if;

            /*
             * Mark the settlement item successful.
             */
            v_stage :=
                'complete tax settlement item';

            update public.government_tax_settlement_item
            set
                status =
                    'settled',

                paid_at =
                    now(),

                error_message =
                    null
            where id =
                  v_item.id;

            if not found then
                raise exception
                    'GOVERNMENT_TAX_SETTLEMENT_ITEM_UPDATE_FAILED';
            end if;

            v_success_count :=
                v_success_count + 1;

        exception
            when others then
                get stacked diagnostics
                    v_item_error =
                        message_text;

                /*
                 * Any GL, wallet, payable, and item
                 * changes made inside this nested block
                 * have been rolled back.
                 */
                update public.government_tax_settlement_item
                set
                    status =
                        'failed',

                    error_message =
                        left(
                            coalesce(
                                v_item_error,
                                'UNKNOWN_TAX_SETTLEMENT_ERROR'
                            ),
                            1000
                        )
                where id =
                      v_item.id;

                v_failed_count :=
                    v_failed_count + 1;
        end;
    end loop;

    /*
     * Check whether any item remains unsettled.
     */
    v_stage :=
        'calculate final tax batch status';

    select count(*)::integer
    into v_remaining_items
    from public.government_tax_settlement_item
        item_record
    where item_record.batch_id =
              v_batch.id

      and item_record.status::text <>
              'settled';

    if v_remaining_items = 0 then
        v_final_status :=
            'settled'::public."SettlementStatus";

    elsif v_success_count = 0
          and v_failed_count > 0
    then
        v_final_status :=
            'failed'::public."SettlementStatus";

    else
        v_final_status :=
            'partial'::public."SettlementStatus";
    end if;

    /*
     * Complete the batch.
     *
     * paid_at is only populated when at least one tax
     * item was paid successfully.
     */
    v_stage :=
        'complete tax settlement batch';

    update public.government_tax_settlement_batch
    set
        status =
            v_final_status,

        paid_at =
            case
                when v_success_count > 0
                then coalesce(
                    paid_at,
                    now()
                )
                else paid_at
            end,

        error_message =
            case
                when v_final_status::text = 'failed'
                then format(
                    'All %s tax settlement item(s) failed',
                    v_failed_count
                )

                when v_final_status::text = 'partial'
                then format(
                    '%s tax settlement item(s) failed',
                    v_failed_count
                )

                else null
            end
    where id =
          v_batch.id
    returning *
    into v_batch;

    if not found then
        raise exception
            'GOVERNMENT_TAX_BATCH_FINAL_UPDATE_FAILED';
    end if;

    return jsonb_build_object(
        'success',
        true,

        'batch_id',
        v_batch.id,

        'document_number',
        v_batch.document_number,

        'currency_code',
        v_batch.currency_code,

        'status',
        v_final_status,

        'processed',
        v_success_count +
        v_failed_count,

        'success_count',
        v_success_count,

        'failed_count',
        v_failed_count,

        'remaining_items',
        v_remaining_items
    );

exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;

        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'GOVERNMENT_TAX_SETTLEMENT_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                concat_ws(
                    E'\n',
                    nullif(
                        v_error_detail,
                        ''
                    ),
                    nullif(
                        v_error_context,
                        ''
                    )
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    'Check the Government Tax Settlement stage'
                );
end;
$$;
ALTER FUNCTION "public"."execute_my_government_tax_settlement_batch"("p_batch_id" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."execute_my_loan_disbursement"("p_requested_amount" "text", "p_token_balance" "text", "p_reference" "text", "p_currency_code" "text" DEFAULT 'usd'::"text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "document_number" "text", "loan_id" "text", "customer_id" "text", "country_code" "text", "currency_code" "text", "principal_amount" "text", "collateral_locked" "text", "initiation_fee" "text", "net_disbursed" "text", "notification_id" "text", "device_tokens" "text"[], "push_title" "text", "push_body" "text", "push_reference" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_transaction_type
        public."TransactionType" :=
        'loan_disbursement'::public."TransactionType";

    v_stage text :=
        'initialization';

    v_user
        public.users%rowtype;

    v_treasury
        public.users%rowtype;

    v_collateral
        public.collateral%rowtype;

    v_reference text;
    v_currency text;

    /*
     * Full loan principal.
     *
     * Example:
     *
     * requested loan = 100
     *
     * principal = 100
     */
    v_requested_amount numeric;

    v_preview jsonb;
    v_preview_data jsonb;

    v_required_collateral numeric;
    v_initiation_fee numeric;

    /*
     * Actual USD amount credited to the customer's wallet.
     *
     * Example:
     *
     * principal       = 100
     * initiation fee  = 2
     * net disbursed   = 98
     */
    v_net_disbursed numeric;

    v_liquidation_price numeric;
    v_ltv_percent numeric;
    v_liquidation_ltv_percent numeric;

    v_loan_interest numeric :=
        12;

    v_fiscal_year integer;
    v_period integer;

    v_mappings
        public.transaction_gl_mapping[];

    v_components
        public.posting_component[];

    v_document_prefix text;
    v_document_number text;

    v_financial_transaction_id bigint;
    v_loan_id text;

    v_receiver_notification
        public.notification_message;

    v_receiver_notification_id text;

    v_device_tokens text[] :=
        array[]::text[];

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;

begin
    /*
     * ==========================================================
     * AUTHENTICATION / AUTHORIZATION
     * ==========================================================
     */
    v_stage :=
        'authorize customer';

    if auth.uid() is null then
        raise exception using
            errcode =
                '42501',
            message =
                'UNAUTHORIZED';
    end if;


    if not public.has_role(
        array[
            'customer',
            'agent',
            'vendor'
        ]::text[]
    ) then
        raise exception using
            errcode =
                '42501',
            message =
                'FORBIDDEN';
    end if;


    select
        user_record.*
    into
        v_user
    from public.users
        user_record
    where user_record.id =
          auth.uid()::text
    limit 1;


    if not found then
        raise exception
            'USER_NOT_FOUND';
    end if;


    if v_user.status is distinct from
       'active'::public."UserStatus"
    then
        raise exception
            'USER_NOT_ACTIVE';
    end if;


    if v_user.country_code is null
       or btrim(
           v_user.country_code
       ) = ''
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;


    /*
     * ==========================================================
     * PARSE REQUESTED AMOUNT
     * ==========================================================
     */
    v_stage :=
        'parse requested amount';


    begin
        v_requested_amount :=
            nullif(
                btrim(
                    p_requested_amount
                ),
                ''
            )::numeric;

    exception
        when invalid_text_representation
          or numeric_value_out_of_range
        then
            raise exception
                'INVALID_LOAN_AMOUNT';
    end;


    if v_requested_amount is null
       or v_requested_amount::text in ('NaN', 'Infinity', '-Infinity')
       or v_requested_amount <> trunc(v_requested_amount, 2)
       or v_requested_amount <= 0
    then
        raise exception
            'INVALID_LOAN_AMOUNT';
    end if;


    /*
     * ==========================================================
     * PARSE REFERENCE
     * ==========================================================
     */
    v_stage :=
        'parse reference';


    v_reference :=
        nullif(
            btrim(
                p_reference
            ),
            ''
        );


    if v_reference is null then
        raise exception
            'REFERENCE_REQUIRED';
    end if;


    /*
     * ==========================================================
     * PARSE CURRENCY
     * ==========================================================
     *
     * Loans are always USD.
     */
    v_stage :=
        'parse currency';


    v_currency :=
        lower(
            nullif(
                btrim(
                    p_currency_code
                ),
                ''
            )
        );


    if v_currency is null then
        raise exception
            'CURRENCY_MISSING';
    end if;


    if v_currency <> 'usd' then
        raise exception
            'UNSUPPORTED_LOAN_CURRENCY';
    end if;


    /*
     * ==========================================================
     * REPLAY PROTECTION
     * ==========================================================
     */
    v_stage :=
        'lock loan reference';


    perform
        pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(
                v_reference,
                0
            )
        );


    perform 1
    from public.financial_transaction
        transaction_record
    where transaction_record.reference =
          v_reference;


    if found then
        raise exception using
            errcode =
                '23505',
            message =
                'TRANSACTION_REPLAY';
    end if;


    /*
     * ==========================================================
     * FETCH COUNTRY TREASURY
     * ==========================================================
     */
    -- Use the same per-user lock as liquidation detection/repayment.
    v_stage := 'lock loan position';
    perform pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('loan-position:' || v_user.id, 0)
    );
    if exists (
        select 1 from public.liquidation_job as j
        where j.user_id = v_user.id
          and j.status::text not in ('completed', 'cancelled')
    ) then
        raise exception 'LOAN_POSITION_LIQUIDATION_IN_PROGRESS';
    end if;

    v_stage :=
        'fetch country treasury';


    v_treasury :=
        public.fetch_country_treasury(
            v_user.country_code
        );


    if v_treasury.id is null then
        raise exception
            'TREASURY_WALLET_NOT_CONFIGURED';
    end if;


    /*
     * ==========================================================
     * ENSURE COLLATERAL ROW EXISTS
     * ==========================================================
     */
    v_stage :=
        'create collateral row';


    insert into public.collateral (
        user_id,
        locked_tokens,
        country_code
    )
    values (
        v_user.id,
        0,
        v_user.country_code
    )
    on conflict (
        user_id
    )
    do nothing;


    /*
     * ==========================================================
     * LOCK COLLATERAL
     * ==========================================================
     */
    v_stage :=
        'lock collateral row';


    select
        collateral_record.*
    into
        v_collateral
    from public.collateral
        collateral_record
    where collateral_record.user_id =
          v_user.id
    for update;


    if not found then
        raise exception
            'COLLATERAL_NOT_FOUND';
    end if;


    if v_collateral.country_code
       is distinct from
       v_user.country_code
    then
        raise exception
            'COLLATERAL_COUNTRY_MISMATCH';
    end if;


    /*
     * ==========================================================
     * RECALCULATE LOAN PREVIEW
     * ==========================================================
     */
    v_stage :=
        'recalculate loan preview';


    v_preview :=
        public.preview_my_loan(
            p_requested_amount =>
                v_requested_amount::text,

            p_token_balance =>
                p_token_balance,

            p_currency_code =>
                v_currency
        );


    if v_preview is null
       or coalesce(
           (
               v_preview
               ->> 'success'
           )::boolean,
           false
       ) = false
    then
        raise exception
            'LOAN_PREVIEW_FAILED';
    end if;


    v_preview_data :=
        v_preview
        -> 'data';


    if v_preview_data is null then
        raise exception
            'LOAN_PREVIEW_DATA_NOT_FOUND';
    end if;


    begin
        v_required_collateral :=
            (
                v_preview_data
                ->> 'required_collateral_grams'
            )::numeric;


        v_initiation_fee :=
            (
                v_preview_data
                ->> 'initiation_fee'
            )::numeric;


        v_net_disbursed :=
            (
                v_preview_data
                ->> 'net_disbursed'
            )::numeric;


        v_liquidation_price :=
            (
                v_preview_data
                -> 'risk'
                ->> 'liquidationPrice'
            )::numeric;


        v_ltv_percent :=
            (
                v_preview_data
                ->> 'ltv_percent'
            )::numeric;


        v_liquidation_ltv_percent :=
            (
                v_preview_data
                ->> 'liquidation_ltv_percent'
            )::numeric;

    exception
        when invalid_text_representation
          or numeric_value_out_of_range
        then
            raise exception
                'INVALID_LOAN_PREVIEW_RESULT';
    end;


    if v_required_collateral is null
       or v_required_collateral::text in ('NaN', 'Infinity', '-Infinity')
       or v_required_collateral <= 0 then
        raise exception
            'INVALID_COLLATERAL_AMOUNT';
    end if;


    if v_initiation_fee is null
       or v_initiation_fee::text in ('NaN', 'Infinity', '-Infinity')
       or v_initiation_fee < 0 then
        raise exception
            'INVALID_INITIATION_FEE';
    end if;


    if v_net_disbursed is null
       or v_net_disbursed::text in ('NaN', 'Infinity', '-Infinity')
       or v_net_disbursed <= 0 then
        raise exception
            'INVALID_NET_DISBURSEMENT';
    end if;


    if v_liquidation_price is null
       or v_liquidation_price::text in ('NaN', 'Infinity', '-Infinity')
       or v_liquidation_price <= 0 then
        raise exception
            'INVALID_LIQUIDATION_PRICE';
    end if;


    /*
     * ==========================================================
     * FETCH LOAN INTEREST
     * ==========================================================
     */
    if v_required_collateral <> ceil(v_required_collateral * 1000000) / 1000000
       or v_initiation_fee <> trunc(v_initiation_fee, 2)
       or v_net_disbursed <> trunc(v_net_disbursed, 2)
       or v_net_disbursed + v_initiation_fee <> v_requested_amount
    then
        raise exception 'INVALID_LOAN_PREVIEW_RESULT';
    end if;

    -- Persist the configured borrowing LTV, not the display-rounded actual
    -- LTV from the risk summary (rounding collateral can slightly lower it).
    select c.rate into v_ltv_percent
    from public.loan_config as c
    where c.config_type = 'loan_ltv' and c.is_active = true
    limit 1;
    if not found or v_ltv_percent is null
       or v_ltv_percent::text in ('NaN', 'Infinity', '-Infinity')
       or v_ltv_percent <= 0 or v_ltv_percent >= 100
       or v_liquidation_ltv_percent is null
       or v_liquidation_ltv_percent::text in ('NaN', 'Infinity', '-Infinity')
       or v_liquidation_ltv_percent <= v_ltv_percent
       or v_liquidation_ltv_percent > 100
    then
        raise exception 'INVALID_LOAN_LTV_CONFIGURATION';
    end if;

    v_stage :=
        'fetch loan interest';


    select
        loan_config_record.rate
    into
        v_loan_interest
    from public.loan_config
        loan_config_record
    where loan_config_record.config_type =
          'loan_interest'
      and loan_config_record.is_active =
          true
    limit 1;


    v_loan_interest :=
        coalesce(
            v_loan_interest,
            12
        );


    if v_loan_interest is null
       or v_loan_interest::text in ('NaN', 'Infinity', '-Infinity')
       or v_loan_interest < 0 then
        raise exception
            'INVALID_LOAN_INTEREST_RATE';
    end if;


    /*
     * ==========================================================
     * FETCH FISCAL PERIOD
     * ==========================================================
     */
    v_stage :=
        'fetch fiscal period';


    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_user.country_code
    ) as fiscal_period;


    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * FETCH GL MAPPINGS
     * ==========================================================
     */
    v_stage :=
        'fetch GL mappings';


    select
        array_agg(
            mapping_record
        )
    into
        v_mappings
    from public.fetch_gl_mappings(
        v_transaction_type
    ) as mapping_record;


    if v_mappings is null
       or cardinality(
           v_mappings
       ) = 0
    then
        raise exception
            'GL_MAPPINGS_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * BUILD POSTING COMPONENTS
     * ==========================================================
     */
    v_stage :=
        'build posting components';


    v_components :=
        public.build_posting_components(
            v_transaction_type,
            v_requested_amount,
            v_mappings,
            v_user.country_code,
            v_currency,
            false
        );


    if v_components is null
       or cardinality(
           v_components
       ) = 0
    then
        raise exception
            'POSTING_COMPONENTS_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * CUSTOMER NOTIFICATION
     * ==========================================================
     */
    v_stage :=
        'create customer notification';


    v_receiver_notification :=
        public.create_notification_message(
            v_user.country_code,
            v_transaction_type,
            'receiver'::public."NotificationAudience",
            v_requested_amount,
            upper(
                v_currency
            ),
            v_reference,
            0,
            coalesce(
                v_treasury.email,
                v_treasury.phone,
                v_treasury.id
            ),
            coalesce(
                v_user.email,
                v_user.phone,
                v_user.id
            )
        );


    v_device_tokens :=
        coalesce(
            public.fetch_device_tokens(
                v_user.country_code,
                v_user.id
            ),
            array[]::text[]
        );


    /*
     * ==========================================================
     * DOCUMENT NUMBER
     * ==========================================================
     */
    v_stage :=
        'fetch document prefix';


    v_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            v_transaction_type
        );


    if v_document_prefix is null
       or btrim(
           v_document_prefix
       ) = ''
    then
        raise exception
            'DOCUMENT_PREFIX_NOT_FOUND';
    end if;


    v_stage :=
        'generate document number';


    v_document_number :=
        public.generate_document_number(
            v_document_prefix,
            v_fiscal_year,
            v_period,
            v_user.country_code
        );


    /*
     * ==========================================================
     * CREATE FINANCIAL TRANSACTION
     * ==========================================================
     */
    v_stage :=
        'create financial transaction';


    insert into public.financial_transaction (
        document_number,
        fiscal_year,
        reference,
        period,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        country_code
    )
    values (
        v_document_number,
        v_fiscal_year,
        v_reference,
        v_period,
        v_transaction_type,
        'Loan disbursement for user ' ||
            v_user.id,
        v_user.id,
        v_requested_amount,
        v_currency,
        v_user.country_code
    )
    returning
        id
    into
        v_financial_transaction_id;


    /*
     * ==========================================================
     * POST FINANCIAL ENTRIES
     * ==========================================================
     */
    v_stage :=
        'post financial entries';


    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_document_number,

        p_country_code =>
            v_user.country_code,

        p_transaction_id =>
            v_financial_transaction_id,

        p_transaction_type =>
            v_transaction_type,

        p_created_by =>
            v_user.id,

        p_components =>
            v_components,

        p_mappings =>
            v_mappings,

        p_currency_code =>
            v_currency,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_reference =>
            v_reference,

        p_deposit_type =>
            null
    );


    /*
     * ==========================================================
     * POST WALLET ENTRIES
     * ==========================================================
     *
     * Only the net loan proceeds are credited to the customer.
     *
     * Example:
     *
     * loan principal  = 100
     * initiation fee  = 2
     * wallet credit   = 98
     */
    v_stage :=
        'post wallet entries';


    select
        posting_result.receiver_notification_id
    into
        v_receiver_notification_id
    from public.post_wallet_entries(
        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_document_number =>
            v_document_number,

        p_reference =>
            v_reference,

        p_receiver_id =>
            v_user.id,

        p_sender_id =>
            v_treasury.id,

        p_transaction_type =>
            v_transaction_type,

        p_credit_amount =>
            v_net_disbursed,

        p_debit_amount =>
            v_net_disbursed,

        p_sender_wallet_owner =>
            'treasury'::public."WalletOwnerType",

        p_receiver_wallet_owner =>
            'customer'::public."WalletOwnerType",

        p_currency_code =>
            v_currency,

        p_country_code =>
            v_user.country_code,

        p_audit_action_type =>
            'loan_issued'::public."AuditActionType",

        p_treasury_id =>
            null,

        p_fee_amount =>
            0,

        p_ip_address =>
            p_ip_address,

        p_receiver_notification =>
            v_receiver_notification,

        p_sender_notification =>
            null
    ) as posting_result;


    /*
     * ==========================================================
     * CREATE LOAN
     * ==========================================================
     *
     * Principal remains the full requested loan amount.
     */
    v_stage :=
        'create loan';


    insert into public.loan (
        document_number,
        reference,
        user_id,
        fiscal_year,
        period,
        principal,
        net_amount,
        initiation_fee,
        interest_rate,
        collateral,
        max_ltv_percent,
        liquidation_ltv,
        liquidation_price,
        status,
        currency_code,
        country_code
    )
    values (
        v_document_number,
        v_reference,
        v_user.id,
        v_fiscal_year,
        v_period,
        v_requested_amount,
        v_net_disbursed,
        v_initiation_fee,
        v_loan_interest,
        v_required_collateral,
        v_ltv_percent,
        v_liquidation_ltv_percent,
        v_liquidation_price,
        'active'::public."LoanStatus",
        v_currency,
        v_user.country_code
    )
    returning
        id::text
    into
        v_loan_id;


    /*
     * ==========================================================
     * CREATE LOAN PRINCIPAL ENTRY
     * ==========================================================
     */
    v_stage :=
        'create loan entry';


    insert into public.loan_entry (
        loan_id,
        fiscal_year,
        period,
        document_number,
        entry_type,
        debit_principal,
        credit_principal,
        debit_interest,
        credit_interest,
        currency_code,
        country_code
    )
    values (
        v_loan_id,
        v_fiscal_year,
        v_period,
        v_document_number,
        'disbursement'::public."LoanEntryType",
        v_requested_amount,
        0,
        0,
        0,
        v_currency,
        v_user.country_code
    );


    /*
     * ==========================================================
     * UPDATE COLLATERAL
     * ==========================================================
     */
    v_stage :=
        'update collateral';


    update public.collateral
    set
        locked_tokens =
            coalesce(
                locked_tokens,
                0
            ) +
            v_required_collateral
    where user_id =
          v_user.id;


    if not found then
        raise exception
            'COLLATERAL_UPDATE_FAILED';
    end if;


    /*
     * ==========================================================
     * CREATE COLLATERAL ENTRY
     * ==========================================================
     */
    v_stage :=
        'create collateral entry';


    insert into public.collateral_entry (
        loan_id,
        document_number,
        debit,
        credit,
        country_code
    )
    values (
        v_loan_id,
        v_document_number,
        v_required_collateral,
        0,
        v_user.country_code
    );


    /*
     * ==========================================================
     * UPDATE LOAN SNAPSHOT
     * ==========================================================
     *
     * Full loan principal increases the outstanding loan.
     */
    v_stage :=
        'update loan snapshot';


    perform public.update_loan_snapshot(
        v_loan_id,
        v_user.id,
        v_user.country_code,
        v_requested_amount,
        0::numeric,
        0::numeric,
        0::numeric,
        v_fiscal_year,
        v_period
    );


    /*
     * ==========================================================
     * UPDATE COLLATERAL SNAPSHOT
     * ==========================================================
     */
    v_stage :=
        'update collateral snapshot';


    perform public.update_collateral_snapshot(
        v_user.id,
        v_user.country_code,
        v_required_collateral,
        0::numeric,
        v_fiscal_year,
        v_period
    );


    /*
     * ==========================================================
     * RETURN COMMITTED RESULT
     * ==========================================================
     *
     * Financial Intelligence uses:
     *
     * principal_amount
     *     = loan / borrowing increase
     *
     * net_disbursed
     *     = customer deposit / savings inflow
     *
     * Example:
     *
     * principal_amount = 100
     * net_disbursed    = 98
     *
     * FI:
     *
     * loan increase    +100
     * savings inflow   +98
     */
    return query
    select
        true,

        v_document_number,

        v_loan_id,

        v_user.id,

        lower(
            btrim(
                v_user.country_code
            )
        ),

        v_currency,

        to_char(
            round(
                v_requested_amount,
                2
            ),
            'FM999999999999999999999999990.00'
        ),

        to_char(
            round(
                v_required_collateral,
                6
            ),
            'FM999999999999999999999999990.000000'
        ),

        to_char(
            round(
                v_initiation_fee,
                2
            ),
            'FM999999999999999999999999990.00'
        ),

        to_char(
            round(
                v_net_disbursed,
                2
            ),
            'FM999999999999999999999999990.00'
        ),

        v_receiver_notification_id,

        v_device_tokens,

        v_receiver_notification.title,

        v_receiver_notification.body,

        v_receiver_notification.payload
            ->> 'reference';


exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;


        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'LOAN_DISBURSEMENT_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                coalesce(
                    nullif(
                        concat_ws(
                            E'\n',
                            nullif(
                                v_error_detail,
                                ''
                            ),
                            nullif(
                                v_error_context,
                                ''
                            )
                        ),
                        ''
                    ),
                    'No additional PostgreSQL context'
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    'Check the Loan Disbursement stage reported in the error'
                );

end;
$$;
ALTER FUNCTION "public"."execute_my_loan_disbursement"("p_requested_amount" "text", "p_token_balance" "text", "p_reference" "text", "p_currency_code" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."execute_my_loan_repayment"("p_amount" "text", "p_reference" "text", "p_currency_code" "text" DEFAULT 'usd'::"text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "document_number" "text", "principal_paid" "text", "interest_paid" "text", "collateral_unlocked" "text", "unused_payment" "text", "loans_closed" integer, "customer_id" "text", "country_code" "text", "currency_code" "text", "payment_applied" "text", "wallet_debit" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_transaction_type
        public."TransactionType" :=
            'loan_repayment'::public."TransactionType";

    v_stage text :=
        'initialization';

    v_user
        public.users%rowtype;

    v_treasury
        public.users%rowtype;

    v_collateral
        public.collateral%rowtype;

    v_loan
        public.loan%rowtype;

    v_reference text;
    v_currency text;


    /*
     * ==========================================================
     * REPAYMENT AMOUNTS
     * ==========================================================
     */

    /*
     * Amount entered by the customer.
     */
    v_payment_amount numeric;

    /*
     * Portion of the entered amount that remains after all
     * outstanding loans have been satisfied.
     *
     * This amount is NOT deducted from the customer's wallet.
     */
    v_remaining_payment numeric;


    v_principal_outstanding numeric;
    v_interest_outstanding numeric;

    v_principal_paid numeric;
    v_interest_paid numeric;


    v_total_principal_paid numeric :=
        0;

    v_total_interest_paid numeric :=
        0;


    /*
     * Exact amount actually applied to outstanding debt.
     *
     * payment_applied =
     *     principal_paid + interest_paid
     *
     * This is also the exact customer wallet debit.
     */
    v_total_payment_applied numeric :=
        0;


    v_principal_remaining numeric;
    v_interest_remaining numeric;

    /*
     * Remaining total debt after this repayment allocation.
     *
     * Collateral protection is based on the complete debt
     * position, not principal alone.
     */
    v_total_debt_remaining numeric :=
        0;


    /*
     * ==========================================================
     * COLLATERAL / RISK
     * ==========================================================
     */

    /*
     * Same current gold price source used by preview_my_loan().
     */
    v_market_price numeric :=
        0;

    -- Shared-pool calculation and current per-loan allocation plan.
    v_previous_locked numeric;
    v_required_pool numeric := 0;
    v_retained_pool numeric;
    v_remaining_pool numeric;
    v_allocation numeric;
    v_target_ltv numeric;
    v_target_collateral numeric;
    v_portfolio_ids text[] := ARRAY[]::text[];
    v_portfolio_id text;
    v_plan jsonb := '[]'::jsonb;
    v_plan_row jsonb;
    v_payments jsonb := '[]'::jsonb;
    v_payment_row jsonb;
    v_release_remaining numeric;
    v_payment_remaining numeric;
    v_release_part numeric;
    v_release_sum numeric := 0;
    v_liquidation_price numeric;

    /*
     * Total released across all loans affected by this repayment.
     */
    v_total_collateral_unlock numeric :=
        0;


    v_closed_loans_count integer :=
        0;

    v_active_loan_found boolean :=
        false;


    /*
     * ==========================================================
     * ACCOUNTING
     * ==========================================================
     */

    v_fiscal_year integer;
    v_period integer;

    v_document_prefix text;
    v_document_number text;

    v_financial_transaction_id bigint;

    v_mappings
        public.transaction_gl_mapping[];

    v_components
        public.posting_component[];


    /*
     * ==========================================================
     * ERROR DIAGNOSTICS
     * ==========================================================
     */

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;

begin
/*
 * ==========================================================
 * AUTHORIZE BORROWER
 * ==========================================================
 *
 * SVA / loan functionality is available to:
 *
 * - customer
 * - agent
 * - vendor
 *
 * Agent and vendor loans belong to the same user and use
 * that user's personal/customer wallet for repayment.
 */

    v_stage :=
        'authorize borrower';


    if auth.uid() is null then
        raise exception using
            errcode =
                '42501',

            message =
                'UNAUTHORIZED';
    end if;


    if not public.has_role(
        array[
            'customer',
            'agent',
            'vendor'
        ]::text[]
    ) then
        raise exception using
            errcode =
                '42501',

            message =
                'FORBIDDEN';
    end if;


    select
        user_record.*
    into
        v_user
    from public.users
        user_record
    where user_record.id =
        auth.uid()::text
    limit 1;


    if not found then
        raise exception
            'USER_NOT_FOUND';
    end if;


    if v_user.status is distinct from
    'active'::public."UserStatus"
    then
        raise exception
            'USER_NOT_ACTIVE';
    end if;


    if v_user.country_code is null
    or btrim(
        v_user.country_code
    ) = ''
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * ==========================================================
     * PARSE REPAYMENT AMOUNT
     * ==========================================================
     */

    v_stage :=
        'parse repayment amount';


    begin
        v_payment_amount :=
            nullif(
                btrim(
                    p_amount
                ),
                ''
            )::numeric;

    exception
        when invalid_text_representation
          or numeric_value_out_of_range
        then
            raise exception
                'INVALID_REPAYMENT_AMOUNT';
    end;


    if v_payment_amount is null
       or v_payment_amount::text in ('NaN', 'Infinity', '-Infinity')
       or v_payment_amount <= 0
       or v_payment_amount <> trunc(v_payment_amount, 2)
    then
        raise exception
            'INVALID_REPAYMENT_AMOUNT';
    end if;


    v_remaining_payment :=
        v_payment_amount;


    /*
     * ==========================================================
     * PARSE REFERENCE
     * ==========================================================
     */

    v_stage :=
        'parse reference';


    v_reference :=
        nullif(
            btrim(
                p_reference
            ),
            ''
        );


    if v_reference is null then
        raise exception
            'REFERENCE_REQUIRED';
    end if;


    /*
     * ==========================================================
     * PARSE CURRENCY
     * ==========================================================
     *
     * Loans are always USD.
     */

    v_stage :=
        'parse currency';


    v_currency :=
        lower(
            nullif(
                btrim(
                    p_currency_code
                ),
                ''
            )
        );


    if v_currency is null then
        raise exception
            'CURRENCY_MISSING';
    end if;


    if v_currency <> 'usd' then
        raise exception
            'UNSUPPORTED_LOAN_CURRENCY';
    end if;


    /*
     * ==========================================================
     * PREVENT REPLAY
     * ==========================================================
     */

    v_stage :=
        'lock repayment reference';


    perform
        pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(
                v_reference,
                0
            )
        );


    perform 1
    from public.financial_transaction
        transaction_record
    where transaction_record.reference =
          v_reference;


    if found then
        raise exception using
            errcode =
                '23505',

            message =
                'TRANSACTION_REPLAY';
    end if;


    /*
     * ==========================================================
     * SERIALIZE CUSTOMER REPAYMENTS
     * ==========================================================
     *
     * Prevent two repayments from allocating against the same
     * outstanding loan balances concurrently.
     */

    v_stage := 'lock customer loan position';

    perform pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'loan-position:' || v_user.id,
            0
        )
    );

    if exists (
        select 1
        from public.liquidation_job as j
        where j.user_id = v_user.id
        and j.status::text not in (
            'completed',
            'cancelled'
        )
    ) then
        raise exception
            'LOAN_POSITION_LIQUIDATION_IN_PROGRESS';
    end if;


    /*
     * ==========================================================
     * FETCH TREASURY
     * ==========================================================
     */

    v_stage :=
        'fetch country treasury';


    v_treasury :=
        public.fetch_country_treasury(
            v_user.country_code
        );


    if v_treasury.id is null then
        raise exception
            'TREASURY_WALLET_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * LOCK CUSTOMER COLLATERAL
     * ==========================================================
     */

    v_stage :=
        'lock collateral';


    select
        collateral_record.*
    into
        v_collateral
    from public.collateral
        collateral_record
    where collateral_record.user_id =
          v_user.id
    for update;


    if not found then
        raise exception
            'COLLATERAL_NOT_FOUND';
    end if;


    if v_collateral.country_code
       is distinct from
       v_user.country_code
    then
        raise exception
            'COLLATERAL_COUNTRY_MISMATCH';
    end if;


    /*
     * ==========================================================
     * FETCH CURRENT GOLD PRICE
     * ==========================================================
     *
     * This is the exact same source used by preview_my_loan().
     */

    v_previous_locked := v_collateral.locked_tokens;
    if v_previous_locked is null
       or v_previous_locked::text in ('NaN', 'Infinity', '-Infinity')
       or v_previous_locked < 0
       or v_previous_locked <> trunc(v_previous_locked, 6)
    then
        raise exception 'INVALID_LOCKED_COLLATERAL';
    end if;

    v_stage :=
        'fetch current gold price';


    select
        current_rate.rate_to_usd
    into
        v_market_price
    from public.current_rates
        current_rate
    where lower(
        btrim(
            current_rate.code
        )
    ) = 'gold'
    limit 1;


    v_market_price :=
        coalesce(
            v_market_price,
            0
        );


    if v_market_price is null
       or v_market_price::text in ('NaN', 'Infinity', '-Infinity')
       or v_market_price <= 0 then
        raise exception
            'INVALID_MARKET_PRICE';
    end if;


    /*
     * ==========================================================
     * FETCH FISCAL PERIOD
     * ==========================================================
     */

    v_stage :=
        'fetch fiscal period';


    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_user.country_code
    ) as fiscal_period;


    if not found
       or v_fiscal_year is null
       or v_period is null
    then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * FETCH DOCUMENT PREFIX
     * ==========================================================
     */

    v_stage :=
        'fetch document prefix';


    v_document_prefix :=
        public.fetch_transaction_doc_num_prefix(
            v_transaction_type
        );


    if v_document_prefix is null
       or btrim(
           v_document_prefix
       ) = ''
    then
        raise exception
            'DOCUMENT_PREFIX_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * GENERATE DOCUMENT NUMBER
     * ==========================================================
     */

    v_stage :=
        'generate document number';


    v_document_number :=
        public.generate_document_number(
            v_document_prefix,
            v_fiscal_year,
            v_period,
            v_user.country_code
        );


    /* Lock the whole active portfolio before posting any repayment.
     * Collateral is shared, so untouched loans also participate in the
     * required-pool calculation. All loans must use this USD portfolio. */
    v_stage := 'lock active loan portfolio';
    for v_loan in
        select l.* from public.loan as l
        where l.user_id = v_user.id
          and l.status = 'active'::public."LoanStatus"
        order by l.created_at, l.id
        for update
    loop
        if lower(btrim(v_loan.currency_code)) is distinct from v_currency
           or v_loan.country_code is distinct from v_user.country_code
        then
            raise exception 'LOAN_PORTFOLIO_CONTEXT_MISMATCH';
        end if;
        v_portfolio_ids := array_append(v_portfolio_ids, v_loan.id::text);
    end loop;

    /* Debt allocation is unchanged: oldest loan first, with interest
     * before principal within each loan. No collateral is released here. */
    v_stage :=
        'allocate loan repayment';


    for v_loan in
        select
            loan_record.*
        from public.loan
            loan_record
        where loan_record.user_id =
              v_user.id

          and loan_record.status =
              'active'::public."LoanStatus"

          and lower(
              btrim(
                  loan_record.currency_code
              )
          ) =
              v_currency

        order by
            loan_record.created_at asc,
            loan_record.id asc

        for update
    loop
        v_active_loan_found :=
            true;


        exit when
            v_remaining_payment <= 0;


        /*
         * ======================================================
         * CURRENT OUTSTANDING BALANCES
         * ======================================================
         */

        select
            greatest(
                coalesce(
                    sum(
                        coalesce(
                            loan_entry_record.debit_principal,
                            0
                        ) -
                        coalesce(
                            loan_entry_record.credit_principal,
                            0
                        )
                    ),
                    0
                ),
                0
            ),

            greatest(
                coalesce(
                    sum(
                        coalesce(
                            loan_entry_record.debit_interest,
                            0
                        ) -
                        coalesce(
                            loan_entry_record.credit_interest,
                            0
                        )
                    ),
                    0
                ),
                0
            )

        into
            v_principal_outstanding,
            v_interest_outstanding

        from public.loan_entry
            loan_entry_record

        where loan_entry_record.loan_id =
              v_loan.id;


        if v_principal_outstanding::text in ('NaN', 'Infinity', '-Infinity')
           or v_interest_outstanding::text in ('NaN', 'Infinity', '-Infinity')
        then
            raise exception 'INVALID_LOAN_BALANCE';
        end if;

        if v_principal_outstanding <= 0
           and v_interest_outstanding <= 0
        then
            continue;
        end if;


        v_interest_paid :=
            0;

        v_principal_paid :=
            0;


        /*
         * ======================================================
         * PAY INTEREST FIRST
         * ======================================================
         */

        if v_interest_outstanding > 0
           and v_remaining_payment > 0
        then
            v_interest_paid :=
                least(
                    v_interest_outstanding,
                    v_remaining_payment
                );


            v_remaining_payment :=
                v_remaining_payment -
                v_interest_paid;


            v_total_interest_paid :=
                v_total_interest_paid +
                v_interest_paid;
        end if;


        /*
         * ======================================================
         * PAY PRINCIPAL SECOND
         * ======================================================
         */

        if v_principal_outstanding > 0
           and v_remaining_payment > 0
        then
            v_principal_paid :=
                least(
                    v_principal_outstanding,
                    v_remaining_payment
                );


            v_remaining_payment :=
                v_remaining_payment -
                v_principal_paid;


            v_total_principal_paid :=
                v_total_principal_paid +
                v_principal_paid;
        end if;


        if v_interest_paid <= 0
           and v_principal_paid <= 0
        then
            continue;
        end if;


        /*
         * ======================================================
         * CREATE REPAYMENT LOAN ENTRY
         * ======================================================
         */

        v_payments := v_payments || jsonb_build_array(jsonb_build_object(
            'loan_id', v_loan.id::text,
            'payment', v_principal_paid + v_interest_paid
        ));

        v_stage :=
            'create loan repayment entry';


        insert into public.loan_entry (
            loan_id,
            fiscal_year,
            period,
            document_number,
            entry_type,
            debit_principal,
            credit_principal,
            debit_interest,
            credit_interest,
            currency_code,
            country_code
        )
        values (
            v_loan.id,
            v_fiscal_year,
            v_period,
            v_document_number,
            'repayment'::public."LoanEntryType",
            0,
            v_principal_paid,
            0,
            v_interest_paid,
            v_currency,
            v_user.country_code
        );


        /*
         * ======================================================
         * UPDATE LOAN SNAPSHOT
         * ======================================================
         */

        v_stage :=
            'update loan snapshot';


        perform public.update_loan_snapshot(
            v_loan.id,
            v_user.id,
            v_user.country_code,
            0::numeric,
            v_principal_paid,
            0::numeric,
            v_interest_paid,
            v_fiscal_year,
            v_period
        );


        /*
         * ======================================================
         * POST-REPAYMENT OUTSTANDING BALANCES
         * ======================================================
         */

        v_principal_remaining :=
            greatest(
                v_principal_outstanding -
                v_principal_paid,
                0
            );


        v_interest_remaining :=
            greatest(
                v_interest_outstanding -
                v_interest_paid,
                0
            );


        v_total_debt_remaining :=
            v_principal_remaining +
            v_interest_remaining;


        /*
         * ======================================================
         * CLOSE FULLY SETTLED LOAN
         * ======================================================
         *
         * Both principal AND interest must be zero before a loan
         * can be closed. Shared collateral is handled after allocation.
         */

        if v_principal_remaining <= 0
           and v_interest_remaining <= 0
        then
            v_stage :=
                'close loan';


            update public.loan
            set
                status =
                    'closed'::public."LoanStatus",

                updated_at =
                    now()

            where id =
                  v_loan.id

              and status =
                  'active'::public."LoanStatus";


            if not found then
                raise exception
                    'LOAN_CLOSE_FAILED';
            end if;


            v_closed_loans_count :=
                v_closed_loans_count +
                1;
        end if;

    end loop;


    /*
     * ==========================================================
     * VALIDATE REPAYMENT ALLOCATION
     * ==========================================================
     */

    if not v_active_loan_found then
        raise exception
            'NO_ACTIVE_LOANS';
    end if;


    if v_total_principal_paid <= 0
       and v_total_interest_paid <= 0
    then
        raise exception
            'NOTHING_TO_REPAY';
    end if;


    /*
     * Exact amount actually consumed by the repayment.
     */
    v_total_payment_applied :=
        v_total_principal_paid +
        v_total_interest_paid;


    /* ==========================================================
     * CALCULATE ONE POST-REPAYMENT REQUIRED POOL
     * ==========================================================
     * Read every loan that was active when this operation started,
     * including loans just closed and loans untouched by this payment.
     * Each loan uses its saved normal borrowing LTV, as top-up does.
     */
    v_stage := 'calculate post-repayment required collateral pool';
    foreach v_portfolio_id in array v_portfolio_ids
    loop
        select l.* into strict v_loan
        from public.loan as l where l.id::text = v_portfolio_id;

        select
            greatest(coalesce(sum(coalesce(e.debit_principal, 0) -
                                  coalesce(e.credit_principal, 0)), 0), 0),
            greatest(coalesce(sum(coalesce(e.debit_interest, 0) -
                                  coalesce(e.credit_interest, 0)), 0), 0)
        into v_principal_remaining, v_interest_remaining
        from public.loan_entry as e where e.loan_id = v_loan.id;

        if v_principal_remaining::text in ('NaN', 'Infinity', '-Infinity')
           or v_interest_remaining::text in ('NaN', 'Infinity', '-Infinity')
        then
            raise exception 'INVALID_LOAN_BALANCE';
        end if;
        v_total_debt_remaining := v_principal_remaining + v_interest_remaining;
        v_target_collateral := 0;
        if v_total_debt_remaining > 0 then
            v_target_ltv := v_loan.max_ltv_percent;
            if v_target_ltv is null
               or v_target_ltv::text in ('NaN', 'Infinity', '-Infinity')
               or v_target_ltv <= 0 or v_target_ltv >= 100
            then
                raise exception 'INVALID_LOAN_LTV_CONFIGURATION';
            end if;
            v_target_collateral := ceil(
                v_total_debt_remaining * 100 /
                (v_target_ltv * v_market_price) * 1000000
            ) / 1000000;
        end if;
        v_required_pool := v_required_pool + v_target_collateral;
        v_plan := v_plan || jsonb_build_array(jsonb_build_object(
            'loan_id', v_loan.id::text,
            'debt', v_total_debt_remaining,
            'required', v_target_collateral,
            'liquidation_ltv', v_loan.liquidation_ltv
        ));
    end loop;

    -- A shortfall means no release; repayment does not create collateral.
    v_total_collateral_unlock := trunc(
        greatest(v_previous_locked - v_required_pool, 0), 6
    );
    v_retained_pool := v_previous_locked - v_total_collateral_unlock;

    if v_retained_pool < least(v_previous_locked, v_required_pool)
       or v_total_collateral_unlock < 0
       or v_total_collateral_unlock > v_previous_locked
    then
        raise exception 'INVALID_COLLATERAL_POOL_RELEASE';
    end if;

    /* Current allocations are maintained separately from audit movements,
     * matching top-up's oldest-first redistribution of the actual pool.
     * Reallocation is not newly locked/released GOLD, so it creates no
     * collateral_entry movement. All allocations sum to the retained pool.
     */
    v_stage := 'redistribute retained collateral pool';
    v_remaining_pool := v_retained_pool;
    for v_plan_row in select value from jsonb_array_elements(v_plan)
    loop
        v_allocation := least(
            (v_plan_row ->> 'required')::numeric, v_remaining_pool
        );
        v_liquidation_price := 0;
        if (v_plan_row ->> 'debt')::numeric > 0 and v_allocation > 0 then
            v_target_ltv := (v_plan_row ->> 'liquidation_ltv')::numeric;
            if v_target_ltv is null
               or v_target_ltv::text in ('NaN', 'Infinity', '-Infinity')
               or v_target_ltv <= 0 or v_target_ltv > 100
            then
                raise exception 'INVALID_LIQUIDATION_LTV';
            end if;
            v_liquidation_price := trunc(
                (v_plan_row ->> 'debt')::numeric /
                (v_allocation * v_target_ltv / 100), 6
            );
        end if;
        update public.loan
        set collateral = v_allocation,
            liquidation_price = v_liquidation_price,
            updated_at = now()
        where id::text = v_plan_row ->> 'loan_id';
        if not found then
            raise exception 'LOAN_COLLATERAL_UPDATE_FAILED';
        end if;
        v_remaining_pool := v_remaining_pool - v_allocation;
    end loop;
    if v_remaining_pool <> 0 then
        raise exception 'COLLATERAL_POOL_ALLOCATION_MISMATCH';
    end if;

    /* Audit attribution: distribute the ONE actual pool release across
     * loans repaid by this document, in proportion to the payment applied.
     * These rows record actual release, not the new per-loan allocations.
     * The final row receives any six-decimal rounding remainder.
     */
    v_stage := 'post pooled collateral release entries';
    v_release_remaining := v_total_collateral_unlock;
    v_payment_remaining := v_total_payment_applied;
    for v_payment_row in select value from jsonb_array_elements(v_payments)
    loop
        if (v_payment_row ->> 'payment')::numeric = v_payment_remaining then
            v_release_part := v_release_remaining;
        else
            v_release_part := least(v_release_remaining, trunc(
                v_total_collateral_unlock *
                (v_payment_row ->> 'payment')::numeric /
                v_total_payment_applied, 6
            ));
        end if;
        if v_release_part > 0 then
            insert into public.collateral_entry (
                loan_id, document_number, debit, credit, country_code
            ) values (
                v_payment_row ->> 'loan_id', v_document_number,
                0, v_release_part, v_user.country_code
            );
        end if;
        v_release_sum := v_release_sum + v_release_part;
        v_release_remaining := v_release_remaining - v_release_part;
        v_payment_remaining := v_payment_remaining -
            (v_payment_row ->> 'payment')::numeric;
    end loop;
    if v_release_sum <> v_total_collateral_unlock
       or v_release_remaining <> 0 or v_payment_remaining <> 0
    then
        raise exception 'COLLATERAL_RELEASE_POSTING_MISMATCH';
    end if;

    /*
     * ==========================================================
     * RELEASE CUSTOMER COLLATERAL
     * ==========================================================
     */

    if v_total_collateral_unlock > 0 then
        v_stage :=
            'release collateral';


        update public.collateral
        set
            locked_tokens =
                locked_tokens -
                v_total_collateral_unlock,
            updated_at = now()

        where id = v_collateral.id
          and user_id = v_user.id
          and coalesce(
              locked_tokens,
              0
          ) >=
              v_total_collateral_unlock;


        if not found then
            raise exception
                'COLLATERAL_BALANCE_TOO_LOW';
        end if;


        /*
         * ======================================================
         * UPDATE COLLATERAL SNAPSHOT
         * ======================================================
         */

        v_stage :=
            'update collateral snapshot';


        perform public.update_collateral_snapshot(
            v_user.id,
            v_user.country_code,
            0::numeric,
            v_total_collateral_unlock,
            v_fiscal_year,
            v_period
        );
    end if;


    /*
     * ==========================================================
     * FETCH GL MAPPINGS
     * ==========================================================
     */

    v_stage :=
        'fetch GL mappings';


    select
        array_agg(
            mapping_record
        )
    into
        v_mappings
    from public.fetch_gl_mappings(
        v_transaction_type
    ) as mapping_record;


    if v_mappings is null
       or cardinality(
           v_mappings
       ) = 0
    then
        raise exception
            'GL_MAPPINGS_NOT_FOUND';
    end if;


    /*
     * ==========================================================
     * BUILD POSTING COMPONENTS
     * ==========================================================
     *
     * Total debit is the exact repayment consumed.
     *
     * Credits are split between:
     *
     * principal
     * interest
     */

    v_components :=
        array[
            row(
                'principal'::public."ComponentType",
                v_total_payment_applied,
                v_total_principal_paid
            )::public.posting_component
        ];


    if v_total_interest_paid > 0 then
        v_components :=
            array_append(
                v_components,
                row(
                    'loan_interest'::public."ComponentType",
                    0,
                    v_total_interest_paid
                )::public.posting_component
            );
    end if;


    /*
     * ==========================================================
     * CREATE FINANCIAL TRANSACTION
     * ==========================================================
     */

    v_stage :=
        'create financial transaction';


    insert into public.financial_transaction (
        document_number,
        fiscal_year,
        period,
        reference,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        country_code
    )
    values (
        v_document_number,
        v_fiscal_year,
        v_period,
        v_reference,
        v_transaction_type,
        'Loan repayment for user ' ||
            v_user.id,
        v_user.id,
        v_total_payment_applied,
        v_currency,
        v_user.country_code
    )
    returning
        id
    into
        v_financial_transaction_id;


    /*
     * ==========================================================
     * POST FINANCIAL ENTRIES
     * ==========================================================
     */

    v_stage :=
        'post financial entries';


    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_document_number,

        p_country_code =>
            v_user.country_code,

        p_transaction_id =>
            v_financial_transaction_id,

        p_transaction_type =>
            v_transaction_type,

        p_created_by =>
            v_user.id,

        p_components =>
            v_components,

        p_mappings =>
            v_mappings,

        p_currency_code =>
            v_currency,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_reference =>
            v_reference,

        p_deposit_type =>
            null
    );


    /*
     * ==========================================================
     * MOVE CUSTOMER FUNDS TO TREASURY
     * ==========================================================
     *
     * Customer wallet debit =
     *
     *     v_total_payment_applied
     *
     * NOT:
     *
     *     v_payment_amount
     *
     * Therefore unused_payment never leaves the customer's
     * wallet.
     */

    v_stage :=
        'post wallet entries';


    perform *
    from public.post_wallet_entries(
        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        p_document_number =>
            v_document_number,

        p_reference =>
            v_reference,

        p_receiver_id =>
            v_treasury.id,

        p_sender_id =>
            v_user.id,

        p_transaction_type =>
            v_transaction_type,

        p_credit_amount =>
            v_total_payment_applied,

        p_debit_amount =>
            v_total_payment_applied,

        p_sender_wallet_owner =>
            'customer'::public."WalletOwnerType",

        p_receiver_wallet_owner =>
            'treasury'::public."WalletOwnerType",

        p_currency_code =>
            v_currency,

        p_country_code =>
            v_user.country_code,

        p_audit_action_type =>
            'loan_repaid'::public."AuditActionType",

        p_treasury_id =>
            null,

        p_fee_amount =>
            0,

        p_ip_address =>
            p_ip_address,

        p_receiver_notification =>
            null,

        p_sender_notification =>
            null
    );


    /*
     * ==========================================================
     * RETURN COMMITTED RESULT
     * ==========================================================
     */

    return query
    select
        true,

        v_document_number,

        to_char(
            round(
                v_total_principal_paid,
                2
            ),
            'FM999999999999999999999999990.00'
        ),

        to_char(
            round(
                v_total_interest_paid,
                2
            ),
            'FM999999999999999999999999990.00'
        ),

        to_char(
            round(
                v_total_collateral_unlock,
                6
            ),
            'FM999999999999999999999999990.000000'
        ),

        to_char(
            round(
                v_remaining_payment,
                2
            ),
            'FM999999999999999999999999990.00'
        ),

        v_closed_loans_count,

        v_user.id,

        lower(
            btrim(
                v_user.country_code
            )
        ),

        v_currency,

        /*
         * Total amount actually applied against debt.
         */
        to_char(
            round(
                v_total_payment_applied,
                2
            ),
            'FM999999999999999999999999990.00'
        ),

        /*
         * Exact customer wallet debit.
         */
        to_char(
            round(
                v_total_payment_applied,
                2
            ),
            'FM999999999999999999999999990.00'
        );


exception
    when others then
        get stacked diagnostics
            v_error_state =
                returned_sqlstate,

            v_error_message =
                message_text,

            v_error_detail =
                pg_exception_detail,

            v_error_hint =
                pg_exception_hint,

            v_error_context =
                pg_exception_context;


        raise exception using
            errcode =
                v_error_state,

            message =
                format(
                    'LOAN_REPAYMENT_FAILED at [%s]: %s',
                    v_stage,
                    v_error_message
                ),

            detail =
                coalesce(
                    nullif(
                        concat_ws(
                            E'\n',

                            nullif(
                                v_error_detail,
                                ''
                            ),

                            nullif(
                                v_error_context,
                                ''
                            )
                        ),
                        ''
                    ),
                    'No additional PostgreSQL context'
                ),

            hint =
                coalesce(
                    nullif(
                        v_error_hint,
                        ''
                    ),
                    'Check the Loan Repayment stage reported in the error'
                );

end;
$$;
ALTER FUNCTION "public"."execute_my_loan_repayment"("p_amount" "text", "p_reference" "text", "p_currency_code" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."execute_my_treasury_funding"("p_transaction_type" "public"."TransactionType", "p_currency_code" "text" DEFAULT NULL::"text", "p_amount" numeric DEFAULT NULL::numeric, "p_document_number" "text" DEFAULT NULL::"text", "p_ip_address" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_executor public.users%rowtype;
    v_treasury public.users%rowtype;

    v_original_transaction
        public.financial_transaction%rowtype;

    v_is_reversal boolean;

    v_currency_code text;
    v_amount numeric;

    v_fiscal_year integer;
    v_period integer;

    v_mappings
        public.transaction_gl_mapping[];

    v_components
        public.posting_component[];

    v_document_prefix text;
    v_document_number text;

    v_transaction_id
        public.financial_transaction.id%type;

    v_treasury_wallet
        public.wallet%rowtype;

    v_balance_before numeric;
    v_balance_after numeric;

    v_credit_amount numeric := 0;
    v_debit_amount numeric := 0;

    v_description text;

    v_audit_action
        public."AuditActionType";

    v_stage text := 'initialization';

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * =========================================================
     * AUTHENTICATION AND AUTHORIZATION
     * =========================================================
     */

    v_stage := 'authorize treasury user';

    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if not public.has_role(
        array[
            'treasury'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * =========================================================
     * TRANSACTION TYPE
     * =========================================================
     */

    v_stage := 'validate transaction type';

    if p_transaction_type not in (
        'treasury_funding'::public."TransactionType",
        'treasury_funding_reversal'::public."TransactionType"
    ) then
        raise exception
            'INVALID_TREASURY_FUNDING_TRANSACTION_TYPE';
    end if;

    v_is_reversal :=
        p_transaction_type =
        'treasury_funding_reversal'::public."TransactionType";

    /*
     * =========================================================
     * AUTHENTICATED USER
     * =========================================================
     */

    v_stage := 'fetch authenticated user';

    v_executor :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_executor.id is null then
        raise exception
            'TREASURY_USER_NOT_FOUND';
    end if;

    if v_executor.country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * The old service received countryCode from its caller.
     *
     * In the RPC architecture we derive it from the authenticated
     * treasury user so the client cannot fund another country's
     * treasury.
     */

    /*
     * =========================================================
     * COUNTRY TREASURY
     * =========================================================
     */

    v_stage := 'fetch country treasury';

    v_treasury :=
        public.fetch_country_treasury(
            v_executor.country_code
        );

    if v_treasury.id is null then
        raise exception
            'TREASURY_NOT_FOUND';
    end if;

    /*
     * =========================================================
     * NORMAL TREASURY FUNDING
     * =========================================================
     */

    if not v_is_reversal then
        v_stage := 'validate funding input';

        v_currency_code :=
            lower(
                nullif(
                    btrim(p_currency_code),
                    ''
                )
            );

        if v_currency_code is null then
            raise exception
                'CURRENCY_REQUIRED';
        end if;

        v_amount :=
            public.round_down(
                p_amount
            );

        if v_amount is null
           or v_amount <= 0
        then
            raise exception
                'INVALID_AMOUNT';
        end if;

        v_description :=
            'Funding treasury';

        v_audit_action :=
            'treasury_funded'::public."AuditActionType";
    end if;

    /*
     * =========================================================
     * TREASURY FUNDING REVERSAL
     * =========================================================
     *
     * The original service received:
     *
     *     currency_code
     *     amount
     *     document_number
     *
     * and used document_number as the financial transaction
     * reference.
     *
     * In the RPC version we make reversal safer by resolving the
     * amount and currency from the original treasury-funding
     * document instead of trusting client-supplied values.
     */

    if v_is_reversal then
        v_stage := 'validate reversal document';

        if nullif(
            btrim(p_document_number),
            ''
        ) is null
        then
            raise exception
                'DOCUMENT_NUMBER_REQUIRED_FOR_REVERSAL';
        end if;

        /*
         * Lock the original treasury funding transaction.
         */
        v_stage := 'fetch original treasury funding';

        select
            transaction_record.*
        into
            v_original_transaction
        from public.financial_transaction
            transaction_record
        where transaction_record.document_number =
              btrim(p_document_number)

          and transaction_record.country_code =
              v_executor.country_code

        for update;

        if not found then
            raise exception
                'DOCUMENT_NOT_FOUND';
        end if;

        if v_original_transaction.transaction_type <>
           'treasury_funding'::public."TransactionType"
        then
            raise exception
                'DOCUMENT_IS_NOT_TREASURY_FUNDING';
        end if;

        /*
         * Prevent the same treasury funding from being
         * reversed more than once.
         */
        v_stage := 'check duplicate reversal';

        perform 1
        from public.financial_transaction
            reversal_record
        where reversal_record.country_code =
              v_executor.country_code

          and reversal_record.transaction_type =
              'treasury_funding_reversal'::public."TransactionType"

          and reversal_record.reversal_of =
              v_original_transaction.document_number
        limit 1;

        if found then
            raise exception
                'DOCUMENT_ALREADY_REVERSED';
        end if;

        v_currency_code :=
            lower(
                v_original_transaction.currency_code
            );

        v_amount :=
            v_original_transaction.gross_amount;

        if v_amount is null
           or v_amount <= 0
        then
            raise exception
                'INVALID_ORIGINAL_AMOUNT';
        end if;

        v_description :=
            'Treasury funding reversal';

        v_audit_action :=
            'treasury_fund_reversed'::public."AuditActionType";
    end if;

    /*
     * =========================================================
     * GL MAPPINGS
     * =========================================================
     *
     * Equivalent to:
     *
     *     fetchGlMappings(transactionType)
     */

    v_stage := 'fetch gl mappings';

    select
        array_agg(mapping_record)
    into
        v_mappings
    from public.fetch_gl_mappings(
        p_transaction_type
    ) as mapping_record;

    if v_mappings is null
       or cardinality(v_mappings) = 0
    then
        raise exception
            'TREASURY_FUNDING_GL_MAPPINGS_NOT_FOUND';
    end if;

    /*
     * =========================================================
     * POSTING COMPONENTS
     * =========================================================
     *
     * Equivalent to:
     *
     *     buildPostingComponents({
     *         transactionType,
     *         principal: amount,
     *         mappings,
     *         countryCode,
     *         currencyCode
     *     })
     */

    v_stage := 'build posting components';

    v_components :=
        public.build_posting_components(
            p_transaction_type,
            v_amount,
            v_mappings,
            v_executor.country_code,
            v_currency_code,
            false
        );

    /*
     * =========================================================
     * FISCAL PERIOD
     * =========================================================
     */

    v_stage := 'fetch fiscal period';

    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_executor.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * =========================================================
     * DOCUMENT PREFIX
     * =========================================================
     *
     * Old code:
     *
     * treasury_funding
     *     -> TREASURY-FUND
     *
     * treasury_funding_reversal
     *     -> REV-TREASURY-FUND
     *
     * We preserve those exact prefixes.
     */

    v_document_prefix :=
        case
            when v_is_reversal then
                'REV-TREASURY-FUND'
            else
                'TREASURY-FUND'
        end;

    /*
     * =========================================================
     * DOCUMENT NUMBER
     * =========================================================
     */

    v_stage := 'generate document number';

    v_document_number :=
        public.generate_document_number(
            v_document_prefix,
            v_fiscal_year,
            v_period,
            v_executor.country_code
        );

    /*
     * =========================================================
     * TREASURY WALLET
     * =========================================================
     *
     * This deliberately mirrors the original Prisma upsert.
     *
     * Funding:
     *     balance = balance + amount
     *
     * Reversal:
     *     balance = balance - amount
     *
     * There is only ONE treasury wallet involved.
     */

    v_stage := 'lock treasury wallet';

    select
        wallet_record.*
    into
        v_treasury_wallet
    from public.wallet wallet_record
    where wallet_record.country_code =
          v_executor.country_code

      and wallet_record.user_id =
          v_treasury.id

      and wallet_record.currency_code =
          v_currency_code

      and wallet_record.owner_type =
          'treasury'::public."WalletOwnerType"

    for update;

    if found then
        v_balance_before :=
            coalesce(
                v_treasury_wallet.balance,
                0
            );

        if v_is_reversal then
            v_balance_after :=
                v_balance_before -
                v_amount;
        else
            v_balance_after :=
                v_balance_before +
                v_amount;
        end if;

        /*
         * Do not allow a reversal to make the treasury
         * wallet negative.
         */
        if v_balance_after < 0 then
            raise exception
                'INSUFFICIENT_TREASURY_BALANCE';
        end if;

        update public.wallet
        set balance =
                v_balance_after
        where id =
              v_treasury_wallet.id

        returning *
        into v_treasury_wallet;
    else
        /*
         * This mirrors the old Prisma upsert create path.
         *
         * A normal funding may create the treasury wallet.
         *
         * A reversal cannot create a missing wallet because
         * there would be nothing to reverse from.
         */
        if v_is_reversal then
            raise exception
                'TREASURY_WALLET_NOT_FOUND';
        end if;

        v_balance_before := 0;
        v_balance_after := v_amount;

        insert into public.wallet (
            user_id,
            currency_code,
            country_code,
            owner_type,
            balance,
            is_active
        )
        values (
            v_treasury.id,
            v_currency_code,
            v_executor.country_code,
            'treasury'::public."WalletOwnerType",
            v_amount,
            true
        )
        returning *
        into v_treasury_wallet;
    end if;

    /*
     * =========================================================
     * FINANCIAL TRANSACTION
     * =========================================================
     *
     * Original:
     *
     * reference: document_number ?? documentNo
     *
     * Normal funding therefore references itself.
     *
     * Reversal references the supplied/original document.
     */

    v_stage := 'create financial transaction';

    insert into public.financial_transaction (
        document_number,
        reference,
        fiscal_year,
        period,
        transaction_type,
        description,
        created_by,
        gross_amount,
        currency_code,
        country_code,
        reversal_of,
        reversed_by
    )
    values (
        v_document_number,

        case
            when v_is_reversal then
                v_original_transaction.document_number
            else
                v_document_number
        end,

        v_fiscal_year,
        v_period,
        p_transaction_type,
        v_description,
        v_executor.id,
        v_amount,
        v_currency_code,
        v_executor.country_code,

        case
            when v_is_reversal then
                v_original_transaction.document_number
            else
                null
        end,

        case
            when v_is_reversal then
                v_executor.id
            else
                null
        end
    )
    returning id
    into v_transaction_id;

    /*
     * =========================================================
     * FINANCIAL ENTRIES
     * =========================================================
     */

    v_stage := 'post financial entries';

    perform *
    from public.post_financial_entries(
        p_document_number =>
            v_document_number,

        p_country_code =>
            v_executor.country_code,

        p_transaction_id =>
            v_transaction_id,

        p_transaction_type =>
            p_transaction_type,

        p_created_by =>
            v_executor.id,

        p_components =>
            v_components,

        p_mappings =>
            v_mappings,

        p_currency_code =>
            v_currency_code,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period,

        /*
         * The old service passed document_number here.
         *
         * Normal funding had no document_number.
         * Reversal supplied the original document number.
         */
        p_reference =>
            case
                when v_is_reversal then
                    v_original_transaction.document_number
                else
                    null
            end,

        p_deposit_type =>
            null
    );

    /*
     * =========================================================
     * WALLET ENTRY
     * =========================================================
     *
     * Exact old behaviour:
     *
     * treasury_funding:
     *     debit  = 0
     *     credit = amount
     *
     * treasury_funding_reversal:
     *     debit  = amount
     *     credit = 0
     */

    if v_is_reversal then
        v_debit_amount :=
            v_amount;

        v_credit_amount :=
            0;
    else
        v_debit_amount :=
            0;

        v_credit_amount :=
            v_amount;
    end if;

    v_stage := 'create treasury wallet entry';

    insert into public.wallet_entry (
        document_number,
        fiscal_year,
        period,
        transaction_type,
        wallet_id,
        currency_code,
        country_code,
        debit,
        credit,
        created_by
    )
    values (
        v_document_number,
        v_fiscal_year,
        v_period,
        p_transaction_type,
        v_treasury_wallet.id,
        v_currency_code,
        v_executor.country_code,
        v_debit_amount,
        v_credit_amount,
        v_executor.id
    );

    /*
     * =========================================================
     * WALLET BALANCE SNAPSHOT
     * =========================================================
     *
     * Equivalent to the original:
     *
     * updateWalletBalanceSnapshot({
     *     sender_id,
     *     transactionType,
     *     receiver_id: treasury.id,
     *     currency_code,
     *     country_code,
     *     receiver_wallet_owner: treasury,
     *     sender_wallet_owner: treasury,
     *     receiver_amount: amount,
     *     sender_amount: amount,
     *     fiscal_year,
     *     period
     * })
     */

    v_stage := 'update treasury wallet balance snapshot';

    perform *
    from public.update_wallet_balance_snapshot(
        p_sender_id =>
            v_executor.id,

        p_transaction_type =>
            p_transaction_type,

        p_receiver_id =>
            v_treasury.id,

        p_currency_code =>
            v_currency_code,

        p_country_code =>
            v_executor.country_code,

        p_receiver_wallet_owner =>
            'treasury'::public."WalletOwnerType",

        p_sender_wallet_owner =>
            'treasury'::public."WalletOwnerType",

        p_receiver_amount =>
            v_amount,

        p_sender_amount =>
            v_amount,

        p_fiscal_year =>
            v_fiscal_year,

        p_period =>
            v_period
    );

    /*
     * =========================================================
     * AUDIT LOG
     * =========================================================
     */

    v_stage := 'create treasury audit log';

    insert into public.audit_log (
        fiscal_year,
        period,
        user_id,
        country_code,
        action_type,
        entity_type,
        entity_id,
        old_value,
        new_value,
        metadata,
        document_number
    )
    values (
        v_fiscal_year,
        v_period,
        v_executor.id,
        v_executor.country_code,
        v_audit_action,
        'treasury',
        v_treasury.id,

        jsonb_build_object(
            'treasury_balance_before',
            v_balance_before
        ),

        jsonb_build_object(
            'treasury_balance_after',
            v_balance_after
        ),

        jsonb_build_object(
            'document_number',
            v_document_number,

            'reference',
            case
                when v_is_reversal then
                    v_original_transaction.document_number
                else
                    null
            end,

            'ip_address',
            p_ip_address
        ),

        v_document_number
    );

    /*
     * =========================================================
     * RESPONSE
     * =========================================================
     */

    return jsonb_build_object(
        'success',
        true,

        'transaction_type',
        p_transaction_type,

        'document_number',
        v_document_number,

        'reference',
        case
            when v_is_reversal then
                v_original_transaction.document_number
            else
                v_document_number
        end,

        'reversal_of',
        case
            when v_is_reversal then
                v_original_transaction.document_number
            else
                null
        end,

        'currency_code',
        v_currency_code,

        'amount',
        v_amount::text,

        'treasury_id',
        v_treasury.id,

        'balance_before',
        v_balance_before::text,

        'balance_after',
        v_balance_after::text
    );

exception
    when others then
        get stacked diagnostics
            v_error_state = returned_sqlstate,
            v_error_message = message_text,
            v_error_detail = pg_exception_detail,
            v_error_hint = pg_exception_hint,
            v_error_context = pg_exception_context;

        raise exception using
            errcode = v_error_state,

            message = format(
                'TREASURY_FUNDING_FAILED at [%s]: %s',
                v_stage,
                v_error_message
            ),

            detail = concat_ws(
                E'\n',
                nullif(v_error_detail, ''),
                nullif(v_error_context, '')
            ),

            hint = coalesce(
                nullif(v_error_hint, ''),
                'Check the Treasury Funding stage reported in the error'
            );
end;
$$;
ALTER FUNCTION "public"."execute_my_treasury_funding"("p_transaction_type" "public"."TransactionType", "p_currency_code" "text", "p_amount" numeric, "p_document_number" "text", "p_ip_address" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."extract_component_totals"("p_components" "public"."posting_component"[], "p_reverse" boolean DEFAULT false) RETURNS "public"."component_totals"
    LANGUAGE "plpgsql" IMMUTABLE PARALLEL SAFE
    AS $$
declare
    v_component public.posting_component;
    v_principal_amount numeric := 0;
    v_others_amount numeric := 0;
    v_principal_found boolean := false;
begin
    if p_components is null then
        return row(0, 0)::public.component_totals;
    end if;

    foreach v_component in array p_components
    loop
        if v_component is null then
            continue;
        end if;

        if v_component.component_type =
           'principal'::public."ComponentType"
        then
            if not v_principal_found then
                v_principal_amount :=
                    case
                        when coalesce(p_reverse, false)
                            then coalesce(v_component.credit_amount, 0)
                        else coalesce(v_component.debit_amount, 0)
                    end;

                v_principal_found := true;
            end if;
        else
            v_others_amount :=
                v_others_amount +
                case
                    when coalesce(p_reverse, false)
                        then coalesce(v_component.debit_amount, 0)
                    else coalesce(v_component.credit_amount, 0)
                end;
        end if;
    end loop;

    return row(
        v_principal_amount,
        v_others_amount
    )::public.component_totals;
end;
$$;
ALTER FUNCTION "public"."extract_component_totals"("p_components" "public"."posting_component"[], "p_reverse" boolean) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fail_liquidation_accounting_job"("p_job_id" "text", "p_error_message" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_job public.liquidation_job%rowtype;
    v_job_id text;
    v_error_message text;
    v_stage text := 'initialization';
    v_error_state text;
    v_database_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    v_stage := 'authorize service role';

    if coalesce(auth.role(), '') <> 'service_role' then
        raise exception using
            errcode = '42501',
            message = 'SERVICE_ROLE_REQUIRED';
    end if;

    v_stage := 'validate input';
    v_job_id := nullif(btrim(p_job_id), '');

    if v_job_id is null then
        raise exception 'LIQUIDATION_JOB_ID_REQUIRED';
    end if;

    v_error_message := coalesce(
        nullif(btrim(p_error_message), ''),
        'LIQUIDATION_ACCOUNTING_FAILED'
    );

    v_stage := 'lock liquidation job';

    select job_record.*
    into v_job
    from public.liquidation_job job_record
    where job_record.id::text = v_job_id
    for update;

    if not found then
        raise exception 'LIQUIDATION_JOB_NOT_FOUND';
    end if;

    if v_job.status::text = 'completed' then
        return jsonb_build_object(
            'success', true,
            'already_completed', true,
            'job_id', v_job.id,
            'status', v_job.status,
            'error_message', null,
            'retryable', false,
            'blockchain_transfer_required', false
        );
    end if;

    if v_job.status::text not in (
        'accounting_processing',
        'accounting_failed'
    ) then
        raise exception
            'INVALID_LIQUIDATION_JOB_STATUS_FOR_ACCOUNTING_FAILURE_%',
            upper(v_job.status::text);
    end if;

    v_stage := 'validate confirmed blockchain transfer';

    perform 1
    from public.liquidation_blockchain_queue queue_record
    where queue_record.liquidation_job_id = v_job.id::text
      and queue_record.status::text = 'confirmed'
      and nullif(btrim(queue_record.tx_hash), '') is not null
    limit 1;

    if not found then
        raise exception 'LIQUIDATION_BLOCKCHAIN_NOT_CONFIRMED';
    end if;

    v_stage := 'mark accounting failed';

    update public.liquidation_job
    set
        status =
            'accounting_failed'::public."LiquidationJobStatus",
        accounting_started_at = null,
        error_message = v_error_message
    where id = v_job.id
    returning * into v_job;

    return jsonb_build_object(
        'success', true,
        'already_completed', false,
        'job_id', v_job.id,
        'status', v_job.status,
        'error_message', v_job.error_message,
        'retryable', true,
        'blockchain_transfer_required', false
    );
exception
    when others then
        get stacked diagnostics
            v_error_state = returned_sqlstate,
            v_database_error_message = message_text,
            v_error_detail = pg_exception_detail,
            v_error_hint = pg_exception_hint,
            v_error_context = pg_exception_context;

        raise exception using
            errcode = v_error_state,
            message = format(
                'LIQUIDATION_ACCOUNTING_FAILURE_UPDATE_FAILED at [%s]: %s',
                v_stage,
                v_database_error_message
            ),
            detail = concat_ws(
                E'\n',
                nullif(v_error_detail, ''),
                nullif(v_error_context, '')
            ),
            hint = coalesce(
                nullif(v_error_hint, ''),
                'Check the liquidation accounting failure stage'
            );
end;
$$;
ALTER FUNCTION "public"."fail_liquidation_accounting_job"("p_job_id" "text", "p_error_message" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fail_liquidation_blockchain_transfer"("p_queue_id" "text", "p_error_message" "text", "p_tx_hash" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
    v_queue public.liquidation_blockchain_queue%rowtype;

    v_queue_id text;
    v_error_message text;
    v_supplied_tx_hash text;
    v_tx_hash text;

    v_retryable boolean;
    v_manual_review boolean;
BEGIN
    IF coalesce(auth.role(), '') <> 'service_role' THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'SERVICE_ROLE_REQUIRED';
    END IF;

    v_queue_id := nullif(btrim(p_queue_id), '');

    v_error_message :=
        coalesce(
            nullif(btrim(p_error_message), ''),
            'LIQUIDATION_BLOCKCHAIN_PROCESSING_FAILED'
        );

    v_supplied_tx_hash :=
        nullif(btrim(p_tx_hash), '');

    IF v_queue_id IS NULL THEN
        RAISE EXCEPTION 'LIQUIDATION_QUEUE_ID_REQUIRED';
    END IF;

    IF v_supplied_tx_hash IS NOT NULL
       AND v_supplied_tx_hash !~ '^0x[0-9A-Fa-f]{64}$'
    THEN
        RAISE EXCEPTION 'INVALID_BLOCKCHAIN_TRANSACTION_HASH';
    END IF;

    SELECT q.*
    INTO v_queue
    FROM public.liquidation_blockchain_queue AS q
    WHERE q.id = v_queue_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'LIQUIDATION_BLOCKCHAIN_QUEUE_NOT_FOUND';
    END IF;

    IF v_queue.tx_hash IS NOT NULL
       AND v_supplied_tx_hash IS NOT NULL
       AND lower(btrim(v_queue.tx_hash))
           IS DISTINCT FROM lower(v_supplied_tx_hash)
    THEN
        RAISE EXCEPTION
            'LIQUIDATION_BLOCKCHAIN_TX_HASH_MISMATCH';
    END IF;

    /*
     * A late failure must not undo confirmation.
     */
    IF v_queue.status::text = 'confirmed' THEN
        RETURN jsonb_build_object(
            'success', true,
            'queue_id', v_queue.id,
            'tx_hash', v_queue.tx_hash,
            'error_message', NULL,
            'retryable', false,
            'manual_review_required',
                v_queue.manual_review_required
        );
    END IF;

    v_tx_hash :=
        coalesce(v_queue.tx_hash, v_supplied_tx_hash);

    -- Escalate immediately when the fifth attempt fails, not only when
    -- the next cron run notices an exhausted row.
    IF v_queue.attempt_count >= 5 THEN
        IF v_error_message NOT LIKE 'LIQUIDATION_BLOCKCHAIN_MAX_ATTEMPTS_REACHED%' THEN
            v_error_message := 'LIQUIDATION_BLOCKCHAIN_MAX_ATTEMPTS_REACHED: ' ||
                               v_error_message;
        END IF;
    END IF;

    IF v_tx_hash IS NOT NULL THEN
        /*
         * Resume the known transaction.
         * Preserve any existing manual-review restriction.
         */
        v_manual_review := v_queue.manual_review_required
                           OR v_queue.attempt_count >= 5;
        v_retryable := NOT v_manual_review;

        UPDATE public.liquidation_blockchain_queue
        SET
            status =
                CASE WHEN v_manual_review
                    THEN 'failed'::public."BlockchainLiquidationStatus"
                    ELSE 'processing'::public."BlockchainLiquidationStatus"
                END,
            manual_review_required = v_manual_review,
            tx_hash = v_tx_hash,
            submitted_at = coalesce(submitted_at, now()),
            error_message = v_error_message,
            retry_count = retry_count + 1,
            lease_expires_at = CASE WHEN v_manual_review THEN NULL ELSE now() END,
            updated_at = now()
        WHERE id = v_queue.id;

        UPDATE public.liquidation_job
        SET
            status =
                CASE WHEN v_manual_review
                    THEN 'failed'::public."LiquidationJobStatus"
                    ELSE 'blockchain_processing'::public."LiquidationJobStatus"
                END,
            error_message = v_error_message
        WHERE id::text = v_queue.liquidation_job_id
          AND status::text IN (
              'pending',
              'failed',
              'blockchain_processing'
          );

    ELSE
        /* Never reopen an uncertain submission automatically.
         * A signed no-hash failure is conservatively escalated too. */
        v_manual_review := v_queue.manual_review_required
                           OR v_queue.attempt_count >= 5
                           OR v_queue.submission_started_at IS NOT NULL
                           OR v_queue.signed_payload IS NOT NULL;

        v_retryable := NOT v_manual_review;

        UPDATE public.liquidation_blockchain_queue
        SET
            status =
                'failed'::public."BlockchainLiquidationStatus",
            error_message = v_error_message,
            retry_count = retry_count + 1,
            manual_review_required = v_manual_review,
            claimed_at = NULL,
            lease_expires_at = NULL,
            updated_at = now()
        WHERE id = v_queue.id;

        UPDATE public.liquidation_job
        SET
            status =
                'failed'::public."LiquidationJobStatus",
            error_message = v_error_message
        WHERE id::text = v_queue.liquidation_job_id
          AND status::text IN (
              'pending',
              'failed',
              'blockchain_processing'
          );
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'queue_id', v_queue.id,
        'tx_hash', v_tx_hash,
        'error_message', v_error_message,
        'retryable', v_retryable,
        'manual_review_required', v_manual_review
    );
END;
$_$;
ALTER FUNCTION "public"."fail_liquidation_blockchain_transfer"("p_queue_id" "text", "p_error_message" "text", "p_tx_hash" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_active_operational_countries"() RETURNS TABLE("country_code" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
    if coalesce(auth.role(), '') <> 'service_role' then
        raise exception using
            errcode = '42501',
            message = 'SERVICE_ROLE_REQUIRED';
    end if;

    return query
    select lower(btrim(country_record.country_code))
    from public.operational_country country_record
    where country_record.is_active = true
      and nullif(btrim(country_record.country_code), '') is not null
    order by lower(btrim(country_record.country_code));
end;
$$;
ALTER FUNCTION "public"."fetch_active_operational_countries"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_active_supported_blockchain"("p_blockchain_code" "text") RETURNS TABLE("code" "text", "chain_id" bigint, "rpc_url" "text", "contract_address" "text", "native_currency_code" "text", "explorer_url" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_blockchain_code text;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;

    IF NOT public.has_role(
        ARRAY[
            'treasury',
            'customer',
            'agent',
            'vendor'
        ]::text[]
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'FORBIDDEN';
    END IF;

    v_blockchain_code :=
        lower(nullif(btrim(p_blockchain_code), ''));

    IF v_blockchain_code IS NULL THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_CODE_REQUIRED';
    END IF;

    RETURN QUERY
    SELECT
        b.code,
        n.chain_id,
        n.rpc_url,
        b.contract_address,
        b.native_currency_code,
        n.explorer_url
    FROM public.supported_blockchain AS b
    JOIN LATERAL (
        SELECT
            network.chain_id,
            network.rpc_url,
            network.explorer_url
        FROM public.supported_blockchain_network AS network
        WHERE network.blockchain_id = b.id
          AND network.is_active = true
        ORDER BY
            network.is_default DESC,
            network.created_at DESC,
            network.id
        LIMIT 1
    ) AS n ON true
    WHERE b.code = v_blockchain_code
      AND b.is_active = true
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_NOT_FOUND_OR_INACTIVE';
    END IF;
END;
$$;
ALTER FUNCTION "public"."fetch_active_supported_blockchain"("p_blockchain_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_active_supported_blockchains"() RETURNS TABLE("code" "text", "chain_id" bigint, "rpc_url" "text", "contract_address" "text", "native_currency_code" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
    /*
     * ==========================================================
     * AUTHENTICATION
     * ==========================================================
     */
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;

    /*
     * ==========================================================
     * ROLE AUTHORIZATION
     * ==========================================================
     *
     * Supported roles:
     * - Treasury
     * - Customer
     */
    IF NOT public.has_role(
        ARRAY[
            'treasury',
            'customer',
            'agent',
            'vendor'
        ]::text[]
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'FORBIDDEN';
    END IF;

    /*
     * ==========================================================
     * FETCH ACTIVE SUPPORTED BLOCKCHAINS
     * ==========================================================
     *
     * Return one active network per blockchain.
     *
     * Prefer the default network.
     * Otherwise select the most recently created
     * active network.
     */
    RETURN QUERY
    SELECT
        b.code,
        n.chain_id,
        n.rpc_url,
        b.contract_address,
        b.native_currency_code
    FROM public.supported_blockchain AS b

    JOIN LATERAL (
        SELECT
            network.chain_id,
            network.rpc_url
        FROM public.supported_blockchain_network AS network
        WHERE network.blockchain_id = b.id
          AND network.is_active = true
        ORDER BY
            network.is_default DESC,
            network.created_at DESC,
            network.id
        LIMIT 1
    ) AS n ON true

    WHERE b.is_active = true

    ORDER BY
        b.code;

END;
$$;
ALTER FUNCTION "public"."fetch_active_supported_blockchains"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_active_user_by_id"("p_user_id" "text") RETURNS SETOF "public"."users"
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
    v_user public.users%rowtype;
begin
    select u.*
    into v_user
    from public.users u
    where u.id = p_user_id
    limit 1;

    if not found then
        raise exception 'USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception 'USER_NOT_ACTIVE';
    end if;

    return next v_user;
    return;
end;
$$;
ALTER FUNCTION "public"."fetch_active_user_by_id"("p_user_id" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_agent_commission_rate"("p_transaction_type" "public"."TransactionType", "p_currency_code" "text", "p_country_code" "text") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
    select coalesce(
        (
            select commission_config.rate
            from public.agent_fee_splitting_config
                commission_config
            where commission_config.is_active = true
              and lower(
                  commission_config.currency_code
              ) = lower(
                  btrim(p_currency_code)
              )
              and commission_config.transaction_type =
                  p_transaction_type
              and lower(
                  commission_config.country_code
              ) = lower(
                  btrim(p_country_code)
              )
            limit 1
        ),
        0
    );
$$;
ALTER FUNCTION "public"."fetch_agent_commission_rate"("p_transaction_type" "public"."TransactionType", "p_currency_code" "text", "p_country_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_all_transaction_configs"("p_country_code" "text", "p_currency_code" "text" DEFAULT NULL::"text") RETURNS TABLE("config_key" "text", "currency_code" "text", "percentage" numeric, "fixed_amount" numeric, "min_amount" numeric, "max_amount" numeric)
    LANGUAGE "plpgsql" STABLE
    AS $$
begin
    return query
    select
        lower(f.transaction_type::text),
        lower(f.currency_code),
        coalesce(f.rate, 0)::numeric,
        f.fixed_amount::numeric,
        f.min_amount::numeric,
        f.max_amount::numeric
    from public.transaction_type_fee_config f
    where f.country_code = p_country_code
      and f.is_active = true
      and (
          p_currency_code is null
          or lower(f.currency_code) =
             lower(p_currency_code)
      );

    return query
    select
        lower(t.transaction_type::text) ||
            '_tax',
        lower(t.currency_code),
        coalesce(t.rate, 0)::numeric,
        t.fixed_amount::numeric,
        t.min_amount::numeric,
        t.max_amount::numeric
    from public.government_tax_config t
    where t.country_code = p_country_code
      and t.is_active = true
      and (
          p_currency_code is null
          or lower(t.currency_code) =
             lower(p_currency_code)
      );

    return query
    select *
    from public.fetch_spread_by_direction(
        'buy'::public."SpreadDirection",
        'gold'::public."AssetType"
    );

    return query
    select *
    from public.fetch_spread_by_direction(
        'sell'::public."SpreadDirection",
        'gold'::public."AssetType"
    );
end;
$$;
ALTER FUNCTION "public"."fetch_all_transaction_configs"("p_country_code" "text", "p_currency_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_country_calling_code"("p_country_code" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_calling_code text;
begin
    select calling_code
      into v_calling_code
      from public.operational_country
     where country_code = lower(p_country_code);

    if v_calling_code is null then
        raise exception 'COUNTRY_CALLING_CODE_NOT_CONFIGURED';
    end if;

    return v_calling_code;
end;
$$;
ALTER FUNCTION "public"."fetch_country_calling_code"("p_country_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_country_treasury"("p_country_code" "text") RETURNS "public"."users"
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
    v_treasury public.users%rowtype;
begin
    select u.*
    into v_treasury
    from public.users u
    join public.user_role r
      on r.id = u.role_id
    where u.country_code = p_country_code
      and r.name = 'treasury'
    limit 1;

    if not found then
        raise exception 'TREASURY_NOT_FOUND';
    end if;

    return v_treasury;
end;
$$;
ALTER FUNCTION "public"."fetch_country_treasury"("p_country_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_device_tokens"("p_country_code" "text", "p_user_id" "text") RETURNS "text"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$

    select
        case
            when exists (
                select 1
                from public.user_presence p
                where p.user_id =
                      p_user_id

                  and p.is_online =
                      true

                  and p.last_seen_at >
                      current_timestamp
                      - interval '2 minutes'
            )
            then
                array[]::text[]

            else
                coalesce(
                    (
                        select
                            array_agg(
                                distinct d.token
                            )
                        from public.device_tokens d
                        where d.user_id =
                              p_user_id

                          and lower(
                              btrim(d.country_code)
                          ) =
                              lower(
                                  btrim(
                                      p_country_code
                                  )
                              )

                          and d.token is not null

                          and btrim(
                              d.token
                          ) <> ''
                    ),
                    array[]::text[]
                )
        end;

$$;
ALTER FUNCTION "public"."fetch_device_tokens"("p_country_code" "text", "p_user_id" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_fiat_price_update_currencies"() RETURNS TABLE("currency_code" "text", "rate_api" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
    if coalesce(auth.role(), '') <> 'service_role' then
        raise exception using
            errcode = '42501',
            message = 'SERVICE_ROLE_REQUIRED';
    end if;

    /*
     * USD is the base currency.
     * Initialize it without calling an external API.
     */
    if exists (
        select 1
        from public.supported_currency c
        where c.currency_code = 'usd'
          and c.is_active = true
          and c.currency_category = 'fiat'
    ) then
        insert into public.current_rates (
            code,
            rate_to_usd,
            updated_at
        )
        values (
            'usd',
            1,
            now()
        )
        on conflict (code)
        do update set
            rate_to_usd = 1,
            updated_at = now();
    end if;

    return query
    select
        c.currency_code,
        c.rate_api
    from public.supported_currency c
    where c.is_active = true
      and c.currency_category = 'fiat'
      and c.currency_code <> 'usd'
    order by c.currency_code;
end;
$$;
ALTER FUNCTION "public"."fetch_fiat_price_update_currencies"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_financial_statement_gl_entries"("p_gl" "text", "p_currency_code" "text", "p_start_date" "date", "p_end_date" "date", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_gl text;
    v_currency_code text;

    v_gl_type text;
    v_gl_description text;
    v_is_debit_normal boolean;

    v_start_at timestamptz;
    v_end_at timestamptz;

    v_opening_debit numeric := 0;
    v_opening_credit numeric := 0;
    v_opening_balance numeric := 0;

    v_total_debit numeric := 0;
    v_total_credit numeric := 0;
    v_range_movement numeric := 0;

    v_calculated_closing_balance numeric := 0;
    v_closing_balance numeric := 0;
    v_difference numeric := 0;
    v_balanced boolean := true;

    v_total_entries bigint := 0;
    v_total_pages integer := 0;
    v_offset integer := 0;

    v_entries jsonb :=
        '[]'::jsonb;
begin
    /*
     * Authenticate and authorize.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if not public.has_role(
        array[
            'finance',
            'accounts',
            'treasury'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Fetch the authenticated user's trusted country.
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Normalize and validate parameters.
     */
    v_gl :=
        nullif(
            btrim(p_gl),
            ''
        );

    if v_gl is null then
        raise exception
            'GL_IS_REQUIRED';
    end if;

    v_currency_code :=
        nullif(
            lower(
                btrim(p_currency_code)
            ),
            ''
        );

    if v_currency_code is null then
        raise exception
            'CURRENCY_IS_REQUIRED';
    end if;

    if p_start_date is null then
        raise exception
            'START_DATE_IS_REQUIRED';
    end if;

    if p_end_date is null then
        raise exception
            'END_DATE_IS_REQUIRED';
    end if;

    if p_start_date > p_end_date then
        raise exception
            'INVALID_DATE_RANGE';
    end if;

    if p_page is null
       or p_page < 1 then
        raise exception
            'INVALID_PAGE';
    end if;

    if p_page_size is null
       or p_page_size < 1
       or p_page_size > 100 then
        raise exception
            'INVALID_PAGE_SIZE';
    end if;

    /*
     * Convert the requested dates into the same effective
     * range as the old implementation:
     *
     * start date = beginning of day
     * end date   = entire end day
     *
     * Using the following day as an exclusive upper bound
     * avoids timestamp precision problems.
     */
    v_start_at :=
        p_start_date::timestamp
        at time zone 'UTC';

    v_end_at :=
        (p_end_date + 1)::timestamp
        at time zone 'UTC';

    /*
     * Fetch GL account details.
     */
    select
        gl_account_record.type::text,
        coalesce(
            gl_account_record.description,
            ''
        )
    into
        v_gl_type,
        v_gl_description
    from public.gl_account
        gl_account_record
    where gl_account_record.code =
          v_gl
    limit 1;

    if not found then
        raise exception
            'GL_ACCOUNT_NOT_FOUND';
    end if;

    /*
     * Asset and expense accounts are debit-normal.
     * Other account types are credit-normal.
     *
     * This preserves the old TypeScript behaviour.
     */
    v_is_debit_normal :=
        v_gl_type in (
            'asset',
            'expense'
        );

    /*
     * Calculate the opening balance from all entries
     * before the requested start date.
     */
    select
        coalesce(
            sum(
                financial_entry_record.debit
            ),
            0
        ),
        coalesce(
            sum(
                financial_entry_record.credit
            ),
            0
        )
    into
        v_opening_debit,
        v_opening_credit
    from public.financial_entry
        financial_entry_record
    where financial_entry_record.country_code =
          v_user.country_code

      and financial_entry_record.currency_code =
          v_currency_code

      and financial_entry_record.gl_account_code =
          v_gl

      and financial_entry_record.created_at <
          v_start_at;

    if v_is_debit_normal then
        v_opening_balance :=
            v_opening_debit -
            v_opening_credit;
    else
        v_opening_balance :=
            v_opening_credit -
            v_opening_debit;
    end if;

    /*
     * Calculate totals for the requested statement range.
     */
    select
        coalesce(
            sum(
                financial_entry_record.debit
            ),
            0
        ),
        coalesce(
            sum(
                financial_entry_record.credit
            ),
            0
        ),
        count(*)
    into
        v_total_debit,
        v_total_credit,
        v_total_entries
    from public.financial_entry
        financial_entry_record
    where financial_entry_record.country_code =
          v_user.country_code

      and financial_entry_record.currency_code =
          v_currency_code

      and financial_entry_record.gl_account_code =
          v_gl

      and financial_entry_record.created_at >=
          v_start_at

      and financial_entry_record.created_at <
          v_end_at;

    if v_is_debit_normal then
        v_range_movement :=
            v_total_debit -
            v_total_credit;
    else
        v_range_movement :=
            v_total_credit -
            v_total_debit;
    end if;

    v_calculated_closing_balance :=
        v_opening_balance +
        v_range_movement;

    /*
     * The old financial-statement implementation derives
     * closing balance from the financial entries.
     */
    v_closing_balance :=
        v_calculated_closing_balance;

    v_difference :=
        v_closing_balance -
        v_calculated_closing_balance;

    v_balanced :=
        abs(v_difference) <=
        0.000001;

    /*
     * Pagination.
     */
    if v_total_entries = 0 then
        v_total_pages := 0;
    else
        v_total_pages :=
            ceil(
                v_total_entries::numeric /
                p_page_size::numeric
            )::integer;
    end if;

    v_offset :=
        (p_page - 1) *
        p_page_size;

    /*
     * Build the paginated GL entries.
     *
     * Running balance is calculated before pagination so
     * page 2, page 3, etc. continue from the preceding
     * entries rather than restarting at opening balance.
     */
    with ordered_entries as (
        select
            financial_entry_record.id,
            financial_entry_record.period,
            financial_entry_record.fiscal_year,
            financial_entry_record.reference,
            financial_entry_record.document_number,
            financial_entry_record.transaction_id,
            financial_entry_record.transaction_type,
            financial_entry_record.gl_account_code,
            financial_entry_record.currency_code,
            financial_entry_record.debit,
            financial_entry_record.credit,
            financial_entry_record.deposit_type,
            financial_entry_record.created_at,

            v_opening_balance +
            sum(
                case
                    when v_is_debit_normal then
                        coalesce(
                            financial_entry_record.debit,
                            0
                        ) -
                        coalesce(
                            financial_entry_record.credit,
                            0
                        )
                    else
                        coalesce(
                            financial_entry_record.credit,
                            0
                        ) -
                        coalesce(
                            financial_entry_record.debit,
                            0
                        )
                end
            ) over (
                order by
                    financial_entry_record.created_at asc,
                    financial_entry_record.id asc
                rows between
                    unbounded preceding
                    and current row
            ) as running_balance

        from public.financial_entry
            financial_entry_record

        where financial_entry_record.country_code =
              v_user.country_code

          and financial_entry_record.currency_code =
              v_currency_code

          and financial_entry_record.gl_account_code =
              v_gl

          and financial_entry_record.created_at >=
              v_start_at

          and financial_entry_record.created_at <
              v_end_at
    ),

    paged_entries as (
        select *
        from ordered_entries
        order by
            created_at asc,
            id asc
        limit p_page_size
        offset v_offset
    )

    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id',
                paged_entry.id,

                'period',
                paged_entry.period,

                'fiscal_year',
                paged_entry.fiscal_year,

                'reference',
                paged_entry.reference,

                'document_number',
                paged_entry.document_number,

                'transaction_id',
                paged_entry.transaction_id,

                'transaction_type',
                paged_entry.transaction_type,

                'gl_account_code',
                paged_entry.gl_account_code,

                'currency_code',
                paged_entry.currency_code,

                'debit',
                paged_entry.debit,

                'credit',
                paged_entry.credit,

                'deposit_type',
                paged_entry.deposit_type,

                'running_balance',
                paged_entry.running_balance,

                'created_at',
                paged_entry.created_at
            )
            order by
                paged_entry.created_at asc,
                paged_entry.id asc
        ),
        '[]'::jsonb
    )
    into v_entries
    from paged_entries
        paged_entry;

    /*
     * Return the FinancialStatementDrilldown contract.
     */
    return jsonb_build_object(
        'gl_account_code',
        v_gl,

        'description',
        v_gl_description,

        'currency_code',
        v_currency_code,

        'start_date',
        p_start_date,

        'end_date',
        p_end_date,

        'balanced',
        v_balanced,

        'opening_balance',
        v_opening_balance,

        'total_debit',
        v_total_debit,

        'total_credit',
        v_total_credit,

        'calculated_closing_balance',
        v_calculated_closing_balance,

        'closing_balance',
        v_closing_balance,

        'difference',
        v_difference,

        'pagination',
        jsonb_build_object(
            'page',
            p_page,

            'page_size',
            p_page_size,

            'total_entries',
            v_total_entries,

            'total_pages',
            v_total_pages,

            'has_previous',
            p_page > 1,

            'has_next',
            p_page < v_total_pages
        ),

        'entries',
        v_entries
    );
end;
$$;
ALTER FUNCTION "public"."fetch_financial_statement_gl_entries"("p_gl" "text", "p_currency_code" "text", "p_start_date" "date", "p_end_date" "date", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_fiscal_period"("p_country_code" "text", "p_date" timestamp without time zone DEFAULT "now"()) RETURNS TABLE("fiscal_year" integer, "period" integer, "period_name" "text")
    LANGUAGE "plpgsql" STABLE
    AS $$
begin
    return query
    select
        f.fiscal_year,
        f.period,
        f.period_name
    from public.fiscal_period_config f
    where f.country_code = p_country_code
      and f.opening_date <= p_date
      and f.closing_date >= p_date
    limit 1;

    if not found then
        raise exception 'FISCAL_PERIOD_NOT_FOUND';
    end if;
end;
$$;
ALTER FUNCTION "public"."fetch_fiscal_period"("p_country_code" "text", "p_date" timestamp without time zone) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_gl_mappings"("p_transaction_type" "public"."TransactionType") RETURNS SETOF "public"."transaction_gl_mapping"
    LANGUAGE "plpgsql" STABLE
    AS $$
begin
    /*
     * At least one active mapping must exist.
     */
    if not exists (
        select 1
        from public.transaction_gl_mapping m
        where m.transaction_type = p_transaction_type
          and m.is_active = true
    ) then
        raise exception
            'GL_MAPPING_NOT_FOUND_%',
            p_transaction_type;
    end if;

    /*
     * Every transaction must have an active principal mapping.
     */
    if not exists (
        select 1
        from public.transaction_gl_mapping m
        where m.transaction_type = p_transaction_type
          and m.component_type = 'principal'
          and m.is_active = true
    ) then
        raise exception
            'PRINCIPAL_GL_MAPPING_NOT_FOUND_%',
            p_transaction_type;
    end if;

    return query
    select m.*
    from public.transaction_gl_mapping m
    where m.transaction_type = p_transaction_type
      and m.is_active = true
    order by m.component_type asc;
end;
$$;
ALTER FUNCTION "public"."fetch_gl_mappings"("p_transaction_type" "public"."TransactionType") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_gold_price"() RETURNS numeric
    LANGUAGE "sql" STABLE
    AS $$
    select coalesce(
        (
            select r.rate_to_usd::numeric
            from public.current_rates r
            where lower(r.code) = 'gold'
            limit 1
        ),
        0
    );
$$;
ALTER FUNCTION "public"."fetch_gold_price"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_gold_rate_api"() RETURNS TABLE("rate_api" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
    if coalesce(
        auth.role(),
        ''
    ) <> 'service_role'
    then
        raise exception using
            errcode = '42501',
            message = 'SERVICE_ROLE_REQUIRED';
    end if;

    return query
    select
        btrim(
            currency_record.rate_api
        )
    from public.supported_currency
        currency_record
    where lower(
        btrim(
            currency_record.currency_code
        )
    ) = 'gold'

      and currency_record.is_active = true

      and nullif(
          btrim(
              currency_record.rate_api
          ),
          ''
      ) is not null
    limit 1;
end;
$$;
ALTER FUNCTION "public"."fetch_gold_rate_api"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_government_tax_rate"("p_transaction_type" "public"."TransactionType", "p_currency_code" "text", "p_country_code" "text") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
    select coalesce(
        (
            select tax_config.rate
            from public.government_tax_config
                tax_config
            where tax_config.is_active = true
              and lower(
                  tax_config.currency_code
              ) = lower(
                  btrim(p_currency_code)
              )
              and tax_config.transaction_type =
                  p_transaction_type
              and lower(
                  tax_config.country_code
              ) = lower(
                  btrim(p_country_code)
              )
            limit 1
        ),
        0
    );
$$;
ALTER FUNCTION "public"."fetch_government_tax_rate"("p_transaction_type" "public"."TransactionType", "p_currency_code" "text", "p_country_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_incomplete_blockchain_transactions"("p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_page integer;
    v_page_size integer;
    v_offset integer;

    v_total_entries bigint := 0;
    v_total_pages integer := 1;

    v_transactions jsonb :=
        '[]'::jsonb;
begin
    /*
     * Preserve the authorization behaviour of the existing
     * report: any authenticated application user may call
     * this RPC.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    /*
     * Validate pagination.
     */
    if p_page is null
       or p_page < 1
    then
        raise exception
            'INVALID_PAGE';
    end if;

    if p_page_size is null
       or p_page_size < 1
       or p_page_size > 100
    then
        raise exception
            'INVALID_PAGE_SIZE';
    end if;

    v_page :=
        p_page;

    v_page_size :=
        p_page_size;

    v_offset :=
        (v_page - 1) *
        v_page_size;

    /*
     * Combine the two incomplete-processing sources before
     * pagination:
     *
     * 1. General blockchain transactions that do not yet
     *    have an accounting document.
     *
     * 2. Liquidation jobs that have not reached completed,
     *    including jobs that have not created a blockchain
     *    transaction yet.
     *
     * source_type lets the frontend select the correct
     * detail model and actions for each row.
     */
    with incomplete_records as materialized (
        select
            blockchain_record.created_at
                as sort_created_at,

            blockchain_record.id::text
                as sort_id,

            to_jsonb(
                blockchain_record
            ) ||
            jsonb_build_object(
                'source_type',
                'blockchain_transaction',

                'record_id',
                blockchain_record.id,

                'record_status',
                coalesce(
                    to_jsonb(blockchain_record) ->>
                        'status',
                    to_jsonb(blockchain_record) ->>
                        'chain_status'
                ),

                'error_message',
                coalesce(
                    nullif(
                        to_jsonb(blockchain_record) ->>
                            'error_message',
                        ''
                    ),
                    nullif(
                        to_jsonb(blockchain_record) ->>
                            'reason',
                        ''
                    ),
                    nullif(
                        blockchain_record.description,
                        ''
                    )
                )
            ) as payload

        from public.blockchain_transaction
            blockchain_record

        where blockchain_record.document_number
              is null

        union all

        select
            liquidation_record.created_at
                as sort_created_at,

            liquidation_record.id::text
                as sort_id,

            jsonb_build_object(
                /*
                 * Common transaction fields retained for
                 * the existing frontend transaction list.
                 */
                'id',
                liquidation_record.id,

                'source_type',
                'liquidation_job',

                'record_id',
                liquidation_record.id,

                'liquidation_job_id',
                liquidation_record.id,

                'user_id',
                liquidation_record.user_id,

                'period',
                liquidation_record.period,

                'fiscal_year',
                liquidation_record.fiscal_year,

                'country_code',
                liquidation_record.country_code,

                'tx_hash',
                nullif(
                    to_jsonb(queue_record) ->>
                        'tx_hash',
                    ''
                ),

                'document_number',
                liquidation_record.document_number,

                'reference',
                liquidation_record.id,

                'transaction_type',
                'loan_liquidation',

                'sender',
                coalesce(
                    nullif(
                        to_jsonb(queue_record) ->>
                            'sender_wallet_address',
                        ''
                    ),
                    liquidation_record.user_id
                ),

                'receiver',
                nullif(
                    to_jsonb(queue_record) ->>
                        'receiver_wallet_address',
                    ''
                ),

                'quantity',
                trim_scale(
                    liquidation_record.collateral_required
                )::text,

                'gross_amount',
                trim_scale(
                    liquidation_record.total_debt
                )::text,

                'net_amount',
                trim_scale(
                    liquidation_record.repayment_required
                )::text,

                'fee_amount',
                trim_scale(
                    liquidation_record.penalty_amount
                )::text,

                'currency_code',
                'gold',

                'chain',
                'chiado',

                'chain_status',
                coalesce(
                    queue_record.status::text,
                    liquidation_record.status::text
                ),

                'record_status',
                liquidation_record.status::text,

                'description',
                coalesce(
                    nullif(
                        liquidation_record.error_message,
                        ''
                    ),
                    nullif(
                        to_jsonb(queue_record) ->>
                            'error_message',
                        ''
                    ),
                    nullif(
                        to_jsonb(queue_record) ->>
                            'reason',
                        ''
                    )
                ),

                'error_message',
                coalesce(
                    nullif(
                        liquidation_record.error_message,
                        ''
                    ),
                    nullif(
                        to_jsonb(queue_record) ->>
                            'error_message',
                        ''
                    ),
                    nullif(
                        to_jsonb(queue_record) ->>
                            'reason',
                        ''
                    )
                ),

                'explorer_url',
                nullif(
                    to_jsonb(queue_record) ->>
                        'explorer_url',
                    ''
                ),

                'created_by',
                'system',

                'created_at',
                liquidation_record.created_at,

                /*
                 * Liquidation-specific fields.
                 */
                'blockchain_queue_id',
                liquidation_record.blockchain_queue_id,

                'blockchain_status',
                queue_record.status,

                'retry_count',
                coalesce(
                    nullif(
                        to_jsonb(queue_record) ->>
                            'retry_count',
                        ''
                    )::integer,
                    0
                ),

                'total_principal',
                trim_scale(
                    liquidation_record.total_principal
                )::text,

                'total_interest',
                trim_scale(
                    liquidation_record.total_interest
                )::text,

                'total_debt',
                trim_scale(
                    liquidation_record.total_debt
                )::text,

                'penalty_amount',
                trim_scale(
                    liquidation_record.penalty_amount
                )::text,

                'repayment_required',
                trim_scale(
                    liquidation_record.repayment_required
                )::text,

                'collateral_required',
                trim_scale(
                    liquidation_record.collateral_required
                )::text,

                'gold_price',
                trim_scale(
                    liquidation_record.gold_price
                )::text,

                'email',
                user_record.email,

                'phone',
                user_record.phone,

                'first_name',
                user_record.first_name,

                'surname',
                user_record.surname
            ) as payload

        from public.liquidation_job
            liquidation_record

        left join public.users
            user_record
          on user_record.id =
             liquidation_record.user_id

        left join lateral (
            select queue_source.*
            from public.liquidation_blockchain_queue
                queue_source
            where queue_source.liquidation_job_id =
                  liquidation_record.id::text
            order by
                queue_source.id desc
            limit 1
        ) as queue_record
          on true

        where liquidation_record.status::text <>
              'completed'
    ),

    page_records as (
        select incomplete_record.*
        from incomplete_records
            incomplete_record
        order by
            incomplete_record.sort_created_at desc,
            incomplete_record.sort_id desc
        limit v_page_size
        offset v_offset
    )
    select
        (
            select count(*)::bigint
            from incomplete_records
        ),

        coalesce(
            (
                select jsonb_agg(
                    page_record.payload
                    order by
                        page_record.sort_created_at desc,
                        page_record.sort_id desc
                )
                from page_records
                    page_record
            ),
            '[]'::jsonb
        )
    into
        v_total_entries,
        v_transactions;

    v_total_pages :=
        case
            when v_total_entries = 0
                then 1
            else
                ceil(
                    v_total_entries::numeric /
                    v_page_size
                )::integer
        end;

    return jsonb_build_object(
        'transactions',
        v_transactions,

        'pagination',
        jsonb_build_object(
            'page',
            v_page,

            'page_size',
            v_page_size,

            'total_entries',
            v_total_entries,

            'total_pages',
            v_total_pages,

            'has_previous',
            v_page > 1,

            'has_next',
            v_page < v_total_pages
        )
    );
end;
$$;
ALTER FUNCTION "public"."fetch_incomplete_blockchain_transactions"("p_page" integer, "p_page_size" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_kyc_review_queue"("p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20, "p_country_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_page integer;
    v_page_size integer;
    v_offset integer;

    v_country_code text;

    v_total_entries integer;
    v_total_pages integer;

    v_has_previous boolean;
    v_has_next boolean;

    v_data jsonb;

BEGIN

    -- ========================================================
    -- AUTHENTICATION
    -- ========================================================

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;


    -- ========================================================
    -- AUTHORIZATION
    --
    -- Only compliance users can access the KYC review queue.
    -- ========================================================

    IF NOT public.has_role(
        ARRAY[
            'compliance'
        ]::text[]
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'FORBIDDEN';
    END IF;


    -- ========================================================
    -- PAGINATION
    -- ========================================================

    v_page :=
        COALESCE(
            p_page,
            1
        );


    v_page_size :=
        COALESCE(
            p_page_size,
            20
        );


    IF v_page < 1 THEN
        RAISE EXCEPTION USING
            ERRCODE = '22023',
            MESSAGE = 'INVALID_PAGE';
    END IF;


    IF (
        v_page_size < 1
        OR
        v_page_size > 100
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '22023',
            MESSAGE = 'INVALID_PAGE_SIZE';
    END IF;


    v_offset :=
        (v_page - 1) *
        v_page_size;


    -- ========================================================
    -- COUNTRY
    --
    -- NULL:
    --   return users from all countries
    --
    -- VALUE:
    --   return users from that country only
    --
    -- Country codes are normalized to lowercase.
    -- ========================================================

    v_country_code :=
        NULLIF(
            lower(
                btrim(
                    p_country_code
                )
            ),
            ''
        );


    -- ========================================================
    -- VALIDATE COUNTRY
    --
    -- Only validate when a country was supplied.
    -- ========================================================

    IF v_country_code IS NOT NULL THEN

        IF NOT EXISTS (
            SELECT 1
            FROM public.operational_country
                country_record
            WHERE lower(
                country_record.country_code
            ) = v_country_code
              AND country_record.is_active =
                  true
        ) THEN

            RAISE EXCEPTION USING
                ERRCODE = '22023',
                MESSAGE = 'INVALID_COUNTRY';

        END IF;

    END IF;


    -- ========================================================
    -- TOTAL ENTRIES
    --
    -- Start from users because users who have not started KYC
    -- do not yet exist in user_kyc.
    --
    -- Eligible roles:
    --
    -- customer
    -- agent
    -- vendor
    -- merchant
    --
    -- Include:
    --
    -- no current KYC
    --
    -- OR
    --
    -- current KYC is not verified
    --
    -- If country was supplied, count only that country.
    -- ========================================================

    SELECT
        count(*)
    INTO
        v_total_entries

    FROM
        public.users user_record

    INNER JOIN
        public.user_role role_record
        ON role_record.id =
           user_record.role_id

    LEFT JOIN
        public.user_kyc kyc_record
        ON kyc_record.user_id =
           user_record.id
       AND kyc_record.is_current =
           true

    WHERE
        lower(role_record.name) IN (
            'customer',
            'agent',
            'vendor',
            'merchant'
        )

        AND (
            kyc_record.id IS NULL
            OR
            kyc_record.kyc_status <>
                'verified'::public."KycStatus"
        )

        AND (
            v_country_code IS NULL
            OR
            lower(
                user_record.country_code
            ) = v_country_code
        );


    -- ========================================================
    -- TOTAL PAGES
    -- ========================================================

    IF v_total_entries = 0 THEN

        v_total_pages :=
            0;

    ELSE

        v_total_pages :=
            CEIL(
                v_total_entries::numeric /
                v_page_size::numeric
            )::integer;

    END IF;


    -- ========================================================
    -- PREVIOUS / NEXT
    -- ========================================================

    v_has_previous :=
        v_page > 1
        AND
        v_total_pages > 0;


    v_has_next :=
        v_page <
        v_total_pages;


    -- ========================================================
    -- PAGE DATA
    --
    -- Ordering:
    --
    -- 1. Country
    -- 2. Users with KYC started
    -- 3. Oldest outstanding KYC
    -- 4. User ID for deterministic pagination
    --
    -- When country is supplied, the first ordering field is
    -- naturally the same for all returned records.
    -- ========================================================

    SELECT
        COALESCE(
            jsonb_agg(
                jsonb_build_object(

                    'user_id',
                        queue_record.user_id,

                    'first_name',
                        queue_record.first_name,

                    'middle_name',
                        queue_record.middle_name,

                    'surname',
                        queue_record.surname,

                    'email',
                        queue_record.email,

                    'phone',
                        queue_record.phone,

                    'country_code',
                        queue_record.country_code,

                    'country_name',
                        queue_record.country_name,

                    'role_id',
                        queue_record.role_id,

                    'role',
                        queue_record.role,

                    'kyc_id',
                        queue_record.kyc_id,

                    'kyc_status',
                        queue_record.kyc_status,

                    'kyc_started_at',
                        queue_record.kyc_started_at,

                    'kyc_updated_at',
                        queue_record.kyc_updated_at
                )
                ORDER BY
                    queue_record.country_code ASC,
                    queue_record.kyc_sort_order ASC,
                    queue_record.kyc_started_at ASC
                        NULLS LAST,
                    queue_record.user_id ASC
            ),
            '[]'::jsonb
        )
    INTO
        v_data

    FROM (

        SELECT

            -- =================================================
            -- USER
            -- =================================================

            user_record.id
                AS user_id,

            user_record.first_name,

            user_record.middle_name,

            user_record.surname,

            user_record.email,

            user_record.phone,

            lower(
                user_record.country_code
            )
                AS country_code,


            -- =================================================
            -- COUNTRY
            -- =================================================

            country_record.name
                AS country_name,


            -- =================================================
            -- ROLE
            -- =================================================

            role_record.id
                AS role_id,

            role_record.name::text
                AS role,


            -- =================================================
            -- KYC
            --
            -- NULL means KYC has not started.
            -- =================================================

            kyc_record.id
                AS kyc_id,

            kyc_record.kyc_status::text
                AS kyc_status,

            kyc_record.created_at
                AS kyc_started_at,

            kyc_record.updated_at
                AS kyc_updated_at,


            -- =================================================
            -- SORT
            --
            -- Existing KYC = 0
            -- Not started   = 1
            -- =================================================

            CASE
                WHEN kyc_record.id IS NOT NULL
                    THEN 0
                ELSE 1
            END
                AS kyc_sort_order


        FROM
            public.users user_record


        -- =====================================================
        -- ROLE
        -- =====================================================

        INNER JOIN
            public.user_role role_record
            ON role_record.id =
               user_record.role_id


        -- =====================================================
        -- COUNTRY
        -- =====================================================

        INNER JOIN
            public.operational_country country_record
            ON lower(
                country_record.country_code
            ) =
               lower(
                   user_record.country_code
               )


        -- =====================================================
        -- CURRENT KYC
        -- =====================================================

        LEFT JOIN
            public.user_kyc kyc_record
            ON kyc_record.user_id =
               user_record.id
           AND kyc_record.is_current =
               true


        -- =====================================================
        -- FILTER
        -- =====================================================

        WHERE
            lower(role_record.name) IN (
                'customer',
                'agent',
                'vendor',
                'merchant'
            )

            AND (
                kyc_record.id IS NULL
                OR
                kyc_record.kyc_status <>
                    'verified'::public."KycStatus"
            )

            AND (
                v_country_code IS NULL
                OR
                lower(
                    user_record.country_code
                ) = v_country_code
            )


        -- =====================================================
        -- ORDER BEFORE PAGINATION
        -- =====================================================

        ORDER BY

            lower(
                user_record.country_code
            ) ASC,

            CASE
                WHEN kyc_record.id IS NOT NULL
                    THEN 0
                ELSE 1
            END ASC,

            kyc_record.created_at ASC
                NULLS LAST,

            user_record.id ASC


        -- =====================================================
        -- PAGINATION
        -- =====================================================

        LIMIT
            v_page_size

        OFFSET
            v_offset

    ) queue_record;


    -- ========================================================
    -- RESPONSE
    -- ========================================================

    RETURN jsonb_build_object(

        'country_code',
            v_country_code,

        'page',
            v_page,

        'page_size',
            v_page_size,

        'total_entries',
            v_total_entries,

        'total_pages',
            v_total_pages,

        'has_previous',
            v_has_previous,

        'has_next',
            v_has_next,

        'data',
            v_data
    );

END;
$$;
ALTER FUNCTION "public"."fetch_kyc_review_queue"("p_page" integer, "p_page_size" integer, "p_country_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_liquidation_blockchain_config"("p_queue_id" "text") RETURNS TABLE("code" "text", "chain_id" bigint, "rpc_url" "text", "contract_address" "text", "native_currency_code" "text", "explorer_url" "text", "treasury_wallet_address" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
    v_queue public.liquidation_blockchain_queue%rowtype;
    v_blockchain public.supported_blockchain%rowtype;
    v_network public.supported_blockchain_network%rowtype;

    v_saved_chain_id bigint;
    v_contract_address text;
    v_treasury_wallet_address text;
    v_resume boolean;
BEGIN
    IF coalesce(auth.role(), '') <> 'service_role' THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'SERVICE_ROLE_REQUIRED';
    END IF;

    SELECT q.*
    INTO v_queue
    FROM public.liquidation_blockchain_queue AS q
    WHERE q.id = p_queue_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'LIQUIDATION_QUEUE_NOT_FOUND';
    END IF;

    IF nullif(btrim(v_queue.blockchain_code), '') IS NULL THEN
        RAISE EXCEPTION 'LIQUIDATION_BLOCKCHAIN_CODE_REQUIRED';
    END IF;

    SELECT b.*
    INTO v_blockchain
    FROM public.supported_blockchain AS b
    WHERE b.code = v_queue.blockchain_code;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'LIQUIDATION_BLOCKCHAIN_NOT_FOUND';
    END IF;

    IF v_blockchain.blockchain_type IS DISTINCT FROM 'evm' THEN
        RAISE EXCEPTION 'UNSUPPORTED_BLOCKCHAIN_TYPE';
    END IF;

    v_resume :=
        v_queue.signed_payload IS NOT NULL
        OR v_queue.tx_hash IS NOT NULL;

    IF v_resume THEN
        /*
         * Recover the exact network and contract used
         * when the signature was created.
         */
        IF v_queue.signed_payload IS NULL
           OR (v_queue.signed_payload ->> 'blockchain_code')
              IS DISTINCT FROM v_queue.blockchain_code
           OR coalesce(
               v_queue.signed_payload ->> 'chain_id',
               ''
           ) !~ '^[0-9]+$'
        THEN
            RAISE EXCEPTION
                'LIQUIDATION_SAVED_BLOCKCHAIN_METADATA_REQUIRED';
        END IF;

        BEGIN
            v_saved_chain_id :=
                (v_queue.signed_payload ->> 'chain_id')::bigint;
        EXCEPTION
            WHEN invalid_text_representation
              OR numeric_value_out_of_range
            THEN
                RAISE EXCEPTION
                    'INVALID_LIQUIDATION_SAVED_CHAIN_ID';
        END;

        IF v_saved_chain_id <= 0 THEN
            RAISE EXCEPTION
                'INVALID_LIQUIDATION_SAVED_CHAIN_ID';
        END IF;

        v_contract_address :=
            nullif(
                btrim(
                    v_queue.signed_payload ->> 'contract_address'
                ),
                ''
            );

        /*
         * chain_id is unique in supported_blockchain_network.
         *
         * Do not filter is_active here: a disabled network
         * may still contain a transaction requiring recovery.
         */
        SELECT n.*
        INTO v_network
        FROM public.supported_blockchain_network AS n
        WHERE n.blockchain_id = v_blockchain.id
          AND n.chain_id = v_saved_chain_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'LIQUIDATION_SAVED_NETWORK_NOT_FOUND';
        END IF;

        /*
         * Use the signed recipient for existing jobs.
         * Configuration changes must not change that recipient.
         */
        v_treasury_wallet_address :=
            nullif(
                btrim(v_queue.signed_payload ->> 'to'),
                ''
            );
    ELSE
        /*
         * A new signature requires an active blockchain
         * and an active configured network.
         */
        IF v_blockchain.is_active IS DISTINCT FROM true THEN
            RAISE EXCEPTION 'BLOCKCHAIN_NOT_FOUND_OR_INACTIVE';
        END IF;

        SELECT n.*
        INTO v_network
        FROM public.supported_blockchain_network AS n
        WHERE n.blockchain_id = v_blockchain.id
          AND n.is_active = true
        ORDER BY
            n.is_default DESC,
            n.created_at DESC,
            n.id
        LIMIT 1;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'BLOCKCHAIN_NETWORK_NOT_FOUND_OR_INACTIVE';
        END IF;

        v_contract_address :=
            nullif(btrim(v_blockchain.contract_address), '');

        v_treasury_wallet_address :=
            nullif(btrim(v_network.treasury_wallet_address), '');
    END IF;

    /*
     * Validate the resolved configuration.
     */
    IF v_network.chain_id <= 0 THEN
        RAISE EXCEPTION 'INVALID_BLOCKCHAIN_CHAIN_ID';
    END IF;

    IF nullif(btrim(v_network.rpc_url), '') IS NULL THEN
        RAISE EXCEPTION 'BLOCKCHAIN_RPC_URL_MISSING';
    END IF;

    IF nullif(btrim(v_network.explorer_url), '') IS NULL THEN
        RAISE EXCEPTION 'BLOCKCHAIN_EXPLORER_URL_MISSING';
    END IF;

    IF v_contract_address IS NULL
       OR v_contract_address !~ '^0x[0-9a-fA-F]{40}$'
       OR lower(v_contract_address) =
          '0x0000000000000000000000000000000000000000'
    THEN
        RAISE EXCEPTION 'INVALID_TOKEN_CONTRACT_ADDRESS';
    END IF;

    IF v_treasury_wallet_address IS NULL
       OR v_treasury_wallet_address !~ '^0x[0-9a-fA-F]{40}$'
       OR lower(v_treasury_wallet_address) =
          '0x0000000000000000000000000000000000000000'
    THEN
        RAISE EXCEPTION
            'INVALID_LIQUIDATION_TREASURY_WALLET_ADDRESS';
    END IF;

    RETURN QUERY
    SELECT
        v_blockchain.code,
        v_network.chain_id,
        btrim(v_network.rpc_url),
        v_contract_address,
        v_blockchain.native_currency_code,
        btrim(v_network.explorer_url),
        v_treasury_wallet_address;
END;
$_$;
ALTER FUNCTION "public"."fetch_liquidation_blockchain_config"("p_queue_id" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_liquidation_reconciliation_context"("p_job_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_job_id text;
    v_result jsonb;
begin
    if coalesce(
        auth.role(),
        ''
    ) <> 'service_role'
    then
        raise exception using
            errcode = '42501',
            message = 'SERVICE_ROLE_REQUIRED';
    end if;

    v_job_id :=
        nullif(
            btrim(
                p_job_id
            ),
            ''
        );

    if v_job_id is null then
        raise exception
            'LIQUIDATION_JOB_ID_REQUIRED';
    end if;

    select jsonb_build_object(
        'queue_id',
        queue_record.id::text,

        'liquidation_job_id',
        job_record.id::text,

        'job_status',
        job_record.status::text,

        'queue_status',
        queue_record.status::text,

        'manual_review_required',
        queue_record.manual_review_required,

        'country_code',
        lower(
            btrim(
                job_record.country_code
            )
        ),

        'document_number',
        job_record.document_number,

        'sender_wallet_address',
        queue_record.sender_wallet_address,

        'receiver_wallet_address',
        coalesce(
            nullif(
                btrim(
                    queue_record.signed_payload ->> 'to'
                ),
                ''
            ),
            queue_record.receiver_wallet_address
        ),

        'collateral',
        trim_scale(
            queue_record.collateral
        )::text,

        'tx_hash',
        queue_record.tx_hash,

        'signed_payload',
        queue_record.signed_payload
    )
    into v_result
    from public.liquidation_job
        job_record

    join public.liquidation_blockchain_queue
        queue_record
      on queue_record.liquidation_job_id =
         job_record.id::text

    where job_record.id::text =
          v_job_id

      and queue_record.manual_review_required = true;

    if v_result is null then
        raise exception
            'LIQUIDATION_RECONCILIATION_CONTEXT_NOT_FOUND';
    end if;

    return v_result;
end;
$$;
ALTER FUNCTION "public"."fetch_liquidation_reconciliation_context"("p_job_id" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_merchant_commission_rate"("p_transaction_type" "public"."TransactionType", "p_currency_code" "text", "p_country_code" "text") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
    select coalesce(
        (
            select
                commission_config.merchant_rate::numeric

            from public.merchant_fee_splitting_config
                commission_config

            where commission_config.transaction_type =
                  p_transaction_type

              and lower(
                  btrim(
                      commission_config.currency_code
                  )
              ) = lower(
                  btrim(
                      p_currency_code
                  )
              )

              and lower(
                  btrim(
                      commission_config.country_code
                  )
              ) = lower(
                  btrim(
                      p_country_code
                  )
              )

              and commission_config.is_active =
                  true

            limit 1
        ),
        0
    );
$$;
ALTER FUNCTION "public"."fetch_merchant_commission_rate"("p_transaction_type" "public"."TransactionType", "p_currency_code" "text", "p_country_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_active_loan_detail"("p_loan_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;
    v_loan public.loan%rowtype;

    v_entries jsonb := '[]'::jsonb;

    v_debit_principal numeric := 0;
    v_credit_principal numeric := 0;
    v_debit_interest numeric := 0;
    v_credit_interest numeric := 0;

    v_principal_balance numeric := 0;
    v_interest_balance numeric := 0;
    v_outstanding_balance numeric := 0;
begin
    /*
     * Authenticate and authorize customer.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'customer',
            'agent',
            'vendor'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    select user_record.*
    into v_user
    from public.users user_record
    where user_record.id =
          auth.uid()::text
    limit 1;

    if not found then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'USER_NOT_ACTIVE';
    end if;

    /*
     * Validate the loan ID.
     */
    if p_loan_id is null
       or btrim(p_loan_id) = ''
    then
        raise exception
            'LOAN_ID_UNDEFINED';
    end if;

    /*
     * Fetch only an active loan belonging to the authenticated
     * customer.
     */
    select loan_record.*
    into v_loan
    from public.loan loan_record
    where loan_record.id =
          btrim(p_loan_id)
      and loan_record.user_id =
          v_user.id
      and loan_record.status =
          'active'::public."LoanStatus"
    limit 1;

    if not found then
        raise exception
            'ACTIVE_LOAN_NOT_FOUND';
    end if;

    /*
     * Fetch loan entries in newest-first display order.
     *
     * Entry amounts remain strings, matching Prisma Decimal
     * serialization from the original API.
     */
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'created_at',
                loan_entry_record.created_at,

                'entry_type',
                loan_entry_record.entry_type::text,

                'debit_principal',
                coalesce(
                    loan_entry_record.debit_principal,
                    0
                )::text,

                'credit_principal',
                coalesce(
                    loan_entry_record.credit_principal,
                    0
                )::text,

                'debit_interest',
                coalesce(
                    loan_entry_record.debit_interest,
                    0
                )::text,

                'credit_interest',
                coalesce(
                    loan_entry_record.credit_interest,
                    0
                )::text,

                'accrual_date',
                loan_entry_record.accrual_date
            )
            order by
                loan_entry_record.created_at desc,
                loan_entry_record.id desc
        ),
        '[]'::jsonb
    )
    into v_entries
    from public.loan_entry
        loan_entry_record
    where loan_entry_record.loan_id =
          v_loan.id;

    /*
     * Calculate totals using PostgreSQL numeric values rather
     * than JavaScript Number conversion.
     */
    select
        coalesce(
            sum(
                loan_entry_record.debit_principal
            ),
            0
        ),

        coalesce(
            sum(
                loan_entry_record.credit_principal
            ),
            0
        ),

        coalesce(
            sum(
                loan_entry_record.debit_interest
            ),
            0
        ),

        coalesce(
            sum(
                loan_entry_record.credit_interest
            ),
            0
        )
    into
        v_debit_principal,
        v_credit_principal,
        v_debit_interest,
        v_credit_interest
    from public.loan_entry
        loan_entry_record
    where loan_entry_record.loan_id =
          v_loan.id;

    v_principal_balance :=
        v_debit_principal -
        v_credit_principal;

    v_interest_balance :=
        v_debit_interest -
        v_credit_interest;

    v_outstanding_balance :=
        v_principal_balance +
        v_interest_balance;

    return jsonb_build_object(
        'entries',
        v_entries,

        'totals',
        jsonb_build_object(
            'debit_principal',
            v_debit_principal,

            'credit_principal',
            v_credit_principal,

            'debit_interest',
            v_debit_interest,

            'credit_interest',
            v_credit_interest
        ),

        'balances',
        jsonb_build_object(
            'principal_balance',
            v_principal_balance,

            'interest_balance',
            v_interest_balance,

            'outstanding_balance',
            v_outstanding_balance
        )
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_active_loan_detail"("p_loan_id" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_active_loan_detail"("p_loan_id" "text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;
    v_loan public.loan%rowtype;

    v_entries jsonb := '[]'::jsonb;

    v_page integer;
    v_page_size integer;
    v_offset bigint;

    v_total_entries bigint := 0;
    v_total_pages bigint := 0;

    v_has_previous boolean := false;
    v_has_next boolean := false;

    v_debit_principal numeric := 0;
    v_credit_principal numeric := 0;
    v_debit_interest numeric := 0;
    v_credit_interest numeric := 0;

    v_principal_balance numeric := 0;
    v_interest_balance numeric := 0;
    v_outstanding_balance numeric := 0;
begin
    /*
     * Authenticate and authorize customer.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'customer',
            'agent',
            'vendor'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    select user_record.*
    into v_user
    from public.users user_record
    where user_record.id = auth.uid()::text
    limit 1;

    if not found then
        raise exception 'USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception 'USER_NOT_ACTIVE';
    end if;

    /*
     * Validate loan ID.
     */
    if p_loan_id is null
       or btrim(p_loan_id) = ''
    then
        raise exception 'LOAN_ID_UNDEFINED';
    end if;

    /*
     * Validate pagination parameters.
     */
    if p_page is null or p_page < 1 then
        raise exception 'INVALID_PAGE';
    end if;

    if p_page_size is null
       or p_page_size < 1
    then
        raise exception 'INVALID_PAGE_SIZE';
    end if;

    v_page := p_page;
    v_page_size := p_page_size;

    v_offset :=
        (v_page::bigint - 1) *
        v_page_size::bigint;

    /*
     * Fetch only an active loan belonging
     * to the authenticated customer.
     */
    select loan_record.*
    into v_loan
    from public.loan loan_record
    where loan_record.id = btrim(p_loan_id)
      and loan_record.user_id = v_user.id
      and loan_record.status =
          'active'::public."LoanStatus"
    limit 1;

    if not found then
        raise exception 'ACTIVE_LOAN_NOT_FOUND';
    end if;

    /*
     * Count all loan entries and calculate
     * financial totals across the entire loan.
     *
     * These totals must NOT be affected
     * by pagination.
     */
    select
        count(*),

        coalesce(
            sum(
                loan_entry_record.debit_principal
            ),
            0
        ),

        coalesce(
            sum(
                loan_entry_record.credit_principal
            ),
            0
        ),

        coalesce(
            sum(
                loan_entry_record.debit_interest
            ),
            0
        ),

        coalesce(
            sum(
                loan_entry_record.credit_interest
            ),
            0
        )
    into
        v_total_entries,
        v_debit_principal,
        v_credit_principal,
        v_debit_interest,
        v_credit_interest
    from public.loan_entry loan_entry_record
    where loan_entry_record.loan_id = v_loan.id;

    /*
     * Calculate total pages.
     */
    v_total_pages :=
        case
            when v_total_entries = 0 then 1
            else
                (
                    v_total_entries +
                    v_page_size::bigint - 1
                ) / v_page_size::bigint
        end;

    /*
     * Determine pagination navigation.
     */
    v_has_previous :=
        v_page > 1;

    v_has_next :=
        v_page < v_total_pages;

    /*
     * Fetch ONLY the requested page.
     *
     * Newest entries first.
     *
     * The ID provides deterministic
     * ordering when timestamps are equal.
     *
     * Amounts remain strings to preserve
     * the existing response format.
     */
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'created_at',
                paged_entry.created_at,

                'entry_type',
                paged_entry.entry_type::text,

                'debit_principal',
                coalesce(
                    paged_entry.debit_principal,
                    0
                )::text,

                'credit_principal',
                coalesce(
                    paged_entry.credit_principal,
                    0
                )::text,

                'debit_interest',
                coalesce(
                    paged_entry.debit_interest,
                    0
                )::text,

                'credit_interest',
                coalesce(
                    paged_entry.credit_interest,
                    0
                )::text,

                'accrual_date',
                paged_entry.accrual_date
            )
            order by
                paged_entry.created_at desc,
                paged_entry.id desc
        ),
        '[]'::jsonb
    )
    into v_entries
    from (
        select
            loan_entry_record.id,
            loan_entry_record.created_at,
            loan_entry_record.entry_type,
            loan_entry_record.debit_principal,
            loan_entry_record.credit_principal,
            loan_entry_record.debit_interest,
            loan_entry_record.credit_interest,
            loan_entry_record.accrual_date
        from public.loan_entry loan_entry_record
        where loan_entry_record.loan_id = v_loan.id
        order by
            loan_entry_record.created_at desc,
            loan_entry_record.id desc
        limit v_page_size
        offset v_offset
    ) paged_entry;

    /*
     * Calculate balances from ALL
     * loan entries.
     */
    v_principal_balance :=
        v_debit_principal -
        v_credit_principal;

    v_interest_balance :=
        v_debit_interest -
        v_credit_interest;

    v_outstanding_balance :=
        v_principal_balance +
        v_interest_balance;

    /*
     * Return paginated entries,
     * complete financial totals,
     * complete balances and
     * pagination metadata.
     */
    return jsonb_build_object(
        'entries',
        v_entries,

        'totals',
        jsonb_build_object(
            'debit_principal',
            v_debit_principal,

            'credit_principal',
            v_credit_principal,

            'debit_interest',
            v_debit_interest,

            'credit_interest',
            v_credit_interest
        ),

        'balances',
        jsonb_build_object(
            'principal_balance',
            v_principal_balance,

            'interest_balance',
            v_interest_balance,

            'outstanding_balance',
            v_outstanding_balance
        ),

        'pagination',
        jsonb_build_object(
            'page',
            v_page,

            'page_size',
            v_page_size,

            'total_entries',
            v_total_entries,

            'total_pages',
            v_total_pages,

            'has_previous',
            v_has_previous,

            'has_next',
            v_has_next
        )
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_active_loan_detail"("p_loan_id" "text", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_active_loans"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user   public.users%rowtype;
    v_result jsonb;
begin
    /*
     * Authorize customer.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'customer',
            'agent',
            'vendor'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    select user_record.*
    into v_user
    from public.users user_record
    where user_record.id = auth.uid()::text
    limit 1;

    if not found then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.status <> 'active'::public."UserStatus" then
        raise exception
            'USER_NOT_ACTIVE';
    end if;

    /*
     * Fetch active loans and aggregate their ledger entries.
     *
     * Principal:
     *   debit_principal  = principal created / increased
     *   credit_principal = principal repaid / reduced
     *
     * Interest:
     *   debit_interest   = interest accrued
     *   credit_interest  = interest repaid / reduced
     */
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id',
                active_loan.id,

                'principal',
                round(
                    coalesce(
                        active_loan.principal,
                        0
                    ),
                    6
                ),

                'initiation_fee',
                round(
                    coalesce(
                        active_loan.initiation_fee,
                        0
                    ),
                    6
                ),

                'net_amount',
                round(
                    coalesce(
                        active_loan.net_amount,
                        0
                    ),
                    6
                ),

                'interest_rate',
                round(
                    coalesce(
                        active_loan.interest_rate,
                        0
                    ),
                    6
                ),

                /*
                 * The database column is collateral.
                 * The API response remains collateral_grams.
                 */
                'collateral_grams',
                round(
                    coalesce(
                        active_loan.collateral,
                        0
                    ),
                    6
                ),

                'liquidation_price',
                round(
                    coalesce(
                        active_loan.liquidation_price,
                        0
                    ),
                    6
                ),

                /*
                 * Outstanding principal:
                 *
                 * principal created
                 * -
                 * principal repaid
                 */
                'outstanding_principal',
                round(
                    coalesce(
                        entry_totals.debit_principal,
                        0
                    )
                    -
                    coalesce(
                        entry_totals.credit_principal,
                        0
                    ),
                    6
                ),

                /*
                 * Accrued interest:
                 *
                 * interest accrued
                 * -
                 * interest repaid
                 */
                'accrued_interest',
                round(
                    coalesce(
                        entry_totals.debit_interest,
                        0
                    )
                    -
                    coalesce(
                        entry_totals.credit_interest,
                        0
                    ),
                    6
                )
            )
            order by
                active_loan.fiscal_year desc,
                active_loan.period desc,
                active_loan.document_number desc
        ),
        '[]'::jsonb
    )
    into v_result

    from public.loan active_loan

    left join lateral (
        select
            /*
             * Principal totals.
             */
            coalesce(
                sum(
                    coalesce(
                        loan_entry_record.debit_principal,
                        0
                    )
                ),
                0
            ) as debit_principal,

            coalesce(
                sum(
                    coalesce(
                        loan_entry_record.credit_principal,
                        0
                    )
                ),
                0
            ) as credit_principal,

            /*
             * Interest totals.
             */
            coalesce(
                sum(
                    coalesce(
                        loan_entry_record.debit_interest,
                        0
                    )
                ),
                0
            ) as debit_interest,

            coalesce(
                sum(
                    coalesce(
                        loan_entry_record.credit_interest,
                        0
                    )
                ),
                0
            ) as credit_interest

        from public.loan_entry loan_entry_record
        where loan_entry_record.loan_id = active_loan.id
    ) as entry_totals
        on true

    where active_loan.user_id = v_user.id
      and active_loan.status = 'active'::public."LoanStatus";

    return v_result;
end;
$$;
ALTER FUNCTION "public"."fetch_my_active_loans"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_additional_collateral_context"() RETURNS TABLE("user_id" "text", "country_code" "text", "user_wallet_address" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;
begin
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'customer',
            'agent',
            'vendor'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    select user_record.*
    into v_user
    from public.users user_record
    where user_record.id =
          auth.uid()::text
      and user_record.status =
          'active'::public."UserStatus"
    limit 1;

    if not found then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if nullif(
        btrim(v_user.country_code),
        ''
    ) is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    if nullif(
        btrim(v_user.wallet_address),
        ''
    ) is null then
        raise exception
            'USER_WALLET_ADDRESS_NOT_FOUND';
    end if;

    return query
    select
        v_user.id::text,
        v_user.country_code::text,
        v_user.wallet_address::text;
end;
$$;
ALTER FUNCTION "public"."fetch_my_additional_collateral_context"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_agent_commission_batches"("p_status" "public"."SettlementStatus") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_batches jsonb :=
        '[]'::jsonb;
begin
    /*
     * Authentication and authorization.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'finance',
            'accounts'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    if p_status is null then
        raise exception
            'SETTLEMENT_STATUS_REQUIRED';
    end if;

    /*
     * Fetch trusted user context.
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'USER_NOT_ACTIVE';
    end if;

    if nullif(
        btrim(
            v_user.country_code
        ),
        ''
    ) is null
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Fetch batch headers only.
     *
     * Settlement items are fetched separately using the
     * paginated drill-down endpoint.
     */
    select coalesce(
        jsonb_agg(
            to_jsonb(
                batch_record
            )
            ||
            jsonb_build_object(
                'total_amount',
                batch_record.total_amount::text
            )
            order by
                batch_record.created_at desc,
                batch_record.id desc
        ),
        '[]'::jsonb
    )
    into v_batches
    from public.agent_settlement_batch
        batch_record
    where batch_record.status =
              p_status

      and lower(
          btrim(
              batch_record.country_code
          )
      ) =
              lower(
                  btrim(
                      v_user.country_code
                  )
              );

    return jsonb_build_object(
        'settlementBatch',
        v_batches
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_agent_commission_batches"("p_status" "public"."SettlementStatus") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_agent_commission_settlement_batches"("p_statuses" "public"."SettlementStatus"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_result jsonb :=
        '[]'::jsonb;
begin
    /*
     * Authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Accounts processes settlement batches.
     * Finance reviews and approves/cancels them.
     */
    if not public.has_role(
        array[
            'accounts',
            'finance'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Validate statuses.
     */
    if p_statuses is null
       or cardinality(p_statuses) = 0
    then
        raise exception
            'SETTLEMENT_STATUSES_REQUIRED';
    end if;

    if array_position(
        p_statuses,
        null
    ) is not null
    then
        raise exception
            'INVALID_SETTLEMENT_STATUS';
    end if;

    /*
     * Fetch trusted user context.
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'USER_NOT_ACTIVE';
    end if;

    if nullif(
        btrim(v_user.country_code),
        ''
    ) is null
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Fetch batches matching any requested status.
     *
     * Items are deliberately excluded. They are fetched
     * separately through the paginated drill-down.
     */
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id',
                batch_record.id,

                'period',
                batch_record.period,

                'fiscal_year',
                batch_record.fiscal_year,

                'document_number',
                batch_record.document_number,

                'reference',
                batch_record.reference,

                'currency_code',
                lower(
                    btrim(
                        batch_record.currency_code
                    )
                ),

                'start_date',
                batch_record.start_date,

                'end_date',
                batch_record.end_date,

                'total_agents',
                batch_record.total_agents,

                'total_amount',
                trim_scale(
                    batch_record.total_amount
                )::text,

                'status',
                batch_record.status,

                'created_by',
                batch_record.created_by,

                'approved_by',
                batch_record.approved_by,

                'created_at',
                batch_record.created_at,

                'approved_at',
                batch_record.approved_at,

                'paid_at',
                batch_record.paid_at,

                'error_message',
                batch_record.error_message
            )
            order by
                batch_record.created_at desc,
                batch_record.id desc
        ),
        '[]'::jsonb
    )
    into v_result
    from public.agent_settlement_batch
        batch_record
    where lower(
        btrim(
            batch_record.country_code
        )
    ) =
        lower(
            btrim(
                v_user.country_code
            )
        )

      and batch_record.status =
          any(p_statuses);

    return jsonb_build_object(
        'settlementBatch',
        v_result
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_agent_commission_settlement_batches"("p_statuses" "public"."SettlementStatus"[]) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_agent_commission_settlement_items"("p_batch_id" "text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;
    v_batch public.agent_settlement_batch%rowtype;

    v_batch_id text;

    v_offset integer;
    v_total_entries integer;
    v_total_pages integer;

    v_items jsonb := '[]'::jsonb;
begin
    /*
     * Authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Accounts creates and reviews batches.
     * Finance may also review settlement details.
     */
    if not public.has_role(
        array[
            'accounts',
            'finance'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Validate input.
     */
    v_batch_id :=
        nullif(
            btrim(p_batch_id),
            ''
        );

    if v_batch_id is null then
        raise exception
            'SETTLEMENT_BATCH_ID_REQUIRED';
    end if;

    if p_page is null
       or p_page < 1
    then
        raise exception
            'INVALID_PAGE';
    end if;

    if p_page_size is null
       or p_page_size < 1
       or p_page_size > 100
    then
        raise exception
            'INVALID_PAGE_SIZE';
    end if;

    v_offset :=
        (p_page - 1) *
        p_page_size;

    /*
     * Fetch trusted user context.
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'USER_NOT_ACTIVE';
    end if;

    if nullif(
        btrim(v_user.country_code),
        ''
    ) is null
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Fetch the requested batch.
     *
     * Country filtering prevents Accounts or Finance
     * users from viewing another country's settlement.
     */
    select batch_record.*
    into v_batch
    from public.agent_settlement_batch
        batch_record
    where batch_record.id::text =
              v_batch_id

      and lower(
          btrim(
              batch_record.country_code
          )
      ) =
          lower(
              btrim(
                  v_user.country_code
              )
          )
    limit 1;

    if not found then
        raise exception
            'AGENT_COMMISSION_SETTLEMENT_BATCH_NOT_FOUND';
    end if;

    /*
     * Count all items in the selected batch.
     */
    select count(*)::integer
    into v_total_entries
    from public.agent_settlement_item
        item_record
    where item_record.batch_id =
          v_batch.id;

    v_total_pages :=
        case
            when v_total_entries = 0
            then 1
            else ceil(
                v_total_entries::numeric /
                p_page_size::numeric
            )::integer
        end;

    /*
     * Fetch the requested page.
     *
     * Only fields required by SettlementItem are
     * returned.
     */
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id',
                paged_item.id,

                'period',
                paged_item.period,

                'fiscal_year',
                paged_item.fiscal_year,

                'batch_id',
                paged_item.batch_id,

                'agent_id',
                paged_item.agent_id,

                'currency_code',
                lower(
                    btrim(
                        paged_item.currency_code
                    )
                ),

                'total_commission',
                trim_scale(
                    paged_item.total_commission
                )::text,

                'total_withdrawal_volume',
                trim_scale(
                    paged_item.total_withdrawal_volume
                )::text,

                'total_fees_generated',
                trim_scale(
                    paged_item.total_fees_generated
                )::text,

                'status',
                paged_item.status,

                'paid_at',
                paged_item.paid_at,

                'error_message',
                paged_item.error_message
            )
            order by
                paged_item.agent_id,
                paged_item.id
        ),
        '[]'::jsonb
    )
    into v_items
    from (
        select item_record.*
        from public.agent_settlement_item
            item_record
        where item_record.batch_id =
              v_batch.id
        order by
            item_record.agent_id,
            item_record.id
        offset v_offset
        limit p_page_size
    ) as paged_item;

    return jsonb_build_object(
        /*
        * Batch header information.
        */
        'totalAgents',
        v_batch.total_agents,

        'currency',
        lower(
            btrim(
                v_batch.currency_code
            )
        ),

        'totalAmount',
        trim_scale(
            v_batch.total_amount
        )::text,

        /*
        * Paginated drill-down rows.
        */
        'items',
        v_items,

        'pagination',
        jsonb_build_object(
            'page',
            p_page,

            'page_size',
            p_page_size,

            'total_entries',
            v_total_entries,

            'total_pages',
            v_total_pages,

            'has_previous',
            p_page > 1,

            'has_next',
            p_page < v_total_pages
        )
    );

end;
$$;
ALTER FUNCTION "public"."fetch_my_agent_commission_settlement_items"("p_batch_id" "text", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_agent_commission_summary"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_now timestamptz :=
        current_timestamp;

    v_start_of_today timestamptz;
    v_start_of_tomorrow timestamptz;

    v_start_of_week timestamptz;
    v_start_of_next_week timestamptz;

    v_start_of_fortnight timestamptz;
    v_end_of_fortnight timestamptz;

    v_start_of_month timestamptz;
    v_start_of_next_month timestamptz;

    v_start_of_year timestamptz;
    v_start_of_next_year timestamptz;

    v_result jsonb :=
        '{}'::jsonb;
begin
    /*
     * Authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Agents, vendors and merchants may earn commission
     * by facilitating transactions such as cash
     * withdrawals.
     */
    if not public.has_role(
        array[
            'agent',
            'vendor',
            'merchant'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Fetch the authenticated user.
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'USER_NOT_ACTIVE';
    end if;

    /*
     * Calculate reporting boundaries.
     *
     * PostgreSQL weeks begin on Monday, matching the
     * ISO-week calculation previously used by dayjs.
     */
    v_start_of_today :=
        date_trunc(
            'day',
            v_now
        );

    v_start_of_tomorrow :=
        v_start_of_today +
        interval '1 day';

    v_start_of_week :=
        date_trunc(
            'week',
            v_now
        );

    v_start_of_next_week :=
        v_start_of_week +
        interval '1 week';

    /*
     * Fortnight means the current ISO week plus the
     * immediately preceding ISO week.
     */
    v_start_of_fortnight :=
        v_start_of_week -
        interval '1 week';

    v_end_of_fortnight :=
        v_start_of_next_week;

    v_start_of_month :=
        date_trunc(
            'month',
            v_now
        );

    v_start_of_next_month :=
        v_start_of_month +
        interval '1 month';

    v_start_of_year :=
        date_trunc(
            'year',
            v_now
        );

    v_start_of_next_year :=
        v_start_of_year +
        interval '1 year';

    /*
     * Build:
     *
     * {
     *   "usd": {
     *     "today": {...},
     *     "week": {...},
     *     "fortnight": {...},
     *     "month": {...},
     *     "year": {...}
     *   }
     * }
     *
     * Only currencies having commission entries during
     * the current year are included, matching the
     * previous Prisma implementation.
     */
    with reporting_periods as (
        select *
        from (
            values
                (
                    'today'::text,
                    1,
                    v_start_of_today,
                    v_start_of_tomorrow
                ),

                (
                    'week'::text,
                    2,
                    v_start_of_week,
                    v_start_of_next_week
                ),

                (
                    'fortnight'::text,
                    3,
                    v_start_of_fortnight,
                    v_end_of_fortnight
                ),

                (
                    'month'::text,
                    4,
                    v_start_of_month,
                    v_start_of_next_month
                ),

                (
                    'year'::text,
                    5,
                    v_start_of_year,
                    v_start_of_next_year
                )
        ) as period_record(
            period_name,
            sort_order,
            start_at,
            end_at
        )
    ),

    user_currencies as (
        select distinct
            lower(
                btrim(
                    commission_record.currency_code
                )
            ) as currency_code

        from public.agent_commission
            commission_record

        where commission_record.agent_id =
                  v_user.id

          and commission_record.created_at >=
                  v_start_of_year

          and commission_record.created_at <
                  v_start_of_next_year
    ),

    period_totals as (
        select
            currency_record.currency_code,

            period_record.period_name,

            period_record.sort_order,

            coalesce(
                sum(
                    coalesce(
                        commission_record.amount,
                        0
                    )
                ),
                0
            )::numeric as total_amount,

            coalesce(
                sum(
                    coalesce(
                        commission_record.fee_amount,
                        0
                    )
                ),
                0
            )::numeric as total_fee,

            coalesce(
                sum(
                    coalesce(
                        commission_record.commission_amount,
                        0
                    )
                ),
                0
            )::numeric as total_commission,

            coalesce(
                sum(
                    case
                        when commission_record.is_settled =
                             true
                        then
                            coalesce(
                                commission_record.commission_amount,
                                0
                            )
                        else
                            0
                    end
                ),
                0
            )::numeric as paid,

            coalesce(
                sum(
                    case
                        when commission_record.is_settled =
                             false
                        then
                            coalesce(
                                commission_record.commission_amount,
                                0
                            )
                        else
                            0
                    end
                ),
                0
            )::numeric as not_paid

        from user_currencies
            currency_record

        cross join reporting_periods
            period_record

        left join public.agent_commission
            commission_record
          on commission_record.agent_id =
                 v_user.id

         and lower(
             btrim(
                 commission_record.currency_code
             )
         ) =
                 currency_record.currency_code

         and commission_record.created_at >=
                 period_record.start_at

         and commission_record.created_at <
                 period_record.end_at

         /*
          * Preserve the original behavior where only
          * current-year rows were loaded before period
          * calculations.
          */
         and commission_record.created_at >=
                 v_start_of_year

         and commission_record.created_at <
                 v_start_of_next_year

        group by
            currency_record.currency_code,
            period_record.period_name,
            period_record.sort_order
    ),

    currency_summaries as (
        select
            period_total.currency_code,

            jsonb_object_agg(
                period_total.period_name,

                jsonb_build_object(
                    'total_amount',
                    trim_scale(
                        period_total.total_amount
                    )::text,

                    'total_fee',
                    trim_scale(
                        period_total.total_fee
                    )::text,

                    'total_commission',
                    trim_scale(
                        period_total.total_commission
                    )::text,

                    'paid',
                    trim_scale(
                        period_total.paid
                    )::text,

                    'not_paid',
                    trim_scale(
                        period_total.not_paid
                    )::text
                )

                order by
                    period_total.sort_order
            ) as summary

        from period_totals
            period_total

        group by
            period_total.currency_code
    )

    select coalesce(
        jsonb_object_agg(
            currency_summary.currency_code,
            currency_summary.summary
            order by
                currency_summary.currency_code
        ),
        '{}'::jsonb
    )
    into v_result
    from currency_summaries
        currency_summary;

    return v_result;
end;
$$;
ALTER FUNCTION "public"."fetch_my_agent_commission_summary"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_agent_dashboard_context"() RETURNS TABLE("wallet_address" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
    /*
     * Authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Return the authenticated active agent's
     * blockchain wallet address.
     */
    return query
    select
        user_record.wallet_address
    from public.users
        user_record
    join public.user_role
        role_record
      on role_record.id =
         user_record.role_id
    where user_record.id =
              auth.uid()::text

      and user_record.status =
              'active'::public."UserStatus"

      and lower(
          role_record.name::text
      ) =
              'agent'
    limit 1;

    if not found then
        raise exception using
            errcode = '42501',
            message = 'AGENT_NOT_AUTHORIZED';
    end if;
end;
$$;
ALTER FUNCTION "public"."fetch_my_agent_dashboard_context"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_balance_sheet"("p_as_of_date" "date", "p_currency_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;
    v_currency_code text;
    v_fiscal_year integer;
    v_currencies jsonb := '{}'::jsonb;
begin
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if not public.has_role(
        array[
            'accounts',
            'finance'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    if p_as_of_date is null then
        raise exception
            'AS_OF_DATE_REQUIRED';
    end if;

    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    v_currency_code :=
        lower(
            nullif(
                btrim(p_currency_code),
                ''
            )
        );

    select fiscal_period.fiscal_year
    into v_fiscal_year
    from public.fetch_fiscal_period(
        v_user.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    with balance_rows as (
        select
            financial_entry_record.gl_account_code,

            lower(
                financial_entry_record.currency_code
            ) as currency_code,

            coalesce(
                sum(
                    financial_entry_record.debit
                ),
                0
            ) as debit,

            coalesce(
                sum(
                    financial_entry_record.credit
                ),
                0
            ) as credit
        from public.financial_entry
            financial_entry_record
        where financial_entry_record.country_code =
              v_user.country_code

          and financial_entry_record.fiscal_year =
              v_fiscal_year

          and financial_entry_record.created_at <
              (
                  p_as_of_date +
                  interval '1 day'
              )

          and (
              (
                  v_currency_code is null
                  and lower(
                      financial_entry_record.currency_code
                  ) <> 'gold'
              )
              or
              (
                  v_currency_code is not null
                  and lower(
                      financial_entry_record.currency_code
                  ) =
                      v_currency_code
              )
          )
        group by
            financial_entry_record.gl_account_code,

            lower(
                financial_entry_record.currency_code
            )
    ),

    calculated_balances as (
        select
            balance_row.currency_code,

            balance_row.gl_account_code,

            coalesce(
                gl_account_record.description,
                ''
            ) as gl_account_name,

            lower(
                gl_account_record.type::text
            ) as account_type,

            case
                when lower(
                    gl_account_record.type::text
                ) in (
                    'asset',
                    'expense'
                )
                then
                    balance_row.debit -
                    balance_row.credit

                else
                    balance_row.credit -
                    balance_row.debit
            end as balance
        from balance_rows balance_row
        join public.gl_account
            gl_account_record
          on gl_account_record.code =
             balance_row.gl_account_code
    ),

    non_zero_balances as (
        select calculated_balance.*
        from calculated_balances
            calculated_balance
        where calculated_balance.balance <> 0
    ),

    currency_totals as (
        select
            calculated_balance.currency_code,

            coalesce(
                sum(
                    calculated_balance.balance
                ) filter (
                    where calculated_balance.account_type =
                          'asset'
                ),
                0
            ) as assets,

            coalesce(
                sum(
                    calculated_balance.balance
                ) filter (
                    where calculated_balance.account_type =
                          'liability'
                ),
                0
            ) as liabilities,

            coalesce(
                sum(
                    calculated_balance.balance
                ) filter (
                    where calculated_balance.account_type =
                          'equity'
                ),
                0
            ) as existing_equity,

            coalesce(
                sum(
                    calculated_balance.balance
                ) filter (
                    where calculated_balance.account_type =
                          'revenue'
                ),
                0
            ) as revenue,

            coalesce(
                sum(
                    calculated_balance.balance
                ) filter (
                    where calculated_balance.account_type =
                          'expense'
                ),
                0
            ) as expenses
        from non_zero_balances
            calculated_balance
        group by
            calculated_balance.currency_code
    ),

    statement_rows as (
        select
            calculated_balance.currency_code,
            calculated_balance.gl_account_code,
            calculated_balance.gl_account_name,
            calculated_balance.account_type,
            calculated_balance.balance
        from non_zero_balances
            calculated_balance
        where calculated_balance.account_type
              in (
                  'asset',
                  'liability',
                  'equity'
              )

        union all

        select
            currency_total.currency_code,
            '5003000'::text,
            'Current Year Profit'::text,
            'equity'::text,
            currency_total.revenue -
                currency_total.expenses
        from currency_totals
            currency_total
        where (
            currency_total.revenue -
            currency_total.expenses
        ) <> 0
    ),

    currency_results as (
        select
            currency_total.currency_code,

            coalesce(
                (
                    select jsonb_agg(
                        jsonb_build_object(
                            'gl_account_code',
                            statement_row.gl_account_code,

                            'gl_account_name',
                            statement_row.gl_account_name,

                            'balance',
                            statement_row.balance
                        )
                        order by
                            statement_row.gl_account_code
                    )
                    from statement_rows
                        statement_row
                    where statement_row.currency_code =
                          currency_total.currency_code
                      and statement_row.account_type =
                          'asset'
                ),
                '[]'::jsonb
            ) as asset_entries,

            coalesce(
                (
                    select jsonb_agg(
                        jsonb_build_object(
                            'gl_account_code',
                            statement_row.gl_account_code,

                            'gl_account_name',
                            statement_row.gl_account_name,

                            'balance',
                            statement_row.balance
                        )
                        order by
                            statement_row.gl_account_code
                    )
                    from statement_rows
                        statement_row
                    where statement_row.currency_code =
                          currency_total.currency_code
                      and statement_row.account_type =
                          'liability'
                ),
                '[]'::jsonb
            ) as liability_entries,

            coalesce(
                (
                    select jsonb_agg(
                        jsonb_build_object(
                            'gl_account_code',
                            statement_row.gl_account_code,

                            'gl_account_name',
                            statement_row.gl_account_name,

                            'balance',
                            statement_row.balance
                        )
                        order by
                            statement_row.gl_account_code
                    )
                    from statement_rows
                        statement_row
                    where statement_row.currency_code =
                          currency_total.currency_code
                      and statement_row.account_type =
                          'equity'
                ),
                '[]'::jsonb
            ) as equity_entries,

            currency_total.assets
                as total_assets,

            currency_total.liabilities
                as total_liabilities,

            currency_total.existing_equity +
                currency_total.revenue -
                currency_total.expenses
                as total_equity,

            currency_total.revenue,

            currency_total.expenses
        from currency_totals
            currency_total
    )

    select coalesce(
        jsonb_object_agg(
            currency_result.currency_code,

            jsonb_build_object(
                'assets',
                currency_result.asset_entries,

                'liabilities',
                currency_result.liability_entries,

                'equity',
                currency_result.equity_entries,

                'totals',
                jsonb_build_object(
                    'assets',
                    currency_result.total_assets,

                    'liabilities',
                    currency_result.total_liabilities,

                    'equity',
                    currency_result.total_equity,

                    'balanced',
                    abs(
                        currency_result.total_assets -
                        (
                            currency_result.total_liabilities +
                            currency_result.total_equity
                        )
                    ) < 0.0001
                ),

                'revenue',
                currency_result.revenue,

                'expenses',
                currency_result.expenses
            )
        ),
        '{}'::jsonb
    )
    into v_currencies
    from currency_results
        currency_result;

    return jsonb_build_object(
        'asOfDate',
        p_as_of_date,

        'currencies',
        v_currencies
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_balance_sheet"("p_as_of_date" "date", "p_currency_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_cash_deposit_context"("p_v" "text", "p_provider_id" "text") RETURNS TABLE("user_id" "text", "country_code" "text", "user_wallet_address" "text", "provider_id" "text", "provider_country_code" "text", "provider_wallet_address" "text", "version_time" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
    /*
     * Validate authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Customer-wallet transactions may be initiated by
     * customers, agents and vendors.
     */
    if not public.has_role(
        array[
            'customer'::public."Role",
            'agent'::public."Role",
            'vendor'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    if p_provider_id is null
       or btrim(p_provider_id) = ''
    then
        raise exception
            'PROVIDER_ID_MISSING';
    end if;

    if auth.uid()::text =
       btrim(p_provider_id)
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    /*
     * The cash provider must have either an agent
     * or merchant or vendor role.
     */
    if not public.user_has_role(
        btrim(p_provider_id),
        array[
            'agent'::public."Role",
            'merchant'::public."Role",
            'vendor'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'PROVIDER_NOT_AUTHORIZED';
    end if;

    /*
     * Return trusted information for both participants.
     */
    return query
    select
        user_record.id,
        user_record.country_code,
        user_record.wallet_address,

        provider_record.id,
        provider_record.country_code,
        provider_record.wallet_address,

        public.get_transaction_v(p_v)
    from public.users user_record
    join public.users provider_record
      on provider_record.id =
         btrim(p_provider_id)
    where user_record.id =
          auth.uid()::text
      and user_record.status =
          'active'::public."UserStatus"
      and provider_record.status =
          'active'::public."UserStatus"
      and user_record.country_code =
          provider_record.country_code
    limit 1;

    if not found then
        raise exception
            'CASH_DEPOSIT_CONTEXT_NOT_FOUND';
    end if;
end;
$$;
ALTER FUNCTION "public"."fetch_my_cash_deposit_context"("p_v" "text", "p_provider_id" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_cash_transfer_context"("p_v" "text") RETURNS TABLE("sender_id" "text", "country_code" "text", "wallet_address" "text", "version_time" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
    /*
     * Confirm that the request contains a valid
     * authenticated Supabase user.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Cash transfers may be performed by users whose
     * main role is customer, agent or vendor.
     *
     * Each role performs the transaction through its
     * customer-owned wallet.
     */
    if not public.has_role(
        array[
            'customer'::public."Role",
            'agent'::public."Role",
            'vendor'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Return trusted sender information derived from
     * auth.uid(). Nothing here comes from the client
     * request body.
     */
    return query
    select
        user_record.id,
        user_record.country_code,
        user_record.wallet_address,
        public.get_transaction_v(p_v)
    from public.users user_record
    where user_record.id =
          auth.uid()::text
      and user_record.status =
          'active'::public."UserStatus"
    limit 1;

    if not found then
        raise exception using
            errcode = '42501',
            message = 'USER_NOT_AUTHORIZED';
    end if;
end;
$$;
ALTER FUNCTION "public"."fetch_my_cash_transfer_context"("p_v" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_cash_transfer_fee_configuration"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;
    v_currency record;
    v_rate_to_usd numeric;
    v_points_per_usd bigint;
    v_loyalty_redemption_enabled boolean := false;
    v_currencies jsonb := '[]'::jsonb;
begin
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    select user_record.*
    into v_user
    from public.users user_record
    join public.user_role role_record
      on role_record.id = user_record.role_id
    where user_record.id = auth.uid()::text
      and user_record.status =
          'active'::public."UserStatus"
      and lower(role_record.name::text) in (
          'customer',
          'agent',
          'vendor'
      )
    limit 1;

    if not found then
        raise exception using
            errcode = '42501',
            message = 'CASH_TRANSFER_NOT_AUTHORIZED';
    end if;

    select exists (
        select 1
        from public.loyalty_account account_record
        where account_record.user_id = v_user.id
          and account_record.is_active = true
    )
    into v_loyalty_redemption_enabled;

    for v_currency in
        select lower(supported_record.currency_code) as currency_code
        from public.country_currencies country_currency_record
        join public.supported_currency supported_record
          on lower(supported_record.currency_code) =
             lower(country_currency_record.currency_code)
        where country_currency_record.country_code =
              v_user.country_code
          and country_currency_record.is_active = true
          and supported_record.is_active = true
          and supported_record.currency_category =
              'fiat'::public."CurrencyCategory"
        order by lower(supported_record.currency_code)
    loop
        if v_currency.currency_code = 'usd' then
            v_rate_to_usd := 1;
        else
            select rate_record.rate_to_usd
            into v_rate_to_usd
            from public.current_rates rate_record
            where lower(btrim(rate_record.code)) =
                  v_currency.currency_code
            limit 1;

            if not found
               or v_rate_to_usd is null
               or v_rate_to_usd <= 0
            then
                raise exception
                    'CURRENT_RATE_NOT_FOUND_%',
                    upper(v_currency.currency_code);
            end if;
        end if;

        v_points_per_usd := null;

        select config_record.points_per_usd
        into v_points_per_usd
        from public.loyalty_redemption_config config_record
        where config_record.transaction_type =
              'cash_transfer'::public."TransactionType"
          and config_record.is_active = true
          and (
              config_record.country_code is null
              or config_record.country_code =
                 lower(v_user.country_code)
          )
          and (
              config_record.currency_code is null
              or config_record.currency_code =
                 v_currency.currency_code
          )
          and (
              config_record.valid_from is null
              or config_record.valid_from <= now()
          )
          and (
              config_record.valid_until is null
              or config_record.valid_until > now()
          )
        order by
            case
                when config_record.country_code is not null
                    then 0
                else 1
            end,
            case
                when config_record.currency_code is not null
                    then 0
                else 1
            end,
            config_record.priority,
            config_record.id
        limit 1;

        v_currencies :=
            v_currencies ||
            jsonb_build_array(
                jsonb_build_object(
                    'currency_code',
                    v_currency.currency_code,
                    'rate_to_usd',
                    trim_scale(v_rate_to_usd)::text,
                    'points_per_usd',
                    v_points_per_usd,
                    'points_payment_available',
                    v_points_per_usd is not null
                )
            );
    end loop;

    return jsonb_build_object(
        'country_code',
        lower(v_user.country_code),
        'loyalty_redemption_enabled',
        v_loyalty_redemption_enabled,
        'currencies',
        v_currencies
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_cash_transfer_fee_configuration"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_cash_withdrawal_context"("p_v" "text", "p_user_id" "text") RETURNS TABLE("agent_id" "text", "country_code" "text", "agent_wallet_address" "text", "user_id" "text", "user_country_code" "text", "user_wallet_address" "text", "version_time" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
    /*
     * Validate authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Cash withdrawal remains on transaction version v3.
     */
    if p_v is distinct from 'v3' then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    /*
     * Only agents, vendors and merchants may initiate a
     * cash withdrawal.
     */
    if not public.has_role(
        array[
            'agent'::public."Role",
            'merchant'::public."Role",
            'vendor'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    if p_user_id is null
       or btrim(p_user_id) = ''
    then
        raise exception
            'USER_ID_MISSING';
    end if;

    /*
     * The agent cannot withdraw from their own
     * customer wallet through this transaction.
     */
    if auth.uid()::text =
       btrim(p_user_id)
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    /*
     * The withdrawing user must have a role that owns
     * a customer wallet.
     */
    if not public.user_has_role(
        btrim(p_user_id),
        array[
            'customer'::public."Role",
            'agent'::public."Role",
            'vendor'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'USER_NOT_AUTHORIZED';
    end if;

    /*
     * Return trusted information for both participants.
     *
     * The agent is derived from auth.uid().
     * The withdrawing user comes from transaction.s.
     */
    return query
    select
        agent_record.id,
        agent_record.country_code,
        agent_record.wallet_address,

        user_record.id,
        user_record.country_code,
        user_record.wallet_address,

        public.get_transaction_v(p_v)
    from public.users agent_record
    join public.users user_record
      on user_record.id =
         btrim(p_user_id)
    where agent_record.id =
          auth.uid()::text
      and agent_record.status =
          'active'::public."UserStatus"
      and user_record.status =
          'active'::public."UserStatus"
      and agent_record.country_code =
          user_record.country_code
    limit 1;

    if not found then
        raise exception
            'CASH_WITHDRAWAL_CONTEXT_NOT_FOUND';
    end if;
end;
$$;
ALTER FUNCTION "public"."fetch_my_cash_withdrawal_context"("p_v" "text", "p_user_id" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_credit_agent_balances"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_merchant record;
    v_account record;

    v_balances jsonb;
    v_credit_agents jsonb :=
        '[]'::jsonb;

    v_rate numeric;
    v_cash_holding_usd numeric;
    v_receivable_usd numeric;

    v_total_entries integer := 0;
begin
    /*
     * Authentication and authorization.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'accounts'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Fetch merchants in the Accounts user's country
     * who have at least one non-zero credit-agent balance.
     *
     * Inactive credit-agent accounts are included because
     * outstanding balances must remain visible.
     */
    for v_merchant in
        select
            merchant_record.id as user_id,
            merchant_record.email,
            merchant_record.phone,
            merchant_record.first_name,
            merchant_record.surname,
            merchant_record.address,
            merchant_record.country_code,
            merchant_record.status

        from public.users merchant_record

        join public.user_role role_record
          on role_record.id =
             merchant_record.role_id

        where lower(
            role_record.name::text
        ) = 'merchant'

          and merchant_record.country_code = (
              select accounts_record.country_code
              from public.users accounts_record
              where accounts_record.id =
                    auth.uid()::text
              limit 1
          )

          and exists (
              select 1
              from public.credit_agent_account
                  account_record
              where account_record.merchant_id =
                    merchant_record.id

                and account_record.country_code =
                    merchant_record.country_code

                and (
                    coalesce(
                        account_record.receivable_balance,
                        0
                    ) <> 0

                    or

                    coalesce(
                        account_record.cash_holding_balance,
                        0
                    ) <> 0
                )
          )

        order by
            merchant_record.first_name,
            merchant_record.surname,
            merchant_record.email
    loop
        v_balances :=
            '{}'::jsonb;

        /*
         * Build the merchant balances by currency.
         *
         * Only currencies with a non-zero balance are
         * returned.
         */
        for v_account in
            select
                lower(
                    btrim(
                        account_record.currency_code
                    )
                ) as currency_code,

                coalesce(
                    account_record.cash_holding_balance,
                    0
                )::numeric as cash_holding_balance,

                coalesce(
                    account_record.receivable_balance,
                    0
                )::numeric as receivable_balance,

                account_record.is_active

            from public.credit_agent_account
                account_record

            where account_record.merchant_id =
                  v_merchant.user_id

              and account_record.country_code =
                  v_merchant.country_code

              and (
                  coalesce(
                      account_record.receivable_balance,
                      0
                  ) <> 0

                  or

                  coalesce(
                      account_record.cash_holding_balance,
                      0
                  ) <> 0
              )

            order by
                lower(
                    btrim(
                        account_record.currency_code
                    )
                )
        loop
            /*
             * Convert balances to USD using the same
             * dashboard conversion rule.
             */
            if v_account.currency_code = 'usd' then
                v_cash_holding_usd :=
                    v_account.cash_holding_balance;

                v_receivable_usd :=
                    v_account.receivable_balance;
            else
                select rate_record.rate_to_usd
                into v_rate
                from public.current_rates rate_record
                where lower(
                    btrim(
                        rate_record.code
                    )
                ) =
                    v_account.currency_code
                limit 1;

                if not found
                   or v_rate is null
                   or v_rate = 0
                then
                    raise exception
                        'MISSING_RATE_%',
                        upper(
                            v_account.currency_code
                        );
                end if;

                v_cash_holding_usd :=
                    v_account.cash_holding_balance /
                    v_rate;

                v_receivable_usd :=
                    v_account.receivable_balance /
                    v_rate;
            end if;

            v_balances :=
                v_balances ||
                jsonb_build_object(
                    v_account.currency_code,

                    jsonb_build_object(
                        'cashOwed',
                        jsonb_build_object(
                            'balance',
                            trim_scale(
                                v_account.cash_holding_balance
                            )::text,

                            'usd_value',
                            to_char(
                                round(
                                    v_cash_holding_usd,
                                    2
                                ),
                                'FM999999999999999999999999990.00'
                            )
                        ),

                        'receivableBalance',
                        jsonb_build_object(
                            'balance',
                            trim_scale(
                                v_account.receivable_balance
                            )::text,

                            'usd_value',
                            to_char(
                                round(
                                    v_receivable_usd,
                                    2
                                ),
                                'FM999999999999999999999999990.00'
                            )
                        ),

                        'isActive',
                        v_account.is_active
                    )
                );
        end loop;

        v_credit_agents :=
            v_credit_agents ||
            jsonb_build_array(
                jsonb_build_object(
                    'user_id',
                    v_merchant.user_id,

                    'email',
                    v_merchant.email,

                    'phone',
                    v_merchant.phone,

                    'first_name',
                    v_merchant.first_name,

                    'surname',
                    v_merchant.surname,

                    'address',
                    v_merchant.address,

                    'country_code',
                    v_merchant.country_code,

                    'status',
                    v_merchant.status,

                    'balances',
                    v_balances
                )
            );

        v_total_entries :=
            v_total_entries + 1;
    end loop;

    return jsonb_build_object(
        'creditAgents',
        v_credit_agents,

        'totalEntries',
        v_total_entries
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_credit_agent_balances"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_credit_agent_balances"("p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_merchant record;
    v_account record;

    v_balances jsonb;
    v_credit_agents jsonb := '[]'::jsonb;

    v_rate numeric;
    v_cash_holding_usd numeric;
    v_receivable_usd numeric;

    v_page integer;
    v_page_size integer;
    v_offset integer;

    v_total_entries integer := 0;
    v_total_pages integer := 1;

    v_has_previous boolean := false;
    v_has_next boolean := false;

    v_country_code text;
begin
    /*
     * Authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Authorization.
     */
    if not public.has_role(
        array[
            'accounts'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Normalize pagination.
     */
    v_page := greatest(
        coalesce(p_page, 1),
        1
    );

    v_page_size := greatest(
        coalesce(p_page_size, 50),
        1
    );

    /*
     * Protect against excessively large requests.
     */
    v_page_size := least(
        v_page_size,
        100
    );

    v_offset :=
        (v_page - 1) * v_page_size;

    /*
     * Accounts user's country.
     */
    select
        accounts_record.country_code
    into
        v_country_code
    from public.users accounts_record
    where accounts_record.id =
          auth.uid()::text
    limit 1;

    if v_country_code is null then
        raise exception
            'USER_COUNTRY_NOT_FOUND';
    end if;

    /*
     * Count all merchants matching this report
     * before pagination.
     *
     * Inactive credit-agent accounts are included
     * if they still have outstanding balances.
     */
    select
        count(*)
    into
        v_total_entries
    from public.users merchant_record

    join public.user_role role_record
      on role_record.id =
         merchant_record.role_id

    where lower(
        role_record.name::text
    ) = 'merchant'

      and merchant_record.country_code =
          v_country_code

      and exists (
          select 1
          from public.credit_agent_account
              account_record
          where account_record.merchant_id =
                merchant_record.id

            and account_record.country_code =
                merchant_record.country_code

            and (
                coalesce(
                    account_record.receivable_balance,
                    0
                ) <> 0

                or

                coalesce(
                    account_record.cash_holding_balance,
                    0
                ) <> 0
            )
      );

    /*
     * Calculate pagination metadata.
     */
    if v_total_entries > 0 then
        v_total_pages :=
            ceil(
                v_total_entries::numeric /
                v_page_size::numeric
            )::integer;
    else
        v_total_pages := 1;
    end if;

    v_has_previous :=
        v_page > 1;

    v_has_next :=
        v_page < v_total_pages;

    /*
     * Fetch only the requested page.
     */
    for v_merchant in
        select
            merchant_record.id as user_id,
            merchant_record.email,
            merchant_record.phone,
            merchant_record.first_name,
            merchant_record.surname,
            merchant_record.residential_address,
            merchant_record.country_code,
            merchant_record.status

        from public.users merchant_record

        join public.user_role role_record
          on role_record.id =
             merchant_record.role_id

        where lower(
            role_record.name::text
        ) = 'merchant'

          and merchant_record.country_code =
              v_country_code

          and exists (
              select 1
              from public.credit_agent_account
                  account_record
              where account_record.merchant_id =
                    merchant_record.id

                and account_record.country_code =
                    merchant_record.country_code

                and (
                    coalesce(
                        account_record.receivable_balance,
                        0
                    ) <> 0

                    or

                    coalesce(
                        account_record.cash_holding_balance,
                        0
                    ) <> 0
                )
          )

        /*
         * Stable ordering is important for pagination.
         * user_id is the final tie breaker.
         */
        order by
            merchant_record.first_name nulls last,
            merchant_record.surname nulls last,
            merchant_record.email nulls last,
            merchant_record.id

        limit v_page_size
        offset v_offset
    loop
        v_balances :=
            '{}'::jsonb;

        /*
         * Build balances for each currency.
         *
         * Only currencies with a non-zero balance
         * are returned.
         */
        for v_account in
            select
                lower(
                    btrim(
                        account_record.currency_code
                    )
                ) as currency_code,

                coalesce(
                    account_record.cash_holding_balance,
                    0
                )::numeric as cash_holding_balance,

                coalesce(
                    account_record.receivable_balance,
                    0
                )::numeric as receivable_balance,

                account_record.is_active

            from public.credit_agent_account
                account_record

            where account_record.merchant_id =
                  v_merchant.user_id

              and account_record.country_code =
                  v_merchant.country_code

              and (
                  coalesce(
                      account_record.receivable_balance,
                      0
                  ) <> 0

                  or

                  coalesce(
                      account_record.cash_holding_balance,
                      0
                  ) <> 0
              )

            order by
                lower(
                    btrim(
                        account_record.currency_code
                    )
                )
        loop
            /*
             * Convert balances to USD using the
             * existing dashboard conversion rule.
             */
            if v_account.currency_code = 'usd' then
                v_cash_holding_usd :=
                    v_account.cash_holding_balance;

                v_receivable_usd :=
                    v_account.receivable_balance;
            else
                select
                    rate_record.rate_to_usd
                into
                    v_rate
                from public.current_rates rate_record
                where lower(
                    btrim(
                        rate_record.code
                    )
                ) =
                    v_account.currency_code
                limit 1;

                if not found
                   or v_rate is null
                   or v_rate = 0
                then
                    raise exception
                        'MISSING_RATE_%',
                        upper(
                            v_account.currency_code
                        );
                end if;

                v_cash_holding_usd :=
                    v_account.cash_holding_balance /
                    v_rate;

                v_receivable_usd :=
                    v_account.receivable_balance /
                    v_rate;
            end if;

            v_balances :=
                v_balances ||
                jsonb_build_object(
                    v_account.currency_code,

                    jsonb_build_object(
                        'cashOwed',
                        jsonb_build_object(
                            'balance',
                            trim_scale(
                                v_account.cash_holding_balance
                            )::text,

                            'usd_value',
                            to_char(
                                round(
                                    v_cash_holding_usd,
                                    2
                                ),
                                'FM999999999999999999999999990.00'
                            )
                        ),

                        'receivableBalance',
                        jsonb_build_object(
                            'balance',
                            trim_scale(
                                v_account.receivable_balance
                            )::text,

                            'usd_value',
                            to_char(
                                round(
                                    v_receivable_usd,
                                    2
                                ),
                                'FM999999999999999999999999990.00'
                            )
                        ),

                        'isActive',
                        v_account.is_active
                    )
                );
        end loop;

        /*
         * Add merchant to response.
         */
        v_credit_agents :=
            v_credit_agents ||
            jsonb_build_array(
                jsonb_build_object(
                    'user_id',
                    v_merchant.user_id,

                    'email',
                    v_merchant.email,

                    'phone',
                    v_merchant.phone,

                    'first_name',
                    v_merchant.first_name,

                    'surname',
                    v_merchant.surname,

                    'residential_address',
                    v_merchant.residential_address,

                    'country_code',
                    v_merchant.country_code,

                    'status',
                    v_merchant.status,

                    'balances',
                    v_balances
                )
            );
    end loop;

    /*
     * Final report response.
     */
    return jsonb_build_object(
        'creditAgents',
        v_credit_agents,

        'pagination',
        jsonb_build_object(
            'page',
            v_page,

            'page_size',
            v_page_size,

            'total_entries',
            v_total_entries,

            'total_pages',
            v_total_pages,

            'has_previous',
            v_has_previous,

            'has_next',
            v_has_next
        )
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_credit_agent_balances"("p_page" integer, "p_page_size" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_credit_agent_cash_settlement_context"("p_v" "text", "p_accounts_id" "text", "p_currency_code" "text") RETURNS TABLE("merchant_id" "text", "merchant_country_code" "text", "merchant_wallet_address" "text", "accounts_id" "text", "accounts_country_code" "text", "accounts_wallet_address" "text", "treasury_id" "text", "version_time" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_accounts_id text;
    v_currency_code text;
begin
    /*
     * Validate authentication.
     *
     * The merchant scans the accounts-generated
     * transaction, signs approval and submits it.
     */
    if auth.uid() is null then
        raise exception using
            errcode =
                '42501',

            message =
                'UNAUTHORIZED';
    end if;

    /*
     * Only an active merchant may submit the settlement
     * approval.
     */
    if not public.has_role(
        array[
            'merchant'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode =
                '42501',

            message =
                'FORBIDDEN';
    end if;

    if p_v is null
       or btrim(p_v) = ''
    then
        raise exception
            'TRANSACTION_VERSION_REQUIRED';
    end if;

    v_accounts_id :=
        nullif(
            btrim(p_accounts_id),
            ''
        );

    if v_accounts_id is null then
        raise exception
            'ACCOUNTS_ID_MISSING';
    end if;

    if auth.uid()::text =
       v_accounts_id
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    v_currency_code :=
        lower(
            nullif(
                btrim(p_currency_code),
                ''
            )
        );

    if v_currency_code is null then
        raise exception
            'CURRENCY_REQUIRED';
    end if;

    if v_currency_code = 'gold' then
        raise exception
            'INVALID_SETTLEMENT_CURRENCY';
    end if;

    /*
     * transaction.s must identify an accounts user.
     */
    if not public.user_has_role(
        v_accounts_id,
        array[
            'accounts'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode =
                '42501',

            message =
                'ACCOUNTS_USER_NOT_AUTHORIZED';
    end if;

    /*
     * Return trusted context:
     *
     * - authenticated merchant;
     * - accounts user who created TransactionData;
     * - country treasury resolved from merchant country;
     * - configured transaction-version lifetime.
     *
     * The credit_agent_account join confirms that the
     * merchant is an active credit agent for the signed
     * fiat currency.
     */
    return query
    select
        merchant_record.id,
        merchant_record.country_code,
        merchant_record.wallet_address,

        accounts_record.id,
        accounts_record.country_code,
        accounts_record.wallet_address,

        treasury_record.id,

        public.get_transaction_v(
            p_v
        )

    from public.users
        merchant_record

    join public.users
        accounts_record
      on accounts_record.id =
         v_accounts_id

    join public.credit_agent_account
        credit_account_record
      on credit_account_record.merchant_id =
         merchant_record.id

     and credit_account_record.country_code =
         merchant_record.country_code

     and lower(
         btrim(
             credit_account_record.currency_code
         )
     ) =
         v_currency_code

     and credit_account_record.is_active =
         true

    cross join lateral
        public.fetch_country_treasury(
            merchant_record.country_code
        ) as treasury_record

    where merchant_record.id =
          auth.uid()::text

      and merchant_record.status =
          'active'::public."UserStatus"

      and accounts_record.status =
          'active'::public."UserStatus"

      and merchant_record.country_code =
          accounts_record.country_code

    limit 1;

    if not found then
        raise exception
            'CREDIT_AGENT_CASH_SETTLEMENT_CONTEXT_NOT_FOUND';
    end if;
end;
$$;
ALTER FUNCTION "public"."fetch_my_credit_agent_cash_settlement_context"("p_v" "text", "p_accounts_id" "text", "p_currency_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_credit_agent_drilldown"("p_merchant_id" "text", "p_currency_code" "text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_accounts public.users%rowtype;
    v_merchant public.users%rowtype;
    v_account public.credit_agent_account%rowtype;
    v_last_settlement public.credit_agent_entry%rowtype;

    v_currency_code text;
    v_page integer;
    v_page_size integer;
    v_offset integer;

    v_opening_receivable numeric := 0;
    v_opening_cash_holding numeric := 0;

    v_total_entries integer := 0;
    v_total_pages integer := 1;

    v_entries jsonb := '[]'::jsonb;
begin
    /*
     * Authentication and authorization.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'accounts'::public."Role"
        ]::public."Role"[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Validate input.
     */
    if nullif(
        btrim(p_merchant_id),
        ''
    ) is null
    then
        raise exception
            'MERCHANT_ID_REQUIRED';
    end if;

    v_currency_code :=
        lower(
            nullif(
                btrim(p_currency_code),
                ''
            )
        );

    if v_currency_code is null then
        raise exception
            'CURRENCY_REQUIRED';
    end if;

    v_page :=
        coalesce(
            p_page,
            1
        );

    v_page_size :=
        coalesce(
            p_page_size,
            50
        );

    if v_page < 1 then
        raise exception
            'INVALID_PAGE';
    end if;

    if v_page_size < 1
       or v_page_size > 100
    then
        raise exception
            'INVALID_PAGE_SIZE';
    end if;

    v_offset :=
        (v_page - 1) *
        v_page_size;

    /*
     * Resolve the authenticated Accounts user.
     */
    select accounts_record.*
    into v_accounts
    from public.users accounts_record
    where accounts_record.id =
          auth.uid()::text

      and accounts_record.status =
          'active'::public."UserStatus"
    limit 1;

    if not found then
        raise exception
            'ACCOUNTS_USER_NOT_FOUND';
    end if;

    /*
     * Resolve the merchant in the Accounts user's country.
     */
    select merchant_record.*
    into v_merchant
    from public.users merchant_record
    join public.user_role role_record
      on role_record.id =
         merchant_record.role_id
    where merchant_record.id =
          btrim(p_merchant_id)

      and merchant_record.country_code =
          v_accounts.country_code

      and lower(
          role_record.name::text
      ) = 'merchant'
    limit 1;

    if not found then
        raise exception
            'MERCHANT_NOT_FOUND';
    end if;

    /*
     * Fetch the selected currency account.
     *
     * Inactive accounts remain available for reporting.
     */
    select account_record.*
    into v_account
    from public.credit_agent_account account_record
    where account_record.merchant_id =
          v_merchant.id

      and account_record.country_code =
          v_merchant.country_code

      and lower(
          btrim(
              account_record.currency_code
          )
      ) = v_currency_code
    limit 1;

    if not found then
        raise exception
            'CREDIT_AGENT_ACCOUNT_NOT_FOUND';
    end if;

    /*
     * Find the most recent cash-settlement checkpoint for
     * this merchant and currency.
     */
    select entry_record.*
    into v_last_settlement
    from public.credit_agent_entry entry_record
    where entry_record.credit_agent_account_id =
          v_account.id

      and entry_record.transaction_type =
          'credit_agent_cash_settlement'::public."TransactionType"
    order by
        entry_record.created_at desc,
        entry_record.id desc
    limit 1;

    if found then
        /*
         * The balances immediately after settlement become
         * the opening position for this drilldown.
         */
        v_opening_receivable :=
            coalesce(
                v_last_settlement.receivable_balance_after,
                0
            );

        v_opening_cash_holding :=
            coalesce(
                v_last_settlement.cash_holding_balance_after,
                0
            );
    else
        /*
         * No settlement exists. Use the balances before the
         * first credit-agent entry as the opening position.
         */
        select
            coalesce(
                first_entry.receivable_balance_before,
                0
            ),

            coalesce(
                first_entry.cash_holding_balance_before,
                0
            )
        into
            v_opening_receivable,
            v_opening_cash_holding
        from public.credit_agent_entry first_entry
        where first_entry.credit_agent_account_id =
              v_account.id
        order by
            first_entry.created_at asc,
            first_entry.id asc
        limit 1;

        if not found then
            v_opening_receivable := 0;
            v_opening_cash_holding := 0;
        end if;
    end if;

    /*
     * Count entries after the most recent settlement.
     *
     * When there is no settlement, all account entries are
     * included.
     */
    select count(*)::integer
    into v_total_entries
    from public.credit_agent_entry entry_record
    where entry_record.credit_agent_account_id =
          v_account.id

      and (
          v_last_settlement.id is null

          or

          (
              entry_record.created_at,
              entry_record.id
          ) >
          (
              v_last_settlement.created_at,
              v_last_settlement.id
          )
      );

    v_total_pages :=
        greatest(
            1,
            ceil(
                v_total_entries::numeric /
                v_page_size
            )::integer
        );

    /*
     * Return chronological entries so each stored balance
     * reads naturally as a running balance.
     */
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id',
                entry_record.id::text,

                'document_number',
                entry_record.document_number,

                'transaction_type',
                entry_record.transaction_type,

                'fiscal_year',
                entry_record.fiscal_year,

                'period',
                entry_record.period,

                'currency_code',
                lower(
                    entry_record.currency_code
                ),

                'debit_receivable',
                trim_scale(
                    entry_record.debit_receivable
                )::text,

                'credit_receivable',
                trim_scale(
                    entry_record.credit_receivable
                )::text,

                'debit_cash_holding',
                trim_scale(
                    entry_record.debit_cash_holding
                )::text,

                'credit_cash_holding',
                trim_scale(
                    entry_record.credit_cash_holding
                )::text,

                'receivable_balance_before',
                trim_scale(
                    entry_record.receivable_balance_before
                )::text,

                'receivable_running_balance',
                trim_scale(
                    entry_record.receivable_balance_after
                )::text,

                'cash_holding_balance_before',
                trim_scale(
                    entry_record.cash_holding_balance_before
                )::text,

                'cash_holding_running_balance',
                trim_scale(
                    entry_record.cash_holding_balance_after
                )::text,

                'created_by',
                entry_record.created_by,

                'created_at',
                entry_record.created_at
            )
            order by
                entry_record.created_at asc,
                entry_record.id asc
        ),
        '[]'::jsonb
    )
    into v_entries
    from (
        select account_entry.*
        from public.credit_agent_entry account_entry
        where account_entry.credit_agent_account_id =
              v_account.id

          and (
              v_last_settlement.id is null

              or

              (
                  account_entry.created_at,
                  account_entry.id
              ) >
              (
                  v_last_settlement.created_at,
                  v_last_settlement.id
              )
          )

        order by
            account_entry.created_at asc,
            account_entry.id asc

        offset v_offset
        limit v_page_size
    ) entry_record;

    return jsonb_build_object(
        'merchant',
        jsonb_build_object(
            'user_id',
            v_merchant.id,

            'email',
            v_merchant.email,

            'phone',
            v_merchant.phone,

            'first_name',
            v_merchant.first_name,

            'surname',
            v_merchant.surname,

            'address',
            v_merchant.residential_address,

            'country_code',
            v_merchant.country_code
        ),

        'account',
        jsonb_build_object(
            'credit_agent_account_id',
            v_account.id::text,

            'currency_code',
            v_currency_code,

            'is_active',
            v_account.is_active,

            'current_receivable_balance',
            trim_scale(
                v_account.receivable_balance
            )::text,

            'current_cash_holding_balance',
            trim_scale(
                v_account.cash_holding_balance
            )::text
        ),

        'opening',
        jsonb_build_object(
            'receivable_balance',
            trim_scale(
                v_opening_receivable
            )::text,

            'cash_holding_balance',
            trim_scale(
                v_opening_cash_holding
            )::text,

            'last_settlement_document_number',
            v_last_settlement.document_number,

            'last_settlement_at',
            v_last_settlement.created_at
        ),

        'entries',
        v_entries,

        'pagination',
        jsonb_build_object(
            'page',
            v_page,

            'page_size',
            v_page_size,

            'total_entries',
            v_total_entries,

            'total_pages',
            v_total_pages,

            'has_previous',
            v_page > 1,

            'has_next',
            v_page < v_total_pages
        )
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_credit_agent_drilldown"("p_merchant_id" "text", "p_currency_code" "text", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_current_gl_balances"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_fiscal_year integer;
    v_period integer;

    v_data jsonb :=
        '{}'::jsonb;

    v_totals jsonb :=
        '{}'::jsonb;
begin
    /*
     * Authenticate and authorize.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if not public.has_role(
        array[
            'finance',
            'accounts'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Fetch trusted user context.
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Fetch current fiscal period.
     */
    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_user.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    with current_snapshots as (
        select
            snapshot_record.gl_account_code,

            lower(
                snapshot_record.currency_code
            ) as currency_code,

            snapshot_record.opening_balance,
            snapshot_record.debit,
            snapshot_record.credit,
            snapshot_record.closing_balance
        from public.gl_balance_snapshot
            snapshot_record
        where snapshot_record.country_code =
              v_user.country_code

          and snapshot_record.fiscal_year =
              v_fiscal_year

          and snapshot_record.period =
              v_period

          and lower(
              snapshot_record.currency_code
          ) <> 'gold'
    ),

    /*
     * Include currencies that have either a current snapshot
     * or an earlier snapshot with a balance carried forward.
     */
    available_currencies as (
        select distinct
            lower(
                snapshot_record.currency_code
            ) as currency_code
        from public.gl_balance_snapshot
            snapshot_record
        where snapshot_record.country_code =
              v_user.country_code

          and lower(
              snapshot_record.currency_code
          ) <> 'gold'

          and (
              snapshot_record.fiscal_year <
                  v_fiscal_year

              or (
                  snapshot_record.fiscal_year =
                      v_fiscal_year

                  and snapshot_record.period <=
                      v_period
              )
          )
    ),

    /*
     * Find the latest snapshot before the current period for
     * every GL account and currency.
     */
    previous_snapshots as (
        select distinct on (
            snapshot_record.gl_account_code,
            lower(
                snapshot_record.currency_code
            )
        )
            snapshot_record.gl_account_code,

            lower(
                snapshot_record.currency_code
            ) as currency_code,

            snapshot_record.closing_balance
        from public.gl_balance_snapshot
            snapshot_record
        where snapshot_record.country_code =
              v_user.country_code

          and lower(
              snapshot_record.currency_code
          ) <> 'gold'

          and (
              snapshot_record.fiscal_year <
                  v_fiscal_year

              or (
                  snapshot_record.fiscal_year =
                      v_fiscal_year

                  and snapshot_record.period <
                      v_period
              )
          )
        order by
            snapshot_record.gl_account_code,

            lower(
                snapshot_record.currency_code
            ),

            snapshot_record.fiscal_year desc,

            snapshot_record.period desc
    ),

    /*
     * GL accounts of type token are excluded from the
     * standard fiat GL balance report.
     */
    display_gl_accounts as (
        select
            gl_account_record.code,
            coalesce(
                gl_account_record.description,
                ''
            ) as description,

            lower(
                gl_account_record.type::text
            ) as gl_type
        from public.gl_account
            gl_account_record
        where lower(
            gl_account_record.type::text
        ) <> 'token'

          and lower(
              gl_account_record.type::text
          ) in (
              'asset',
              'liability',
              'equity',
              'revenue',
              'expense'
          )
    ),

    base_rows as (
        select
            available_currency.currency_code,

            gl_account_record.code
                as gl_account_code,

            gl_account_record.description,

            gl_account_record.gl_type,

            case
                when current_snapshot.gl_account_code
                     is null
                then
                    coalesce(
                        previous_snapshot.closing_balance,
                        0
                    )

                when coalesce(
                    current_snapshot.opening_balance,
                    0
                ) = 0
                then
                    coalesce(
                        previous_snapshot.closing_balance,
                        0
                    )

                else
                    current_snapshot.opening_balance
            end as opening_balance,

            coalesce(
                current_snapshot.debit,
                0
            ) as debit,

            coalesce(
                current_snapshot.credit,
                0
            ) as credit,

            coalesce(
                current_snapshot.closing_balance,
                0
            ) as stored_closing_balance,

            current_snapshot.gl_account_code
                is not null
                as current_snapshot_exists
        from available_currencies
            available_currency
        cross join display_gl_accounts
            gl_account_record
        left join current_snapshots
            current_snapshot
          on current_snapshot.currency_code =
             available_currency.currency_code

         and current_snapshot.gl_account_code =
             gl_account_record.code
        left join previous_snapshots
            previous_snapshot
          on previous_snapshot.currency_code =
             available_currency.currency_code

         and previous_snapshot.gl_account_code =
             gl_account_record.code
    ),

    enriched_rows as (
        select
            base_row.currency_code
                as currency,

            base_row.gl_account_code,

            base_row.description,

            base_row.gl_type,

            base_row.opening_balance,

            base_row.debit,

            base_row.credit,

            case
                when not base_row.current_snapshot_exists
                then
                    base_row.opening_balance +
                    base_row.debit -
                    base_row.credit

                when base_row.stored_closing_balance = 0
                then
                    base_row.opening_balance +
                    base_row.debit -
                    base_row.credit

                else
                    base_row.stored_closing_balance
            end as closing_balance
        from base_rows
            base_row
    ),

    currency_results as (
        select
            enriched_row.currency,

            jsonb_build_object(
                'asset',
                coalesce(
                    jsonb_agg(
                        jsonb_build_object(
                            'currency',
                            enriched_row.currency,

                            'gl_account_code',
                            enriched_row.gl_account_code,

                            'description',
                            enriched_row.description,

                            'gl_type',
                            enriched_row.gl_type,

                            'opening_balance',
                            enriched_row.opening_balance::text,

                            'debit',
                            enriched_row.debit::text,

                            'credit',
                            enriched_row.credit::text,

                            'closing_balance',
                            enriched_row.closing_balance::text
                        )
                        order by
                            enriched_row.gl_account_code
                    ) filter (
                        where enriched_row.gl_type =
                              'asset'
                    ),
                    '[]'::jsonb
                ),

                'liability',
                coalesce(
                    jsonb_agg(
                        jsonb_build_object(
                            'currency',
                            enriched_row.currency,

                            'gl_account_code',
                            enriched_row.gl_account_code,

                            'description',
                            enriched_row.description,

                            'gl_type',
                            enriched_row.gl_type,

                            'opening_balance',
                            enriched_row.opening_balance::text,

                            'debit',
                            enriched_row.debit::text,

                            'credit',
                            enriched_row.credit::text,

                            'closing_balance',
                            enriched_row.closing_balance::text
                        )
                        order by
                            enriched_row.gl_account_code
                    ) filter (
                        where enriched_row.gl_type =
                              'liability'
                    ),
                    '[]'::jsonb
                ),

                'equity',
                coalesce(
                    jsonb_agg(
                        jsonb_build_object(
                            'currency',
                            enriched_row.currency,

                            'gl_account_code',
                            enriched_row.gl_account_code,

                            'description',
                            enriched_row.description,

                            'gl_type',
                            enriched_row.gl_type,

                            'opening_balance',
                            enriched_row.opening_balance::text,

                            'debit',
                            enriched_row.debit::text,

                            'credit',
                            enriched_row.credit::text,

                            'closing_balance',
                            enriched_row.closing_balance::text
                        )
                        order by
                            enriched_row.gl_account_code
                    ) filter (
                        where enriched_row.gl_type =
                              'equity'
                    ),
                    '[]'::jsonb
                ),

                'revenue',
                coalesce(
                    jsonb_agg(
                        jsonb_build_object(
                            'currency',
                            enriched_row.currency,

                            'gl_account_code',
                            enriched_row.gl_account_code,

                            'description',
                            enriched_row.description,

                            'gl_type',
                            enriched_row.gl_type,

                            'opening_balance',
                            enriched_row.opening_balance::text,

                            'debit',
                            enriched_row.debit::text,

                            'credit',
                            enriched_row.credit::text,

                            'closing_balance',
                            enriched_row.closing_balance::text
                        )
                        order by
                            enriched_row.gl_account_code
                    ) filter (
                        where enriched_row.gl_type =
                              'revenue'
                    ),
                    '[]'::jsonb
                ),

                'expense',
                coalesce(
                    jsonb_agg(
                        jsonb_build_object(
                            'currency',
                            enriched_row.currency,

                            'gl_account_code',
                            enriched_row.gl_account_code,

                            'description',
                            enriched_row.description,

                            'gl_type',
                            enriched_row.gl_type,

                            'opening_balance',
                            enriched_row.opening_balance::text,

                            'debit',
                            enriched_row.debit::text,

                            'credit',
                            enriched_row.credit::text,

                            'closing_balance',
                            enriched_row.closing_balance::text
                        )
                        order by
                            enriched_row.gl_account_code
                    ) filter (
                        where enriched_row.gl_type =
                              'expense'
                    ),
                    '[]'::jsonb
                )
            ) as grouped_data,

            jsonb_build_object(
                'opening',
                sum(
                    enriched_row.opening_balance
                )::text,

                'debit',
                sum(
                    enriched_row.debit
                )::text,

                'credit',
                sum(
                    enriched_row.credit
                )::text,

                'closing',
                sum(
                    enriched_row.closing_balance
                )::text
            ) as currency_totals
        from enriched_rows
            enriched_row
        group by
            enriched_row.currency
    )

    select
        coalesce(
            jsonb_object_agg(
                currency_result.currency,
                currency_result.grouped_data
            ),
            '{}'::jsonb
        ),

        coalesce(
            jsonb_object_agg(
                currency_result.currency,
                currency_result.currency_totals
            ),
            '{}'::jsonb
        )
    into
        v_data,
        v_totals
    from currency_results
        currency_result;

    return jsonb_build_object(
        'fiscalYear',
        v_fiscal_year,

        'period',
        v_period,

        'totals',
        v_totals,

        'data',
        v_data
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_current_gl_balances"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_current_token_gl_balance"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_country_code text;

    v_fiscal_year integer;
    v_period integer;

    v_accounts jsonb :=
        '[]'::jsonb;

    v_total_opening numeric := 0;
    v_total_debit numeric := 0;
    v_total_credit numeric := 0;
    v_total_closing numeric := 0;
begin
    /*
     * Authenticate.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    /*
     * Preserve the existing treasury-role requirement.
     */
    if not public.has_role(
        array[
            'treasury'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Fetch trusted user context.
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'TREASURY_USER_NOT_FOUND';
    end if;

    v_country_code :=
        lower(
            nullif(
                btrim(
                    v_user.country_code
                ),
                ''
            )
        );

    if v_country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Fetch current fiscal period.
     */
    select
        fiscal_period.fiscal_year,
        fiscal_period.period
    into
        v_fiscal_year,
        v_period
    from public.fetch_fiscal_period(
        v_country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Build all token GL rows.
     *
     * For each configured token GL:
     * - use the current snapshot when available;
     * - otherwise carry forward the latest earlier closing
     *   balance;
     * - otherwise start from zero.
     */
    with token_accounts as (
        select
            btrim(
                gl_record.code
            ) as gl_account_code,

            coalesce(
                btrim(
                    gl_record.description
                ),
                ''
            ) as description
        from public.gl_account
            gl_record
        where gl_record.type =
              'token'::public."GlType"
    ),
    enriched_accounts as (
        select
            token_account.gl_account_code,
            token_account.description,

            case
                when current_snapshot.gl_account_code is not null
                then
                    coalesce(
                        current_snapshot.opening_balance,
                        0
                    )
                else
                    coalesce(
                        previous_snapshot.closing_balance,
                        0
                    )
            end as opening_balance,

            coalesce(
                current_snapshot.debit,
                0
            ) as debit,

            coalesce(
                current_snapshot.credit,
                0
            ) as credit,

            case
                when current_snapshot.gl_account_code is not null
                then
                    coalesce(
                        current_snapshot.closing_balance,
                        0
                    )
                else
                    coalesce(
                        previous_snapshot.closing_balance,
                        0
                    )
            end as closing_balance
        from token_accounts
            token_account

        left join lateral (
            select snapshot_record.*
            from public.gl_balance_snapshot
                snapshot_record
            where snapshot_record.country_code =
                  v_country_code

              and lower(
                  snapshot_record.currency_code
              ) =
                  'gold'

              and snapshot_record.gl_account_code =
                  token_account.gl_account_code

              and snapshot_record.fiscal_year =
                  v_fiscal_year

              and snapshot_record.period =
                  v_period
            limit 1
        ) as current_snapshot
          on true

        left join lateral (
            select snapshot_record.*
            from public.gl_balance_snapshot
                snapshot_record
            where snapshot_record.country_code =
                  v_country_code

              and lower(
                  snapshot_record.currency_code
              ) =
                  'gold'

              and snapshot_record.gl_account_code =
                  token_account.gl_account_code

              and (
                  snapshot_record.fiscal_year <
                      v_fiscal_year

                  or (
                      snapshot_record.fiscal_year =
                          v_fiscal_year

                      and snapshot_record.period <
                          v_period
                  )
              )
            order by
                snapshot_record.fiscal_year desc,
                snapshot_record.period desc
            limit 1
        ) as previous_snapshot
          on true
    )
    select
        coalesce(
            jsonb_agg(
                jsonb_build_object(
                    'currency',
                    'gold',

                    'gl_account_code',
                    enriched_account.gl_account_code,

                    'description',
                    enriched_account.description,

                    'gl_type',
                    'token',

                    'opening_balance',
                    enriched_account.opening_balance,

                    'debit',
                    enriched_account.debit,

                    'credit',
                    enriched_account.credit,

                    'closing_balance',
                    enriched_account.closing_balance
                )
                order by
                    enriched_account.gl_account_code
            ),
            '[]'::jsonb
        ),

        coalesce(
            sum(
                enriched_account.opening_balance
            ),
            0
        ),

        coalesce(
            sum(
                enriched_account.debit
            ),
            0
        ),

        coalesce(
            sum(
                enriched_account.credit
            ),
            0
        ),

        coalesce(
            sum(
                enriched_account.closing_balance
            ),
            0
        )
    into
        v_accounts,
        v_total_opening,
        v_total_debit,
        v_total_credit,
        v_total_closing
    from enriched_accounts
        enriched_account;

    return jsonb_build_object(
        'fiscalYear',
        v_fiscal_year,

        'period',
        v_period,

        'currency',
        'gold',

        'totals',
        jsonb_build_object(
            'opening',
            v_total_opening,

            'debit',
            v_total_debit,

            'credit',
            v_total_credit,

            'closing',
            v_total_closing
        ),

        'accounts',
        v_accounts
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_current_token_gl_balance"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_customer_dashboard_context"() RETURNS TABLE("wallet_address" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    return query
    select u.wallet_address
    from public.users u
    join public.user_role r
      on r.id = u.role_id
    where u.id = auth.uid()::text
      and u.status =
          'active'::public."UserStatus"
      and lower(r.name) = 'customer'
    limit 1;

    if not found then
        raise exception using
            errcode = '42501',
            message = 'CUSTOMER_NOT_AUTHORIZED';
    end if;
end;
$$;
ALTER FUNCTION "public"."fetch_my_customer_dashboard_context"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_express_tap_limits"() RETURNS TABLE("currency_code" "text", "express_tap_limit" numeric, "is_active" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;
begin
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'customer',
            'treasury',
            'finance',
            'agent',
            'admin',
            'accounts',
            'merchant',
            'vendor'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    select user_record.*
    into v_user
    from public.users user_record
    where user_record.id =
          auth.uid()::text
      and user_record.status =
          'active'::public."UserStatus"
    limit 1;

    if not found then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.country_code is null
       or btrim(
           v_user.country_code
       ) = ''
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    return query
    select
        lower(
            btrim(
                config_record.currency_code
            )
        ) as currency_code,

        config_record.max_amount::numeric
            as express_tap_limit,

        config_record.is_active

    from public.maximum_tap_payment_amount_config
        config_record

    where lower(
        btrim(
            config_record.country_code
        )
    ) = lower(
        btrim(
            v_user.country_code
        )
    )

      and config_record.is_active =
          true

    order by
        lower(
            btrim(
                config_record.currency_code
            )
        );
end;
$$;
ALTER FUNCTION "public"."fetch_my_express_tap_limits"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_financial_document"("p_document_number" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_document_number text;

    v_first_entry
        public.financial_entry%rowtype;

    v_reversal_document_number text;

    v_total_debit numeric := 0;
    v_total_credit numeric := 0;

    v_journal jsonb :=
        '[]'::jsonb;

    v_wallet jsonb :=
        '[]'::jsonb;
begin
    /*
     * Authenticate and authorize.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if not public.has_role(
        array[
            'finance',
            'accounts'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    v_document_number :=
        nullif(
            btrim(p_document_number),
            ''
        );

    if v_document_number is null then
        raise exception
            'ENTER_DOCUMENT_NUMBER';
    end if;

    /*
     * Fetch the authenticated user's trusted country.
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Fetch the first financial entry for the document.
     */
    select financial_entry_record.*
    into v_first_entry
    from public.financial_entry
        financial_entry_record
    where financial_entry_record.document_number =
          v_document_number

      and financial_entry_record.country_code =
          v_user.country_code
    order by
        financial_entry_record.created_at asc,
        financial_entry_record.id asc
    limit 1;

    if not found then
        raise exception
            'DOCUMENT_NOT_FOUND';
    end if;

    /*
     * Find a reversal document whose reference points to this
     * document.
     */
    select financial_entry_record.document_number
    into v_reversal_document_number
    from public.financial_entry
        financial_entry_record
    where financial_entry_record.reference =
          v_document_number

      and financial_entry_record.document_number <>
          v_document_number

      and financial_entry_record.country_code =
          v_user.country_code
    order by
        financial_entry_record.created_at asc,
        financial_entry_record.document_number asc
    limit 1;

    /*
     * Calculate financial-entry totals.
     */
    select
        coalesce(
            sum(
                financial_entry_record.debit
            ),
            0
        ),

        coalesce(
            sum(
                financial_entry_record.credit
            ),
            0
        )
    into
        v_total_debit,
        v_total_credit
    from public.financial_entry
        financial_entry_record
    where financial_entry_record.document_number =
          v_document_number

      and financial_entry_record.country_code =
          v_user.country_code;

    /*
     * Build journal lines.
     */
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id',
                journal_line.id,

                'period',
                journal_line.period,

                'fiscal_year',
                journal_line.fiscal_year,

                'line_number',
                journal_line.line_number::text,

                'document_number',
                journal_line.document_number,

                'transaction_type',
                journal_line.transaction_type,

                'currency_code',
                journal_line.currency_code,

                'gl_account_code',
                journal_line.gl_account_code,

                'gl_account_name',
                journal_line.gl_account_name,

                'debit',
                journal_line.debit::text,

                'credit',
                journal_line.credit::text,

                'created_at',
                journal_line.created_at
            )
            order by
                journal_line.line_number
        ),
        '[]'::jsonb
    )
    into v_journal
    from (
        select
            financial_entry_record.id,
            financial_entry_record.period,
            financial_entry_record.fiscal_year,
            financial_entry_record.document_number,
            financial_entry_record.transaction_type,
            financial_entry_record.currency_code,
            financial_entry_record.gl_account_code,

            coalesce(
                gl_account_record.description,
                ''
            ) as gl_account_name,

            financial_entry_record.debit,
            financial_entry_record.credit,
            financial_entry_record.created_at,

            row_number() over (
                order by
                    financial_entry_record.created_at asc,
                    financial_entry_record.id asc
            ) as line_number
        from public.financial_entry
            financial_entry_record
        left join public.gl_account
            gl_account_record
          on gl_account_record.code =
             financial_entry_record.gl_account_code
        where financial_entry_record.document_number =
              v_document_number

          and financial_entry_record.country_code =
              v_user.country_code
    ) as journal_line;

    /*
     * Build wallet lines and resolve wallet owner types.
     */
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id',
                wallet_line.id,

                'period',
                wallet_line.period,

                'fiscal_year',
                wallet_line.fiscal_year,

                'line_number',
                wallet_line.line_number::text,

                'document_number',
                wallet_line.document_number,

                'transaction_type',
                wallet_line.transaction_type,

                'currency_code',
                wallet_line.currency_code,

                'wallet_id',
                wallet_line.wallet_id,

                'wallet_owner',
                wallet_line.wallet_owner,

                'debit',
                wallet_line.debit::text,

                'credit',
                wallet_line.credit::text,

                'created_at',
                wallet_line.created_at
            )
            order by
                wallet_line.line_number
        ),
        '[]'::jsonb
    )
    into v_wallet
    from (
        select
            wallet_entry_record.id,
            wallet_entry_record.period,
            wallet_entry_record.fiscal_year,
            wallet_entry_record.document_number,
            wallet_entry_record.transaction_type,
            wallet_entry_record.currency_code,
            wallet_entry_record.wallet_id,

            coalesce(
                wallet_record.owner_type::text,
                ''
            ) as wallet_owner,

            wallet_entry_record.debit,
            wallet_entry_record.credit,
            wallet_entry_record.created_at,

            row_number() over (
                order by
                    wallet_entry_record.created_at asc,
                    wallet_entry_record.id asc
            ) as line_number
        from public.wallet_entry
            wallet_entry_record
        left join public.wallet
            wallet_record
          on wallet_record.id =
             wallet_entry_record.wallet_id
        where wallet_entry_record.document_number =
              v_document_number

          and wallet_entry_record.country_code =
              v_user.country_code
    ) as wallet_line;

    /*
     * Return the complete document.
     */
    return jsonb_build_object(
        'document_number',
        v_document_number,

        'reversal_document_number',
        v_reversal_document_number,

        'transaction_type',
        v_first_entry.transaction_type,

        'currency',
        v_first_entry.currency_code,

        'created_at',
        v_first_entry.created_at,

        'total_debit',
        v_total_debit::text,

        'total_credit',
        v_total_credit::text,

        'balanced',
        v_total_debit =
            v_total_credit,

        'journal',
        v_journal,

        'wallet',
        v_wallet
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_financial_document"("p_document_number" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_fiscal_periods"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_user public.users%rowtype;

    v_current_fiscal_year integer;
    v_next_fiscal_year integer;

    v_current_periods jsonb;
    v_next_periods jsonb;
BEGIN
    /*
     * Authentication
     */
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHENTICATED';
    END IF;

    /*
     * Authorization
     *
     * Fiscal period maintenance is restricted
     * to Finance only.
     */
    IF NOT public.has_role(
        ARRAY[
            'finance'
        ]::text[]
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'FORBIDDEN';
    END IF;

    /*
     * Fetch the authenticated application user.
     */
    SELECT user_record.*
    INTO v_user
    FROM public.fetch_user_by_id(
        auth.uid()::text
    ) AS user_record;

    IF v_user.id IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'USER_NOT_FOUND';
    END IF;

    IF v_user.country_code IS NULL
       OR btrim(v_user.country_code) = '' THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'USER_COUNTRY_NOT_CONFIGURED';
    END IF;

    /*
     * Determine the current fiscal year.
     *
     * We use the configured fiscal-period dates rather
     * than assuming that fiscal year = calendar year.
     *
     * A fiscal year is current when today's date falls
     * within one of its configured periods.
     */
    SELECT fpc.fiscal_year
    INTO v_current_fiscal_year
    FROM public.fiscal_period_config AS fpc
    WHERE fpc.country_code = v_user.country_code
      AND CURRENT_TIMESTAMP >= fpc.opening_date
      AND CURRENT_TIMESTAMP <= fpc.closing_date
    ORDER BY
        fpc.fiscal_year DESC,
        fpc.period DESC
    LIMIT 1;

    /*
     * There must already be a fiscal year configured
     * for the user's country.
     */
    IF v_current_fiscal_year IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'CURRENT_FISCAL_YEAR_NOT_CONFIGURED';
    END IF;

    v_next_fiscal_year :=
        v_current_fiscal_year + 1;

    /*
     * Current fiscal-year periods.
     */
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'id',
                fpc.id,

                'fiscal_year',
                fpc.fiscal_year,

                'period',
                fpc.period,

                'country_code',
                fpc.country_code,

                'period_name',
                fpc.period_name,

                'opening_date',
                fpc.opening_date,

                'closing_date',
                fpc.closing_date,

                'is_closed',
                fpc.is_closed,

                'created_at',
                fpc.created_at,

                'created_by',
                fpc.created_by,

                'updated_at',
                fpc.updated_at,

                'updated_by',
                fpc.updated_by
            )
            ORDER BY fpc.period
        ),
        '[]'::jsonb
    )
    INTO v_current_periods
    FROM public.fiscal_period_config AS fpc
    WHERE fpc.country_code = v_user.country_code
      AND fpc.fiscal_year = v_current_fiscal_year;

    /*
     * Next fiscal-year periods.
     *
     * This intentionally returns [] when the next fiscal
     * year has not yet been opened/configured.
     *
     * Flutter uses that condition to enable the
     * "Open Fiscal Year" button.
     */
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'id',
                fpc.id,

                'fiscal_year',
                fpc.fiscal_year,

                'period',
                fpc.period,

                'country_code',
                fpc.country_code,

                'period_name',
                fpc.period_name,

                'opening_date',
                fpc.opening_date,

                'closing_date',
                fpc.closing_date,

                'is_closed',
                fpc.is_closed,

                'created_at',
                fpc.created_at,

                'created_by',
                fpc.created_by,

                'updated_at',
                fpc.updated_at,

                'updated_by',
                fpc.updated_by
            )
            ORDER BY fpc.period
        ),
        '[]'::jsonb
    )
    INTO v_next_periods
    FROM public.fiscal_period_config AS fpc
    WHERE fpc.country_code = v_user.country_code
      AND fpc.fiscal_year = v_next_fiscal_year;

    /*
     * Response expected by FiscalPeriodSummary.
     */
    RETURN jsonb_build_object(
        'country_code',
        v_user.country_code,

        'current_fiscal_year',
        v_current_fiscal_year,

        'next_fiscal_year',
        v_next_fiscal_year,

        'current_periods',
        v_current_periods,

        'next_periods',
        v_next_periods
    );
END;
$$;
ALTER FUNCTION "public"."fetch_my_fiscal_periods"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_gamification_notifications"("p_limit" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user_id text;
    v_rows jsonb := '[]'::jsonb;
begin
    v_user_id := auth.uid()::text;

    if v_user_id is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if p_limit is null
       or p_limit < 1
       or p_limit > 50
    then
        raise exception 'INVALID_NOTIFICATION_LIMIT';
    end if;

    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id', notification_record.id,
                'event_id', notification_record.event_id,
                'notification_type',
                    notification_record.notification_type,
                'points', notification_record.points,
                'title', notification_record.title,
                'subtitle', notification_record.subtitle,
                'display_priority',
                    notification_record.display_priority,
                'payload', notification_record.payload,
                'seen_at', notification_record.seen_at,
                'displayed_at', notification_record.displayed_at,
                'created_at', notification_record.created_at
            )
            order by
                notification_record.display_priority,
                notification_record.created_at,
                notification_record.id
        ),
        '[]'::jsonb
    )
    into v_rows
    from (
        select notification_source.*
        from public.gamification_notification notification_source
        where notification_source.user_id = v_user_id
          and notification_source.displayed_at is null
        order by
            notification_source.display_priority,
            notification_source.created_at,
            notification_source.id
        limit p_limit
    ) notification_record;

    return jsonb_build_object(
        'rows', v_rows,
        'count', jsonb_array_length(v_rows)
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_gamification_notifications"("p_limit" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_gl_period_entries"("p_gl_account_code" "text", "p_currency_code" "text", "p_fiscal_year" integer, "p_period" integer, "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_gl_account_code text;
    v_currency_code text;

    v_gl_description text;
    v_gl_type text;

    v_is_debit_normal boolean;

    v_exact_snapshot
        public.gl_balance_snapshot%rowtype;

    v_previous_snapshot
        public.gl_balance_snapshot%rowtype;

    v_raw_opening_balance numeric := 0;
    v_raw_closing_balance numeric := 0;

    v_opening_balance numeric := 0;
    v_closing_balance numeric := 0;

    v_total_entries bigint := 0;
    v_total_pages integer := 1;

    v_total_debit numeric := 0;
    v_total_credit numeric := 0;

    v_total_movement numeric := 0;

    v_calculated_closing_balance numeric := 0;
    v_difference numeric := 0;

    v_balance_tolerance numeric :=
        0.000001;

    v_page integer;
    v_page_size integer;
    v_offset integer;

    v_entries jsonb :=
        '[]'::jsonb;
begin
    /*
     * Authenticate and authorize.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if not public.has_role(
        array[
            'treasury',
            'finance',
            'accounts'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Validate parameters.
     */
    v_gl_account_code :=
        nullif(
            btrim(p_gl_account_code),
            ''
        );

    if v_gl_account_code is null then
        raise exception
            'GL_IS_REQUIRED';
    end if;

    v_currency_code :=
        lower(
            nullif(
                btrim(p_currency_code),
                ''
            )
        );

    if v_currency_code is null then
        raise exception
            'CURRENCY_IS_REQUIRED';
    end if;

    if p_fiscal_year is null then
        raise exception
            'FISCAL_YEAR_IS_REQUIRED';
    end if;

    if p_period is null then
        raise exception
            'PERIOD_IS_REQUIRED';
    end if;

    if p_period < 1
       or p_period > 12
    then
        raise exception
            'INVALID_PERIOD';
    end if;

    if p_page is null
       or p_page < 1
    then
        raise exception
            'INVALID_PAGE';
    end if;

    if p_page_size is null
       or p_page_size < 1
       or p_page_size > 100
    then
        raise exception
            'INVALID_PAGE_SIZE';
    end if;

    v_page :=
        p_page;

    v_page_size :=
        p_page_size;

    v_offset :=
        (v_page - 1) *
        v_page_size;

    /*
     * Fetch trusted user context.
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Fetch GL account information.
     */
    select
        coalesce(
            gl_account_record.description,
            ''
        ),

        lower(
            gl_account_record.type::text
        )
    into
        v_gl_description,
        v_gl_type
    from public.gl_account
        gl_account_record
    where gl_account_record.code =
          v_gl_account_code;

    if not found then
        raise exception
            'GL_ACCOUNT_NOT_FOUND';
    end if;

    /*
     * Assets and expenses are debit-normal.
     *
     * Liabilities, equity and revenue are credit-normal.
     */
    v_is_debit_normal :=
        v_gl_type in (
            'asset',
            'expense'
        );

    /*
     * Fetch the exact requested-period snapshot.
     */
    select snapshot_record.*
    into v_exact_snapshot
    from public.gl_balance_snapshot
        snapshot_record
    where snapshot_record.country_code =
          v_user.country_code

      and snapshot_record.gl_account_code =
          v_gl_account_code

      and lower(
          snapshot_record.currency_code
      ) =
          v_currency_code

      and snapshot_record.fiscal_year =
          p_fiscal_year

      and snapshot_record.period =
          p_period
    limit 1;

    if found then
        v_raw_opening_balance :=
            coalesce(
                v_exact_snapshot.opening_balance,
                0
            );

        v_raw_closing_balance :=
            coalesce(
                v_exact_snapshot.closing_balance,
                0
            );
    else
        /*
         * Find the latest snapshot preceding the selected
         * fiscal period.
         */
        select snapshot_record.*
        into v_previous_snapshot
        from public.gl_balance_snapshot
            snapshot_record
        where snapshot_record.country_code =
              v_user.country_code

          and snapshot_record.gl_account_code =
              v_gl_account_code

          and lower(
              snapshot_record.currency_code
          ) =
              v_currency_code

          and (
              snapshot_record.fiscal_year <
                  p_fiscal_year

              or (
                  snapshot_record.fiscal_year =
                      p_fiscal_year

                  and snapshot_record.period <
                      p_period
              )
          )
        order by
            snapshot_record.fiscal_year desc,
            snapshot_record.period desc
        limit 1;

        if found then
            v_raw_opening_balance :=
                coalesce(
                    v_previous_snapshot.closing_balance,
                    0
                );

            v_raw_closing_balance :=
                v_raw_opening_balance;
        else
            v_raw_opening_balance := 0;
            v_raw_closing_balance := 0;
        end if;
    end if;

    /*
     * Snapshots store balances using:
     *
     *     opening + debit - credit
     *
     * Normalize credit-normal accounts so the displayed and
     * calculated balances use their natural positive sign.
     *
     * Negation is used instead of abs() so abnormal balances
     * remain visible as negative amounts.
     */
    if v_is_debit_normal then
        v_opening_balance :=
            v_raw_opening_balance;

        v_closing_balance :=
            v_raw_closing_balance;
    else
        v_opening_balance :=
            -v_raw_opening_balance;

        v_closing_balance :=
            -v_raw_closing_balance;
    end if;

    /*
     * Calculate complete period totals.
     */
    select
        count(*),

        coalesce(
            sum(
                financial_entry_record.debit
            ),
            0
        ),

        coalesce(
            sum(
                financial_entry_record.credit
            ),
            0
        )
    into
        v_total_entries,
        v_total_debit,
        v_total_credit
    from public.financial_entry
        financial_entry_record
    where financial_entry_record.country_code =
          v_user.country_code

      and financial_entry_record.gl_account_code =
          v_gl_account_code

      and lower(
          financial_entry_record.currency_code
      ) =
          v_currency_code

      and financial_entry_record.fiscal_year =
          p_fiscal_year

      and financial_entry_record.period =
          p_period;

    /*
     * Apply movements according to the account's normal
     * balance.
     */
    v_total_movement :=
        case
            when v_is_debit_normal
            then
                v_total_debit -
                v_total_credit

            else
                v_total_credit -
                v_total_debit
        end;

    v_calculated_closing_balance :=
        v_opening_balance +
        v_total_movement;

    v_difference :=
        v_calculated_closing_balance -
        v_closing_balance;

    v_total_pages :=
        case
            when v_total_entries = 0
                then 1
            else ceil(
                v_total_entries::numeric /
                v_page_size::numeric
            )::integer
        end;

    /*
     * Calculate running balances over all entries before
     * applying pagination.
     */
    with ordered_entries as (
        select
            financial_entry_record.id,
            financial_entry_record.document_number,
            financial_entry_record.transaction_type,

            coalesce(
                financial_entry_record.debit,
                0
            ) as debit,

            coalesce(
                financial_entry_record.credit,
                0
            ) as credit,

            financial_entry_record.created_at,

            row_number() over (
                order by
                    financial_entry_record.created_at asc,
                    financial_entry_record.id asc
            ) as entry_number,

            sum(
                case
                    when v_is_debit_normal
                    then
                        coalesce(
                            financial_entry_record.debit,
                            0
                        ) -
                        coalesce(
                            financial_entry_record.credit,
                            0
                        )

                    else
                        coalesce(
                            financial_entry_record.credit,
                            0
                        ) -
                        coalesce(
                            financial_entry_record.debit,
                            0
                        )
                end
            ) over (
                order by
                    financial_entry_record.created_at asc,
                    financial_entry_record.id asc

                rows between unbounded preceding
                         and current row
            ) as cumulative_movement
        from public.financial_entry
            financial_entry_record
        where financial_entry_record.country_code =
              v_user.country_code

          and financial_entry_record.gl_account_code =
              v_gl_account_code

          and lower(
              financial_entry_record.currency_code
          ) =
              v_currency_code

          and financial_entry_record.fiscal_year =
              p_fiscal_year

          and financial_entry_record.period =
              p_period
    ),

    paginated_entries as (
        select ordered_entry.*
        from ordered_entries
            ordered_entry
        where ordered_entry.entry_number >
              v_offset

          and ordered_entry.entry_number <=
              (
                  v_offset +
                  v_page_size
              )
        order by
            ordered_entry.entry_number
    )

    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id',
                paginated_entry.id::text,

                'document_number',
                paginated_entry.document_number,

                'transaction_type',
                paginated_entry.transaction_type,

                'debit',
                paginated_entry.debit::text,

                'credit',
                paginated_entry.credit::text,

                'running_balance',
                (
                    v_opening_balance +
                    paginated_entry.cumulative_movement
                )::text,

                'created_at',
                paginated_entry.created_at
            )
            order by
                paginated_entry.entry_number
        ),
        '[]'::jsonb
    )
    into v_entries
    from paginated_entries
        paginated_entry;

    return jsonb_build_object(
        'currency_code',
        v_currency_code,

        'fiscal_year',
        p_fiscal_year,

        'gl_account_code',
        v_gl_account_code,

        'period',
        p_period,

        'description',
        v_gl_description,

        'balanced',
        abs(
            v_difference
        ) <= v_balance_tolerance,

        'difference',
        v_difference::text,

        'opening_balance',
        v_opening_balance::text,

        'total_debit',
        v_total_debit::text,

        'total_credit',
        v_total_credit::text,

        'calculated_closing_balance',
        v_calculated_closing_balance::text,

        'closing_balance',
        v_closing_balance::text,

        'pagination',
        jsonb_build_object(
            'page',
            v_page,

            'page_size',
            v_page_size,

            'total_entries',
            v_total_entries,

            'total_pages',
            v_total_pages,

            'has_previous',
            v_page > 1,

            'has_next',
            v_page < v_total_pages
        ),

        'entries',
        v_entries
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_gl_period_entries"("p_gl_account_code" "text", "p_currency_code" "text", "p_fiscal_year" integer, "p_period" integer, "p_page" integer, "p_page_size" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_gl_periodic_balances"("p_gl_account_code" "text", "p_currency_code" "text" DEFAULT 'usd'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_gl_account_code text;
    v_currency_code text;

    v_description text;

    v_fiscal_year integer;

    v_periods jsonb :=
        '[]'::jsonb;
begin
    /*
     * Authenticate and authorize.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if not public.has_role(
        array[
            'finance',
            'treasury'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Validate parameters.
     */
    v_gl_account_code :=
        nullif(
            btrim(p_gl_account_code),
            ''
        );

    if v_gl_account_code is null then
        raise exception
            'GL_ACCOUNT_CODE_REQUIRED';
    end if;

    v_currency_code :=
        lower(
            coalesce(
                nullif(
                    btrim(p_currency_code),
                    ''
                ),
                'usd'
            )
        );

    /*
     * Fetch the authenticated user's country.
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Validate the GL account and fetch its description.
     */
    select coalesce(
        gl_account_record.description,
        ''
    )
    into v_description
    from public.gl_account
        gl_account_record
    where gl_account_record.code =
          v_gl_account_code;

    if not found then
        raise exception
            'GL_ACCOUNT_NOT_FOUND_%',
            v_gl_account_code;
    end if;

    /*
     * Fetch the current fiscal year.
     */
    select fiscal_period.fiscal_year
    into v_fiscal_year
    from public.fetch_fiscal_period(
        v_user.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Generate all twelve fiscal periods.
     *
     * When a period has no snapshot, the latest earlier
     * closing balance in the same fiscal year is carried
     * forward.
     */
    with fiscal_periods as (
        select generate_series(
            1,
            12
        )::integer as period
    ),

    period_balances as (
        select
            fiscal_period.period,

            current_snapshot.gl_account_code
                is not null
                as snapshot_exists,

            case
                when current_snapshot.gl_account_code
                     is not null
                then
                    current_snapshot.opening_balance

                else
                    coalesce(
                        previous_snapshot.closing_balance,
                        0
                    )
            end as opening_balance,

            coalesce(
                current_snapshot.debit,
                0
            ) as debit,

            coalesce(
                current_snapshot.credit,
                0
            ) as credit,

            case
                when current_snapshot.gl_account_code
                     is not null
                then
                    abs(
                        current_snapshot.closing_balance
                    )

                else
                    coalesce(
                        previous_snapshot.closing_balance,
                        0
                    )
            end as closing_balance
        from fiscal_periods
            fiscal_period
        left join public.gl_balance_snapshot
            current_snapshot
          on current_snapshot.country_code =
             v_user.country_code

         and current_snapshot.gl_account_code =
             v_gl_account_code

         and lower(
             current_snapshot.currency_code
         ) =
             v_currency_code

         and current_snapshot.fiscal_year =
             v_fiscal_year

         and current_snapshot.period =
             fiscal_period.period

        left join lateral (
            select
                previous_record.closing_balance
            from public.gl_balance_snapshot
                previous_record
            where previous_record.country_code =
                  v_user.country_code

              and previous_record.gl_account_code =
                  v_gl_account_code

              and lower(
                  previous_record.currency_code
              ) =
                  v_currency_code

              and previous_record.fiscal_year =
                  v_fiscal_year

              and previous_record.period <
                  fiscal_period.period
            order by
                previous_record.period desc
            limit 1
        ) as previous_snapshot
          on true
    )

    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'period',
                period_balance.period,

                'opening_balance',
                period_balance.opening_balance::text,

                'debit',
                period_balance.debit::text,

                'credit',
                period_balance.credit::text,

                'closing_balance',
                period_balance.closing_balance::text
            )
            order by
                period_balance.period
        ),
        '[]'::jsonb
    )
    into v_periods
    from period_balances
        period_balance;

    return jsonb_build_object(
        'gl_account_code',
        v_gl_account_code,

        'description',
        v_description,

        'fiscalYear',
        v_fiscal_year,

        'periods',
        v_periods
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_gl_periodic_balances"("p_gl_account_code" "text", "p_currency_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_gold_buy_context"("p_v" "text", "p_blockchain_code" "text") RETURNS TABLE("user_id" "text", "country_code" "text", "wallet_address" "text", "wallet_index" bigint, "version_time" bigint, "blockchain_code" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_user public.users%rowtype;
    v_version_time bigint;
    v_blockchain_code text;
    v_network record;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;

    IF p_v IS DISTINCT FROM 'v7' THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'OPERATION_NOT_ALLOWED';
    END IF;

    IF NOT public.has_role(
        ARRAY[
            'customer',
            'agent',
            'vendor'
        ]::text[]
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'FORBIDDEN';
    END IF;

    v_blockchain_code :=
        lower(nullif(btrim(p_blockchain_code), ''));

    IF v_blockchain_code IS NULL THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_CODE_REQUIRED';
    END IF;

    /*
     * Validate the selected blockchain using
     * the existing authenticated RPC.
     */
    SELECT network.*
    INTO v_network
    FROM public.fetch_active_supported_blockchain(
        v_blockchain_code
    ) AS network;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_NOT_FOUND_OR_INACTIVE';
    END IF;

    SELECT user_record.*
    INTO v_user
    FROM public.users AS user_record
    WHERE user_record.id = auth.uid()::text
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'BUYER_NOT_FOUND';
    END IF;

    IF v_user.status <>
       'active'::public."UserStatus"
    THEN
        RAISE EXCEPTION
            'BUYER_NOT_ACTIVE';
    END IF;

    IF v_user.country_code IS NULL
       OR btrim(v_user.country_code) = ''
    THEN
        RAISE EXCEPTION
            'USER_COUNTRY_NOT_CONFIGURED';
    END IF;

    IF v_user.wallet_address IS NULL
       OR btrim(v_user.wallet_address) = ''
    THEN
        RAISE EXCEPTION
            'USER_WALLET_NOT_CONFIGURED';
    END IF;

    /*
     * Wallet index zero is valid.
     */
    IF v_user.wallet_index IS NULL THEN
        RAISE EXCEPTION
            'USER_WALLET_INDEX_NOT_CONFIGURED';
    END IF;

    SELECT public.get_transaction_v(p_v)::bigint
    INTO v_version_time;

    IF v_version_time IS NULL
       OR v_version_time <= 0
    THEN
        RAISE EXCEPTION
            'INVALID_TRANSACTION_VERSION';
    END IF;

    RETURN QUERY
    SELECT
        v_user.id,
        lower(btrim(v_user.country_code)),
        v_user.wallet_address,
        v_user.wallet_index::bigint,
        v_version_time,
        v_blockchain_code;
END;
$$;
ALTER FUNCTION "public"."fetch_my_gold_buy_context"("p_v" "text", "p_blockchain_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_gold_sell_context"("p_v" "text", "p_blockchain_code" "text") RETURNS TABLE("seller_id" "text", "country_code" "text", "wallet_address" "text", "wallet_index" bigint, "version_time" bigint, "blockchain_code" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_seller public.users%rowtype;
    v_version_time bigint;
    v_blockchain_code text;
    v_network record;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;

    IF p_v IS DISTINCT FROM 'v7' THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'OPERATION_NOT_ALLOWED';
    END IF;

    IF NOT public.has_role(
        ARRAY[
            'customer',
            'agent',
            'vendor'
        ]::text[]
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'FORBIDDEN';
    END IF;

    v_blockchain_code :=
        lower(nullif(btrim(p_blockchain_code), ''));

    IF v_blockchain_code IS NULL THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_CODE_REQUIRED';
    END IF;

    /*
     * Validate the selected blockchain using
     * the existing authenticated RPC.
     */
    SELECT network.*
    INTO v_network
    FROM public.fetch_active_supported_blockchain(
        v_blockchain_code
    ) AS network;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'BLOCKCHAIN_NOT_FOUND_OR_INACTIVE';
    END IF;

    SELECT user_record.*
    INTO v_seller
    FROM public.users AS user_record
    WHERE user_record.id = auth.uid()::text
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'SELLER_NOT_FOUND';
    END IF;

    IF v_seller.status <>
       'active'::public."UserStatus"
    THEN
        RAISE EXCEPTION
            'SELLER_NOT_ACTIVE';
    END IF;

    IF v_seller.country_code IS NULL
       OR btrim(v_seller.country_code) = ''
    THEN
        RAISE EXCEPTION
            'USER_COUNTRY_NOT_CONFIGURED';
    END IF;

    IF v_seller.wallet_address IS NULL
       OR btrim(v_seller.wallet_address) = ''
    THEN
        RAISE EXCEPTION
            'USER_WALLET_NOT_CONFIGURED';
    END IF;

    /*
     * Wallet index zero is valid.
     */
    IF v_seller.wallet_index IS NULL THEN
        RAISE EXCEPTION
            'USER_WALLET_INDEX_NOT_CONFIGURED';
    END IF;

    SELECT public.get_transaction_v(p_v)::bigint
    INTO v_version_time;

    IF v_version_time IS NULL
       OR v_version_time <= 0
    THEN
        RAISE EXCEPTION
            'INVALID_TRANSACTION_VERSION';
    END IF;

    RETURN QUERY
    SELECT
        v_seller.id,
        lower(btrim(v_seller.country_code)),
        v_seller.wallet_address,
        v_seller.wallet_index::bigint,
        v_version_time,
        v_blockchain_code;
END;
$$;
ALTER FUNCTION "public"."fetch_my_gold_sell_context"("p_v" "text", "p_blockchain_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_gold_transfer_context"("p_v" "text") RETURNS TABLE("sender_id" "text", "country_code" "text", "wallet_address" "text", "wallet_index" bigint, "version_time" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_sender public.users%rowtype;
    v_version_time bigint;
begin
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if p_v is distinct from 'v6' then
        raise exception using
            errcode = '42501',
            message = 'OPERATION_NOT_ALLOWED';
    end if;

    /*
     * Continue using the existing centralized
     * authenticated role function.
     */
    if not public.has_role(
        array[
            'customer',
            'agent',
            'vendor'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    select user_record.*
    into v_sender
    from public.users user_record
    where user_record.id =
          auth.uid()::text
    limit 1;

    if not found then
        raise exception
            'SENDER_NOT_FOUND';
    end if;

    if v_sender.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'SENDER_NOT_ACTIVE';
    end if;

    if v_sender.country_code is null
       or btrim(
           v_sender.country_code
       ) = ''
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    if v_sender.wallet_address is null
       or btrim(
           v_sender.wallet_address
       ) = ''
    then
        raise exception
            'USER_WALLET_NOT_CONFIGURED';
    end if;

    if v_sender.wallet_index is null then
        raise exception
            'USER_WALLET_INDEX_NOT_CONFIGURED';
    end if;

    /*
     * Correct existing function name.
     */
    select public.get_transaction_v(
        p_v
    )::bigint
    into v_version_time;

    if v_version_time is null
       or v_version_time <= 0
    then
        raise exception
            'INVALID_TRANSACTION_VERSION';
    end if;

    return query
    select
        v_sender.id,
        lower(
            btrim(
                v_sender.country_code
            )
        ),
        v_sender.wallet_address,
        v_sender.wallet_index::bigint,
        v_version_time;
end;
$$;
ALTER FUNCTION "public"."fetch_my_gold_transfer_context"("p_v" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_government_tax_settlement_batches"("p_statuses" "public"."SettlementStatus"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_batches jsonb :=
        '[]'::jsonb;
begin
    /*
     * Authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Accounts creates and executes settlements.
     * Finance reviews and approves/cancels them.
     */
    if not public.has_role(
        array[
            'accounts',
            'finance'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Validate requested statuses.
     */
    if p_statuses is null
       or cardinality(p_statuses) = 0
    then
        raise exception
            'SETTLEMENT_STATUSES_REQUIRED';
    end if;

    if array_position(
        p_statuses,
        null
    ) is not null
    then
        raise exception
            'INVALID_SETTLEMENT_STATUS';
    end if;

    /*
     * Fetch trusted user context.
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'USER_NOT_ACTIVE';
    end if;

    if nullif(
        btrim(
            v_user.country_code
        ),
        ''
    ) is null
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Fetch only batch headers.
     *
     * Tax settlement items are deliberately excluded.
     * They are retrieved through the separate paginated
     * drill-down function.
     */
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id',
                batch_record.id,

                'period',
                batch_record.period,

                'fiscal_year',
                batch_record.fiscal_year,

                'document_number',
                batch_record.document_number,

                'currency_code',
                lower(
                    btrim(
                        batch_record.currency_code
                    )
                ),

                'start_date',
                batch_record.start_date,

                'end_date',
                batch_record.end_date,

                'total_amount',
                trim_scale(
                    batch_record.total_amount
                )::text,

                'status',
                batch_record.status,

                'created_by',
                batch_record.created_by,

                'approved_by',
                batch_record.approved_by,

                'created_at',
                batch_record.created_at,

                'approved_at',
                batch_record.approved_at,

                'paid_at',
                batch_record.paid_at,

                'error_message',
                batch_record.error_message
            )
            order by
                batch_record.created_at desc,
                batch_record.id desc
        ),
        '[]'::jsonb
    )
    into v_batches
    from public.government_tax_settlement_batch
        batch_record
    where lower(
        btrim(
            batch_record.country_code
        )
    ) =
        lower(
            btrim(
                v_user.country_code
            )
        )

      and batch_record.status =
          any(p_statuses);

    return jsonb_build_object(
        'settlementBatch',
        v_batches
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_government_tax_settlement_batches"("p_statuses" "public"."SettlementStatus"[]) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_government_tax_settlement_items"("p_batch_id" "text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_batch
        public.government_tax_settlement_batch%rowtype;

    v_batch_id text;

    v_offset integer;
    v_total_entries integer;
    v_total_pages integer;

    v_items jsonb :=
        '[]'::jsonb;
begin
    /*
     * Authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Accounts processes Government Tax settlements.
     * Finance reviews and approves/cancels them.
     */
    if not public.has_role(
        array[
            'accounts',
            'finance'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Validate input.
     */
    v_batch_id :=
        nullif(
            btrim(p_batch_id),
            ''
        );

    if v_batch_id is null then
        raise exception
            'SETTLEMENT_BATCH_ID_REQUIRED';
    end if;

    if p_page is null
       or p_page < 1
    then
        raise exception
            'INVALID_PAGE';
    end if;

    if p_page_size is null
       or p_page_size < 1
       or p_page_size > 100
    then
        raise exception
            'INVALID_PAGE_SIZE';
    end if;

    v_offset :=
        (p_page - 1) *
        p_page_size;

    /*
     * Fetch trusted user context.
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'USER_NOT_ACTIVE';
    end if;

    if nullif(
        btrim(
            v_user.country_code
        ),
        ''
    ) is null
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Fetch the requested tax settlement batch and
     * enforce country isolation.
     */
    select batch_record.*
    into v_batch
    from public.government_tax_settlement_batch
        batch_record
    where batch_record.id::text =
              v_batch_id

      and lower(
          btrim(
              batch_record.country_code
          )
      ) =
          lower(
              btrim(
                  v_user.country_code
              )
          )
    limit 1;

    if not found then
        raise exception
            'GOVERNMENT_TAX_SETTLEMENT_BATCH_NOT_FOUND';
    end if;

    /*
     * Count all items belonging to the batch.
     */
    select count(*)::integer
    into v_total_entries
    from public.government_tax_settlement_item
        item_record
    where item_record.batch_id =
          v_batch.id;

    v_total_pages :=
        case
            when v_total_entries = 0
            then 1

            else ceil(
                v_total_entries::numeric /
                p_page_size::numeric
            )::integer
        end;

    /*
     * Fetch the requested page.
     *
     * Government Tax settlement items are grouped by
     * originating transaction type.
     */
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id',
                paged_item.id,

                'batch_id',
                paged_item.batch_id,

                'transaction_type',
                paged_item.transaction_type,

                'fiscal_year',
                paged_item.fiscal_year,

                'period',
                paged_item.period,

                'currency_code',
                lower(
                    btrim(
                        paged_item.currency_code
                    )
                ),

                'gross_amount',
                trim_scale(
                    paged_item.gross_amount
                )::text,

                'tax_amount',
                trim_scale(
                    paged_item.tax_amount
                )::text,

                'status',
                paged_item.status
            )
            order by
                paged_item.transaction_type,
                paged_item.id
        ),
        '[]'::jsonb
    )
    into v_items
    from (
        select item_record.*
        from public.government_tax_settlement_item
            item_record
        where item_record.batch_id =
              v_batch.id
        order by
            item_record.transaction_type,
            item_record.id
        offset v_offset
        limit p_page_size
    ) as paged_item;

    return jsonb_build_object(
        /*
         * Batch header.
         */
        'currency',
        lower(
            btrim(
                v_batch.currency_code
            )
        ),

        /*
         * This is the total Government Tax payable.
         */
        'totalAmount',
        trim_scale(
            v_batch.total_amount
        )::text,

        'totalItems',
        v_total_entries,

        /*
         * Paginated drill-down.
         */
        'items',
        v_items,

        'pagination',
        jsonb_build_object(
            'page',
            p_page,

            'page_size',
            p_page_size,

            'total_entries',
            v_total_entries,

            'total_pages',
            v_total_pages,

            'has_previous',
            p_page > 1,

            'has_next',
            p_page < v_total_pages
        )
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_government_tax_settlement_items"("p_batch_id" "text", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_incomplete_liquidation_jobs"("p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_offset integer;
    v_total_entries integer := 0;
    v_total_pages integer := 1;

    v_rows jsonb :=
        '[]'::jsonb;

    v_stage text :=
        'initialization';

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * Accounts and Finance may review failed liquidation
     * processing.
     */
    v_stage :=
        'authorize reporting user';

    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'accounts',
            'finance'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'REPORTING_USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'REPORTING_USER_NOT_ACTIVE';
    end if;

    if nullif(
        btrim(
            v_user.country_code
        ),
        ''
    ) is null
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Validate pagination.
     */
    v_stage :=
        'validate pagination';

    if p_page is null
       or p_page < 1
    then
        raise exception
            'INVALID_PAGE';
    end if;

    if p_page_size is null
       or p_page_size < 1
       or p_page_size > 100
    then
        raise exception
            'INVALID_PAGE_SIZE';
    end if;

    v_offset :=
        (p_page - 1) *
        p_page_size;

    /*
     * Return incomplete jobs having either a job-level
     * error or a failed blockchain queue entry.
     *
     * to_jsonb(queue_record) lets this report support the
     * existing queue schemas that used either error_message
     * or reason for the blockchain failure text.
     */
    v_stage :=
        'fetch incomplete liquidation jobs';

    with report_rows as materialized (
        select
            job_record.id::text
                as job_id,

            job_record.user_id,

            user_record.email,
            user_record.phone,
            user_record.first_name,
            user_record.surname,

            job_record.document_number,

            lower(
                btrim(
                    job_record.country_code
                )
            ) as country_code,

            job_record.fiscal_year,
            job_record.period,

            job_record.status::text
                as job_status,

            trim_scale(
                job_record.total_principal
            )::text as total_principal,

            trim_scale(
                job_record.total_interest
            )::text as total_interest,

            trim_scale(
                job_record.total_debt
            )::text as total_debt,

            trim_scale(
                job_record.penalty_amount
            )::text as penalty_amount,

            trim_scale(
                job_record.repayment_required
            )::text as repayment_required,

            trim_scale(
                job_record.collateral_required
            )::text as collateral_required,

            trim_scale(
                job_record.gold_price
            )::text as gold_price,

            job_record.blockchain_queue_id,

            queue_record.status::text
                as blockchain_status,

            nullif(
                to_jsonb(queue_record) ->>
                    'tx_hash',
                ''
            ) as tx_hash,

            coalesce(
                nullif(
                    job_record.error_message,
                    ''
                ),
                nullif(
                    to_jsonb(queue_record) ->>
                        'error_message',
                    ''
                ),
                nullif(
                    to_jsonb(queue_record) ->>
                        'reason',
                    ''
                )
            ) as error_message,

            coalesce(
                nullif(
                    to_jsonb(queue_record) ->>
                        'retry_count',
                    ''
                )::integer,
                0
            ) as retry_count,

            job_record.created_at

        from public.liquidation_job
            job_record

        join public.users
            user_record
          on user_record.id =
             job_record.user_id

        left join lateral (
            select queue_source.*
            from public.liquidation_blockchain_queue
                queue_source
            where queue_source.liquidation_job_id =
                  job_record.id::text
            order by
                queue_source.id desc
            limit 1
        ) as queue_record
          on true

        where lower(
            btrim(
                job_record.country_code
            )
        ) =
            lower(
                btrim(
                    v_user.country_code
                )
            )

          and job_record.status::text <>
              'completed'

          and (
              nullif(
                  btrim(
                      job_record.error_message
                  ),
                  ''
              ) is not null

              or queue_record.status::text =
                 'failed'

              or nullif(
                  btrim(
                      coalesce(
                          to_jsonb(queue_record) ->>
                              'error_message',
                          to_jsonb(queue_record) ->>
                              'reason'
                      )
                  ),
                  ''
              ) is not null
          )
    ),

    page_rows as (
        select report_record.*
        from report_rows
            report_record
        order by
            report_record.created_at desc,
            report_record.job_id desc
        limit p_page_size
        offset v_offset
    )
    select
        (
            select count(*)::integer
            from report_rows
        ),

        coalesce(
            (
                select jsonb_agg(
                    to_jsonb(
                        page_record
                    )
                    order by
                        page_record.created_at desc,
                        page_record.job_id desc
                )
                from page_rows
                    page_record
            ),
            '[]'::jsonb
        )
    into
        v_total_entries,
        v_rows;

    v_total_pages :=
        greatest(
            ceil(
                v_total_entries::numeric /
                p_page_size
            )::integer,
            1
        );

    return jsonb_build_object(
        'rows',
        v_rows,

        'pagination',
        jsonb_build_object(
            'page',
            p_page,

            'page_size',
            p_page_size,

            'total_entries',
            v_total_entries,

            'total_pages',
            v_total_pages,

            'has_previous',
            p_page > 1,

            'has_next',
            p_page < v_total_pages
        )
    );

exception
    when others then
        get stacked diagnostics
            v_error_state = returned_sqlstate,
            v_error_message = message_text,
            v_error_detail = pg_exception_detail,
            v_error_hint = pg_exception_hint,
            v_error_context = pg_exception_context;

        raise exception using
            errcode = v_error_state,

            message = format(
                'INCOMPLETE_LIQUIDATION_JOBS_REPORT_FAILED at [%s]: %s',
                v_stage,
                v_error_message
            ),

            detail = concat_ws(
                E'\n',
                nullif(v_error_detail, ''),
                nullif(v_error_context, '')
            ),

            hint = coalesce(
                nullif(v_error_hint, ''),
                'Check the incomplete-liquidation report stage'
            );
end;
$$;
ALTER FUNCTION "public"."fetch_my_incomplete_liquidation_jobs"("p_page" integer, "p_page_size" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_last_agent_commission_settlement"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_fiscal_year integer;
    v_fiscal_year_start date;

    v_result jsonb :=
        '[]'::jsonb;
begin
    /*
     * Authentication and authorization.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'accounts'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Fetch trusted Accounts user context.
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'ACCOUNTS_USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'ACCOUNTS_USER_NOT_ACTIVE';
    end if;

    if nullif(
        btrim(
            v_user.country_code
        ),
        ''
    ) is null
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Fetch the current fiscal year.
     */
    select fiscal_period.fiscal_year
    into v_fiscal_year
    from public.fetch_fiscal_period(
        v_user.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Fetch the beginning of the current fiscal year.
     *
     * This becomes next_start_date when the currency has
     * never had a settlement batch.
     */
    select min(
        fiscal_period_record.opening_date
    )::date
    into v_fiscal_year_start
    from public.fiscal_period_config
        fiscal_period_record
    where fiscal_period_record.country_code =
              v_user.country_code

      and fiscal_period_record.fiscal_year =
              v_fiscal_year;

    if v_fiscal_year_start is null then
        raise exception
            'FISCAL_YEAR_START_NOT_FOUND';
    end if;

    /*
     * Return every currency having commission entries in
     * the current fiscal year.
     *
     * The latest batch is returned regardless of status,
     * because a draft batch has already reserved the
     * commission entries and must prevent another batch.
     */
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'currency_code',
                currency_record.currency_code,

                'start_date',
                settlement_record.start_date,

                'end_date',
                settlement_record.end_date,

                'next_start_date',
                case
                    when settlement_record.end_date
                         is not null
                    then
                        settlement_record.end_date::date +
                        1
                    else
                        v_fiscal_year_start
                end,

                'batch_id',
                settlement_record.batch_id,

                'document_number',
                settlement_record.document_number,

                'status',
                settlement_record.status,

                'payment_underway',
                case
                    when settlement_record.batch_id
                         is null
                    then
                        false

                    when settlement_record.status::text <>
                         'settled'
                    then
                        true

                    else
                        false
                end
            )
            order by
                currency_record.currency_code
        ),
        '[]'::jsonb
    )
    into v_result
    from (
        select distinct
            lower(
                btrim(
                    commission_record.currency_code
                )
            ) as currency_code

        from public.agent_commission
            commission_record

        where commission_record.fiscal_year =
                  v_fiscal_year

          and lower(
              btrim(
                  commission_record.country_code
              )
          ) =
              lower(
                  btrim(
                      v_user.country_code
                  )
              )

          and nullif(
              btrim(
                  commission_record.currency_code
              ),
              ''
          ) is not null
    ) as currency_record

    left join lateral (
        select
            batch_record.id as batch_id,

            batch_record.document_number,

            batch_record.start_date,

            batch_record.end_date,

            batch_record.status

        from public.agent_settlement_batch
            batch_record

        where lower(
            btrim(
                batch_record.country_code
            )
        ) =
            lower(
                btrim(
                    v_user.country_code
                )
            )

          and lower(
              btrim(
                  batch_record.currency_code
              )
          ) =
              currency_record.currency_code

        order by
            batch_record.end_date desc,
            batch_record.created_at desc,
            batch_record.id desc

        limit 1
    ) as settlement_record
      on true;

    return v_result;
end;
$$;
ALTER FUNCTION "public"."fetch_my_last_agent_commission_settlement"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_last_government_tax_settlement"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_fiscal_year integer;
    v_fiscal_year_start date;

    v_result jsonb :=
        '[]'::jsonb;
begin
    /*
     * Authentication and authorization.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'accounts'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Fetch trusted Accounts user context.
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'ACCOUNTS_USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'ACCOUNTS_USER_NOT_ACTIVE';
    end if;

    if nullif(
        btrim(
            v_user.country_code
        ),
        ''
    ) is null
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Fetch the current fiscal year.
     */
    select fiscal_period.fiscal_year
    into v_fiscal_year
    from public.fetch_fiscal_period(
        v_user.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Fetch the beginning of the current fiscal year.
     */
    select min(
        fiscal_period_record.opening_date
    )::date
    into v_fiscal_year_start
    from public.fiscal_period_config
        fiscal_period_record
    where fiscal_period_record.country_code =
              v_user.country_code

      and fiscal_period_record.fiscal_year =
              v_fiscal_year;

    if v_fiscal_year_start is null then
        raise exception
            'FISCAL_YEAR_START_NOT_FOUND';
    end if;

    /*
     * Return every currency having Government Tax
     * payable entries in the current fiscal year.
     *
     * Draft and other unfinished batches are returned so
     * Accounts can see that payment is underway.
     */
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'currency_code',
                currency_record.currency_code,

                'start_date',
                settlement_record.start_date,

                'end_date',
                settlement_record.end_date,

                'next_start_date',
                case
                    when settlement_record.end_date
                         is not null
                    then
                        settlement_record.end_date::date +
                        1
                    else
                        v_fiscal_year_start
                end,

                'batch_id',
                settlement_record.batch_id,

                'document_number',
                settlement_record.document_number,

                'status',
                settlement_record.status,

                'payment_underway',
                case
                    when settlement_record.batch_id
                         is null
                    then
                        false

                    when settlement_record.status::text <>
                         'settled'
                    then
                        true

                    else
                        false
                end
            )
            order by
                currency_record.currency_code
        ),
        '[]'::jsonb
    )
    into v_result
    from (
        select distinct
            lower(
                btrim(
                    tax_record.currency_code
                )
            ) as currency_code

        from public.government_tax_payable
            tax_record

        where tax_record.fiscal_year =
                  v_fiscal_year

          and lower(
              btrim(
                  tax_record.country_code
              )
          ) =
              lower(
                  btrim(
                      v_user.country_code
                  )
              )

          and nullif(
              btrim(
                  tax_record.currency_code
              ),
              ''
          ) is not null
    ) as currency_record

    left join lateral (
        select
            batch_record.id as batch_id,

            batch_record.document_number,

            batch_record.start_date,

            batch_record.end_date,

            batch_record.status

        from public.government_tax_settlement_batch
            batch_record

        where lower(
            btrim(
                batch_record.country_code
            )
        ) =
            lower(
                btrim(
                    v_user.country_code
                )
            )

          and lower(
              btrim(
                  batch_record.currency_code
              )
          ) =
              currency_record.currency_code

        order by
            batch_record.end_date desc,
            batch_record.created_at desc,
            batch_record.id desc

        limit 1
    ) as settlement_record
      on true;

    return v_result;
end;
$$;
ALTER FUNCTION "public"."fetch_my_last_government_tax_settlement"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_last_loan_interest_accrual"() RETURNS TABLE("last_accrual_run" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;
    v_last_accrual_run timestamptz;
begin
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    /*
     * Preserve the original authorization:
     * only finance users may access this information.
     */
    if not public.has_role(
        array[
            'finance'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    select max(
        loan_entry_record.created_at
    )
    into v_last_accrual_run
    from public.loan_entry
        loan_entry_record
    where loan_entry_record.country_code =
          v_user.country_code
      and loan_entry_record.entry_type =
          'interest_accrual'::public."LoanEntryType"
      and loan_entry_record.debit_interest > 0;

    return query
    select v_last_accrual_run;
end;
$$;
ALTER FUNCTION "public"."fetch_my_last_loan_interest_accrual"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_liquidated_loans_by_date"("p_liquidation_date" "date", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_offset integer;
    v_total_entries integer := 0;
    v_total_pages integer := 1;

    v_rows jsonb :=
        '[]'::jsonb;

    v_stage text :=
        'initialization';

    v_error_state text;
    v_error_message text;
    v_error_detail text;
    v_error_hint text;
    v_error_context text;
begin
    /*
     * Accounts and Finance may review liquidation reports.
     */
    v_stage :=
        'authorize reporting user';

    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'accounts',
            'finance'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'REPORTING_USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'REPORTING_USER_NOT_ACTIVE';
    end if;

    if nullif(
        btrim(
            v_user.country_code
        ),
        ''
    ) is null
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * A report date must always be supplied explicitly.
     */
    v_stage :=
        'validate liquidation date';

    if p_liquidation_date is null then
        raise exception
            'LIQUIDATION_DATE_REQUIRED';
    end if;

    /*
     * Validate pagination.
     */
    v_stage :=
        'validate pagination';

    if p_page is null
       or p_page < 1
    then
        raise exception
            'INVALID_PAGE';
    end if;

    if p_page_size is null
       or p_page_size < 1
       or p_page_size > 100
    then
        raise exception
            'INVALID_PAGE_SIZE';
    end if;

    v_offset :=
        (p_page - 1) *
        p_page_size;

    /*
     * A loan appears here only after liquidation accounting
     * has created both the loan ledger entry and financial
     * transaction header.
     *
     * This avoids treating a merely detected or queued job
     * as a completed liquidation.
     */
    v_stage :=
        'fetch liquidated loans';

    with report_rows as materialized (
        select
            loan_entry_record.loan_id::text
                as loan_id,

            loan_record.user_id
                as user_id,

            user_record.email,
            user_record.phone,
            user_record.first_name,
            user_record.surname,

            loan_entry_record.document_number,

            lower(
                btrim(
                    loan_entry_record.currency_code
                )
            ) as currency_code,

            trim_scale(
                coalesce(
                    sum(
                        loan_entry_record.credit_principal
                    ),
                    0
                )
            )::text as principal_liquidated,

            trim_scale(
                coalesce(
                    sum(
                        loan_entry_record.credit_interest
                    ),
                    0
                )
            )::text as interest_liquidated,

            trim_scale(
                coalesce(
                    sum(
                        loan_entry_record.credit_principal +
                        loan_entry_record.credit_interest
                    ),
                    0
                )
            )::text as total_liquidated,

            loan_record.status::text
                as loan_status,

            min(
                transaction_record.created_at
            ) as liquidated_at

        from public.loan_entry
            loan_entry_record

        join public.loan
            loan_record
          on loan_record.id =
             loan_entry_record.loan_id

        join public.users
            user_record
          on user_record.id =
             loan_record.user_id

        join public.financial_transaction
            transaction_record
          on transaction_record.document_number =
             loan_entry_record.document_number

         and transaction_record.country_code =
             loan_entry_record.country_code

         and transaction_record.transaction_type =
             'loan_liquidation'::public."TransactionType"

        where lower(
            btrim(
                loan_entry_record.country_code
            )
        ) =
            lower(
                btrim(
                    v_user.country_code
                )
            )

          and loan_entry_record.entry_type::text =
              'liquidation'

          and transaction_record.created_at >=
              p_liquidation_date

          and transaction_record.created_at <
              p_liquidation_date + 1

        group by
            loan_entry_record.loan_id,
            loan_record.user_id,
            user_record.email,
            user_record.phone,
            user_record.first_name,
            user_record.surname,
            loan_entry_record.document_number,
            lower(
                btrim(
                    loan_entry_record.currency_code
                )
            ),
            loan_record.status::text
    ),

    page_rows as (
        select report_record.*
        from report_rows
            report_record
        order by
            report_record.liquidated_at desc,
            report_record.document_number desc,
            report_record.loan_id
        limit p_page_size
        offset v_offset
    )
    select
        (
            select count(*)::integer
            from report_rows
        ),

        coalesce(
            (
                select jsonb_agg(
                    to_jsonb(
                        page_record
                    )
                    order by
                        page_record.liquidated_at desc,
                        page_record.document_number desc,
                        page_record.loan_id
                )
                from page_rows
                    page_record
            ),
            '[]'::jsonb
        )
    into
        v_total_entries,
        v_rows;

    v_total_pages :=
        greatest(
            ceil(
                v_total_entries::numeric /
                p_page_size
            )::integer,
            1
        );

    return jsonb_build_object(
        'liquidation_date',
        p_liquidation_date,

        'rows',
        v_rows,

        'pagination',
        jsonb_build_object(
            'page',
            p_page,

            'page_size',
            p_page_size,

            'total_entries',
            v_total_entries,

            'total_pages',
            v_total_pages,

            'has_previous',
            p_page > 1,

            'has_next',
            p_page < v_total_pages
        )
    );

exception
    when others then
        get stacked diagnostics
            v_error_state = returned_sqlstate,
            v_error_message = message_text,
            v_error_detail = pg_exception_detail,
            v_error_hint = pg_exception_hint,
            v_error_context = pg_exception_context;

        raise exception using
            errcode = v_error_state,

            message = format(
                'LIQUIDATED_LOANS_BY_DATE_REPORT_FAILED at [%s]: %s',
                v_stage,
                v_error_message
            ),

            detail = concat_ws(
                E'\n',
                nullif(v_error_detail, ''),
                nullif(v_error_context, '')
            ),

            hint = coalesce(
                nullif(v_error_hint, ''),
                'Check the liquidated-loans-by-date report stage'
            );
end;
$$;
ALTER FUNCTION "public"."fetch_my_liquidated_loans_by_date"("p_liquidation_date" "date", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_loan_preview_context"() RETURNS TABLE("wallet_address" "text", "country_code" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;
begin
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'customer',
            'agent',
            'vendor'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    select user_record.*
    into v_user
    from public.users user_record
    where user_record.id =
          auth.uid()::text
    limit 1;

    if not found then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.status is distinct from
       'active'::public."UserStatus"
    then
        raise exception
            'USER_NOT_ACTIVE';
    end if;

    if v_user.wallet_address is null
       or btrim(v_user.wallet_address) = ''
    then
        raise exception
            'USER_WALLET_NOT_CONFIGURED';
    end if;

    if v_user.country_code is null
       or btrim(v_user.country_code) = ''
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    return query
    select
        v_user.wallet_address,
        v_user.country_code;
end;
$$;
ALTER FUNCTION "public"."fetch_my_loan_preview_context"() OWNER TO "postgres";
