CREATE OR REPLACE FUNCTION "public"."fetch_my_loyalty_badges"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user_id text;
    v_rows jsonb := '[]'::jsonb;
    v_total integer := 0;
    v_earned integer := 0;
begin
    v_user_id := auth.uid()::text;

    if v_user_id is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    with badge_rows as materialized (
        select
            badge_record.id,
            badge_record.badge_code,
            badge_record.name,
            badge_record.description,
            badge_record.category::text as category,
            badge_record.icon_key,
            badge_record.sort_order,
            badge_record.is_secret,
            user_badge_record.id as user_badge_id,
            user_badge_record.awarded_at,
            user_badge_record.id is not null as is_earned,
            least(
                coalesce(progress_record.current_value, 0),
                badge_record.target_value
            ) as current_value,
            badge_record.target_value,
            least(
                round(
                    (
                        least(
                            coalesce(progress_record.current_value, 0),
                            badge_record.target_value
                        )::numeric /
                        badge_record.target_value::numeric
                    ) * 100,
                    2
                ),
                100
            ) as progress_percent
        from public.loyalty_badge badge_record
        left join public.loyalty_badge_progress progress_record
          on progress_record.badge_id = badge_record.id
         and progress_record.user_id = v_user_id
        left join public.user_badge user_badge_record
          on user_badge_record.badge_id = badge_record.id
         and user_badge_record.user_id = v_user_id
        where badge_record.is_active = true
          and (
              badge_record.valid_from is null
              or badge_record.valid_from <= now()
          )
          and (
              badge_record.valid_until is null
              or badge_record.valid_until > now()
          )
          and (
              badge_record.is_secret = false
              or user_badge_record.id is not null
          )
    )
    select
        count(*)::integer,
        count(*) filter (where badge_row.is_earned)::integer,
        coalesce(
            jsonb_agg(
                to_jsonb(badge_row)
                order by
                    badge_row.is_earned desc,
                    badge_row.sort_order,
                    badge_row.id
            ),
            '[]'::jsonb
        )
    into v_total, v_earned, v_rows
    from badge_rows badge_row;

    return jsonb_build_object(
        'rows', v_rows,
        'summary', jsonb_build_object(
            'total', v_total,
            'earned', v_earned,
            'remaining', greatest(v_total - v_earned, 0)
        )
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_loyalty_badges"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_loyalty_ledger"("p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user_id text;
    v_offset integer;
    v_total_entries bigint := 0;
    v_total_pages integer := 1;
    v_rows jsonb := '[]'::jsonb;
begin
    v_user_id := auth.uid()::text;

    if v_user_id is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if p_page is null or p_page < 1 then
        raise exception 'INVALID_PAGE';
    end if;

    if p_page_size is null
       or p_page_size < 1
       or p_page_size > 100
    then
        raise exception 'INVALID_PAGE_SIZE';
    end if;

    v_offset := (p_page - 1) * p_page_size;

    select count(*)::bigint
    into v_total_entries
    from public.loyalty_ledger ledger_record
    where ledger_record.user_id = v_user_id;

    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id', ledger_record.id,
                'event_id', ledger_record.event_id,
                'ledger_type', ledger_record.ledger_type,
                'event_type', ledger_record.event_type,
                'points_delta', ledger_record.points_delta,
                'available_balance_after',
                    ledger_record.available_balance_after,
                'tier_points_delta',
                    ledger_record.tier_points_delta,
                'tier_balance_after',
                    ledger_record.tier_balance_after,
                'source_reference',
                    ledger_record.source_reference,
                'description', ledger_record.description,
                'reversal_of_ledger_id',
                    ledger_record.reversal_of_ledger_id,
                'metadata', ledger_record.metadata,
                'created_at', ledger_record.created_at
            )
            order by
                ledger_record.created_at desc,
                ledger_record.id desc
        ),
        '[]'::jsonb
    )
    into v_rows
    from (
        select ledger_source.*
        from public.loyalty_ledger ledger_source
        where ledger_source.user_id = v_user_id
        order by
            ledger_source.created_at desc,
            ledger_source.id desc
        limit p_page_size
        offset v_offset
    ) ledger_record;

    v_total_pages := greatest(
        ceil(
            v_total_entries::numeric /
            p_page_size::numeric
        )::integer,
        1
    );

    return jsonb_build_object(
        'rows', v_rows,
        'pagination', jsonb_build_object(
            'page', p_page,
            'page_size', p_page_size,
            'total_entries', v_total_entries,
            'total_pages', v_total_pages,
            'has_previous', p_page > 1,
            'has_next', p_page < v_total_pages
        )
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_loyalty_ledger"("p_page" integer, "p_page_size" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_loyalty_summary"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user_id text;
    v_account public.loyalty_account%rowtype;
    v_level public.loyalty_level%rowtype;
    v_next_level public.loyalty_level%rowtype;

    v_available_points bigint := 0;
    v_tier_points bigint := 0;
    v_lifetime_earned_points bigint := 0;
    v_progress_points bigint := 0;
    v_level_span bigint;
    v_points_to_next bigint := 0;
    v_progress_percent numeric := 100;
begin
    v_user_id := auth.uid()::text;

    if v_user_id is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    perform 1
    from public.users user_record
    where user_record.id = v_user_id
      and user_record.status::text = 'active';

    if not found then
        raise exception using
            errcode = '42501',
            message = 'USER_NOT_ACTIVE';
    end if;

    select account_record.*
    into v_account
    from public.loyalty_account account_record
    where account_record.user_id = v_user_id
      and account_record.is_active = true;

    if found then
        v_available_points := v_account.available_points;
        v_tier_points := v_account.tier_points;
        v_lifetime_earned_points :=
            v_account.lifetime_earned_points;

        select level_record.*
        into v_level
        from public.loyalty_level level_record
        where level_record.level_code = v_account.level_code
          and level_record.is_active = true;
    else
        select level_record.*
        into v_level
        from public.loyalty_level level_record
        where level_record.is_active = true
        order by
            level_record.min_tier_points,
            level_record.sort_order,
            level_record.id
        limit 1;
    end if;

    if not found then
        raise exception 'ACTIVE_LOYALTY_LEVEL_NOT_FOUND';
    end if;

    select level_record.*
    into v_next_level
    from public.loyalty_level level_record
    where level_record.is_active = true
      and level_record.min_tier_points > v_level.min_tier_points
    order by
        level_record.min_tier_points,
        level_record.sort_order,
        level_record.id
    limit 1;

    if found then
        v_progress_points := greatest(
            v_tier_points - v_level.min_tier_points,
            0
        );

        v_level_span :=
            v_next_level.min_tier_points -
            v_level.min_tier_points;

        v_points_to_next := greatest(
            v_next_level.min_tier_points - v_tier_points,
            0
        );

        v_progress_percent :=
            case
                when v_level_span <= 0 then 100
                else least(
                    round(
                        (
                            v_progress_points::numeric /
                            v_level_span::numeric
                        ) * 100,
                        2
                    ),
                    100
                )
            end;
    else
        v_progress_points := 0;
        v_points_to_next := 0;
        v_progress_percent := 100;
    end if;

    return jsonb_build_object(
        'user_id', v_user_id,
        'account_id', v_account.id,
        'available_points', v_available_points,
        'tier_points', v_tier_points,
        'lifetime_earned_points', v_lifetime_earned_points,
        'level', jsonb_build_object(
            'code', v_level.level_code,
            'name', v_level.name,
            'min_tier_points', v_level.min_tier_points,
            'max_tier_points', v_level.max_tier_points,
            'sort_order', v_level.sort_order,
            'benefits', v_level.benefits
        ),
        'next_level',
            case
                when v_next_level.id is null then null
                else jsonb_build_object(
                    'code', v_next_level.level_code,
                    'name', v_next_level.name,
                    'min_tier_points',
                        v_next_level.min_tier_points,
                    'max_tier_points',
                        v_next_level.max_tier_points,
                    'sort_order', v_next_level.sort_order,
                    'benefits', v_next_level.benefits
                )
            end,
        'progress', jsonb_build_object(
            'points_in_current_level', v_progress_points,
            'points_to_next_level', v_points_to_next,
            'percent', v_progress_percent,
            'is_highest_level', v_next_level.id is null
        ),
        'last_event_at', v_account.last_event_at,
        'updated_at', v_account.updated_at
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_loyalty_summary"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_manual_review_liquidation_job"("p_job_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
    v_user public.users%rowtype;
    v_job_id text;
    v_result jsonb;
begin
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'accounts',
            'finance'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'REPORTING_USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'REPORTING_USER_NOT_ACTIVE';
    end if;

    if nullif(
        btrim(
            v_user.country_code
        ),
        ''
    ) is null
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    v_job_id :=
        nullif(
            btrim(
                p_job_id
            ),
            ''
        );

    if v_job_id is null then
        raise exception
            'LIQUIDATION_JOB_ID_REQUIRED';
    end if;

    select jsonb_build_object(
        'queue_id',
        queue_record.id::text,

        'liquidation_job_id',
        job_record.id::text,

        'manual_review_required',
        queue_record.manual_review_required,

        'document',
        jsonb_build_object(
            'document_number',
            job_record.document_number,

            'fiscal_year',
            job_record.fiscal_year,

            'period',
            job_record.period,

            'country_code',
            lower(
                btrim(
                    job_record.country_code
                )
            )
        ),

        'customer',
        jsonb_build_object(
            'user_id',
            job_record.user_id,

            'email',
            customer_record.email,

            'phone',
            customer_record.phone,

            'first_name',
            customer_record.first_name,

            'surname',
            customer_record.surname
        ),

        'status',
        jsonb_build_object(
            'job_status',
            job_record.status::text,

            'queue_status',
            queue_record.status::text,

            'job_error',
            job_record.error_message,

            'queue_error',
            queue_record.error_message,

            'attempt_count',
            queue_record.attempt_count,

            'retry_count',
            queue_record.retry_count
        ),

        'expected_transfer',
        jsonb_build_object(
            'chain',
            'chiado',

            'transaction_type',
            'loan_liquidation',

            'from',
            queue_record.sender_wallet_address,

            'to',
            coalesce(
                nullif(
                    btrim(
                        queue_record.signed_payload ->> 'to'
                    ),
                    ''
                ),
                queue_record.receiver_wallet_address
            ),

            'currency_code',
            'gold',

            'amount',
            trim_scale(
                queue_record.collateral
            )::text,

            'raw_amount',
            nullif(
                btrim(
                    queue_record.signed_payload ->> 'parsedAmount'
                ),
                ''
            ),

            'permit_owner',
            nullif(
                btrim(
                    queue_record.signed_payload ->> 'owner'
                ),
                ''
            ),

            'permit_nonce',
            nullif(
                btrim(
                    queue_record.signed_payload ->> 'nonce'
                ),
                ''
            ),

            'permit_deadline',
            case
                when queue_record.signed_payload ->> 'deadline'
                     ~ '^[0-9]+$'
                then to_timestamp(
                    (
                        queue_record.signed_payload ->>
                        'deadline'
                    )::double precision
                )
                else null
            end,

            'permit_expired',
            case
                when queue_record.signed_payload ->> 'deadline'
                     ~ '^[0-9]+$'
                then to_timestamp(
                    (
                        queue_record.signed_payload ->>
                        'deadline'
                    )::double precision
                ) < now()
                else null
            end
        ),

        'liquidation_values',
        jsonb_build_object(
            'principal',
            trim_scale(
                job_record.total_principal
            )::text,

            'interest',
            trim_scale(
                job_record.total_interest
            )::text,

            'total_debt',
            trim_scale(
                job_record.total_debt
            )::text,

            'repayment_required',
            trim_scale(
                job_record.repayment_required
            )::text,

            'penalty_amount',
            trim_scale(
                job_record.penalty_amount
            )::text,

            'total_proceeds',
            trim_scale(
                job_record.total_required
            )::text,

            'collateral_required',
            trim_scale(
                job_record.collateral_required
            )::text,

            'gold_price',
            trim_scale(
                job_record.gold_price
            )::text
        ),

        'blockchain_evidence',
        jsonb_build_object(
            'queue_tx_hash',
            queue_record.tx_hash,

            'recorded_tx_hash',
            blockchain_record.tx_hash,

            'blockchain_transaction_id',
            blockchain_record.id,

            'transaction_status',
            blockchain_record.status,

            'chain_status',
            blockchain_record.chain_status,

            'explorer_url',
            coalesce(
                queue_record.explorer_url,
                blockchain_record.explorer_url
            ),

            'submitted_at',
            queue_record.submitted_at,

            'confirmed_at',
            queue_record.confirmed_at,

            'recorded_at',
            blockchain_record.created_at
        ),

        'timeline',
        jsonb_build_object(
            'created_at',
            queue_record.created_at,

            'processing_started_at',
            queue_record.processing_started_at,

            'last_attempt_at',
            queue_record.last_attempt_at,

            'signed_at',
            queue_record.signed_at,

            'claimed_at',
            queue_record.claimed_at
        ),

        'recommended_action',
        case
            when nullif(
                btrim(
                    queue_record.tx_hash
                ),
                ''
            ) is null
            then jsonb_build_object(
                'code',
                'VERIFY_ON_CHAIN',

                'message',
                'Search Chiado for the expected Gold transfer before changing this job.',

                'success_result',
                'A trusted service must verify and record the transaction hash, then confirm the transfer.',

                'not_found_result',
                'If the permit nonce is unchanged and no transfer exists, clear the expired signature and retry.',

                'uncertain_result',
                'If the nonce advanced but the matching transfer is not identified, keep manual review enabled.'
            )

            when queue_record.status::text = 'confirmed'
                 and blockchain_record.id is not null
            then jsonb_build_object(
                'code',
                'RESUME_ACCOUNTING',

                'message',
                'Blockchain confirmation is recorded. Resume liquidation accounting.'
            )

            else jsonb_build_object(
                'code',
                'VERIFY_STORED_TRANSACTION',

                'message',
                'Verify the stored hash, successful receipt and exact Gold transfer event before continuing.'
            )
        end,

        'verification_requirements',
        jsonb_build_array(
            'The transaction receipt succeeded on Chiado.',
            'The token contract is the configured Gold token contract.',
            'The transfer sender equals expected_transfer.from.',
            'The transfer receiver equals expected_transfer.to.',
            'The raw token amount equals expected_transfer.raw_amount.',
            'The permit nonce belongs to expected_transfer.permit_owner.'
        )
    )
    into v_result
    from public.liquidation_job
        job_record

    join public.liquidation_blockchain_queue
        queue_record
      on queue_record.liquidation_job_id =
         job_record.id::text

    left join public.users
        customer_record
      on customer_record.id =
         job_record.user_id

    left join lateral (
        select transaction_record.*
        from public.blockchain_transaction
            transaction_record
        where (
            nullif(
                btrim(
                    queue_record.tx_hash
                ),
                ''
            ) is not null

            and lower(
                transaction_record.tx_hash
            ) = lower(
                btrim(
                    queue_record.tx_hash
                )
            )
        )

        or (
            nullif(
                btrim(
                    queue_record.tx_hash
                ),
                ''
            ) is null

            and transaction_record.document_number =
                job_record.document_number

            and transaction_record.transaction_type =
                'loan_liquidation'::public."TransactionType"
        )
        order by
            transaction_record.created_at desc
        limit 1
    ) as blockchain_record
      on true

    where job_record.id::text =
          v_job_id

      and queue_record.manual_review_required = true

      and lower(
          btrim(
              job_record.country_code
          )
      ) = lower(
          btrim(
              v_user.country_code
          )
      );

    if v_result is null then
        raise exception
            'MANUAL_REVIEW_LIQUIDATION_JOB_NOT_FOUND';
    end if;

    return v_result;
end;
$_$;
ALTER FUNCTION "public"."fetch_my_manual_review_liquidation_job"("p_job_id" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_manual_review_liquidation_jobs"("p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;
    v_offset integer;
    v_total_entries integer := 0;
    v_total_pages integer := 1;
    v_rows jsonb := '[]'::jsonb;
begin
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    if not public.has_role(
        array[
            'accounts',
            'finance'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'REPORTING_USER_NOT_FOUND';
    end if;

    if v_user.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'REPORTING_USER_NOT_ACTIVE';
    end if;

    if nullif(
        btrim(
            v_user.country_code
        ),
        ''
    ) is null
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    if p_page is null
       or p_page < 1
    then
        raise exception
            'INVALID_PAGE';
    end if;

    if p_page_size is null
       or p_page_size < 1
       or p_page_size > 100
    then
        raise exception
            'INVALID_PAGE_SIZE';
    end if;

    v_offset :=
        (p_page - 1) *
        p_page_size;

    with report_rows as materialized (
        select
            queue_record.id::text
                as queue_id,

            job_record.id::text
                as liquidation_job_id,

            job_record.document_number,
            job_record.fiscal_year,
            job_record.period,

            lower(
                btrim(
                    job_record.country_code
                )
            ) as country_code,

            job_record.user_id,
            customer_record.email,
            customer_record.phone,
            customer_record.first_name,
            customer_record.surname,

            job_record.status::text
                as job_status,

            queue_record.status::text
                as queue_status,

            queue_record.sender_wallet_address
                as from_address,

            coalesce(
                nullif(
                    btrim(
                        queue_record.signed_payload ->> 'to'
                    ),
                    ''
                ),
                queue_record.receiver_wallet_address
            ) as to_address,

            trim_scale(
                queue_record.collateral
            )::text as amount,

            'gold'::text
                as currency_code,

            queue_record.tx_hash,
            queue_record.explorer_url,
            queue_record.attempt_count,
            queue_record.retry_count,
            queue_record.error_message,
            queue_record.created_at,
            queue_record.signed_at,
            queue_record.last_attempt_at,

            case
                when nullif(
                    btrim(
                        queue_record.tx_hash
                    ),
                    ''
                ) is null
                then 'VERIFY_ON_CHAIN'

                when queue_record.status::text = 'confirmed'
                     and blockchain_record.id is not null
                then 'RESUME_ACCOUNTING'

                else 'VERIFY_STORED_TRANSACTION'
            end as recommended_action,

            case
                when nullif(
                    btrim(
                        queue_record.tx_hash
                    ),
                    ''
                ) is null
                then
                    'Find and verify the Chiado transaction before retrying.'

                when queue_record.status::text = 'confirmed'
                     and blockchain_record.id is not null
                then
                    'The transfer is recorded; continue liquidation accounting.'

                else
                    'Verify the stored hash, receipt and Gold transfer event.'
            end as action_message,

            coalesce(
                queue_record.last_attempt_at,
                queue_record.signed_at,
                queue_record.created_at
            ) as review_sort_at

        from public.liquidation_blockchain_queue
            queue_record

        join public.liquidation_job
            job_record
          on job_record.id::text =
             queue_record.liquidation_job_id

        left join public.users
            customer_record
          on customer_record.id =
             job_record.user_id

        left join lateral (
            select transaction_record.id
            from public.blockchain_transaction
                transaction_record
            where nullif(
                btrim(
                    queue_record.tx_hash
                ),
                ''
            ) is not null

              and lower(
                  transaction_record.tx_hash
              ) = lower(
                  btrim(
                      queue_record.tx_hash
                  )
              )
            limit 1
        ) as blockchain_record
          on true

        where queue_record.manual_review_required = true

          and lower(
              btrim(
                  queue_record.country_code
              )
          ) = lower(
              btrim(
                  v_user.country_code
              )
          )
    ),

    page_rows as (
        select report_record.*
        from report_rows
            report_record
        order by
            report_record.review_sort_at desc,
            report_record.queue_id desc
        limit p_page_size
        offset v_offset
    )
    select
        (
            select count(*)::integer
            from report_rows
        ),

        coalesce(
            (
                select jsonb_agg(
                    to_jsonb(page_record) - 'review_sort_at'
                    order by
                        page_record.review_sort_at desc,
                        page_record.queue_id desc
                )
                from page_rows
                    page_record
            ),
            '[]'::jsonb
        )
    into
        v_total_entries,
        v_rows;

    v_total_pages :=
        greatest(
            ceil(
                v_total_entries::numeric /
                p_page_size
            )::integer,
            1
        );

    return jsonb_build_object(
        'rows',
        v_rows,

        'pagination',
        jsonb_build_object(
            'page',
            p_page,

            'page_size',
            p_page_size,

            'total_entries',
            v_total_entries,

            'total_pages',
            v_total_pages,

            'has_previous',
            p_page > 1,

            'has_next',
            p_page < v_total_pages
        )
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_manual_review_liquidation_jobs"("p_page" integer, "p_page_size" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_merchant_payment_context"("p_v" "text", "p_merchant_id" "text") RETURNS TABLE("payer_id" "text", "merchant_id" "text", "country_code" "text", "payer_wallet_address" "text", "merchant_wallet_address" "text", "version_time" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_payer public.users%rowtype;
    v_merchant public.users%rowtype;

    v_merchant_id text;
    v_version_time bigint;
begin
    /*
     * Authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Merchant payment uses transaction version v4.
     */
    if p_v is distinct from 'v4' then
        raise exception using
            errcode = '42501',
            message = 'OPERATION_NOT_ALLOWED';
    end if;

    /*
     * Validate and normalize the payment receiver ID.
     */
    v_merchant_id :=
        nullif(
            btrim(
                p_merchant_id
            ),
            ''
        );

    if v_merchant_id is null then
        raise exception
            'MERCHANT_ID_IS_REQUIRED';
    end if;

    /*
     * Validate the authenticated payer role.
     *
     * Customers, vendors and agents may make merchant
     * payments.
     */
    if not public.has_role(
        array[
            'customer',
            'vendor',
            'agent'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Fetch the authenticated payer.
     */
    select payer_record.*
    into v_payer
    from public.users payer_record
    where payer_record.id =
          auth.uid()::text
    limit 1;

    if not found then
        raise exception
            'PAYER_NOT_FOUND';
    end if;

    /*
     * Fetch the payment receiver.
     *
     * The receiver can be either a merchant or vendor.
     */
    select receiver_record.*
    into v_merchant
    from public.users receiver_record
    where receiver_record.id =
          v_merchant_id
    limit 1;

    if not found then
        raise exception
            'MERCHANT_NOT_FOUND';
    end if;

    /*
     * Validate participant status.
     */
    if v_payer.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'PAYER_NOT_ACTIVE';
    end if;

    if v_merchant.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'MERCHANT_NOT_ACTIVE';
    end if;

    /*
     * Prevent payment to the same user.
     */
    if v_payer.id =
       v_merchant.id
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    /*
     * Both participants must belong to the same country.
     */
    if lower(
        btrim(
            v_payer.country_code
        )
    ) is distinct from lower(
        btrim(
            v_merchant.country_code
        )
    ) then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    /*
     * Merchants and vendors may receive merchant
     * payments.
     */
    if not exists (
        select 1
        from public.user_role role_record
        where role_record.id =
              v_merchant.role_id

          and lower(
              role_record.name::text
          ) in (
              'merchant',
              'vendor'
          )
    ) then
        raise exception
            'INVALID_MERCHANT_ROLE';
    end if;

    /*
     * Validate country configuration.
     */
    if v_payer.country_code is null
       or btrim(
           v_payer.country_code
       ) = ''
    then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Both blockchain wallet addresses are required for
     * signature verification.
     */
    if v_payer.wallet_address is null
       or btrim(
           v_payer.wallet_address
       ) = ''
    then
        raise exception
            'PAYER_WALLET_NOT_CONFIGURED';
    end if;

    if v_merchant.wallet_address is null
       or btrim(
           v_merchant.wallet_address
       ) = ''
    then
        raise exception
            'MERCHANT_WALLET_NOT_CONFIGURED';
    end if;

    /*
     * Fetch the configured transaction-version lifetime.
     */
    select public.get_transaction_v(
        p_v
    )::bigint
    into v_version_time;

    if v_version_time is null
       or v_version_time <= 0
    then
        raise exception
            'INVALID_TRANSACTION_VERSION';
    end if;

    return query
    select
        v_payer.id,
        v_merchant.id,

        lower(
            btrim(
                v_payer.country_code
            )
        ),

        v_payer.wallet_address,
        v_merchant.wallet_address,
        v_version_time;
end;
$$;
ALTER FUNCTION "public"."fetch_my_merchant_payment_context"("p_v" "text", "p_merchant_id" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_multi_wallet_context"() RETURNS TABLE("wallet_address" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    return query
    select
        u.wallet_address::text
    from public.users u
    join public.user_role r
      on r.id = u.role_id
    where u.id = auth.uid()::text
      and u.status =
          'active'::public."UserStatus"
      and lower(r.name::text) in (
          'agent',
          'merchant',
          'vendor'
      )
    limit 1;

    if not found then
        raise exception using
            errcode = '42501',
            message =
                'MULTI_WALLET_BALANCES_NOT_AUTHORIZED';
    end if;
end;
$$;
ALTER FUNCTION "public"."fetch_my_multi_wallet_context"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_profit_and_loss"("p_start_date" "date", "p_end_date" "date", "p_currency_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_currency_code text;

    v_fiscal_year integer;

    v_currencies jsonb :=
        '{}'::jsonb;
begin
    /*
     * Authenticate and authorize.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if not public.has_role(
        array[
            'accounts',
            'finance'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Validate report period.
     */
    if p_start_date is null then
        raise exception
            'START_DATE_REQUIRED';
    end if;

    if p_end_date is null then
        raise exception
            'END_DATE_REQUIRED';
    end if;

    if p_end_date < p_start_date then
        raise exception
            'INVALID_REPORT_DATE_RANGE';
    end if;

    /*
     * Fetch the authenticated user's trusted country.
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    v_currency_code :=
        lower(
            nullif(
                btrim(p_currency_code),
                ''
            )
        );

    /*
     * Gold is excluded from this fiat Profit and Loss report.
     */
    if v_currency_code = 'gold' then
        raise exception
            'GOLD_CURRENCY_NOT_ALLOWED';
    end if;

    /*
     * Preserve the existing report behaviour by using the
     * current fiscal year for the user's country.
     */
    select fiscal_period.fiscal_year
    into v_fiscal_year
    from public.fetch_fiscal_period(
        v_user.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Build the Profit and Loss report.
     */
    with grouped_entries as (
        select
            lower(
                financial_entry_record.currency_code
            ) as currency_code,

            financial_entry_record.gl_account_code,

            coalesce(
                gl_account_record.description,
                ''
            ) as gl_account_name,

            lower(
                gl_account_record.type::text
            ) as account_type,

            coalesce(
                sum(
                    financial_entry_record.debit
                ),
                0
            ) as debit,

            coalesce(
                sum(
                    financial_entry_record.credit
                ),
                0
            ) as credit
        from public.financial_entry
            financial_entry_record
        join public.gl_account
            gl_account_record
          on gl_account_record.code =
             financial_entry_record.gl_account_code
        where financial_entry_record.country_code =
              v_user.country_code

          and financial_entry_record.fiscal_year =
              v_fiscal_year

          /*
           * Include the whole start and end dates.
           */
          and financial_entry_record.created_at >=
              p_start_date::timestamptz

          and financial_entry_record.created_at <
              (
                  p_end_date +
                  interval '1 day'
              )

          /*
           * Profit and Loss is fiat-only.
           */
          and lower(
              financial_entry_record.currency_code
          ) <> 'gold'

          and (
              v_currency_code is null
              or lower(
                  financial_entry_record.currency_code
              ) = v_currency_code
          )

          and lower(
              gl_account_record.type::text
          ) in (
              'revenue',
              'expense'
          )
        group by
            lower(
                financial_entry_record.currency_code
            ),

            financial_entry_record.gl_account_code,

            gl_account_record.description,

            lower(
                gl_account_record.type::text
            )
    ),

    calculated_entries as (
        select
            grouped_entry.currency_code,
            grouped_entry.gl_account_code,
            grouped_entry.gl_account_name,
            grouped_entry.account_type,

            case
                when grouped_entry.account_type =
                     'revenue'
                then
                    grouped_entry.credit -
                    grouped_entry.debit

                when grouped_entry.account_type =
                     'expense'
                then
                    grouped_entry.debit -
                    grouped_entry.credit

                else
                    0
            end as amount
        from grouped_entries
            grouped_entry
    ),

    currency_totals as (
        select
            calculated_entry.currency_code,

            coalesce(
                sum(
                    calculated_entry.amount
                ) filter (
                    where calculated_entry.account_type =
                          'revenue'
                ),
                0
            ) as total_revenue,

            coalesce(
                sum(
                    calculated_entry.amount
                ) filter (
                    where calculated_entry.account_type =
                          'expense'
                ),
                0
            ) as total_expense
        from calculated_entries
            calculated_entry
        group by
            calculated_entry.currency_code
    ),

    currency_results as (
        select
            currency_total.currency_code,

            coalesce(
                (
                    select jsonb_agg(
                        jsonb_build_object(
                            'gl_account_code',
                            calculated_entry.gl_account_code,

                            'gl_account_name',
                            calculated_entry.gl_account_name,

                            'amount',
                            calculated_entry.amount
                        )
                        order by
                            calculated_entry.gl_account_code
                    )
                    from calculated_entries
                        calculated_entry
                    where calculated_entry.currency_code =
                          currency_total.currency_code
                      and calculated_entry.account_type =
                          'revenue'
                ),
                '[]'::jsonb
            ) as revenue_entries,

            coalesce(
                (
                    select jsonb_agg(
                        jsonb_build_object(
                            'gl_account_code',
                            calculated_entry.gl_account_code,

                            'gl_account_name',
                            calculated_entry.gl_account_name,

                            'amount',
                            calculated_entry.amount
                        )
                        order by
                            calculated_entry.gl_account_code
                    )
                    from calculated_entries
                        calculated_entry
                    where calculated_entry.currency_code =
                          currency_total.currency_code
                      and calculated_entry.account_type =
                          'expense'
                ),
                '[]'::jsonb
            ) as expense_entries,

            currency_total.total_revenue,

            currency_total.total_expense,

            currency_total.total_revenue -
                currency_total.total_expense
                as net_income
        from currency_totals
            currency_total
    )

    select coalesce(
        jsonb_object_agg(
            currency_result.currency_code,

            jsonb_build_object(
                'revenue',
                currency_result.revenue_entries,

                'expense',
                currency_result.expense_entries,

                'totals',
                jsonb_build_object(
                    'totalRevenue',
                    currency_result.total_revenue,

                    'totalExpense',
                    currency_result.total_expense,

                    'netIncome',
                    currency_result.net_income
                )
            )
        ),
        '{}'::jsonb
    )
    into v_currencies
    from currency_results
        currency_result;

    return jsonb_build_object(
        'period',
        jsonb_build_object(
            'startDate',
            p_start_date,

            'endDate',
            p_end_date
        ),

        'currencies',
        v_currencies
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_profit_and_loss"("p_start_date" "date", "p_end_date" "date", "p_currency_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_recent_financial_transactions"("p_currency_code" "text" DEFAULT NULL::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50, "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_currency_code text;
    v_currency_record record;

    v_page integer;
    v_page_size integer;
    v_offset integer;

    v_total_entries bigint;
    v_total_pages integer;

    v_transactions jsonb;

    /*
     * The frontend expects currencies directly at the root:
     *
     * {
     *   "usd": {
     *     "pagination": {...},
     *     "transactions": [...]
     *   }
     * }
     */
    v_result jsonb :=
        '{}'::jsonb;
begin
    /*
     * Authentication and role authorization.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if not public.has_role(
        array[
            'accounts',
            'finance'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Fetch the authenticated user's country for report
     * data isolation.
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Validate pagination.
     */
    if p_page is null
       or p_page < 1
    then
        raise exception
            'INVALID_PAGE';
    end if;

    if p_page_size is null
       or p_page_size < 1
       or p_page_size > 100
    then
        raise exception
            'INVALID_PAGE_SIZE';
    end if;

    /*
     * Validate optional date range.
     */
    if p_start_date is not null
       and p_end_date is not null
       and p_end_date < p_start_date
    then
        raise exception
            'INVALID_REPORT_DATE_RANGE';
    end if;

    v_currency_code :=
        lower(
            nullif(
                btrim(p_currency_code),
                ''
            )
        );

    v_page_size :=
        p_page_size;

    /*
     * When no currency is selected, return the first page
     * independently for every currency.
     */
    v_page :=
        case
            when v_currency_code is null
                then 1
            else p_page
        end;

    v_offset :=
        (v_page - 1) *
        v_page_size;

    /*
     * Get currencies directly from financial_transaction.
     *
     * There is no dependency on country_currencies.
     */
    for v_currency_record in
        select distinct
            lower(
                financial_transaction_record.currency_code
            ) as currency_code
        from public.financial_transaction
            financial_transaction_record
        where financial_transaction_record.country_code =
              v_user.country_code

          and financial_transaction_record.currency_code
              is not null

          and btrim(
              financial_transaction_record.currency_code
          ) <> ''

          and (
              v_currency_code is null
              or lower(
                  financial_transaction_record.currency_code
              ) = v_currency_code
          )

          and (
              p_start_date is null
              or financial_transaction_record.created_at >=
                  p_start_date::timestamptz
          )

          and (
              p_end_date is null
              or financial_transaction_record.created_at <
                  (
                      p_end_date +
                      interval '1 day'
                  )
          )
        order by
            lower(
                financial_transaction_record.currency_code
            )
    loop
        /*
         * Count matching transactions for this currency.
         */
        select count(*)
        into v_total_entries
        from public.financial_transaction
            financial_transaction_record
        where financial_transaction_record.country_code =
              v_user.country_code

          and lower(
              financial_transaction_record.currency_code
          ) =
              v_currency_record.currency_code

          and (
              p_start_date is null
              or financial_transaction_record.created_at >=
                  p_start_date::timestamptz
          )

          and (
              p_end_date is null
              or financial_transaction_record.created_at <
                  (
                      p_end_date +
                      interval '1 day'
                  )
          );

        v_total_pages :=
            case
                when v_total_entries = 0
                    then 1
                else ceil(
                    v_total_entries::numeric /
                    v_page_size::numeric
                )::integer
            end;

        /*
         * Fetch the requested transaction page.
         */
        select coalesce(
            jsonb_agg(
                jsonb_build_object(
                    'fiscal_year',
                    transaction_record.fiscal_year,

                    'period',
                    transaction_record.period,

                    'created_at',
                    transaction_record.created_at,

                    'document_number',
                    transaction_record.document_number,

                    'transaction_type',
                    transaction_record.transaction_type,

                    'description',
                    transaction_record.description,

                    'gross_amount',
                    transaction_record.gross_amount
                )
                order by
                    transaction_record.created_at desc,
                    transaction_record.document_number desc
            ),
            '[]'::jsonb
        )
        into v_transactions
        from (
            select
                financial_transaction_record.fiscal_year,
                financial_transaction_record.period,
                financial_transaction_record.created_at,
                financial_transaction_record.document_number,
                financial_transaction_record.transaction_type,
                financial_transaction_record.description,
                financial_transaction_record.gross_amount
            from public.financial_transaction
                financial_transaction_record
            where financial_transaction_record.country_code =
                  v_user.country_code

              and lower(
                  financial_transaction_record.currency_code
              ) =
                  v_currency_record.currency_code

              and (
                  p_start_date is null
                  or financial_transaction_record.created_at >=
                      p_start_date::timestamptz
              )

              and (
                  p_end_date is null
                  or financial_transaction_record.created_at <
                      (
                          p_end_date +
                          interval '1 day'
                      )
              )
            order by
                financial_transaction_record.created_at desc,
                financial_transaction_record.document_number desc
            limit v_page_size
            offset v_offset
        ) as transaction_record;

        /*
         * Add the currency directly to the root object.
         */
        v_result :=
            v_result ||
            jsonb_build_object(
                v_currency_record.currency_code,

                jsonb_build_object(
                    'pagination',
                    jsonb_build_object(
                        'page',
                        v_page,

                        'page_size',
                        v_page_size,

                        'total_entries',
                        v_total_entries,

                        'total_pages',
                        v_total_pages,

                        'has_previous',
                        v_page > 1,

                        'has_next',
                        v_page < v_total_pages
                    ),

                    'transactions',
                    v_transactions
                )
            );
    end loop;

    return v_result;
end;
$$;
ALTER FUNCTION "public"."fetch_my_recent_financial_transactions"("p_currency_code" "text", "p_page" integer, "p_page_size" integer, "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_transaction_configs"() RETURNS TABLE("config_key" "text", "currency_code" "text", "percentage" numeric, "fixed_amount" numeric, "min_amount" numeric, "max_amount" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_country_code text;
begin
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    select u.country_code
    into v_country_code
    from public.users u
    join public.user_role r
      on r.id = u.role_id
    where u.id = auth.uid()::text
      and u.status =
          'active'::public."UserStatus"
      and lower(r.name) in (
          'customer',
          'treasury',
          'finance',
          'agent',
          'admin',
          'accounts',
          'merchant',
          'vendor'
      )
    limit 1;

    if not found then
        raise exception using
            errcode = '42501',
            message = 'USER_NOT_AUTHORIZED';
    end if;

    if v_country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    /*
     * Active transaction fees for every currency in the
     * authenticated user's country.
     */
    return query
    select
        lower(f.transaction_type::text),
        lower(f.currency_code),
        coalesce(f.rate, 0)::numeric,
        f.fixed_amount::numeric,
        f.min_amount::numeric,
        f.max_amount::numeric
    from public.transaction_type_fee_config f
    where f.country_code = v_country_code
      and f.is_active = true;

    /*
     * Active government taxes for the user's country.
     */
    return query
    select
        lower(t.transaction_type::text) ||
            '_tax',
        lower(t.currency_code),
        coalesce(t.rate, 0)::numeric,
        t.fixed_amount::numeric,
        t.min_amount::numeric,
        t.max_amount::numeric
    from public.government_tax_config t
    where t.country_code = v_country_code
      and t.is_active = true;

    /*
     * Global gold buy spread.
     */
    return query
    select
        'gold_spread_' ||
            lower(s.direction::text),
        'gold'::text,
        coalesce(s.rate, 0)::numeric,
        null::numeric,
        null::numeric,
        null::numeric
    from public.spread_config s
    where s.direction =
          'buy'::public."SpreadDirection"
      and s.asset =
          'gold'::public."AssetType"
      and s.is_active = true
    limit 1;

    /*
     * Global gold sell spread.
     */
    return query
    select
        'gold_spread_' ||
            lower(s.direction::text),
        'gold'::text,
        coalesce(s.rate, 0)::numeric,
        null::numeric,
        null::numeric,
        null::numeric
    from public.spread_config s
    where s.direction =
          'sell'::public."SpreadDirection"
      and s.asset =
          'gold'::public."AssetType"
      and s.is_active = true
    limit 1;
end;
$$;
ALTER FUNCTION "public"."fetch_my_transaction_configs"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_treasury_dashboard_context"() RETURNS TABLE("user_id" "text", "country_code" "text", "wallet_address" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
    /*
     * Authentication.
     */
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;

    /*
     * Fetch authenticated Treasury user
     * and blockchain wallet address.
     */
    RETURN QUERY
    SELECT
        u.id::text,
        u.country_code::text,
        u.wallet_address::text
    FROM public.users u
    JOIN public.user_role r
        ON r.id = u.role_id
    WHERE u.id = auth.uid()::text
      AND u.status =
          'active'::public."UserStatus"
      AND lower(r.name::text) = 'treasury'
    LIMIT 1;

    /*
     * Reject unauthorized Treasury access.
     */
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'TREASURY_NOT_AUTHORIZED';
    END IF;
END;
$$;
ALTER FUNCTION "public"."fetch_my_treasury_dashboard_context"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_trial_balance"("p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_currency_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;

    v_currency_code text;

    v_fiscal_year integer;

    v_currencies jsonb :=
        '{}'::jsonb;
begin
    /*
     * Authenticate and authorize.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHENTICATED';
    end if;

    if not public.has_role(
        array[
            'accounts',
            'finance'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    /*
     * Both dates must either be supplied together or omitted.
     */
    if (
        p_start_date is null
        and p_end_date is not null
    ) or (
        p_start_date is not null
        and p_end_date is null
    ) then
        raise exception
            'START_AND_END_DATE_REQUIRED_TOGETHER';
    end if;

    if p_start_date is not null
       and p_end_date < p_start_date
    then
        raise exception
            'INVALID_REPORT_DATE_RANGE';
    end if;

    /*
     * Get the trusted user country from auth.uid().
     */
    v_user :=
        public.fetch_user_by_id(
            auth.uid()::text
        );

    if v_user.id is null then
        raise exception
            'USER_NOT_FOUND';
    end if;

    if v_user.country_code is null then
        raise exception
            'USER_COUNTRY_NOT_CONFIGURED';
    end if;

    v_currency_code :=
        lower(
            nullif(
                btrim(p_currency_code),
                ''
            )
        );

    /*
     * Preserve the current fiscal-year behaviour.
     */
    select fiscal_period.fiscal_year
    into v_fiscal_year
    from public.fetch_fiscal_period(
        v_user.country_code
    ) as fiscal_period;

    if not found then
        raise exception
            'FISCAL_PERIOD_NOT_FOUND';
    end if;

    /*
     * Build the trial balance.
     */
    with grouped_entries as (
        select
            lower(
                financial_entry_record.currency_code
            ) as currency_code,

            financial_entry_record.gl_account_code,

            coalesce(
                gl_account_record.description,
                ''
            ) as gl_account_name,

            coalesce(
                sum(
                    financial_entry_record.debit
                ),
                0
            ) as total_debit,

            coalesce(
                sum(
                    financial_entry_record.credit
                ),
                0
            ) as total_credit
        from public.financial_entry
            financial_entry_record
        left join public.gl_account
            gl_account_record
          on gl_account_record.code =
             financial_entry_record.gl_account_code
        where financial_entry_record.country_code =
              v_user.country_code

          and financial_entry_record.fiscal_year =
              v_fiscal_year

          /*
           * Apply the date range only when both dates exist.
           * The whole end date is included.
           */
          and (
              p_start_date is null
              or (
                  financial_entry_record.created_at >=
                      p_start_date::timestamptz

                  and financial_entry_record.created_at <
                      (
                          p_end_date +
                          interval '1 day'
                      )
              )
          )

          /*
           * Without a selected currency, exclude Gold.
           * When explicitly selected, use that currency.
           */
          and (
              (
                  v_currency_code is null
                  and lower(
                      financial_entry_record.currency_code
                  ) <> 'gold'
              )
              or
              (
                  v_currency_code is not null
                  and lower(
                      financial_entry_record.currency_code
                  ) =
                      v_currency_code
              )
          )
        group by
            lower(
                financial_entry_record.currency_code
            ),

            financial_entry_record.gl_account_code,

            gl_account_record.description
    ),

    currency_totals as (
        select
            grouped_entry.currency_code,

            sum(
                grouped_entry.total_debit
            ) as total_debit,

            sum(
                grouped_entry.total_credit
            ) as total_credit
        from grouped_entries
            grouped_entry
        group by
            grouped_entry.currency_code
    ),

    currency_results as (
        select
            currency_total.currency_code,

            coalesce(
                (
                    select jsonb_agg(
                        jsonb_build_object(
                            'gl_account_code',
                            grouped_entry.gl_account_code,

                            'gl_account_name',
                            grouped_entry.gl_account_name,

                            'total_debit',
                            grouped_entry.total_debit,

                            'total_credit',
                            grouped_entry.total_credit
                        )
                        order by
                            grouped_entry.gl_account_code
                    )
                    from grouped_entries
                        grouped_entry
                    where grouped_entry.currency_code =
                          currency_total.currency_code
                ),
                '[]'::jsonb
            ) as accounts,

            currency_total.total_debit,

            currency_total.total_credit
        from currency_totals
            currency_total
    )

    select coalesce(
        jsonb_object_agg(
            currency_result.currency_code,

            jsonb_build_object(
                'accounts',
                currency_result.accounts,

                'totals',
                jsonb_build_object(
                    'total_debit',
                    currency_result.total_debit,

                    'total_credit',
                    currency_result.total_credit,

                    'balanced',
                    currency_result.total_debit =
                        currency_result.total_credit
                )
            )
        ),
        '{}'::jsonb
    )
    into v_currencies
    from currency_results
        currency_result;

    return jsonb_build_object(
        'currencies',
        v_currencies
    );
end;
$$;
ALTER FUNCTION "public"."fetch_my_trial_balance"("p_start_date" "date", "p_end_date" "date", "p_currency_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_user_contact_context"("p_country_code" "text") RETURNS TABLE("user_id" "text", "current_email" "text", "current_phone" "text", "country_code" "text", "country_name" "text", "calling_code" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_country_code text;

BEGIN

    -- ========================================================
    -- AUTHENTICATION
    -- ========================================================

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;


    -- ========================================================
    -- COUNTRY CODE
    --
    -- Ngoda stores country codes in lowercase.
    -- ========================================================

    IF p_country_code IS NULL
       OR btrim(p_country_code) = ''
    THEN
        RAISE EXCEPTION USING
            ERRCODE = '22023',
            MESSAGE = 'COUNTRY_CODE_MISSING';
    END IF;


    v_country_code :=
        lower(
            btrim(p_country_code)
        );


    -- ========================================================
    -- TRUSTED CONTACT CONTEXT
    --
    -- calling_code is fetched from operational_country.
    --
    -- The Edge Function uses this value to convert a local
    -- phone number to E.164.
    -- ========================================================

    RETURN QUERY
    SELECT
        user_record.id,

        user_record.email,

        user_record.phone,

        country_record.country_code,

        country_record.name,

        country_record.calling_code

    FROM public.users user_record

    JOIN public.operational_country country_record
      ON country_record.country_code =
         v_country_code

    WHERE user_record.id =
          auth.uid()::text

      AND user_record.status =
          'active'::public."UserStatus"

      AND country_record.is_active =
          true

    LIMIT 1;


    -- ========================================================
    -- CONTEXT NOT FOUND
    -- ========================================================

    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = '22023',
            MESSAGE = 'USER_CONTACT_CONTEXT_NOT_FOUND';
    END IF;

END;
$$;
ALTER FUNCTION "public"."fetch_my_user_contact_context"("p_country_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_user_details"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE

    v_user public.users%rowtype;

    v_country_name text;

    v_kyc public.user_kyc%rowtype;

    v_id_front jsonb;
    v_id_back jsonb;
    v_proof_of_address jsonb;
    v_selfie jsonb;

    v_verification_status text;

BEGIN

    -- ========================================================
    -- AUTHENTICATION
    -- ========================================================

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;


    -- ========================================================
    -- USER
    -- ========================================================

    SELECT user_record.*
    INTO v_user
    FROM public.users user_record
    WHERE user_record.id = auth.uid()::text
      AND user_record.status =
          'active'::public."UserStatus"
    LIMIT 1;


    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'USER_NOT_AUTHORIZED';
    END IF;


    -- ========================================================
    -- COUNTRY
    --
    -- Country name is not duplicated on users.
    -- It is derived from operational_country.
    -- ========================================================

    SELECT country_record.name
    INTO v_country_name
    FROM public.operational_country country_record
    WHERE lower(country_record.country_code) =
          lower(v_user.country_code)
    LIMIT 1;


    -- ========================================================
    -- CURRENT KYC PROFILE
    -- ========================================================

    SELECT kyc_record.*
    INTO v_kyc
    FROM public.user_kyc kyc_record
    WHERE kyc_record.user_id = v_user.id
      AND kyc_record.is_current = true
    ORDER BY
        kyc_record.updated_at DESC NULLS LAST,
        kyc_record.created_at DESC NULLS LAST,
        kyc_record.id DESC
    LIMIT 1;


    -- ========================================================
    -- ID FRONT
    --
    -- Latest uploaded ID front is returned.
    -- Older documents remain available for audit/history.
    -- ========================================================

    SELECT jsonb_build_object(
        'id',
            document_record.id,

        'url',
            document_record.url,

        'file_name',
            document_record.file_name,

        'status',
            document_record.status::text,

        'uploaded_at',
            document_record.uploaded_at,

        'verified_at',
            document_record.verified_at
    )
    INTO v_id_front
    FROM public.user_verification_document document_record
    WHERE document_record.user_id = v_user.id
      AND document_record.document_type =
          'id_front'::public."VerificationDocumentType"
    ORDER BY
        document_record.uploaded_at DESC,
        document_record.created_at DESC,
        document_record.id DESC
    LIMIT 1;


    -- ========================================================
    -- ID BACK
    -- ========================================================

    SELECT jsonb_build_object(
        'id',
            document_record.id,

        'url',
            document_record.url,

        'file_name',
            document_record.file_name,

        'status',
            document_record.status::text,

        'uploaded_at',
            document_record.uploaded_at,

        'verified_at',
            document_record.verified_at
    )
    INTO v_id_back
    FROM public.user_verification_document document_record
    WHERE document_record.user_id = v_user.id
      AND document_record.document_type =
          'id_back'::public."VerificationDocumentType"
    ORDER BY
        document_record.uploaded_at DESC,
        document_record.created_at DESC,
        document_record.id DESC
    LIMIT 1;


    -- ========================================================
    -- PROOF OF ADDRESS
    -- ========================================================

    SELECT jsonb_build_object(
        'id',
            document_record.id,

        'url',
            document_record.url,

        'file_name',
            document_record.file_name,

        'status',
            document_record.status::text,

        'uploaded_at',
            document_record.uploaded_at,

        'verified_at',
            document_record.verified_at
    )
    INTO v_proof_of_address
    FROM public.user_verification_document document_record
    WHERE document_record.user_id = v_user.id
      AND document_record.document_type =
          'proof_of_address'::public."VerificationDocumentType"
    ORDER BY
        document_record.uploaded_at DESC,
        document_record.created_at DESC,
        document_record.id DESC
    LIMIT 1;


    -- ========================================================
    -- SELFIE
    -- ========================================================

    SELECT jsonb_build_object(
        'id',
            document_record.id,

        'url',
            document_record.url,

        'file_name',
            document_record.file_name,

        'status',
            document_record.status::text,

        'uploaded_at',
            document_record.uploaded_at,

        'verified_at',
            document_record.verified_at
    )
    INTO v_selfie
    FROM public.user_verification_document document_record
    WHERE document_record.user_id = v_user.id
      AND document_record.document_type =
          'selfie'::public."VerificationDocumentType"
    ORDER BY
        document_record.uploaded_at DESC,
        document_record.created_at DESC,
        document_record.id DESC
    LIMIT 1;


    -- ========================================================
    -- OVERALL VERIFICATION STATUS
    --
    -- user_kyc.kyc_status is currently the overall source
    -- of truth for the user's KYC verification status.
    -- ========================================================

    IF v_kyc.id IS NOT NULL THEN
        v_verification_status :=
            v_kyc.kyc_status::text;
    ELSE
        v_verification_status := NULL;
    END IF;


    -- ========================================================
    -- RETURN
    --
    -- Structure matches:
    --
    -- UserDetails
    --   basicProfile
    --   contactDetails
    --   kycDetails
    --   verificationDocuments
    -- ========================================================

    RETURN jsonb_build_object(

        -- ====================================================
        -- USER
        -- ====================================================

        'user_id',
            v_user.id,


        -- ====================================================
        -- BASIC PROFILE
        -- ====================================================

        'basic_profile',
            jsonb_build_object(

                'first_name',
                    v_user.first_name,

                'middle_name',
                    v_user.middle_name,

                'surname',
                    v_user.surname,

                'dob',
                    v_user.dob,

                'gender',
                    v_user.gender,

                'nationality',
                    v_user.nationality
            ),


        -- ====================================================
        -- CONTACT DETAILS
        -- ====================================================

        'contact_details',
            jsonb_build_object(

                'email',
                    v_user.email,

                'phone',
                    v_user.phone,

                'country_code',
                    lower(v_user.country_code),

                'country_name',
                    v_country_name,

                'residential_address',
                    v_user.residential_address,

                'city',
                    v_user.city,

                'province_state',
                    v_user.province_state
            ),


        -- ====================================================
        -- KYC DETAILS
        -- ====================================================

        'kyc_details',
            jsonb_build_object(

                'id_type',
                    v_kyc.id_type::text,

                'id_number',
                    v_kyc.id_number,

                'expiry_date',
                    v_kyc.expiry_date,

                'occupation',
                    v_kyc.occupation,

                'source_of_funds',
                    v_kyc.source_of_funds,

                'tax_number',
                    v_kyc.tax_number,

                'kyc_status',
                    v_kyc.kyc_status::text
            ),


        -- ====================================================
        -- VERIFICATION DOCUMENTS
        -- ====================================================

        'verification_documents',
            jsonb_build_object(

                'id_front',
                    v_id_front,

                'id_back',
                    v_id_back,

                'proof_of_address',
                    v_proof_of_address,

                'selfie',
                    v_selfie,

                'verification_status',
                    v_verification_status
            )

    );

END;
$$;
ALTER FUNCTION "public"."fetch_my_user_details"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_vendor_dashboard_context"() RETURNS TABLE("wallet_address" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
    /*
     * Authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Return the authenticated active vendor's
     * blockchain wallet address.
     */
    return query
    select
        user_record.wallet_address
    from public.users
        user_record
    join public.user_role
        role_record
      on role_record.id =
         user_record.role_id
    where user_record.id =
              auth.uid()::text

      and user_record.status =
              'active'::public."UserStatus"

      and lower(
          role_record.name::text
      ) =
              'vendor'
    limit 1;

    if not found then
        raise exception using
            errcode = '42501',
            message = 'VENDOR_NOT_AUTHORIZED';
    end if;
end;
$$;
ALTER FUNCTION "public"."fetch_my_vendor_dashboard_context"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_my_voucher_payment_context"("p_v" "text", "p_voucher_owner_id" "text") RETURNS TABLE("merchant_id" "text", "country_code" "text", "merchant_wallet_address" "text", "voucher_owner_wallet_address" "text", "version_time" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_merchant public.users%rowtype;
    v_voucher_owner public.users%rowtype;
    v_version_time numeric;
begin
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Merchants and vendors can accept voucher payments.
     * A vendor may operate a merchant-owned wallet.
     */
    if not public.has_role(
        array[
            'merchant',
            'vendor'
        ]::text[]
    ) then
        raise exception using
            errcode = '42501',
            message = 'FORBIDDEN';
    end if;

    select user_record.*
    into v_merchant
    from public.users user_record
    where user_record.id =
          auth.uid()::text
    limit 1;

    if not found then
        raise exception 'MERCHANT_NOT_FOUND';
    end if;

    if v_merchant.status <>
       'active'::public."UserStatus"
    then
        raise exception 'MERCHANT_NOT_ACTIVE';
    end if;

    if v_merchant.country_code is null
       or btrim(v_merchant.country_code) = ''
    then
        raise exception
            'MERCHANT_COUNTRY_NOT_CONFIGURED';
    end if;

    if v_merchant.wallet_address is null
       or btrim(v_merchant.wallet_address) = ''
    then
        raise exception
            'MERCHANT_WALLET_NOT_CONFIGURED';
    end if;

    if p_voucher_owner_id is null
       or btrim(p_voucher_owner_id) = ''
    then
        raise exception
            'VOUCHER_OWNER_ID_MISSING';
    end if;

    select user_record.*
    into v_voucher_owner
    from public.users user_record
    where user_record.id =
          btrim(p_voucher_owner_id)
    limit 1;

    if not found then
        raise exception
            'VOUCHER_OWNER_NOT_FOUND';
    end if;

    if v_voucher_owner.status <>
       'active'::public."UserStatus"
    then
        raise exception
            'VOUCHER_OWNER_NOT_ACTIVE';
    end if;

    if v_voucher_owner.wallet_address is null
       or btrim(v_voucher_owner.wallet_address) = ''
    then
        raise exception
            'VOUCHER_OWNER_WALLET_NOT_CONFIGURED';
    end if;

    if v_voucher_owner.country_code is distinct from
       v_merchant.country_code
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    if v_voucher_owner.id =
       v_merchant.id
    then
        raise exception
            'OPERATION_NOT_ALLOWED';
    end if;

    v_version_time :=
        public.get_transaction_v(p_v);

    if v_version_time is null then
        raise exception
            'TRANSACTION_VERSION_NOT_FOUND';
    end if;

    return query
    select
        v_merchant.id,
        v_merchant.country_code,
        v_merchant.wallet_address,
        v_voucher_owner.wallet_address,
        v_version_time;
end;
$$;
ALTER FUNCTION "public"."fetch_my_voucher_payment_context"("p_v" "text", "p_voucher_owner_id" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."fetch_opening_wallet_snapshot"("p_user_id" "text", "p_currency_code" "text", "p_wallet_owner" "public"."WalletOwnerType", "p_fiscal_year" integer, "p_period" integer, "p_blockchain_code" "text" DEFAULT NULL::"text") RETURNS TABLE("user_id" "text", "currency_code" "text", "wallet_owner" "public"."WalletOwnerType", "fiscal_year" integer, "period" integer, "opening_balance" numeric, "debit" numeric, "credit" numeric, "closing_balance" numeric)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
    v_snapshot public.wallet_balance_snapshot%rowtype;
    v_currency_code text;
    v_blockchain_code text;
begin
    v_currency_code :=
        nullif(lower(btrim(p_currency_code)), '');

    v_blockchain_code :=
        nullif(lower(btrim(p_blockchain_code)), '');

    if v_currency_code is null then
        raise exception 'CURRENCY_IS_REQUIRED';
    end if;

    if v_currency_code = 'gold'
       and v_blockchain_code is null
    then
        raise exception 'BLOCKCHAIN_CODE_IS_REQUIRED';
    end if;

    /*
     * Snapshot for the requested period.
     */
    select s.*
    into v_snapshot
    from public.wallet_balance_snapshot s
    where s.user_id = p_user_id
      and lower(btrim(s.currency_code)) = v_currency_code
      and s.wallet_owner = p_wallet_owner
      and s.fiscal_year = p_fiscal_year
      and s.period = p_period
      and (
          v_currency_code <> 'gold'
          or lower(btrim(s.blockchain_code)) = v_blockchain_code
      )
    limit 1;

    if found then
        return query
        select
            v_snapshot.user_id,
            v_snapshot.currency_code,
            v_snapshot.wallet_owner,
            v_snapshot.fiscal_year,
            v_snapshot.period,
            coalesce(v_snapshot.opening_balance, 0),
            coalesce(v_snapshot.debit, 0),
            coalesce(v_snapshot.credit, 0),
            coalesce(v_snapshot.closing_balance, 0);
        return;
    end if;

    /*
     * Most recent snapshot in the same fiscal year.
     */
    select s.*
    into v_snapshot
    from public.wallet_balance_snapshot s
    where s.user_id = p_user_id
      and lower(btrim(s.currency_code)) = v_currency_code
      and s.wallet_owner = p_wallet_owner
      and s.fiscal_year = p_fiscal_year
      and s.period < p_period
      and (
          v_currency_code <> 'gold'
          or lower(btrim(s.blockchain_code)) = v_blockchain_code
      )
    order by s.period desc
    limit 1;

    /*
     * Most recent snapshot in a previous fiscal year.
     */
    if not found then
        select s.*
        into v_snapshot
        from public.wallet_balance_snapshot s
        where s.user_id = p_user_id
          and lower(btrim(s.currency_code)) = v_currency_code
          and s.wallet_owner = p_wallet_owner
          and s.fiscal_year < p_fiscal_year
          and (
              v_currency_code <> 'gold'
              or lower(btrim(s.blockchain_code)) = v_blockchain_code
          )
        order by s.fiscal_year desc, s.period desc
        limit 1;
    end if;

    if found then
        return query
        select
            p_user_id,
            v_currency_code,
            p_wallet_owner,
            p_fiscal_year,
            p_period,
            coalesce(v_snapshot.closing_balance, 0),
            0::numeric,
            0::numeric,
            coalesce(v_snapshot.closing_balance, 0);
        return;
    end if;

    /*
     * No current or previous snapshot.
     */
    return query
    select
        p_user_id,
        v_currency_code,
        p_wallet_owner,
        p_fiscal_year,
        p_period,
        0::numeric,
        0::numeric,
        0::numeric,
        0::numeric;
end;
$$;
ALTER FUNCTION "public"."fetch_opening_wallet_snapshot"("p_user_id" "text", "p_currency_code" "text", "p_wallet_owner" "public"."WalletOwnerType", "p_fiscal_year" integer, "p_period" integer, "p_blockchain_code" "text") OWNER TO "postgres";
