CREATE OR REPLACE FUNCTION "public"."fetch_spread_by_direction"("p_direction" "public"."SpreadDirection", "p_asset" "public"."AssetType") RETURNS TABLE("config_key" "text", "currency_code" "text", "percentage" numeric, "fixed_amount" numeric, "min_amount" numeric, "max_amount" numeric)
    LANGUAGE "sql" STABLE
    AS $$
    select
        'gold_spread_' || lower(s.direction::text),
        'gold'::text,
        coalesce(s.rate, 0)::numeric,
        null::numeric,
        null::numeric,
