        t.v,
        t."time"
    from public.transaction_v t;
$$;
ALTER FUNCTION "public"."get_all_transaction_v"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."get_base_transaction_type"("p_transaction_type" "public"."TransactionType") RETURNS "public"."TransactionType"
    LANGUAGE "plpgsql" IMMUTABLE STRICT PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
declare
    v_transaction_type_text text;
    v_base_transaction_type_text text;
    v_base_transaction_type
        public."TransactionType";
begin
    v_transaction_type_text :=
        p_transaction_type::text;

    /*
     * Normal transactions are already their own base type.
     */
    if v_transaction_type_text not like
       '%\_reversal' escape '\'
    then
        return p_transaction_type;
    end if;

    /*
     * Reversal transaction names follow:
     *
     * <base_transaction_type>_reversal
     */
    v_base_transaction_type_text :=
        left(
            v_transaction_type_text,
            length(v_transaction_type_text)
            - length('_reversal')
        );

    if nullif(
        btrim(v_base_transaction_type_text),
        ''
    ) is null
    then
        raise exception
            'BASE_TRANSACTION_TYPE_NOT_FOUND_%',
            upper(v_transaction_type_text);
    end if;

    /*
     * Validate that the derived base name exists in the
     * TransactionType enum.
     */
    begin
        v_base_transaction_type :=
            v_base_transaction_type_text
                ::public."TransactionType";

    exception
        when invalid_text_representation then
            raise exception
                'BASE_TRANSACTION_TYPE_NOT_FOUND_%',
                upper(v_transaction_type_text);
    end;

    return v_base_transaction_type;
end;
$$;
ALTER FUNCTION "public"."get_base_transaction_type"("p_transaction_type" "public"."TransactionType") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."get_last_wallet_transactions"("p_user_id" "text", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_currency_code" "text" DEFAULT NULL::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
    v_page integer;
    v_skip integer;
    v_result jsonb;
begin
    if p_start_date is null then
        raise exception 'START_DATE_IS_REQUIRED';
    end if;

    if p_end_date is null then
        raise exception 'END_DATE_IS_REQUIRED';
    end if;

    if p_end_date < p_start_date then
        raise exception 'INVALID_DATE_RANGE';
    end if;

    if p_page < 1 then
        raise exception 'INVALID_PAGE';
    end if;

    if p_page_size < 1 or p_page_size > 100 then
        raise exception 'INVALID_PAGE_SIZE';
    end if;

    /*
     * Without a currency, always return page one
     * for every currency.
     */
    v_page :=
        case
            when p_currency_code is null
                 or btrim(p_currency_code) = ''
            then 1
            else p_page
        end;

    v_skip := (v_page - 1) * p_page_size;

    with user_wallets as (
        select
            w.id,
            lower(btrim(w.currency_code))
                as currency_code,
            coalesce(w.balance, 0)::numeric
                as balance
        from public.wallet w
        where w.user_id = p_user_id
          and (
              p_currency_code is null
              or btrim(p_currency_code) = ''
              or lower(btrim(w.currency_code)) =
                 lower(btrim(p_currency_code))
          )
    ),

    base_entries as (
        select
            e.id,
            e.wallet_id,
            e.document_number,
            e.transaction_type,
            coalesce(e.debit, 0)::numeric
                as debit,
            coalesce(e.credit, 0)::numeric
                as credit,
            (
                coalesce(e.credit, 0) -
                coalesce(e.debit, 0)
            )::numeric as net_amount,
            e.created_at,
            wallet.currency_code,
            wallet.balance as wallet_balance

        from public.wallet_entry e
        join user_wallets wallet
          on wallet.id = e.wallet_id

        where e.created_at >= p_start_date
          and e.created_at <= p_end_date
    ),

    ordered_entries as (
        select
            entry.*,

            row_number() over (
                partition by entry.currency_code
                order by
                    entry.created_at desc,
                    entry.id desc
            ) as currency_entry_number,

            entry.wallet_balance -
            coalesce(
                sum(entry.net_amount) over (
                    partition by entry.wallet_id
                    order by
                        entry.created_at desc,
                        entry.id desc
                    rows between
                        unbounded preceding
                        and 1 preceding
                ),
                0
            ) as running_balance

        from base_entries entry
    ),

    currency_totals as (
        select
            wallet.currency_code,
            sum(wallet.balance)::numeric
                as current_balance

        from user_wallets wallet
        group by wallet.currency_code
    ),

    entry_totals as (
        select
            entry.currency_code,
            count(*)::integer
                as total_entries,
            coalesce(sum(entry.debit), 0)
                as total_debit,
            coalesce(sum(entry.credit), 0)
                as total_credit

        from ordered_entries entry
        group by entry.currency_code
    ),

    currency_results as (
        select
            currency.currency_code,

            jsonb_build_object(
                'balance',
                currency.current_balance::text,

                'total_debit',
                coalesce(
                    totals.total_debit,
                    0
                )::text,

                'total_credit',
                coalesce(
                    totals.total_credit,
                    0
                )::text,

                /*
                 * Balance after reversing transactions
                 * newer than the requested page.
                 */
                'page_closing_balance',
                (
                    currency.current_balance -
                    coalesce(
                        (
                            select sum(entry.net_amount)
                            from ordered_entries entry
                            where entry.currency_code =
                                  currency.currency_code
                              and entry.currency_entry_number <=
                                  v_skip
                        ),
                        0
                    )
                )::text,

                /*
                 * Balance after reversing every transaction
                 * included on this page.
                 */
                'page_opening_balance',
                (
                    currency.current_balance -
                    coalesce(
                        (
                            select sum(entry.net_amount)
                            from ordered_entries entry
                            where entry.currency_code =
                                  currency.currency_code
                              and entry.currency_entry_number <=
                                  v_skip + p_page_size
                        ),
                        0
                    )
                )::text,

                'pagination',
                jsonb_build_object(
                    'page',
                    v_page,

                    'page_size',
                    p_page_size,

                    'total_entries',
                    coalesce(
                        totals.total_entries,
                        0
                    ),

                    'total_pages',
                    greatest(
                        1,
                        ceil(
                            coalesce(
                                totals.total_entries,
                                0
                            )::numeric /
                            p_page_size::numeric
                        )::integer
                    ),

                    'has_previous',
                    v_page > 1,

                    'has_next',
                    v_page <
                    greatest(
                        1,
                        ceil(
                            coalesce(
                                totals.total_entries,
                                0
                            )::numeric /
                            p_page_size::numeric
                        )::integer
                    )
                ),

                'transactions',
                coalesce(
                    (
                        select jsonb_agg(
                            jsonb_build_object(
                                'id',
                                entry.id::text,

                                'document_number',
                                entry.document_number,

                                'transaction_type',
                                entry.transaction_type::text,

                                'debit',
                                entry.debit::text,

                                'credit',
                                entry.credit::text,

                                'running_balance',
                                entry.running_balance::text,

                                'created_at',
                                entry.created_at
                            )
                            order by
                                entry.created_at desc,
                                entry.id desc
                        )
                        from ordered_entries entry
                        where entry.currency_code =
                              currency.currency_code
                          and entry.currency_entry_number >
                              v_skip
                          and entry.currency_entry_number <=
                              v_skip + p_page_size
                    ),
                    '[]'::jsonb
                )
            ) as statement

        from currency_totals currency

        left join entry_totals totals
          on totals.currency_code =
             currency.currency_code
    )

    select coalesce(
        jsonb_object_agg(
            currency_code,
            statement
            order by currency_code
        ),
        '{}'::jsonb
    )
    into v_result
    from currency_results;

    return v_result;
end;
$$;
ALTER FUNCTION "public"."get_last_wallet_transactions"("p_user_id" "text", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_currency_code" "text", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."get_multi_wallet_balances"("p_user_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
    v_missing_currency text;
    v_result jsonb;
begin
    /*
     * Validate that every non-USD wallet has an active rate.
     */
    select lower(btrim(w.currency_code))
    into v_missing_currency
    from public.wallet w
    left join public.current_rates r
        on lower(btrim(r.code)) =
           lower(btrim(w.currency_code))
    where w.user_id = p_user_id
      and w.owner_type in (
          'merchant'::public."WalletOwnerType",
          'customer'::public."WalletOwnerType",
          'agent'::public."WalletOwnerType"
      )
      and lower(btrim(w.currency_code)) <> 'usd'
      and (
          r.code is null
          or r.rate_to_usd is null
          or r.rate_to_usd <= 0
      )
    limit 1;

    if found then
        raise exception
            'MISSING_RATE_FOR_CURRENCY_%',
            upper(v_missing_currency);
    end if;

    with wallet_values as (
        select
            w.owner_type,
            lower(btrim(w.currency_code))
                as currency_code,

            coalesce(w.balance, 0)::numeric
                as balance,

            case
                when lower(btrim(w.currency_code)) = 'usd'
                then coalesce(w.balance, 0)::numeric

                when lower(btrim(w.currency_code)) = 'gold'
                then
                    coalesce(w.balance, 0)::numeric *
                    r.rate_to_usd::numeric

                else
                    coalesce(w.balance, 0)::numeric /
                    r.rate_to_usd::numeric
            end as usd_value

        from public.wallet w
        left join public.current_rates r
            on lower(btrim(r.code)) =
               lower(btrim(w.currency_code))

        where w.user_id = p_user_id
          and w.owner_type in (
              'merchant'::public."WalletOwnerType",
              'customer'::public."WalletOwnerType",
              'agent'::public."WalletOwnerType"
          )
    ),

    owner_summaries as (
        select
            owner_type,

            jsonb_agg(
                jsonb_build_object(
                    'currency_code',
                    currency_code,

                    'balance',
                    balance::text,

                    'usd_value',
                    usd_value::text
                )
                order by currency_code
            ) as wallet_balances,

            coalesce(
                sum(usd_value),
                0
            ) as total_usd_value

        from wallet_values
        group by owner_type
    )

    select jsonb_build_object(
        'merchantWallet',
        jsonb_build_object(
            'wallet_balances',
            coalesce(
                (
                    select s.wallet_balances
                    from owner_summaries s
                    where s.owner_type =
                        'merchant'::public."WalletOwnerType"
                ),
                '[]'::jsonb
            ),

            'total_usd_value',
            coalesce(
                (
                    select s.total_usd_value
                    from owner_summaries s
                    where s.owner_type =
                        'merchant'::public."WalletOwnerType"
                ),
                0
            )::text
        ),

        'customerWallet',
        jsonb_build_object(
            'wallet_balances',
            coalesce(
                (
                    select s.wallet_balances
                    from owner_summaries s
                    where s.owner_type =
                        'customer'::public."WalletOwnerType"
                ),
                '[]'::jsonb
            ),

            'total_usd_value',
            coalesce(
                (
                    select s.total_usd_value
                    from owner_summaries s
                    where s.owner_type =
                        'customer'::public."WalletOwnerType"
                ),
                0
            )::text
        ),

        'agentWallet',
        jsonb_build_object(
            'wallet_balances',
            coalesce(
                (
                    select s.wallet_balances
                    from owner_summaries s
                    where s.owner_type =
                        'agent'::public."WalletOwnerType"
                ),
                '[]'::jsonb
            ),

            'total_usd_value',
            coalesce(
                (
                    select s.total_usd_value
                    from owner_summaries s
                    where s.owner_type =
                        'agent'::public."WalletOwnerType"
                ),
                0
            )::text
        )
    )
    into v_result;

    return v_result;
end;
$$;
ALTER FUNCTION "public"."get_multi_wallet_balances"("p_user_id" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."get_my_financial_badges"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_user_id text;
    v_result jsonb;
BEGIN

    -- ==========================================================
    -- AUTHENTICATION
    -- ==========================================================

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;


    -- ==========================================================
    -- VALIDATE CUSTOMER
    -- ==========================================================


    SELECT
        u.id
    INTO
        v_user_id
    FROM public.users AS u
    JOIN public.user_role AS r
        ON r.id = u.role_id
    WHERE u.id = auth.uid()::text
    AND u.status = 'active'::public."UserStatus"
    AND lower(r.name::text) IN (
        'customer',
        'vendor',
        'agent'
    )
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'FINANCIAL_BEHAVIOUR_NOT_AUTHORIZED';
    END IF;

    -- ==========================================================
    -- BUILD BADGE REPORT
    --
    -- Returns every active badge definition together with
    -- the authenticated user's achievement information.
    --
    -- An unearned badge remains in the response with:
    --
    -- earned = false
    -- achieved_value_usd = null
    -- fiscal_year = null
    -- period = null
    -- achieved_at = null
    -- ==========================================================

    SELECT
        jsonb_build_object(

            'badges',

            COALESCE(
                jsonb_agg(
                    jsonb_build_object(

                        'id',
                            b.id,

                        'code',
                            b.code,

                        'behavior',
                            b.behavior,

                        'metric',
                            b.metric,

                        'level',
                            b.level,

                        'threshold_usd',
                            b.threshold_usd,

                        'name',
                            b.name,

                        'description',
                            b.description,

                        'earned',
                            ub.id IS NOT NULL,

                        'achieved_value_usd',
                            ub.achieved_value_usd,

                        'fiscal_year',
                            ub.fiscal_year,

                        'period',
                            ub.period,

                        'achieved_at',
                            ub.achieved_at
                    )
                    ORDER BY
                        b.behavior,
                        b.level,
                        b.threshold_usd
                ),
                '[]'::jsonb
            )
        )
    INTO
        v_result
    FROM public.financial_badge AS b

    LEFT JOIN public.user_financial_badge AS ub
        ON ub.badge_id = b.id
       AND ub.user_id = v_user_id

    WHERE b.is_active = true;


    -- ==========================================================
    -- RETURN
    -- ==========================================================

    RETURN COALESCE(
        v_result,
        jsonb_build_object(
            'badges',
            '[]'::jsonb
        )
    );

END;
$$;
ALTER FUNCTION "public"."get_my_financial_badges"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."get_my_financial_periods"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_user_id text;
    v_country_code text;

    v_fiscal_year integer;
    v_current_period integer;

    v_fiscal_year_behavior
        public.financial_behavior_type :=
            'neutral'::public.financial_behavior_type;

    v_fiscal_year_shopper_score numeric := 0;
    v_fiscal_year_saver_score numeric := 0;
    v_fiscal_year_investor_score numeric := 0;
    v_fiscal_year_borrower_score numeric := 0;

    v_periods jsonb;

BEGIN

    /*
     * ==========================================================
     * AUTHENTICATION
     * ==========================================================
     */

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;


    /*
     * ==========================================================
     * AUTHORIZED USER + COUNTRY
     * ==========================================================
     */

    SELECT
        u.id,
        lower(u.country_code)
    INTO
        v_user_id,
        v_country_code
    FROM public.users AS u

    JOIN public.user_role AS r
        ON r.id = u.role_id

    WHERE u.id = auth.uid()::text

      AND u.status =
          'active'::public."UserStatus"

      AND lower(r.name::text) IN (
          'customer',
          'vendor',
          'agent'
      )

    LIMIT 1;


    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'FINANCIAL_BEHAVIOUR_NOT_AUTHORIZED';
    END IF;


    IF v_country_code IS NULL
       OR trim(v_country_code) = ''
    THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'USER_COUNTRY_NOT_FOUND';
    END IF;


    /*
     * ==========================================================
     * CURRENT FISCAL YEAR / PERIOD
     * ==========================================================
     */

    SELECT
        fiscal_period.fiscal_year,
        fiscal_period.period
    INTO
        v_fiscal_year,
        v_current_period
    FROM public.fetch_fiscal_period(
        v_country_code
    ) AS fiscal_period;


    IF NOT FOUND
       OR v_fiscal_year IS NULL
       OR v_current_period IS NULL
    THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE = 'FISCAL_PERIOD_NOT_FOUND';
    END IF;


    /*
     * ==========================================================
     * FISCAL-YEAR / ALL-CURRENCY BEHAVIOR
     * ==========================================================
     */

    SELECT
        fb.behavior,

        COALESCE(
            fb.shopper_score_percentage,
            0
        ),

        COALESCE(
            fb.saver_score_percentage,
            0
        ),

        COALESCE(
            fb.investor_score_percentage,
            0
        ),

        COALESCE(
            fb.borrower_score_percentage,
            0
        )

    INTO
        v_fiscal_year_behavior,
        v_fiscal_year_shopper_score,
        v_fiscal_year_saver_score,
        v_fiscal_year_investor_score,
        v_fiscal_year_borrower_score

    FROM public.financial_behavior AS fb

    WHERE fb.user_id = v_user_id

      AND fb.country_code = v_country_code

      AND fb.fiscal_year = v_fiscal_year

      AND fb.scope =
          'fiscal_year'::public.financial_behavior_scope

      AND fb.period IS NULL

      AND fb.currency_code IS NULL

    LIMIT 1;


    IF NOT FOUND THEN

        v_fiscal_year_behavior :=
            'neutral'::public.financial_behavior_type;

        v_fiscal_year_shopper_score := 0;
        v_fiscal_year_saver_score := 0;
        v_fiscal_year_investor_score := 0;
        v_fiscal_year_borrower_score := 0;

    END IF;


    /*
     * ==========================================================
     * BUILD PERIOD RESPONSE
     * ==========================================================
     */

    WITH periods AS (

        /*
         * Always return P1 - P12.
         */
        SELECT
            generate_series(
                1,
                12
            ) AS period

    ),


    /*
     * ==========================================================
     * FINANCIAL POT SNAPSHOT BY PERIOD / CURRENCY
     * ==========================================================
     *
     * financial_pot is now the reporting source of truth.
     *
     * financial_pot_event is deliberately NOT consulted by this
     * report.
     * ==========================================================
     */

    currency_rows AS (

        SELECT
            fp.period,

            lower(
                fp.currency_code
            ) AS currency_code,


            /*
             * --------------------------------------------------
             * DEPOSIT
             * --------------------------------------------------
             */

            COALESCE(
                SUM(fp.deposit_amount),
                0
            ) AS deposit_amount,

            COALESCE(
                SUM(fp.deposit_amount_usd),
                0
            ) AS deposit_amount_usd,


            /*
             * --------------------------------------------------
             * MONEY IN SNAPSHOTS
             * --------------------------------------------------
             */

            COALESCE(
                SUM(fp.cash_in_amount),
                0
            ) AS cash_in_amount,

            COALESCE(
                SUM(fp.cash_in_amount_usd),
                0
            ) AS cash_in_amount_usd,

            COALESCE(
                SUM(fp.transfer_in_amount),
                0
            ) AS transfer_in_amount,

            COALESCE(
                SUM(fp.transfer_in_amount_usd),
                0
            ) AS transfer_in_amount_usd,

            COALESCE(
                SUM(fp.investment_proceeds_amount),
                0
            ) AS investment_proceeds_amount,

            COALESCE(
                SUM(fp.investment_proceeds_amount_usd),
                0
            ) AS investment_proceeds_amount_usd,


            /*
             * --------------------------------------------------
             * WITHDRAWAL
             * --------------------------------------------------
             */

            COALESCE(
                SUM(fp.withdrawal_amount),
                0
            ) AS withdrawal_amount,

            COALESCE(
                SUM(fp.withdrawal_amount_usd),
                0
            ) AS withdrawal_amount_usd,

            COALESCE(
                SUM(fp.withdrawal_cash_amount),
                0
            ) AS withdrawal_cash_amount,

            COALESCE(
                SUM(fp.withdrawal_cash_amount_usd),
                0
            ) AS withdrawal_cash_amount_usd,


            /*
             * --------------------------------------------------
             * SPENDING
             * --------------------------------------------------
             */

            COALESCE(
                SUM(fp.spending_amount),
                0
            ) AS spending_amount,

            COALESCE(
                SUM(fp.spending_amount_usd),
                0
            ) AS spending_amount_usd,

            COALESCE(
                SUM(fp.spending_cash_amount),
                0
            ) AS spending_cash_amount,

            COALESCE(
                SUM(fp.spending_cash_amount_usd),
                0
            ) AS spending_cash_amount_usd,


            /*
             * --------------------------------------------------
             * SAVINGS
             * --------------------------------------------------
             */

            COALESCE(
                SUM(fp.opening_savings),
                0
            ) AS opening_savings,

            COALESCE(
                SUM(fp.opening_savings_usd),
                0
            ) AS opening_savings_usd,

            COALESCE(
                SUM(fp.savings_inflow),
                0
            ) AS savings_inflow,

            COALESCE(
                SUM(fp.savings_inflow_usd),
                0
            ) AS savings_inflow_usd,

            COALESCE(
                SUM(fp.savings_outflow),
                0
            ) AS savings_outflow,

            COALESCE(
                SUM(fp.savings_outflow_usd),
                0
            ) AS savings_outflow_usd,

            COALESCE(
                SUM(fp.saving_amount),
                0
            ) AS saving_amount,

            COALESCE(
                SUM(fp.saving_amount_usd),
                0
            ) AS saving_amount_usd,

            COALESCE(
                SUM(fp.closing_savings),
                0
            ) AS closing_savings,

            COALESCE(
                SUM(fp.closing_savings_usd),
                0
            ) AS closing_savings_usd,


            /*
             * --------------------------------------------------
             * INVESTMENT
             * --------------------------------------------------
             */

            COALESCE(
                SUM(fp.investment_purchase_amount),
                0
            ) AS investment_purchase_amount,

            COALESCE(
                SUM(fp.investment_purchase_amount_usd),
                0
            ) AS investment_purchase_amount_usd,

            COALESCE(
                SUM(fp.investment_sale_amount),
                0
            ) AS investment_sale_amount,

            COALESCE(
                SUM(fp.investment_sale_amount_usd),
                0
            ) AS investment_sale_amount_usd,

            COALESCE(
                SUM(fp.investment_cash_amount),
                0
            ) AS investment_cash_amount,

            COALESCE(
                SUM(fp.investment_cash_amount_usd),
                0
            ) AS investment_cash_amount_usd,


            /*
             * --------------------------------------------------
             * LOAN
             * --------------------------------------------------
             */

            COALESCE(
                SUM(fp.opening_loan_balance),
                0
            ) AS opening_loan_balance,

            COALESCE(
                SUM(fp.opening_loan_balance_usd),
                0
            ) AS opening_loan_balance_usd,

            COALESCE(
                SUM(fp.loan_disbursed_amount),
                0
            ) AS loan_disbursed_amount,

            COALESCE(
                SUM(fp.loan_disbursed_amount_usd),
                0
            ) AS loan_disbursed_amount_usd,

            COALESCE(
                SUM(fp.loan_repayment_amount),
                0
            ) AS loan_repayment_amount,

            COALESCE(
                SUM(fp.loan_repayment_amount_usd),
                0
            ) AS loan_repayment_amount_usd,

            COALESCE(
                SUM(fp.repayment_cash_amount),
                0
            ) AS repayment_cash_amount,

            COALESCE(
                SUM(fp.repayment_cash_amount_usd),
                0
            ) AS repayment_cash_amount_usd,

            COALESCE(
                SUM(fp.loan_principal_repaid),
                0
            ) AS loan_principal_repaid,

            COALESCE(
                SUM(fp.loan_principal_repaid_usd),
                0
            ) AS loan_principal_repaid_usd,

            COALESCE(
                SUM(fp.loan_interest_repaid),
                0
            ) AS loan_interest_repaid,

            COALESCE(
                SUM(fp.loan_interest_repaid_usd),
                0
            ) AS loan_interest_repaid_usd,

            COALESCE(
                SUM(fp.loan_interest_accrued),
                0
            ) AS loan_interest_accrued,

            COALESCE(
                SUM(fp.loan_interest_accrued_usd),
                0
            ) AS loan_interest_accrued_usd,

            COALESCE(
                SUM(fp.closing_loan_balance),
                0
            ) AS closing_loan_balance,

            COALESCE(
                SUM(fp.closing_loan_balance_usd),
                0
            ) AS closing_loan_balance_usd

        FROM public.financial_pot AS fp

        WHERE fp.user_id = v_user_id
          AND fp.country_code = v_country_code
          AND fp.fiscal_year = v_fiscal_year

        GROUP BY
            fp.period,
            lower(fp.currency_code)

    ),


    /*
     * ==========================================================
     * HISTORICAL SAVINGS POSITION
     * ==========================================================
     *
     * Used only when the CURRENT period has no financial_pot row.
     *
     * This remains display-only. No row is inserted by the
     * reporting function.
     * ==========================================================
     */

    historical_savings_rows AS (

        SELECT
            fp.fiscal_year,
            fp.period,

            lower(
                fp.currency_code
            ) AS currency_code,

            COALESCE(
                SUM(fp.closing_savings),
                0
            ) AS closing_savings,

            COALESCE(
                SUM(fp.closing_savings_usd),
                0
            ) AS closing_savings_usd

        FROM public.financial_pot AS fp

        WHERE fp.user_id = v_user_id
          AND fp.country_code = v_country_code

          AND (
              fp.fiscal_year < v_fiscal_year

              OR (
                  fp.fiscal_year = v_fiscal_year
                  AND fp.period < v_current_period
              )
          )

        GROUP BY
            fp.fiscal_year,
            fp.period,
            lower(fp.currency_code)

    ),


    /*
     * ==========================================================
     * LATEST PREVIOUS SAVINGS BY CURRENCY
     * ==========================================================
     *
     * We intentionally use the latest available prior period.
     *
     * Example:
     *
     * July      -> row exists
     * August    -> no transaction / no row
     * September -> no transaction yet
     *
     * September still displays July's closing savings as its
     * brought-forward position.
     * ==========================================================
     */

    latest_previous_savings AS (

        SELECT
            ranked.currency_code,
            ranked.closing_savings,
            ranked.closing_savings_usd

        FROM (

            SELECT
                hsr.currency_code,
                hsr.closing_savings,
                hsr.closing_savings_usd,

                ROW_NUMBER() OVER (
                    PARTITION BY
                        hsr.currency_code

                    ORDER BY
                        hsr.fiscal_year DESC,
                        hsr.period DESC
                ) AS row_number

            FROM historical_savings_rows AS hsr

        ) AS ranked

        WHERE ranked.row_number = 1

    ),


    /*
     * ==========================================================
     * ACTUAL MONEY FLOW BY PERIOD / CURRENCY
     * ==========================================================
     *
     * Everything here comes directly from financial_pot.
     *
     * No transaction/event history scan is needed.
     * ==========================================================
     */

    actual_money_currency_rows AS (

        SELECT
            cr.period,
            cr.currency_code,


            /*
             * --------------------------------------------------
             * MONEY IN
             * --------------------------------------------------
             */

            cr.opening_savings
                AS savings_brought_forward,

            cr.opening_savings_usd
                AS savings_brought_forward_usd,

            cr.cash_in_amount
                AS cash_in,

            cr.cash_in_amount_usd
                AS cash_in_usd,

            cr.transfer_in_amount
                AS transfer_in,

            cr.transfer_in_amount_usd
                AS transfer_in_usd,

            cr.loan_disbursed_amount
                AS loan_disbursement,

            cr.loan_disbursed_amount_usd
                AS loan_disbursement_usd,

            cr.investment_proceeds_amount
                AS investment_proceeds,

            cr.investment_proceeds_amount_usd
                AS investment_proceeds_usd,


            /*
             * --------------------------------------------------
             * DISTRIBUTION
             * --------------------------------------------------
             *
             * These use the actual CASH movement snapshots, not
             * the business/activity amounts.
             * --------------------------------------------------
             */

            cr.withdrawal_cash_amount
                AS withdrawal,

            cr.withdrawal_cash_amount_usd
                AS withdrawal_usd,

            cr.spending_cash_amount
                AS spending,

            cr.spending_cash_amount_usd
                AS spending_usd,

            cr.investment_cash_amount
                AS investment,

            cr.investment_cash_amount_usd
                AS investment_usd,

            cr.repayment_cash_amount
                AS repayment,

            cr.repayment_cash_amount_usd
                AS repayment_usd,


            /*
             * Remaining/closing savings.
             */
            cr.closing_savings
                AS savings,

            cr.closing_savings_usd
                AS savings_usd

        FROM currency_rows AS cr

    ),


    /*
     * ==========================================================
     * DISPLAY-ONLY CURRENT PERIOD CARRY FORWARD
     * ==========================================================
     *
     * If no transaction has occurred in the current period there
     * may be no financial_pot row.
     *
     * In that case:
     *
     *     Savings B/F = latest prior closing savings
     *     Savings     = latest prior closing savings
     *
     * Every current-period movement remains zero.
     *
     * Importantly, this does NOT create activity and does NOT
     * create financial behavior.
     * ==========================================================
     */

    current_period_carry_forward AS (

        SELECT
            v_current_period AS period,

            lps.currency_code,

            lps.closing_savings
                AS savings_brought_forward,

            lps.closing_savings_usd
                AS savings_brought_forward_usd,

            0::numeric AS cash_in,
            0::numeric AS cash_in_usd,

            0::numeric AS transfer_in,
            0::numeric AS transfer_in_usd,

            0::numeric AS loan_disbursement,
            0::numeric AS loan_disbursement_usd,

            0::numeric AS investment_proceeds,
            0::numeric AS investment_proceeds_usd,

            0::numeric AS withdrawal,
            0::numeric AS withdrawal_usd,

            0::numeric AS spending,
            0::numeric AS spending_usd,

            0::numeric AS investment,
            0::numeric AS investment_usd,

            0::numeric AS repayment,
            0::numeric AS repayment_usd,

            lps.closing_savings
                AS savings,

            lps.closing_savings_usd
                AS savings_usd

        FROM latest_previous_savings AS lps

        WHERE NOT EXISTS (

            SELECT
                1

            FROM currency_rows AS cr

            WHERE cr.period = v_current_period
              AND cr.currency_code = lps.currency_code

        )

    ),


    /*
     * ==========================================================
     * FINAL MONEY FLOW ROWS
     * ==========================================================
     */

    money_currency_rows AS (

        SELECT
            amcr.period,
            amcr.currency_code,

            amcr.savings_brought_forward,
            amcr.savings_brought_forward_usd,

            amcr.cash_in,
            amcr.cash_in_usd,

            amcr.transfer_in,
            amcr.transfer_in_usd,

            amcr.loan_disbursement,
            amcr.loan_disbursement_usd,

            amcr.investment_proceeds,
            amcr.investment_proceeds_usd,

            amcr.withdrawal,
            amcr.withdrawal_usd,

            amcr.spending,
            amcr.spending_usd,

            amcr.investment,
            amcr.investment_usd,

            amcr.repayment,
            amcr.repayment_usd,

            amcr.savings,
            amcr.savings_usd

        FROM actual_money_currency_rows AS amcr


        UNION ALL


        SELECT
            cpcf.period,
            cpcf.currency_code,

            cpcf.savings_brought_forward,
            cpcf.savings_brought_forward_usd,

            cpcf.cash_in,
            cpcf.cash_in_usd,

            cpcf.transfer_in,
            cpcf.transfer_in_usd,

            cpcf.loan_disbursement,
            cpcf.loan_disbursement_usd,

            cpcf.investment_proceeds,
            cpcf.investment_proceeds_usd,

            cpcf.withdrawal,
            cpcf.withdrawal_usd,

            cpcf.spending,
            cpcf.spending_usd,

            cpcf.investment,
            cpcf.investment_usd,

            cpcf.repayment,
            cpcf.repayment_usd,

            cpcf.savings,
            cpcf.savings_usd

        FROM current_period_carry_forward AS cpcf

    ),


    /*
     * ==========================================================
     * ALL-CURRENCY PERIOD MONEY FLOW
     * ==========================================================
     *
     * Consolidated values use USD equivalent.
     * ==========================================================
     */

    period_money_totals AS (

        SELECT
            mcr.period,

            COALESCE(
                SUM(mcr.savings_brought_forward_usd),
                0
            ) AS savings_brought_forward_usd,

            COALESCE(
                SUM(mcr.cash_in_usd),
                0
            ) AS cash_in_usd,

            COALESCE(
                SUM(mcr.transfer_in_usd),
                0
            ) AS transfer_in_usd,

            COALESCE(
                SUM(mcr.loan_disbursement_usd),
                0
            ) AS loan_disbursement_usd,

            COALESCE(
                SUM(mcr.investment_proceeds_usd),
                0
            ) AS investment_proceeds_usd,

            COALESCE(
                SUM(mcr.withdrawal_usd),
                0
            ) AS withdrawal_usd,

            COALESCE(
                SUM(mcr.spending_usd),
                0
            ) AS spending_usd,

            COALESCE(
                SUM(mcr.investment_usd),
                0
            ) AS investment_usd,

            COALESCE(
                SUM(mcr.repayment_usd),
                0
            ) AS repayment_usd,

            COALESCE(
                SUM(mcr.savings_usd),
                0
            ) AS savings_usd

        FROM money_currency_rows AS mcr

        GROUP BY
            mcr.period

    ),


    /*
     * ==========================================================
     * EXISTING PERIOD TOTALS
     * ==========================================================
     *
     * Preserved exactly for backward compatibility.
     * ==========================================================
     */

    period_totals AS (

        SELECT
            cr.period,

            COALESCE(
                SUM(cr.deposit_amount_usd),
                0
            ) AS deposit_usd,

            COALESCE(
                SUM(cr.withdrawal_amount_usd),
                0
            ) AS withdrawal_usd,

            COALESCE(
                SUM(cr.spending_amount_usd),
                0
            ) AS spending_usd,

            COALESCE(
                SUM(cr.savings_inflow_usd),
                0
            ) AS savings_inflow_usd,

            COALESCE(
                SUM(cr.savings_outflow_usd),
                0
            ) AS savings_outflow_usd,

            COALESCE(
                SUM(cr.saving_amount_usd),
                0
            ) AS saving_usd,

            COALESCE(
                SUM(cr.closing_savings_usd),
                0
            ) AS closing_savings_usd,

            COALESCE(
                SUM(cr.investment_purchase_amount_usd),
                0
            ) AS investment_usd,

            COALESCE(
                SUM(cr.investment_sale_amount_usd),
                0
            ) AS investment_sale_usd,

            COALESCE(
                SUM(cr.loan_disbursed_amount_usd),
                0
            ) AS borrowing_usd,

            COALESCE(
                SUM(cr.loan_repayment_amount_usd),
                0
            ) AS repayment_usd,

            COALESCE(
                SUM(cr.loan_interest_accrued_usd),
                0
            ) AS interest_accrued_usd,

            COALESCE(
                SUM(cr.closing_loan_balance_usd),
                0
            ) AS closing_loan_balance_usd

        FROM currency_rows AS cr

        GROUP BY
            cr.period

    ),


    /*
     * ==========================================================
     * PERIOD / ALL-CURRENCY BEHAVIOR
     * ==========================================================
     */

    period_behavior AS (

        SELECT
            fb.period,
            fb.behavior,

            COALESCE(
                fb.shopper_score_percentage,
                0
            ) AS shopper_score_percentage,

            COALESCE(
                fb.saver_score_percentage,
                0
            ) AS saver_score_percentage,

            COALESCE(
                fb.investor_score_percentage,
                0
            ) AS investor_score_percentage,

            COALESCE(
                fb.borrower_score_percentage,
                0
            ) AS borrower_score_percentage

        FROM public.financial_behavior AS fb

        WHERE fb.user_id = v_user_id
          AND fb.country_code = v_country_code
          AND fb.fiscal_year = v_fiscal_year

          AND fb.scope =
              'period'::public.financial_behavior_scope

          AND fb.period IS NOT NULL

          AND fb.currency_code IS NULL

    ),


    /*
     * ==========================================================
     * PERIOD / CURRENCY BEHAVIOR
     * ==========================================================
     */

    currency_behavior AS (

        SELECT
            fb.period,

            lower(
                fb.currency_code
            ) AS currency_code,

            fb.behavior,

            COALESCE(
                fb.shopper_score_percentage,
                0
            ) AS shopper_score_percentage,

            COALESCE(
                fb.saver_score_percentage,
                0
            ) AS saver_score_percentage,

            COALESCE(
                fb.investor_score_percentage,
                0
            ) AS investor_score_percentage,

            COALESCE(
                fb.borrower_score_percentage,
                0
            ) AS borrower_score_percentage

        FROM public.financial_behavior AS fb

        WHERE fb.user_id = v_user_id
          AND fb.country_code = v_country_code
          AND fb.fiscal_year = v_fiscal_year

          AND fb.scope =
              'period'::public.financial_behavior_scope

          AND fb.period IS NOT NULL

          AND fb.currency_code IS NOT NULL

    ),


    /*
     * ==========================================================
     * EXISTING CURRENCY JSON
     * ==========================================================
     *
     * Preserved for compatibility.
     *
     * This still represents actual financial_pot rows only.
     *
     * A display-only current-period carry-forward is therefore
     * intentionally not inserted into this legacy currencies[]
     * collection.
     * ==========================================================
     */

    period_currency_json AS (

        SELECT
            cr.period,

            jsonb_agg(
                jsonb_build_object(

                    'currency_code',
                        cr.currency_code,

                    'behavior',
                        COALESCE(
                            cb.behavior,
                            'neutral'::public.financial_behavior_type
                        ),

                    'behavior_scores',
                        jsonb_build_object(

                            'shopper_percentage',
                                COALESCE(
                                    cb.shopper_score_percentage,
                                    0
                                ),

                            'saver_percentage',
                                COALESCE(
                                    cb.saver_score_percentage,
                                    0
                                ),

                            'investor_percentage',
                                COALESCE(
                                    cb.investor_score_percentage,
                                    0
                                ),

                            'borrower_percentage',
                                COALESCE(
                                    cb.borrower_score_percentage,
                                    0
                                )
                        ),

                    'deposit',
                        jsonb_build_object(
                            'amount',
                                cr.deposit_amount,

                            'amount_usd',
                                cr.deposit_amount_usd
                        ),

                    'withdrawal',
                        jsonb_build_object(
                            'amount',
                                cr.withdrawal_amount,

                            'amount_usd',
                                cr.withdrawal_amount_usd
                        ),

                    'spending',
                        jsonb_build_object(
                            'amount',
                                cr.spending_amount,

                            'amount_usd',
                                cr.spending_amount_usd
                        ),

                    'savings',
                        jsonb_build_object(

                            'opening',
                                cr.opening_savings,

                            'opening_usd',
                                cr.opening_savings_usd,

                            'inflow',
                                cr.savings_inflow,

                            'inflow_usd',
                                cr.savings_inflow_usd,

                            'outflow',
                                cr.savings_outflow,

                            'outflow_usd',
                                cr.savings_outflow_usd,

                            'saved',
                                cr.saving_amount,

                            'saved_usd',
                                cr.saving_amount_usd,

                            'closing',
                                cr.closing_savings,

                            'closing_usd',
                                cr.closing_savings_usd
                        ),

                    'investment',
                        jsonb_build_object(

                            'purchased',
                                cr.investment_purchase_amount,

                            'purchased_usd',
                                cr.investment_purchase_amount_usd,

                            'sold',
                                cr.investment_sale_amount,

                            'sold_usd',
                                cr.investment_sale_amount_usd
                        ),

                    'loan',
                        jsonb_build_object(

                            'opening_balance',
                                cr.opening_loan_balance,

                            'opening_balance_usd',
                                cr.opening_loan_balance_usd,

                            'disbursed',
                                cr.loan_disbursed_amount,

                            'disbursed_usd',
                                cr.loan_disbursed_amount_usd,

                            'repaid',
                                cr.loan_repayment_amount,

                            'repaid_usd',
                                cr.loan_repayment_amount_usd,

                            'principal_repaid',
                                cr.loan_principal_repaid,

                            'principal_repaid_usd',
                                cr.loan_principal_repaid_usd,

                            'interest_repaid',
                                cr.loan_interest_repaid,

                            'interest_repaid_usd',
                                cr.loan_interest_repaid_usd,

                            'interest_accrued',
                                cr.loan_interest_accrued,

                            'interest_accrued_usd',
                                cr.loan_interest_accrued_usd,

                            'closing_balance',
                                cr.closing_loan_balance,

                            'closing_balance_usd',
                                cr.closing_loan_balance_usd
                        )

                )
                ORDER BY
                    cr.currency_code
            ) AS currencies

        FROM currency_rows AS cr

        LEFT JOIN currency_behavior AS cb
            ON cb.period = cr.period
           AND cb.currency_code = cr.currency_code

        GROUP BY
            cr.period

    ),


    /*
     * ==========================================================
     * PERIOD MONEY BY CURRENCY JSON
     * ==========================================================
     */

    period_money_currency_json AS (

        SELECT
            mcr.period,

            jsonb_agg(
                jsonb_build_object(

                    'currency_code',
                        mcr.currency_code,


                    /*
                     * ------------------------------------------
                     * MONEY IN
                     * ------------------------------------------
                     */

                    'money_in',
                        jsonb_build_object(

                            'savings_brought_forward',
                                mcr.savings_brought_forward,

                            'savings_brought_forward_usd',
                                mcr.savings_brought_forward_usd,

                            'cash_in',
                                mcr.cash_in,

                            'cash_in_usd',
                                mcr.cash_in_usd,

                            'transfer_in',
                                mcr.transfer_in,

                            'transfer_in_usd',
                                mcr.transfer_in_usd,

                            'loan_disbursement',
                                mcr.loan_disbursement,

                            'loan_disbursement_usd',
                                mcr.loan_disbursement_usd,

                            'investment_proceeds',
                                mcr.investment_proceeds,

                            'investment_proceeds_usd',
                                mcr.investment_proceeds_usd,

                            'total',
                                mcr.savings_brought_forward
                                + mcr.cash_in
                                + mcr.transfer_in
                                + mcr.loan_disbursement
                                + mcr.investment_proceeds,

                            'total_usd',
                                mcr.savings_brought_forward_usd
                                + mcr.cash_in_usd
                                + mcr.transfer_in_usd
                                + mcr.loan_disbursement_usd
                                + mcr.investment_proceeds_usd
                        ),


                    /*
                     * ------------------------------------------
                     * DISTRIBUTION
                     * ------------------------------------------
                     */

                    'distribution',
                        jsonb_build_object(

                            'withdrawal',
                                mcr.withdrawal,

                            'withdrawal_usd',
                                mcr.withdrawal_usd,

                            'spending',
                                mcr.spending,

                            'spending_usd',
                                mcr.spending_usd,

                            'investment',
                                mcr.investment,

                            'investment_usd',
                                mcr.investment_usd,

                            'repayment',
                                mcr.repayment,

                            'repayment_usd',
                                mcr.repayment_usd,

                            'savings',
                                mcr.savings,

                            'savings_usd',
                                mcr.savings_usd,

                            'total',
                                mcr.withdrawal
                                + mcr.spending
                                + mcr.investment
                                + mcr.repayment
                                + mcr.savings,

                            'total_usd',
                                mcr.withdrawal_usd
                                + mcr.spending_usd
                                + mcr.investment_usd
                                + mcr.repayment_usd
                                + mcr.savings_usd
                        )

                )
                ORDER BY
                    mcr.currency_code
            ) AS money_by_currency

        FROM money_currency_rows AS mcr

        GROUP BY
            mcr.period

    )


    /*
     * ==========================================================
     * BUILD P1 - P12
     * ==========================================================
     */

    SELECT
        jsonb_agg(
            jsonb_build_object(

                /*
                 * ----------------------------------------------
                 * PERIOD
                 * ----------------------------------------------
                 */

                'period',
                    p.period,

                'is_current_period',
                    p.period = v_current_period,

                /*
                 * Display-only carry-forward does NOT mean that
                 * the user transacted during the current period.
                 */
                'has_activity',
                    pt.period IS NOT NULL,


                /*
                 * ----------------------------------------------
                 * CONSOLIDATED PERIOD BEHAVIOR
                 * ----------------------------------------------
                 */

                'behavior',
                    COALESCE(
                        pb.behavior,
                        'neutral'::public.financial_behavior_type
                    ),

                'behavior_scores',
                    jsonb_build_object(

                        'shopper_percentage',
                            COALESCE(
                                pb.shopper_score_percentage,
                                0
                            ),

                        'saver_percentage',
                            COALESCE(
                                pb.saver_score_percentage,
                                0
                            ),

                        'investor_percentage',
                            COALESCE(
                                pb.investor_score_percentage,
                                0
                            ),

                        'borrower_percentage',
                            COALESCE(
                                pb.borrower_score_percentage,
                                0
                            )
                    ),


                /*
                 * ----------------------------------------------
                 * EXISTING ALL-CURRENCY PERIOD TOTALS
                 * ----------------------------------------------
                 */

                'all',
                    jsonb_build_object(

                        'deposit_usd',
                            COALESCE(
                                pt.deposit_usd,
                                0
                            ),

                        'withdrawal_usd',
                            COALESCE(
                                pt.withdrawal_usd,
                                0
                            ),

                        'spending_usd',
                            COALESCE(
                                pt.spending_usd,
                                0
                            ),

                        'savings_inflow_usd',
                            COALESCE(
                                pt.savings_inflow_usd,
                                0
                            ),

                        'savings_outflow_usd',
                            COALESCE(
                                pt.savings_outflow_usd,
                                0
                            ),

                        'saving_usd',
                            COALESCE(
                                pt.saving_usd,
                                0
                            ),

                        'closing_savings_usd',
                            COALESCE(
                                pt.closing_savings_usd,
                                0
                            ),

                        'investment_usd',
                            COALESCE(
                                pt.investment_usd,
                                0
                            ),

                        'investment_sale_usd',
                            COALESCE(
                                pt.investment_sale_usd,
                                0
                            ),

                        'borrowing_usd',
                            COALESCE(
                                pt.borrowing_usd,
                                0
                            ),

                        'repayment_usd',
                            COALESCE(
                                pt.repayment_usd,
                                0
                            ),

                        'interest_accrued_usd',
                            COALESCE(
                                pt.interest_accrued_usd,
                                0
                            ),

                        'closing_loan_balance_usd',
                            COALESCE(
                                pt.closing_loan_balance_usd,
                                0
                            )
                    ),


                /*
                 * ----------------------------------------------
                 * CONSOLIDATED MONEY IN
                 * ----------------------------------------------
                 */

                'money_in',
                    jsonb_build_object(

                        'savings_brought_forward_usd',
                            COALESCE(
                                pmt.savings_brought_forward_usd,
                                0
                            ),

                        'cash_in_usd',
                            COALESCE(
                                pmt.cash_in_usd,
                                0
                            ),

                        'transfer_in_usd',
                            COALESCE(
                                pmt.transfer_in_usd,
                                0
                            ),

                        'loan_disbursement_usd',
                            COALESCE(
                                pmt.loan_disbursement_usd,
                                0
                            ),

                        'investment_proceeds_usd',
                            COALESCE(
                                pmt.investment_proceeds_usd,
                                0
                            ),

                        'total_usd',
                            COALESCE(
                                pmt.savings_brought_forward_usd,
                                0
                            )
                            +
                            COALESCE(
                                pmt.cash_in_usd,
                                0
                            )
                            +
                            COALESCE(
                                pmt.transfer_in_usd,
                                0
                            )
                            +
                            COALESCE(
                                pmt.loan_disbursement_usd,
                                0
                            )
                            +
                            COALESCE(
                                pmt.investment_proceeds_usd,
                                0
                            )
                    ),


                /*
                 * ----------------------------------------------
                 * CONSOLIDATED DISTRIBUTION
                 * ----------------------------------------------
                 */

                'distribution',
                    jsonb_build_object(

                        'withdrawal_usd',
                            COALESCE(
                                pmt.withdrawal_usd,
                                0
                            ),

                        'spending_usd',
                            COALESCE(
                                pmt.spending_usd,
                                0
                            ),

                        'investment_usd',
                            COALESCE(
                                pmt.investment_usd,
                                0
                            ),

                        'repayment_usd',
                            COALESCE(
                                pmt.repayment_usd,
                                0
                            ),

                        'savings_usd',
                            COALESCE(
                                pmt.savings_usd,
                                0
                            ),

                        'total_usd',
                            COALESCE(
                                pmt.withdrawal_usd,
                                0
                            )
                            +
                            COALESCE(
                                pmt.spending_usd,
                                0
                            )
                            +
                            COALESCE(
                                pmt.investment_usd,
                                0
                            )
                            +
                            COALESCE(
                                pmt.repayment_usd,
                                0
                            )
                            +
                            COALESCE(
                                pmt.savings_usd,
                                0
                            )
                    ),


                /*
                 * ----------------------------------------------
                 * EXISTING CURRENCY BREAKDOWN
                 * ----------------------------------------------
                 */

                'currencies',
                    COALESCE(
                        pcj.currencies,
                        '[]'::jsonb
                    ),


                /*
                 * ----------------------------------------------
                 * MONEY FLOW BY CURRENCY
                 * ----------------------------------------------
                 */

                'money_by_currency',
                    COALESCE(
                        pmcj.money_by_currency,
                        '[]'::jsonb
                    )

            )
            ORDER BY
                p.period
        )

    INTO
        v_periods

    FROM periods AS p

    LEFT JOIN period_totals AS pt
        ON pt.period = p.period

    LEFT JOIN period_money_totals AS pmt
        ON pmt.period = p.period

    LEFT JOIN period_behavior AS pb
        ON pb.period = p.period

    LEFT JOIN period_currency_json AS pcj
        ON pcj.period = p.period

    LEFT JOIN period_money_currency_json AS pmcj
        ON pmcj.period = p.period;


    /*
     * ==========================================================
     * RESPONSE
     * ==========================================================
     */

    RETURN jsonb_build_object(

        'fiscal_year',
            v_fiscal_year,

        'current_period',
            v_current_period,

        'fiscal_year_behavior',
            v_fiscal_year_behavior,

        'fiscal_year_behavior_scores',
            jsonb_build_object(

                'shopper_percentage',
                    v_fiscal_year_shopper_score,

                'saver_percentage',
                    v_fiscal_year_saver_score,

                'investor_percentage',
                    v_fiscal_year_investor_score,

                'borrower_percentage',
                    v_fiscal_year_borrower_score
            ),

        'periods',
            COALESCE(
                v_periods,
                '[]'::jsonb
            )
    );

END;
$$;
ALTER FUNCTION "public"."get_my_financial_periods"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."get_my_financial_summary"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_user_id text;
    v_country_code text;

    v_fiscal_year integer;
    v_period integer;

    v_currencies jsonb;
    v_money_by_currency jsonb;
    v_money_in jsonb;
    v_distribution jsonb;
    v_gold jsonb;

    -- ==========================================================
    -- FISCAL YEAR BEHAVIOR
    -- ==========================================================

    v_behavior public.financial_behavior_type :=
        'neutral'::public.financial_behavior_type;

    v_shopper_score_percentage numeric := 0;
    v_saver_score_percentage numeric := 0;
    v_investor_score_percentage numeric := 0;
    v_borrower_score_percentage numeric := 0;

    -- ==========================================================
    -- CURRENT PERIOD BEHAVIOR
    -- ==========================================================

    v_current_period_behavior public.financial_behavior_type :=
        'neutral'::public.financial_behavior_type;

    v_current_period_shopper_score_percentage numeric := 0;
    v_current_period_saver_score_percentage numeric := 0;
    v_current_period_investor_score_percentage numeric := 0;
    v_current_period_borrower_score_percentage numeric := 0;

BEGIN

    -- ==========================================================
    -- AUTHENTICATION
    -- ==========================================================

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;


    -- ==========================================================
    -- AUTHORIZED USER + COUNTRY
    -- ==========================================================

    SELECT
        u.id,
        lower(u.country_code)
    INTO
        v_user_id,
        v_country_code
    FROM public.users AS u

    JOIN public.user_role AS r
        ON r.id = u.role_id

    WHERE u.id = auth.uid()::text

      AND u.status =
          'active'::public."UserStatus"

      AND lower(r.name::text) IN (
          'customer',
          'vendor',
          'agent'
      )

    LIMIT 1;


    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE =
                'FINANCIAL_BEHAVIOUR_NOT_AUTHORIZED';
    END IF;


    IF v_country_code IS NULL
       OR trim(v_country_code) = ''
    THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE =
                'USER_COUNTRY_NOT_FOUND';
    END IF;


    -- ==========================================================
    -- CURRENT FISCAL PERIOD
    -- ==========================================================

    SELECT
        fiscal_period.fiscal_year,
        fiscal_period.period
    INTO
        v_fiscal_year,
        v_period
    FROM public.fetch_fiscal_period(
        v_country_code
    ) AS fiscal_period;


    IF NOT FOUND
       OR v_fiscal_year IS NULL
       OR v_period IS NULL
    THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0001',
            MESSAGE =
                'FISCAL_PERIOD_NOT_FOUND';
    END IF;


    -- ==========================================================
    -- FISCAL YEAR CONSOLIDATED BEHAVIOR
    -- ==========================================================

    SELECT
        fb.behavior,

        COALESCE(
            fb.shopper_score_percentage,
            0
        ),

        COALESCE(
            fb.saver_score_percentage,
            0
        ),

        COALESCE(
            fb.investor_score_percentage,
            0
        ),

        COALESCE(
            fb.borrower_score_percentage,
            0
        )

    INTO
        v_behavior,
        v_shopper_score_percentage,
        v_saver_score_percentage,
        v_investor_score_percentage,
        v_borrower_score_percentage

    FROM public.financial_behavior AS fb

    WHERE fb.user_id =
          v_user_id

      AND fb.country_code =
          v_country_code

      AND fb.fiscal_year =
          v_fiscal_year

      AND fb.scope =
          'fiscal_year'::public.financial_behavior_scope

      AND fb.period IS NULL

      AND fb.currency_code IS NULL

    LIMIT 1;


    IF NOT FOUND THEN

        v_behavior :=
            'neutral'::public.financial_behavior_type;

        v_shopper_score_percentage := 0;
        v_saver_score_percentage := 0;
        v_investor_score_percentage := 0;
        v_borrower_score_percentage := 0;

    END IF;


    -- ==========================================================
    -- CURRENT PERIOD CONSOLIDATED BEHAVIOR
    -- ==========================================================

    SELECT
        fb.behavior,

        COALESCE(
            fb.shopper_score_percentage,
            0
        ),

        COALESCE(
            fb.saver_score_percentage,
            0
        ),

        COALESCE(
            fb.investor_score_percentage,
            0
        ),

        COALESCE(
            fb.borrower_score_percentage,
            0
        )

    INTO
        v_current_period_behavior,
        v_current_period_shopper_score_percentage,
        v_current_period_saver_score_percentage,
        v_current_period_investor_score_percentage,
        v_current_period_borrower_score_percentage

    FROM public.financial_behavior AS fb

    WHERE fb.user_id =
          v_user_id

      AND fb.country_code =
          v_country_code

      AND fb.fiscal_year =
          v_fiscal_year

      AND fb.period =
          v_period

      AND fb.scope =
          'period'::public.financial_behavior_scope

      AND fb.currency_code IS NULL

    LIMIT 1;


    IF NOT FOUND THEN

        v_current_period_behavior :=
            'neutral'::public.financial_behavior_type;

        v_current_period_shopper_score_percentage := 0;
        v_current_period_saver_score_percentage := 0;
        v_current_period_investor_score_percentage := 0;
        v_current_period_borrower_score_percentage := 0;

    END IF;


    -- ==========================================================
    -- FY-TO-DATE MONEY BY CURRENCY
    --
    -- financial_pot is the reporting source of truth.
    --
    -- Period flows are summed.
    --
    -- Savings B/F is taken ONLY from the first period.
    -- Closing savings is taken ONLY from the latest period.
    -- ==========================================================

    WITH pot_ranked AS (

        SELECT
            fp.*,

            ROW_NUMBER() OVER (
                PARTITION BY fp.currency_code
                ORDER BY fp.period ASC
            ) AS first_period_row,

            ROW_NUMBER() OVER (
                PARTITION BY fp.currency_code
                ORDER BY fp.period DESC
            ) AS last_period_row

        FROM public.financial_pot AS fp

        WHERE fp.user_id =
              v_user_id

          AND fp.country_code =
              v_country_code

          AND fp.fiscal_year =
              v_fiscal_year

          AND fp.period <=
              v_period
    ),

    currency_money AS (

        SELECT
            pr.currency_code,

            -- --------------------------------------------------
            -- POSITION: FIRST PERIOD ONLY
            -- --------------------------------------------------

            COALESCE(
                MAX(pr.opening_savings)
                FILTER (
                    WHERE pr.first_period_row = 1
                ),
                0
            ) AS savings_brought_forward,

            COALESCE(
                MAX(pr.opening_savings_usd)
                FILTER (
                    WHERE pr.first_period_row = 1
                ),
                0
            ) AS savings_brought_forward_usd,

            -- --------------------------------------------------
            -- MONEY IN FLOWS: SUM ALL PERIODS
            -- --------------------------------------------------

            COALESCE(
                SUM(pr.cash_in_amount),
                0
            ) AS cash_in,

            COALESCE(
                SUM(pr.cash_in_amount_usd),
                0
            ) AS cash_in_usd,

            COALESCE(
                SUM(pr.transfer_in_amount),
                0
            ) AS transfer_in,

            COALESCE(
                SUM(pr.transfer_in_amount_usd),
                0
            ) AS transfer_in_usd,

            COALESCE(
                SUM(pr.loan_disbursed_amount),
                0
            ) AS loan_disbursement,

            COALESCE(
                SUM(pr.loan_disbursed_amount_usd),
                0
            ) AS loan_disbursement_usd,

            COALESCE(
                SUM(pr.investment_proceeds_amount),
                0
            ) AS investment_proceeds,

            COALESCE(
                SUM(pr.investment_proceeds_amount_usd),
                0
            ) AS investment_proceeds_usd,

            -- --------------------------------------------------
            -- DISTRIBUTION FLOWS: SUM ALL PERIODS
            -- --------------------------------------------------

            COALESCE(
                SUM(pr.withdrawal_cash_amount),
                0
            ) AS withdrawal,

            COALESCE(
                SUM(pr.withdrawal_cash_amount_usd),
                0
            ) AS withdrawal_usd,

            COALESCE(
                SUM(pr.spending_cash_amount),
                0
            ) AS spending,

            COALESCE(
                SUM(pr.spending_cash_amount_usd),
                0
            ) AS spending_usd,

            COALESCE(
                SUM(pr.investment_cash_amount),
                0
            ) AS investment,

            COALESCE(
                SUM(pr.investment_cash_amount_usd),
                0
            ) AS investment_usd,

            COALESCE(
                SUM(pr.repayment_cash_amount),
                0
            ) AS repayment,

            COALESCE(
                SUM(pr.repayment_cash_amount_usd),
                0
            ) AS repayment_usd,

            -- --------------------------------------------------
            -- POSITION: LATEST PERIOD ONLY
            -- --------------------------------------------------

            COALESCE(
                MAX(pr.closing_savings)
                FILTER (
                    WHERE pr.last_period_row = 1
                ),
                0
            ) AS savings,

            COALESCE(
                MAX(pr.closing_savings_usd)
                FILTER (
                    WHERE pr.last_period_row = 1
                ),
                0
            ) AS savings_usd

        FROM pot_ranked AS pr

        GROUP BY
            pr.currency_code
    ),

    currency_totals AS (

        SELECT
            cm.*,

            (
                  cm.savings_brought_forward
                + cm.cash_in
                + cm.transfer_in
                + cm.loan_disbursement
                + cm.investment_proceeds
            ) AS available_money,

            (
                  cm.savings_brought_forward_usd
                + cm.cash_in_usd
                + cm.transfer_in_usd
                + cm.loan_disbursement_usd
                + cm.investment_proceeds_usd
            ) AS available_money_usd,

            (
                  cm.withdrawal
                + cm.spending
                + cm.investment
                + cm.repayment
                + cm.savings
            ) AS distribution_total,

            (
                  cm.withdrawal_usd
                + cm.spending_usd
                + cm.investment_usd
                + cm.repayment_usd
                + cm.savings_usd
            ) AS distribution_total_usd

        FROM currency_money AS cm
    )

    SELECT
        COALESCE(
            jsonb_agg(
                jsonb_build_object(

                    'currency_code',
                        ct.currency_code,

                    'money_in',
                        jsonb_build_object(

                            'savings_brought_forward',
                                ct.savings_brought_forward,

                            'savings_brought_forward_usd',
                                ct.savings_brought_forward_usd,

                            'cash_in',
                                ct.cash_in,

                            'cash_in_usd',
                                ct.cash_in_usd,

                            'transfer_in',
                                ct.transfer_in,

                            'transfer_in_usd',
                                ct.transfer_in_usd,

                            'loan_disbursement',
                                ct.loan_disbursement,

                            'loan_disbursement_usd',
                                ct.loan_disbursement_usd,

                            'investment_proceeds',
                                ct.investment_proceeds,

                            'investment_proceeds_usd',
                                ct.investment_proceeds_usd,

                            'total',
                                ct.available_money,

                            'total_usd',
                                ct.available_money_usd
                        ),

                    'distribution',
                        jsonb_build_object(

                            'withdrawal',
                                ct.withdrawal,

                            'withdrawal_usd',
                                ct.withdrawal_usd,

                            'spending',
                                ct.spending,

                            'spending_usd',
                                ct.spending_usd,

                            'investment',
                                ct.investment,

                            'investment_usd',
                                ct.investment_usd,

                            'repayment',
                                ct.repayment,

                            'repayment_usd',
                                ct.repayment_usd,

                            'savings',
                                ct.savings,

                            'savings_usd',
                                ct.savings_usd,

                            'total',
                                ct.distribution_total,

                            'total_usd',
                                ct.distribution_total_usd
                        )
                )
                ORDER BY
                    ct.currency_code
            ),
            '[]'::jsonb
        )

    INTO
        v_money_by_currency

    FROM currency_totals AS ct;


    -- ==========================================================
    -- CONSOLIDATED FY-TO-DATE MONEY IN
    --
    -- Currency values have already been consolidated from
    -- financial_pot. We only consolidate currencies into USD.
    -- ==========================================================

    WITH source AS (

        SELECT
            item

        FROM jsonb_array_elements(
            v_money_by_currency
        ) AS item
    ),

    totals AS (

        SELECT
            COALESCE(
                SUM(
                    (
                        item
                        -> 'money_in'
                        ->> 'savings_brought_forward_usd'
                    )::numeric
                ),
                0
            ) AS savings_brought_forward_usd,

            COALESCE(
                SUM(
                    (
                        item
                        -> 'money_in'
                        ->> 'cash_in_usd'
                    )::numeric
                ),
                0
            ) AS cash_in_usd,

            COALESCE(
                SUM(
                    (
                        item
                        -> 'money_in'
                        ->> 'transfer_in_usd'
                    )::numeric
                ),
                0
            ) AS transfer_in_usd,

            COALESCE(
                SUM(
                    (
                        item
                        -> 'money_in'
                        ->> 'loan_disbursement_usd'
                    )::numeric
                ),
                0
            ) AS loan_disbursement_usd,

            COALESCE(
                SUM(
                    (
                        item
                        -> 'money_in'
                        ->> 'investment_proceeds_usd'
                    )::numeric
                ),
                0
            ) AS investment_proceeds_usd

        FROM source
    )

    SELECT
        jsonb_build_object(

            'savings_brought_forward_usd',
                t.savings_brought_forward_usd,

            'cash_in_usd',
                t.cash_in_usd,

            'transfer_in_usd',
                t.transfer_in_usd,

            'loan_disbursement_usd',
                t.loan_disbursement_usd,

            'investment_proceeds_usd',
                t.investment_proceeds_usd,

            'total_usd',
                  t.savings_brought_forward_usd
                + t.cash_in_usd
                + t.transfer_in_usd
                + t.loan_disbursement_usd
                + t.investment_proceeds_usd
        )

    INTO
        v_money_in

    FROM totals AS t;


    -- ==========================================================
    -- CONSOLIDATED FY-TO-DATE DISTRIBUTION
    -- ==========================================================

    WITH source AS (

        SELECT
            item

        FROM jsonb_array_elements(
            v_money_by_currency
        ) AS item
    ),

    totals AS (

        SELECT
            COALESCE(
                SUM(
                    (
                        item
                        -> 'distribution'
                        ->> 'withdrawal_usd'
                    )::numeric
                ),
                0
            ) AS withdrawal_usd,

            COALESCE(
                SUM(
                    (
                        item
                        -> 'distribution'
                        ->> 'spending_usd'
                    )::numeric
                ),
                0
            ) AS spending_usd,

            COALESCE(
                SUM(
                    (
                        item
                        -> 'distribution'
                        ->> 'investment_usd'
                    )::numeric
                ),
                0
            ) AS investment_usd,

            COALESCE(
                SUM(
                    (
                        item
                        -> 'distribution'
                        ->> 'repayment_usd'
                    )::numeric
                ),
                0
            ) AS repayment_usd,

            COALESCE(
                SUM(
                    (
                        item
                        -> 'distribution'
                        ->> 'savings_usd'
                    )::numeric
                ),
                0
            ) AS savings_usd

        FROM source
    )

    SELECT
        jsonb_build_object(

            'withdrawal_usd',
                t.withdrawal_usd,

            'spending_usd',
                t.spending_usd,

            'investment_usd',
                t.investment_usd,

            'repayment_usd',
                t.repayment_usd,

            'savings_usd',
                t.savings_usd,

            'total_usd',
                  t.withdrawal_usd
                + t.spending_usd
                + t.investment_usd
                + t.repayment_usd
                + t.savings_usd
        )

    INTO
        v_distribution

    FROM totals AS t;


    -- ==========================================================
    -- FY-TO-DATE CURRENCY SUMMARY
    --
    -- All activity values are summed across periods.
    --
    -- Opening positions come from the first period.
    -- Closing positions come from the latest period.
    -- ==========================================================

    WITH currency_periods AS (

        SELECT
            fp.*,

            ROW_NUMBER() OVER (
                PARTITION BY fp.currency_code
                ORDER BY fp.period ASC
            ) AS first_period_row,

            ROW_NUMBER() OVER (
                PARTITION BY fp.currency_code
                ORDER BY fp.period DESC
            ) AS last_period_row

        FROM public.financial_pot AS fp

        WHERE fp.user_id =
              v_user_id

          AND fp.country_code =
              v_country_code

          AND fp.fiscal_year =
              v_fiscal_year

          AND fp.period <=
              v_period
    ),

    currency_summary AS (

        SELECT
            cp.currency_code,

            COALESCE(
                SUM(cp.deposit_amount),
                0
            ) AS deposit_amount,

            COALESCE(
                SUM(cp.deposit_amount_usd),
                0
            ) AS deposit_amount_usd,

            COALESCE(
                SUM(cp.withdrawal_amount),
                0
            ) AS withdrawal_amount,

            COALESCE(
                SUM(cp.withdrawal_amount_usd),
                0
            ) AS withdrawal_amount_usd,

            COALESCE(
                SUM(cp.spending_amount),
                0
            ) AS spending_amount,

            COALESCE(
                SUM(cp.spending_amount_usd),
                0
            ) AS spending_amount_usd,

            COALESCE(
                SUM(cp.savings_inflow),
                0
            ) AS savings_inflow,

            COALESCE(
                SUM(cp.savings_inflow_usd),
                0
            ) AS savings_inflow_usd,

            COALESCE(
                SUM(cp.savings_outflow),
                0
            ) AS savings_outflow,

            COALESCE(
                SUM(cp.savings_outflow_usd),
                0
            ) AS savings_outflow_usd,

            COALESCE(
                SUM(cp.saving_amount),
                0
            ) AS saving_amount,

            COALESCE(
                SUM(cp.saving_amount_usd),
                0
            ) AS saving_amount_usd,

            COALESCE(
                MAX(cp.opening_savings)
                FILTER (
                    WHERE cp.first_period_row = 1
                ),
                0
            ) AS opening_savings,

            COALESCE(
                MAX(cp.opening_savings_usd)
                FILTER (
                    WHERE cp.first_period_row = 1
                ),
                0
            ) AS opening_savings_usd,

            COALESCE(
                MAX(cp.closing_savings)
                FILTER (
                    WHERE cp.last_period_row = 1
                ),
                0
            ) AS closing_savings,

            COALESCE(
                MAX(cp.closing_savings_usd)
                FILTER (
                    WHERE cp.last_period_row = 1
                ),
                0
            ) AS closing_savings_usd,

            COALESCE(
                SUM(cp.investment_purchase_amount),
                0
            ) AS investment_purchase_amount,

            COALESCE(
                SUM(cp.investment_purchase_amount_usd),
                0
            ) AS investment_purchase_amount_usd,

            COALESCE(
                SUM(cp.investment_sale_amount),
                0
            ) AS investment_sale_amount,

            COALESCE(
                SUM(cp.investment_sale_amount_usd),
                0
            ) AS investment_sale_amount_usd,

            COALESCE(
                SUM(cp.loan_disbursed_amount),
                0
            ) AS loan_disbursed_amount,

            COALESCE(
                SUM(cp.loan_disbursed_amount_usd),
                0
            ) AS loan_disbursed_amount_usd,

            COALESCE(
                SUM(cp.loan_repayment_amount),
                0
            ) AS loan_repayment_amount,

            COALESCE(
                SUM(cp.loan_repayment_amount_usd),
                0
            ) AS loan_repayment_amount_usd,

            COALESCE(
                SUM(cp.loan_principal_repaid),
                0
            ) AS loan_principal_repaid,

            COALESCE(
                SUM(cp.loan_principal_repaid_usd),
                0
            ) AS loan_principal_repaid_usd,

            COALESCE(
                SUM(cp.loan_interest_repaid),
                0
            ) AS loan_interest_repaid,

            COALESCE(
                SUM(cp.loan_interest_repaid_usd),
                0
            ) AS loan_interest_repaid_usd,

            COALESCE(
                SUM(cp.loan_interest_accrued),
                0
            ) AS loan_interest_accrued,

            COALESCE(
                SUM(cp.loan_interest_accrued_usd),
                0
            ) AS loan_interest_accrued_usd,

            COALESCE(
                MAX(cp.opening_loan_balance)
                FILTER (
                    WHERE cp.first_period_row = 1
                ),
                0
            ) AS opening_loan_balance,

            COALESCE(
                MAX(cp.opening_loan_balance_usd)
                FILTER (
                    WHERE cp.first_period_row = 1
                ),
                0
            ) AS opening_loan_balance_usd,

            COALESCE(
                MAX(cp.closing_loan_balance)
                FILTER (
                    WHERE cp.last_period_row = 1
                ),
                0
            ) AS closing_loan_balance,

            COALESCE(
                MAX(cp.closing_loan_balance_usd)
                FILTER (
                    WHERE cp.last_period_row = 1
                ),
                0
            ) AS closing_loan_balance_usd

        FROM currency_periods AS cp

        GROUP BY
            cp.currency_code
    )

    SELECT
        COALESCE(
            jsonb_agg(
                jsonb_build_object(

                    'currency_code',
                        cs.currency_code,

                    'deposit',
                        jsonb_build_object(

                            'amount',
                                cs.deposit_amount,

                            'amount_usd',
                                cs.deposit_amount_usd
                        ),

                    'withdrawal',
                        jsonb_build_object(

                            'amount',
                                cs.withdrawal_amount,

                            'amount_usd',
                                cs.withdrawal_amount_usd
                        ),

                    'spending',
                        jsonb_build_object(

                            'amount',
                                cs.spending_amount,

                            'amount_usd',
                                cs.spending_amount_usd
                        ),

                    'savings',
                        jsonb_build_object(

                            'opening',
                                cs.opening_savings,

                            'opening_usd',
                                cs.opening_savings_usd,

                            'inflow',
                                cs.savings_inflow,

                            'inflow_usd',
                                cs.savings_inflow_usd,

                            'outflow',
                                cs.savings_outflow,

                            'outflow_usd',
                                cs.savings_outflow_usd,

                            'saved',
                                cs.saving_amount,

                            'saved_usd',
                                cs.saving_amount_usd,

                            'closing',
                                cs.closing_savings,

                            'closing_usd',
                                cs.closing_savings_usd
                        ),

                    'investment',
                        jsonb_build_object(

                            'purchased',
                                cs.investment_purchase_amount,

                            'purchased_usd',
                                cs.investment_purchase_amount_usd,

                            'sold',
                                cs.investment_sale_amount,

                            'sold_usd',
                                cs.investment_sale_amount_usd
                        ),

                    'loan',
                        jsonb_build_object(

                            'opening_balance',
                                cs.opening_loan_balance,

                            'opening_balance_usd',
                                cs.opening_loan_balance_usd,

                            'disbursed',
                                cs.loan_disbursed_amount,

                            'disbursed_usd',
                                cs.loan_disbursed_amount_usd,

                            'repaid',
                                cs.loan_repayment_amount,

                            'repaid_usd',
                                cs.loan_repayment_amount_usd,

                            'principal_repaid',
                                cs.loan_principal_repaid,

                            'principal_repaid_usd',
                                cs.loan_principal_repaid_usd,

                            'interest_repaid',
                                cs.loan_interest_repaid,

                            'interest_repaid_usd',
                                cs.loan_interest_repaid_usd,

                            'interest_accrued',
                                cs.loan_interest_accrued,

                            'interest_accrued_usd',
                                cs.loan_interest_accrued_usd,

                            'closing_balance',
                                cs.closing_loan_balance,

                            'closing_balance_usd',
                                cs.closing_loan_balance_usd
                        )
                )
                ORDER BY
                    cs.currency_code
            ),
            '[]'::jsonb
        )

    INTO
        v_currencies

    FROM currency_summary AS cs;


    -- ==========================================================
    -- GOLD FY-TO-DATE
    --
    -- Gold also comes entirely from financial_pot.
    --
    -- Opening position = first period.
    -- Activity = sum of period activity.
    -- Closing position = latest period.
    -- ==========================================================

    WITH gold_periods AS (

        SELECT
            fp.*,

            ROW_NUMBER() OVER (
                ORDER BY fp.period ASC
            ) AS first_period_row,

            ROW_NUMBER() OVER (
                ORDER BY fp.period DESC
            ) AS last_period_row

        FROM public.financial_pot AS fp

        WHERE fp.user_id =
              v_user_id

          AND fp.country_code =
              v_country_code

          AND fp.currency_code =
              'gold'

          AND fp.fiscal_year =
              v_fiscal_year

          AND fp.period <=
              v_period
    ),

    gold_summary AS (

        SELECT

            COALESCE(
                MAX(gp.opening_gold_quantity)
                FILTER (
                    WHERE gp.first_period_row = 1
                ),
                0
            ) AS opening_quantity,

            COALESCE(
                SUM(gp.gold_purchased),
                0
            ) AS purchased,

            COALESCE(
                SUM(gp.gold_sold),
                0
            ) AS sold,

            COALESCE(
                SUM(gp.gold_transferred_in),
                0
            ) AS transferred_in,

            COALESCE(
                SUM(gp.gold_transferred_out),
                0
            ) AS transferred_out,

            COALESCE(
                MAX(gp.closing_gold_quantity)
                FILTER (
                    WHERE gp.last_period_row = 1
                ),
                0
            ) AS closing_quantity

        FROM gold_periods AS gp
    )

    SELECT
        jsonb_build_object(

            'opening_quantity',
                gs.opening_quantity,

            'purchased',
                gs.purchased,

            'sold',
                gs.sold,

            'transferred_in',
                gs.transferred_in,

            'transferred_out',
                gs.transferred_out,

            'closing_quantity',
                gs.closing_quantity
        )

    INTO
        v_gold

    FROM gold_summary AS gs;


    -- ==========================================================
    -- RESPONSE
    -- ==========================================================

    RETURN jsonb_build_object(

        'fiscal_year',
            v_fiscal_year,

        'current_period',
            v_period,

        'money_in',
            v_money_in,

        'distribution',
            v_distribution,

        'money_by_currency',
            v_money_by_currency,

        'behavior',
            v_behavior,

        'behavior_scores',
            jsonb_build_object(

                'shopper_percentage',
                    v_shopper_score_percentage,

                'saver_percentage',
                    v_saver_score_percentage,

                'investor_percentage',
                    v_investor_score_percentage,

                'borrower_percentage',
                    v_borrower_score_percentage
            ),

        'current_period_behavior',
            v_current_period_behavior,

        'current_period_behavior_scores',
            jsonb_build_object(

                'shopper_percentage',
                    v_current_period_shopper_score_percentage,

                'saver_percentage',
                    v_current_period_saver_score_percentage,

                'investor_percentage',
                    v_current_period_investor_score_percentage,

                'borrower_percentage',
                    v_current_period_borrower_score_percentage
            ),

        'currencies',
            v_currencies,

        'gold',
            v_gold
    );

END;
$$;
ALTER FUNCTION "public"."get_my_financial_summary"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."get_my_last_wallet_transactions"("p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_currency_code" "text" DEFAULT NULL::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user_id text;
begin
    /*
     * Authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Fetch the authenticated application user and
     * validate status and required role.
     */
    select u.id
    into v_user_id
    from public.users u
    join public.user_role r
      on r.id = u.role_id
    where u.id = auth.uid()::text
      and u.status =
          'active'::public."UserStatus"
      and lower(r.name::text) in (
          'admin',
          'agent',
          'vendor',
          'finance',
          'treasury',
          'customer',
          'merchant',
          'accounts'
      )
    limit 1;

    if not found then
        raise exception using
            errcode = '42501',
            message = 'USER_NOT_AUTHORIZED';
    end if;

    /*
     * Run the existing internal report using the
     * authenticated application user ID.
     */
    return public.get_last_wallet_transactions(
        v_user_id,
        p_start_date,
        p_end_date,
        p_currency_code,
        p_page,
        p_page_size
    );
end;
$$;
ALTER FUNCTION "public"."get_my_last_wallet_transactions"("p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_currency_code" "text", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."get_my_multi_wallet_balances"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_user_id text;
    v_missing_currency text;

    v_result jsonb;

BEGIN
    /*
     * ==========================================================
     * 1. AUTHENTICATION
     * ==========================================================
     */
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;

    /*
     * ==========================================================
     * 2. VALIDATE USER AND ROLE
     * ==========================================================
     */
    SELECT u.id
    INTO v_user_id
    FROM public.users u
    JOIN public.user_role r
        ON r.id = u.role_id
    WHERE u.id = auth.uid()::text
      AND u.status = 'active'::public."UserStatus"
      AND lower(r.name::text) IN (
          'agent',
          'merchant',
          'vendor'
      )
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'MULTI_WALLET_BALANCES_NOT_AUTHORIZED';
    END IF;

    /*
     * ==========================================================
     * 3. VALIDATE EXCHANGE RATES
     *
     * Same rules as get_wallet_balances:
     *
     * USD:
     *   USD value = balance
     *
     * GOLD:
     *   USD value = balance * rate_to_usd
     *
     * Other fiat:
     *   USD value = balance / rate_to_usd
     * ==========================================================
     */
    SELECT lower(btrim(w.currency_code))
    INTO v_missing_currency
    FROM public.wallet w
    LEFT JOIN public.current_rates r
        ON lower(btrim(r.code)) =
           lower(btrim(w.currency_code))
    WHERE w.user_id = v_user_id
      AND lower(btrim(w.owner_type::text)) IN (
          'agent',
          'customer',
          'merchant'
      )
      AND lower(btrim(w.currency_code)) <> 'usd'
      AND (
          r.code IS NULL
          OR r.rate_to_usd IS NULL
          OR r.rate_to_usd <= 0
      )
    LIMIT 1;

    IF FOUND THEN
        RAISE EXCEPTION
            'MISSING_RATE_FOR_CURRENCY_%',
            upper(v_missing_currency);
    END IF;

    /*
     * ==========================================================
     * 4. CALCULATE WALLET BALANCES
     * ==========================================================
     */
    WITH wallet_values AS (
        SELECT
            lower(btrim(w.owner_type::text))
                AS owner_type,

            lower(btrim(w.currency_code))
                AS currency_code,

            NULLIF(
                lower(btrim(w.blockchain_code)),
                ''
            ) AS blockchain_code,

            coalesce(w.balance, 0)::numeric
                AS balance,

            CASE
                WHEN lower(btrim(w.currency_code)) = 'usd'
                THEN
                    coalesce(w.balance, 0)::numeric

                WHEN lower(btrim(w.currency_code)) = 'gold'
                THEN
                    coalesce(w.balance, 0)::numeric *
                    r.rate_to_usd::numeric

                ELSE
                    coalesce(w.balance, 0)::numeric /
                    r.rate_to_usd::numeric
            END AS usd_value

        FROM public.wallet w

        LEFT JOIN public.current_rates r
            ON lower(btrim(r.code)) =
               lower(btrim(w.currency_code))

        WHERE w.user_id = v_user_id
          AND lower(btrim(w.owner_type::text)) IN (
              'agent',
              'customer',
              'merchant'
          )
    ),

    /*
     * ==========================================================
     * 5. CONSOLIDATED CURRENCY BALANCES
     * ==========================================================
     */
    currency_totals AS (
        SELECT
            owner_type,
            currency_code,
            sum(balance) AS balance,
            sum(usd_value) AS usd_value
        FROM wallet_values
        GROUP BY
            owner_type,
            currency_code
    ),

    /*
     * ==========================================================
     * 6. BLOCKCHAIN-SPECIFIC BALANCES
     * ==========================================================
     */
    blockchain_totals AS (
        SELECT
            owner_type,
            blockchain_code,
            currency_code,
            sum(balance) AS balance,
            sum(usd_value) AS usd_value
        FROM wallet_values
        WHERE blockchain_code IS NOT NULL
        GROUP BY
            owner_type,
            blockchain_code,
            currency_code
    ),

    /*
     * ==========================================================
     * 7. BUILD SUMMARY FOR EACH WALLET OWNER
     * ==========================================================
     */
    wallet_summaries AS (
        SELECT
            owners.owner_type,

            jsonb_build_object(
                'balances',
                (
                    SELECT coalesce(
                        jsonb_object_agg(
                            c.currency_code,
                            jsonb_build_object(
                                'balance',
                                c.balance::text,
                                'usd_value',
                                c.usd_value::text
                            )
                            ORDER BY c.currency_code
                        ),
                        '{}'::jsonb
                    )
                    FROM currency_totals c
                    WHERE c.owner_type = owners.owner_type
                ),

                'blockchain_balances',
                (
                    SELECT coalesce(
                        jsonb_agg(
                            jsonb_build_object(
                                'blockchain_code',
                                b.blockchain_code,
                                'currency_code',
                                b.currency_code,
                                'balance',
                                b.balance::text,
                                'usd_value',
                                b.usd_value::text
                            )
                            ORDER BY
                                b.blockchain_code,
                                b.currency_code
                        ),
                        '[]'::jsonb
                    )
                    FROM blockchain_totals b
                    WHERE b.owner_type = owners.owner_type
                ),

                'total_usd_value',
                (
                    SELECT coalesce(
                        sum(c.usd_value),
                        0
                    )::text
                    FROM currency_totals c
                    WHERE c.owner_type = owners.owner_type
                )
            ) AS summary

        FROM (
            VALUES
                ('agent'),
                ('customer'),
                ('merchant')
        ) AS owners(owner_type)
    )

    /*
     * ==========================================================
     * 8. BUILD FINAL MULTI-WALLET RESPONSE
     *
     * No MAX(jsonb).
     * Each owner maps directly to one JSON object.
     * ==========================================================
     */
    SELECT jsonb_object_agg(
        CASE ws.owner_type
            WHEN 'agent'
                THEN 'agentWallet'
            WHEN 'customer'
                THEN 'customerWallet'
            WHEN 'merchant'
                THEN 'merchantWallet'
        END,
        ws.summary
    )
    INTO v_result
    FROM wallet_summaries ws;

    /*
     * ==========================================================
     * 9. RETURN RESULT
     * ==========================================================
     */
    RETURN coalesce(
        v_result,
        jsonb_build_object(
            'agentWallet',
            jsonb_build_object(
                'balances', '{}'::jsonb,
                'blockchain_balances', '[]'::jsonb,
                'total_usd_value', '0'
            ),
            'customerWallet',
            jsonb_build_object(
                'balances', '{}'::jsonb,
                'blockchain_balances', '[]'::jsonb,
                'total_usd_value', '0'
            ),
            'merchantWallet',
            jsonb_build_object(
                'balances', '{}'::jsonb,
                'blockchain_balances', '[]'::jsonb,
                'total_usd_value', '0'
            )
        )
    );

END;
$$;
ALTER FUNCTION "public"."get_my_multi_wallet_balances"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."get_my_wallet_balance_snapshot"("p_currency_code" "text", "p_wallet_owner" "public"."WalletOwnerType", "p_blockchain_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user public.users%rowtype;
    v_currency_code text;
    v_blockchain_code text;
begin
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    v_currency_code :=
        lower(btrim(p_currency_code));

    if v_currency_code is null
       or v_currency_code = ''
    then
        raise exception
            'CURRENCY_IS_REQUIRED';
    end if;

    if p_wallet_owner is null then
        raise exception
            'WALLET_OWNER_IS_REQUIRED';
    end if;

    v_blockchain_code :=
        nullif(
            lower(btrim(p_blockchain_code)),
            ''
        );

    if v_currency_code = 'gold'
       and v_blockchain_code is null
    then
        raise exception
            'BLOCKCHAIN_CODE_IS_REQUIRED';
    end if;

    /*
     * Authentication, active-user validation
     * and required-role validation.
     */
    select u.*
    into v_user
    from public.users u
    join public.user_role r
      on r.id = u.role_id
    where u.id = auth.uid()::text
      and u.status =
          'active'::public."UserStatus"
      and lower(r.name::text) in (
          'treasury',
          'customer',
          'agent',
          'merchant',
          'vendor'
      )
    limit 1;

    if not found then
        raise exception using
            errcode = '42501',
            message =
                'WALLET_BALANCE_SNAPSHOT_NOT_AUTHORIZED';
    end if;

    return public.get_wallet_balance_snapshot(
        p_user_id =>
            v_user.id,

        p_currency_code =>
            v_currency_code,

        p_country_code =>
            v_user.country_code,

        p_wallet_owner =>
            p_wallet_owner,

        p_blockchain_code =>
            v_blockchain_code
    );
end;
$$;
