CREATE OR REPLACE FUNCTION "public"."get_my_wallet_balances"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_user_id text;
BEGIN
    /*
     * Authentication.
     */
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'UNAUTHORIZED';
    END IF;

    /*
     * Required-role validation.
     */
    SELECT u.id
    INTO v_user_id
    FROM public.users u
    JOIN public.user_role r
        ON r.id = u.role_id
    WHERE u.id = auth.uid()::text
      AND u.status = 'active'::public."UserStatus"
      AND lower(r.name::text) IN (
          'treasury',
          'customer'
      )
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'WALLET_BALANCES_NOT_AUTHORIZED';
    END IF;

    /*
     * Shared wallet balance function.
     */
    RETURN public.get_wallet_balances(
        v_user_id
    );
END;
$$;
