CREATE OR REPLACE FUNCTION "public"."get_wallet_balance_snapshot"("p_user_id" "text", "p_currency_code" "text", "p_country_code" "text", "p_wallet_owner" "public"."WalletOwnerType", "p_blockchain_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
    v_fiscal_year integer;
    v_result jsonb;
    v_currency_code text;
    v_blockchain_code text;
begin
    v_currency_code :=
        lower(btrim(p_currency_code));

    if v_currency_code is null
       or v_currency_code = ''
    then
        raise exception
            'CURRENCY_IS_REQUIRED';
    end if;

    if p_wallet_owner is null then
        raise exception
            'WALLET_OWNER_IS_REQUIRED';
    end if;

    v_blockchain_code :=
        nullif(
            lower(btrim(p_blockchain_code)),
            ''
        );

    if v_currency_code = 'gold'
       and v_blockchain_code is null
    then
        raise exception
            'BLOCKCHAIN_CODE_IS_REQUIRED';
    end if;

    /*
     * Fetch the current fiscal year.
     */
    select fp.fiscal_year
    into v_fiscal_year
    from public.fetch_fiscal_period(
        p_country_code
    ) fp
    limit 1;

    with snapshots as (
        select
            s.period,
            s.opening_balance,
            s.debit,
            s.credit,
            s.closing_balance

        from public.wallet_balance_snapshot s

        where s.user_id = p_user_id
          and s.wallet_owner = p_wallet_owner
          and lower(btrim(s.currency_code)) =
              v_currency_code
          and s.fiscal_year = v_fiscal_year

          /*
           * GOLD must match the selected blockchain.
           * Fiat retains the existing behavior.
           */
          and (
              v_currency_code <> 'gold'
              or lower(btrim(s.blockchain_code)) =
                  v_blockchain_code
          )
    ),

    period_values as (
        select
            generated_period.period,

            case
                when current_snapshot.period is not null
                then current_snapshot.opening_balance

                else coalesce(
                    previous_snapshot.closing_balance,
                    0
                )
            end as opening_balance,

            case
                when current_snapshot.period is not null
                then current_snapshot.debit
                else 0
            end as debit,

            case
                when current_snapshot.period is not null
                then current_snapshot.credit
                else 0
            end as credit,

            case
                when current_snapshot.period is not null
                then abs(
                    current_snapshot.closing_balance
                )

                else coalesce(
                    previous_snapshot.closing_balance,
                    0
                )
            end as closing_balance

        from generate_series(
            1,
            12
        ) as generated_period(period)

        left join snapshots current_snapshot
            on current_snapshot.period =
               generated_period.period

        left join lateral (
            select previous.closing_balance
            from snapshots previous
            where previous.period <
                  generated_period.period
            order by previous.period desc
            limit 1
        ) previous_snapshot on true
    )

    select jsonb_build_object(
        'currency_code',
        v_currency_code,

        'blockchain_code',
        v_blockchain_code,

        'fiscalYear',
        v_fiscal_year,

        'periods',
        coalesce(
            jsonb_agg(
                jsonb_build_object(
                    'period',
                    period,

                    'opening_balance',
                    opening_balance::text,

                    'debit',
                    debit::text,

                    'credit',
                    credit::text,

                    'closing_balance',
                    closing_balance::text
                )
                order by period
            ),
            '[]'::jsonb
        )
    )
    into v_result
    from period_values;

    return v_result;
end;
$$;
ALTER FUNCTION "public"."get_wallet_balance_snapshot"("p_user_id" "text", "p_currency_code" "text", "p_country_code" "text", "p_wallet_owner" "public"."WalletOwnerType", "p_blockchain_code" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."get_wallet_balances"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
    v_user_id text;
begin
    /*
     * Authentication.
     */
    if auth.uid() is null then
        raise exception using
            errcode = '42501',
            message = 'UNAUTHORIZED';
    end if;

    /*
     * Required-role validation:
     * - treasury
     * - customer
     */
    select u.id
    into v_user_id
    from public.users u
    join public.user_role r
      on r.id = u.role_id
    where u.id = auth.uid()::text
      and u.status =
          'active'::public."UserStatus"
      and lower(r.name::text) in (
          'treasury',
          'customer'
      )
    limit 1;

    if not found then
        raise exception using
            errcode = '42501',
            message = 'WALLET_BALANCES_NOT_AUTHORIZED';
    end if;

    return public.get_wallet_balances(
        v_user_id
    );
end;
$$;
ALTER FUNCTION "public"."get_wallet_balances"() OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."get_wallet_balances"("p_user_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
DECLARE
    v_missing_currency text;
    v_result jsonb;
BEGIN
    /*
     * Validate exchange rates.
     *
     * USD:
     *   USD value = balance
     *
     * GOLD:
     *   USD value = balance * rate_to_usd
     *
     * Other fiat:
     *   USD value = balance / rate_to_usd
     */

    SELECT lower(btrim(w.currency_code))
    INTO v_missing_currency
    FROM public.wallet w
    LEFT JOIN public.current_rates r
        ON lower(btrim(r.code)) =
           lower(btrim(w.currency_code))
    WHERE w.user_id = p_user_id
      AND lower(btrim(w.currency_code)) <> 'usd'
      AND (
          r.code IS NULL
          OR r.rate_to_usd IS NULL
          OR r.rate_to_usd <= 0
      )
    LIMIT 1;

    IF FOUND THEN
        RAISE EXCEPTION
            'MISSING_RATE_FOR_CURRENCY_%',
            upper(v_missing_currency);
    END IF;

    WITH wallet_values AS (
        SELECT
            w.id AS wallet_id,

            lower(btrim(w.currency_code))
                AS currency_code,

            NULLIF(
                lower(btrim(w.blockchain_code)),
                ''
            ) AS blockchain_code,

            coalesce(w.balance, 0)::numeric
                AS balance,

            CASE
                WHEN lower(btrim(w.currency_code)) = 'usd'
                THEN coalesce(w.balance, 0)::numeric

                WHEN lower(btrim(w.currency_code)) = 'gold'
                THEN
                    coalesce(w.balance, 0)::numeric *
                    r.rate_to_usd::numeric

                ELSE
                    coalesce(w.balance, 0)::numeric /
                    r.rate_to_usd::numeric
            END AS usd_value

        FROM public.wallet w

        LEFT JOIN public.current_rates r
            ON lower(btrim(r.code)) =
               lower(btrim(w.currency_code))

        WHERE w.user_id = p_user_id
    ),

    /*
     * Consolidated balances per currency.
     */
    currency_totals AS (
        SELECT
            currency_code,
            sum(balance) AS balance,
            sum(usd_value) AS usd_value
        FROM wallet_values
        GROUP BY currency_code
    ),

    /*
     * Blockchain-specific balances.
     */
    blockchain_totals AS (
        SELECT
            blockchain_code,
            currency_code,
            sum(balance) AS balance,
            sum(usd_value) AS usd_value
        FROM wallet_values
        WHERE blockchain_code IS NOT NULL
        GROUP BY
            blockchain_code,
            currency_code
    )

    SELECT jsonb_build_object(
        'balances',
        (
            SELECT coalesce(
                jsonb_object_agg(
                    c.currency_code,
                    jsonb_build_object(
                        'balance', c.balance::text,
                        'usd_value', c.usd_value::text
                    )
                    ORDER BY c.currency_code
                ),
                '{}'::jsonb
            )
            FROM currency_totals c
        ),

        'blockchain_balances',
        (
            SELECT coalesce(
                jsonb_agg(
                    jsonb_build_object(
                        'blockchain_code', b.blockchain_code,
                        'currency_code', b.currency_code,
                        'balance', b.balance::text,
                        'usd_value', b.usd_value::text
                    )
                    ORDER BY
                        b.blockchain_code,
                        b.currency_code
                ),
                '[]'::jsonb
            )
            FROM blockchain_totals b
        )
    )
    INTO v_result;

    RETURN v_result;
END;
$$;
ALTER FUNCTION "public"."get_wallet_balances"("p_user_id" "text") OWNER TO "postgres";
CREATE OR REPLACE FUNCTION "public"."get_wallet_period_entries"("p_user_id" "text", "p_currency_code" "text", "p_wallet_owner" "public"."WalletOwnerType", "p_fiscal_year" integer, "p_period" integer, "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50, "p_blockchain_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
    v_wallet public.wallet%rowtype;

    v_currency_code text;
    v_blockchain_code text;

    v_opening_balance numeric := 0;
    v_closing_balance numeric := 0;

    v_total_entries integer := 0;
    v_total_debit numeric := 0;
    v_total_credit numeric := 0;

    v_calculated_closing numeric := 0;
    v_difference numeric := 0;
    v_balanced boolean := false;

    v_skip integer;
    v_total_pages integer;

    v_page_opening numeric := 0;
    v_page_closing numeric := 0;

    v_entries jsonb := '[]'::jsonb;
begin
    /*
     * Normalize parameters.
     */
    v_currency_code :=
        nullif(lower(btrim(p_currency_code)), '');

    v_blockchain_code :=
        nullif(lower(btrim(p_blockchain_code)), '');

    if p_user_id is null or btrim(p_user_id) = '' then
        raise exception 'USER_ID_IS_REQUIRED';
    end if;

    if v_currency_code is null then
        raise exception 'CURRENCY_IS_REQUIRED';
    end if;

    if p_wallet_owner is null then
        raise exception 'WALLET_OWNER_IS_REQUIRED';
    end if;

    if v_currency_code = 'gold'
       and v_blockchain_code is null
    then
        raise exception 'BLOCKCHAIN_CODE_IS_REQUIRED';
    end if;

    if p_fiscal_year is null then
        raise exception 'FISCAL_YEAR_IS_REQUIRED';
    end if;

    if p_period is null then
        raise exception 'PERIOD_IS_REQUIRED';
    end if;

    if p_period < 1 or p_period > 12 then
        raise exception 'INVALID_PERIOD';
    end if;

    if p_page is null or p_page < 1 then
        raise exception 'INVALID_PAGE';
    end if;

    if p_page_size is null
       or p_page_size < 1
       or p_page_size > 100
    then
        raise exception 'INVALID_PAGE_SIZE';
    end if;

    v_skip := (p_page - 1) * p_page_size;

    /*
     * Resolve the exact wallet.
     */
    v_wallet := public.fetch_wallet(
        p_user_id,
        v_currency_code,
        p_wallet_owner,
        v_blockchain_code
    );

    /*
     * Fetch opening and closing balances
     * for the same blockchain.
     */
    select
        snapshot.opening_balance,
        snapshot.closing_balance
    into
        v_opening_balance,
        v_closing_balance
    from public.fetch_opening_wallet_snapshot(
        p_user_id,
        v_currency_code,
        v_wallet.owner_type,
        p_fiscal_year,
        p_period,
        v_blockchain_code
    ) snapshot;

    v_opening_balance :=
        coalesce(v_opening_balance, 0);

    v_closing_balance :=
        coalesce(v_closing_balance, 0);

    /*
     * Period totals.
     */
    select
        count(*)::integer,
        coalesce(sum(coalesce(e.debit, 0)), 0),
        coalesce(sum(coalesce(e.credit, 0)), 0)
    into
        v_total_entries,
        v_total_debit,
        v_total_credit
    from public.wallet_entry e
    where e.wallet_id = v_wallet.id
      and lower(btrim(e.currency_code)) = v_currency_code
      and e.fiscal_year = p_fiscal_year
      and e.period = p_period
      and (
          v_currency_code <> 'gold'
          or lower(btrim(e.blockchain_code)) =
              v_blockchain_code
      );

    /*
     * Balance immediately before the requested page.
     */
    select
        v_opening_balance +
        coalesce(
            sum(previous.credit - previous.debit),
            0
        )
    into v_page_opening
    from (
        select
            coalesce(e.debit, 0) as debit,
            coalesce(e.credit, 0) as credit
        from public.wallet_entry e
        where e.wallet_id = v_wallet.id
          and lower(btrim(e.currency_code)) = v_currency_code
          and e.fiscal_year = p_fiscal_year
          and e.period = p_period
          and (
              v_currency_code <> 'gold'
              or lower(btrim(e.blockchain_code)) =
                  v_blockchain_code
          )
        order by
            e.created_at asc,
            e.id asc
        limit v_skip
    ) previous;

    /*
     * Ordered entries with cumulative movements.
     */
    with ordered_entries as (
        select
            e.id,
            e.document_number,
            e.transaction_type,
            coalesce(e.debit, 0) as debit,
            coalesce(e.credit, 0) as credit,
            e.created_at,

            row_number() over (
                order by
                    e.created_at asc,
                    e.id asc
            ) as entry_number,

            sum(
                coalesce(e.credit, 0) -
                coalesce(e.debit, 0)
            ) over (
                order by
                    e.created_at asc,
                    e.id asc
                rows between
                    unbounded preceding
                    and current row
            ) as running_movement

        from public.wallet_entry e
        where e.wallet_id = v_wallet.id
          and lower(btrim(e.currency_code)) = v_currency_code
          and e.fiscal_year = p_fiscal_year
          and e.period = p_period
          and (
              v_currency_code <> 'gold'
              or lower(btrim(e.blockchain_code)) =
                  v_blockchain_code
          )
    ),

    paged_entries as (
        select *
        from ordered_entries
        where entry_number > v_skip
          and entry_number <= v_skip + p_page_size
    )

    select
        coalesce(
            jsonb_agg(
                jsonb_build_object(
                    'id',
                    entry.id::text,

                    'document_number',
                    entry.document_number,

                    'transaction_type',
                    entry.transaction_type::text,

                    'debit',
                    entry.debit::text,

                    'credit',
                    entry.credit::text,

                    'running_balance',
                    (
                        v_opening_balance +
                        entry.running_movement
                    )::text,

                    'created_at',
                    entry.created_at
                )
                order by entry.entry_number
            ),
            '[]'::jsonb
        ),

        coalesce(
            (
                array_agg(
                    v_opening_balance +
                    entry.running_movement
                    order by entry.entry_number desc
                )
            )[1],
            v_page_opening
        )

    into
        v_entries,
        v_page_closing

    from paged_entries entry;

    /*
     * Reconciliation.
     */
    v_calculated_closing :=
        v_opening_balance +
        v_total_credit -
        v_total_debit;

    v_difference :=
        v_calculated_closing -
        v_closing_balance;

    v_balanced :=
        abs(v_difference) <= 0.000001;

    /*
     * Pagination.
     */
    v_total_pages :=
        case
            when v_total_entries = 0 then 1
            else ceil(
                v_total_entries::numeric /
                p_page_size::numeric
            )::integer
        end;

    /*
     * Return the existing response structure
     * with blockchain_code added.
     */
    return jsonb_build_object(
        'currency_code',
        v_currency_code,

        'blockchain_code',
        case
            when v_currency_code = 'gold'
            then v_blockchain_code
            else null
        end,

        'fiscal_year',
        p_fiscal_year,

        'gl_account_code',
        '',

        'description',
        '',

        'period',
        p_period,

        'difference',
        v_difference::text,

        'balanced',
        v_balanced,

        'opening_balance',
        v_opening_balance::text,

        'total_debit',
        v_total_debit::text,

        'total_credit',
        v_total_credit::text,

        'calculated_closing_balance',
        v_calculated_closing::text,

        'closing_balance',
        v_closing_balance::text,

        'page_opening_balance',
        v_page_opening::text,

        'page_closing_balance',
        v_page_closing::text,

        'pagination',
        jsonb_build_object(
            'page',
            p_page,

            'page_size',
            p_page_size,

            'total_entries',
            v_total_entries,

            'total_pages',
            v_total_pages,

            'has_previous',
            p_page > 1,

            'has_next',
            p_page < v_total_pages
        ),

        'entries',
        v_entries
    );
end;
$$;
