CREATE OR REPLACE FUNCTION "public"."ngoda_add_check_constraint"("p_table" "text", "p_constraint" "text", "p_check_sql" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF to_regclass('public.' || p_table) IS NULL THEN
    RETURN;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint c
    JOIN pg_class t ON t.oid = c.conrelid
    JOIN pg_namespace n ON n.oid = t.relnamespace
    WHERE c.conname = p_constraint
      AND t.relname = p_table
      AND n.nspname = 'public'
  ) THEN
    EXECUTE format('ALTER TABLE public.%I ADD CONSTRAINT %I CHECK (%s);', p_table, p_constraint, p_check_sql);
  END IF;
END;
$$;
ALTER FUNCTION "public"."ngoda_add_check_constraint"("p_table" "text", "p_constraint" "text", "p_check_sql" "text") OWNER TO "postgres";
