CREATE TABLE IF NOT EXISTS "public"."wallet_balance_snapshot" (
    "id" "text" DEFAULT ("gen_random_uuid"())::"text" NOT NULL,
    "country_code" "text" NOT NULL,
    "user_id" "text" NOT NULL,
    "currency_code" "text" NOT NULL,
    "wallet_owner" "public"."WalletOwnerType" NOT NULL,
    "fiscal_year" integer NOT NULL,
    "period" integer NOT NULL,
    "opening_balance" numeric(20,6) NOT NULL,
    "debit" numeric(20,6) NOT NULL,
    "credit" numeric(20,6) NOT NULL,
    "closing_balance" numeric(20,6) NOT NULL,
    "created_at" timestamp(3) without time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp(3) without time zone DEFAULT "now"() NOT NULL,
    "blockchain_code" "text",
    CONSTRAINT "wallet_balance_snapshot_amounts_check" CHECK ((("opening_balance" >= (0)::numeric) AND ("debit" >= (0)::numeric) AND ("credit" >= (0)::numeric) AND ("closing_balance" >= (0)::numeric)))
);
ALTER TABLE "public"."wallet_balance_snapshot" OWNER TO "postgres";
CREATE TABLE IF NOT EXISTS "public"."wallet_entry" (
    "id" bigint NOT NULL,
    "transaction_id" bigint,
    "country_code" "text" NOT NULL,
    "period" integer NOT NULL,
    "fiscal_year" integer NOT NULL,
    "document_number" "text" NOT NULL,
    "reference" "text",
    "transaction_type" "public"."TransactionType" NOT NULL,
    "wallet_id" "text" NOT NULL,
    "debit" numeric(20,6),
    "credit" numeric(20,6),
    "currency_code" "text" NOT NULL,
    "created_at" timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "created_by" "text" NOT NULL,
    "blockchain_code" "text",
    CONSTRAINT "wallet_entry_debit_credit_check" CHECK ((((COALESCE("debit", (0)::numeric) > (0)::numeric) AND (COALESCE("credit", (0)::numeric) = (0)::numeric)) OR ((COALESCE("credit", (0)::numeric) > (0)::numeric) AND (COALESCE("debit", (0)::numeric) = (0)::numeric))))
);
